function qt_asset_url($relativePath) {
    $normalizedPath = ltrim(str_replace('\\', '/', (string)$relativePath), '/');
    $scriptDir = str_replace('\\', '/', dirname((string)($_SERVER['SCRIPT_NAME'] ?? '')));
    $scriptDir = rtrim($scriptDir, '/.');
    if ($scriptDir === '') {
        return $normalizedPath;
    }
    return $scriptDir . '/' . $normalizedPath;
}
function qt_resolve_profile_pic($profilePic, $fallback = 'images/default-profile.png') {
    $candidate = trim((string)($profilePic ?? ''));
    if ($candidate === '') {
        return $fallback;
    }

    $normalized = str_replace('\\', '/', $candidate);
    $profilesPrefix = 'uploads/profiles/';
    $prefixPos = stripos($normalized, $profilesPrefix);
    if ($prefixPos === false) {
        return $candidate;
    }

    $relativePath = ltrim(substr($normalized, $prefixPos), '/');
    $absolutePath = __DIR__ . '/' . $relativePath;
    return is_file($absolutePath) ? $candidate : $fallback;
}
$token = $_GET['token'] ?? '';
if (!$token) {
    die(__('missing_token'));
}
$defaultProfilePicAsset = qt_asset_url('images/default-profile.png');
$defaultAiProfilePicAsset = qt_asset_url('images/default-ai.png');
$dingAudioAsset = qt_asset_url('audio/ding.mp3');
$ringbackAudioAsset = qt_asset_url('audio/ringback.mp3');
$ringtoneAudioAsset = qt_asset_url('audio/ringtone.mp3');
// Validate session and get user info
$stmt = $pdo->prepare("
    SELECT
        users.id,
        users.username,
        users.email,
        COALESCE(NULLIF(users.display_name, ''), users.username) AS display_name,
        COALESCE(users.bio, '') AS bio,
        users.created_at,
        users.profile_pic,
        COALESCE(users.tutorial_completed, 0) AS tutorial_completed,
        COALESCE(users.tutorial_skipped, 0) AS tutorial_skipped
    FROM sessions
    JOIN users ON sessions.user_id = users.id
    WHERE sessions.token = ?
");
$stmt->execute([$token]);
$user = $stmt->fetch();
if (!$user) {
    die(__('invalid_session'));
}
$resolvedCurrentUserProfilePic = qt_resolve_profile_pic($user['profile_pic'] ?? null);
$user_id = $user['id'];
$user_email = $user['email'] ?? '';
$tutorial_completed = (int)($user['tutorial_completed'] ?? 0);
$tutorial_skipped = (int)($user['tutorial_skipped'] ?? 0);
$initialSettingsStorageKey = 'quilltalk.appSettings.v2.user.' . (($user_id ?? '') !== '' ? (string)$user_id : (string)($user['username'] ?? 'guest'));
$tutorialCssVersion = is_file(__DIR__ . '/tutorial_system.css') ? (string)filemtime(__DIR__ . '/tutorial_system.css') : '1';
$tutorialJsVersion = is_file(__DIR__ . '/tutorial_system.js') ? (string)filemtime(__DIR__ . '/tutorial_system.js') : '1';
$scrollsMaxUploadBytes = qt_scrolls_max_upload_bytes(125829120);
$scrollsMaxUploadLabel = qt_scrolls_format_bytes($scrollsMaxUploadBytes);
$scrollComposerIntroCopy = "Upload a short vertical video";
if ($scrollsMaxUploadBytes > 0) {
    $scrollComposerIntroCopy .= ' up to ' . $scrollsMaxUploadLabel;
}
$scrollComposerIntroCopy .= " to share it across everyone's Scrolls feed.";
$scrollComposerIdleStatus = $scrollsMaxUploadBytes > 0
    ? 'Pick a video up to ' . $scrollsMaxUploadLabel . ', then post it to Scrolls.'
    : 'Pick a video, then post it to Scrolls.';

$_SESSION['user_id'] = (int)$user_id;
$_SESSION['username'] = (string)($user['username'] ?? '');
$_SESSION['display_name'] = (string)($user['display_name'] ?? $user['username'] ?? '');
$_SESSION['bio'] = (string)($user['bio'] ?? '');
