    <!-- Firebase App (core) -->
    <script>
        (() => {
            let debugEnabled = false;
            try {
                const params = new URLSearchParams(window.location.search || '');
                debugEnabled = params.get('debug') === '1'
                    || window.localStorage.getItem('quilltalkDebug') === '1';
            } catch (error) {}

            if (!debugEnabled && window.console) {
                ['log', 'debug', 'info'].forEach(method => {
                    if (typeof window.console[method] === 'function') {
                        window.console[method] = () => {};
                    }
                });
            }
        })();

        (() => {
            const root = document.documentElement;
            const storageKey = <?= json_encode($initialSettingsStorageKey) ?>;
            const legacyKey = 'quilltalk.appSettings.v1';
            const defaultAccent = '#2d58f5';

            const normalizeHexColor = (value) => {
                const color = String(value || '').trim();
                return /^#[0-9a-fA-F]{6}$/.test(color) ? color.toLowerCase() : defaultAccent;
            };

            const hexToRgb = (hex) => {
                const normalized = normalizeHexColor(hex);
                const numeric = parseInt(normalized.slice(1), 16);
                return {
                    r: (numeric >> 16) & 255,
                    g: (numeric >> 8) & 255,
                    b: numeric & 255
                };
            };

            const rgbToHex = (r, g, b) => {
                const clamp = (value) => Math.max(0, Math.min(255, Math.round(value)));
                return `#${[clamp(r), clamp(g), clamp(b)].map(value => value.toString(16).padStart(2, '0')).join('')}`;
            };

            const invertHexColor = (hex) => {
                const { r, g, b } = hexToRgb(hex);
                return rgbToHex(255 - r, 255 - g, 255 - b);
            };

            const mixHexColors = (baseHex, targetHex, amount) => {
                const clampedAmount = Math.max(0, Math.min(1, Number(amount) || 0));
                const base = hexToRgb(baseHex);
                const target = hexToRgb(targetHex);
                return rgbToHex(
                    base.r + ((target.r - base.r) * clampedAmount),
                    base.g + ((target.g - base.g) * clampedAmount),
                    base.b + ((target.b - base.b) * clampedAmount)
                );
            };

            const readableTextColor = (hex) => {
                const { r, g, b } = hexToRgb(hex);
                const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
                return luminance > 0.62 ? '#111827' : '#ffffff';
            };
            const normalizeMessagePositionMode = (value) => {
                const normalized = String(value || '').trim().toLowerCase();
                return normalized === 'single' ? 'single' : 'split';
            };
            const normalizeMessagePositionSide = (value, fallback = 'right') => {
                const normalized = String(value || '').trim().toLowerCase();
                if (normalized === 'left' || normalized === 'right') {
                    return normalized;
                }
                return fallback;
            };

            let rawSettings = null;
            try {
                rawSettings = localStorage.getItem(storageKey) || localStorage.getItem(legacyKey);
            } catch (error) {
                rawSettings = null;
            }

            let settings = {};
            if (rawSettings) {
                try {
                    settings = JSON.parse(rawSettings) || {};
                } catch (error) {
                    settings = {};
                }
            }

            const requestedThemeMode = settings && typeof settings.themeMode === 'string'
                ? String(settings.themeMode).toLowerCase()
                : 'system';
            const prefersDarkTheme = typeof window.matchMedia === 'function'
                && window.matchMedia('(prefers-color-scheme: dark)').matches;
            const themeMode = requestedThemeMode === 'system'
                ? (prefersDarkTheme ? 'dark' : 'light')
                : (requestedThemeMode === 'dark' ? 'dark' : 'light');
            const accentColor = normalizeHexColor(settings && settings.accentColor);
            const oppositeAccentColor = invertHexColor(accentColor);
            const accentRgb = hexToRgb(accentColor);
            const messagePositionMode = normalizeMessagePositionMode(settings && settings.messagePositionMode);
            const messageSplitSelfSide = normalizeMessagePositionSide(settings && settings.messageSplitSelfSide, 'right');
            const messageSingleSide = normalizeMessagePositionSide(settings && settings.messageSingleSide, 'left');

            root.setAttribute('data-theme', themeMode);
            root.dataset.messagePositionMode = messagePositionMode;
            root.dataset.messagePositionSide = messagePositionMode === 'single'
                ? messageSingleSide
                : messageSplitSelfSide;
            root.style.colorScheme = themeMode;
            const accentSoft = themeMode === 'dark'
                ? `rgba(${accentRgb.r}, ${accentRgb.g}, ${accentRgb.b}, 0.18)`
                : mixHexColors(accentColor, '#ffffff', 0.88);
            const accentSoftStrong = themeMode === 'dark'
                ? `rgba(${accentRgb.r}, ${accentRgb.g}, ${accentRgb.b}, 0.28)`
                : mixHexColors(accentColor, '#ffffff', 0.8);

            root.style.setProperty('--accent-color', accentColor);
            root.style.setProperty('--accent-hover', mixHexColors(accentColor, '#000000', 0.18));
            root.style.setProperty('--accent-soft', accentSoft);
            root.style.setProperty('--accent-soft-strong', accentSoftStrong);
            root.style.setProperty('--token-highlight-bg', oppositeAccentColor);
            root.style.setProperty('--mention-row-highlight', mixHexColors(oppositeAccentColor, '#ffffff', 0.62));
            root.style.setProperty('--accent-contrast', readableTextColor(accentColor));
            root.style.setProperty('--accent-shadow', `rgba(${accentRgb.r}, ${accentRgb.g}, ${accentRgb.b}, 0.22)`);
            root.style.setProperty('--accent-shadow-strong', `rgba(${accentRgb.r}, ${accentRgb.g}, ${accentRgb.b}, 0.3)`);
            root.style.setProperty('--message-bubble-bg', themeMode === 'dark' ? 'rgba(255, 255, 255, 0.08)' : mixHexColors(accentColor, '#ffffff', 0.84));
            root.style.setProperty('--message-bubble-text', themeMode === 'dark' ? '#e5eefc' : '#111827');
            root.style.setProperty('--message-select-bg-self', mixHexColors(oppositeAccentColor, '#000000', 0.14));
            root.style.setProperty('--message-select-bg-other', mixHexColors(oppositeAccentColor, '#ffffff', 0.12));
            root.style.setProperty('--message-select-text', readableTextColor(oppositeAccentColor));
            root.style.setProperty('--voice-bar-bg', `rgba(${accentRgb.r}, ${accentRgb.g}, ${accentRgb.b}, 0.24)`);
            root.style.setProperty('--voice-bar-bg-self', 'rgba(255, 255, 255, 0.32)');
            root.style.setProperty('--chess-light-square-bg', oppositeAccentColor);
            root.style.setProperty('--chess-dark-square-bg', accentColor);
            root.style.setProperty('--chess-light-square-label', readableTextColor(oppositeAccentColor));
            root.style.setProperty('--chess-dark-square-label', readableTextColor(accentColor));
        })();
    </script>

