            background: linear-gradient(135deg, #2d58f5 0%, rgba(4, 12, 38, 0.84) 46%, rgba(45, 88, 245, 0.22) 100%); color: var(--accent-contrast); padding: 15px;

            display: flex; justify-content: space-between; align-items: center;

            font-weight: 600; font-size: 1.2em;

        }

        .main {
          display: flex;
          flex-direction: column !important;
          height: calc(var(--qt-app-height, 100vh) - 60px);
          min-height: 0;
          overflow: hidden;
        }

        .main-body {
          display: flex;
          flex: 1 1 auto;
          min-height: 0;
          overflow: hidden;
        }

        .desktop-sidebar-tabs-host {
            display: none;
        }

        .sidebar {

            width: 270px; background: #f0f0f0; padding: 0 20px 20px;

            display: flex; flex-direction: column;

            overflow: hidden;

            min-height: 0;

            border-right: 1px solid #ccc;

        }

