        }

        .sidebar-new-dropdown {
            position: relative;
            flex-shrink: 0;
        }

        .sidebar-new-trigger {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 10px 14px;
            border: 1px solid var(--border-subtle);
            border-radius: 16px;
            background: linear-gradient(135deg, var(--surface-bg) 0%, var(--surface-soft) 100%);
            color: var(--text-primary);
            box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
            cursor: pointer;
            font: inherit;
            font-weight: 700;
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, background 0.18s ease;
        }

        .sidebar-new-trigger:hover,
        .sidebar-new-trigger:focus-visible {
            transform: translateY(-1px);
            box-shadow: 0 14px 28px var(--accent-shadow);
            border-color: var(--accent-color);
            outline: none;
        }

        .sidebar-new-trigger-icon {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: var(--accent-soft);
            color: var(--accent-color);
            font-size: 0.8rem;
            flex-shrink: 0;
        }

        .sidebar-new-trigger-label {
            line-height: 1;
        }

        .sidebar-new-trigger .down-arrow {
            margin-left: 0;
            font-size: 11px;
            color: var(--text-secondary);
            transition: transform 0.18s ease, color 0.18s ease;
        }

        .sidebar-new-dropdown:hover .sidebar-new-trigger .down-arrow,
        .sidebar-new-dropdown:focus-within .sidebar-new-trigger .down-arrow {
            transform: rotate(180deg);
            color: var(--accent-color);
        }

        .sidebar-new-menu {
            top: calc(100% + 10px);
            right: 0;
            min-width: 220px;
            padding: 10px;
            border: 1px solid var(--border-subtle);
            border-radius: 18px;
            box-shadow: 0 22px 44px rgba(15, 23, 42, 0.16);
            z-index: 5000;
        }

        .friend-request-dropdown-btn .dropdown-action-icon {
            color: var(--accent-color);
        }

        .mobile-new-dropdown {
            display: none;
        }

        .sidebar-footer-note {
            margin-top: 18px;
            padding: 0 2px 12px;
            color: var(--text-secondary);
            font-size: 0.88rem;
            line-height: 1.5;
            flex-shrink: 0;
        }

        .sidebar-footer-note a {
            color: var(--accent-color);
            text-decoration: none;
            font-weight: 700;
        }

        .sidebar-footer-note a:hover {
            text-decoration: underline;
        }

        .sidebar-contact-tabs {
            position: relative;
            z-index: 9;
            display: flex;
            flex-shrink: 0;
            gap: 0;
            align-self: stretch;
            margin: 0 -20px -20px;
            padding: 0 0 env(safe-area-inset-bottom, 0px);
            background: var(--surface-bg, #ffffff);
            border-top: 1px solid var(--border-subtle);
            box-shadow: none;
        }

        .sidebar-contact-tab {
            flex: 1 1 25%;
            min-width: 0;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            min-height: 68px;
            padding: 14px 16px;
            border: none;
            border-right: 1px solid var(--border-subtle);
            border-radius: 0;
            background: var(--surface-bg, #ffffff);
            color: var(--text-secondary);
            font-size: 0.9rem;
            font-weight: 700;
            cursor: pointer;
            transition: background 0.18s ease, color 0.18s ease;
        }

        .sidebar-contact-tab:last-child {
            border-right: none;
        }

        .sidebar-contact-tab-icon {
            font-size: 0.95rem;
            line-height: 1;
        }

        .sidebar-contact-tab-label {
            white-space: nowrap;
        }

        .sidebar-contact-tab:hover,
        .sidebar-contact-tab:focus-visible {
            background: var(--surface-muted);
            color: var(--text-primary);
            outline: none;
        }

        .sidebar-contact-tab.is-active {
            background: var(--contact-active-bg);
            color: var(--contact-active-text);
            box-shadow: none;
        }

        @media (min-width: 769px) {
            .desktop-sidebar-tabs-host {
                display: block;
                flex-shrink: 0;
                padding: 12px 14px 0;
                background: var(--surface-bg, #ffffff);
                border-bottom: 1px solid var(--border-subtle);
            }

            .desktop-sidebar-tabs-host[hidden] {
                display: none !important;
            }

            .desktop-sidebar-tabs-host .sidebar-contact-tabs {
                margin: 0;
                padding: 0;
                border: 1px solid var(--border-subtle);
                border-bottom: none;
                border-radius: 18px 18px 0 0;
                overflow: hidden;
                background: var(--surface-elevated, #ffffff);
            }

            .desktop-sidebar-tabs-host .sidebar-contact-tab {
                flex: 1 1 25%;
                min-height: 58px;
            }
        }

        .sidebar-history-panel {
            display: flex;
            flex: 1 1 auto;
            flex-direction: column;
            min-height: 0;
            margin: 6px 0 12px;
            border: 1px solid var(--border-subtle);
            border-radius: 22px;
            background: var(--surface-elevated);
            overflow: hidden;
        }

        .sidebar-history-panel[hidden] {
            display: none !important;
        }

        .sidebar-history-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            padding: 16px 18px 10px;
            border-bottom: 1px solid var(--border-subtle);
            flex-shrink: 0;
        }

        .sidebar-history-title {
            font-size: 1rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .sidebar-history-refresh {
            width: 38px;
            height: 38px;
            border: 1px solid var(--border-subtle);
            border-radius: 12px;
            background: var(--surface-muted);
            color: var(--text-secondary);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
        }

        .sidebar-history-refresh:hover,
        .sidebar-history-refresh:focus-visible {
            background: var(--contact-active-bg);
            color: var(--text-primary);
            border-color: var(--contact-active-border);
            outline: none;
        }

        .sidebar-history-filters {
            display: flex;
            gap: 8px;
            padding: 12px 18px 14px;
            border-bottom: 1px solid var(--border-subtle);
            overflow-x: auto;
            flex-shrink: 0;
            scrollbar-width: none;
        }

        .sidebar-history-filters::-webkit-scrollbar {
            display: none;
        }

        .sidebar-history-filter {
            border: 1px solid var(--border-subtle);
            border-radius: 999px;
            background: var(--surface-bg);
            color: var(--text-secondary);
            font-size: 0.84rem;
            font-weight: 700;
            padding: 9px 14px;
            cursor: pointer;
            white-space: nowrap;
            transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
        }

        .sidebar-history-filter:hover,
        .sidebar-history-filter:focus-visible {
            background: var(--surface-muted);
            color: var(--text-primary);
            outline: none;
        }

        .sidebar-history-filter.is-active {
            background: var(--contact-active-bg);
            border-color: var(--contact-active-border);
            color: var(--contact-active-text);
        }

        .sidebar-history-status {
            padding: 14px 18px 0;
            color: var(--text-secondary);
            font-size: 0.86rem;
            line-height: 1.45;
            flex-shrink: 0;
        }

        .sidebar-history-status[data-state="error"] {
            color: #b91c1c;
        }

        .sidebar-history-list {
            flex: 1 1 auto;
            min-height: 0;
            overflow-y: auto;
            padding: 14px 18px 18px;
        }

        .sidebar-history-empty {
            padding: 28px 18px;
            border: 1px dashed var(--border-subtle);
            border-radius: 18px;
            background: var(--surface-muted);
            color: var(--text-secondary);
            font-size: 0.9rem;
            line-height: 1.5;
            text-align: center;
        }

        .sidebar-history-item {
            display: flex;
            align-items: flex-start;
            gap: 12px;
            padding: 14px 0;
            border-bottom: 1px solid var(--border-subtle);
        }

        .sidebar-history-item:last-child {
            border-bottom: none;
            padding-bottom: 0;
        }

        .sidebar-history-item-avatar,
        .sidebar-history-item-icon {
            flex: 0 0 42px;
            width: 42px;
            height: 42px;
            border-radius: 50%;
        }

        .sidebar-history-item-avatar {
            object-fit: cover;
            background: var(--surface-muted);
            border: 1px solid var(--border-subtle);
        }

        .sidebar-history-item-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: var(--surface-muted);
            border: 1px solid var(--border-subtle);
            color: var(--accent-color);
            font-size: 0.95rem;
        }

        .sidebar-history-item-main {
            display: flex;
            align-items: flex-start;
            gap: 12px;
            flex: 1 1 auto;
            min-width: 0;
        }

        .sidebar-history-item-copy {
            min-width: 0;
            flex: 1 1 auto;
        }

        .sidebar-history-item-text {
            color: var(--text-primary);
            font-size: 0.92rem;
            line-height: 1.45;
            word-break: break-word;
        }

        .sidebar-history-item-meta {
            margin-top: 6px;
            color: var(--text-secondary);
            font-size: 0.78rem;
            line-height: 1.35;
        }

        .sidebar-history-item-time {
            flex: 0 0 120px;
            margin-left: auto;
            color: var(--text-secondary);
            font-size: 0.74rem;
            line-height: 1.35;
            text-align: right;
        }

        .sidebar-history-message-bubble {
            display: inline-flex;
            max-width: 100%;
            padding: 10px 12px;
            border-radius: 16px;
            background: var(--accent-color);
            color: var(--accent-contrast);
            font-size: 0.92rem;
            line-height: 1.45;
            word-break: break-word;
        }

        .sidebar-history-call-icon {
            background: transparent;
            border: none;
            color: inherit;
        }

        .scrolls-panel {
            display: flex;
            flex: 1 1 auto;
            flex-direction: column;
            min-height: 0;
            margin: 6px 0 12px;
            border: 1px solid var(--border-subtle);
            border-radius: 22px;
            background: var(--surface-elevated, #ffffff);
            overflow: hidden;
        }

        .scrolls-panel[hidden] {
            display: none !important;
        }

        .scrolls-panel-head {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            padding: 16px 18px 12px;
            border-bottom: 1px solid var(--border-subtle);
            flex-shrink: 0;
        }

        .scrolls-panel-title {
            display: flex;
            flex-direction: column;
            gap: 4px;
            min-width: 0;
        }

        .scrolls-panel-title strong {
            font-size: 1rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .scrolls-panel-title span {
            color: var(--text-secondary);
            font-size: 0.86rem;
        }

        .scrolls-panel-actions {
            display: flex;
            align-items: center;
            gap: 10px;
            flex-shrink: 0;
        }

        .scrolls-create-trigger {
            min-height: 46px;
            padding: 10px 18px 10px 16px;
            white-space: nowrap;
        }

        .scrolls-create-trigger-hint {
            font-size: 0.78rem;
            font-weight: 800;
            color: var(--text-secondary);
            letter-spacing: 0.02em;
        }

        .scrolls-status {
            padding: 0 18px;
            color: var(--text-secondary);
            font-size: 0.86rem;
            flex-shrink: 0;
        }

        .scrolls-status[hidden] {
            display: none !important;
        }

        .scrolls-grid-wrap {
            flex: 1 1 auto;
            min-height: 0;
            overflow-y: auto;
            padding: 18px;
        }

        .scrolls-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 14px;
        }

        .scroll-card {
            position: relative;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: var(--surface-bg, #ffffff);
            overflow: hidden;
            cursor: pointer;
            box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .scroll-card:hover,
        .scroll-card:focus-visible {
            transform: translateY(-2px);
            box-shadow: 0 16px 32px rgba(15, 23, 42, 0.12);
            border-color: var(--accent-color);
            outline: none;
        }

        .scroll-card-video-wrap {
            position: relative;
            aspect-ratio: 9 / 16;
            background: #0f172a;
            overflow: hidden;
        }

        .scroll-card-video {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
            background: #020617;
        }

        .scroll-card-overlay {
            position: absolute;
            inset: 0;
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            gap: 14px;
            padding: 14px 12px 12px;
            background: linear-gradient(180deg, rgba(15, 23, 42, 0.08) 10%, rgba(15, 23, 42, 0.78) 100%);
            color: #f8fafc;
        }

        .scroll-card-copy {
            min-width: 0;
            display: flex;
            flex-direction: column;
            gap: 6px;
            padding-right: 4px;
        }

        .scroll-card-title {
            font-size: 0.9rem;
            font-weight: 800;
            line-height: 1.32;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
            text-wrap: pretty;
        }

        .scroll-card-author {
            font-weight: 700;
            font-size: 0.86rem;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            opacity: 0.96;
        }

        .scroll-card-stats {
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 0.76rem;
            opacity: 0.9;
        }

        .scroll-card-stats span {
            display: inline-flex;
            align-items: center;
            gap: 5px;
        }

        .scroll-card-actions {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            flex-shrink: 0;
        }

        .scroll-card-action-btn {
            display: inline-flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 4px;
            width: auto;
            min-height: auto;
            padding: 2px 0;
            border: none;
            border-radius: 0;
            background: transparent;
            color: #f8fafc;
            font: inherit;
            font-size: 0.8rem;
            font-weight: 700;
            cursor: pointer;
            text-shadow: 0 8px 20px rgba(2, 6, 23, 0.42);
            transition: transform 0.18s ease, color 0.18s ease, opacity 0.18s ease;
        }

        .scroll-card-action-btn:hover,
        .scroll-card-action-btn:focus-visible {
            transform: translateY(-1px);
            color: rgba(255, 255, 255, 0.94);
            outline: none;
        }

        .scroll-card-action-btn.is-active {
            color: var(--accent-color);
        }

        .scrolls-empty {
            border: 1px dashed var(--border-subtle);
            border-radius: 18px;
            padding: 22px 18px;
            text-align: center;
            color: var(--text-secondary);
            background: rgba(255, 255, 255, 0.72);
        }

        .scrolls-empty[hidden] {
            display: none !important;
        }

        .scrolls-compose-dialog {
            max-height: min(82dvh, 760px);
        }

        .scrolls-compose-body {
            display: flex;
            flex: 1 1 auto;
            flex-direction: column;
            gap: 16px;
            min-height: 0;
            overflow-y: auto;
            padding-right: 6px;
            margin-right: -4px;
            scrollbar-width: thin;
            scrollbar-color: var(--accent-color) rgba(148, 163, 184, 0.22);
        }

        .scrolls-compose-body::-webkit-scrollbar {
            width: 10px;
        }

        .scrolls-compose-body::-webkit-scrollbar-track {
            background: rgba(148, 163, 184, 0.12);
            border-radius: 999px;
        }

        .scrolls-compose-body::-webkit-scrollbar-thumb {
            background: var(--accent-color);
            border-radius: 999px;
        }

        .scrolls-compose-picker {
            display: flex;
            align-items: center;
            gap: 12px;
            flex-wrap: wrap;
        }

        .scrolls-compose-preview {
            display: flex;
            align-items: center;
            justify-content: center;
            width: min(220px, 100%);
            aspect-ratio: 9 / 16;
            border-radius: 20px;
            background: linear-gradient(180deg, #0f172a 0%, #1e293b 100%);
            overflow: hidden;
            color: rgba(248, 250, 252, 0.88);
            font-size: 0.9rem;
            text-align: center;
            padding: 18px;
        }

        .scrolls-compose-preview video {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .scrolls-compose-caption {
            width: 100%;
            min-height: 96px;
            resize: vertical;
        }

        .scrolls-viewer-panel {
            position: fixed;
            inset: 0;
            z-index: 9000;
            display: flex;
            flex: 1 1 auto;
            flex-direction: column;
            gap: 18px;
            min-height: 0;
            padding: 24px;
            overflow: hidden;
            overscroll-behavior: contain;
            scrollbar-width: thin;
            scrollbar-color: var(--accent-color) rgba(148, 163, 184, 0.22);
            background:
                radial-gradient(circle at top left, rgba(14, 165, 233, 0.14), transparent 42%),
                radial-gradient(circle at bottom right, rgba(249, 115, 22, 0.12), transparent 38%),
                #020617;
        }

        .scrolls-viewer-panel[hidden] {
            display: none !important;
        }

        .scrolls-viewer-panel::-webkit-scrollbar {
            width: 10px;
        }

        .scrolls-viewer-panel::-webkit-scrollbar-track {
            background: rgba(148, 163, 184, 0.12);
            border-radius: 999px;
        }

        .scrolls-viewer-panel::-webkit-scrollbar-thumb {
            background: var(--accent-color);
            border-radius: 999px;
        }

        .scrolls-viewer-toolbar {
            display: flex;
            align-items: center;
            justify-content: flex-start;
            gap: 12px;
            flex-shrink: 0;
            position: absolute;
            top: 24px;
            left: 24px;
            right: 24px;
            z-index: 5;
        }

        .scrolls-viewer-back {
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .scrolls-viewer-shell {
            display: grid;
            grid-template-columns: minmax(0, 1fr) minmax(320px, 400px);
            gap: 20px;
            align-items: center;
            flex: 1 1 auto;
            min-height: 0;
            height: 100%;
            padding-top: 58px;
            box-sizing: border-box;
            overflow: hidden;
            will-change: transform, opacity, filter;
        }

        .scrolls-viewer-stage-wrap {
            display: flex;
            align-items: center;
            justify-content: center;
            min-width: 0;
            min-height: 0;
            height: 100%;
        }

        .scrolls-viewer-stage {
            --scroll-stage-max-width: min(100%, 400px);
            --scroll-stage-max-height: min(100%, calc(100dvh - 152px));
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            width: min(var(--scroll-stage-max-width), calc(var(--scroll-stage-max-height) * 9 / 16));
            height: min(var(--scroll-stage-max-height), calc(var(--scroll-stage-max-width) * 16 / 9));
            aspect-ratio: 9 / 16;
            border-radius: 26px;
            overflow: hidden;
            background: #020617;
            box-shadow: 0 18px 42px rgba(15, 23, 42, 0.24);
            isolation: isolate;
            max-width: 100%;
            max-height: 100%;
            will-change: transform, opacity, filter;
        }

        .scrolls-viewer-video {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: center;
            display: block;
            background: #020617;
        }

        .scrolls-viewer-actions {
            position: absolute;
            right: 14px;
            bottom: calc(82px + env(safe-area-inset-bottom, 0px));
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 14px;
            z-index: 3;
        }

        .scrolls-viewer-side {
            display: flex;
            flex-direction: column;
            gap: 18px;
            min-width: 0;
            min-height: 0;
            max-height: 100%;
            overflow-y: auto;
            padding-right: 4px;
        }

        .scrolls-viewer-side-kicker {
            color: var(--text-secondary);
            font-size: 0.84rem;
            font-weight: 800;
            letter-spacing: 0.02em;
            text-transform: uppercase;
        }

        .scrolls-viewer-author {
            display: flex;
            align-items: flex-start;
            gap: 12px;
        }

        .scrolls-viewer-author img {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            object-fit: cover;
            flex-shrink: 0;
        }

        .scrolls-viewer-author-copy {
            min-width: 0;
            flex: 1 1 auto;
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .scrolls-viewer-author-row {
            display: flex;
            align-items: center;
            gap: 10px;
            flex-wrap: wrap;
            min-width: 0;
        }

        .scrolls-viewer-author-name {
            font-size: 1rem;
            font-weight: 800;
            color: var(--text-primary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .scrolls-viewer-author-subtitle {
            color: var(--text-secondary);
            font-size: 0.84rem;
        }

        .scrolls-follow-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            min-height: 36px;
            padding: 8px 14px;
            border: none;
            border-radius: 999px;
            background: var(--accent-color);
            color: #ffffff;
            font: inherit;
            font-size: 0.8rem;
            font-weight: 800;
            cursor: pointer;
            box-shadow: 0 12px 24px rgba(15, 23, 42, 0.16);
            transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
        }

        .scrolls-follow-btn:hover,
        .scrolls-follow-btn:focus-visible {
            transform: translateY(-1px);
            box-shadow: 0 16px 28px rgba(15, 23, 42, 0.2);
            outline: none;
        }

        .scrolls-follow-btn.is-active {
            background: rgba(15, 23, 42, 0.08);
            color: var(--text-primary);
            box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.34);
        }

        .scrolls-follow-btn[hidden] {
            display: none !important;
        }

        .scrolls-viewer-title {
            font-size: 1.2rem;
            font-weight: 800;
            color: var(--text-primary);
            line-height: 1.25;
            text-wrap: pretty;
        }

        .scrolls-action-btn {
            display: inline-flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 4px;
            width: auto;
            min-height: auto;
            padding: 0;
            border-radius: 0;
            border: none;
            background: transparent;
            color: #f8fafc;
            font: inherit;
            font-weight: 700;
            cursor: pointer;
            text-shadow: 0 8px 20px rgba(2, 6, 23, 0.42);
            transition: color 0.18s ease, transform 0.18s ease, opacity 0.18s ease;
        }

        .scrolls-action-btn:hover,
        .scrolls-action-btn:focus-visible {
            outline: none;
            transform: translateY(-1px);
            color: rgba(255, 255, 255, 0.94);
