            z-index: 3;
            color: #f8fafc;
            pointer-events: none;
        }

        .scrolls-viewer-mobile-layout {
            width: 100%;
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            gap: 12px;
            align-items: end;
        }

        .scrolls-viewer-mobile-identity {
            display: flex;
            align-items: flex-end;
            gap: 10px;
            min-width: 0;
            max-width: 100%;
        }

        .scrolls-viewer-mobile-identity img,
