            width: 36px;
            height: 36px;
            border-radius: 50%;
            object-fit: cover;
            flex-shrink: 0;
            box-shadow: 0 10px 24px rgba(2, 6, 23, 0.22);
        }

        .scrolls-viewer-mobile-identity-copy {
            display: flex;
            flex-direction: column;
            gap: 4px;
            min-width: 0;
        }

        .scrolls-viewer-mobile-author-name {
            font-size: 0.92rem;
            font-weight: 800;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 100%;
        }

        .scrolls-viewer-mobile-author-subtitle {
            font-size: 0.78rem;
            color: rgba(248, 250, 252, 0.84);
        }

        .scrolls-viewer-mobile-right {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            justify-content: flex-end;
            gap: 8px;
            min-width: 0;
            text-align: right;
            pointer-events: auto;
        }

        .scrolls-viewer-mobile-title {
            margin-top: 2px;
            font-size: 0.98rem;
            font-weight: 800;
            line-height: 1.28;
            text-wrap: pretty;
            text-shadow: 0 10px 28px rgba(2, 6, 23, 0.48);
