        .scrolls-follow-btn-mobile {
            pointer-events: auto;
            min-height: 32px;
            padding: 6px 12px;
            font-size: 0.76rem;
            box-shadow: 0 12px 24px rgba(2, 6, 23, 0.22);
        }

        .scrolls-viewer-controls {
            position: absolute;
            left: 0;
            right: 0;
            bottom: 0;
            z-index: 2;
            display: flex;
            align-items: flex-end;
            gap: 14px;
            padding: 18px 18px calc(16px + env(safe-area-inset-bottom, 0px));
            background: linear-gradient(0deg, rgba(2, 6, 23, 0.96) 0%, rgba(2, 6, 23, 0.8) 52%, rgba(2, 6, 23, 0) 100%);
        }

        .scrolls-viewer-play-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 48px;
            height: 48px;
            border: none;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.12);
            color: #f8fafc;
            font: inherit;
            font-size: 1rem;
            cursor: pointer;
            backdrop-filter: blur(12px);
            box-shadow: 0 12px 24px rgba(2, 6, 23, 0.18);
            transition: transform 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
        }

        .scrolls-viewer-play-btn:hover,
        .scrolls-viewer-play-btn:focus-visible {
            background: rgba(255, 255, 255, 0.2);
            outline: none;
            transform: translateY(-1px);
            box-shadow: 0 16px 30px rgba(2, 6, 23, 0.22);
        }

        .scrolls-viewer-progress-wrap {
            flex: 1 1 auto;
            min-width: 0;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .scrolls-viewer-progress {
            --scroll-progress: 0%;
            width: 100%;
            margin: 0;
            padding: 0;
            border: none;
            background: transparent;
            appearance: none;
            -webkit-appearance: none;
            accent-color: var(--accent-color);
            cursor: pointer;
        }

        .scrolls-viewer-progress:focus-visible {
            outline: none;
        }

        .scrolls-viewer-progress:disabled {
            opacity: 0.45;
            cursor: default;
        }

        .scrolls-viewer-progress::-webkit-slider-runnable-track {
            height: 4px;
            border-radius: 999px;
            background: linear-gradient(90deg, var(--accent-color) 0%, var(--accent-color) var(--scroll-progress), rgba(255, 255, 255, 0.28) var(--scroll-progress), rgba(255, 255, 255, 0.28) 100%);
        }

        .scrolls-viewer-progress::-moz-range-track {
            height: 4px;
            border-radius: 999px;
            background: linear-gradient(90deg, var(--accent-color) 0%, var(--accent-color) var(--scroll-progress), rgba(255, 255, 255, 0.28) var(--scroll-progress), rgba(255, 255, 255, 0.28) 100%);
        }

        .scrolls-viewer-progress::-webkit-slider-thumb {
            appearance: none;
            -webkit-appearance: none;
            width: 12px;
            height: 12px;
            margin-top: -4px;
            border: none;
            border-radius: 50%;
            background: #ffffff;
            box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.16);
        }

        .scrolls-viewer-progress::-moz-range-thumb {
            width: 12px;
            height: 12px;
            border: none;
            border-radius: 50%;
            background: #ffffff;
            box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.16);
        }

        .scrolls-viewer-time {
            color: rgba(248, 250, 252, 0.88);
            font-size: 0.78rem;
            font-weight: 700;
            text-align: right;
        }

        .scrolls-viewer-comments {
            display: none;
            flex: 1 1 auto;
            min-height: 0;
            max-height: 100%;
            border: 1px solid var(--border-subtle);
            border-radius: 24px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            box-shadow: 0 18px 40px rgba(15, 23, 42, 0.12);
            overflow: hidden;
        }

        .scrolls-viewer-panel.is-comments-mode .scrolls-viewer-comments {
            display: flex;
            flex-direction: column;
        }

        .scrolls-viewer-panel.is-comments-mode .scrolls-viewer-side {
            display: none;
        }

        .scrolls-viewer-panel.is-comments-mode .scrolls-viewer-mobile-meta {
            display: flex;
        }

        .scrolls-comments-head {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            padding: 16px 18px 14px;
            border-bottom: 1px solid var(--border-subtle);
            flex-shrink: 0;
        }

        .scrolls-comments-head-copy {
