        }

        .scrolls-comments-head-copy strong {
            display: block;
            font-size: 1rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .scrolls-comments-head-copy span {
            display: block;
            margin-top: 4px;
            color: var(--text-secondary);
            font-size: 0.82rem;
        }

        .scrolls-comments-close {
            width: 38px;
            height: 38px;
            border: none;
            border-radius: 14px;
            background: rgba(148, 163, 184, 0.14);
            color: var(--text-secondary);
            cursor: pointer;
            transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
        }

        .scrolls-comments-close:hover,
        .scrolls-comments-close:focus-visible {
            background: rgba(148, 163, 184, 0.22);
            color: var(--text-primary);
            outline: none;
            transform: translateY(-1px);
        }

        .scrolls-comments-list {
            flex: 1 1 auto;
            min-height: 0;
            overflow-y: auto;
            overflow-x: hidden;
            padding: 16px 18px;
            display: flex;
            flex-direction: column;
            gap: 14px;
        }

        .scrolls-comments-list::-webkit-scrollbar {
            width: 10px;
        }

        .scrolls-comments-list::-webkit-scrollbar-thumb {
            background: var(--accent-color);
            border-radius: 999px;
        }

        .scrolls-comments-empty {
            color: var(--text-secondary);
