            flex-shrink: 0;
        }

        .scrolls-comment-body {
            min-width: 0;
            flex: 1 1 auto;
        }

        .scrolls-comment-card {
            border-radius: 18px;
            padding: 12px 14px;
            background: rgba(255, 255, 255, 0.88);
            border: 1px solid rgba(148, 163, 184, 0.18);
        }

        .scrolls-comment-reply-context {
            display: flex;
            flex-direction: column;
            gap: 3px;
            margin-bottom: 10px;
            padding: 9px 11px;
            border-radius: 14px;
            border-left: 3px solid var(--accent-color);
            background: rgba(14, 165, 233, 0.08);
        }

        .scrolls-comment-reply-context-label {
            font-size: 0.72rem;
            font-weight: 800;
            color: var(--accent-color);
            letter-spacing: 0.01em;
            text-transform: uppercase;
        }

        .scrolls-comment-reply-context-text {
            color: var(--text-secondary);
            font-size: 0.8rem;
            line-height: 1.45;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .scrolls-comment-head {
            display: flex;
            align-items: baseline;
            justify-content: space-between;
            gap: 12px;
            margin-bottom: 6px;
        }

        .scrolls-comment-name {
            font-size: 0.9rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .scrolls-comment-time {
            font-size: 0.74rem;
            color: var(--text-secondary);
