        }

        .scrolls-comment-text {
            color: var(--text-primary);
            font-size: 0.9rem;
            line-height: 1.52;
            white-space: pre-wrap;
            word-break: break-word;
        }

        .scrolls-comment-actions-row {
            display: flex;
            align-items: center;
            gap: 8px;
            flex-wrap: wrap;
            margin-top: 12px;
        }

        .scrolls-comment-action {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            min-height: 32px;
            padding: 6px 10px;
            border: none;
            border-radius: 999px;
            background: rgba(148, 163, 184, 0.12);
            color: var(--text-secondary);
            font: inherit;
            font-size: 0.78rem;
            font-weight: 700;
            cursor: pointer;
            transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease;
        }

        .scrolls-comment-action:hover,
        .scrolls-comment-action:focus-visible {
            transform: translateY(-1px);
            background: rgba(148, 163, 184, 0.18);
            color: var(--text-primary);
            outline: none;
        }

        .scrolls-comment-action.is-active {
            background: rgba(14, 165, 233, 0.14);
            color: var(--accent-color);
        }

        .scrolls-comment-action-count {
            min-width: 1ch;
            color: inherit;
            line-height: 1;
        }

        .scrolls-comments-compose {
            padding: 16px 18px 18px;
            border-top: 1px solid var(--border-subtle);
            display: flex;
            flex-direction: column;
            gap: 12px;
            flex-shrink: 0;
            background: rgba(255, 255, 255, 0.84);
        }

        .scrolls-comments-reply-bar {
            display: flex;
            align-items: flex-start;
            justify-content: space-between;
            gap: 12px;
            padding: 10px 12px;
            border-radius: 16px;
            background: rgba(14, 165, 233, 0.08);
            border: 1px solid rgba(14, 165, 233, 0.16);
        }

        .scrolls-comments-reply-bar[hidden] {
            display: none !important;
        }

        .scrolls-comments-reply-copy {
            min-width: 0;
            color: var(--text-secondary);
            font-size: 0.8rem;
            line-height: 1.45;
        }

        .scrolls-comments-reply-clear {
            width: 32px;
            height: 32px;
            border: none;
            border-radius: 12px;
            background: rgba(148, 163, 184, 0.14);
            color: var(--text-secondary);
            cursor: pointer;
            flex-shrink: 0;
            transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
        }

        .scrolls-comments-reply-clear:hover,
        .scrolls-comments-reply-clear:focus-visible {
            background: rgba(148, 163, 184, 0.22);
            color: var(--text-primary);
            outline: none;
            transform: translateY(-1px);
        }

        .scrolls-comments-input {
            width: 100%;
            min-height: 88px;
            box-sizing: border-box;
            border: 1px solid var(--border-subtle);
            border-radius: 18px;
            padding: 12px 14px;
            font: inherit;
            color: var(--text-primary);
            background: var(--surface-bg, #ffffff);
            resize: vertical;
        }

        .scrolls-comments-input:focus {
            outline: none;
            border-color: var(--accent-color);
        }

        .scrolls-comments-compose-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
        }

        .scrolls-comments-submit {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 42px;
            height: 42px;
            padding: 0;
            border: none;
            border-radius: 50%;
            background: #2d58f5;
            color: var(--accent-contrast);
            font: inherit;
            font-weight: 800;
            cursor: pointer;
            flex: 0 0 auto;
            transition: background-color 0.3s ease;
        }

        .scrolls-comments-submit i {
            font-size: 1rem;
            line-height: 1;
            color: var(--accent-contrast);
            display: block;
            transform: translateX(-3px) rotate(47deg);
            transform-origin: center;
        }

        .scrolls-comments-submit:hover:not(:disabled),
        .scrolls-comments-submit:focus-visible:not(:disabled) {
            background: #2447c9;
            outline: none;
        }

        .scrolls-comments-submit:disabled {
            opacity: 0.6;
            cursor: default;
        }

        .scrolls-comments-status {
            color: var(--text-secondary);
            font-size: 0.82rem;
            min-height: 1.2em;
        }

        .scrolls-comments-status[data-state="error"] {
            color: #dc2626;
        }

        .scroll-comments-overlay {
            position: fixed;
            inset: 0;
            z-index: 13000;
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
            background: rgba(15, 23, 42, 0.36);
            transition: opacity 0.24s ease, visibility 0.24s step-end;
        }

        .scroll-comments-overlay.open {
            opacity: 1;
            visibility: visible;
            pointer-events: auto;
            transition: opacity 0.24s ease;
        }

        .scroll-comments-sheet {
            position: absolute;
            left: 8px;
            right: 8px;
            bottom: 0;
            width: min(560px, calc(100vw - 16px));
            max-width: 560px;
            max-width: calc(100vw - 16px);
            max-height: min(78dvh, 720px);
            min-height: 0;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 14px;
            box-sizing: border-box;
            padding: 18px max(16px, calc(16px + env(safe-area-inset-right, 0px))) calc(18px + env(safe-area-inset-bottom, 0px)) max(16px, calc(16px + env(safe-area-inset-left, 0px)));
            border-radius: 28px 28px 0 0;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            box-shadow: 0 -24px 54px rgba(15, 23, 42, 0.22);
            transform: translateY(34px) scale(0.98);
            opacity: 0;
            transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.28s ease;
        }

        .scroll-comments-overlay.open .scroll-comments-sheet {
            transform: translateY(0) scale(1);
            opacity: 1;
        }

        .scroll-comments-sheet-head {
            display: flex;
            align-items: flex-start;
            justify-content: space-between;
            gap: 12px;
            padding-bottom: 6px;
            border-bottom: 1px solid var(--border-subtle);
        }

        .scroll-comments-sheet-head-copy {
            min-width: 0;
        }

        .scroll-comments-sheet-head-copy strong {
            display: block;
            font-size: 1rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .scroll-comments-sheet-head-copy span {
            display: block;
            margin-top: 4px;
            font-size: 0.82rem;
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .scroll-comments-sheet-close {
            width: 38px;
            height: 38px;
            border: none;
            border-radius: 14px;
            background: rgba(148, 163, 184, 0.14);
            color: var(--text-secondary);
            cursor: pointer;
        }

        .scroll-comments-sheet .scrolls-comments-list {
            padding: 4px 4px 0;
        }

        .scroll-comments-sheet .scrolls-comments-compose {
            padding: 0;
            border-top: none;
