        }

        .scrolls-viewer-panel.is-comments-mode .scrolls-viewer-actions {
            bottom: calc(124px + env(safe-area-inset-bottom, 0px));
        }

        .scrolls-settings-card {
            border: 1px solid var(--border-subtle);
            border-radius: 18px;
            padding: 14px;
            background: var(--surface-bg, #ffffff);
