                bottom: calc(76px + env(safe-area-inset-bottom, 0px));
            }

            .scrolls-viewer-actions {
                right: 12px;
                bottom: calc(126px + env(safe-area-inset-bottom, 0px));
                gap: 10px;
            }

            .scrolls-viewer-controls {
