            }

            .contact-quick-actions-menu {
                left: 12px !important;
                right: 12px !important;
                top: auto !important;
                bottom: calc(12px + env(safe-area-inset-bottom, 0px));
                max-width: none;
                min-width: 0;
                border-radius: 24px;
                padding: 10px;
            }

        }
        
        .contact {
            width: 100% !important;
            display: flex;
            align-items: center;
            box-sizing: border-box;
            padding: 12px;
            margin: 0;
            position: relative;
            z-index: 1;
            pointer-events: auto;
            touch-action: manipulation;
        }

        .mobile-contact-status-card {
