            height: 40px;
            border-radius: 50%;
            object-fit: cover;
        }

        .contact-img-wrapper {
            position: relative;
            display: inline-block;
        }

        .online-indicator {
            position: absolute;
            bottom: 0;
            right: 0;
            width: 12px;
            min-width: 12px;
            height: 12px;
            min-height: 12px;
            border-radius: 50%;
            background-color: #6b7280; /* Default gray */
            border: 2px solid white;
            z-index: 1;

            --presence-typing-width: 20px;

            --presence-typing-height: 12px;
        }

        .online-indicator.online {
            background-color: #22c55e;
        }

        .contact .online-indicator {
            width: 12px !important;
            min-width: 12px !important;
            height: 12px !important;
            min-height: 12px !important;
        }

        @media (min-width: 769px) {
            .mobile-sidebar-brand {
                display: none;
            }
        }

        .mobile-sidebar-brand-logo {
            display: block;
            height: 70px;
            width: auto;
            max-width: min(260px, 66vw);
            object-fit: contain;
	    transform: translateX(20px);
        }

        .mobile-sidebar-brand-logo--light {
            display: none;
        }

        .mobile-sidebar-brand-logo--dark {
            display: block;
        }

        html[data-theme="dark"] .mobile-sidebar-brand-logo--light {
            display: block;
        }

        html[data-theme="dark"] .mobile-sidebar-brand-logo--dark {
            display: none;
        }

        html[data-theme="dark"] .mobile-contact-status-card {
            background: transparent;
            border-color: transparent;
            box-shadow: none;
        }

        html[data-theme="dark"] .mobile-contact-status-name {
            color: var(--text-primary);
        }

        html[data-theme="dark"] .mobile-contact-status-text {
            display: none;
        }

        @media (min-width: 769px) {
            .mobile-contacts-strip {
                display: none;
            }
        }

