        /* User Dropdown */
        .user-dropdown {
          position: relative;
          display: inline-block;
        }

        .profile-container {
          display: flex;
          align-items: center;
          cursor: pointer;
          background: none;
          border: none;
          padding: 0;
          font: inherit;
        }

        .profile-btn {
          width: 40px;
          height: 40px;
          border-radius: 50%;
          object-fit: cover;
        }

        .down-arrow {
          margin-left: 5px;
          font-size: 12px;
          pointer-events: none; /* so hover triggers work */
        }

        /* Dropdown menu */
        .dropdown-menu {
          display: none;
          position: absolute;
          right: 0;
          top: 100%;
          background: var(--surface-elevated);
          border: 1px solid var(--border-subtle);
          border-radius: 8px;
          padding: 10px;
          min-width: 130px;
          z-index: 999;
        }

        .dropdown-menu::before {
          content: '';
          position: absolute;
          left: 0;
          right: 0;
          top: -10px;
          height: 10px;
        }

        /* Show dropdown on hover */
        .user-dropdown:hover .dropdown-menu,
        .user-dropdown:focus-within .dropdown-menu,
        .dropdown-menu.show {
          display: block;
        }

        .dropdown-menu {
          padding: 8px;
          min-width: 170px;
        }

        .dropdown-menu button {
          display: flex;
          align-items: center;
          gap: 10px;
          width: 100%;
          padding: 11px 12px;
          border-radius: 12px;
          font-weight: 600;
          color: #111827;
          transition: background-color 0.2s ease, color 0.2s ease;
        }

        .dropdown-menu button + button {
          margin-top: 4px;
        }

        .dropdown-menu button:hover {
          background: #f4f7ff;
        }

        .dropdown-action-icon {
          width: 18px;
          text-align: center;
          font-size: 0.98rem;
          flex-shrink: 0;
          transition: transform 0.35s ease, color 0.2s ease;
        }

        .settings-dropdown-btn .dropdown-action-icon {
          color: #2d58f5;
        }

        .settings-dropdown-btn:hover .dropdown-action-icon {
          transform: rotate(180deg);
        }

        .group-settings-trigger .dropdown-action-icon {
          color: var(--accent-color, #2d58f5);
        }

        .group-settings-trigger:hover .dropdown-action-icon {
          transform: rotate(180deg);
        }

        .logout-dropdown-btn .dropdown-action-icon {
          color: #dc2626;
        }

        .dropdown-action-label {
          font-family: 'Raleway', sans-serif;
          font-weight: 600;
          line-height: 1;
        }

        .friend-request-modal {
          position: fixed;
          inset: 0;
          display: none;
          align-items: center;
          justify-content: center;
          padding: 24px;
          background: rgba(15, 23, 42, 0.28);
          backdrop-filter: blur(16px);
          z-index: 12000;
        }

        .friend-request-modal.open {
          display: flex;
          pointer-events: auto;
        }

        .friend-request-modal-dialog {
          position: relative;
          width: min(560px, calc(100vw - 32px));
          max-height: min(76dvh, 720px);
          min-height: 0;
          overflow: hidden;
          display: flex;
          flex-direction: column;
          gap: 18px;
          padding: 28px;
          box-sizing: border-box;
          border: 1px solid var(--border-subtle);
          border-radius: 32px;
          background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
          box-shadow: 0 28px 60px rgba(15, 23, 42, 0.24);
        }

        .friend-request-modal-close {
          position: absolute;
          top: 18px;
          right: 18px;
          width: 40px;
          height: 40px;
          border: 1px solid var(--border-subtle);
          border-radius: 14px;
          background: var(--surface-bg);
          color: var(--text-secondary);
          cursor: pointer;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
        }

        .friend-request-modal-close:hover,
        .friend-request-modal-close:focus-visible {
          color: var(--accent-color);
          border-color: var(--accent-color);
          background: var(--accent-soft);
          outline: none;
          transform: translateY(-1px);
        }

        .friend-request-modal-kicker {
          margin: 0;
          font-size: 0.78rem;
          letter-spacing: 0.16em;
          text-transform: uppercase;
          font-weight: 800;
          color: var(--accent-color);
        }

        .friend-request-modal-head h2 {
          margin: 6px 0 8px;
          font-size: 1.9rem;
          line-height: 1.1;
          color: var(--text-primary);
        }

        .friend-request-modal-head p:last-child {
          margin: 0;
          color: var(--text-secondary);
          line-height: 1.6;
        }

        .friend-request-modal-head,
        .friend-request-modal-actions,
        .group-chat-step-actions,
        .group-settings-actions {
          flex-shrink: 0;
        }

        .friend-request-modal-body {
          display: flex;
          flex-direction: column;
          gap: 18px;
          min-height: 0;
        }

        .friend-request-modal-actions {
          display: flex;
          justify-content: flex-end;
          gap: 12px;
          flex-wrap: wrap;
        }

        .friend-request-search-shell {
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 14px 16px;
          border: 1px solid var(--border-subtle);
          border-radius: 22px;
          background: var(--surface-bg);
          box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28);
        }

        .friend-request-search-shell:focus-within {
          border-color: var(--accent-color);
          box-shadow: 0 0 0 4px var(--accent-soft), inset 0 1px 0 rgba(255, 255, 255, 0.28);
        }

        .friend-request-search-shell i {
          color: var(--accent-color);
          font-size: 1rem;
          flex-shrink: 0;
        }

        .friend-request-search-shell input {
          width: 100%;
          border: none;
          outline: none;
          background: transparent;
          color: var(--text-primary);
          font: inherit;
          font-size: 1rem;
        }

        .friend-request-search-shell input::placeholder {
          color: var(--text-muted);
        }

        .group-chat-modal-dialog {
          width: min(680px, calc(100vw - 32px));
          max-height: min(82dvh, 780px);
        }

        .group-chat-step {
          display: none;
          flex-direction: column;
          gap: 18px;
          min-height: 0;
        }

        .group-chat-step.active {
          display: flex;
          flex: 1 1 auto;
          overflow-y: auto;
          overflow-x: hidden;
          padding-right: 4px;
          overscroll-behavior: contain;
        }

        .group-chat-modal-single-flow .group-chat-step,
        .group-chat-modal-single-flow .group-chat-step.active,
        .group-chat-modal-single-flow .group-chat-step[hidden] {
          display: flex !important;
        }

        .group-chat-modal-single-flow #groupChatStepMembers {
          flex: 0 0 auto;
        }

        .group-chat-modal-single-flow #groupChatStepDetails {
          padding-top: 8px;
          border-top: 1px solid var(--border-subtle);
        }

        .group-chat-modal-single-flow #groupChatStepMembers .group-chat-step-actions,
        .group-chat-modal-single-flow #groupChatDetailsBack {
          display: none;
        }

        .group-chat-modal-single-flow .group-chat-members-list {
