        }

        .group-chat-icon-preview-wrap {
          width: 96px;
          height: 96px;
          border-radius: 30px;
          overflow: hidden;
          border: 1px solid var(--border-subtle);
          background: var(--surface-bg);
          box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28);
          flex-shrink: 0;
        }

        .group-chat-icon-preview {
          width: 100%;
          height: 100%;
          object-fit: cover;
          display: block;
        }

        .group-chat-icon-actions {
          min-width: 0;
