        .group-chat-field {
          display: flex;
          flex-direction: column;
          gap: 10px;
          color: var(--text-primary);
          font-weight: 700;
        }

        .group-chat-field input,
        .group-chat-field textarea {
          width: 100%;
          border: 1px solid var(--border-strong);
          border-radius: 20px;
          background: var(--surface-bg);
          color: var(--text-primary);
          font: inherit;
          padding: 14px 16px;
          resize: vertical;
          outline: none;
        }

        .group-chat-field input:focus,
        .group-chat-field textarea:focus {
          border-color: var(--accent-color);
          box-shadow: 0 0 0 4px var(--accent-soft);
        }

        .table-picker-controls {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 14px;
        }

        .table-picker-status {
          color: var(--text-secondary);
          font-size: 0.9rem;
          font-weight: 600;
        }

        .table-picker-grid-shell {
          display: flex;
          flex-direction: column;
          gap: 12px;
        }

        .table-picker-actions {
          justify-content: space-between;
          align-items: center;
        }

        .table-picker-grid-frame {
          display: inline-flex;
          max-width: 100%;
          max-height: 320px;
          padding: 12px;
          border: 1px solid var(--border-subtle);
          border-radius: 18px;
          background: var(--surface-bg);
          overflow: auto;
        }

        .table-picker-grid {
          --table-picker-cols: 8;
          display: grid;
          grid-template-columns: repeat(var(--table-picker-cols), 24px);
          gap: 6px;
        }

        .table-picker-cell {
          width: 24px;
          height: 24px;
          border: 1px solid var(--border-subtle);
          border-radius: 7px;
          background: var(--surface-muted);
          transition: background 0.14s ease, border-color 0.14s ease, transform 0.14s ease;
          cursor: pointer;
        }

        .table-picker-cell.is-active {
          background: var(--accent-soft);
          border-color: var(--accent-color);
          transform: translateY(-1px);
        }

        .table-picker-cell:hover {
          border-color: var(--accent-color);
        }
        
