        }

        .chat-action-modal-actions {
          display: flex;
          align-items: center;
          gap: 12px;
          flex-wrap: wrap;
        }

        .chat-action-modal-btn {
          min-width: 112px;
          min-height: 46px;
          border-radius: 14px;
          border: 1px solid transparent;
          font: inherit;
          font-weight: 700;
          cursor: pointer;
          transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease, border-color 0.18s ease;
        }

        .chat-action-modal-btn:hover,
        .chat-action-modal-btn:focus-visible {
          outline: none;
          transform: translateY(-1px);
        }

        .chat-action-modal-btn.confirm[data-tone="danger"] {
          background: #ef4444;
          color: #ffffff;
          box-shadow: 0 16px 30px rgba(239, 68, 68, 0.26);
        }

        .chat-action-modal-btn.confirm[data-tone="danger"]:hover,
        .chat-action-modal-btn.confirm[data-tone="danger"]:focus-visible {
          background: #dc2626;
        }

        .chat-action-modal-btn.confirm[data-tone="accent"] {
          background: var(--accent-color);
          color: var(--accent-contrast);
          box-shadow: 0 16px 30px var(--accent-shadow);
        }

        .chat-action-modal-btn.confirm[data-tone="accent"]:hover,
        .chat-action-modal-btn.confirm[data-tone="accent"]:focus-visible {
          background: var(--accent-hover);
        }

        .chat-action-modal-btn.cancel {
          background: rgba(148, 163, 184, 0.18);
          color: var(--text-primary);
          border-color: var(--border-subtle);
        }

        .friend-request-search-status {
