        .game-catalog-body {
            display: flex;
            flex-direction: column;
            flex: 1 1 auto;
            min-height: 0;
            gap: 18px;
            padding: 22px 28px 28px;
            overflow-y: auto;
            overscroll-behavior: contain;
        }

        .game-catalog-list {
            display: flex;
            flex-direction: column;
            gap: 14px;
        }

        .game-catalog-card {
            display: flex;
            align-items: center;
            gap: 18px;
            width: 100%;
            padding: 18px;
            border: 1px solid var(--border-subtle);
            border-radius: 24px;
            background:
                radial-gradient(circle at top right, rgba(45, 88, 245, 0.12) 0%, transparent 40%),
                linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            box-shadow: 0 16px 30px rgba(15, 23, 42, 0.08);
            cursor: pointer;
            text-align: left;
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .game-catalog-card:hover,
        .game-catalog-card:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(45, 88, 245, 0.34);
            box-shadow: 0 20px 36px rgba(15, 23, 42, 0.14);
            outline: none;
        }

        .game-catalog-card:disabled {
            cursor: wait;
            opacity: 0.74;
            transform: none;
            box-shadow: 0 12px 24px rgba(15, 23, 42, 0.08);
        }

        .game-catalog-preview {
            display: grid;
            grid-template-columns: repeat(4, 14px);
            gap: 3px;
            padding: 8px;
            border-radius: 18px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-soft) 100%);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.32);
            flex-shrink: 0;
        }

        .game-catalog-preview span {
            width: 14px;
            height: 14px;
            border-radius: 4px;
            background: rgba(255, 255, 255, 0.88);
        }

        .game-catalog-preview span.is-dark {
            background: var(--accent-color);
            opacity: 0.74;
        }

        .game-catalog-preview.is-checkers {
            grid-template-columns: repeat(4, 15px);
        }

        .game-catalog-preview.is-checkers span {
            border-radius: 999px;
            background: #f8fafc;
            box-shadow: inset 0 -2px 0 rgba(15, 23, 42, 0.12);
        }

        .game-catalog-preview.is-checkers span.is-dark {
            background: #0f172a;
            opacity: 1;
            box-shadow: inset 0 -2px 0 rgba(255, 255, 255, 0.12);
        }

        .game-catalog-preview.is-connect-four {
            grid-template-columns: repeat(4, 15px);
            background: linear-gradient(180deg, #1d4ed8 0%, #1e40af 100%);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18);
        }

        .game-catalog-preview.is-connect-four span {
            border-radius: 999px;
            background: rgba(255, 255, 255, 0.94);
        }

        .game-catalog-preview.is-connect-four span.is-dark {
            background: #f59e0b;
            opacity: 1;
        }

        .game-catalog-preview.is-sketchoff {
            display: flex;
            align-items: center;
            justify-content: center;
            min-width: 76px;
            min-height: 76px;
            background:
                radial-gradient(circle at 18% 18%, rgba(255, 255, 255, 0.82) 0, rgba(255, 255, 255, 0.82) 10px, transparent 10px),
                linear-gradient(135deg, #f97316 0%, #ea580c 42%, #7c2d12 100%);
            overflow: hidden;
        }

        .game-catalog-preview.is-sketchoff i {
            font-size: 1.85rem;
            color: #fff7ed;
            text-shadow: 0 10px 18px rgba(124, 45, 18, 0.34);
        }

        .game-catalog-copy {
            min-width: 0;
            flex: 1;
        }

        .game-catalog-title-row {
            display: flex;
            align-items: center;
            gap: 10px;
            flex-wrap: wrap;
        }

        .game-catalog-title {
            font-size: 1.02rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .game-catalog-badge {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-height: 24px;
            padding: 4px 10px;
            border-radius: 999px;
            background: var(--accent-soft);
            color: var(--accent-color);
            font-size: 0.76rem;
            font-weight: 800;
            letter-spacing: 0.04em;
            text-transform: uppercase;
        }

        .game-catalog-copy-text {
            margin: 8px 0 0;
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .chess-setup-modal-dialog {
            width: min(620px, calc(100vw - 32px));
            max-height: min(82dvh, 760px);
            gap: 0;
            padding: 0;
            overflow: hidden;
        }

        .chess-setup-body {
            display: flex;
            flex: 1 1 auto;
            flex-direction: column;
            gap: 18px;
            min-height: 0;
            overflow-y: auto;
            overflow-x: hidden;
            padding: 22px 28px 24px;
            overscroll-behavior: contain;
        }

        #chessSetupModal .friend-request-modal-actions {
            padding: 18px 28px 28px;
            border-top: 1px solid var(--border-subtle);
            background: linear-gradient(180deg, rgba(255, 255, 255, 0) 0%, var(--surface-bg) 100%);
        }

        .chess-setup-opponents {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 14px;
        }

        .chess-setup-opponent-card {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            gap: 10px;
            width: 100%;
            padding: 18px;
            border: 1px solid var(--border-subtle);
            border-radius: 22px;
            background:
                radial-gradient(circle at top right, rgba(45, 88, 245, 0.12) 0%, transparent 42%),
                linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            color: var(--text-primary);
            text-align: left;
            cursor: pointer;
            transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
        }

        .chess-setup-opponent-card:hover,
        .chess-setup-opponent-card:focus-visible,
        .chess-setup-opponent-card.is-selected {
            border-color: rgba(45, 88, 245, 0.42);
            box-shadow: 0 18px 34px rgba(15, 23, 42, 0.12);
            outline: none;
            transform: translateY(-1px);
        }

        .chess-setup-opponent-card.is-selected {
            box-shadow: 0 0 0 3px var(--accent-soft), 0 18px 34px rgba(15, 23, 42, 0.12);
        }

        .chess-setup-opponent-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 46px;
            height: 46px;
            border-radius: 16px;
            background: var(--accent-soft);
            color: var(--accent-color);
            font-size: 1rem;
        }

        .chess-setup-card-title {
            font-size: 0.98rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .chess-setup-card-copy {
            color: var(--text-secondary);
            line-height: 1.5;
            font-size: 0.9rem;
        }

        .chess-setup-options {
            display: flex;
            flex-direction: column;
            gap: 16px;
            padding: 18px;
            border: 1px solid var(--border-subtle);
            border-radius: 22px;
            background: var(--surface-muted);
        }

        .chess-setup-options[hidden] {
            display: none !important;
        }

        .chess-setup-section {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .chess-setup-section-title {
            color: var(--text-primary);
            font-size: 0.88rem;
            font-weight: 800;
            letter-spacing: 0.04em;
            text-transform: uppercase;
        }

        .chess-setup-chip-row {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }

        .chess-setup-chip {
            min-height: 40px;
            padding: 9px 14px;
            border: 1px solid var(--border-subtle);
            border-radius: 999px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font: inherit;
            font-weight: 700;
            cursor: pointer;
            transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
        }

        .chess-setup-chip:hover,
        .chess-setup-chip:focus-visible,
        .chess-setup-chip.is-selected {
            border-color: var(--accent-color);
            background: var(--accent-soft);
            color: var(--accent-color);
            outline: none;
        }

        .chess-setup-note {
            color: var(--text-secondary);
            line-height: 1.5;
            font-size: 0.9rem;
        }

        .chess-game-modal-dialog {
            position: relative;
            width: min(1320px, calc(100vw - 24px));
            max-height: min(96dvh, 900px);
            gap: 0;
            padding: 0;
            overflow: hidden;
        }

        .chess-game-body {
            display: flex;
            flex: 1 1 auto;
            min-height: 0;
            padding: 18px 22px 20px;
            overflow: hidden;
        }

        .chess-game-layout {
            display: grid;
            grid-template-columns: minmax(320px, 460px) minmax(400px, 1fr);
            gap: 16px;
            flex: 1 1 auto;
            min-height: 0;
            min-width: 0;
            align-items: stretch;
        }

        .chess-game-board-column {
            display: flex;
            flex-direction: column;
            gap: 14px;
            min-width: 0;
            min-height: 0;
            overflow-y: auto;
            overflow-x: hidden;
            padding-right: 4px;
            overscroll-behavior: contain;
        }

        .chess-player-rows {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .chess-player-strip {
            display: flex;
            align-items: center;
            gap: 10px;
            min-height: 62px;
            padding: 10px 12px;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: var(--surface-muted);
            transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
        }

        .chess-player-strip.is-turn {
            border-color: var(--accent-color);
            box-shadow: 0 0 0 3px var(--accent-soft);
            transform: translateY(-1px);
        }

        .chess-player-avatar {
            width: 42px;
            height: 42px;
            border-radius: 50%;
            object-fit: cover;
            flex-shrink: 0;
            border: 2px solid var(--surface-bg);
        }

        .chess-player-avatar.placeholder {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: var(--accent-soft);
            color: var(--accent-color);
            font-weight: 800;
            font-size: 0.82rem;
        }

        .chess-player-meta {
            min-width: 0;
            flex: 1;
        }

        .chess-player-top {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
        }

        .chess-player-name {
            font-size: 0.96rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .chess-player-role {
            margin-top: 4px;
            color: var(--text-secondary);
            font-size: 0.8rem;
        }

        .chess-player-clock {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 76px;
            min-height: 34px;
            padding: 6px 10px;
            border-radius: 12px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font-size: 0.86rem;
            font-weight: 800;
            font-variant-numeric: tabular-nums;
            letter-spacing: 0.02em;
            flex-shrink: 0;
        }

        .chess-player-clock.is-running {
            background: var(--accent-soft);
            color: var(--accent-color);
        }

        .chess-player-clock.is-low {
            background: rgba(239, 68, 68, 0.12);
            color: #dc2626;
        }

        .chess-board-shell {
            position: relative;
            width: min(100%, 420px, max(240px, calc(100dvh - 430px)));
            align-self: center;
        }

        .chess-board {
            display: grid;
            grid-template-columns: repeat(8, minmax(0, 1fr));
            width: 100%;
            aspect-ratio: 1 / 1;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            overflow: hidden;
            background: var(--surface-bg);
            box-shadow: 0 18px 34px rgba(15, 23, 42, 0.14);
        }

        .chess-square {
            position: relative;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            aspect-ratio: 1 / 1;
            border: none;
            padding: 0;
            background: transparent;
            cursor: pointer;
            transition: transform 0.16s ease, box-shadow 0.16s ease, filter 0.16s ease;
            user-select: none;
        }

        .chess-square.light {
            background: var(--chess-light-square-bg);
        }

        .chess-square.dark {
            background: var(--chess-dark-square-bg);
        }

        .chess-square.is-last-move {
            filter: brightness(1.04);
            box-shadow: inset 0 0 0 999px rgba(251, 191, 36, 0.12);
        }

        .chess-square.is-selected {
            box-shadow: inset 0 0 0 4px var(--accent-color);
            z-index: 1;
        }

        .chess-square.is-legal::after {
            content: '';
            position: absolute;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.38);
            box-shadow: 0 0 0 1px rgba(15, 23, 42, 0.18);
        }

        .chess-square.is-capture::after {
            width: 68%;
            height: 68%;
            background: transparent;
            border: 4px solid rgba(248, 250, 252, 0.76);
            box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.18);
        }

        .chess-square:disabled {
            cursor: default;
        }

        .chess-piece {
            position: relative;
            z-index: 1;
            font-size: clamp(1.35rem, 4.1vw, 2.3rem);
            line-height: 1;
            pointer-events: none;
            text-shadow: 0 2px 8px rgba(15, 23, 42, 0.18);
        }

        .chess-piece.white {
            color: #ffffff;
            text-shadow: 0 2px 8px rgba(15, 23, 42, 0.24), 0 0 2px rgba(15, 23, 42, 0.18);
        }

        .chess-piece.black {
            color: #0f172a;
            text-shadow: 0 2px 8px rgba(248, 250, 252, 0.18);
        }

        .chess-square-label,
        .chess-square-rank {
            position: absolute;
            font-size: 0.66rem;
            font-weight: 700;
            color: var(--chess-light-square-label);
            opacity: 0.72;
            pointer-events: none;
        }

        .chess-square-label {
            left: 8px;
            bottom: 7px;
        }

        .chess-square-rank {
            right: 8px;
            top: 7px;
        }

        .chess-square.dark .chess-square-label,
        .chess-square.dark .chess-square-rank {
            color: var(--chess-dark-square-label);
        }

        .chess-promotion-prompt {
            position: absolute;
            left: 12px;
            right: 12px;
            bottom: 12px;
            padding: 14px;
            border: 1px solid var(--border-subtle);
            border-radius: 18px;
            background: rgba(15, 23, 42, 0.9);
            box-shadow: 0 20px 36px rgba(2, 6, 23, 0.34);
            backdrop-filter: blur(18px);
            z-index: 3;
        }

        .chess-promotion-title {
            color: #f8fbff;
            font-size: 0.88rem;
            font-weight: 700;
            text-align: center;
        }

        .chess-promotion-actions {
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 10px;
            margin-top: 12px;
        }

        .chess-promotion-btn {
            min-height: 42px;
            border: 1px solid rgba(255, 255, 255, 0.14);
            border-radius: 14px;
            background: rgba(255, 255, 255, 0.08);
            color: #f8fbff;
            font: inherit;
            font-weight: 700;
            cursor: pointer;
        }

        .chess-promotion-btn:hover,
        .chess-promotion-btn:focus-visible {
            background: rgba(255, 255, 255, 0.16);
            outline: none;
        }

        .chess-game-lower {
            display: grid;
            grid-template-columns: minmax(0, 1fr);
            gap: 14px;
            align-items: start;
        }

        .chess-game-meta {
            display: flex;
            flex-direction: column;
            gap: 10px;
            min-height: 100%;
            padding: 14px 16px;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: var(--surface-muted);
        }

        .chess-turn-label {
            color: var(--text-primary);
            font-size: 0.96rem;
            font-weight: 800;
        }

        .chess-game-result {
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .chess-sidebar-column {
            display: flex;
            flex-direction: column;
            gap: 14px;
            min-height: 0;
        }

        .chess-move-log-shell {
            display: flex;
            flex-direction: column;
            min-height: 0;
            padding: 14px 16px;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: var(--surface-muted);
        }

        .chess-move-log-title {
            color: var(--text-primary);
            font-size: 0.86rem;
            font-weight: 800;
            letter-spacing: 0.04em;
            text-transform: uppercase;
        }

        .chess-move-log {
            display: flex;
            flex-direction: column;
            gap: 8px;
            max-height: min(34dvh, 360px);
            margin-top: 12px;
            overflow-y: auto;
            padding-right: 4px;
        }

        .chess-conversation-column {
            display: flex;
            flex-direction: column;
            min-width: 0;
            min-height: 0;
            overflow: hidden;
        }

        .chess-conversation-dock {
            display: flex;
            flex: 1 1 auto;
            min-width: 0;
            min-height: 0;
        }

        .chess-conversation-dock > .chat-container {
            display: flex !important;
            flex-direction: column;
            flex: 1 1 auto;
            width: 100%;
            min-width: 0;
            min-height: 0;
            height: 100%;
            border: 1px solid var(--border-subtle);
            border-radius: 24px;
            overflow: hidden;
            background: var(--surface-muted);
            box-shadow: 0 18px 34px rgba(15, 23, 42, 0.08);
        }

        .chess-conversation-empty {
            display: flex;
            align-items: center;
            justify-content: center;
            flex: 1 1 auto;
            min-height: 240px;
            padding: 24px;
            border: 1px dashed var(--border-subtle);
            border-radius: 24px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            color: var(--text-secondary);
            line-height: 1.6;
            text-align: center;
        }

        .chat-container.is-docked-in-chess-modal [data-action="game"] {
            display: none !important;
        }

        .chat-container.is-docked-in-chess-modal #mobileBackBtn {
            display: none !important;
        }

        .chat-container.is-docked-in-chess-modal .right-icons {
            display: none;
        }

        .chat-container.is-docked-in-chess-modal .chat-header {
            padding: 10px 12px;
        }

        .chat-container.is-docked-in-chess-modal .chat-box {
            padding: 14px 12px;
        }

        .chat-container.is-docked-in-chess-modal .chat-input {
            gap: 8px;
            padding: 8px;
        }

        .chess-chat-container-placeholder {
            flex: 1 1 auto;
            min-width: 0;
            min-height: 0;
            visibility: hidden;
            pointer-events: none;
        }

        .chess-move-log-empty {
            color: var(--text-secondary);
            font-size: 0.9rem;
        }

        .chess-move-row {
            display: grid;
            grid-template-columns: 38px minmax(0, 1fr) minmax(0, 1fr);
            gap: 10px;
            align-items: center;
            font-size: 0.88rem;
        }

        .chess-move-number {
            color: var(--text-secondary);
            font-weight: 700;
        }

        .chess-move-cell {
            min-height: 34px;
            padding: 8px 10px;
            border-radius: 12px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font-weight: 700;
            text-align: center;
        }

        .chess-move-cell.is-latest {
            background: var(--accent-soft);
            color: var(--accent-color);
        }

        .chess-chat-shell {
            display: flex;
            flex-direction: column;
            gap: 12px;
            min-height: 0;
            padding: 14px 16px;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: var(--surface-muted);
        }

        .chess-chat-log {
            display: flex;
            flex-direction: column;
            gap: 10px;
            max-height: 172px;
            overflow-y: auto;
            padding-right: 4px;
        }

        .chess-chat-empty {
            color: var(--text-secondary);
            font-size: 0.9rem;
            line-height: 1.5;
        }

        .chess-chat-message {
            display: flex;
            align-items: flex-end;
            gap: 8px;
        }

        .chess-chat-message.self {
            justify-content: flex-end;
        }

        .chess-chat-avatar {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            object-fit: cover;
            flex-shrink: 0;
        }

        .chess-chat-bubble {
            max-width: calc(100% - 36px);
            padding: 10px 12px;
            border-radius: 16px;
            background: var(--surface-bg);
            color: var(--text-primary);
            box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
        }

        .chess-chat-message.self .chess-chat-bubble {
            background: var(--accent-color);
            color: #ffffff;
        }

        .chess-chat-message.bot .chess-chat-bubble {
            background: rgba(45, 88, 245, 0.12);
        }

        .chess-chat-author {
            font-size: 0.72rem;
            font-weight: 800;
            color: inherit;
            opacity: 0.72;
            text-transform: uppercase;
            letter-spacing: 0.04em;
        }

        .chess-chat-text {
            margin-top: 4px;
            line-height: 1.45;
            white-space: pre-wrap;
            word-break: break-word;
        }

        .chess-chat-compose {
            display: flex;
            gap: 10px;
            align-items: flex-end;
        }

        .chess-chat-input {
            width: 100%;
            min-height: 42px;
            padding: 11px 14px;
            border: 1px solid var(--border-subtle);
            border-radius: 16px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font: inherit;
        }

        .chess-chat-input:focus {
            border-color: var(--accent-color);
            outline: none;
            box-shadow: 0 0 0 3px var(--accent-soft);
        }

        .chess-chat-send {
            min-width: 82px;
        }

        .chess-result-popup {
            position: absolute;
            inset: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 24px;
            background: rgba(15, 23, 42, 0.52);
            backdrop-filter: blur(14px);
            z-index: 6;
        }

        .chess-result-popup[hidden] {
            display: none !important;
        }

        .chess-result-popup-card {
            width: min(420px, 100%);
            padding: 28px 24px 22px;
            border: 1px solid rgba(255, 255, 255, 0.14);
            border-radius: 28px;
            background:
                radial-gradient(circle at top center, rgba(96, 165, 250, 0.22) 0%, transparent 44%),
                linear-gradient(180deg, rgba(15, 23, 42, 0.98) 0%, rgba(15, 23, 42, 0.94) 100%);
            color: #f8fbff;
            box-shadow: 0 30px 60px rgba(2, 6, 23, 0.42);
            text-align: center;
        }

        .chess-result-popup-kicker {
            margin: 0;
            color: rgba(191, 219, 254, 0.92);
            font-size: 0.78rem;
            font-weight: 800;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .chess-result-popup-summary {
            margin-top: 12px;
            font-size: 1.28rem;
            font-weight: 800;
            line-height: 1.4;
        }

        .chess-result-popup-reason {
            margin-top: 10px;
            color: rgba(248, 251, 255, 0.82);
            line-height: 1.45;
        }

        .chess-result-popup-actions {
            display: flex;
            justify-content: center;
            margin-top: 20px;
        }

        .chess-game-actions {
            justify-content: space-between;
            align-items: center;
            padding: 16px 22px 20px;
            border-top: 1px solid var(--border-subtle);
        }

        .chess-game-footer-left {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .chess-game-footer-right {
            display: flex;
            align-items: center;
            gap: 10px;
            margin-left: auto;
        }

        .chess-resign-btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .sketchoff-shell {
            display: flex;
            flex-direction: column;
            gap: 14px;
            min-height: 100%;
        }

        .sketchoff-hero {
            padding: 16px 18px;
            border-radius: 22px;
            background:
                radial-gradient(circle at top left, rgba(249, 115, 22, 0.18) 0%, transparent 44%),
                linear-gradient(180deg, rgba(255, 247, 237, 0.94) 0%, rgba(255, 255, 255, 0.98) 100%);
            border: 1px solid rgba(249, 115, 22, 0.18);
        }

        .sketchoff-kicker {
            margin: 0 0 6px;
            font-size: 0.78rem;
            font-weight: 800;
            letter-spacing: 0.14em;
            text-transform: uppercase;
            color: #c2410c;
        }

        .sketchoff-prompt {
            margin: 0;
            font-size: clamp(1.2rem, 2vw, 1.7rem);
            font-weight: 900;
            color: #111827;
            line-height: 1.2;
        }

        .sketchoff-subcopy {
            margin: 8px 0 0;
            color: #7c2d12;
            line-height: 1.45;
        }

        .sketchoff-canvas-card,
        .sketchoff-results-grid,
        .sketchoff-status-card {
            border: 1px solid var(--border-subtle);
            border-radius: 24px;
            background: var(--surface-bg);
            box-shadow: 0 16px 34px rgba(15, 23, 42, 0.08);
        }

        .sketchoff-canvas-card {
            padding: 16px;
        }

        .sketchoff-toolbar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            margin-bottom: 12px;
            flex-wrap: wrap;
        }

        .sketchoff-toolbar-left,
        .sketchoff-toolbar-right {
            display: flex;
            align-items: center;
            gap: 10px;
            flex-wrap: wrap;
        }

        .sketchoff-countdown {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            min-height: 38px;
            padding: 8px 12px;
            border-radius: 999px;
            background: rgba(249, 115, 22, 0.12);
            color: #9a3412;
            font-weight: 800;
        }

        .sketchoff-countdown.is-low {
            background: rgba(220, 38, 38, 0.12);
            color: #b91c1c;
        }

        .sketchoff-brush {
            width: 130px;
        }

        .sketchoff-color-control {
            display: inline-flex;
            align-items: center;
            justify-content: center;
        }

        .sketchoff-color {
            width: 42px;
            height: 42px;
            padding: 0;
            border: none;
            border-radius: 14px;
            background: transparent;
            cursor: pointer;
        }

        .sketchoff-color::-webkit-color-swatch-wrapper {
            padding: 0;
        }

        .sketchoff-color::-webkit-color-swatch,
        .sketchoff-color::-moz-color-swatch {
            border: none;
            border-radius: 14px;
            box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.14);
        }

        .sketchoff-canvas-frame {
            position: relative;
            aspect-ratio: 1 / 1;
            border-radius: 22px;
            overflow: hidden;
            background:
                linear-gradient(0deg, rgba(15, 23, 42, 0.04) 1px, transparent 1px),
                linear-gradient(90deg, rgba(15, 23, 42, 0.04) 1px, transparent 1px),
                linear-gradient(180deg, #ffffff 0%, #fff7ed 100%);
            background-size: 36px 36px, 36px 36px, 100% 100%;
            border: 1px solid rgba(249, 115, 22, 0.12);
        }

        .sketchoff-canvas {
            width: 100%;
            height: 100%;
            display: block;
            touch-action: none;
            cursor: crosshair;
        }

        .sketchoff-canvas[aria-disabled="true"] {
            cursor: default;
        }

        .sketchoff-submission-note {
            margin: 12px 0 0;
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .sketchoff-status-card {
            padding: 16px 18px;
        }

        .sketchoff-status-title {
            margin: 0;
            font-weight: 800;
            color: var(--text-primary);
        }

        .sketchoff-status-copy {
            margin: 8px 0 0;
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .sketchoff-results-grid {
            display: flex;
            flex-direction: column;
            gap: 12px;
            padding: 14px;
        }

        .sketchoff-result-card {
            border-radius: 20px;
            background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(248, 250, 252, 0.98) 100%);
            border: 1px solid rgba(15, 23, 42, 0.08);
            padding: 12px;
            display: flex;
            flex-direction: column;
            gap: 10px;
            min-width: 0;
        }

        .sketchoff-result-card.is-reference {
            background:
                radial-gradient(circle at top left, rgba(96, 165, 250, 0.14) 0%, transparent 44%),
                linear-gradient(180deg, rgba(248, 250, 252, 0.98) 0%, rgba(241, 245, 249, 0.98) 100%);
        }

        .sketchoff-result-card.is-winner {
            border-color: rgba(249, 115, 22, 0.32);
            box-shadow: 0 18px 30px rgba(249, 115, 22, 0.12);
        }

        .sketchoff-result-top {
            display: flex;
            align-items: flex-start;
            justify-content: space-between;
            gap: 10px;
        }

        .sketchoff-result-name {
            font-weight: 800;
            color: var(--text-primary);
        }

        .sketchoff-result-badge {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-height: 30px;
            padding: 6px 10px;
            border-radius: 999px;
            background: rgba(15, 23, 42, 0.08);
            color: var(--text-primary);
            font-weight: 800;
            white-space: nowrap;
        }

        .sketchoff-result-preview {
            width: 100%;
            aspect-ratio: 1 / 1;
            object-fit: contain;
            border-radius: 18px;
            background: #fff;
            border: 1px solid rgba(15, 23, 42, 0.08);
        }

        .sketchoff-result-meta {
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .chess-game-body.is-sketchoff-layout {
            overflow-y: auto;
            overflow-x: hidden;
            -webkit-overflow-scrolling: touch;
        }

        .chess-game-layout.is-sketchoff-layout {
            display: flex;
            flex-direction: column;
            align-items: start;
            gap: 16px;
            overflow: visible;
        }

        .chess-game-board-column.is-sketchoff-layout {
            order: 0;
            flex: 0 0 auto;
            overflow: visible;
            padding-right: 0;
        }

        .chess-conversation-column.is-sketchoff-layout {
            order: 1;
            flex: 0 0 auto;
            width: 100%;
            min-height: min(56dvh, 680px);
        }

        .chess-conversation-column.is-sketchoff-layout .chess-conversation-dock {
            width: 100%;
        }

        .chess-conversation-column.is-sketchoff-layout .chess-conversation-dock > .chat-container,
        .chess-conversation-column.is-sketchoff-layout .chess-conversation-empty {
            min-height: min(56dvh, 680px);
            height: min(56dvh, 680px);
        }

        .chess-board-shell.is-sketchoff-shell {
            width: 100%;
            max-width: none;
            align-self: stretch;
        }

        .chess-board.is-sketchoff-board {
            aspect-ratio: auto;
            border: none;
            box-shadow: none;
            background: transparent;
            overflow: visible;
        }

        .sketchoff-shell {
            width: 100%;
            max-width: none;
            margin: 0 auto;
        }

        @media (max-width: 1180px) {
            .chess-game-modal-dialog {
                width: min(calc(100vw - 24px), 960px);
            }

            .chess-game-layout {
                grid-template-columns: minmax(0, 1fr);
                gap: 14px;
                overflow-y: auto;
                overflow-x: hidden;
            }

            .chess-game-board-column {
                padding-right: 0;
                overflow: visible;
            }

            .chess-conversation-column {
                min-height: min(54dvh, 620px);
            }

            .chess-conversation-dock > .chat-container,
            .chess-conversation-empty {
                min-height: min(54dvh, 620px);
            }
        }

        @media (max-width: 760px) {
            .chess-setup-modal-dialog {
                width: min(calc(100vw - 16px), 440px);
            }

            .chess-setup-body {
                padding: 18px 16px 18px;
            }

            #chessSetupModal .friend-request-modal-actions {
                padding: 16px;
            }

            .chess-setup-opponents {
                grid-template-columns: minmax(0, 1fr);
            }

            .chess-game-modal-dialog {
                width: min(calc(100vw - 16px), 440px);
                max-height: min(98dvh, 820px);
            }

            .chess-game-body {
                padding: 16px;
                overflow-y: auto;
                overflow-x: hidden;
                -webkit-overflow-scrolling: touch;
            }

            .chess-game-layout {
                grid-template-columns: minmax(0, 1fr);
                gap: 12px;
                align-items: start;
                min-height: auto;
                overflow: visible;
            }

            .chess-game-board-column {
                padding-right: 0;
                overflow: visible;
                min-height: auto;
            }

            .chess-board-shell.is-sketchoff-shell {
                width: min(100%, 360px);
            }

            .chess-board-shell {
                width: min(100%, 320px, max(220px, calc(100dvh - 420px)));
            }

            .chess-game-lower {
                gap: 12px;
            }

            .chess-move-log {
                max-height: 180px;
            }

            .chess-conversation-column {
                min-height: 0;
            }

            .chess-conversation-dock > .chat-container,
            .chess-conversation-empty {
                border-radius: 20px;
                min-height: 320px;
                height: min(58dvh, 520px);
            }

            .chess-conversation-column.is-sketchoff-layout {
                min-height: 0;
            }

            .chess-conversation-column.is-sketchoff-layout .chess-conversation-dock > .chat-container,
            .chess-conversation-column.is-sketchoff-layout .chess-conversation-empty {
                min-height: 320px;
                height: min(58dvh, 520px);
            }

            .sketchoff-toolbar-right {
                width: 100%;
                justify-content: flex-start;
            }

            .chess-game-actions {
                padding: 14px 16px 18px;
            }

            .chess-result-popup {
                padding: 16px;
            }

            .chess-result-popup-card {
                padding: 24px 18px 18px;
            }
        }

        @media (max-height: 780px) {
            .chess-game-modal-dialog {
                max-height: min(calc(100dvh - 12px), 760px);
            }

            .chess-player-strip {
                min-height: 56px;
            }

            .chess-board-shell {
                width: min(100%, 300px, max(220px, calc(100dvh - 430px)));
            }

            .chess-piece {
                font-size: clamp(1.2rem, 3.8vw, 2rem);
            }

            .chess-move-log,
            .chess-chat-log {
                max-height: 96px;
            }
        }

        .gif-modal-body {
            display: flex;
            flex-direction: column;
            gap: 18px;
            padding: 22px 28px 28px;
            min-height: 0;
            flex: 1 1 auto;
            overflow: hidden;
        }

        .gif-category-toolbar {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        #gifSearchShell[hidden],
        .gif-category-toolbar[hidden],
        .gif-category-list[hidden],
        .gif-search-results[hidden] {
            display: none !important;
        }

        .gif-category-back {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            border: 1px solid var(--border-subtle);
            border-radius: 999px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font: inherit;
            font-weight: 700;
            padding: 9px 14px;
            cursor: pointer;
        }

        .gif-category-back:hover,
        .gif-category-back:focus-visible {
            background: var(--surface-muted);
            outline: none;
        }

        .gif-category-title {
            font-size: 1rem;
            font-weight: 800;
            color: var(--text-primary);
        }

        .gif-category-list {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 12px;
            flex: 1 1 auto;
            min-height: 0;
            overflow-y: auto;
        }

        .gif-category-card {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            gap: 8px;
            width: 100%;
            padding: 18px 18px 16px;
            border: 1px solid var(--border-subtle);
            border-radius: 18px;
            background:
                radial-gradient(circle at top right, rgba(45, 88, 245, 0.12) 0%, transparent 40%),
                linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            color: var(--text-primary);
            text-align: left;
            cursor: pointer;
            box-shadow: 0 12px 26px rgba(15, 23, 42, 0.08);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .gif-category-card:hover,
        .gif-category-card:focus-visible {
            transform: translateY(-2px);
            box-shadow: 0 16px 30px rgba(15, 23, 42, 0.14);
            border-color: rgba(45, 88, 245, 0.28);
            outline: none;
        }

        .gif-category-card i {
            font-size: 1.2rem;
            color: var(--accent-color);
        }

        .gif-category-card-title {
            font-size: 0.98rem;
            font-weight: 800;
        }

        .gif-category-card-note {
            font-size: 0.82rem;
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .gif-search-results {
            flex: 1 1 auto;
            min-height: 240px;
            min-height: 0;
            overflow-y: auto;
        }

        .gif-search-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 12px;
        }

        .gif-search-card {
            border: none;
            padding: 0;
            background: transparent;
            border-radius: 18px;
            cursor: pointer;
            overflow: hidden;
            position: relative;
            min-height: 140px;
            box-shadow: 0 12px 26px rgba(15, 23, 42, 0.12);
            transition: transform 0.18s ease, box-shadow 0.18s ease;
        }

        .gif-search-card:hover,
        .gif-search-card:focus-visible {
            transform: translateY(-2px);
            box-shadow: 0 16px 30px rgba(15, 23, 42, 0.18);
            outline: none;
        }

        .gif-search-card.is-loading {
            cursor: progress;
            opacity: 0.72;
        }

        .gif-search-card.is-selected {
            transform: translateY(-2px);
            box-shadow: 0 0 0 3px var(--accent-color), 0 18px 32px var(--accent-shadow-strong);
        }

        .gif-search-card.is-selected::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            border: 3px solid var(--accent-color);
            box-sizing: border-box;
            pointer-events: none;
        }

        .gif-search-card img {
            display: block;
            width: 100%;
            height: 100%;
            min-height: 140px;
            max-height: 220px;
            object-fit: cover;
            background: linear-gradient(135deg, #e2e8f0 0%, #cbd5e1 100%);
        }

        .gif-search-card-badge {
            position: absolute;
            top: 10px;
            right: 10px;
            min-width: 28px;
            height: 28px;
            padding: 0 8px;
            border-radius: 50%;
            background: var(--accent-color);
            color: var(--accent-contrast);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 8px 18px rgba(15, 23, 42, 0.18);
            opacity: 0;
            transform: scale(0.8);
            transition: opacity 0.18s ease, transform 0.18s ease;
            pointer-events: none;
            font-size: 0.78rem;
            font-weight: 800;
        }

        .gif-search-card.is-selected .gif-search-card-badge {
            opacity: 1;
            transform: scale(1);
        }

        .gif-search-card-caption {
            position: absolute;
            left: 0;
            right: 0;
            bottom: 0;
            padding: 12px 12px 10px;
            background: linear-gradient(180deg, transparent 0%, rgba(15, 23, 42, 0.82) 100%);
            color: #ffffff;
            font-size: 0.82rem;
            font-weight: 600;
            text-align: left;
        }

        .gif-search-loading {
            display: flex;
            align-items: center;
            justify-content: center;
            min-height: 220px;
            color: var(--text-secondary);
            font-size: 0.95rem;
        }

        .gif-selection-bar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            padding: 16px 20px 18px;
            border-top: 1px solid var(--border-subtle);
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            box-shadow: 0 -8px 20px rgba(15, 23, 42, 0.08);
        }

        .gif-selection-bar[hidden] {
            display: none !important;
        }

        .gif-selection-bar-main {
            min-width: 0;
            flex: 1;
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .gif-selection-bar-label-wrap {
            display: flex;
            flex-direction: column;
            gap: 4px;
            flex-shrink: 0;
        }

        .gif-selection-bar-label {
            font-size: 0.76rem;
            font-weight: 800;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: var(--text-secondary);
        }

        .gif-selection-bar-note {
            font-size: 0.82rem;
            color: var(--text-secondary);
            white-space: nowrap;
        }

        .gif-selection-bar-count {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 26px;
            padding: 4px 8px;
            border-radius: 999px;
            background: var(--accent-soft);
            color: var(--accent-color);
            font-size: 0.78rem;
            font-weight: 700;
        }

        .gif-selection-strip {
            display: flex;
            align-items: center;
            gap: 8px;
            min-width: 0;
            overflow-x: auto;
            padding-bottom: 2px;
        }

        .gif-selection-chip {
            width: 40px;
            height: 40px;
            border-radius: 12px;
            overflow: hidden;
            border: 1px solid var(--accent-soft-strong);
            box-shadow: 0 8px 16px rgba(15, 23, 42, 0.14);
            background: var(--surface-bg);
            flex-shrink: 0;
        }

        .gif-selection-chip.is-first {
            box-shadow: 0 0 0 2px var(--accent-color), 0 8px 16px rgba(15, 23, 42, 0.14);
        }

        .gif-selection-chip img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .gif-selection-bar-actions {
            display: flex;
            align-items: center;
            gap: 8px;
            flex-shrink: 0;
        }

        .gif-selection-bar-actions .settings-action-btn {
            margin-top: 0;
            padding: 10px 14px;
            border-radius: 10px;
            box-shadow: none;
        }

        @media (max-width: 600px) {
            .gif-category-list {
                grid-template-columns: minmax(0, 1fr);
            }

            .gif-selection-bar {
                flex-direction: column;
                align-items: stretch;
            }

            .gif-selection-bar-main {
                width: 100%;
            }

            .gif-selection-bar-actions {
                justify-content: flex-end;
            }
        }

        #userInfoModal .friend-request-modal-dialog {
            width: min(400px, calc(100vw - 32px));
            max-height: min(76dvh, 720px);
            gap: 0;
            padding: 0;
            overflow: hidden;
        }

        .user-info-modal-content {
            max-height: min(76dvh, 720px);
        }

        .poll-modal-body {
            display: flex;
            flex-direction: column;
            gap: 18px;
            padding: 22px 28px 28px;
            overflow-y: auto;
        }

        .poll-modal-section {
            display: flex;
            flex-direction: column;
            gap: 14px;
            padding: 18px;
            border: 1px solid var(--border-subtle);
            border-radius: 24px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28);
        }

        .poll-section-head {
            display: flex;
            align-items: flex-start;
            justify-content: space-between;
            gap: 12px;
        }

        .poll-section-head h3 {
            margin: 0;
            font-size: 1rem;
            color: var(--text-primary);
        }

        .poll-section-head p {
            margin: 6px 0 0;
            font-size: 0.85rem;
            line-height: 1.5;
            color: var(--text-secondary);
        }

        .poll-form-group {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .poll-form-label {
            font-size: 0.78rem;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            font-weight: 800;
            color: var(--text-secondary);
        }

        .poll-form-input {
            width: 100%;
            padding: 14px 16px;
            border: 1px solid var(--border-strong);
            border-radius: 18px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font-size: 0.96rem;
            font-family: inherit;
            transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
            box-sizing: border-box;
        }

        .poll-form-input:focus {
            outline: none;
            border-color: var(--accent-color);
            box-shadow: 0 0 0 4px var(--accent-soft);
            transform: translateY(-1px);
        }

        .poll-form-hint {
            margin: 0;
            font-size: 0.84rem;
            line-height: 1.5;
            color: var(--text-secondary);
        }

        .poll-options-container {
            display: flex;
            flex-direction: column;
            gap: 14px;
        }

        .poll-option-item {
            padding: 18px;
            border: 1px solid var(--border-subtle);
            border-radius: 22px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            display: flex;
            flex-direction: column;
            gap: 14px;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24);
            transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
        }

        .poll-option-item:focus-within {
            border-color: var(--accent-color);
            box-shadow: 0 16px 32px var(--accent-shadow), inset 0 1px 0 rgba(255, 255, 255, 0.24);
            transform: translateY(-1px);
        }

        .poll-option-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 14px;
        }

        .poll-option-number {
            font-size: 0.92rem;
            font-weight: 700;
            color: var(--text-primary);
        }

        .poll-option-remove {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 12px;
            border: 1px solid rgba(220, 38, 38, 0.18);
            border-radius: 999px;
            background: rgba(220, 38, 38, 0.08);
            color: #dc2626;
            font-size: 0.82rem;
            font-weight: 700;
            cursor: pointer;
            transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
        }

        .poll-option-remove:hover {
            background: rgba(220, 38, 38, 0.14);
            border-color: rgba(220, 38, 38, 0.28);
            transform: translateY(-1px);
        }

        .poll-option-image-upload {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .poll-option-image-label {
            font-size: 0.82rem;
            font-weight: 600;
            color: var(--text-secondary);
        }

        .poll-option-image-input {
            width: 100%;
            padding: 10px 12px;
            border: 1px dashed var(--border-strong);
            border-radius: 16px;
            background: var(--surface-bg);
            color: var(--text-secondary);
            font-size: 0.88rem;
            box-sizing: border-box;
        }

        .poll-option-image-input::file-selector-button {
            margin-right: 12px;
            padding: 9px 14px;
            border: 1px solid var(--accent-soft-strong);
            border-radius: 999px;
            background: var(--accent-soft);
            color: var(--accent-color);
            font: inherit;
            font-weight: 700;
            cursor: pointer;
            transition: background 0.18s ease, transform 0.18s ease;
        }

        .poll-option-image-input::file-selector-button:hover {
            background: var(--accent-soft-strong);
            transform: translateY(-1px);
        }

        .poll-add-option-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            padding: 14px 18px;
            border: 1px solid var(--accent-soft-strong);
            border-radius: 18px;
            background: var(--accent-soft);
            color: var(--accent-color);
            font-size: 0.94rem;
            font-weight: 800;
            cursor: pointer;
            transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3);
        }

        .poll-add-option-btn:hover {
            background: var(--accent-soft-strong);
            border-color: var(--accent-color);
            transform: translateY(-1px);
            box-shadow: 0 16px 28px var(--accent-shadow);
        }

        .poll-end-options {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .poll-end-option {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 14px 16px;
            border: 1px solid transparent;
            border-radius: 18px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font-weight: 700;
            transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
        }

        .poll-end-option:has(.poll-checkbox:checked) {
            border-color: var(--accent-color);
            background: var(--accent-soft);
            box-shadow: 0 16px 28px var(--accent-shadow);
            transform: translateY(-1px);
        }

        .poll-checkbox {
            width: 18px;
            height: 18px;
            cursor: pointer;
            accent-color: var(--accent-color);
            flex-shrink: 0;
        }

        .poll-date-picker-container,
        .poll-responses-picker-container {
            margin: 0;
        }

        .poll-or-divider {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            font-size: 0.78rem;
            letter-spacing: 0.12em;
            text-transform: uppercase;
            font-weight: 800;
            color: var(--text-muted);
            margin: 2px 0;
        }

        .poll-or-divider::before,
        .poll-or-divider::after {
            content: '';
            flex: 1;
            height: 1px;
            background: var(--border-subtle);
        }

        .poll-modal-actions {
            display: flex;
            justify-content: flex-end;
            gap: 12px;
            padding: 18px 28px 28px;
            border-top: 1px solid var(--border-subtle);
            background: linear-gradient(180deg, rgba(255, 255, 255, 0) 0%, var(--surface-bg) 20%);
        }

        /* ── Poll Message Styles ── */
        .message.poll-message .message-bubble,
        .message.self.poll-message .message-bubble {
            padding: 0;
            overflow: hidden;
            max-width: min(460px, 82vw);
            border: 1px solid var(--border-subtle);
            border-radius: 24px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            color: var(--text-primary);
            box-shadow: 0 18px 40px rgba(15, 23, 42, 0.12);
        }

        .poll-container {
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .poll-title {
            padding: 18px 18px 14px;
            font-size: 1.06rem;
            font-weight: 800;
            color: var(--text-primary);
            border-bottom: 1px solid var(--border-subtle);
        }

        .poll-options-list {
            display: flex;
            flex-direction: column;
            padding: 14px;
            gap: 12px;
        }

        .poll-option {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 14px 16px;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            cursor: pointer;
            transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
            position: relative;
            overflow: hidden;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24);
        }

        .poll-option:hover {
            border-color: var(--accent-soft-strong);
            transform: translateY(-1px);
            box-shadow: 0 16px 32px rgba(15, 23, 42, 0.08);
        }

        .poll-option.selected {
            border-color: var(--accent-color);
            box-shadow: 0 18px 36px var(--accent-shadow);
        }

        .poll-option.disabled {
            cursor: not-allowed;
            opacity: 0.8;
            box-shadow: none;
            transform: none;
        }

        .poll-option-bar {
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            background: linear-gradient(90deg, var(--accent-soft-strong) 0%, var(--accent-soft) 100%);
            opacity: 0.72;
            transition: width 0.3s ease;
            pointer-events: none;
        }

        .poll-option-indicator {
            position: relative;
            width: 32px;
            height: 32px;
            border-radius: 50%;
            border: 1px solid var(--border-strong);
            background: var(--surface-bg);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
            z-index: 1;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28);
            transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease, transform 0.18s ease;
        }

        .poll-option-indicator::before {
            content: '';
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: transparent;
            transition: background 0.18s ease, transform 0.18s ease;
        }

        .poll-option.selected .poll-option-indicator {
            border-color: var(--accent-color);
            background: var(--accent-color);
            color: var(--accent-contrast);
            transform: scale(1.02);
        }

        .poll-option.selected .poll-option-indicator::before {
            width: auto;
            height: auto;
            border-radius: 0;
            background: transparent;
            content: '\f00c';
            font-family: 'Font Awesome 7 Free';
            font-weight: 900;
            font-size: 0.82rem;
            color: var(--accent-contrast);
        }

        .poll-option-image {
            width: 52px;
            height: 52px;
            border-radius: 16px;
            object-fit: cover;
            flex-shrink: 0;
            position: relative;
            z-index: 1;
            box-shadow: 0 12px 24px rgba(15, 23, 42, 0.14);
        }

        .poll-option-content {
            flex: 1;
            min-width: 0;
            display: flex;
            flex-direction: column;
            gap: 8px;
            position: relative;
            z-index: 1;
        }

        .poll-option-text {
            font-size: 0.94rem;
            font-weight: 700;
            color: var(--text-primary);
            word-wrap: break-word;
            line-height: 1.4;
        }

        .poll-option-stats {
            display: flex;
            align-items: center;
            gap: 10px;
            flex-wrap: wrap;
            font-size: 0.82rem;
        }

        .poll-option-percentage {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            padding: 5px 10px;
            border-radius: 999px;
            background: rgba(255, 255, 255, 0.74);
            color: var(--accent-color);
            font-weight: 800;
        }

        .poll-option-count {
            border: none;
            padding: 0;
            background: transparent;
            color: var(--text-secondary);
            font: inherit;
            font-weight: 700;
            cursor: pointer;
            display: inline-flex;
            align-items: center;
            gap: 6px;
            text-decoration: none;
        }

        .poll-option-count:hover,
        .poll-option-count:focus-visible {
            color: var(--accent-color);
            outline: none;
        }

        .poll-info {
            padding: 0 18px 18px;
            display: flex;
            flex-direction: column;
            gap: 8px;
            font-size: 0.85rem;
            color: var(--text-secondary);
        }

        .poll-info-row {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 10px 12px;
            border-radius: 16px;
            background: rgba(255, 255, 255, 0.64);
            border: 1px solid rgba(226, 232, 240, 0.72);
        }

        .poll-info-row i {
            width: 14px;
            text-align: center;
            color: var(--accent-color);
        }

        .poll-info-row.live {
            border-color: var(--accent-soft-strong);
            background: var(--accent-soft);
            color: var(--text-primary);
            font-weight: 700;
        }

        .poll-total-responses {
            font-weight: 700;
            color: var(--text-primary);
        }

        .poll-actions {
            padding: 0 18px 18px;
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }

        .poll-action-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            padding: 11px 14px;
            border: 1px solid var(--border-subtle);
            border-radius: 16px;
            background: var(--surface-bg);
            color: var(--text-primary);
            font-size: 0.88rem;
            font-weight: 700;
            cursor: pointer;
            transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28);
        }

        .poll-action-btn:hover {
            background: var(--surface-hover);
            border-color: var(--accent-soft-strong);
            transform: translateY(-1px);
            box-shadow: 0 14px 24px rgba(15, 23, 42, 0.1);
        }

        .poll-action-btn.danger {
            color: #dc2626;
        }

        .poll-action-btn.danger:hover {
            background: rgba(220, 38, 38, 0.08);
            border-color: rgba(220, 38, 38, 0.32);
        }

        .poll-ended-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 12px;
            background: #64748b;
            color: #fff;
            border-radius: 999px;
            font-size: 0.82rem;
            font-weight: 800;
        }

        /* Poll Responses Modal */
        .poll-responses-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
            padding: 20px 28px 28px;
            max-height: 420px;
            overflow-y: auto;
        }

        .poll-responses-empty {
            padding: 24px 18px;
            border: 1px dashed var(--border-strong);
            border-radius: 22px;
            background: var(--surface-soft);
            color: var(--text-secondary);
            text-align: center;
        }

        .poll-response-item {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 14px 16px;
            border: 1px solid var(--border-subtle);
            border-radius: 20px;
            background: linear-gradient(180deg, var(--surface-bg) 0%, var(--surface-muted) 100%);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24);
        }

        .poll-response-avatar-wrap {
            position: relative;
            width: 46px;
            height: 46px;
            flex-shrink: 0;
        }

        .poll-response-avatar {
            width: 46px;
            height: 46px;
            border-radius: 16px;
            object-fit: cover;
            background: var(--surface-muted);
        }

        .poll-response-status {
            position: absolute;
            right: -1px;
            bottom: -1px;
            width: 13px;
            height: 13px;
            border-radius: 50%;
            border: 2px solid var(--surface-bg);
            background: #6b7280;
        }

        .poll-response-status.online {
            background: #22c55e;
        }

        .poll-response-info {
            flex: 1;
            min-width: 0;
        }

        .poll-response-name {
            font-size: 0.94rem;
            font-weight: 700;
            color: var(--text-primary);
        }

        .poll-response-username {
            font-size: 0.83rem;
            color: var(--text-secondary);
        }

        @media (max-width: 768px) {
            .poll-modal-dialog,
            #pollResponsesModal .friend-request-modal-dialog {
                width: min(100vw - 20px, 700px);
                border-radius: 28px;
            }

            #pollModal .friend-request-modal-head,
            #pollResponsesModal .friend-request-modal-head,
            .poll-modal-body,
            .poll-modal-actions,
            .poll-responses-list {
                padding-left: 20px;
                padding-right: 20px;
            }

            .poll-modal-actions {
                flex-direction: column-reverse;
            }

            .poll-modal-actions .settings-action-btn {
                width: 100%;
            }

            .poll-option {
                align-items: flex-start;
            }
        }

        /* Toast animations */
        @keyframes slideUp {
            from {
                opacity: 0;
                transform: translateX(-50%) translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateX(-50%) translateY(0);
            }
        }

        @keyframes slideDown {
            from {
                opacity: 1;
                transform: translateX(-50%) translateY(0);
            }
            to {
                opacity: 0;
                transform: translateX(-50%) translateY(20px);
            }
        }

        .friend-request-result-name {
          margin: 0;
          color: var(--text-primary);
          font-weight: 800;
          font-size: 1rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .friend-request-result-username {
          margin: 4px 0 0;
          color: var(--text-secondary);
          font-size: 0.9rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .friend-request-result-action {
          border: none;
          border-radius: 16px;
          background: var(--accent-color);
          color: var(--accent-contrast);
          padding: 10px 14px;
          min-width: 118px;
          font: inherit;
          font-weight: 800;
          cursor: pointer;
          transition: background 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
          box-shadow: 0 14px 28px var(--accent-shadow);
        }

        .friend-request-result-action:hover,
        .friend-request-result-action:focus-visible {
          background: var(--accent-hover);
          transform: translateY(-1px);
          outline: none;
        }

        .friend-request-result-action:disabled {
          cursor: default;
          opacity: 0.72;
          transform: none;
          box-shadow: none;
        }

        /* Professional settings menu */
        #accountMenu {
          display: none;
          position: fixed;
          inset: 0;
          background: #f8fafc;
          z-index: 2000;
          overflow: hidden;
        }

        #accountMenu .close-btn {
          position: absolute;
          top: 22px;
          right: 22px;
          width: 42px;
          height: 42px;
          border: none;
          border-radius: 14px;
          background: rgba(255, 255, 255, 0.92);
          color: #0f172a;
          cursor: pointer;
          font-size: 1.1rem;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          box-shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
        }

        .settings-shell {
          height: 100%;
          display: grid;
          grid-template-columns: 280px minmax(0, 1fr);
        }

        .settings-sidebar {
          background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
          border-right: 1px solid #e2e8f0;
          padding: 92px 18px 24px;
          overflow-y: auto;
          scrollbar-width: none;
          -ms-overflow-style: none;
        }

        .settings-sidebar-head {
          margin-bottom: 22px;
          padding: 0 8px;
        }

        .settings-sidebar-kicker {
          display: flex;
          align-items: center;
          gap: 10px;
          font-family: 'Raleway', sans-serif;
          font-weight: 800;
          font-size: 1.08rem;
          color: #0f172a;
        }

        .settings-sidebar-kicker i {
          width: 34px;
          height: 34px;
          border-radius: 12px;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          background: #e8efff;
          color: #2d58f5;
        }

        .settings-sidebar-subtitle {
          margin: 12px 0 0;
          color: #64748b;
          line-height: 1.55;
          font-size: 0.93rem;
        }

        .settings-nav-list {
          display: flex;
          flex-direction: column;
          gap: 8px;
        }

        .settings-nav-scrollbar {
          display: none;
          width: 100%;
          min-height: 28px;
          margin-top: 8px;
          padding: 0;
          border: 0;
          accent-color: var(--accent-color);
          cursor: pointer;
          -webkit-appearance: none;
          appearance: none;
          background: transparent;
        }

        .settings-nav-scrollbar::-webkit-slider-runnable-track {
          height: 6px;
          border-radius: 999px;
          background: rgba(148, 163, 184, 0.32);
        }

        .settings-nav-scrollbar::-webkit-slider-thumb {
          -webkit-appearance: none;
          appearance: none;
          width: 16px;
          height: 16px;
          margin-top: -5px;
          border: none;
          border-radius: 50%;
          background: var(--accent-color);
          box-shadow: 0 4px 12px var(--accent-shadow);
        }

        .settings-nav-scrollbar::-moz-range-track {
          height: 6px;
          border: none;
          border-radius: 999px;
          background: rgba(148, 163, 184, 0.32);
        }

        .settings-nav-scrollbar::-moz-range-thumb {
          width: 16px;
          height: 16px;
          border: none;
          border-radius: 50%;
          background: var(--accent-color);
          box-shadow: 0 4px 12px var(--accent-shadow);
        }

        .settings-nav-scrollbar:focus-visible {
          outline: none;
        }

        .settings-nav-scrollbar:focus-visible::-webkit-slider-thumb,
        .settings-nav-scrollbar:focus-visible::-moz-range-thumb {
          box-shadow: 0 0 0 3px var(--accent-soft-strong), 0 4px 12px var(--accent-shadow);
        }

        .settings-nav-scrollbar:disabled::-webkit-slider-runnable-track,
        .settings-nav-scrollbar:disabled::-moz-range-track {
          background: rgba(148, 163, 184, 0.2);
        }

        .settings-nav-scrollbar:disabled::-webkit-slider-thumb,
        .settings-nav-scrollbar:disabled::-moz-range-thumb {
          background: #94a3b8;
          box-shadow: none;
        }

        .settings-nav-scrollbar:disabled {
          cursor: default;
          opacity: 0.45;
        }

        .settings-nav-item {
          width: 100%;
          border: none;
          background: transparent;
          border-radius: 16px;
          padding: 12px 14px;
          display: flex;
          align-items: center;
          gap: 12px;
          cursor: pointer;
          color: #334155;
          font: inherit;
          font-weight: 700;
          text-align: left;
          transition: background-color 0.18s ease, color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
        }

        .settings-nav-item i {
          width: 18px;
          text-align: center;
          color: #2d58f5;
        }

        .settings-nav-item:hover {
          background: #eef4ff;
          color: #0f172a;
          transform: translateX(2px);
        }

        .settings-nav-item.active {
          background: #2d58f5;
          color: var(--accent-contrast);
          box-shadow: 0 12px 24px rgba(45, 88, 245, 0.22);
        }

        .settings-nav-item.active i {
          color: var(--accent-contrast);
        }

        .settings-content {
          overflow-y: auto;
          padding: 92px 32px 32px;
          scrollbar-width: none;
          -ms-overflow-style: none;
        }

        .settings-sidebar::-webkit-scrollbar,
        .settings-content::-webkit-scrollbar {
          width: 0;
          height: 0;
          display: none;
        }

        .settings-nav-list {
          scrollbar-width: none;
          scrollbar-color: var(--accent-color) rgba(148, 163, 184, 0.22);
          -ms-overflow-style: auto;
        }

        .chat-header-status-dot,
        .contact-info-status-dot,
        .message-presence-dot,
        .online-indicator {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          gap: 2px;
          overflow: hidden;
          box-sizing: border-box;
          transition: width 0.22s ease, height 0.22s ease, border-radius 0.22s ease, background-color 0.22s ease, transform 0.22s ease, padding 0.22s ease;
        }

        .chat-header-status-dot span,
        .contact-info-status-dot span,
        .message-presence-dot span,
        .online-indicator span {
          width: 2px;
          height: 2px;
          border-radius: 50%;
          background: #ffffff;
          opacity: 0;
          transform: translateY(1px) scale(0.7);
          transition: opacity 0.16s ease, transform 0.16s ease;
        }

        .chat-header-status-dot.typing,
        .contact-info-status-dot.typing,
        .message-presence-dot.typing,
        .online-indicator.typing {
          width: var(--presence-typing-width, 18px);
          min-width: var(--presence-typing-width, 18px);
          height: var(--presence-typing-height, 10px);
          padding: 0 3px;
          border-radius: 999px;
          background: #22c55e;
          transform: translateY(-1px);
        }

        .chat-header-status-dot.typing span,
        .contact-info-status-dot.typing span,
        .message-presence-dot.typing span,
        .online-indicator.typing span {
          opacity: 1;
          transform: translateY(0) scale(1);
          animation: typingDotFloat 0.95s ease-in-out infinite;
        }

        .chat-header-status-dot.typing span:nth-child(2),
        .contact-info-status-dot.typing span:nth-child(2),
        .message-presence-dot.typing span:nth-child(2),
        .online-indicator.typing span:nth-child(2) {
          animation-delay: 0.14s;
        }

        .chat-header-status-dot.typing span:nth-child(3),
        .contact-info-status-dot.typing span:nth-child(3),
        .message-presence-dot.typing span:nth-child(3),
        .online-indicator.typing span:nth-child(3) {
          animation-delay: 0.28s;
        }

        .contact .online-indicator {
          width: 12px !important;
          min-width: 12px !important;
          height: 12px !important;
          min-height: 12px !important;
        }

        .contact .online-indicator.typing {
          width: var(--presence-typing-width, 20px) !important;
          min-width: var(--presence-typing-width, 20px) !important;
          height: var(--presence-typing-height, 12px) !important;
          min-height: var(--presence-typing-height, 12px) !important;
          padding: 0 3px;
          border-radius: 999px;
          background: #22c55e;
          transform: translateY(-1px);
        }

        .settings-panel {
          display: none;
          max-width: 980px;
        }

        .settings-panel.active {
          display: block;
        }

        .settings-panel-header {
          margin-bottom: 24px;
        }

        .settings-eyebrow {
          margin: 0 0 10px;
          display: inline-flex;
          align-items: center;
          gap: 10px;
          font-family: 'Raleway', sans-serif;
          font-size: 0.9rem;
          font-weight: 800;
          color: #2d58f5;
          text-transform: uppercase;
          letter-spacing: 0.08em;
        }

        .settings-panel-header h2 {
          margin: 0;
          font-family: 'Raleway', sans-serif;
          font-size: 2rem;
          line-height: 1.1;
          color: #0f172a;
        }

        .settings-panel-description {
          margin: 10px 0 0;
          color: #64748b;
          font-size: 0.98rem;
          line-height: 1.65;
          max-width: 720px;
        }

        .settings-device-note {
          margin: 0 0 18px;
          display: inline-flex;
          align-items: center;
          gap: 8px;
          padding: 9px 12px;
          border-radius: 999px;
          background: #eef4ff;
          color: #3657c8;
          font-size: 0.88rem;
          font-weight: 700;
        }

        .settings-grid {
          display: grid;
          gap: 18px;
        }

        .settings-card {
          background: #ffffff;
          border: 1px solid #e2e8f0;
          border-radius: 22px;
          padding: 22px;
          box-shadow: 0 18px 45px rgba(15, 23, 42, 0.05);
        }

        .settings-card-title {
          display: flex;
          align-items: center;
          gap: 12px;
          margin: 0;
          font-family: 'Raleway', sans-serif;
          font-size: 1.04rem;
          font-weight: 800;
          color: #0f172a;
        }

        .settings-card-icon {
          width: 38px;
          height: 38px;
          border-radius: 14px;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          background: #eef4ff;
          color: #2d58f5;
          flex-shrink: 0;
        }

        .settings-card-copy {
          margin: 12px 0 0;
          color: #64748b;
          line-height: 1.6;
          font-size: 0.95rem;
        }

        .settings-hero {
          display: flex;
          align-items: center;
          gap: 18px;
        }

        .settings-hero-avatar {
          width: 92px;
          height: 92px;
          border-radius: 28px;
          object-fit: cover;
          display: block;
          flex-shrink: 0;
          box-shadow: 0 16px 36px rgba(45, 88, 245, 0.16);
        }

        .settings-hero-copy {
          min-width: 0;
        }

        .settings-hero-copy h3 {
          margin: 0;
          font-family: 'Raleway', sans-serif;
          font-size: 1.6rem;
          font-weight: 800;
          color: #0f172a;
        }

        .settings-hero-copy p {
          margin: 8px 0 0;
        }

        .settings-meta-line {
          display: flex;
          align-items: center;
          gap: 9px;
          color: #64748b;
          font-size: 0.95rem;
          line-height: 1.5;
        }

        .settings-info-list {
          display: grid;
          gap: 14px;
          margin-top: 18px;
        }

        .settings-info-item {
          display: flex;
          align-items: flex-start;
          gap: 12px;
          padding: 14px 16px;
          border-radius: 16px;
          background: #f8fafc;
          border: 1px solid #edf2f7;
        }

        .settings-info-item i {
          width: 18px;
          color: #2d58f5;
          text-align: center;
          margin-top: 2px;
        }

        .settings-info-label {
          font-size: 0.82rem;
          font-weight: 700;
          letter-spacing: 0.04em;
          text-transform: uppercase;
          color: #94a3b8;
        }

        .settings-info-value {
          margin-top: 4px;
          color: #0f172a;
          font-weight: 700;
          word-break: break-word;
        }

        .username-container {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 16px;
          flex-wrap: wrap;
          margin-top: 18px;
        }

        .account-identity {
          min-width: 0;
        }

        .account-username {
          margin-top: 6px;
          color: #6b7280;
          font-size: 0.95rem;
          line-height: 1.4;
          word-break: break-word;
        }

        #editUsernameLink {
          cursor: pointer;
          color: #2d58f5;
          text-decoration: none;
          font-weight: 700;
          display: inline-flex;
          align-items: center;
          gap: 8px;
          padding: 10px 14px;
          border-radius: 12px;
          background: #eef4ff;
        }

        #editUsernameLink:hover {
          background: #e2ebff;
        }

        .account-field {
          margin-top: 0;
          max-width: none;
        }

        .account-field h3 {
          margin: 0 0 10px;
          font-family: 'Raleway', sans-serif;
          font-size: 1rem;
          font-weight: 800;
          color: #0f172a;
        }

        .account-field textarea,
        .account-field input[type="text"],
        .settings-select {
          width: 100%;
          padding: 12px 14px;
          border: 1px solid #cbd5e1;
          border-radius: 12px;
          font: inherit;
          background: #ffffff;
          color: #0f172a;
          box-sizing: border-box;
        }

        .account-field textarea {
          min-height: 112px;
          resize: vertical;
        }

        .account-help-text {
          margin-top: 8px;
          color: #64748b;
          font-size: 0.85rem;
          line-height: 1.55;
        }

        .account-save-btn,
        .settings-action-btn {
          margin-top: 12px;
          padding: 11px 18px;
          border: none;
          border-radius: 12px;
          background: #2d58f5;
          color: var(--accent-contrast);
          cursor: pointer;
          font: inherit;
          font-weight: 700;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          gap: 9px;
          text-decoration: none;
          transition: transform 0.16s ease, box-shadow 0.16s ease, background-color 0.16s ease;
          box-shadow: 0 14px 28px rgba(45, 88, 245, 0.22);
        }

        .account-save-btn:hover,
        .settings-action-btn:hover {
          transform: translateY(-1px);
        }

        .settings-action-btn.secondary {
          background: #eef2f7;
          color: #334155;
          box-shadow: none;
        }

        .settings-action-btn.danger {
          background: #ef4444;
          box-shadow: 0 14px 28px rgba(239, 68, 68, 0.2);
        }

        .settings-color-actions {
          display: flex;
          align-items: center;
          gap: 10px;
          flex-wrap: wrap;
          justify-content: flex-end;
        }

        .settings-color-chip {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          padding: 9px 12px;
          border-radius: 12px;
          border: 1px solid var(--border-subtle);
          background: var(--surface-bg);
          color: var(--text-primary);
          font-weight: 700;
          font-size: 0.9rem;
        }

        .settings-color-chip-swatch {
          width: 16px;
          height: 16px;
          border-radius: 50%;
          border: 2px solid rgba(255, 255, 255, 0.9);
          box-shadow: 0 0 0 1px rgba(15, 23, 42, 0.12);
          background: var(--accent-color);
          flex-shrink: 0;
        }

        .settings-color-trigger {
          margin-top: 0;
        }

        .settings-row {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 16px;
          padding: 16px 0;
          border-top: 1px solid #edf2f7;
        }

        .settings-row:first-child {
          border-top: none;
          padding-top: 0;
        }

        .settings-row:last-child {
          padding-bottom: 0;
        }
        #settingMessageSplitSelfSideRow[hidden],
        #settingMessageSingleSideRow[hidden] {
          display: none !important;
        }
        html[data-message-position-mode="split"] #settingMessageSplitSelfSideRow {
          display: flex;
        }
        html[data-message-position-mode="split"] #settingMessageSingleSideRow {
          display: none !important;
        }
        html[data-message-position-mode="single"] #settingMessageSplitSelfSideRow {
          display: none !important;
        }
        html[data-message-position-mode="single"] #settingMessageSingleSideRow {
          display: flex;
        }

        .settings-row-main {
          display: flex;
          align-items: flex-start;
          gap: 14px;
          min-width: 0;
        }

        body,
        html {
          background: var(--page-bg);
          color: var(--text-primary);
        }

        header,
        .search-ui button,
        #searchResults button,
        .chat-input .send-btn,
        .account-save-btn,
        .settings-action-btn:not(.secondary):not(.danger),
        .settings-nav-item.active,
        .settings-switch input:checked + .settings-switch-slider,
        .emoji-picker-tab.active,
        .voice-message-duration::before {
          background: var(--accent-color);
          border-color: var(--accent-color);
        }

        header,
        .search-ui button,
        #searchResults button,
        .chat-input .send-btn,
        .account-save-btn,
        .settings-action-btn:not(.secondary):not(.danger),
        .settings-nav-item.active,
        .settings-nav-item.active i,
        .emoji-picker-tab.active,
        .friend-request-popup .accept-btn,
        .message.self .message-bubble,
        .message.self .username {
          color: var(--accent-contrast);
        }

        .search-ui button:hover,
        #searchResults button:hover,
        .chat-input .send-btn:hover,
        .settings-action-btn:not(.secondary):not(.danger):hover {
          background: var(--accent-hover);
        }

        .account-save-btn,
        .settings-action-btn:not(.secondary):not(.danger),
        .settings-nav-item.active {
          box-shadow: 0 14px 28px var(--accent-shadow);
        }

        .sidebar,
        .settings-sidebar {
          background: var(--sidebar-bg);
          border-color: var(--border-subtle);
        }

        .contact,
        .chat-header,
        .contact-info-panel,
        .dropdown-menu,
        .settings-card,
        .emoji-picker,
        .settings-content {
          background: var(--surface-bg);
          border-color: var(--border-subtle);
        }

        .chat-box,
        .typing-row,
        .attachment-preview-row,
        .chat-input,
        #accountMenu {
          background: var(--surface-muted);
        }

        .chat-input input,
        .search-ui input,
        .account-field textarea,
        .account-field input[type="text"],
        .settings-select {
          background: var(--surface-bg);
          border-color: var(--border-strong);
          color: var(--text-primary);
        }

        .sidebar h4,
        .contact-name,
        .settings-panel-header h2,
        .settings-card-title,
        .settings-row-label,
        .settings-info-value,
        .contact-info-display-name,
        .contact-info-text,
        #currentChatUser,
        .dropdown-menu button,
        .account-field h3 {
          color: var(--text-primary);
        }

        .contact-preview,
        .account-username,
        .settings-row-help,
        .settings-panel-description,
        .settings-card-copy,
        .settings-sidebar-subtitle,
        .account-help-text,
        .contact-info-username,
        .typing-indicator,
        .settings-info-label,
        .contact-info-label,
        .contact-info-text,
        .message .username,
        .emoji-picker-empty {
          color: var(--text-secondary);
        }

        .settings-sidebar-kicker i,
        .settings-card-icon,
        .settings-info-item i,
        .settings-nav-item i,
        .settings-eyebrow,
        .settings-dropdown-btn .dropdown-action-icon,
        .group-settings-trigger .dropdown-action-icon,
        .call-icon-desktop,
        .call-icon-mobile,
        .info-icon-btn,
        #editUsernameLink,
        .chat-input .attachment-btn,
        .chat-input .voice-btn,
        .voice-message-play,
        .attachment-preview-file-icon,
        .attachment-file i {
          color: var(--accent-color);
        }

        .settings-sidebar-kicker i,
        .settings-card-icon,
        #editUsernameLink,
        .chat-input .attachment-btn,
        .chat-input .voice-btn,
        .voice-message-play,
        .attachment-preview-file-icon,
        .attachment-file,
        .settings-nav-item:hover,
        .emoji-picker-emoji:hover,
        .emoji-picker-tab,
        .settings-device-note {
          background: var(--accent-soft);
        }

        .chat-input .attachment-btn:hover,
        .chat-input .voice-btn:hover,
        #editUsernameLink:hover {
          background: var(--accent-soft-strong);
        }

        .chat-input-field .emoji-btn {
          color: var(--text-secondary);
          background: transparent;
        }

        .chat-input-field .emoji-btn:hover,
        .chat-input-field .emoji-btn.open {
          color: var(--accent-color);
          background: transparent;
        }

        .call-icon-desktop:hover,
        .call-icon-mobile:hover {
          background: none;
        }

                .call-icon-desktop,
                .call-icon-mobile {
                        position: relative;
                        z-index: 2200;
                        pointer-events: auto;
                }

        .block-icon-btn {
          color: #ef4444;
          background: none;
          border: none;
        }

        .block-icon-btn:hover,
        .block-icon-btn:focus-visible,
        .block-icon-btn.is-blocked {
          background: none;
          border: none;
        }

        .settings-device-note,
        .emoji-picker-tab,
        .settings-row-main .settings-card-icon,
        .voice-message-play,
        .attachment-file,
        #editUsernameLink {
          border-color: transparent;
        }

        .message-bubble {
          background: var(--message-bubble-bg);
          color: var(--message-bubble-text);
        }

        .message.self .message-bubble {
          background: var(--accent-color);
          color: var(--accent-contrast);
        }

        .message.local-ai-assistant .message-bubble {
          background: linear-gradient(135deg, var(--surface-bg) 0%, var(--accent-soft) 100%);
          color: var(--text-primary);
        }

        .message.self .username,
        .message.self .attachment-size,
        .message.self .attachment-caption {
          color: rgba(255, 255, 255, 0.84);
        }

        .voice-message-bar {
          background: var(--voice-bar-bg);
        }

        .voice-message-bar.played {
          background: var(--accent-color);
        }

        /* Unheard voice messages have all bars blue */
        .voice-message-player.unheard .voice-message-bar:not(.played) {
          background: var(--accent-color);
        }

        .message.self .voice-message-bar {
          background: var(--voice-bar-bg-self);
        }

        .message.self .voice-message-bar.played {
          background: #ffffff;
        }

        /* Self messages don't show unheard state */
        .message.self .voice-message-player.unheard .voice-message-bar:not(.played) {
          background: var(--voice-bar-bg-self);
        }

        .voice-message-duration {
          color: var(--text-secondary);
          flex: 0 0 64px;
          min-width: 64px;
          text-align: right;
          white-space: nowrap;
          font-variant-numeric: tabular-nums;
        }

        .emoji-picker {
          box-shadow: 0 18px 40px rgba(15, 23, 42, 0.14);
        }

        .settings-row-main .settings-card-icon {
          width: 36px;
          height: 36px;
          border-radius: 12px;
        }

        .settings-row-copy {
          min-width: 0;
        }

        .settings-row-label {
          color: #0f172a;
          font-weight: 700;
          line-height: 1.35;
        }

        .settings-row-help {
          margin-top: 4px;
          color: #64748b;
          font-size: 0.9rem;
          line-height: 1.55;
        }

        .settings-static-value {
          color: #0f172a;
          font-weight: 700;
          font-size: 0.95rem;
          white-space: nowrap;
        }

        .settings-row .settings-select {
          width: 116px;
          min-width: 116px;
          flex-shrink: 0;
        }

        .settings-switch {
          position: relative;
          width: 50px;
          height: 30px;
          flex-shrink: 0;
        }

        .settings-switch input {
          position: absolute;
          inset: 0;
          opacity: 0;
          cursor: pointer;
          margin: 0;
        }

        .settings-switch-slider {
          position: absolute;
          inset: 0;
          background: #cbd5e1;
          border-radius: 999px;
          transition: background-color 0.18s ease;
        }

        .settings-switch-slider::after {
          content: '';
          position: absolute;
          top: 3px;
          left: 3px;
          width: 24px;
          height: 24px;
          border-radius: 50%;
          background: #ffffff;
          box-shadow: 0 2px 8px rgba(15, 23, 42, 0.18);
          transition: transform 0.18s ease;
        }

        .settings-switch input:checked + .settings-switch-slider {
          background: #2d58f5;
        }

        .settings-switch input:checked + .settings-switch-slider::after {
          transform: translateX(20px);
        }

        .settings-actions {
          display: flex;
          flex-wrap: wrap;
          gap: 12px;
          margin-top: 16px;
        }

        .settings-actions form {
          margin: 0;
        }

        .tutorial-settings-status {
          display: flex;
          align-items: flex-start;
          gap: 14px;
          margin-top: 18px;
          padding: 16px 18px;
          border-radius: 18px;
          border: 1px solid var(--border-subtle);
          background: var(--surface-muted);
        }

        .tutorial-settings-status-icon {
          width: 42px;
          height: 42px;
          border-radius: 14px;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          flex-shrink: 0;
          font-size: 1rem;
          background: rgba(148, 163, 184, 0.14);
          color: var(--text-secondary);
        }

        .tutorial-settings-status-copy {
          min-width: 0;
        }

        .tutorial-settings-status-label {
          color: var(--text-primary);
          font-weight: 800;
          line-height: 1.3;
        }

        .tutorial-settings-status-detail {
          margin-top: 4px;
          color: var(--text-secondary);
          font-size: 0.92rem;
          line-height: 1.55;
        }

        .tutorial-settings-status[data-state="completed"] .tutorial-settings-status-icon {
          background: rgba(34, 197, 94, 0.14);
          color: #16a34a;
        }

        .tutorial-settings-status[data-state="skipped"] .tutorial-settings-status-icon {
          background: rgba(239, 68, 68, 0.14);
          color: #dc2626;
        }

        .tutorial-settings-status[data-state="delayed"] .tutorial-settings-status-icon {
          background: var(--accent-soft);
          color: var(--accent-color);
        }

        .tutorial-settings-status[data-state="not_started"] .tutorial-settings-status-icon {
          background: rgba(148, 163, 184, 0.14);
          color: var(--text-secondary);
        }

        .settings-form-inline {
          display: flex;
          flex-wrap: wrap;
          gap: 12px;
          align-items: center;
          margin-top: 16px;
        }

        .settings-form-inline input[type="file"] {
          max-width: 100%;
        }

        #profilePicForm .file-picker-input:not(.profile-pic-file-input) {
          position: fixed;
          left: -9999px;
          top: 0;
        }

        .account-file-picker-btn {
          position: relative;
          overflow: hidden;
        }

        .account-file-picker-btn .profile-pic-file-input {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          margin: 0;
          opacity: 0;
          cursor: pointer;
          clip: auto;
          clip-path: none;
          white-space: normal;
        }

        @media (max-width: 900px) {
          #accountMenu {
            overflow: hidden;
          }

          #accountMenu .close-btn {
            top: 16px;
            right: 16px;
          }

          .settings-shell {
            grid-template-columns: 1fr;
            height: 100dvh;
            min-height: 100dvh;
            min-width: 0;
            overflow: hidden;
          }

          .settings-sidebar {
            padding: 18px 68px 14px 16px;
            border-right: none;
            border-bottom: 1px solid #e2e8f0;
            overflow: visible;
            flex-shrink: 0;
            min-width: 0;
          }

          .settings-sidebar-head {
            margin-bottom: 14px;
          }

          .settings-sidebar-subtitle {
            display: none;
          }

          .settings-nav-list {
            flex-direction: row;
            overflow-x: auto;
            overflow-y: hidden;
            flex-wrap: nowrap;
            width: 100%;
            max-width: 100%;
            min-width: 0;
            padding-bottom: 10px;
            scrollbar-width: thin;
            scrollbar-gutter: stable both-edges;
            -ms-overflow-style: auto;
            -webkit-overflow-scrolling: touch;
            overscroll-behavior-x: contain;
            touch-action: pan-x;
            scrollbar-color: var(--accent-color) rgba(148, 163, 184, 0.28);
          }

          .settings-nav-list::-webkit-scrollbar {
            display: block;
            height: 8px;
          }

          .settings-nav-list::-webkit-scrollbar-track {
            background: rgba(148, 163, 184, 0.22);
            border-radius: 999px;
          }

          .settings-nav-list::-webkit-scrollbar-thumb {
            background: var(--accent-color);
            border-radius: 999px;
          }

          .settings-nav-scrollbar {
            display: none;
          }

          .settings-nav-item {
            flex: 0 0 auto;
            width: auto;
            min-width: max-content;
            padding: 10px 12px;
            gap: 8px;
          }

          .settings-content {
            padding: 20px 16px 28px;
            overflow-y: auto;
            min-height: 0;
            -webkit-overflow-scrolling: touch;
          }

          .settings-panel-header h2 {
            font-size: 1.6rem;
          }

          .settings-hero {
            flex-direction: column;
            align-items: flex-start;
          }

          .settings-row {
            flex-direction: column;
            align-items: stretch;
          }

          .settings-color-actions {
            justify-content: flex-start;
          }

          .settings-static-value,
          .settings-select,
          .settings-switch {
            align-self: flex-start;
          }

          .settings-row .settings-select {
            width: 100%;
            min-width: 0;
          }
        }
		
        .mobile-back {
            display:none;
            background:none;
            border:none;
            color:#2d58f5;
            font-size:1.4rem;
            line-height:1;
            padding:0;
            cursor:pointer;
            margin-right:6px;
            width:40px;
            min-width:40px;
            height:40px;
            min-height:40px;
            border-radius:12px;
            flex-shrink:0;
            position:relative;
            z-index:20;
            touch-action:manipulation;
        }
        .mobile-back::before {
            content:none;
            display:none;
        }
        .mobile-back[data-mode="close"]::before {
            content:none;
            display:none;
        }
        .mobile-back i {
            font-size:1.35rem;
            line-height:1;
            pointer-events:none;
        }
        @media (max-width:768px){
            .chat-input.composer-actions-collapsed .composer-action-buttons {
                display:none;
            }

            .chat-input.composer-actions-collapsed .composer-actions-back-btn {
                display:inline-flex;
            }

            .mobile-back {
                display:inline-flex;
                align-items:center;
                justify-content:center;
                position:absolute;
                left:10px;
                top:50%;
                transform:translateY(-50%);
                pointer-events:auto;
            }

            .mobile-back:active {
                background: rgba(45, 88, 245, 0.08);
            }
        }
		
        @media (max-width:768px) {
            .chat-header {
                position: sticky;
                top: 0;
                z-index: 25;
                padding-left: 58px;
            }

            .chat-container {
                display:none;   /* hide chat until user picks someone */
            }
            .sidebar {
                left:0 !important; /* contacts visible by default */
                box-shadow:none;
                position:relative;
            }
        }
        
        .contact-text {
          display: flex;
          flex-direction: column;
          overflow: hidden;
        }

        .contact-preview {
          font-size: 0.8em;
          color: var(--text-secondary);
          display: flex;
          align-items: center;
          gap: 6px;
          overflow: hidden;
          white-space: nowrap;
          text-overflow: ellipsis;
          line-height: 1.25;
          max-width: 100%;
          min-width: 0;
        }

        .contact-preview-main {
          flex: 1 1 auto;
          min-width: 0;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .contact-preview-separator,
        .contact-preview-time {
          flex: 0 0 auto;
          white-space: nowrap;
        }

        .contact-preview-main,
        .contact-preview-separator,
        .contact-preview-time {
          color: inherit;
        }

        @media (min-width: 769px) {
            .scrolls-grid {
                grid-template-columns: repeat(7, minmax(0, 1fr));
            }

            .sidebar.is-contact-rail {
                width: 94px;
                padding: 0 10px 14px;
            }

            .sidebar.is-contact-rail .sidebar-sticky-shell,
            .sidebar.is-contact-rail .sidebar-footer-note,
            .sidebar.is-contact-rail .archived-contacts-empty,
            .sidebar.is-contact-rail .sidebar-history-panel,
            .sidebar.is-contact-rail .contacts-sort-row,
            .sidebar.is-contact-rail .sidebar-contact-tabs {
                display: none !important;
            }

            .sidebar.is-contact-rail #contactsList {
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 8px;
                padding: 14px 0 10px;
            }

            .sidebar.is-contact-rail .contact {
                max-width: 68px;
                margin-bottom: 0;
                padding: 8px 6px;
                display: flex;
                align-items: center;
                justify-content: center;
                border-radius: 18px;
            }

            .sidebar.is-contact-rail .contact-text,
            .sidebar.is-contact-rail .contact-more-btn,
            .sidebar.is-contact-rail .contact-restore-btn {
                display: none !important;
            }

            .sidebar.is-contact-rail .contact-img-wrapper {
                margin: 0;
            }
        }

        .unread-badge {
            background: #2d58f5;
            color: white;
            min-width: 22px;
            height: 22px;
            border-radius: 50%;
            font-size: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-left: auto;
            font-weight: 600;
        }

        .contact.unread .contact-preview {
            font-weight: 700;
            color: #000;
        }

        .unread-attention-cue {
            position: fixed;
            z-index: 100003;
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 8px 10px;
            border-radius: 999px;
            background: rgba(15, 23, 42, 0.92);
            color: #ffffff;
            box-shadow: 0 18px 34px rgba(15, 23, 42, 0.26);
            backdrop-filter: blur(14px);
            pointer-events: none;
        }

        .unread-attention-avatars {
            display: inline-flex;
            align-items: center;
        }

        .unread-attention-avatar,
        .unread-attention-overflow {
            position: relative;
            width: 34px;
            height: 34px;
            border-radius: 50%;
            border: 2px solid rgba(15, 23, 42, 0.92);
            background: rgba(255, 255, 255, 0.16);
            margin-left: -8px;
            overflow: hidden;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 0.72rem;
            font-weight: 700;
        }

        .unread-attention-avatar:first-child,
        .unread-attention-overflow:first-child {
            margin-left: 0;
        }

        .unread-attention-avatar img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .unread-attention-avatar-status {
            position: absolute;
            right: 1px;
            bottom: 1px;
            width: 9px;
            height: 9px;
            border-radius: 50%;
            background: #64748b;
            border: 2px solid rgba(15, 23, 42, 0.92);
        }

        .unread-attention-avatar-status.is-online {
            background: #22c55e;
        }

        .unread-attention-count {
            min-width: 34px;
            height: 34px;
            padding: 0 10px;
            border-radius: 999px;
            background: var(--accent-color);
            color: var(--accent-contrast);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 0.82rem;
            font-weight: 800;
            box-shadow: 0 0 0 3px var(--accent-soft);
        }

        .unread-attention-arrow {
            font-size: 1.1rem;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            color: #ffffff;
            animation-duration: 0.9s;
            animation-timing-function: ease-in-out;
            animation-iteration-count: infinite;
        }

        .unread-attention-cue.is-left .unread-attention-arrow {
            animation-name: unreadAttentionArrowPulseLeft;
        }

        .unread-attention-cue.is-right .unread-attention-arrow {
            animation-name: unreadAttentionArrowPulseRight;
        }

        @keyframes unreadAttentionArrowPulseRight {
            0%, 100% {
                transform: translateX(0);
            }
            50% {
                transform: translateX(4px);
            }
        }

        @keyframes unreadAttentionArrowPulseLeft {
            0%, 100% {
                transform: translateX(0);
            }
            50% {
                transform: translateX(-4px);
            }
        }
        
        .unread-divider {
            display: flex;
            align-items: center;
            margin: 20px 0;
            width: 100%;
            gap: 12px;
        }

        .unread-divider::before,
        .unread-divider::after {
            content: '';
            flex: 1;
            border-bottom: 2px solid #2d58f5;
        }

        .unread-divider-shell {
            display: flex;
            flex-direction: column;
            gap: 10px;
            min-width: min(100%, 320px);
            max-width: min(100%, 560px);
            padding: 12px 16px;
            border-radius: 18px;
            border: 1px solid rgba(45, 88, 245, 0.18);
            background: linear-gradient(180deg, rgba(255, 255, 255, 0.96) 0%, rgba(244, 247, 250, 0.98) 100%);
            box-shadow: 0 10px 30px rgba(45, 88, 245, 0.08);
        }

        .unread-divider-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
        }

        .unread-divider-label {
            flex: 1;
            min-width: 0;
            color: #2d58f5;
            font-weight: bold;
            font-size: 0.8em;
            text-transform: none;
            letter-spacing: 0.02em;
            line-height: 1.4;
        }

        .unread-divider-summary-btn {
            width: 34px;
            height: 34px;
            border: none;
            border-radius: 12px;
            background: linear-gradient(135deg, rgba(45, 88, 245, 0.14) 0%, rgba(45, 88, 245, 0.22) 100%);
            color: #2d58f5;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 1.05rem;
            font-weight: 700;
            cursor: pointer;
            transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease, opacity 0.18s ease;
            box-shadow: 0 8px 18px rgba(45, 88, 245, 0.12);
        }

        .unread-divider-summary-btn:hover,
        .unread-divider-summary-btn:focus-visible {
            transform: translateY(-1px) scale(1.03);
            background: linear-gradient(135deg, rgba(45, 88, 245, 0.18) 0%, rgba(45, 88, 245, 0.28) 100%);
            box-shadow: 0 10px 20px rgba(45, 88, 245, 0.16);
            outline: none;
        }

        .unread-divider-summary-btn:disabled {
            cursor: wait;
            opacity: 0.68;
            transform: none;
            box-shadow: none;
        }

        .unread-divider-body {
            display: none;
            padding-top: 2px;
        }

        .unread-divider.is-loading .unread-divider-body,
        .unread-divider.is-summarized .unread-divider-body,
        .unread-divider.has-error .unread-divider-body {
            display: block;
        }

        .unread-divider-body .transcribe-loading-container {
            gap: 8px;
            padding: 6px 0 2px;
        }

        .unread-divider-body .transcribe-loading-line {
            height: 10px;
            border-radius: 999px;
        }

        .unread-divider-summary-text {
            margin: 0;
            color: var(--text-primary);
            font-size: 0.95rem;
            line-height: 1.65;
            white-space: pre-wrap;
        }

        .unread-divider-error-text {
            margin: 0;
            color: #b42318;
            font-size: 0.9rem;
            line-height: 1.55;
        }

        .unread-divider-meta {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            color: var(--text-secondary);
            font-size: 0.8rem;
            text-transform: none;
            letter-spacing: normal;
        }
        
        #call-ui {
            background: linear-gradient(180deg, rgba(20,20,20,0.9) 0%, rgba(0,0,0,1) 100%) !important;
            backdrop-filter: blur(10px);
            width: 100vw;
            height: var(--qt-app-height, 100vh);
            min-height: var(--qt-app-height, 100vh);
            max-width: none;
            max-height: none;
            box-sizing: border-box;
            z-index: 100001 !important;
            transition:
                top 0.2s ease,
                right 0.2s ease,
                left 0.2s ease,
                width 0.2s ease,
                height 0.2s ease,
                padding 0.2s ease,
                border-radius 0.2s ease,
                box-shadow 0.2s ease;
        }
        .call-ui-topbar {
            position: absolute;
            top: 24px;
            left: 24px;
            right: 24px;
            z-index: 5;
            display: flex;
            justify-content: flex-start;
            pointer-events: none;
        }
        .call-ui-topbar > * {
            pointer-events: auto;
        }
        #call-close-btn {
            margin-left: auto;
        }
        .call-ui-icon-btn {
            width: 52px;
            height: 52px;
            border: 1px solid rgba(255,255,255,0.14);
            border-radius: 999px;
            background: rgba(15, 23, 42, 0.72);
            color: #fff;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 1.05rem;
            cursor: pointer;
            box-shadow: 0 18px 34px rgba(0,0,0,0.28);
            backdrop-filter: blur(14px);
            transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
        }
        .call-ui-icon-btn:hover,
        .call-ui-icon-btn:focus-visible {
            transform: translateY(-1px);
            background: rgba(30, 41, 59, 0.88);
            border-color: rgba(255,255,255,0.24);
            outline: none;
        }
        #call-ui.is-minimized {
            width: min(220px, 32vw) !important;
            height: auto !important;
            max-width: 220px;
            min-height: 0 !important;
            aspect-ratio: 16 / 9;
            box-sizing: border-box;
            padding: 12px !important;
            border-radius: 20px !important;
            align-items: stretch !important;
            justify-content: flex-end !important;
            box-shadow: 0 30px 70px rgba(2, 6, 23, 0.45);
            border: 1px solid rgba(255,255,255,0.12);
            cursor: grab;
            user-select: none;
            touch-action: none;
        }
        #call-ui.is-minimized:active {
            cursor: grabbing;
        }
        #call-ui.is-minimized::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            background: linear-gradient(180deg, rgba(2, 6, 23, 0.18) 0%, rgba(2, 6, 23, 0.72) 100%);
            pointer-events: none;
            z-index: 1;
        }
        #call-ui.is-minimized .call-ui-topbar {
            display: none;
        }
        #call-ui.is-minimized .call-hero {
            width: 100%;
            text-align: left !important;
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            justify-content: flex-end;
            gap: 4px;
            margin-top: auto;
            z-index: 3;
            pointer-events: none;
        }
        #call-ui.is-minimized #call-image {
            width: 42px !important;
            height: 42px !important;
            margin: 0 0 8px !important;
            border-width: 2px !important;
        }
        #call-ui.is-minimized #call-username {
            font-size: 0.88rem !important;
            max-width: 100%;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        #call-ui.is-minimized #call-status {
            font-size: 0.72rem !important;
            margin-top: 0 !important;
            letter-spacing: 0.02em !important;
            max-width: 100%;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            color: rgba(226,232,240,0.88) !important;
        }
        #call-ui.is-minimized #callStopwatch {
            margin-top: 2px;
            font-size: 0.7rem;
            color: rgba(255,255,255,0.76);
        }
        #call-ui.is-minimized #incoming-actions,
        #call-ui.is-minimized #in-call-controls,
        #call-ui.is-minimized #group-call-participants,
        #call-ui.is-minimized #callVideoLocalPreview {
            display: none !important;
        }
        #call-ui.is-minimized .call-video-stage {
            inset: 0;
            padding: 0;
            border-radius: inherit;
            overflow: hidden;
        }
        #call-ui.is-minimized .call-video-grid {
            width: 100%;
            height: 100%;
            gap: 0;
        }
        #call-ui.is-minimized .call-media-tile {
            height: 100%;
            aspect-ratio: auto;
            border-radius: inherit;
            border: none;
            box-shadow: none;
        }
        #call-ui.is-minimized .call-video-identity {
            font-size: 0.72rem;
            padding: 5px 8px;
        }
        #call-ui.has-video #call-image {
            display: none;
        }
        .call-hero {
            position: relative;
            z-index: 2;
            transition: opacity 0.2s ease;
        }
        .call-video-stage {
            position: absolute;
            inset: 0;
            z-index: 1;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 112px 24px 152px;
            pointer-events: none;
        }
        .call-video-grid {
            width: min(1120px, 100%);
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 18px;
            align-content: center;
            justify-items: stretch;
        }
        .call-video-stage.is-mobile-direct {
            padding: 0;
        }
        .call-video-grid.is-mobile-direct {
            width: 100%;
            height: 100%;
            display: flex;
        }
        .call-video-grid.is-mobile-direct .call-media-tile {
            width: 100%;
            height: 100%;
            max-width: none;
            aspect-ratio: auto;
            border-radius: 0;
            border: none;
            box-shadow: none;
        }
        .call-video-grid.is-mobile-direct .call-video-label {
            bottom: 88px;
        }
        .call-video-grid.has-odd .call-media-tile:last-child:nth-child(odd) {
            grid-column: 1 / -1;
            max-width: min(540px, 100%);
            justify-self: center;
        }
        .call-media-tile {
            position: relative;
            width: 100%;
            aspect-ratio: 16 / 9;
            border-radius: 24px;
            overflow: hidden;
            border: 1px solid rgba(255,255,255,0.12);
            background: rgba(15, 23, 42, 0.75);
            box-shadow: 0 22px 48px rgba(0,0,0,0.35);
            transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
        }
        .call-media-tile.single {
            max-width: min(760px, 100%);
            justify-self: center;
        }
        .call-video-tile {
            position: relative;
        }
        .call-avatar-tile {
            display: flex;
            align-items: center;
            justify-content: center;
            background:
                radial-gradient(circle at 30% 20%, rgba(45,88,245,0.22), transparent 38%),
                linear-gradient(180deg, rgba(15,23,42,0.92) 0%, rgba(2,6,23,0.96) 100%);
        }
        .call-avatar-shell {
            width: 124px;
            height: 124px;
            border-radius: 50%;
            border: 4px solid rgba(255,255,255,0.16);
            overflow: hidden;
            box-shadow: 0 16px 36px rgba(0,0,0,0.28);
            transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
        }
        .call-avatar-shell img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }
        .call-video-tile video {
            width: 100%;
            height: 100%;
            object-fit: cover;
            background: #020617;
            display: block;
        }
        .call-media-tile.is-speaking,
        .call-video-local-preview.is-speaking {
            border-color: var(--accent-color, #2d58f5);
            box-shadow: 0 0 0 3px rgba(45,88,245,0.28), 0 22px 48px rgba(0,0,0,0.35);
        }
        .call-avatar-tile.is-speaking .call-avatar-shell {
            border-color: var(--accent-color, #2d58f5);
            box-shadow: 0 0 0 4px rgba(45,88,245,0.25), 0 18px 40px rgba(0,0,0,0.32);
            transform: scale(1.02);
        }
        .call-video-tile.is-mirrored video,
        .call-video-local-preview.is-mirrored video {
            transform: scaleX(-1);
        }
        .call-video-identity {
            position: absolute;
            left: 12px;
            bottom: 12px;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 6px 10px;
            border-radius: 999px;
            background: rgba(0,0,0,0.55);
            color: rgba(255,255,255,0.96);
            font-size: 0.82rem;
            font-weight: 700;
            letter-spacing: 0.01em;
            backdrop-filter: blur(8px);
        }
        .call-video-identity-avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            object-fit: cover;
            border: 1px solid rgba(255,255,255,0.2);
            flex-shrink: 0;
        }
        .call-video-local-preview {
            position: absolute;
            top: 24px;
            right: 24px;
            z-index: 4;
            width: min(220px, 32vw);
            aspect-ratio: 16 / 9;
            border-radius: 20px;
            overflow: hidden;
            border: 1px solid rgba(255,255,255,0.16);
            box-shadow: 0 20px 42px rgba(0,0,0,0.4);
            background: rgba(15, 23, 42, 0.88);
            cursor: grab;
            touch-action: none;
        }
        .call-video-local-preview:active {
            cursor: grabbing;
        }
        .call-video-local-preview video {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
            background: #020617;
        }
        .call-video-local-preview .call-video-identity {
            left: 10px;
            bottom: 10px;
            font-size: 0.76rem;
            padding: 5px 9px;
        }
        .call-video-local-preview .call-video-identity-avatar {
            width: 26px;
            height: 26px;
        }
        
        .call-btn{
          width:80px;
          height:80px;
          border-radius:50%;
          border:none;
          display:flex;
          align-items:center;
          justify-content:center;
          font-size:32px;
          color:white;
          cursor:pointer;
          transition:transform 0.15s ease,opacity 0.15s ease;
        }
        .call-btn:hover{transform:scale(1.08);}
        .call-btn.accept{background:#22c55e;}
        .call-btn.reject{background:#ef4444;}
        
        /* Call more dropdown menu */
        #call-more-menu-wrapper {
            position: relative;
        }
        .call-more-dropdown {
            position: absolute;
            bottom: calc(100% + 12px);
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0, 0, 0, 0.95);
            border-radius: 16px;
            padding: 8px;
            min-width: 200px;
            backdrop-filter: blur(20px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
            z-index: 10001;
        }
        .call-more-option {
            display: flex;
            align-items: center;
            gap: 12px;
            width: 100%;
            padding: 12px 14px;
            background: none;
            border: none;
            color: white;
            font-size: 15px;
            font-weight: 500;
            cursor: pointer;
            border-radius: 10px;
            transition: background 0.2s;
            text-align: left;
        }
        .call-more-option:hover {
            background: rgba(255, 255, 255, 0.1);
        }
        .call-more-option i {
            font-size: 18px;
            width: 20px;
            text-align: center;
            flex-shrink: 0;
        }
        .call-more-option.active {
            background: rgba(45, 88, 245, 0.2);
        }
        .call-more-option.active i {
            color: #5b8def;
        }
        
        #call-ended-controls {
            position: fixed;
            left: 50%;
            bottom: calc(22px + env(safe-area-inset-bottom, 0px));
            transform: translateX(-50%);
            z-index: 6;
            justify-content: center;
            align-items: flex-start;
            gap: 18px;
            flex-wrap: nowrap;
            width: auto;
        }
        .call-ended-action {
            border: none;
            background: none;
            padding: 0;
            color: #fff;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 6px;
            cursor: pointer;
            font: inherit;
        }
        .call-ended-action:hover .call-ended-action-circle,
        .call-ended-action:focus-visible .call-ended-action-circle {
            transform: scale(1.06);
        }
        .call-ended-action:focus-visible {
            outline: none;
        }
        .call-ended-action-circle {
            width: 56px;
            height: 56px;
            border-radius: 50%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-size: 22px;
            color: #fff;
            transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
            box-shadow: 0 12px 24px rgba(0,0,0,0.2);
        }
        .call-ended-action-label {
            font-size: 12px;
            font-weight: 500;
            color: rgba(255,255,255,0.92);
            letter-spacing: 0.01em;
        }
        #call-again-btn .call-ended-action-circle {
            background: #22c55e;
        }
        #call-close-bottom-btn .call-ended-action-circle {
            background: rgba(255,255,255,0.12);
            border: 1px solid rgba(255,255,255,0.2);
        }

        /* Group call participant strip */
        #group-call-participants {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 18px;
            margin-top: 28px;
            max-width: 520px;
        }
        .gc-participant {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 6px;
            position: relative;
            cursor: default;
        }
        .gc-participant-avatar-wrap {
            position: relative;
            width: 64px;
            height: 64px;
        }
        .gc-participant-avatar {
            width: 64px;
            height: 64px;
            border-radius: 50%;
            object-fit: cover;
            border: 3px solid transparent;
            transition: border-color 0.2s;
            display: block;
        }
        .gc-participant.is-speaking .gc-participant-avatar {
            border-color: var(--accent-color, #2d58f5);
            box-shadow: 0 0 0 3px rgba(45,88,245,0.35);
        }
        .gc-participant-name {
            font-size: 0.72rem;
            color: rgba(255,255,255,0.75);
            max-width: 72px;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            text-align: center;
            opacity: 0;
            transition: opacity 0.15s;
            pointer-events: none;
            position: absolute;
            bottom: -20px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0,0,0,0.7);
            padding: 2px 7px;
            border-radius: 8px;
            white-space: nowrap;
        }
        .gc-participant:hover .gc-participant-name { opacity: 1; }
        .gc-participant-pending { opacity: 0.45; }

        /* Profile picture crop modal */
        #pfpCropModal {
            position: fixed;
            inset: 0;
            z-index: 99999;
            background: rgba(0,0,0,0.72);
            display: none;
            align-items: center;
            justify-content: center;
        }
        #pfpCropModal.is-open { display: flex; }
        .pfp-crop-dialog {
            background: var(--surface-elevated, #fff);
            border-radius: 20px;
            padding: 28px 24px 20px;
            width: min(420px, calc(100vw - 32px));
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 18px;
            box-shadow: 0 24px 64px rgba(0,0,0,0.35);
        }
        .pfp-crop-title {
            font-size: 1.1rem;
            font-weight: 700;
            color: var(--text-primary);
            align-self: flex-start;
        }
        .pfp-crop-canvas-wrap {
            position: relative;
            width: 280px;
            height: 280px;
            overflow: hidden;
            border-radius: 12px;
            background: #111;
            cursor: grab;
            touch-action: none;
            user-select: none;
        }
        .pfp-crop-canvas-wrap:active { cursor: grabbing; }
        #pfpCropCanvas {
            position: absolute;
            top: 0; left: 0;
        }
        .pfp-crop-overlay {
            position: absolute;
            inset: 0;
            pointer-events: none;
        }
        .pfp-crop-hint {
            font-size: 0.8rem;
            color: var(--text-secondary);
        }
        .pfp-crop-zoom {
            width: 100%;
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .pfp-crop-zoom label { font-size: 0.82rem; color: var(--text-secondary); flex-shrink: 0; }
        .pfp-crop-zoom input[type=range] { flex: 1; }
        .pfp-crop-actions {
            display: flex;
            gap: 10px;
            align-self: flex-end;
        }

        /* NEW: Active call bottom controls styles */
        #in-call-controls {
            position: fixed !important;
            left: 50% !important;
            right: auto !important;
            bottom: 40px !important;
            transform: translateX(-50%) !important;
            width: max-content !important;
            min-width: max-content;
            max-width: calc(100vw - 32px);
            margin: 0 !important;
            justify-content: center !important;
            align-items: center !important;
            background: rgba(0,0,0,0.8);
