            z-index: 3;
            width: min(100%, 400px);
            margin-inline: auto;
            flex-shrink: 0;
            padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 4px);
        }
        #in-call-controls .call-btn,
        #in-call-controls .call-control {
            width: 64px !important;
            height: 64px !important;
            border-radius: 50% !important;
            border: none !important;
            display: flex !important;
            align-items: center !important;
            justify-content: center !important;
            font-size: 24px !important;
            cursor: pointer !important;
            transition: all 0.2s ease !important;
        }
        #in-call-controls .call-btn:hover { transform: scale(1.05) !important; }
        #mic-toggle i.fa-microphone-slash { opacity: 0.7; }
        #video-toggle i.fa-video-slash { opacity: 0.7; }
        #screen-share-toggle i.fa-stop { opacity: 0.82; }
