            <div id="contactsList">

                <?php
                $contacts = qt_fetch_all_contact_rows($pdo, (int)$user_id);

                foreach($contacts as $c): 
                    $profilePic = isset($c['chat_type']) && $c['chat_type'] === 'group'
                    ? (!empty($c['profile_pic']) ? $c['profile_pic'] : QT_DEFAULT_GROUP_CHAT_ICON)
