                  <div class="settings-static-value" id="emailMaskedDisplay"><?php
                    $email = $user_email ?? '';
                    if ($email) {
                        $atPos = strpos($email, '@');
                        if ($atPos !== false) {
                            $localPart = substr($email, 0, $atPos);
                            $domainPart = substr($email, $atPos);
                            if (strlen($localPart) <= 4) {
                                echo htmlspecialchars(substr($localPart, 0, 1) . str_repeat('*', max(7, strlen($localPart) - 1)) . $domainPart);
                            } else {
                                echo htmlspecialchars(substr($localPart, 0, 4) . str_repeat('*', strlen($localPart) - 4) . $domainPart);
                            }
                        } else {
                            echo '••••••••';
                        }
                    } else {
                        echo '••••••••';
                    }
                  ?></div>
                  <button type="button" id="changeEmailBtn" class="settings-action-btn secondary" style="margin-left: 12px;">
