    const RINGTONE_AUDIO_SRC = <?= json_encode($ringtoneAudioAsset) ?>;
    const VIDEO_ATTACHMENT_EXTENSIONS = new Set([
        'mp4', 'm4v', 'mov', 'webm', 'mkv', 'avi', 'ogv', 'mpeg', 'mpg', 'mpe', '3gp', '3g2'
    ]);
    const TABLE_MESSAGE_MIN_DIMENSION = 1;
    const TABLE_MESSAGE_MAX_DIMENSION = 20;
