    const DEFAULT_VOICE_WAVEFORM = [
        0.24, 0.34, 0.58, 0.43, 0.76, 0.36, 0.62, 0.29, 0.55, 0.81,
        0.47, 0.68, 0.32, 0.52, 0.88, 0.41, 0.73, 0.35, 0.57, 0.79,
        0.44, 0.66, 0.31, 0.54, 0.72, 0.39, 0.61, 0.27
    ];
    const EMOJI_SEQUENCE_PATTERN_SOURCE = '(?:(?:\\p{Regional_Indicator}{2})|(?:[#*0-9]\\uFE0F?\\u20E3)|(?:\\p{Extended_Pictographic}(?:\\uFE0E|\\uFE0F)?(?:\\p{Emoji_Modifier})?(?:\\u200D\\p{Extended_Pictographic}(?:\\uFE0E|\\uFE0F)?(?:\\p{Emoji_Modifier})?)*))';
    let emojiOnlyMessagePattern = null;
    let emojiInlinePattern = null;
    try {
        emojiOnlyMessagePattern = new RegExp(`^(?:\\s*${EMOJI_SEQUENCE_PATTERN_SOURCE}\\s*)+$`, 'u');
        emojiInlinePattern = new RegExp(EMOJI_SEQUENCE_PATTERN_SOURCE, 'gu');
    } catch (error) {
        console.warn('Emoji-only message detection is not available in this browser.', error);
    }
    const EMOJI_GROUP = Object.freeze({
        SMILEYS_EMOTION: 0,
