        { key: 'food_drink', label: 'Food and Drink', emojis: ['🍕', '🍔', '🍟', '🌮', '🍿', '🍩', '🍪', '🍓', '🍉', '🍇', '🥑', '🍜', '🍣', '☕', '🧋', '🍰'] },
        { key: 'activities', label: 'Activities', emojis: ['🎉', '🎊', '🎂', '🎁', '🎈', '✨', '🌟', '⚡', '🎵', '🎶', '📸', '💌', '🚀', '🏆', '⚽', '🎮'] },
        { key: 'symbols', label: 'Symbols', emojis: ['❤️', '🩷', '🧡', '💛', '💚', '🩵', '💙', '💜', '🖤', '🤍', '🤎', '💔', '❣️', '💕', '💞', '💯'] }
    ];
    const EMOJI_PICKER_FULL_CATEGORIES = [
        { key: 'smileys_people', label: 'Smileys & People', icon: 'fa-regular fa-face-smile', groups: [EMOJI_GROUP.SMILEYS_EMOTION, EMOJI_GROUP.PEOPLE_BODY] },
        { key: 'animals_nature', label: 'Animals and Nature', icon: 'fa-solid fa-leaf', groups: [EMOJI_GROUP.ANIMALS_NATURE] },
        { key: 'food_drink', label: 'Food and Drink', icon: 'fa-solid fa-utensils', groups: [EMOJI_GROUP.FOOD_DRINK] },
        { key: 'activities', label: 'Activities', icon: 'fa-solid fa-futbol', groups: [EMOJI_GROUP.ACTIVITIES] },
        { key: 'travel_places', label: 'Travel and Places', icon: 'fa-solid fa-plane', groups: [EMOJI_GROUP.TRAVEL_PLACES] },
        { key: 'objects', label: 'Objects', icon: 'fa-solid fa-lightbulb', groups: [EMOJI_GROUP.OBJECTS] },
        { key: 'symbols', label: 'Symbols', icon: 'fa-solid fa-heart', groups: [EMOJI_GROUP.SYMBOLS] },
        { key: 'flags', label: 'Flags', icon: 'fa-solid fa-flag', groups: [EMOJI_GROUP.FLAGS] }
    ];
    const DEFAULT_EMOJI_CATEGORY = EMOJI_PICKER_FULL_CATEGORIES[0].key;
    const TWEMOJI_CDN_BASE = 'https://cdn.jsdelivr.net/npm/twemoji@14.0.2/assets/svg';
    const EMOJI_USAGE_STORAGE_KEY = 'quilltalk.emojiUsageStats.v1';
    const EMOJI_FAVORITES_CATEGORY = Object.freeze({
        key: 'favorites',
        label: 'Favorites',
        icon: 'fa-solid fa-star',
        groups: []
    });
    
    // Global emoji data for both grid and autocomplete
    let emojiData = [];
    let recentEmojis = [];
    let emojiUsageStats = {};
    let emojiDataSource = 'fallback';
    let emojiByValue = new Map();
    let emojiByShortcode = new Map();

    function loadEmojiUsageStats() {
        try {
            const stored = localStorage.getItem(EMOJI_USAGE_STORAGE_KEY);
            const parsed = stored ? JSON.parse(stored) : {};
            emojiUsageStats = parsed && typeof parsed === 'object' ? parsed : {};
        } catch (error) {
            emojiUsageStats = {};
        }
    }

    function persistEmojiUsageStats() {
        try {
            localStorage.setItem(EMOJI_USAGE_STORAGE_KEY, JSON.stringify(emojiUsageStats));
        } catch (error) {
            console.error('Failed to save emoji favorites:', error);
        }
    }

    function recordEmojiUsage(emoji) {
        const key = String(emoji || '').trim();
        if (!key) {
            return;
        }

        const now = Date.now();
        const existing = emojiUsageStats[key] && typeof emojiUsageStats[key] === 'object'
            ? emojiUsageStats[key]
            : {};
        emojiUsageStats[key] = {
            count: Math.min(9999, Math.max(0, Number(existing.count || 0)) + 1),
            lastUsed: now
        };
        persistEmojiUsageStats();
    }

    function getFavoriteEmojiRecords(limit = 48) {
        const results = [];
        const seen = new Set();
        const usageEntries = Object.entries(emojiUsageStats || {})
            .filter(([emoji]) => String(emoji || '').trim() !== '')
            .sort((a, b) => {
                const aCount = Math.max(0, Number(a[1] && a[1].count || 0));
                const bCount = Math.max(0, Number(b[1] && b[1].count || 0));
                const aLastUsed = Math.max(0, Number(a[1] && a[1].lastUsed || 0));
                const bLastUsed = Math.max(0, Number(b[1] && b[1].lastUsed || 0));
                return bCount - aCount || bLastUsed - aLastUsed;
            });

        usageEntries.forEach(([emoji]) => {
            if (seen.has(emoji)) {
                return;
            }
            seen.add(emoji);
            results.push(emojiByValue.get(emoji) || {
                emoji,
                label: '',
                shortcodes: [],
                tags: [],
                order: Number.MAX_SAFE_INTEGER
            });
        });

        recentEmojis.forEach(emoji => {
            if (seen.has(emoji)) {
                return;
            }
            seen.add(emoji);
            results.push(emojiByValue.get(emoji) || {
                emoji,
                label: '',
                shortcodes: [],
                tags: [],
                order: Number.MAX_SAFE_INTEGER
            });
        });

        return results.slice(0, limit);
    }

    function decodeEmojiHexcode(hexcode) {
        const codepoints = String(hexcode || '')
            .split('-')
            .map(part => parseInt(part, 16))
            .filter(Number.isFinite);
        return codepoints.length ? String.fromCodePoint(...codepoints) : '';
    }

    function normalizeEmojiSearchValue(value) {
        return String(value || '')
            .toLowerCase()
            .replace(/[_-]+/g, ' ')
            .replace(/:/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function buildEmojiRecord(entry, index) {
        const emojiValue = entry && (entry.unicode || entry.emoji || decodeEmojiHexcode(entry.hexcode));
        if (!emojiValue) {
            return null;
        }

        const shortcodes = Array.isArray(entry.shortcodes)
            ? Array.from(new Set(entry.shortcodes.map(sc => String(sc || '').trim()).filter(Boolean)))
            : [];
        const tags = Array.isArray(entry.tags)
            ? Array.from(new Set(entry.tags.map(tag => String(tag || '').trim()).filter(Boolean)))
            : [];
        const label = String(entry.annotation || entry.label || '').trim();
        const normalizedShortcodes = shortcodes.map(normalizeEmojiSearchValue).filter(Boolean);
        const normalizedTags = tags.map(normalizeEmojiSearchValue).filter(Boolean);

        return {
            emoji: emojiValue,
            label,
            shortcodes,
            tags,
            group: Number.isInteger(entry.group) ? entry.group : null,
            order: Number.isFinite(entry.order) ? entry.order : index,
            normalizedLabel: normalizeEmojiSearchValue(label),
            normalizedShortcodes,
            normalizedTags
        };
    }

    function buildFallbackEmojiData() {
        const fallbackGroupByKey = {
            smileys_people: EMOJI_GROUP.SMILEYS_EMOTION,
            animals_nature: EMOJI_GROUP.ANIMALS_NATURE,
            food_drink: EMOJI_GROUP.FOOD_DRINK,
            activities: EMOJI_GROUP.ACTIVITIES,
            symbols: EMOJI_GROUP.SYMBOLS
        };

        const fallbackData = [];
        EMOJI_LIBRARY.forEach((category, categoryIndex) => {
            category.emojis.forEach((emoji, emojiIndex) => {
                const record = buildEmojiRecord({
                    unicode: emoji,
                    label: category.label,
                    tags: [category.label.toLowerCase()],
                    group: fallbackGroupByKey[category.key] ?? EMOJI_GROUP.OBJECTS,
                    order: (categoryIndex * 100) + emojiIndex
                }, (categoryIndex * 100) + emojiIndex);
                if (record) {
                    fallbackData.push(record);
                }
            });
        });
        return fallbackData;
    }

    function setEmojiData(nextData, source) {
        emojiData = Array.isArray(nextData) ? nextData.filter(Boolean) : [];
        emojiDataSource = source || 'fallback';
        emojiByValue = new Map();
        emojiByShortcode = new Map();

        emojiData.forEach((emoji, index) => {
            emoji.order = Number.isFinite(emoji.order) ? emoji.order : index;
            emojiByValue.set(emoji.emoji, emoji);
            emoji.shortcodes.forEach(shortcode => {
                const normalized = normalizeEmojiSearchValue(shortcode);
                if (normalized && !emojiByShortcode.has(normalized)) {
                    emojiByShortcode.set(normalized, emoji);
                }
            });
        });
    }
    
    // Load emoji data from CDN
    async function loadEmojiData() {
        try {
            const response = await fetch('https://cdn.jsdelivr.net/npm/emojibase-data@15/en/compact.json');
            if (!response.ok) {
                throw new Error(`Emoji library request failed with status ${response.status}`);
            }
            const data = await response.json();
            const nextEmojiData = data
                .map((emoji, index) => buildEmojiRecord(emoji, index))
                .filter(Boolean);

            setEmojiData(nextEmojiData, 'emojibase');
            console.log(`Loaded ${emojiData.length} emojis from emojibase`);
        } catch (error) {
            console.error('Failed to load emoji data:', error);
            setEmojiData(buildFallbackEmojiData(), 'fallback');
        } finally {
            window.dispatchEvent(new Event('quilltalk:emojis-loaded'));
        }
    }

    // Load recent emojis from localStorage
    function loadRecentEmojis() {
        loadEmojiUsageStats();
        try {
            const stored = localStorage.getItem('quilltalk.recentEmojis');
            recentEmojis = stored ? JSON.parse(stored) : [];
        } catch (e) {
            recentEmojis = [];
        }
    }

    // Save recent emoji
    function saveRecentEmoji(emoji) {
        recordEmojiUsage(emoji);
        recentEmojis = recentEmojis.filter(e => e !== emoji);
        recentEmojis.unshift(emoji);
        recentEmojis = recentEmojis.slice(0, 20); // Keep only 20 most recent
        try {
            localStorage.setItem('quilltalk.recentEmojis', JSON.stringify(recentEmojis));
        } catch (e) {
            console.error('Failed to save recent emoji:', e);
        }
    }

    // Initialize emoji system
    loadRecentEmojis();
    loadEmojiData();
    
