    let userUsernamesMap = {};
    let userProfilePics = {};
    let userOnlineMap = {};
    let directContactOnlineMap = {};
    let userBiosMap = {};
    let userCreatedAtMap = {};
    let groupNamesMap = {};
    let groupDescriptionsMap = {};
    let groupIconsMap = {};
    let groupCreatedAtMap = {};
    let groupMemberCountMap = {};
    let groupMembersMap = {};
    let chatNicknamesByChat = {};
    let groupOnlineMap = {};
    const currentUserId = <?=json_encode($user_id)?>;
    let currentUserDisplayName = <?= json_encode($user['display_name'] ?? $user['username'] ?? 'User') ?>;
    const currentUsername = <?= json_encode($user['username'] ?? 'user000') ?>;
    let currentUserProfilePic = <?= json_encode($resolvedCurrentUserProfilePic) ?>;
    
    // Nickname storage - initialize early to avoid reference errors
    const NICKNAME_DISPLAY_PREF_KEY = 'quilltalk.nicknameDisplayPref.v1';
    let userNicknamesCache = {}; // Cache nicknames from database
    
    // Clear display preferences on page load so nicknames always show by default
    try {
        sessionStorage.removeItem(NICKNAME_DISPLAY_PREF_KEY);
    } catch (e) {}
    
    // Load nicknames from database
    async function loadNicknamesFromDatabase() {
        try {
            console.log('Loading nicknames from database...');
            const res = await fetch(`get_nicknames.php?token=${encodeURIComponent(token)}`);
            if (!res.ok) {
                console.warn('get_nicknames.php returned', res.status);
                return false;
            }
            const data = await res.json();
            console.log('Nicknames response:', data);
            if (data && data.success) {
                userNicknamesCache = data.nicknames || {};
                console.log('Loaded nicknames:', userNicknamesCache);
                return true;
            }
        } catch (e) {
            console.error('Failed to load nicknames:', e);
        }
        return false;
