    if (!window.aiChatsMap) window.aiChatsMap = {};
    
    // Helper function to load AI chats if functions are ready
    async function loadAiChatsIfReady() {
        if (typeof loadAiChatsFromDatabase === 'function' && typeof addContact === 'function') {
            console.log('[AI CHATS] Loading AI chats synchronously with contacts');
            try {
                await loadAiChatsFromDatabase();
                console.log('[AI CHATS] AI chats loaded successfully');
            } catch (err) {
                console.error('[AI CHATS] Failed to load AI chats:', err);
            }
        } else {
            console.log('[AI CHATS] Functions not ready yet, skipping AI chat loading');
        }
    }
    
    // Load AI chats from database
    async function loadAiChatsFromDatabase() {
        try {
            console.log('Loading AI chats from database...');
            const res = await fetch(`fetch_ai_chats.php?token=${encodeURIComponent(token)}&t=${Date.now()}`);
            if (!res.ok) {
                console.warn('fetch_ai_chats.php returned', res.status);
                return false;
            }
            const data = await res.json();
            console.log('AI chats response:', data);
            if (data && data.success && Array.isArray(data.ai_chats)) {
                // Log the first AI chat to see what fields we're getting
                if (data.ai_chats.length > 0) {
                    console.log('[AI CHATS] First AI chat data:', JSON.stringify(data.ai_chats[0], null, 2));
                    console.log('[AI CHATS] last_message field:', data.ai_chats[0].last_message);
                    console.log('[AI CHATS] last_message type:', typeof data.ai_chats[0].last_message);
                }
                
                // Add each AI chat to contacts
                data.ai_chats.forEach(aiChat => {
                    const aiChatKey = `ai:${aiChat.id}`;
                    const parsedNotes = parseSidequestBotAiChatNotes(aiChat.notes || '');
                    const isTemporary = isTemporarySidequestBotAiMeta(parsedNotes.meta);
                    
                    // Log what we're getting for this chat
                    console.log('[AI CHATS] Processing chat:', aiChatKey, 'last_message:', aiChat.last_message);
                    
                    window.aiChatsMap[aiChatKey] = {
                        id: aiChat.id,
                        displayName: aiChat.display_name,
                        bio: aiChat.bio,
                        notes: aiChat.notes,
                        profilePic: aiChat.profile_pic || DEFAULT_AI_PROFILE_PIC
                    };
                    
                    // Add to contacts list if addContact is available
                    if (isTemporary) {
                        removeAiChatContact(aiChatKey);
                    } else if (typeof addContact === 'function') {
                        addContact(
                            aiChatKey,
                            aiChat.display_name,
                            '',
                            aiChat.profile_pic || DEFAULT_AI_PROFILE_PIC,
                            0,
                            aiChat.bio || ''
                        );
                    } else {
                        console.warn('addContact not available yet, AI chat not added to contacts:', aiChatKey);
                    }
                });
                console.log('Loaded AI chats:', window.aiChatsMap);
                
                // Fetch last messages for each AI chat to populate previews
                console.log('[AI CHATS] Starting to fetch messages for', data.ai_chats.length, 'chats');
                data.ai_chats.forEach(async (aiChat) => {
                    const aiChatKey = `ai:${aiChat.id}`;
                    if (isTemporaryAiChatKey(aiChatKey)) {
                        return;
                    }
                    console.log('[AI CHATS] Fetching messages for:', aiChatKey);
                    try {
                        const msgRes = await fetch(`fetch_ai_messages.php?token=${encodeURIComponent(token)}&ai_chat_key=${encodeURIComponent(aiChatKey)}&last_id=0&t=${Date.now()}`);
                        console.log('[AI CHATS] Fetch response status for', aiChatKey, ':', msgRes.status);
                        if (msgRes.ok) {
                            const messages = await msgRes.json();
                            console.log('[AI CHATS] Got', messages.length, 'messages for', aiChatKey);
                            if (Array.isArray(messages) && messages.length > 0) {
                                // Get the last message
                                const lastMsg = messages[messages.length - 1];
                                console.log('[AI CHATS] Last message for', aiChatKey, ':', lastMsg.message);
                                
                                // Update preview
                                if (typeof updateContactPreview === 'function') {
                                    updateContactPreview(aiChatKey, lastMsg, false);
                                    console.log('[AI CHATS] Updated preview for', aiChatKey);
                                } else {
                                    console.warn('[AI CHATS] updateContactPreview not available');
                                }
                            } else {
                                console.log('[AI CHATS] No messages for', aiChatKey);
                            }
                        }
                    } catch (e) {
                        console.error('[AI CHATS] Failed to fetch messages for', aiChatKey, e);
                    }
                });
                
                // Sort contacts list after loading AI chats
                setTimeout(() => {
                    if (typeof sortContactsList === 'function') {
                        sortContactsList();
                    }
                }, 200);
                
                return true;
            }
        } catch (e) {
            console.error('Failed to load AI chats:', e);
        }
        return false;
    }
    
    // Make function globally accessible for DOMContentLoaded handler
    window.loadAiChatsFromDatabase = loadAiChatsFromDatabase;
    
    // Function to add any pending AI chats to contacts
    function addPendingAiChatsToContacts() {
        if (!window.aiChatsMap || typeof addContact !== 'function') {
            return;
        }
        
        Object.entries(window.aiChatsMap).forEach(([aiChatKey, aiChat]) => {
            if (isTemporaryAiChatKey(aiChatKey)) {
                removeAiChatContact(aiChatKey);
                return;
            }
            // Check if this AI chat is already in contacts
            const existingContact = contactsList.querySelector(`.contact[data-id="${aiChatKey}"]`);
            if (!existingContact) {
                // Add to contacts list
                addContact(
                    aiChatKey,
                    aiChat.displayName,
                    '',
                    aiChat.profilePic,
                    0,
                    aiChat.bio || ''
                );
                console.log('Added pending AI chat to contacts:', aiChatKey);
            }
        });
    }
    
    // Make function globally accessible
    window.addPendingAiChatsToContacts = addPendingAiChatsToContacts;
    
    // Nickname helper functions - defined early to avoid reference errors
    function getUserNickname(userId) {
        const nickname = userNicknamesCache[String(userId)] || null;
        console.log(`getUserNickname(${userId}): cache has ${Object.keys(userNicknamesCache).length} entries, returning "${nickname}"`);
        return nickname;
    }

    function normalizeChatScopedNicknameValue(nickname) {
        const normalized = String(nickname || '').replace(/\s+/g, ' ').trim();
        return normalized.slice(0, 50);
    }

    function rememberChatNickname(chatKey, userId, nickname) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedUserId = String(userId || '').trim();
        const normalizedNickname = normalizeChatScopedNicknameValue(nickname);

        if (!normalizedChatKey || !normalizedUserId) {
            return '';
        }

        if (!chatNicknamesByChat[normalizedChatKey]) {
            chatNicknamesByChat[normalizedChatKey] = {};
        }

        if (normalizedNickname) {
            chatNicknamesByChat[normalizedChatKey][normalizedUserId] = normalizedNickname;
        } else if (chatNicknamesByChat[normalizedChatKey]) {
            delete chatNicknamesByChat[normalizedChatKey][normalizedUserId];
            if (!Object.keys(chatNicknamesByChat[normalizedChatKey]).length) {
                delete chatNicknamesByChat[normalizedChatKey];
            }
        }

        return normalizedNickname;
    }

    function rememberViewerChatNickname(chatKey, nickname) {
        return rememberChatNickname(chatKey, currentUserId, nickname);
    }

    function getChatNicknameForUser(chatKey, userId) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedChatKey || !normalizedUserId) {
            return '';
        }

        return normalizeChatScopedNicknameValue(
            chatNicknamesByChat[normalizedChatKey]
                ? chatNicknamesByChat[normalizedChatKey][normalizedUserId]
                : ''
        );
    }

    function getViewerChatNickname(chatKey) {
        return getChatNicknameForUser(chatKey, currentUserId);
    }
    
    async function setUserNickname(userId, nickname) {
        try {
            const res = await fetch('set_nickname.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    target_user_id: String(userId),
                    nickname: nickname && nickname.trim() ? nickname.trim() : ''
                })
            });
            const data = await res.json();
            
            if (data && data.success) {
                // Update cache
                if (nickname && nickname.trim()) {
                    userNicknamesCache[String(userId)] = nickname.trim();
                } else {
                    delete userNicknamesCache[String(userId)];
                }
                return true;
            }
        } catch (e) {
            console.error('Failed to save nickname:', e);
        }
        return false;
    }
    
    async function clearUserNickname(userId) {
        return await setUserNickname(userId, null);
    }
    
    function getNicknameDisplayPref(userId) {
        const nickname = getUserNickname(userId);
        if (!nickname) {
            return 'display'; // No nickname, show display name
        }
        
        // On page load, always default to nickname
        // The preference is only used during the current session
        try {
            const prefs = JSON.parse(sessionStorage.getItem(NICKNAME_DISPLAY_PREF_KEY) || '{}');
            return prefs[String(userId)] || 'nickname';
        } catch (e) {
            return 'nickname';
        }
    }
    
    function setNicknameDisplayPref(userId, pref) {
        try {
            // Use sessionStorage so it resets on page reload
            const prefs = JSON.parse(sessionStorage.getItem(NICKNAME_DISPLAY_PREF_KEY) || '{}');
            prefs[String(userId)] = pref;
            sessionStorage.setItem(NICKNAME_DISPLAY_PREF_KEY, JSON.stringify(prefs));
            return true;
        } catch (e) {
            return false;
        }
    }
    
    // --- Notification preferences (must be defined before getContactMeta) ---
    const CHAT_NOTIFICATION_KEY = 'quilltalk.chatNotif.';
    const LEGACY_GROUP_NOTIFICATION_KEY = 'quilltalk.groupNotif.';
    let notificationPrefsBootstrapped = false;
    
    function normalizeChatNotificationMode(mode) {
        return String(mode || '').toLowerCase() === 'mention' ? 'mention' : 'all';
    }
    
    function getStoredChatNotificationPref(chatKey) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return '';
        }

        try {
            const stored = localStorage.getItem(CHAT_NOTIFICATION_KEY + normalizedChatKey);
            if (stored) {
                return normalizeChatNotificationMode(stored);
            }

            if (isGroupChatKey(normalizedChatKey)) {
                const legacyStored = localStorage.getItem(LEGACY_GROUP_NOTIFICATION_KEY + normalizedChatKey);
                if (legacyStored) {
                    return normalizeChatNotificationMode(legacyStored);
                }
            }
        } catch (error) {}

        return '';
    }

    function getContactNotificationMode(chatKey) {
        const contactEl = getContactElement(chatKey);
        return normalizeChatNotificationMode(contactEl ? contactEl.dataset.notificationMode : 'all');
    }

    function setContactNotificationMode(chatKey, mode) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return;
        }

        const contactEl = getContactElement(normalizedChatKey);
        if (contactEl) {
            contactEl.dataset.notificationMode = normalizeChatNotificationMode(mode);
        }
    }

    async function persistChatNotificationPref(chatKey, pref) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return;
        }

        const res = await fetch('save_chat_notification_preference.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                token,
                chat_key: normalizedChatKey,
                mode: normalizeChatNotificationMode(pref)
            })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) {
            throw new Error(data.error || 'Unable to save notification preference.');
        }
        setContactNotificationMode(normalizedChatKey, data.mode || pref);
    }

    async function setChatNotificationPref(chatKey, pref, { persistServer = true } = {}) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return 'all';
        }

        const normalizedPref = normalizeChatNotificationMode(pref);
        try {
            localStorage.setItem(CHAT_NOTIFICATION_KEY + normalizedChatKey, normalizedPref);
            if (isGroupChatKey(normalizedChatKey)) {
                localStorage.setItem(LEGACY_GROUP_NOTIFICATION_KEY + normalizedChatKey, normalizedPref);
            }
        } catch (error) {}

        setContactNotificationMode(normalizedChatKey, normalizedPref);

        if (persistServer) {
            try {
                await persistChatNotificationPref(normalizedChatKey, normalizedPref);
            } catch (error) {
                console.warn('Unable to persist notification preference.', error);
            }
        }

        return normalizedPref;
    }

    function getChatNotificationPref(chatKey) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return 'all';
        }

        const storedPref = getStoredChatNotificationPref(normalizedChatKey);
        if (storedPref) {
            return storedPref;
        }

        return getContactNotificationMode(normalizedChatKey);
    }

    function getGroupNotifPref(groupKey) {
        return getChatNotificationPref(groupKey);
    }

    async function setGroupNotifPref(groupKey, pref) {
        return setChatNotificationPref(groupKey, pref);
    }
    
    // --- User profile mapping ---
        const defaultProfilePic = DEFAULT_PROFILE_PIC;
    
    function normalizeGroupRole(value) {
        const normalized = String(value || '').trim().toLowerCase();
        if (normalized === GROUP_ROLE_OWNER || normalized === GROUP_ROLE_ADMIN) {
            return normalized;
        }
        return GROUP_ROLE_MEMBER;
    }

    function normalizeGroupSendPermission(value) {
        return String(value || '').trim().toLowerCase() === GROUP_SEND_PERMISSION_ADMINS
            ? GROUP_SEND_PERMISSION_ADMINS
            : GROUP_SEND_PERMISSION_ALL;
    }

    function normalizeGroupAddPermission(value) {
        return String(value || '').trim().toLowerCase() === GROUP_ADD_PERMISSION_ALL
            ? GROUP_ADD_PERMISSION_ALL
            : GROUP_ADD_PERMISSION_ADMINS;
    }
    
    function getContactFallbackPic(chatType) {
        if (chatType === 'group') {
            return DEFAULT_GROUP_CHAT_ICON;
        }
        if (chatType === 'ai') {
            return DEFAULT_AI_PROFILE_PIC;
        }
        return defaultProfilePic;
    }

    function normalizeProfilePic(value, chatType = 'direct') {
        const normalized = typeof value === 'string'
            ? value.trim()
            : '';
        return normalized || getContactFallbackPic(chatType);
    }
    
    function getContactChatType(input) {
        if (typeof input === 'string' || typeof input === 'number') {
            return getChatTypeFromKey(String(input));
        }

        if (input && typeof input === 'object') {
            const datasetType = String(input.dataset && input.dataset.chatType ? input.dataset.chatType : '').trim().toLowerCase();
            if (datasetType === 'group' || datasetType === 'direct' || datasetType === 'ai') {
                return datasetType;
            }
            return getChatTypeFromKey(String(input.dataset && input.dataset.id ? input.dataset.id : ''));
        }

        return 'direct';
    }
    
    function getContactElement(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId || !contactsList) {
            return null;
        }
        return Array.from(contactsList.querySelectorAll('.contact')).find(contactEl => {
            return String(contactEl.dataset.id || '') === normalizedUserId;
        }) || null;
    }
    
    function getResolvedContactOnlineState(userId, contactEl = null) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId) {
            return false;
        }

        if (normalizedUserId === String(currentUserId)) {
            return true;
        }

        const resolvedContactEl = contactEl || getContactElement(normalizedUserId);
        const chatType = resolvedContactEl ? getContactChatType(resolvedContactEl) : getChatTypeFromKey(normalizedUserId);

        if (chatType === 'group') {
            if (normalizedUserId in groupOnlineMap) {
                return !!groupOnlineMap[normalizedUserId];
            }
            return !!(resolvedContactEl && resolvedContactEl.dataset.online === '1');
        }

        if (resolvedContactEl && resolvedContactEl.dataset && resolvedContactEl.dataset.online !== undefined) {
            return resolvedContactEl.dataset.online === '1';
        }

        if (normalizedUserId in directContactOnlineMap) {
            return !!directContactOnlineMap[normalizedUserId];
        }

        if (normalizedUserId in userOnlineMap) {
            return !!userOnlineMap[normalizedUserId];
        }

        return !!(resolvedContactEl && resolvedContactEl.dataset.online === '1');
    }
    
    function getContactMeta(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId) {
            return null;
        }

        if (normalizedUserId === String(currentUserId)) {
            return {
                displayName: currentUserDisplayName,
                username: currentUsername,
                profilePic: normalizeProfilePic(currentUserProfilePic, 'direct'),
                bio: currentUserBio || '',
                createdAt: currentUserCreatedAt || '',
                isOnline: true,
                type: 'direct',
                isGroup: false,
                memberCount: 0,
                notificationMode: 'all'
            };
        }

        if (normalizedUserId.startsWith('ai:') && window.aiChatsMap && window.aiChatsMap[normalizedUserId]) {
            const aiData = window.aiChatsMap[normalizedUserId] || {};
            return {
                displayName: String(aiData.displayName || 'QuillTalk AI'),
                username: '',
                profilePic: normalizeProfilePic(aiData.profilePic || DEFAULT_AI_PROFILE_PIC, 'direct'),
                bio: String(aiData.bio || ''),
                createdAt: '',
                isOnline: true,
                type: 'direct',
                isGroup: false,
                isAiChat: true,
                memberCount: 0,
                notificationMode: 'all'
            };
        }

        const contactEl = getContactElement(normalizedUserId);
        const contactImg = contactEl ? contactEl.querySelector('.contact-img') : null;
        const chatType = contactEl ? getContactChatType(contactEl) : getChatTypeFromKey(normalizedUserId);
        const isGroup = chatType === 'group';
        const memberCount = parseInt(
            String((contactEl && contactEl.dataset.memberCount) || groupMemberCountMap[normalizedUserId] || 0),
            10
        ) || 0;

        if (isGroup) {
            const viewerRole = normalizeGroupRole(contactEl ? contactEl.dataset.viewerRole : '');
            const viewerMutedUntil = contactEl ? String(contactEl.dataset.viewerMutedUntil || '') : '';
            const sendPermission = normalizeGroupSendPermission(contactEl ? contactEl.dataset.sendPermission : '');
            const addMembersPermission = normalizeGroupAddPermission(contactEl ? contactEl.dataset.addMembersPermission : '');
            const canManageGroup = !!(contactEl && contactEl.dataset.canManageGroup === '1');
            const canChangeRoles = !!(contactEl && contactEl.dataset.canChangeRoles === '1');
            const canDeleteGroup = !!(contactEl && contactEl.dataset.canDeleteGroup === '1');
            const viewerIsMuted = isFutureDateValue(viewerMutedUntil);
            const canSend = !viewerIsMuted && (
                sendPermission === GROUP_SEND_PERMISSION_ALL
                || viewerRole === GROUP_ROLE_OWNER
                || viewerRole === GROUP_ROLE_ADMIN
            );
            return {
                displayName: groupNamesMap[normalizedUserId]
                    || (contactEl ? (contactEl.dataset.displayName || `Group ${getGroupIdFromChatKey(normalizedUserId) || ''}`.trim()) : `Group ${getGroupIdFromChatKey(normalizedUserId) || ''}`.trim()),
                username: '',
                profilePic: normalizeProfilePic(groupIconsMap[normalizedUserId] || (contactImg ? (contactImg.currentSrc || contactImg.src) : DEFAULT_GROUP_CHAT_ICON), 'group'),
                bio: groupDescriptionsMap[normalizedUserId] || (contactEl ? (contactEl.dataset.bio || '') : ''),
                createdAt: groupCreatedAtMap[normalizedUserId] || (contactEl ? (contactEl.dataset.createdAt || '') : ''),
                isOnline: getResolvedContactOnlineState(normalizedUserId, contactEl),
                type: 'group',
                isGroup: true,
                memberCount,
                viewerRole,
                viewerMutedUntil,
                viewerIsMuted,
                sendPermission,
                addMembersPermission,
                canManageGroup,
                canChangeRoles,
                canDeleteGroup,
                canSend,
                notificationMode: getChatNotificationPref(normalizedUserId)
            };
        }

        return {
            displayName: userNamesMap[normalizedUserId] || (contactEl ? (contactEl.dataset.displayName || `User ${normalizedUserId}`) : `User ${normalizedUserId}`),
            username: userUsernamesMap[normalizedUserId] || (contactEl ? (contactEl.dataset.username || '') : ''),
            profilePic: normalizeProfilePic(userProfilePics[normalizedUserId] || (contactImg ? (contactImg.currentSrc || contactImg.src) : defaultProfilePic), 'direct'),
            bio: userBiosMap[normalizedUserId] || (contactEl ? (contactEl.dataset.bio || '') : ''),
            createdAt: userCreatedAtMap[normalizedUserId] || (contactEl ? (contactEl.dataset.createdAt || '') : ''),
            isOnline: getResolvedContactOnlineState(normalizedUserId, contactEl),
            type: 'direct',
            isGroup: false,
            memberCount: 0,
            notificationMode: getChatNotificationPref(normalizedUserId)
        };
    }

    function getAiAssistantIdentityForChat(chatKey = '') {
        const normalizedChatKey = String(chatKey || '').trim();
        if (normalizedChatKey.startsWith('ai:') && window.aiChatsMap && window.aiChatsMap[normalizedChatKey]) {
            const aiData = window.aiChatsMap[normalizedChatKey] || {};
            return {
                displayName: String(aiData.displayName || 'QuillTalk AI'),
                profilePic: normalizeProfilePic(aiData.profilePic || DEFAULT_AI_PROFILE_PIC, 'direct')
            };
        }

        return {
            displayName: 'QuillTalk AI',
            profilePic: normalizeProfilePic(DEFAULT_AI_PROFILE_PIC, 'direct')
        };
    }
    
    function getDisplayNameForUser(userId, meta = null, chatKey = '') {
        // Always check for nickname first
        const nickname = getUserNickname(userId);
        const pref = getNicknameDisplayPref(userId);
        
        console.log(`getDisplayNameForUser(${userId}): nickname="${nickname}", pref="${pref}"`);
        
        if (nickname && pref === 'nickname') {
            console.log(`  -> Returning nickname: "${nickname}"`);
            return nickname;
        }

        const chatNickname = getChatNicknameForUser(chatKey, userId);
        if (chatNickname) {
            console.log(`  -> Returning chat nickname: "${chatNickname}"`);
            return chatNickname;
        }
        
        // Fall back to display name
        if (!meta) {
            // Check if getContactMeta is available (it's defined later in the file)
            if (typeof getContactMeta === 'function') {
                meta = getContactMeta(userId);
            }
        }
        if (!meta) {
            console.log(`  -> No meta, returning "Unknown"`);
            return 'Unknown';
        }
        
        console.log(`  -> Returning displayName: "${meta.displayName}"`);
        return meta.displayName || 'Unknown';
    }
    
    // Apply nicknames to all contacts on page load
    function applyNicknamesOnPageLoad() {
        try {
            const contacts = document.querySelectorAll('#contactsList .contact');
            console.log('Applying nicknames to', contacts.length, 'contacts');
            contacts.forEach(contactEl => {
                const userId = contactEl.dataset.id;
                if (userId && !userId.startsWith('group:')) {
                    const nickname = getUserNickname(userId);
                    if (nickname) {
                        const pref = getNicknameDisplayPref(userId);
                        console.log('Contact', userId, 'nickname:', nickname, 'pref:', pref);
                        if (pref === 'nickname') {
                            const nameEl = contactEl.querySelector('.contact-name');
                            if (nameEl) {
                                console.log('Updating contact name from', nameEl.textContent, 'to', nickname);
                                nameEl.textContent = nickname;
                            }
                        }
                    }
                }
            });
        } catch (e) {
            console.error('Failed to apply nicknames on load', e);
        }
    }
    
    // Make function globally accessible for DOMContentLoaded handler
    window.applyNicknamesOnPageLoad = applyNicknamesOnPageLoad;
    
    let currentUserBio = <?= json_encode($user['bio'] ?? '') ?>;
    const currentUserCreatedAt = <?= json_encode($user['created_at'] ?? '') ?>;
    const token = "<?=$token?>";
    const scrollsMaxUploadBytes = <?= json_encode($scrollsMaxUploadBytes) ?>;
    const scrollsMaxUploadLabel = <?= json_encode($scrollsMaxUploadLabel) ?>;
    const scrollComposerIdleStatus = <?= json_encode($scrollComposerIdleStatus) ?>;
    const tutorialCompleted = <?= json_encode($tutorial_completed) ?>;
    const tutorialSkipped = <?= json_encode($tutorial_skipped) ?>;
    window.__QT_SESSION_TOKEN = token;
    function getSessionTokenValue() {
        if (typeof window.__QT_SESSION_TOKEN === 'string' && window.__QT_SESSION_TOKEN) {
            return window.__QT_SESSION_TOKEN;
        }

        return typeof token === 'string' ? token : '';
    }

    function syncAndroidSessionToken() {
        try {
            window.__QT_SESSION_TOKEN = token;
            if (token && window.QuillTalkAndroid && typeof window.QuillTalkAndroid.saveSessionToken === 'function') {
                window.QuillTalkAndroid.saveSessionToken(token);
            }
        } catch (error) {}
    }

    function notifyAndroidIncomingCallAnswered() {
        try {
            if (window.QuillTalkAndroid && typeof window.QuillTalkAndroid.answerIncomingCall === 'function') {
                window.QuillTalkAndroid.answerIncomingCall();
            }
        } catch (error) {}
    }

    function notifyAndroidIncomingCallRejected() {
        try {
            if (window.QuillTalkAndroid && typeof window.QuillTalkAndroid.rejectIncomingCall === 'function') {
                window.QuillTalkAndroid.rejectIncomingCall();
            }
        } catch (error) {}
    }

    function notifyAndroidCallEnded(reason = 'local_hangup') {
        try {
            if (window.QuillTalkAndroid && typeof window.QuillTalkAndroid.endCurrentCall === 'function') {
                window.QuillTalkAndroid.endCurrentCall(String(reason || 'local_hangup'));
            }
        } catch (error) {}
    }

    setTimeout(syncAndroidSessionToken, 0);
    window.addEventListener('focus', syncAndroidSessionToken);
    let selectedUser = null;
    let lastId = 0;
    let isInitialConversationLoad = false;
    let initialLoadMessageCount = 0;

    function buildGroupChatKey(groupId) {
        const normalizedId = parseInt(groupId, 10);
        return normalizedId > 0 ? `${GROUP_CHAT_PREFIX}${normalizedId}` : '';
    }

    function isGroupChatKey(value) {
        return String(value || '').startsWith(GROUP_CHAT_PREFIX);
    }

    function getGroupIdFromChatKey(value) {
        if (!isGroupChatKey(value)) {
            return 0;
        }
        return parseInt(String(value).slice(GROUP_CHAT_PREFIX.length), 10) || 0;
    }

    function isAiChatKey(value) {
        return String(value || '').startsWith('ai:');
    }

    function getAiChatIdFromChatKey(value) {
        if (!isAiChatKey(value)) {
            return 0;
        }
        return parseInt(String(value).slice(3), 10) || 0;
    }

    function getChatTypeFromKey(value) {
        if (isGroupChatKey(value)) {
            return 'group';
        }
        if (isAiChatKey(value)) {
            return 'ai';
        }
        return 'direct';
    }

    function getDirectUserIdFromChatKey(value) {
        return (isGroupChatKey(value) || isAiChatKey(value)) ? '' : String(value || '');
    }

    function getMessageChatKey(msg) {
        if (msg && msg.group_id) {
            return buildGroupChatKey(msg.group_id);
        }

        if (msg && msg.chat_key) {
            return String(msg.chat_key);
        }

        if (!msg) {
            return '';
        }

        if (msg && msg.is_ai_response) {
            const originId = msg.original_user_id ? String(msg.original_user_id) : '';
            const recipientId = msg.recipient_id ? String(msg.recipient_id) : '';
            if (originId && recipientId) {
                if (originId === String(currentUserId)) {
                    return recipientId;
                }
                if (recipientId === String(currentUserId)) {
                    return originId;
                }
            }
        }

        const directTarget = msg.self ? msg.recipient_id : msg.sender_id;
        return directTarget ? String(directTarget) : '';
    }

    function getMessageServerId(input) {
        if (!input) {
            return 0;
        }

        let rawValue = '';
        if (typeof input === 'object' && input.dataset) {
            rawValue = String(input.dataset.messageId || input.dataset.id || '').trim();
        } else if (typeof input === 'object') {
            rawValue = String(
                input.message_id
                ?? input.server_id
                ?? input.storage_id
                ?? input.id
                ?? ''
            ).trim();
        } else {
            rawValue = String(input || '').trim();
        }

        const parsed = Number(rawValue);
        return Number.isFinite(parsed) ? parsed : 0;
    }

    function getMessageClientId(msg, fallbackChatKey = '') {
        const explicitClientId = String(msg && msg.client_id ? msg.client_id : '').trim();
        if (explicitClientId) {
            return explicitClientId;
        }

        const rawId = getMessageServerId(msg);
        if (rawId > 0) {
            const resolvedChatKey = String(
                (msg && (msg.chat_key || getMessageChatKey(msg)))
                || fallbackChatKey
                || ''
            ).trim();
            if (resolvedChatKey.startsWith('ai:')) {
                return `ai-msg-${rawId}`;
            }
            return String(rawId);
        }

        return String((msg && msg.id) || '').trim();
    }

    function findMessageElementByServerId(messageId) {
        if (!chatBox) {
            return null;
        }

        const normalizedMessageId = Number(messageId || 0);
        if (!(normalizedMessageId > 0)) {
            return null;
        }

        return chatBox.querySelector(`.message[data-message-id="${normalizedMessageId}"]`);
    }

    function findMessageElementByAnyId(messageId) {
        if (!chatBox) {
            return null;
        }

        const normalizedMessageId = Number(messageId || 0);
        if (!Number.isFinite(normalizedMessageId) || normalizedMessageId === 0) {
            return null;
        }

        return chatBox.querySelector(`.message[data-message-id="${normalizedMessageId}"]`);
    }

    function getChatMessageType(chatKey = String(selectedUser || '')) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (normalizedChatKey.startsWith('ai:')) {
            return 'ai';
        }
        return isGroupChatKey(normalizedChatKey) ? 'group' : 'direct';
    }

    // Now define the helper functions globally so they can be called from anywhere
    function parseCallEventMessage(message) {
        if (typeof message !== 'string' || !message.startsWith(CALL_EVENT_PREFIX)) {
            return null;
        }

        const payload = message.slice(CALL_EVENT_PREFIX.length);
        const [type, callerIdRaw] = payload.split('|');
        if (!type) {
            return null;
        }

        return {
            type,
            callerId: callerIdRaw ? String(callerIdRaw) : ''
        };
    }

    function parseGroupCallMessage(message) {
        if (typeof message !== 'string' || !message.startsWith(GROUP_CALL_MESSAGE_PREFIX)) return null;
        try {
            const parsed = JSON.parse(message.slice(GROUP_CALL_MESSAGE_PREFIX.length));
            return parsed && typeof parsed === 'object' ? parsed : null;
        } catch (e) {
            console.warn('[parseGroupCallMessage] JSON parse failed:', e, message.slice(0, 100));
            return null;
        }
    }

    function parseGroupNewsMessage(message) {
        if (typeof message !== 'string' || !message.startsWith(GROUP_NEWS_MESSAGE_PREFIX)) {
            return null;
        }

        try {
            const parsed = JSON.parse(message.slice(GROUP_NEWS_MESSAGE_PREFIX.length));
            return parsed && typeof parsed === 'object' && parsed.type
                ? parsed
                : null;
        } catch (error) {
            console.warn('[parseGroupNewsMessage] JSON parse failed:', error, message.slice(0, 100));
            return null;
        }
    }

    function getGroupNewsSentence(payload) {
        const news = payload && typeof payload === 'object' ? payload : {};
        const subjectName = normalizeContactPreviewBody(news.subject_name, 'Someone');
        const roleLabel = normalizeContactPreviewBody(news.role_label, 'Member');
        const durationText = normalizeContactPreviewBody(news.duration_text, 'a while');

        if (news.type === 'member_invited') {
            return `${subjectName} was invited to the group chat.`;
        }

        if (news.type === 'role_changed') {
            return `${subjectName}'s role was changed to ${roleLabel}.`;
        }

        if (news.type === 'member_timed_out') {
            return `${subjectName} was timed out for ${durationText}.`;
        }

        if (news.type === 'member_removed') {
            return `${subjectName} was removed from the group chat.`;
        }

        return 'Group chat news.';
    }

    // ── Stopwatch ──────────────────────────────────────────────────────────────
    let stopwatchInterval = null;
    let stopwatchStartTime = null;
    const callStopwatchEl = document.getElementById('callStopwatch');

    function formatStopwatch(ms) {
        const totalSec = Math.floor(ms / 1000);
        const h = Math.floor(totalSec / 3600);
        const m = Math.floor((totalSec % 3600) / 60);
        const s = totalSec % 60;
        const pad = n => String(n).padStart(2, '0');
        return h > 0 ? `${pad(h)}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
    }

    function startStopwatch(serverStartIso = null, serverStartUnix = null) {
        // Prefer Unix timestamp (no timezone ambiguity)
        if (serverStartUnix && serverStartUnix > 0) {
            stopwatchStartTime = serverStartUnix * 1000; // convert seconds → ms
        } else if (serverStartIso) {
            const normalized = String(serverStartIso).replace(' ', 'T') + 'Z';
            const parsed = new Date(normalized).getTime();
            stopwatchStartTime = (!isNaN(parsed) && parsed > 0) ? parsed : Date.now();
        } else {
            stopwatchStartTime = Date.now();
        }
        if (stopwatchInterval) clearInterval(stopwatchInterval);
        stopwatchInterval = setInterval(() => {
            if (callStopwatchEl) callStopwatchEl.textContent = formatStopwatch(Math.max(0, Date.now() - stopwatchStartTime));
        }, 1000);
        if (callStopwatchEl) callStopwatchEl.textContent = formatStopwatch(Math.max(0, Date.now() - stopwatchStartTime));
    }

    function freezeStopwatch() {
        if (stopwatchInterval) {
            clearInterval(stopwatchInterval);
            stopwatchInterval = null;
        }
    }

    function stopStopwatch() {
        freezeStopwatch();
        if (callStopwatchEl) callStopwatchEl.textContent = '';
        stopwatchStartTime = null;
    }

    function getAttachmentExtension(value = '') {
        const normalizedValue = String(value || '').split('#')[0].split('?')[0];
        const parts = normalizedValue.split('.');
        if (parts.length < 2) {
            return '';
        }
        return String(parts.pop() || '').trim().toLowerCase();
    }

    function isVideoAttachmentDescriptor(mime = '', value = '') {
        const normalizedMime = String(mime || '').trim().toLowerCase();
        if (normalizedMime.startsWith('video/')) {
            return true;
        }
        return VIDEO_ATTACHMENT_EXTENSIONS.has(getAttachmentExtension(value));
    }

    function normalizeAttachmentKind(rawKind, payload = {}) {
        const normalizedKind = String(rawKind || '').trim().toLowerCase();
        if (normalizedKind === 'image' || normalizedKind === 'audio' || normalizedKind === 'video') {
            return normalizedKind;
        }

        const mime = String(payload.mime || '');
        const name = String(payload.name || payload.url || '');
        if (isVideoAttachmentDescriptor(mime, name)) {
            return 'video';
        }

        return 'file';
    }

    function parseAttachmentMessage(message) {
        if (typeof message !== 'string' || !message.startsWith(ATTACHMENT_MESSAGE_PREFIX)) {
            return null;
        }

        try {
            const payload = JSON.parse(message.slice(ATTACHMENT_MESSAGE_PREFIX.length));
            if (!payload || typeof payload !== 'object' || (!payload.url && !payload.pending)) {
                return null;
            }

            return {
                kind: normalizeAttachmentKind(payload.kind, payload),
                url: payload.url ? String(payload.url) : '',
                name: payload.name ? String(payload.name) : 'File',
                mime: payload.mime ? String(payload.mime) : '',
                size: Number(payload.size || 0),
                caption: payload.caption ? String(payload.caption) : '',
                duration: Number(payload.duration || 0),
                waveform: Array.isArray(payload.waveform) ? payload.waveform : [],
                pending: payload.pending === true || payload.pending === 1 || payload.pending === '1',
                loadingLabel: payload.loading_label ? String(payload.loading_label) : '',
                aiGenerated: payload.ai_generated === true || payload.ai_generated === 1 || payload.ai_generated === '1'
            };
        } catch (e) {
            console.warn('Failed to parse attachment message.', e);
            return null;
        }
    }

    function clampTableMessageDimension(value, fallback = 3) {
        const numericValue = Number.parseInt(value, 10);
        if (!Number.isFinite(numericValue)) {
            return Math.min(TABLE_MESSAGE_MAX_DIMENSION, Math.max(TABLE_MESSAGE_MIN_DIMENSION, Number(fallback) || 3));
        }

        return Math.min(
            TABLE_MESSAGE_MAX_DIMENSION,
            Math.max(TABLE_MESSAGE_MIN_DIMENSION, numericValue)
        );
    }

    function sanitizeTableMessageCellValue(value) {
        return String(value == null ? '' : value)
            .replace(/\r\n?/g, '\n')
            .replace(/\u00a0/g, ' ')
            .trim();
    }

    function createTableMessageCells(rows, cols, sourceCells = []) {
        const nextRows = clampTableMessageDimension(rows);
        const nextCols = clampTableMessageDimension(cols);
        const normalizedSource = Array.isArray(sourceCells) ? sourceCells : [];

        return Array.from({ length: nextRows }, (_, rowIndex) => (
            Array.from({ length: nextCols }, (_, colIndex) => sanitizeTableMessageCellValue(
                normalizedSource[rowIndex] && Array.isArray(normalizedSource[rowIndex])
                    ? normalizedSource[rowIndex][colIndex]
                    : ''
            ))
        ));
    }

    function normalizeTableMessagePayload(payload) {
        if (!payload || typeof payload !== 'object') {
            return null;
        }

        const rows = clampTableMessageDimension(payload.rows, 3);
        const cols = clampTableMessageDimension(payload.cols, 3);
        const cells = createTableMessageCells(rows, cols, payload.cells);
        const caption = String(payload.caption || '').trim();

        return {
            rows,
            cols,
            cells,
            caption
        };
    }

    function parseTableMessage(message) {
        if (typeof message !== 'string' || !message.startsWith(TABLE_MESSAGE_PREFIX)) {
            return null;
        }

        try {
            return normalizeTableMessagePayload(JSON.parse(message.slice(TABLE_MESSAGE_PREFIX.length)));
        } catch (error) {
            console.warn('Failed to parse table message.', error);
            return null;
        }
    }

    function normalizeGameMessagePayload(payload) {
        if (!payload || typeof payload !== 'object') {
            return null;
        }

        const gameId = Math.max(0, Number(payload.game_id || payload.gameId || 0) || 0);
        const gameType = String(payload.game_type || payload.gameType || '').trim().toLowerCase();
        if (!gameId || !gameType) {
            return null;
        }

        return {
            gameId,
            gameType,
            label: gameType === SIDEQUEST_GAME_CHESS
                ? 'Chess'
                : (
                    gameType === SIDEQUEST_GAME_CHECKERS
                        ? 'Checkers'
                        : (
                            gameType === SIDEQUEST_GAME_CONNECT_FOUR
                                ? 'Connect Four'
                                : (
                                    gameType === SIDEQUEST_GAME_SKETCHOFF
                                        ? 'Sketchoff'
                                        : (String(payload.label || gameType).trim() || 'Game')
                                )
                        )
                )
        };
    }

    function parseGameMessage(message) {
        if (typeof message !== 'string' || !message.startsWith(GAME_MESSAGE_PREFIX)) {
            return null;
        }

        try {
            return normalizeGameMessagePayload(JSON.parse(message.slice(GAME_MESSAGE_PREFIX.length)));
        } catch (error) {
            console.warn('Failed to parse game message.', error);
            return null;
        }
    }

    function getGameMessageLabel(gameMessage) {
        const normalized = normalizeGameMessagePayload(gameMessage);
        return normalized ? normalized.label : 'Game';
    }

    function buildTableMessageString(tableData, caption = '') {
        const normalized = normalizeTableMessagePayload({
            ...(tableData && typeof tableData === 'object' ? tableData : {}),
            caption: String(caption || '').trim()
        });
        return normalized ? `${TABLE_MESSAGE_PREFIX}${JSON.stringify(normalized)}` : '';
    }

    function getTableMessageSummary(tableData) {
        const normalized = normalizeTableMessagePayload(tableData);
        if (!normalized) {
            return 'Table';
        }

        return normalized.caption || `${normalized.rows} x ${normalized.cols} table`;
    }

    function getGamePreviewText(gameMessage, starterName = 'Someone') {
        const label = getGameMessageLabel(gameMessage);
        return `${starterName} started the ${label} game.`;
    }

    function isEmojiOnlyMessageText(value) {
        const normalizedValue = typeof value === 'string' ? value.trim() : '';
        if (!normalizedValue || !emojiOnlyMessagePattern) {
            return false;
        }

        return emojiOnlyMessagePattern.test(normalizedValue);
    }

    function isOutgoingCallEventForUser(callEvent, viewerId = currentUserId) {
        return !!(callEvent && callEvent.callerId && String(callEvent.callerId) === String(viewerId));
    }

    function getCallEventPreviewText(message) {
        const attachment = parseAttachmentMessage(message);
        if (attachment) {
            if (attachment.kind === 'image') {
                return 'Photo';
            }

            if (attachment.kind === 'video') {
                return 'Video';
            }

            if (attachment.kind === 'audio') {
                return 'Voice message';
            }

            return attachment.name || 'File';
        }

        const tableMessage = parseTableMessage(message);
        if (tableMessage) {
            return getTableMessageSummary(tableMessage);
        }

        const gameMessage = parseGameMessage(message);
        if (gameMessage) {
            return getGameMessageLabel(gameMessage);
        }

        const event = parseCallEventMessage(message);
        if (!event) {
            return message;
        }

        if (event.type === 'missed') return 'Missed call';
        if (event.type === 'ended') {
            return isOutgoingCallEventForUser(event) ? 'Outgoing call' : 'Incoming call';
        }
        return 'Call';
    }

    function parseContactActivityValue(value) {
        if (value === null || value === undefined || value === '') return 0;
        const normalized = String(value).trim();
        if (!normalized) return 0;
        if (/^\d+(?:\.\d+)?$/.test(normalized)) {
            const numeric = Number(normalized);
            return Number.isFinite(numeric) ? numeric : 0;
        }
        return parseServerDateTimeMs(normalized);
    }

    function parseServerDateTimeMs(value) {
        if (value === null || value === undefined || value === '') {
            return 0;
        }

        if (value instanceof Date) {
            const timestamp = value.getTime();
            return Number.isNaN(timestamp) ? 0 : timestamp;
        }

        const normalizedValue = String(value).trim();
        if (!normalizedValue) {
            return 0;
        }

        // Always treat server datetimes as UTC by appending Z if no timezone info present
        const hasTimezone = /[Zz]$/.test(normalizedValue) || /[+-]\d{2}:?\d{2}$/.test(normalizedValue);
        const isoValue = normalizedValue.includes('T')
            ? normalizedValue
            : normalizedValue.replace(' ', 'T');
        const withTz = hasTimezone ? isoValue : isoValue + 'Z';
        const parsed = Date.parse(withTz);
        return Number.isNaN(parsed) ? 0 : parsed;
    }

    function isFutureDateValue(value) {
        const timestamp = parseServerDateTimeMs(value);
        return timestamp > Date.now();
    }

    function getEffectiveContactActivityValue(contactEl) {
        if (!contactEl) {
            return 0;
        }

        return Math.max(
            parseContactActivityValue(contactEl.dataset.lastActivity || ''),
            parseServerDateTimeMs(contactEl.dataset.lastActivity || ''),
            parseServerDateTimeMs(contactEl.dataset.createdAt || '')
        );
    }

    function formatDurationParts(totalMilliseconds) {
        const totalSeconds = Math.max(0, Math.floor(totalMilliseconds / 1000));
        const days = Math.floor(totalSeconds / 86400);
        const hours = Math.floor((totalSeconds % 86400) / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        if (days > 0) {
            return `${days}d ${hours}h ${minutes}m`;
        }
        if (hours > 0) {
            return `${hours}h ${minutes}m ${seconds}s`;
        }
        if (minutes > 0) {
            return `${minutes}m ${seconds}s`;
        }
        return `${seconds}s`;
    }

    function getNormalizedContactsSearchQuery() {
        const searchInput = document.getElementById('contactsSearchInput');
        return searchInput ? searchInput.value.trim().toLowerCase() : '';
    }

    function getContactSearchRank(contactEl, query) {
        if (!query) {
            return 0;
        }

        const displayName = String(contactEl.dataset.displayName || '').trim().toLowerCase();
        const username = String(contactEl.dataset.username || '').trim().toLowerCase();
        const id = String(contactEl.dataset.id || '').trim().toLowerCase();

        if (displayName.startsWith(query)) return 0;
        if (username.startsWith(query)) return 1;
        if (displayName.includes(query)) return 2;
        if (username.includes(query)) return 3;
        if (id.includes(query)) return 4;
        return Number.POSITIVE_INFINITY;
    }

    function getCurrentContactViewValue() {
        return typeof window.__qtGetActiveContactView === 'function'
            ? window.__qtGetActiveContactView()
            : 'contacts';
    }

    function isDesktopAuxContactView(view = getCurrentContactViewValue()) {
        return !isMobileViewport() && (view === 'history' || view === 'archived' || view === 'scrolls');
    }

    function getSidebarContactView(view = getCurrentContactViewValue()) {
        return isDesktopAuxContactView(view) ? 'contacts' : view;
    }

    function shouldUseCollapsedDesktopContactRail(view = getCurrentContactViewValue()) {
        return !isMobileViewport() && view !== 'contacts';
    }

    function getContactCreatedValue(contactEl) {
        return contactEl ? parseServerDateTimeMs(contactEl.dataset.createdAt || '') : 0;
    }

    let contactsSortMode = 'recent';

    function isAiContactElement(contactEl) {
        const contactId = String(contactEl && contactEl.dataset ? (contactEl.dataset.id || '') : '').trim().toLowerCase();
        return contactId.startsWith('ai:');
    }

    function contactMatchesSortMode(contactEl) {
        if (!contactEl) {
            return false;
        }

        const isAiChat = isAiContactElement(contactEl);
        if (contactsSortMode === 'ai') {
            return isAiChat;
        }

        if (isAiChat && contactsSortMode !== 'recent') {
            return false;
        }

        if (contactsSortMode === 'unread') {
            return contactEl.classList.contains('unread');
        }

        if (contactsSortMode === 'groups') {
            return getContactChatType(contactEl) === 'group';
        }

        return true;
    }

    function compareContactsForSort(a, b, query = '') {
        const aPinned = typeof window.__qtIsPinnedChatId === 'function'
            ? !!window.__qtIsPinnedChatId(a && a.dataset ? a.dataset.id || '' : '')
            : false;
        const bPinned = typeof window.__qtIsPinnedChatId === 'function'
            ? !!window.__qtIsPinnedChatId(b && b.dataset ? b.dataset.id || '' : '')
            : false;
        if (aPinned !== bPinned) {
            return aPinned ? -1 : 1;
        }

        if (query) {
            const aRank = getContactSearchRank(a, query);
            const bRank = getContactSearchRank(b, query);
            if (aRank !== bRank) {
                return aRank - bRank;
            }
        }

        if (contactsSortMode === 'oldest' || contactsSortMode === 'newest') {
            const aCreated = getContactCreatedValue(a);
            const bCreated = getContactCreatedValue(b);
            if (aCreated !== bCreated) {
                return contactsSortMode === 'oldest'
                    ? aCreated - bCreated
                    : bCreated - aCreated;
            }
        } else {
            const aValue = getEffectiveContactActivityValue(a);
            const bValue = getEffectiveContactActivityValue(b);
            if (aValue !== bValue) {
                return bValue - aValue;
            }
        }

        const aName = (a.dataset.displayName || a.dataset.username || '').toLowerCase();
        const bName = (b.dataset.displayName || b.dataset.username || '').toLowerCase();
        return aName.localeCompare(bName);
    }

    function contactMatchesView(contactEl, view, query = '') {
        const isArchived = typeof window.__qtIsArchivedContactId === 'function'
            ? !!window.__qtIsArchivedContactId(contactEl.dataset.id || '')
            : false;
        const matchesQuery = !query || Number.isFinite(getContactSearchRank(contactEl, query));
        const matchesMode = contactMatchesSortMode(contactEl);
        const matchesView = view === 'history' || view === 'scrolls'
            ? false
            : (view === 'archived' ? isArchived : !isArchived);
        return matchesQuery && matchesMode && matchesView;
    }

    function sortContactsList() {
        const contactListEl = document.getElementById('contactsList');
        const searchStatusEl = document.getElementById('contactsSearchStatus');
        if (!contactListEl) return;
        const activeView = typeof window.__qtGetActiveContactView === 'function'
            ? window.__qtGetActiveContactView()
            : 'contacts';
        const isDesktopAuxView = isDesktopAuxContactView(activeView);
        const query = isDesktopAuxView ? '' : getNormalizedContactsSearchQuery();
        const sidebarView = getSidebarContactView(activeView);
        const contacts = [...contactListEl.querySelectorAll('.contact')];
        contacts.sort((a, b) => compareContactsForSort(a, b, query));

        let visibleCount = 0;
        contacts.forEach(contact => {
            if (typeof window.__qtEnsureContactActionControls === 'function') {
                window.__qtEnsureContactActionControls(contact);
            }
            if (typeof window.__qtUpdateContactActionControls === 'function') {
                window.__qtUpdateContactActionControls(contact);
            }
            const shouldShow = contactMatchesView(contact, sidebarView, query);
            contact.hidden = !shouldShow;
            contact.style.display = shouldShow ? '' : 'none';
            if (shouldShow) {
                visibleCount += 1;
            }
            contactListEl.appendChild(contact);
        });

        const shouldHideEmptyCategoryContacts = !query
            && sidebarView === 'contacts'
            && visibleCount === 0
            && ['unread', 'groups', 'ai'].includes(contactsSortMode);
        const shouldHideContactsList = (!isDesktopAuxView && (sidebarView === 'history' || sidebarView === 'scrolls'))
            || shouldHideEmptyCategoryContacts;
        contactListEl.hidden = shouldHideContactsList;

        if (typeof window.__qtUpdateArchivedEmptyState === 'function') {
            window.__qtUpdateArchivedEmptyState({ visibleCount: sidebarView === 'archived' ? visibleCount : 0, query });
        }

        if (isDesktopAuxContactView(activeView) && activeView === 'archived' && typeof window.__qtRenderDesktopArchivedContacts === 'function') {
            window.__qtRenderDesktopArchivedContacts(contacts, query);
        }

        if (searchStatusEl) {
            if (activeView === 'history' || activeView === 'scrolls' || isDesktopAuxView) {
                searchStatusEl.hidden = true;
                searchStatusEl.textContent = '';
                delete searchStatusEl.dataset.state;
                return;
            }
            const statusView = isDesktopAuxContactView(activeView) ? activeView : sidebarView;
            const statusCount = contacts.filter(contact => contactMatchesView(contact, statusView, query)).length;
            const isAiMode = contactsSortMode === 'ai';
            if (query && statusCount === 0) {
                searchStatusEl.hidden = false;
                searchStatusEl.dataset.state = 'error';
                searchStatusEl.textContent = statusView === 'archived'
                    ? (isAiMode ? 'No archived AI chats match your search.' : 'No archived chats match your search.')
                    : (isAiMode ? 'No AI chats match your search.' : 'No chats match your search.');
            } else if (query) {
                searchStatusEl.hidden = false;
                searchStatusEl.dataset.state = '';
                searchStatusEl.textContent = statusView === 'archived'
                    ? (isAiMode
                        ? `${statusCount} archived AI chat${statusCount === 1 ? '' : 's'} found.`
                        : `${statusCount} archived chat${statusCount === 1 ? '' : 's'} found.`)
                    : (isAiMode
                        ? `${statusCount} AI chat${statusCount === 1 ? '' : 's'} found.`
                        : `${statusCount} chat${statusCount === 1 ? '' : 's'} found.`);
            } else {
                searchStatusEl.hidden = true;
                searchStatusEl.textContent = '';
                delete searchStatusEl.dataset.state;
            }
        }

        if (typeof renderMobileContactsStrip === 'function') {
            renderMobileContactsStrip();
        }
    }

    function moveContactToTop(userId) {
        const contactListEl = document.getElementById('contactsList');
        const contact = document.querySelector(`.contact[data-id="${userId}"]`);
        if (!contact || !contactListEl || contact.parentElement !== contactListEl) return;
        sortContactsList();
    }

    const contactsSearchInputEl = document.getElementById('contactsSearchInput');
    if (contactsSearchInputEl) {
        contactsSearchInputEl.addEventListener('input', () => {
            sortContactsList();
        });
    }

    function formatContactPreviewTime(ts) {
        return formatCompactRelativeTimestamp(ts, { includeWeeks: true });
    }

    // Make formatContactPreviewTime globally accessible for AI chat loading
    window.formatContactPreviewTime = formatContactPreviewTime;

    function normalizeContactPreviewBody(value, fallback = 'Message') {
        const normalized = typeof value === 'string'
            ? value.replace(/\s+/g, ' ').trim()
            : '';
        return normalized || fallback;
    }

    function setContactPreviewContent(preview, mainText, createdAt) {
        try {
            if (!preview) {
                return;
            }

            preview.textContent = '';

            const main = document.createElement('span');
            main.className = 'contact-preview-main';
            main.textContent = normalizeContactPreviewBody(mainText);
            preview.appendChild(main);

            const timeText = formatContactPreviewTime(createdAt);
            if (!timeText) {
                return;
            }

            const separator = document.createElement('span');
            separator.className = 'contact-preview-separator';
            separator.textContent = '|';
            preview.appendChild(separator);

            const time = document.createElement('span');
            time.className = 'contact-preview-time';
            time.textContent = timeText;
            preview.appendChild(time);
        } catch (error) {
            console.warn('Unable to render contact preview.', error);
            if (preview) {
                preview.textContent = normalizeContactPreviewBody(mainText);
            }
        }
    }

    // Make setContactPreviewContent globally accessible for AI chat loading
    window.setContactPreviewContent = setContactPreviewContent;

    function updateContactPreview(userId, msg, promote = false) {
        const chatKey = String(userId || getMessageChatKey(msg) || '');
        if (!chatKey) return;

        // Find contact element by dataset instead of CSS selector to avoid
        // selector-escaping issues when chat keys contain unusual characters.
        const contact = Array.from(document.querySelectorAll('.contact')).find(el => String(el.dataset.id || '') === chatKey);
        if (!contact) return;

        const preview = contact.querySelector('.contact-preview');
        if (!preview) return;
        if (_draftPreviewElements.has(chatKey) && !promote) {
            return;
        }
        preview.classList.remove('is-draft');

        const currentActivity = parseContactActivityValue(contact.dataset.lastActivity || '');
        const messageActivity = msg && msg.created_at
            ? parseContactActivityValue(msg.created_at)
            : 0;

        if (messageActivity) {
            contact.dataset.lastActivity = String(Math.max(currentActivity, messageActivity));
        }

        const isGroupChat = (contact.dataset.chatType || getChatTypeFromKey(chatKey)) === 'group';
        const isMe =
            msg.self === true ||
            parseInt(msg.sender_id, 10) === parseInt(currentUserId, 10);
        const isAiResponse = !!(msg && (msg.is_ai_response === true || msg.is_ai_response === 1 || msg.is_ai_response === '1'));
        const senderName = isMe
            ? 'You'
            : isAiResponse
                ? normalizeContactPreviewBody(
                    (msg && msg.sender_display_name) || 'QuillTalk AI',
                    'QuillTalk AI'
                )
            : (isGroupChat
                ? normalizeContactPreviewBody(
                    (msg && msg.sender_display_name)
                        || userNamesMap[String(msg && msg.sender_id ? msg.sender_id : '')]
                        || 'Someone',
                    'Someone'
                )
                : (userNamesMap[chatKey]
                    || ((contact.querySelector('.contact-name') && contact.querySelector('.contact-name').textContent)
                        ? contact.querySelector('.contact-name').textContent.trim()
                        : 'User')));

        const callEvent = parseCallEventMessage(msg.message);
        if (callEvent) {
            setContactPreviewContent(preview, getCallEventPreviewText(msg.message), msg.created_at);
            if (promote) moveContactToTop(userId);
            return;
        }

        const groupCallMsg = parseGroupCallMessage(msg.message);
        if (groupCallMsg) {
            setContactPreviewContent(preview, '📞 Group Call', msg.created_at);
            if (promote) moveContactToTop(userId);
            return;
        }

        const groupNews = parseGroupNewsMessage(msg.message);
        if (groupNews) {
            setContactPreviewContent(preview, getGroupNewsSentence(groupNews), msg.created_at);
            if (promote) moveContactToTop(chatKey);
            return;
        }

        const gameMessage = parseGameMessage(msg.message);
        if (gameMessage) {
            setContactPreviewContent(preview, getGamePreviewText(gameMessage, msg.self ? 'You' : senderName), msg.created_at);
            if (promote) moveContactToTop(chatKey);
            return;
        }

        const tableMessage = parseTableMessage(msg.message);
        if (tableMessage) {
            setContactPreviewContent(preview, `${senderName}: ${getTableMessageSummary(tableMessage)}`, msg.created_at);
            if (promote) moveContactToTop(chatKey);
            return;
        }

        const pollMessage = parsePollMessage(msg.message);
        if (pollMessage) {
            setContactPreviewContent(preview, `${senderName} started a poll.`, msg.created_at);
            if (promote) moveContactToTop(chatKey);
            return;
        }

        const attachment = parseAttachmentMessage(msg.message);
        if (attachment) {
            const attachmentPreviewText = (attachment.kind === 'image' || attachment.kind === 'video')
                ? `${senderName} sent an attachment`
                : `${senderName}: ${getCallEventPreviewText(msg.message)}`;
            setContactPreviewContent(preview, attachmentPreviewText, msg.created_at);
            if (promote) moveContactToTop(chatKey);
            return;
        }

        setContactPreviewContent(
            preview,
            `${senderName}: ${getCallEventPreviewText(msg.message)}`,
            msg.created_at
        );
        if (promote) moveContactToTop(chatKey);
    }

    // Live draft preview: updates the contact list while the composer has text
    const _draftPreviewOriginalStateMap = new Map();
    const _draftPreviewElements = new Map();
    const _composerDraftsByChatKey = new Map();

    // Utility functions needed by draft preview system
    function isMobileViewport() {
        const appHeader = document.querySelector('body > header');
        if (appHeader && window.getComputedStyle(appHeader).display === 'none') {
            return true;
        }
        return window.matchMedia('(max-width: 768px)').matches;
    }

    function rememberMessageSelection() {
        if (!messageInput) {
            return;
        }

        lastMessageSelectionStart = typeof messageInput.selectionStart === 'number'
            ? messageInput.selectionStart
            : messageInput.value.length;
        lastMessageSelectionEnd = typeof messageInput.selectionEnd === 'number'
            ? messageInput.selectionEnd
            : lastMessageSelectionStart;
    }

    function setComposerDraft(chatKey, value = '') {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return;
        }

        const rawValue = typeof value === 'string' ? value : String(value || '');
        if (rawValue.trim()) {
            _composerDraftsByChatKey.set(normalizedChatKey, rawValue);
        } else {
            _composerDraftsByChatKey.delete(normalizedChatKey);
        }
    }

    function restoreComposerDraft(chatKey) {
        if (!messageInput) {
            return;
        }

        const normalizedChatKey = String(chatKey || '');
        const nextValue = normalizedChatKey
            ? String(_composerDraftsByChatKey.get(normalizedChatKey) || '')
            : '';

        if (messageInput.value !== nextValue) {
            messageInput.value = nextValue;
        }

        try {
            const cursorPos = nextValue.length;
            messageInput.setSelectionRange(cursorPos, cursorPos);
        } catch (error) {}
        rememberMessageSelection();
        try { closeCommandPicker(); } catch (e) {}
        try { closeMentionPicker(); } catch (e) {}
        try { closeEmojiPicker(); } catch (e) {}
        try { updateComposerHighlightOverlay(); } catch (e) {}
    }

    function renderDraftPreview(chatKey, draftValue = '') {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey || isMobileViewport()) {
            return;
        }

        const contact = Array.from(document.querySelectorAll('.contact')).find(el => String(el.dataset.id || '') === normalizedChatKey);
        if (!contact) {
            return;
        }

        const preview = contact.querySelector('.contact-preview');
        if (!preview) {
            return;
        }

        const content = normalizeContactPreviewBody(draftValue, '');
        if (!content) {
            clearDraftPreview(normalizedChatKey, true);
            return;
        }

        if (!_draftPreviewOriginalStateMap.has(normalizedChatKey)) {
            _draftPreviewOriginalStateMap.set(normalizedChatKey, {
                html: preview.innerHTML
            });
        }

        preview.innerHTML = '';
        preview.classList.add('is-draft');

        const main = document.createElement('span');
        main.className = 'contact-preview-main';

        const draftLabel = document.createElement('span');
        draftLabel.className = 'draft-label';
        draftLabel.textContent = 'Draft:';
        main.appendChild(draftLabel);

        const textSpan = document.createElement('span');
        textSpan.className = 'draft-text';
        textSpan.textContent = ' ' + content;
        main.appendChild(textSpan);

        preview.appendChild(main);
        _draftPreviewElements.set(normalizedChatKey, true);
    }

    function syncDraftPreviews() {
        if (isMobileViewport()) {
            return;
        }

        Array.from(_draftPreviewElements.keys()).forEach(key => {
            if (!_composerDraftsByChatKey.has(String(key))) {
                clearDraftPreview(key, true);
            }
        });

        Array.from(_composerDraftsByChatKey.entries()).forEach(([chatKey, draftValue]) => {
            renderDraftPreview(chatKey, draftValue);
        });
    }

    function clearDraftPreview(chatKey, restoreOriginal = true) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return;
        }

        if (restoreOriginal && _draftPreviewOriginalStateMap.has(normalizedChatKey)) {
            const contact = Array.from(document.querySelectorAll('.contact')).find(el => String(el.dataset.id || '') === normalizedChatKey);
            if (contact) {
                const preview = contact.querySelector('.contact-preview');
                const originalState = _draftPreviewOriginalStateMap.get(normalizedChatKey) || {};
                if (preview) {
                    preview.innerHTML = typeof originalState.html === 'string' ? originalState.html : '';
                    preview.classList.remove('is-draft');
                }
            }
        }

        if (!restoreOriginal) {
            const contact = Array.from(document.querySelectorAll('.contact')).find(el => String(el.dataset.id || '') === normalizedChatKey);
            if (contact) {
                const preview = contact.querySelector('.contact-preview');
                if (preview) {
                    preview.classList.remove('is-draft');
                }
            }
        }

        _draftPreviewOriginalStateMap.delete(normalizedChatKey);
        _draftPreviewElements.delete(normalizedChatKey);
    }

    function updateDraftPreview() {
        try {
            if (isMobileViewport()) return;
            if (!messageInput) return;
            if (!selectedUser) return;

            const chatKey = String(selectedUser || '');
            const draftValue = String(messageInput.value || '');

            if (!draftValue.trim()) {
                clearDraftPreview(chatKey, true);
                return;
            }

            renderDraftPreview(chatKey, draftValue);
        } catch (err) {
            console.error('[draft] error:', err);
        }
    }


    async function loadContactPreviews() {
        try {
            const res = await fetch(`get_last_messages.php?token=${token}&t=${Date.now()}`);
            if (!res.ok) return;
            const data = await res.json();
            data.forEach(msg => {
                try {
                    const idToUpdate = String(msg.chat_key || msg.friend_id || getMessageChatKey(msg) || '');
                    if (!idToUpdate) {
                        return;
                    }
                    updateContactPreview(idToUpdate, msg, false);
                } catch (error) {
                    console.error('Preview render error:', error, msg);
                }
            });
            syncDraftPreviews();
            sortContactsList();

        } catch (e) {
            console.error("Preview load error:", e);
        }
    }
    (() => {
    const chatBox = document.getElementById('chatBox');
    var scrollChatToBottomAfterSend = function () {
        const activeChatBox = chatBox || document.getElementById('chatBox');
        if (!activeChatBox) {
            return;
        }

        const syncToBottom = () => {
            activeChatBox.scrollTop = activeChatBox.scrollHeight;
        };

        syncToBottom();
        window.requestAnimationFrame(syncToBottom);
        window.setTimeout(syncToBottom, 120);
    };
    window.scrollChatToBottomAfterSend = scrollChatToBottomAfterSend;
    const messageInput = document.getElementById('messageInput');
    const composerHighlightOverlay = document.getElementById('composerHighlightOverlay');
    const composerHighlightOverlayContent = document.getElementById('composerHighlightOverlayContent');
    const attachmentBtn = document.getElementById('attachmentBtn');
    const voiceRecordBtn = document.getElementById('voiceRecordBtn');
    const voiceActionMenu = document.getElementById('voiceActionMenu');
    const emojiBtn = document.getElementById('emojiBtn');
    const emojiPickerGrid = document.getElementById('emojiPickerGrid');
    const emojiPickerSearch = document.getElementById('emojiPickerSearch');
    const emojiCategoryTabs = document.getElementById('emojiCategoryTabs');
    const emojiGrid = document.getElementById('emojiGrid');
    const attachmentInput = document.getElementById('attachmentInput');
    const attachmentPreviewRow = document.getElementById('attachmentPreviewRow');
    const attachmentPreviewCard = document.getElementById('attachmentPreviewCard');
    const translateModal = document.getElementById('translateModal');
    const translateModalClose = document.getElementById('translateModalClose');
    const translateModalSubtitle = document.getElementById('translateModalSubtitle');
    const translateLanguageList = document.getElementById('translateLanguageList');
    const chatForm = document.getElementById('chatForm');
    const sendBtn = document.getElementById('sendBtn');
    const composerActionButtons = document.getElementById('composerActionButtons');
    const composerActionsBackBtn = document.getElementById('composerActionsBackBtn');
    const typingRow = document.querySelector('.typing-row');
    const contactsList = document.getElementById('contactsList');
    const contactsSearchInput = document.getElementById('contactsSearchInput');
    const contactsSearchStatus = document.getElementById('contactsSearchStatus');
    const mobileContactsStripWrap = document.getElementById('mobileContactsStripWrap');
    const mobileContactsStrip = document.getElementById('mobileContactsStrip');
    const mobileContactsScrollbar = document.getElementById('mobileContactsScrollbar');
