    function loadArchivedContactIdsFromStorage() {
        try {
            const raw = localStorage.getItem(CONTACT_ARCHIVE_STORAGE_KEY);
            if (!raw) {
                return new Set();
            }

            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                return new Set(parsed.map(value => String(value || '').trim()).filter(Boolean));
            }

            if (parsed && typeof parsed === 'object') {
                return new Set(
                    Object.keys(parsed)
                        .filter(key => parsed[key])
                        .map(value => String(value || '').trim())
                        .filter(Boolean)
                );
            }
        } catch (error) {
            console.warn('Unable to restore archived contacts from storage.', error);
        }

        return new Set();
    }

    function loadStoredChatIdSet(storageKey) {
        try {
            const raw = localStorage.getItem(storageKey);
            if (!raw) {
                return new Set();
            }

            const parsed = JSON.parse(raw);
            if (!Array.isArray(parsed)) {
                return new Set();
            }

            return new Set(
                parsed
                    .map(value => String(value || '').trim())
                    .filter(Boolean)
            );
        } catch (error) {
            console.warn('Unable to restore stored chat state.', error);
            return new Set();
        }
    }

    function persistStoredChatIdSet(storageKey, valueSet) {
        try {
            localStorage.setItem(storageKey, JSON.stringify(Array.from(valueSet)));
        } catch (error) {
            console.warn('Unable to persist stored chat state.', error);
        }
    }

    function sanitizePinnedMessageRecord(rawRecord, fallbackChatKey = '') {
        if (!rawRecord || typeof rawRecord !== 'object') {
            return null;
        }

        const chatKey = String(rawRecord.chatKey || fallbackChatKey || '').trim();
        const messageId = Number(rawRecord.messageId || 0);
        const snippet = String(rawRecord.snippet || '').trim();
        if (!chatKey || !Number.isFinite(messageId) || messageId === 0 || !snippet) {
            return null;
        }

        return {
            chatKey,
            messageId,
            snippet,
            senderName: String(rawRecord.senderName || '').trim() || 'Message',
            createdAt: String(rawRecord.createdAt || '').trim(),
            rawMessage: String(rawRecord.rawMessage || '').trim()
        };
    }

    function loadPinnedMessagesFromStorage() {
        try {
            const raw = localStorage.getItem(PINNED_MESSAGE_STORAGE_KEY);
            if (!raw) {
                return {};
            }

            const parsed = JSON.parse(raw);
            if (!parsed || typeof parsed !== 'object') {
                return {};
            }

            const nextState = {};
            Object.entries(parsed).forEach(([chatKey, record]) => {
                const sanitized = sanitizePinnedMessageRecord(record, chatKey);
                if (sanitized) {
                    nextState[chatKey] = sanitized;
                }
            });
            return nextState;
        } catch (error) {
            console.warn('Unable to restore pinned messages.', error);
            return {};
        }
    }

    function persistPinnedMessagesToStorage() {
        try {
            localStorage.setItem(PINNED_MESSAGE_STORAGE_KEY, JSON.stringify(pinnedMessagesByChatKey));
        } catch (error) {
            console.warn('Unable to persist pinned messages.', error);
        }
    }

    function persistArchivedContactIdsToStorage() {
        try {
            localStorage.setItem(CONTACT_ARCHIVE_STORAGE_KEY, JSON.stringify(Array.from(archivedContactIds)));
        } catch (error) {
            console.warn('Unable to persist archived contacts.', error);
        }
    }

    function isArchivedContactId(userId) {
        const normalizedUserId = String(userId || '').trim();
        return !!normalizedUserId && archivedContactIds.has(normalizedUserId);
    }

    function isPinnedChatId(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        return !!(normalizedChatKey && pinnedChatIds.has(normalizedChatKey));
    }

    function isManuallyUnreadChatId(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        return !!(normalizedChatKey && manualUnreadChatIds.has(normalizedChatKey));
    }

    function isChatUnreadLocally(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return false;
        }

        if (isManuallyUnreadChatId(normalizedChatKey)) {
            return true;
        }

        const contactEl = getContactElement(normalizedChatKey);
        if (contactEl && (contactEl.classList.contains('unread') || contactEl.querySelector('.unread-badge'))) {
            return true;
        }

        const unreadRow = Array.isArray(unreadOverlayState && unreadOverlayState.rows)
            ? unreadOverlayState.rows.find(row => String(row && (row.chat_key || row.sender_id || '') || '') === normalizedChatKey)
            : null;
        return !!(unreadRow && getUnreadEffectiveCount(unreadRow) > 0);
    }

    function getPinnedMessageRecord(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return null;
        }

        return pinnedMessagesByChatKey[normalizedChatKey] || null;
    }

    function hasRenderablePinnedMessageRecord(record) {
        return !!(
            record
            && Number.isFinite(Number(record.messageId || 0))
            && Number(record.messageId || 0) !== 0
            && (
                String(record.snippet || '').trim()
                || String(record.rawMessage || '').trim()
            )
        );
    }

    function isPinnedMessageForChat(chatKey, messageId) {
        const pinnedRecord = getPinnedMessageRecord(chatKey);
        return !!(pinnedRecord && Number(pinnedRecord.messageId || 0) === Number(messageId || 0));
    }

    function buildPinnedMessageRecord(messageData, senderName = '') {
        const chatKey = String(getMessageChatKey(messageData) || selectedUser || '').trim();
        const messageId = getMessageServerId(messageData);
        if (!chatKey || !Number.isFinite(messageId) || messageId === 0) {
            return null;
        }

        const rawMessage = String(messageData && messageData.message ? messageData.message : '');
        const fallbackMeta = getContactMeta(String(messageData && messageData.sender_id ? messageData.sender_id : ''));
        const isSelfMessage = !!(
            (messageData && (messageData.self === true || messageData.self === 1 || messageData.self === '1'))
            || String(messageData && messageData.sender_id ? messageData.sender_id : '') === String(currentUserId)
        );
        const resolvedSenderName = isSelfMessage
            ? 'You'
            : (String(senderName || '').trim()
                || getDisplayNameForUser(String(messageData && messageData.sender_id ? messageData.sender_id : ''), fallbackMeta, chatKey)
                || 'Message');

        return sanitizePinnedMessageRecord({
            chatKey,
            messageId,
            snippet: getMessageSnippetForReply(rawMessage) || 'Message',
            senderName: resolvedSenderName,
            createdAt: String(messageData && messageData.created_at ? messageData.created_at : ''),
            rawMessage
        }, chatKey);
    }

    function renderPinnedMessageBar(chatKey = selectedUser) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!chatPinnedMessageBar || !chatPinnedMessageText || !chatPinnedMessageJump || !chatPinnedMessageClear) {
            return;
        }

        const record = normalizedChatKey ? getPinnedMessageRecord(normalizedChatKey) : null;
        if (!hasRenderablePinnedMessageRecord(record)) {
            chatPinnedMessageBar.hidden = true;
            chatPinnedMessageBar.setAttribute('aria-hidden', 'true');
            chatPinnedMessageText.textContent = '';
            chatPinnedMessageText.title = '';
            chatPinnedMessageJump.title = '';
            chatPinnedMessageClear.title = '';
            return;
        }

        const summary = `${record.senderName}: ${record.snippet}`;
        chatPinnedMessageText.textContent = summary;
        chatPinnedMessageText.title = summary;
        chatPinnedMessageJump.title = 'Jump to pinned message';
        chatPinnedMessageClear.title = 'Unpin message';
        chatPinnedMessageBar.hidden = false;
        chatPinnedMessageBar.setAttribute('aria-hidden', 'false');
    }

    function setPinnedMessageForChat(chatKey, nextRecord, { showToast = true } = {}) {
        const normalizedChatKey = String(chatKey || '').trim();
        const sanitized = sanitizePinnedMessageRecord(nextRecord, normalizedChatKey);
        if (!normalizedChatKey || !sanitized) {
            return false;
        }

        pinnedMessagesByChatKey[normalizedChatKey] = sanitized;
        persistPinnedMessagesToStorage();
        if (String(selectedUser || '') === normalizedChatKey) {
            renderPinnedMessageBar(normalizedChatKey);
        }
        if (showToast) {
            showToast('Pinned message updated.', 'success');
        }
        return true;
    }

    function clearPinnedMessageForChat(chatKey, { showToast = true } = {}) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey || !pinnedMessagesByChatKey[normalizedChatKey]) {
            return false;
        }

        delete pinnedMessagesByChatKey[normalizedChatKey];
        persistPinnedMessagesToStorage();
        if (String(selectedUser || '') === normalizedChatKey) {
            renderPinnedMessageBar(normalizedChatKey);
        }
        if (showToast) {
            showToast('Pinned message removed.', 'success');
        }
        return true;
    }

    function syncPinnedMessageRecordForMessage(chatKey, messageData, senderName = '') {
        const normalizedChatKey = String(chatKey || getMessageChatKey(messageData) || '').trim();
        if (!normalizedChatKey) {
            return;
        }

        const pinnedRecord = getPinnedMessageRecord(normalizedChatKey);
        const messageId = getMessageServerId(messageData);
        if (
            !pinnedRecord
            || !Number.isFinite(messageId)
            || messageId === 0
            || Number(pinnedRecord.messageId || 0) !== messageId
        ) {
            return;
        }

        const refreshedRecord = buildPinnedMessageRecord(messageData, senderName);
        if (refreshedRecord) {
            setPinnedMessageForChat(normalizedChatKey, refreshedRecord, { showToast: false });
        }
    }

    function clearPinnedMessageIfMatches(chatKey, messageId) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedMessageId = Number(messageId || 0);
        if (!normalizedChatKey || !Number.isFinite(normalizedMessageId) || normalizedMessageId === 0) {
            return;
        }

        if (isPinnedMessageForChat(normalizedChatKey, normalizedMessageId)) {
            clearPinnedMessageForChat(normalizedChatKey, { showToast: false });
        }
    }

    function setPinnedChatState(chatKey, pinned, { showToast = true } = {}) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return false;
        }

        const shouldPin = !!pinned;
        const wasPinned = isPinnedChatId(normalizedChatKey);
        if (shouldPin === wasPinned) {
            return false;
        }

        if (shouldPin) {
            pinnedChatIds.add(normalizedChatKey);
        } else {
            pinnedChatIds.delete(normalizedChatKey);
        }

        persistStoredChatIdSet(PINNED_CHAT_STORAGE_KEY, pinnedChatIds);
        updateContactActionControls(getContactElement(normalizedChatKey));
        sortContactsList();
        if (typeof renderMobileContactsStrip === 'function') {
            renderMobileContactsStrip();
        }
        refreshOpenProfileViews(normalizedChatKey);

        if (showToast) {
            showToast(shouldPin ? 'Pinned chat to the top.' : 'Unpinned chat.', 'success');
        }

        return true;
    }

    function setManualUnreadState(chatKey, unread) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return false;
        }

        const shouldMarkUnread = !!unread;
        const wasMarkedUnread = isManuallyUnreadChatId(normalizedChatKey);
        if (shouldMarkUnread === wasMarkedUnread) {
            return false;
        }

        if (shouldMarkUnread) {
            manualUnreadChatIds.add(normalizedChatKey);
        } else {
            manualUnreadChatIds.delete(normalizedChatKey);
        }

        persistStoredChatIdSet(MANUAL_UNREAD_CHAT_STORAGE_KEY, manualUnreadChatIds);
        return true;
    }

    function markChatAsUnreadExplicit(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return false;
        }

        const changed = setManualUnreadState(normalizedChatKey, true);
        refreshUnreadBadges();
        if (changed) {
            showToast('Marked chat as unread.', 'success');
        }
        return changed;
    }

    async function markChatAsReadExplicit(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return false;
        }

        const wasUnreadBefore = isChatUnreadLocally(normalizedChatKey);
        const hadManualUnread = setManualUnreadState(normalizedChatKey, false);
        await markChatAsRead(normalizedChatKey);
        refreshUnreadBadges();
        if (hadManualUnread || wasUnreadBefore) {
            showToast('Marked chat as read.', 'success');
        } else {
            showToast('Chat is already read.', 'info');
        }
        return true;
    }

    function getActiveContactView() {
        if (activeContactView === 'archived') {
            return 'archived';
        }
        if (activeContactView === 'history') {
            return 'history';
        }
        if (activeContactView === 'scrolls') {
            return 'scrolls';
        }
        return 'contacts';
    }

    function formatDetailedTimestamp(ts) {
        const parsedTimestamp = parseServerDateTimeMs(ts);
        if (!parsedTimestamp) {
            return '';
        }

        return new Date(parsedTimestamp).toLocaleString(undefined, {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: 'numeric',
            minute: '2-digit',
            second: '2-digit'
        });
    }

    function formatCompactRelativeTimestamp(ts, { includeWeeks = true } = {}) {
        try {
            if (!ts) {
                return '';
            }

            const timestamp = parseServerDateTimeMs(ts);
            if (!timestamp) {
                return '';
            }

            const diffMs = Math.max(0, Date.now() - timestamp);
            const minuteMs = 60 * 1000;
            const hourMs = 60 * minuteMs;
            const dayMs = 24 * hourMs;
            const weekMs = 7 * dayMs;
            const monthMs = 30 * dayMs;
            const yearMs = 365 * dayMs;

            if (diffMs < hourMs) {
                return `${Math.max(1, Math.floor(diffMs / minuteMs))}m`;
            }

            if (diffMs < dayMs) {
                return `${Math.max(1, Math.floor(diffMs / hourMs))}h`;
            }

            if (includeWeeks && diffMs < monthMs) {
                if (diffMs < weekMs) {
                    return `${Math.max(1, Math.floor(diffMs / dayMs))}d`;
                }
                return `${Math.max(1, Math.floor(diffMs / weekMs))}w`;
            }

            if (diffMs < monthMs) {
                return `${Math.max(1, Math.floor(diffMs / dayMs))}d`;
            }

            if (diffMs < yearMs) {
                return `${Math.max(1, Math.floor(diffMs / monthMs))}mo`;
            }

            return `${Math.max(1, Math.floor(diffMs / yearMs))}y`;
        } catch (error) {
            console.warn('Unable to format compact relative timestamp.', error);
            return '';
        }
    }

    function getHistoryCurrentUserProfilePic() {
        return normalizeProfilePic(currentUserProfilePic || defaultProfilePic, 'direct');
    }

    function getHistoryTargetDescriptor(rawMessage) {
        const attachment = parseAttachmentMessage(rawMessage);
        if (attachment) {
            if (attachment.kind === 'image') {
                return { kind: 'photo', label: 'photo', display: 'Photo', snippet: '' };
            }
            if (attachment.kind === 'video') {
                return { kind: 'video', label: 'video', display: 'Video', snippet: '' };
            }
            if (attachment.kind === 'audio') {
                return { kind: 'voice', label: 'voice message', display: 'Voice message', snippet: '' };
            }
            return {
                kind: 'attachment',
                label: 'attachment',
                display: attachment.name || 'Attachment',
                snippet: ''
            };
        }

        const tableMessage = parseTableMessage(rawMessage);
        if (tableMessage) {
            return {
                kind: 'table',
                label: 'table',
                display: getTableMessageSummary(tableMessage),
                snippet: ''
            };
        }

        const gameMessage = parseGameMessage(rawMessage);
        if (gameMessage) {
            return {
                kind: 'game',
                label: 'game',
                display: getGameMessageLabel(gameMessage),
                snippet: ''
            };
        }

        if (parsePollMessage(rawMessage)) {
            return { kind: 'poll', label: 'poll', display: 'Poll', snippet: '' };
        }

        if (parseGroupCallMessage(rawMessage)) {
            return { kind: 'group_call', label: 'group call', display: 'Group call', snippet: '' };
        }

        if (parseCallEventMessage(rawMessage)) {
            return { kind: 'call', label: 'call', display: 'Call', snippet: '' };
        }

        const groupNews = parseGroupNewsMessage(rawMessage);
        if (groupNews) {
            const sentence = getGroupNewsSentence(groupNews);
            return {
                kind: 'news',
                label: 'group chat news',
                display: sentence,
                snippet: sentence
            };
        }

        const snippet = getMessageSnippetForReply(rawMessage) || 'Message';
        return {
            kind: 'message',
            label: 'message',
            display: snippet,
            snippet
        };
    }

    function getHistoryMessageBody(rawMessage) {
        const descriptor = getHistoryTargetDescriptor(rawMessage);
        return descriptor.display || 'Message';
    }

    function getHistoryCallText(record) {
        const counterpartName = String(record && record.counterpart_name ? record.counterpart_name : 'this contact');
        const callType = String(record && record.call_type ? record.call_type : 'ended');
        const isOutgoing = String(record && record.caller_id ? record.caller_id : '') === String(currentUserId);

        if (callType === 'missed') {
            return isOutgoing
                ? `${counterpartName} missed your call.`
                : `You missed a call from ${counterpartName}.`;
        }

        return isOutgoing
            ? `You called ${counterpartName}.`
            : `${counterpartName} called you.`;
    }

    function getHistoryReactionText(record) {
        const emojiText = Array.isArray(record && record.emojis) && record.emojis.length
            ? record.emojis.join(', ')
            : 'a reaction';
        const targetDescriptor = getHistoryTargetDescriptor(record && record.target_message ? record.target_message : '');
        const actorId = String(record && record.actor_id ? record.actor_id : '');
        const actorName = String(record && record.actor_name ? record.actor_name : 'Someone');
        const ownerName = String(record && record.message_owner_name ? record.message_owner_name : 'someone');

        if (actorId === String(currentUserId)) {
            return targetDescriptor.kind === 'message'
                ? `You reacted ${emojiText} to ${ownerName}'s message: ${targetDescriptor.display}.`
                : `You reacted ${emojiText} to ${ownerName}'s ${targetDescriptor.label}.`;
        }

        return targetDescriptor.kind === 'message'
            ? `${actorName} reacted ${emojiText} to your message: ${targetDescriptor.display}.`
            : `${actorName} reacted ${emojiText} to your ${targetDescriptor.label}.`;
    }

    function getHistoryReplyText(record) {
        const targetDescriptor = getHistoryTargetDescriptor(record && record.target_message ? record.target_message : '');
        const actorId = String(record && record.actor_id ? record.actor_id : '');
        const actorName = String(record && record.actor_name ? record.actor_name : 'Someone');
        const ownerName = String(record && record.target_owner_name ? record.target_owner_name : 'someone');

        if (actorId === String(currentUserId)) {
            return targetDescriptor.kind === 'message'
                ? `You replied to ${ownerName}'s message: ${targetDescriptor.display}.`
                : `You replied to ${ownerName}'s ${targetDescriptor.label}.`;
        }

        return targetDescriptor.kind === 'message'
            ? `${actorName} replied to your message: ${targetDescriptor.display}.`
            : `${actorName} replied to your ${targetDescriptor.label}.`;
    }

    function getHistoryEventText(record) {
        const eventType = String(record && record.event_type ? record.event_type : '');
        const eventValue = String(record && record.event_value ? record.event_value : '').trim();
        const actorId = String(record && record.actor_id ? record.actor_id : '');
        const actorName = String(record && record.actor_name ? record.actor_name : 'Someone');
        const subjectName = String(record && record.subject_name ? record.subject_name : 'someone');
        const conversationType = String(record && record.conversation_type ? record.conversation_type : '');
        const conversationName = String(record && record.conversation_name ? record.conversation_name : '').trim();
        const quotedValue = eventValue ? `"${eventValue}"` : '';
        const chatContext = conversationType === 'group'
            ? `in group chat ${conversationName || 'Group chat'}`
            : `to ${conversationName || 'this contact'}`;

        if (eventType === 'block') {
            return actorId === String(currentUserId)
                ? `You blocked ${subjectName}.`
                : `${actorName} blocked you.`;
        }

        if (eventType === 'unblock') {
            return actorId === String(currentUserId)
                ? `You unblocked ${subjectName}.`
                : `${actorName} unblocked you.`;
        }

        if (eventType === 'nickname_set') {
            return quotedValue
                ? `You gave ${subjectName} the nickname ${quotedValue}.`
                : `You updated ${subjectName}'s nickname.`;
        }

        if (eventType === 'nickname_removed') {
            return quotedValue
                ? `You removed the nickname ${quotedValue} from ${subjectName}.`
                : `You removed ${subjectName}'s nickname.`;
        }

        if (eventType === 'chat_nickname_set') {
            return quotedValue
                ? `You gave yourself the chat nickname ${quotedValue} ${chatContext}.`
                : `You updated your chat nickname ${chatContext}.`;
        }

        if (eventType === 'chat_nickname_removed') {
            return `You removed your chat nickname ${chatContext}.`;
        }

        if (eventType === 'group_created') {
            return conversationName
                ? `You created the group chat ${conversationName}.`
                : 'You created a group chat.';
        }

        if (eventType === 'group_member_invited') {
            return actorId === String(currentUserId)
                ? (conversationName
                    ? `You invited ${subjectName} to the group chat ${conversationName}.`
                    : `You invited ${subjectName} to the group chat.`)
                : (conversationName
                    ? `You were invited to the group chat ${conversationName}.`
                    : 'You were invited to a group chat.');
        }

        if (eventType === 'group_role_changed') {
            return actorId === String(currentUserId)
                ? `You changed ${subjectName}'s role to ${eventValue || 'Member'}.`
                : `Your role was changed to ${eventValue || 'Member'}.`;
        }

        if (eventType === 'group_member_timed_out') {
            return actorId === String(currentUserId)
                ? `You timed out ${subjectName} for ${eventValue || 'a while'}.`
                : `You were timed out for ${eventValue || 'a while'}.`;
        }

        if (eventType === 'group_member_removed') {
            return actorId === String(currentUserId)
                ? (conversationName
                    ? `You removed ${subjectName} from the group chat ${conversationName}.`
                    : `You removed ${subjectName} from the group chat.`)
                : (conversationName
                    ? `You were removed from the group chat ${conversationName}.`
                    : 'You were removed from a group chat.');
        }

        if (eventType === 'message_edited') {
            return quotedValue
                ? `You edited a message to ${quotedValue}.`
                : 'You edited a message.';
        }

        if (eventType === 'voice_message_rerecorded') {
            return 'You re-recorded a voice message.';
        }

        if (eventType === 'message_deleted_for_me') {
            return quotedValue
                ? `You deleted ${quotedValue} for yourself.`
                : 'You deleted a message for yourself.';
        }

        if (eventType === 'message_deleted_everyone') {
            return actorId === String(currentUserId)
                ? (quotedValue ? `You deleted ${quotedValue} for everyone.` : 'You deleted a message for everyone.')
                : `${actorName} deleted one of your messages.`;
        }

        if (eventType === 'scheduled_message_created') {
            return quotedValue
                ? `You scheduled ${quotedValue} for later ${chatContext}.`
                : `You scheduled a message for later ${chatContext}.`;
        }

        if (eventType === 'scheduled_message_updated') {
            return quotedValue
                ? `You updated a scheduled message to ${quotedValue}.`
                : 'You updated a scheduled message.';
        }

        if (eventType === 'scheduled_message_deleted') {
            return quotedValue
                ? `You deleted the scheduled message ${quotedValue}.`
                : 'You deleted a scheduled message.';
        }

        if (eventType === 'scheduled_message_hidden') {
            return quotedValue
                ? `You hid the scheduled message ${quotedValue}.`
                : 'You hid a scheduled message.';
        }

        if (eventType === 'scheduled_message_sent_now') {
            return quotedValue
                ? `You sent the scheduled message ${quotedValue} right away.`
                : 'You sent a scheduled message right away.';
        }

        if (eventType === 'scheduled_message_sent') {
            return quotedValue
                ? `Your scheduled message ${quotedValue} was sent.`
                : 'Your scheduled message was sent.';
        }

        if (eventType === 'message_translated') {
            return eventValue
                ? `You translated a message to ${eventValue}.`
                : 'You translated a message.';
        }

        if (eventType === 'voice_transcription_used') {
            return 'You transcribed your voice into text.';
        }

        if (eventType === 'voice_message_transcribed') {
            return 'You transcribed a voice message.';
        }

        if (eventType === 'poll_created') {
            return quotedValue
                ? `You created the poll ${quotedValue}.`
                : 'You created a poll.';
        }

        if (eventType === 'poll_voted') {
            return quotedValue
                ? `You voted in the poll ${quotedValue}.`
                : 'You voted in a poll.';
        }

        if (eventType === 'poll_vote_cleared') {
            return quotedValue
                ? `You cleared your response from the poll ${quotedValue}.`
                : 'You cleared your poll response.';
        }

        if (eventType === 'poll_ended') {
            return quotedValue
                ? `You ended the poll ${quotedValue}.`
                : 'You ended a poll.';
        }

        return 'History event';
    }

    function getHistoryFriendRequestText(record) {
        const counterpartName = String(record && record.counterpart_name ? record.counterpart_name : 'this user');
        const status = String(record && record.request_status ? record.request_status : 'pending');
        const role = String(record && record.request_role ? record.request_role : 'receiver');

        if (role === 'sender') {
            if (status === 'accepted') {
                return `${counterpartName} accepted your friend request.`;
            }
            if (status === 'rejected') {
                return `${counterpartName} rejected your friend request.`;
            }
            return `You sent a friend request to ${counterpartName}.`;
        }

        if (status === 'accepted') {
            return `You accepted ${counterpartName}'s friend request.`;
        }
        if (status === 'rejected') {
            return `You rejected ${counterpartName}'s friend request.`;
        }
        return `You received a friend request from ${counterpartName}.`;
    }

    function getHistoryRecordMeta(record) {
        if (!record || typeof record !== 'object') {
            return '';
        }

        if (record.kind === 'message') {
            if (record.conversation_type === 'group') {
                return `In ${record.conversation_name || 'Group chat'}`;
            }
            return `To ${record.conversation_name || 'Contact'}`;
        }

        if (record.kind === 'reaction' && record.conversation_type === 'group') {
            return `In ${record.conversation_name || 'Group chat'}`;
        }

        if (record.kind === 'reply' && record.conversation_type === 'group') {
            return `In ${record.conversation_name || 'Group chat'}`;
        }

        if (record.kind === 'event') {
            if (record.conversation_type === 'group') {
                return `In ${record.conversation_name || 'Group chat'}`;
            }
            if (record.conversation_type === 'direct') {
                return `To ${record.conversation_name || 'Contact'}`;
            }
        }

        return '';
    }

    function getHistoryRecordsForActiveFilter() {
        if (historyActiveFilter === 'all') {
            return historyRecords.slice();
        }

        return historyRecords.filter(record => String(record && record.filter_group ? record.filter_group : '') === historyActiveFilter);
    }

    function updateHistoryFilterButtons() {
        historyFilterButtons.forEach(button => {
            const isActive = String(button.dataset.filter || '') === historyActiveFilter;
            button.classList.toggle('is-active', isActive);
            button.setAttribute('aria-selected', isActive ? 'true' : 'false');
        });
    }

    function buildHistoryIconElement(record) {
        const iconEl = document.createElement('div');
        iconEl.className = 'sidebar-history-item-icon';

        if (record.kind === 'call') {
            const callIcon = document.createElement('div');
            callIcon.className = `call-event-icon sidebar-history-call-icon ${getCallEventIconType({
                type: String(record && record.call_type ? record.call_type : 'ended'),
                callerId: String(record && record.caller_id ? record.caller_id : '')
            })}`;
            const phoneIcon = document.createElement('i');
            phoneIcon.className = 'fa-solid fa-phone';
            callIcon.appendChild(phoneIcon);
            if (String(record && record.call_type ? record.call_type : '') === 'missed') {
                const arrow = document.createElement('span');
                arrow.className = 'missed-call-arrow';
                callIcon.appendChild(arrow);
            }
            iconEl.appendChild(callIcon);
            return iconEl;
        }

        if (record.kind === 'reaction') {
            iconEl.innerHTML = '<i class="fa-regular fa-face-smile" aria-hidden="true"></i>';
            return iconEl;
        }

        if (record.kind === 'reply') {
            iconEl.innerHTML = '<i class="fa-solid fa-reply" aria-hidden="true"></i>';
            return iconEl;
        }

        if (record.kind === 'event') {
            if (record.event_type === 'block' || record.event_type === 'unblock') {
                iconEl.innerHTML = '<i class="fa-solid fa-user-slash" aria-hidden="true"></i>';
            } else if (record.event_type === 'group_created' || record.event_type === 'group_member_invited') {
                iconEl.innerHTML = '<i class="fa-solid fa-user-group" aria-hidden="true"></i>';
            } else if (record.event_type === 'group_role_changed') {
                iconEl.innerHTML = '<i class="fa-solid fa-user-gear" aria-hidden="true"></i>';
            } else if (record.event_type === 'group_member_timed_out') {
                iconEl.innerHTML = '<i class="fa-solid fa-user-clock" aria-hidden="true"></i>';
            } else if (record.event_type === 'group_member_removed') {
                iconEl.innerHTML = '<i class="fa-solid fa-user-minus" aria-hidden="true"></i>';
            } else if (record.event_type === 'message_edited') {
                iconEl.innerHTML = '<i class="fa-solid fa-pen-to-square" aria-hidden="true"></i>';
            } else if (record.event_type === 'voice_message_rerecorded') {
                iconEl.innerHTML = '<i class="fa-solid fa-microphone" aria-hidden="true"></i>';
            } else if (record.event_type === 'message_deleted_for_me' || record.event_type === 'message_deleted_everyone' || record.event_type === 'scheduled_message_deleted' || record.event_type === 'scheduled_message_hidden') {
                iconEl.innerHTML = '<i class="fa-solid fa-trash" aria-hidden="true"></i>';
            } else if (record.event_type === 'scheduled_message_created' || record.event_type === 'scheduled_message_updated' || record.event_type === 'scheduled_message_sent' || record.event_type === 'scheduled_message_sent_now') {
                iconEl.innerHTML = '<i class="fa-regular fa-clock" aria-hidden="true"></i>';
            } else if (record.event_type === 'message_translated') {
                iconEl.innerHTML = '<i class="fa-solid fa-language" aria-hidden="true"></i>';
            } else if (record.event_type === 'voice_transcription_used' || record.event_type === 'voice_message_transcribed') {
                iconEl.innerHTML = '<i class="fa-solid fa-wave-square" aria-hidden="true"></i>';
            } else if (record.event_type === 'poll_created' || record.event_type === 'poll_voted' || record.event_type === 'poll_vote_cleared' || record.event_type === 'poll_ended') {
                iconEl.innerHTML = '<i class="fa-solid fa-square-poll-vertical" aria-hidden="true"></i>';
            } else {
                iconEl.innerHTML = '<i class="fa-solid fa-tag" aria-hidden="true"></i>';
            }
            return iconEl;
        }

        iconEl.innerHTML = '<i class="fa-solid fa-user-plus" aria-hidden="true"></i>';
        return iconEl;
    }

    function renderHistoryRecords() {
        if (!historyPanel || !historyListEl || !historyStatusEl) {
            return;
        }

        historyListEl.innerHTML = '';
        updateHistoryFilterButtons();

        const visibleRecords = getHistoryRecordsForActiveFilter();
        if (!visibleRecords.length) {
            const emptyEl = document.createElement('div');
            emptyEl.className = 'sidebar-history-empty';
            emptyEl.textContent = historyActiveFilter === 'all'
                ? 'No history is available yet.'
                : `No ${historyActiveFilter} history is available yet.`;
            historyListEl.appendChild(emptyEl);
            return;
        }

        visibleRecords.forEach(record => {
            const itemEl = document.createElement('article');
            itemEl.className = `sidebar-history-item sidebar-history-item--${record.kind || 'entry'}`;

            const mainEl = document.createElement('div');
            mainEl.className = 'sidebar-history-item-main';

            if (record.kind === 'message') {
                const avatarEl = document.createElement('img');
                avatarEl.className = 'sidebar-history-item-avatar';
                avatarEl.src = getHistoryCurrentUserProfilePic();
                avatarEl.alt = currentUserDisplayName || 'You';
                applyProfileImageFallback(avatarEl, 'direct');
                mainEl.appendChild(avatarEl);
            } else {
                mainEl.appendChild(buildHistoryIconElement(record));
            }

            const copyEl = document.createElement('div');
            copyEl.className = 'sidebar-history-item-copy';

            const textEl = document.createElement('div');
            if (record.kind === 'message') {
                textEl.className = 'sidebar-history-message-bubble';
                textEl.textContent = getHistoryMessageBody(record.raw_message || '');
            } else {
                textEl.className = 'sidebar-history-item-text';
                if (record.kind === 'call') {
                    textEl.textContent = getHistoryCallText(record);
                } else if (record.kind === 'reaction') {
                    textEl.textContent = getHistoryReactionText(record);
                } else if (record.kind === 'reply') {
                    textEl.textContent = getHistoryReplyText(record);
                } else if (record.kind === 'event') {
                    textEl.textContent = getHistoryEventText(record);
                } else {
                    textEl.textContent = getHistoryFriendRequestText(record);
                }
            }
            copyEl.appendChild(textEl);

            const metaText = getHistoryRecordMeta(record);
            if (metaText) {
                const metaEl = document.createElement('div');
                metaEl.className = 'sidebar-history-item-meta';
                metaEl.textContent = metaText;
                copyEl.appendChild(metaEl);
            }

            mainEl.appendChild(copyEl);

            const timeEl = document.createElement('div');
            timeEl.className = 'sidebar-history-item-time';
            timeEl.textContent = formatDetailedTimestamp(record.created_at || '');

            itemEl.appendChild(mainEl);
            itemEl.appendChild(timeEl);
            historyListEl.appendChild(itemEl);
        });
    }

    function setHistoryStatus(message, state = '') {
        if (!historyStatusEl) {
            return;
        }

        historyStatusEl.textContent = message || '';
        if (state) {
            historyStatusEl.dataset.state = state;
            historyStatusEl.hidden = false;
            return;
        }

        delete historyStatusEl.dataset.state;
        historyStatusEl.hidden = !message;
    }

    function invalidateSidebarHistoryCache({ reloadIfVisible = false } = {}) {
        historyRecords = [];
        if (reloadIfVisible && getActiveContactView() === 'history') {
            loadSidebarHistory({ force: true });
        }
    }

    async function loadSidebarHistory({ force = false } = {}) {
        ensureHistoryPanelUi();
        if (!historyPanel) {
            return;
        }

        if (historyLoadingPromise && !force) {
            return historyLoadingPromise;
        }

        if (!force && historyRecords.length) {
            setHistoryStatus('');
            renderHistoryRecords();
            return historyRecords;
        }

        setHistoryStatus('Loading history...');

        historyLoadingPromise = (async () => {
            try {
                const response = await fetch(`fetch_history.php?token=${encodeURIComponent(token)}&t=${Date.now()}`);
                const data = await response.json().catch(() => ({}));
                if (!response.ok || !data.success || !Array.isArray(data.items)) {
                    throw new Error(data && data.error ? data.error : 'Unable to load history.');
                }

                historyRecords = data.items
                    .filter(record => record && typeof record === 'object')
                    .sort((left, right) => {
                        const leftTs = parseServerDateTimeMs(left && left.created_at ? left.created_at : '');
                        const rightTs = parseServerDateTimeMs(right && right.created_at ? right.created_at : '');
                        return rightTs - leftTs;
                    });

                setHistoryStatus('');
                renderHistoryRecords();
                return historyRecords;
            } catch (error) {
                console.error('Failed to load sidebar history.', error);
                if (!historyRecords.length) {
                    historyListEl.innerHTML = '';
                }
                setHistoryStatus('Unable to load history right now.', 'error');
                renderHistoryRecords();
                return [];
            } finally {
                historyLoadingPromise = null;
            }
        })();

        return historyLoadingPromise;
    }

    function ensureHistoryPanelUi() {
        const sidebarEl = document.getElementById('sidebar');
        if (historyPanel || !sidebarEl || !contactsList) {
            return;
        }

        historyPanel = document.createElement('section');
        historyPanel.id = 'sidebarHistoryPanel';
        historyPanel.className = 'sidebar-history-panel';
        historyPanel.hidden = true;

        const headerEl = document.createElement('div');
        headerEl.className = 'sidebar-history-header';

        const titleEl = document.createElement('div');
        titleEl.className = 'sidebar-history-title';
        titleEl.textContent = 'History';

        historyRefreshBtn = document.createElement('button');
        historyRefreshBtn.type = 'button';
        historyRefreshBtn.className = 'sidebar-history-refresh';
        historyRefreshBtn.setAttribute('aria-label', 'Refresh history');
        historyRefreshBtn.innerHTML = '<i class="fa-solid fa-rotate-right" aria-hidden="true"></i>';
        historyRefreshBtn.addEventListener('click', () => {
            loadSidebarHistory({ force: true });
        });

        headerEl.appendChild(titleEl);
        headerEl.appendChild(historyRefreshBtn);

        const filtersEl = document.createElement('div');
        filtersEl.className = 'sidebar-history-filters';
        filtersEl.setAttribute('role', 'tablist');

        historyFilterButtons = [];
        [
            { key: 'all', label: 'All' },
            { key: 'messages', label: 'Messages' },
            { key: 'calls', label: 'Calls' },
            { key: 'other', label: 'Other' }
        ].forEach(filter => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'sidebar-history-filter';
            button.dataset.filter = filter.key;
            button.setAttribute('role', 'tab');
            button.textContent = filter.label;
            button.addEventListener('click', () => {
                historyActiveFilter = filter.key;
                renderHistoryRecords();
            });
            historyFilterButtons.push(button);
            filtersEl.appendChild(button);
        });

        historyStatusEl = document.createElement('div');
        historyStatusEl.className = 'sidebar-history-status';
        historyStatusEl.hidden = true;

        historyListEl = document.createElement('div');
        historyListEl.className = 'sidebar-history-list';

        historyPanel.appendChild(headerEl);
        historyPanel.appendChild(filtersEl);
        historyPanel.appendChild(historyStatusEl);
        historyPanel.appendChild(historyListEl);

        contactsList.insertAdjacentElement('afterend', historyPanel);
        updateHistoryFilterButtons();
    }

    function ensureContactsSortUi() {
        if (contactsSortRow || !contactsList) {
            return;
        }

        const searchShell = contactsSearchInput
            ? contactsSearchInput.closest('.sidebar-contact-search')
            : document.querySelector('.sidebar-contact-search');
        if (!searchShell) {
            return;
        }

        contactsSortRow = document.createElement('label');
        contactsSortRow.className = 'contacts-sort-row';

        const label = document.createElement('span');
        label.className = 'contacts-sort-label';
        label.textContent = 'Sort';

        contactsSortSelect = document.createElement('select');
        contactsSortSelect.className = 'contacts-sort-select';
        contactsSortSelect.setAttribute('aria-label', 'Sort or filter chats');
        [
            ['recent', 'All'],
            ['oldest', 'Oldest'],
            ['newest', 'Newest'],
            ['unread', 'Unread'],
            ['groups', 'Group Chats'],
            ['ai', 'AI chats']
        ].forEach(([value, text]) => {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = text;
            contactsSortSelect.appendChild(option);
        });
        contactsSortSelect.value = contactsSortMode;
        contactsSortSelect.addEventListener('change', () => {
            contactsSortMode = String(contactsSortSelect.value || 'recent');
            sortContactsList();
        });

        contactsSortRow.appendChild(label);
        contactsSortRow.appendChild(contactsSortSelect);
        searchShell.insertAdjacentElement('afterend', contactsSortRow);
    }

    function ensureDesktopContactViewUi() {
        if (desktopContactViewHost || !chatBox) {
            return;
        }

        desktopContactViewHost = document.createElement('section');
        desktopContactViewHost.className = 'desktop-contact-view-panel';
        desktopContactViewHost.hidden = true;

        desktopArchivedPanel = document.createElement('section');
        desktopArchivedPanel.className = 'sidebar-history-panel desktop-archived-panel';
        desktopArchivedPanel.hidden = true;

        const archivedHeader = document.createElement('div');
        archivedHeader.className = 'sidebar-history-header';
        const archivedTitle = document.createElement('div');
        archivedTitle.className = 'sidebar-history-title';
        archivedTitle.textContent = 'Archived';
        archivedHeader.appendChild(archivedTitle);

        desktopArchivedListEl = document.createElement('div');
        desktopArchivedListEl.className = 'sidebar-history-list desktop-archived-list';

        desktopArchivedPanel.appendChild(archivedHeader);
        desktopArchivedPanel.appendChild(desktopArchivedListEl);
        desktopContactViewHost.appendChild(desktopArchivedPanel);

        chatBox.insertAdjacentElement('beforebegin', desktopContactViewHost);
    }

    function restoreHistoryPanelToSidebar() {
        if (!historyPanel || !contactsList) {
            return;
        }

        if (historyPanel.parentElement === desktopContactViewHost) {
            contactsList.insertAdjacentElement('afterend', historyPanel);
        }
    }

    function setScrollsStatus(message = '') {
        if (!scrollsStatusEl) {
            return;
        }
        scrollsStatusEl.textContent = String(message || '').trim();
        scrollsStatusEl.hidden = !scrollsStatusEl.textContent;
    }

    function normalizeScrollCaption(value) {
        return String(value || '')
            .replace(/\r\n/g, '\n')
            .replace(/\r/g, '\n')
            .trim();
    }

    function normalizeScrollTitle(value) {
        return String(value || '')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function setScrollComposerStatus(message = '', state = 'info') {
        if (!scrollComposerStatusEl) {
            return;
        }
        scrollComposerStatusEl.textContent = String(message || '').trim();
        if (state === 'error' || state === 'success') {
            scrollComposerStatusEl.dataset.state = state;
            return;
        }
        delete scrollComposerStatusEl.dataset.state;
    }

    function getScrollComposerUploadLimitMessage() {
        return scrollsMaxUploadBytes > 0
            ? `Please keep Scroll videos under ${scrollsMaxUploadLabel}.`
            : 'Please choose a smaller video before posting.';
    }

    function getScrollComposerPostErrorMessage(error) {
        const rawMessage = error && error.message ? String(error.message).trim() : '';
        if (rawMessage && rawMessage !== 'Failed to fetch') {
            return rawMessage;
        }

        if (scrollComposerSelectedFile && scrollsMaxUploadBytes > 0) {
            const fileSize = Math.max(0, Number(scrollComposerSelectedFile.size || 0) || 0);
            if (fileSize > scrollsMaxUploadBytes) {
                return getScrollComposerUploadLimitMessage();
            }
        }

        if (error && error.name === 'AbortError') {
            return 'Posting timed out. Try a smaller video or try again.';
        }

        return scrollsMaxUploadBytes > 0
            ? `The upload did not finish. Try a video under ${scrollsMaxUploadLabel} or try again.`
            : 'The upload did not finish. Please try again.';
    }

    function getScrollFeedItem(scrollId) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        if (!normalizedScrollId) {
            return null;
        }
        return scrollsFeedItems.find(item => Number(item && item.id ? item.id : 0) === normalizedScrollId) || null;
    }

    function getScrollFeedIndex(scrollId) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        if (!normalizedScrollId) {
            return -1;
        }
        return scrollsFeedItems.findIndex(item => Number(item && item.id ? item.id : 0) === normalizedScrollId);
    }

    function getAdjacentScrollFeedItem(scrollId, direction = 1) {
        const currentIndex = getScrollFeedIndex(scrollId);
        if (currentIndex < 0) {
            return null;
        }

        const offset = direction >= 0 ? 1 : -1;
        const nextItem = scrollsFeedItems[currentIndex + offset] || null;
        return nextItem && Number(nextItem.id || 0) > 0 ? nextItem : null;
    }

    function getScrollCommentCountLabel(count) {
        const normalizedCount = Math.max(0, Number(count || 0) || 0);
        if (normalizedCount === 0) {
            return 'No comments yet';
        }
        return normalizedCount === 1 ? '1 comment' : `${normalizedCount} comments`;
    }

    function normalizeScrollCommentText(value) {
        const normalized = String(value || '')
            .replace(/\r\n?/g, '\n')
            .trim();
        return normalized.slice(0, 600).trim();
    }

    function truncateScrollCommentSnippet(value, maxLength = 96) {
        const normalized = String(value || '')
            .replace(/\s+/g, ' ')
            .trim();
        if (!normalized) {
            return '';
        }
        if (normalized.length <= maxLength) {
            return normalized;
        }
        return `${normalized.slice(0, Math.max(0, maxLength - 1)).trim()}...`;
    }

    function getScrollCommentThreadRootId(comment) {
        const explicitRootId = Math.max(0, Number(comment && comment.thread_root_comment_id ? comment.thread_root_comment_id : 0) || 0);
        const replyToCommentId = Math.max(0, Number(comment && comment.reply_to_comment_id ? comment.reply_to_comment_id : 0) || 0);
        const commentId = Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0);
        return explicitRootId || replyToCommentId || commentId;
    }

    function getScrollCommentFromCache(scrollId, commentId) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        const normalizedCommentId = Math.max(0, Number(commentId || 0) || 0);
        if (!normalizedScrollId || !normalizedCommentId) {
            return null;
        }

        const cachedComments = scrollCommentsCache.get(normalizedScrollId);
        if (!Array.isArray(cachedComments)) {
            return null;
        }

        return cachedComments.find(comment => Number(comment && comment.id ? comment.id : 0) === normalizedCommentId) || null;
    }

    function updateScrollCommentCacheEntry(scrollId, commentId, nextFields = {}) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        const normalizedCommentId = Math.max(0, Number(commentId || 0) || 0);
        if (!normalizedScrollId || !normalizedCommentId || !scrollCommentsCache.has(normalizedScrollId)) {
            return false;
        }

        let didUpdate = false;
        const cachedComments = Array.isArray(scrollCommentsCache.get(normalizedScrollId))
            ? (scrollCommentsCache.get(normalizedScrollId) || [])
            : [];
        const nextComments = cachedComments.map(comment => {
            if (Number(comment && comment.id ? comment.id : 0) !== normalizedCommentId) {
                return comment;
            }

            didUpdate = true;
            return {
                ...comment,
                ...nextFields
            };
        });

        if (didUpdate) {
            scrollCommentsCache.set(normalizedScrollId, nextComments);
        }
        return didUpdate;
    }

    function syncScrollCommentReplyBar(replyBarEl, replyCopyEl, inputEl) {
        if (!replyBarEl || !replyCopyEl) {
            return;
        }

        if (!activeScrollCommentReply) {
            replyBarEl.hidden = true;
            replyCopyEl.textContent = '';
            if (inputEl) {
                inputEl.placeholder = 'Add a comment...';
            }
            return;
        }

        const replyName = String(activeScrollCommentReply.displayName || 'QuillTalk user').trim() || 'QuillTalk user';
        const replySnippet = truncateScrollCommentSnippet(activeScrollCommentReply.commentText || '', 72);
        replyCopyEl.textContent = replySnippet
            ? `Replying to ${replyName}: ${replySnippet}`
            : `Replying to ${replyName}`;
        replyBarEl.hidden = false;
        if (inputEl) {
            inputEl.placeholder = `Reply to ${replyName}...`;
        }
    }

    function syncScrollCommentReplyUi() {
        syncScrollCommentReplyBar(scrollViewerCommentsReplyBarEl, scrollViewerCommentsReplyCopyEl, scrollViewerCommentsInputEl);
        syncScrollCommentReplyBar(scrollCommentsSheetReplyBarEl, scrollCommentsSheetReplyCopyEl, scrollCommentsSheetInputEl);
    }

    function clearActiveScrollCommentReply() {
        activeScrollCommentReply = null;
        syncScrollCommentReplyUi();
    }

    function setActiveScrollCommentReply(comment) {
        const normalizedCommentId = Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0);
        if (!normalizedCommentId) {
            clearActiveScrollCommentReply();
            return;
        }

        activeScrollCommentReply = {
            commentId: normalizedCommentId,
            replyToCommentId: normalizedCommentId,
            displayName: String(comment && comment.commenter_display_name ? comment.commenter_display_name : 'QuillTalk user').trim() || 'QuillTalk user',
            commentText: String(comment && comment.comment_text ? comment.comment_text : '').trim()
        };
        syncScrollCommentReplyUi();
    }

    function focusActiveScrollCommentInput(preferMobileSheet = false) {
        const targetInput = preferMobileSheet ? scrollCommentsSheetInputEl : scrollViewerCommentsInputEl;
        if (!targetInput) {
            return;
        }

        try {
            targetInput.focus({ preventScroll: true });
        } catch (error) {
            targetInput.focus();
        }
    }

    function setScrollCommentsStatus(targetEl, message = '', state = '') {
        if (!targetEl) {
            return;
        }

        const normalizedMessage = String(message || '').trim();
        const normalizedState = String(state || '').trim();
        targetEl.textContent = normalizedMessage;
        if (normalizedState) {
            targetEl.dataset.state = normalizedState;
        } else {
            delete targetEl.dataset.state;
        }
    }

    function updateScrollFeedItemCommentCount(scrollId, commentCount) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        if (!normalizedScrollId) {
            return;
        }

        const normalizedCount = Math.max(0, Number(commentCount || 0) || 0);
        scrollsFeedItems = scrollsFeedItems.map(item => {
            if (Number(item && item.id ? item.id : 0) !== normalizedScrollId) {
                return item;
            }
            return {
                ...item,
                comment_count: normalizedCount
            };
        });
    }

    function syncScrollCommentMeta(scrollId = activeScrollViewerId) {
        const item = getScrollFeedItem(scrollId);
        const title = item ? (normalizeScrollTitle(item.title) || 'Untitled Scroll') : 'Comments';
        const commentCount = Math.max(0, Number(item && item.comment_count ? item.comment_count : 0) || 0);
        const metaText = `${title} - ${getScrollCommentCountLabel(commentCount)}`;

        if (scrollViewerCommentsTitleEl) {
            scrollViewerCommentsTitleEl.textContent = 'Comments';
        }
        if (scrollViewerCommentsMetaEl) {
            scrollViewerCommentsMetaEl.textContent = metaText;
        }
        if (scrollCommentsSheetTitleEl) {
            scrollCommentsSheetTitleEl.textContent = 'Comments';
        }
        if (scrollCommentsSheetMetaEl) {
            scrollCommentsSheetMetaEl.textContent = metaText;
        }
    }

    function renderScrollCommentsList(targetEl, comments = []) {
        if (!targetEl) {
            return;
        }

        targetEl.innerHTML = '';
        const normalizedComments = Array.isArray(comments) ? comments : [];

        if (!normalizedComments.length) {
            const emptyEl = document.createElement('div');
            emptyEl.className = 'scrolls-comments-empty';
            emptyEl.textContent = 'No comments yet. Start the conversation.';
            targetEl.appendChild(emptyEl);
            return;
        }

        const repliesByParentId = new Map();
        const topLevelComments = [];

        normalizedComments.forEach(comment => {
            const replyToCommentId = Math.max(0, Number(comment && comment.reply_to_comment_id ? comment.reply_to_comment_id : 0) || 0);
            if (!replyToCommentId) {
                topLevelComments.push(comment);
                return;
            }

            const threadRootCommentId = getScrollCommentThreadRootId(comment);
            if (!repliesByParentId.has(threadRootCommentId)) {
                repliesByParentId.set(threadRootCommentId, []);
            }
            repliesByParentId.get(threadRootCommentId).push(comment);
        });

        const renderSingleComment = (comment, { isReply = false } = {}) => {
            const article = document.createElement('article');
            article.className = 'scrolls-comment';
            if (isReply) {
                article.classList.add('is-reply');
            }
            article.dataset.commentId = String(Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0));

            const avatar = document.createElement('img');
            avatar.className = 'scrolls-comment-avatar';
            avatar.src = normalizeProfilePic(String(comment.commenter_profile_pic || defaultProfilePic), 'direct');
            avatar.alt = String(comment.commenter_display_name || 'Commenter');

            const body = document.createElement('div');
            body.className = 'scrolls-comment-body';

            const card = document.createElement('div');
            card.className = 'scrolls-comment-card';

            const head = document.createElement('div');
            head.className = 'scrolls-comment-head';

            const nameEl = document.createElement('div');
            nameEl.className = 'scrolls-comment-name';
            nameEl.textContent = String(comment.commenter_display_name || 'QuillTalk user');

            const timeEl = document.createElement('div');
            timeEl.className = 'scrolls-comment-time';
            timeEl.textContent = formatCompactRelativeTimestamp(comment.created_at || '', { includeWeeks: false });

            head.appendChild(nameEl);
            head.appendChild(timeEl);

            const textEl = document.createElement('div');
            textEl.className = 'scrolls-comment-text';
            textEl.textContent = String(comment.comment_text || '');

            if (Math.max(0, Number(comment && comment.reply_to_comment_id ? comment.reply_to_comment_id : 0) || 0) > 0) {
                const replyContextEl = document.createElement('div');
                replyContextEl.className = 'scrolls-comment-reply-context';

                const replyContextLabelEl = document.createElement('div');
                replyContextLabelEl.className = 'scrolls-comment-reply-context-label';
                replyContextLabelEl.textContent = `Replied to ${String(comment.reply_to_display_name || 'QuillTalk user').trim() || 'QuillTalk user'}`;

                const replyContextTextEl = document.createElement('div');
                replyContextTextEl.className = 'scrolls-comment-reply-context-text';
                replyContextTextEl.textContent = truncateScrollCommentSnippet(comment.reply_to_comment_text || '', 76) || 'View thread';

                replyContextEl.appendChild(replyContextLabelEl);
                replyContextEl.appendChild(replyContextTextEl);
                card.appendChild(replyContextEl);
            }

            const actionsRow = document.createElement('div');
            actionsRow.className = 'scrolls-comment-actions-row';

            const buildActionButton = (action, iconClass, label, count = 0, isActive = false) => {
                const button = document.createElement('button');
                button.type = 'button';
                button.className = 'scrolls-comment-action';
                if (isActive) {
                    button.classList.add('is-active');
                }
                button.dataset.scrollCommentAction = action;
                button.dataset.scrollCommentId = String(Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0));
                button.dataset.scrollId = String(Math.max(0, Number(comment && comment.scroll_id ? comment.scroll_id : activeScrollViewerId) || 0));
                button.setAttribute('aria-label', label);
                button.setAttribute('title', label);
                button.innerHTML = `<i class="${iconClass}" aria-hidden="true"></i>${action === 'reply' ? '<span>Reply</span>' : `<span class="scrolls-comment-action-count">${Math.max(0, Number(count || 0) || 0)}</span>`}`;
                return button;
            };

            actionsRow.appendChild(
                buildActionButton(
                    'like',
                    'fa-solid fa-thumbs-up',
                    'Like comment',
                    Math.max(0, Number(comment.like_count || 0) || 0),
                    String(comment.user_reaction || '') === 'like'
                )
            );
            actionsRow.appendChild(
                buildActionButton(
                    'dislike',
                    'fa-solid fa-thumbs-down',
                    'Dislike comment',
                    Math.max(0, Number(comment.dislike_count || 0) || 0),
                    String(comment.user_reaction || '') === 'dislike'
                )
            );
            actionsRow.appendChild(
                buildActionButton(
                    'reply',
                    'fa-solid fa-reply',
                    'Reply to comment'
                )
            );

            card.appendChild(head);
            card.appendChild(textEl);
            card.appendChild(actionsRow);
            body.appendChild(card);
            article.appendChild(avatar);
            article.appendChild(body);
            targetEl.appendChild(article);
        };

        topLevelComments.forEach(comment => {
            renderSingleComment(comment, { isReply: false });
            const replies = Array.isArray(repliesByParentId.get(Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0)))
                ? (repliesByParentId.get(Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0)) || [])
                : [];
            replies.forEach(reply => {
                renderSingleComment(reply, { isReply: true });
            });
            repliesByParentId.delete(Math.max(0, Number(comment && comment.id ? comment.id : 0) || 0));
        });

        repliesByParentId.forEach(orphanReplies => {
            (Array.isArray(orphanReplies) ? orphanReplies : []).forEach(reply => {
                renderSingleComment(reply, { isReply: true });
            });
        });
    }

    function renderCachedScrollComments(scrollId = activeScrollViewerId) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        const cachedComments = normalizedScrollId ? (scrollCommentsCache.get(normalizedScrollId) || []) : [];
        syncScrollCommentMeta(normalizedScrollId);
        renderScrollCommentsList(scrollViewerCommentsListEl, cachedComments);
        renderScrollCommentsList(scrollCommentsSheetListEl, cachedComments);
        syncScrollCommentReplyUi();
    }

    async function loadScrollComments(scrollId, { force = false } = {}) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        if (!normalizedScrollId) {
            return [];
        }

        if (!force && scrollCommentsCache.has(normalizedScrollId)) {
            return scrollCommentsCache.get(normalizedScrollId) || [];
        }

        if (!force && scrollCommentsLoadingPromises.has(normalizedScrollId)) {
            return scrollCommentsLoadingPromises.get(normalizedScrollId);
        }

        const loadingPromise = (async () => {
            const response = await fetch(`fetch_scroll_comments.php?token=${encodeURIComponent(token)}&scroll_id=${encodeURIComponent(normalizedScrollId)}&t=${Date.now()}`);
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(data && data.error ? data.error : 'Could not load comments right now.');
            }

            const comments = Array.isArray(data.comments) ? data.comments : [];
            scrollCommentsCache.set(normalizedScrollId, comments);
            updateScrollFeedItemCommentCount(normalizedScrollId, data.comment_count);

            if (normalizedScrollId === activeScrollViewerId) {
                syncScrollViewerState(activeScrollViewerId);
            }
            syncScrollCommentMeta(normalizedScrollId);
            return comments;
        })();

        scrollCommentsLoadingPromises.set(normalizedScrollId, loadingPromise);

        try {
            return await loadingPromise;
        } finally {
            scrollCommentsLoadingPromises.delete(normalizedScrollId);
        }
    }

    function cancelElementAnimations(element) {
        if (!element || typeof element.getAnimations !== 'function') {
            return;
        }

        try {
            element.getAnimations().forEach(animation => animation.cancel());
        } catch (error) {}
    }

    async function animateScrollViewerShellNavigation(direction = 1, phase = 'out') {
        if (!scrollViewerShellEl || typeof scrollViewerShellEl.animate !== 'function') {
            return;
        }

        cancelElementAnimations(scrollViewerShellEl);
        const offset = direction >= 0 ? 56 : -56;
        const keyframes = phase === 'out'
            ? [
                { transform: 'translateY(0) scale(1)', opacity: 1, filter: 'blur(0px)' },
                { transform: `translateY(${offset * -1}px) scale(0.99)`, opacity: 0.18, filter: 'blur(8px)' }
            ]
            : [
                { transform: `translateY(${offset}px) scale(0.99)`, opacity: 0.18, filter: 'blur(8px)' },
                { transform: 'translateY(0) scale(1)', opacity: 1, filter: 'blur(0px)' }
            ];

        const animation = scrollViewerShellEl.animate(keyframes, {
            duration: phase === 'out' ? 190 : 260,
            easing: 'cubic-bezier(0.22, 1, 0.36, 1)',
            fill: 'forwards'
        });

        try {
            await animation.finished;
        } catch (error) {}

        if (phase === 'in') {
            cancelElementAnimations(scrollViewerShellEl);
        }
    }

    async function animateDesktopCommentsPanel(opening) {
        if (!scrollViewerCommentsWrapEl || typeof scrollViewerCommentsWrapEl.animate !== 'function') {
            return;
        }

        cancelElementAnimations(scrollViewerCommentsWrapEl);
        const keyframes = opening
            ? [
                { transform: 'translateX(28px)', opacity: 0.12 },
                { transform: 'translateX(0)', opacity: 1 }
            ]
            : [
                { transform: 'translateX(0)', opacity: 1 },
                { transform: 'translateX(24px)', opacity: 0.08 }
            ];

        const animation = scrollViewerCommentsWrapEl.animate(keyframes, {
            duration: opening ? 280 : 210,
            easing: 'cubic-bezier(0.22, 1, 0.36, 1)',
            fill: 'forwards'
        });

        try {
            await animation.finished;
        } catch (error) {}

        cancelElementAnimations(scrollViewerCommentsWrapEl);
    }

    function closeScrollCommentsSheet() {
        if (!scrollCommentsOverlayEl) {
            return;
        }

        const wasOpen = scrollCommentsOverlayEl.classList.contains('open') || scrollCommentsSheetActiveScrollId > 0;
        scrollCommentsOverlayEl.classList.remove('open');
        scrollCommentsOverlayEl.setAttribute('aria-hidden', 'true');
        resetOverlayZIndex(scrollCommentsOverlayEl);
        scrollCommentsSheetActiveScrollId = 0;
        clearActiveScrollCommentReply();
        if (scrollCommentsSheetInputEl) {
            scrollCommentsSheetInputEl.value = '';
        }
        setScrollCommentsStatus(scrollCommentsSheetStatusEl);
        if (wasOpen) {
            syncScrollViewerState(activeScrollViewerId);
        }
    }

    async function openScrollCommentsSheet(scrollId) {
        ensureScrollsPanelUi();
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        if (!normalizedScrollId || !scrollCommentsOverlayEl) {
            return;
        }

        scrollCommentsSheetActiveScrollId = normalizedScrollId;
        scrollCommentsOverlayEl.classList.add('open');
        scrollCommentsOverlayEl.setAttribute('aria-hidden', 'false');
        bringOverlayToFront(scrollCommentsOverlayEl, 8);
        if (scrollCommentsSheetInputEl) {
            scrollCommentsSheetInputEl.value = '';
        }
        clearActiveScrollCommentReply();
        setScrollCommentsStatus(scrollCommentsSheetStatusEl);
        renderCachedScrollComments(normalizedScrollId);
        syncScrollViewerState(activeScrollViewerId);

        if (!scrollCommentsCache.has(normalizedScrollId)) {
            setScrollCommentsStatus(scrollCommentsSheetStatusEl, 'Loading comments...');
        }

        try {
            await loadScrollComments(normalizedScrollId);
            renderCachedScrollComments(normalizedScrollId);
            setScrollCommentsStatus(scrollCommentsSheetStatusEl);
        } catch (error) {
            setScrollCommentsStatus(
                scrollCommentsSheetStatusEl,
                error && error.message ? error.message : 'Could not load comments right now.',
                'error'
            );
        }
    }

    async function setScrollViewerCommentsMode(shouldOpen) {
        ensureScrollsPanelUi();
        const normalizedOpen = !!shouldOpen;

        if (isMobileViewport()) {
            scrollViewerCommentsMode = false;
            if (normalizedOpen) {
                await openScrollCommentsSheet(activeScrollViewerId);
            } else {
                closeScrollCommentsSheet();
            }
            return;
        }

        if (!normalizedOpen && scrollViewerCommentsMode) {
            clearActiveScrollCommentReply();
            await animateDesktopCommentsPanel(false);
        }

        scrollViewerCommentsMode = normalizedOpen;
        if (scrollViewerPanelEl) {
            scrollViewerPanelEl.classList.toggle('is-comments-mode', normalizedOpen);
        }
        syncScrollViewerState(activeScrollViewerId);
        if (!normalizedOpen) {
            if (scrollViewerCommentsInputEl) {
                scrollViewerCommentsInputEl.value = '';
            }
            setScrollCommentsStatus(scrollViewerCommentsStatusEl);
            return;
        }

        clearActiveScrollCommentReply();
        await animateDesktopCommentsPanel(true);
        renderCachedScrollComments(activeScrollViewerId);
        if (!scrollCommentsCache.has(activeScrollViewerId)) {
            setScrollCommentsStatus(scrollViewerCommentsStatusEl, 'Loading comments...');
        }

        try {
            await loadScrollComments(activeScrollViewerId);
            renderCachedScrollComments(activeScrollViewerId);
            setScrollCommentsStatus(scrollViewerCommentsStatusEl);
        } catch (error) {
            setScrollCommentsStatus(
                scrollViewerCommentsStatusEl,
                error && error.message ? error.message : 'Could not load comments right now.',
                'error'
            );
        }
    }

    async function submitScrollComment(scrollId, inputEl, statusEl, submitBtn) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        const commentText = normalizeScrollCommentText(inputEl ? inputEl.value : '');
        const replyToCommentId = Math.max(0, Number(activeScrollCommentReply && activeScrollCommentReply.replyToCommentId ? activeScrollCommentReply.replyToCommentId : 0) || 0);
        if (!normalizedScrollId || !inputEl || !submitBtn) {
            return;
        }

        if (!commentText) {
            setScrollCommentsStatus(statusEl, 'Write a comment first.', 'error');
            inputEl.focus();
            return;
        }

        submitBtn.disabled = true;
        setScrollCommentsStatus(statusEl, 'Posting comment...');

        try {
            const response = await fetch('create_scroll_comment.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    scroll_id: normalizedScrollId,
                    reply_to_comment_id: replyToCommentId,
                    comment: commentText
                })
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(data && data.error ? data.error : 'Could not post that comment right now.');
            }

            clearActiveScrollCommentReply();
            updateScrollFeedItemCommentCount(normalizedScrollId, data.comment_count);
            inputEl.value = '';
            scrollCommentsCache.delete(normalizedScrollId);
            try {
                await loadScrollComments(normalizedScrollId, { force: true });
            } catch (refreshError) {
                const fallbackComments = Array.isArray(scrollCommentsCache.get(normalizedScrollId))
                    ? [...(scrollCommentsCache.get(normalizedScrollId) || [])]
                    : [];
                if (data.comment && Number(data.comment.id || 0) > 0) {
                    fallbackComments.unshift(data.comment);
                }
                scrollCommentsCache.set(normalizedScrollId, fallbackComments);
            }
            renderCachedScrollComments(normalizedScrollId);
            setScrollCommentsStatus(statusEl, 'Comment posted.');
            if (normalizedScrollId === activeScrollViewerId) {
                syncScrollViewerState(activeScrollViewerId);
            }
        } catch (error) {
            setScrollCommentsStatus(
                statusEl,
                error && error.message ? error.message : 'Could not post that comment right now.',
                'error'
            );
        } finally {
            submitBtn.disabled = false;
        }
    }

    async function submitScrollCommentReaction(scrollId, commentId, reactionType) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        const normalizedCommentId = Math.max(0, Number(commentId || 0) || 0);
        const normalizedReactionType = String(reactionType || '').trim();
        if (!normalizedScrollId || !normalizedCommentId || !['like', 'dislike'].includes(normalizedReactionType)) {
            return;
        }

        try {
            const response = await fetch('toggle_scroll_comment_reaction.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    comment_id: normalizedCommentId,
                    reaction_type: normalizedReactionType
                })
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(data && data.error ? data.error : 'Could not update the comment reaction.');
            }

            updateScrollCommentCacheEntry(normalizedScrollId, normalizedCommentId, {
                like_count: Math.max(0, Number(data.like_count || 0) || 0),
                dislike_count: Math.max(0, Number(data.dislike_count || 0) || 0),
                user_reaction: String(data.user_reaction || '')
            });
            renderCachedScrollComments(normalizedScrollId);
        } catch (error) {
            console.error('Unable to update scroll comment reaction.', error);
            showToast(error && error.message ? error.message : 'Could not update the comment reaction.', 'error');
        }
    }

    function handleScrollCommentListClick(event) {
        const actionButton = event && event.target && typeof event.target.closest === 'function'
            ? event.target.closest('[data-scroll-comment-action]')
            : null;
        if (!actionButton) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();

        const action = String(actionButton.dataset.scrollCommentAction || '').trim();
        const scrollId = Math.max(0, Number(actionButton.dataset.scrollId || activeScrollViewerId) || 0);
        const commentId = Math.max(0, Number(actionButton.dataset.scrollCommentId || 0) || 0);
        const comment = getScrollCommentFromCache(scrollId, commentId);
        if (!scrollId || !commentId || !action) {
            return;
        }

        if (action === 'reply') {
            setActiveScrollCommentReply(comment);
            focusActiveScrollCommentInput(isMobileViewport());
            return;
        }

        if (action === 'like' || action === 'dislike') {
            void submitScrollCommentReaction(scrollId, commentId, action);
        }
    }

    function navigateActiveScrollViewer(direction = 1) {
        const nextItem = getAdjacentScrollFeedItem(activeScrollViewerId, direction);
        if (!nextItem) {
            return Promise.resolve(false);
        }

        if (scrollViewerTransitionPromise) {
            return scrollViewerTransitionPromise.then(() => false).catch(() => false);
        }

        scrollViewerTransitionPromise = (async () => {
            await animateScrollViewerShellNavigation(direction, 'out');
            openScrollViewer(nextItem.id, {
                preserveCommentsMode: scrollViewerCommentsMode && !isMobileViewport()
            });
            await animateScrollViewerShellNavigation(direction, 'in');
            return true;
        })();

        return scrollViewerTransitionPromise
            .catch(() => false)
            .finally(() => {
                scrollViewerTransitionPromise = null;
            });
    }

    function handleScrollViewerWheelNavigation(event) {
        const interactiveTarget = event && event.target && typeof event.target.closest === 'function'
            ? event.target.closest('button, input, textarea, select')
            : null;
        if (interactiveTarget || !isScrollViewerOpen() || scrollViewerTransitionPromise || Math.abs(Number(event.deltaY || 0)) < 36) {
            return;
        }

        const now = Date.now();
        if (now < scrollViewerWheelLockUntil) {
            event.preventDefault();
            return;
        }

        scrollViewerWheelLockUntil = now + 420;
        void navigateActiveScrollViewer(Number(event.deltaY || 0) > 0 ? 1 : -1);
        event.preventDefault();
    }

    function handleScrollViewerTouchStart(event) {
        const interactiveTarget = event && event.target && typeof event.target.closest === 'function'
            ? event.target.closest('button, input, textarea, select')
            : null;
        if (interactiveTarget || !isScrollViewerOpen() || !event.touches || event.touches.length !== 1) {
            scrollViewerTouchStartY = null;
            return;
        }

        scrollViewerTouchStartY = Number(event.touches[0].clientY || 0);
    }

    function handleScrollViewerTouchEnd(event) {
        const interactiveTarget = event && event.target && typeof event.target.closest === 'function'
            ? event.target.closest('button, input, textarea, select')
            : null;
        if (interactiveTarget || !isScrollViewerOpen() || scrollViewerTouchStartY === null || !event.changedTouches || !event.changedTouches.length) {
            scrollViewerTouchStartY = null;
            return;
        }

        const endY = Number(event.changedTouches[0].clientY || 0);
        const deltaY = scrollViewerTouchStartY - endY;
        scrollViewerTouchStartY = null;

        if (Math.abs(deltaY) < 54) {
            return;
        }

        const now = Date.now();
        if (now < scrollViewerWheelLockUntil || scrollViewerTransitionPromise) {
            return;
        }

        scrollViewerWheelLockUntil = now + 420;
        void navigateActiveScrollViewer(deltaY > 0 ? 1 : -1);
    }

    function releaseScrollComposerPreviewUrl() {
        if (scrollComposerPreviewUrl) {
            URL.revokeObjectURL(scrollComposerPreviewUrl);
            scrollComposerPreviewUrl = '';
        }
    }

    function resetScrollComposerModalState() {
        scrollComposerSelectedFile = null;
        releaseScrollComposerPreviewUrl();
        if (scrollComposerVideoInput) {
            scrollComposerVideoInput.value = '';
        }
        if (scrollComposerPreviewEl) {
            scrollComposerPreviewEl.innerHTML = '<span>Choose a vertical video to preview it here.</span>';
        }
        if (scrollComposerTitleInput) {
            scrollComposerTitleInput.value = '';
        }
        if (scrollComposerCaptionInput) {
            scrollComposerCaptionInput.value = '';
        }
        setScrollComposerStatus(scrollComposerIdleStatus);
        if (scrollComposerPostBtn) {
            scrollComposerPostBtn.disabled = false;
        }
    }

    function closeScrollComposerModal() {
        if (!scrollComposerModalEl) {
            return;
        }
        scrollComposerModalEl.classList.remove('open');
        scrollComposerModalEl.setAttribute('aria-hidden', 'true');
        resetOverlayZIndex(scrollComposerModalEl);
        resetScrollComposerModalState();
    }

    function openScrollComposerModal() {
        ensureScrollsPanelUi();
        if (!scrollComposerModalEl) {
            return;
        }
        resetScrollComposerModalState();
        bringOverlayToFront(scrollComposerModalEl, 6);
        scrollComposerModalEl.classList.add('open');
        scrollComposerModalEl.setAttribute('aria-hidden', 'false');
    }

    function isScrollViewerOpen() {
        return activeScrollViewerId > 0 && !!getScrollFeedItem(activeScrollViewerId);
    }

    function syncScrollViewerVisibility() {
        const isOpen = isScrollViewerOpen();
        if (scrollsGridWrapEl) {
            scrollsGridWrapEl.hidden = isOpen;
        }
        if (scrollViewerPanelEl) {
            scrollViewerPanelEl.hidden = !isOpen;
        }
    }

    function setScrollViewerFollowButtonState(button, isOwnScroll, isFollowing) {
        if (!button) {
            return;
        }

        button.hidden = !!isOwnScroll;
        button.classList.toggle('is-active', !!isFollowing);
        button.setAttribute('aria-label', isFollowing ? 'Following creator' : 'Follow creator');
        button.setAttribute('title', isFollowing ? 'Following creator' : 'Follow creator');
        button.innerHTML = isFollowing
            ? '<i class="fa-solid fa-user-check" aria-hidden="true"></i><span>Following</span>'
            : '<i class="fa-solid fa-user-plus" aria-hidden="true"></i><span>Follow</span>';
    }

    function syncScrollViewerPlaybackUi() {
        if (!scrollViewerVideoEl) {
            return;
        }

        const duration = Number.isFinite(Number(scrollViewerVideoEl.duration)) && Number(scrollViewerVideoEl.duration) > 0
            ? Number(scrollViewerVideoEl.duration)
            : 0;
        const currentTime = duration > 0
            ? Math.min(duration, Math.max(0, Number(scrollViewerVideoEl.currentTime || 0) || 0))
            : 0;
        const progressPercent = duration > 0
            ? Math.max(0, Math.min(100, (currentTime / duration) * 100))
            : 0;
        const isPaused = !!scrollViewerVideoEl.paused || !!scrollViewerVideoEl.ended;

        if (scrollViewerPlayBtn) {
            scrollViewerPlayBtn.setAttribute('aria-label', isPaused ? 'Play Scroll' : 'Pause Scroll');
            scrollViewerPlayBtn.setAttribute('title', isPaused ? 'Play Scroll' : 'Pause Scroll');
            scrollViewerPlayBtn.innerHTML = isPaused
                ? '<i class="fa-solid fa-play" aria-hidden="true"></i>'
                : '<i class="fa-solid fa-pause" aria-hidden="true"></i>';
        }

        if (scrollViewerProgressEl) {
            scrollViewerProgressEl.max = duration > 0 ? String(duration) : '100';
            scrollViewerProgressEl.value = duration > 0 ? String(currentTime) : '0';
            scrollViewerProgressEl.disabled = duration <= 0;
            scrollViewerProgressEl.style.setProperty('--scroll-progress', `${progressPercent}%`);
        }

        if (scrollViewerTimeEl) {
            scrollViewerTimeEl.textContent = `${formatVoiceMessageDuration(currentTime)}/${formatVoiceMessageDuration(duration)}`;
        }

        if (scrollViewerMuteBtn) {
            scrollViewerMuteBtn.classList.toggle('is-active', !scrollViewerVideoEl.muted);
            scrollViewerMuteBtn.setAttribute('aria-label', scrollViewerVideoEl.muted ? 'Unmute Scroll' : 'Mute Scroll');
            scrollViewerMuteBtn.setAttribute('title', scrollViewerVideoEl.muted ? 'Unmute Scroll' : 'Mute Scroll');
            scrollViewerMuteBtn.innerHTML = scrollViewerVideoEl.muted
                ? '<i class="fa-solid fa-volume-xmark" aria-hidden="true"></i>'
                : '<i class="fa-solid fa-volume-high" aria-hidden="true"></i>';
        }

        if (scrollViewerLoopBtn) {
            scrollViewerLoopBtn.classList.toggle('is-active', !!scrollViewerVideoEl.loop);
            scrollViewerLoopBtn.setAttribute('aria-label', scrollViewerVideoEl.loop ? 'Looping Scroll' : 'Loop Scroll');
            scrollViewerLoopBtn.setAttribute('title', scrollViewerVideoEl.loop ? 'Looping Scroll' : 'Loop Scroll');
            scrollViewerLoopBtn.innerHTML = '<i class="fa-solid fa-repeat" aria-hidden="true"></i>';
        }

        if (scrollViewerSpeedSelect) {
            const nextRate = Number(scrollViewerVideoEl.playbackRate || 1);
            scrollViewerSpeedSelect.value = ['0.5', '0.75', '1', '1.25', '1.5', '2'].includes(String(nextRate))
                ? String(nextRate)
                : '1';
        }
    }

    function toggleActiveScrollViewerPlayback(forcePlay = null) {
        if (!scrollViewerVideoEl) {
            return;
        }

        const shouldPlay = typeof forcePlay === 'boolean'
            ? forcePlay
            : (scrollViewerVideoEl.paused || scrollViewerVideoEl.ended);

        if (!shouldPlay) {
            scrollViewerVideoEl.pause();
            syncScrollViewerPlaybackUi();
            return;
        }

        try {
            const duration = Number(scrollViewerVideoEl.duration || 0) || 0;
            if (scrollViewerVideoEl.ended || (duration > 0 && Number(scrollViewerVideoEl.currentTime || 0) >= duration - 0.1)) {
                scrollViewerVideoEl.currentTime = 0;
            }
        } catch (error) {}

        scrollViewerVideoEl.play()
            .then(() => {
                syncScrollViewerPlaybackUi();
            })
            .catch(() => {
                syncScrollViewerPlaybackUi();
            });
        syncScrollViewerPlaybackUi();
    }

    function closeScrollViewer() {
        if (!scrollViewerPanelEl) {
            return;
        }

        cancelElementAnimations(scrollViewerShellEl);
        closeScrollCommentsSheet();
        scrollViewerCommentsMode = false;
        scrollViewerWheelLockUntil = 0;
        scrollViewerTouchStartY = null;
        scrollViewerTransitionPromise = null;
        clearActiveScrollCommentReply();
        scrollViewerPanelEl.classList.remove('is-comments-mode');
        activeScrollViewerId = 0;
        if (scrollViewerVideoEl) {
            scrollViewerVideoEl.pause();
            try {
                scrollViewerVideoEl.currentTime = 0;
            } catch (error) {}
            scrollViewerVideoEl.removeAttribute('src');
            scrollViewerVideoEl.load();
        }
        syncScrollViewerVisibility();
        syncScrollViewerPlaybackUi();
    }

    function openScrollViewer(scrollId, { preserveCommentsMode = false } = {}) {
        const item = getScrollFeedItem(scrollId);
        if (!item || !scrollViewerPanelEl || !scrollViewerVideoEl) {
            return;
        }

        clearActiveScrollCommentReply();
        const shouldKeepCommentsMode = !!preserveCommentsMode && !isMobileViewport();
        closeScrollCommentsSheet();
        scrollViewerCommentsMode = shouldKeepCommentsMode;
        scrollViewerPanelEl.classList.toggle('is-comments-mode', shouldKeepCommentsMode);
        activeScrollViewerId = Number(item.id || 0);
        syncScrollViewerVisibility();
        scrollViewerVideoEl.src = String(item.video_path || '');
        scrollViewerVideoEl.muted = false;
        scrollViewerVideoEl.loop = true;
        scrollViewerVideoEl.playbackRate = 1;
        scrollViewerVideoEl.load();
        scrollViewerPanelEl.scrollTop = 0;
        syncScrollViewerState(activeScrollViewerId);
        if (shouldKeepCommentsMode) {
            void setScrollViewerCommentsMode(true);
        } else {
            setScrollCommentsStatus(scrollViewerCommentsStatusEl);
        }
        toggleActiveScrollViewerPlayback(true);
    }

    function syncScrollViewerState(scrollId = activeScrollViewerId) {
        const item = getScrollFeedItem(scrollId);
        if (!item || !scrollViewerVideoEl) {
            return;
        }

        activeScrollViewerId = Number(item.id || 0);
        const normalizedAuthorName = String(item.uploader_display_name || 'QuillTalk user');
        const normalizedAvatar = normalizeProfilePic(String(item.uploader_profile_pic || defaultProfilePic), 'direct');
        const normalizedTitle = normalizeScrollTitle(item.title) || 'Untitled Scroll';
        const followerCount = Math.max(0, Number(item.follower_count || 0) || 0);
        const commentCount = Math.max(0, Number(item.comment_count || 0) || 0);
        const followerLabel = followerCount === 1
            ? '1 follower'
            : `${followerCount} followers`;
        const isOwnScroll = Number(item.uploader_id || 0) === Number(currentUserId || 0);

        if (scrollViewerAuthorAvatarEl) {
            scrollViewerAuthorAvatarEl.src = normalizedAvatar;
            scrollViewerAuthorAvatarEl.alt = normalizedAuthorName || 'Uploader';
        }
        if (scrollViewerAuthorNameEl) {
            scrollViewerAuthorNameEl.textContent = normalizedAuthorName;
        }
        if (scrollViewerAuthorSubtitleEl) {
            scrollViewerAuthorSubtitleEl.textContent = followerLabel;
        }
        if (scrollViewerMobileAuthorAvatarEl) {
            scrollViewerMobileAuthorAvatarEl.src = normalizedAvatar;
            scrollViewerMobileAuthorAvatarEl.alt = normalizedAuthorName || 'Uploader';
        }
        if (scrollViewerMobileAuthorNameEl) {
            scrollViewerMobileAuthorNameEl.textContent = normalizedAuthorName;
        }
        if (scrollViewerMobileAuthorSubtitleEl) {
            scrollViewerMobileAuthorSubtitleEl.textContent = followerLabel;
        }
        if (scrollViewerTitleEl) {
            scrollViewerTitleEl.textContent = normalizedTitle;
        }
        if (scrollViewerMobileTitleEl) {
            scrollViewerMobileTitleEl.textContent = normalizedTitle;
        }
        if (scrollViewerCaptionEl) {
            const caption = normalizeScrollCaption(item.caption);
            scrollViewerCaptionEl.textContent = caption || 'No caption yet.';
        }
        setScrollViewerFollowButtonState(scrollViewerFollowBtn, isOwnScroll, !!item.is_following);
        setScrollViewerFollowButtonState(scrollViewerMobileFollowBtn, isOwnScroll, !!item.is_following);
        if (scrollViewerLikeBtn) {
            scrollViewerLikeBtn.innerHTML = `<i class="fa-solid fa-thumbs-up" aria-hidden="true"></i><span class="scrolls-action-count">${Math.max(0, Number(item.like_count || 0) || 0)}</span>`;
            scrollViewerLikeBtn.classList.toggle('is-active', item.user_reaction === 'like');
        }
        if (scrollViewerDislikeBtn) {
            scrollViewerDislikeBtn.innerHTML = `<i class="fa-solid fa-thumbs-down" aria-hidden="true"></i><span class="scrolls-action-count">${Math.max(0, Number(item.dislike_count || 0) || 0)}</span>`;
            scrollViewerDislikeBtn.classList.toggle('is-active', item.user_reaction === 'dislike');
        }
        if (scrollViewerCommentsBtn) {
            const isCommentsOpen = (scrollViewerCommentsMode && !isMobileViewport())
                || scrollCommentsSheetActiveScrollId === activeScrollViewerId;
            scrollViewerCommentsBtn.innerHTML = `<i class="fa-solid fa-comments" aria-hidden="true"></i><span class="scrolls-action-count">${commentCount}</span>`;
            scrollViewerCommentsBtn.classList.toggle('is-active', isCommentsOpen);
            scrollViewerCommentsBtn.setAttribute('aria-label', isCommentsOpen ? 'Close comments' : 'Open comments');
            scrollViewerCommentsBtn.setAttribute('title', isCommentsOpen ? 'Close comments' : 'Open comments');
        }
        syncScrollCommentMeta(activeScrollViewerId);
        syncScrollViewerPlaybackUi();
    }

    async function loadScrollsFeed({ force = false } = {}) {
        ensureScrollsPanelUi();
        if (scrollsFeedLoadingPromise && !force) {
            return scrollsFeedLoadingPromise;
        }

        setScrollsStatus('Loading Scrolls...');
        scrollsFeedLoadingPromise = (async () => {
            try {
                const response = await fetch(`fetch_scrolls.php?token=${encodeURIComponent(token)}&t=${Date.now()}`);
                const data = await response.json().catch(() => ({}));
                if (!response.ok || !data.success) {
                    throw new Error(data && data.error ? data.error : 'Could not load Scrolls right now.');
                }
                scrollsFeedItems = Array.isArray(data.items) ? data.items : [];
                renderScrollsFeed();
                setScrollsStatus(scrollsFeedItems.length ? '' : 'No videos yet');
                return scrollsFeedItems;
            } catch (error) {
                console.error('Failed to load Scrolls.', error);
                scrollsFeedItems = [];
                renderScrollsFeed();
                setScrollsStatus(error && error.message ? error.message : 'Could not load Scrolls right now.');
                return [];
            } finally {
                scrollsFeedLoadingPromise = null;
            }
        })();

        return scrollsFeedLoadingPromise;
    }

    function bindScrollPreviewVideo(videoEl) {
        if (!videoEl || videoEl.dataset.scrollPreviewBound === '1') {
            return;
        }

        videoEl.dataset.scrollPreviewBound = '1';
        const previewTime = 0.45;

        const syncPreviewFrame = () => {
            try {
                if (videoEl.readyState >= 1) {
                    videoEl.currentTime = previewTime;
                }
            } catch (error) {}
        };

        videoEl.addEventListener('loadedmetadata', syncPreviewFrame);
        videoEl.addEventListener('mouseenter', () => {
            if (isMobileViewport()) {
                return;
            }
            videoEl.muted = true;
            videoEl.play().catch(() => {});
        });
        videoEl.addEventListener('mouseleave', () => {
            if (isMobileViewport()) {
                return;
            }
            videoEl.pause();
            syncPreviewFrame();
        });
    }

    function renderScrollsFeed() {
        ensureScrollsPanelUi();
        if (!scrollsGridEl || !scrollsEmptyEl) {
            return;
        }

        scrollsGridEl.innerHTML = '';
        const hasItems = scrollsFeedItems.length > 0;
        scrollsEmptyEl.hidden = hasItems;
        scrollsGridEl.hidden = !hasItems;

        if (!hasItems) {
            scrollsEmptyEl.textContent = 'No videos yet';
            if (activeScrollViewerId) {
                closeScrollViewer();
            }
            return;
        }

        scrollsFeedItems.forEach(item => {
            const normalizedScrollId = Math.max(0, Number(item && item.id ? item.id : 0) || 0);
            const normalizedTitle = normalizeScrollTitle(item.title);
            const isOwnScroll = Number(item.uploader_id || 0) === Number(currentUserId || 0);

            const card = document.createElement('article');
            card.className = 'scroll-card';
            card.dataset.scrollId = String(normalizedScrollId);
            card.tabIndex = 0;
            card.setAttribute('role', 'button');
            card.setAttribute('aria-label', normalizedTitle
                ? `Watch ${normalizedTitle} by ${item.uploader_display_name || 'QuillTalk user'}`
                : `Watch ${item.uploader_display_name || 'scroll'}`);

            const openCardViewer = () => {
                ensureScrollsPanelUi();
                if (!scrollViewerPanelEl || !scrollViewerVideoEl) {
                    return;
                }
                openScrollViewer(normalizedScrollId);
            };

            const mediaWrap = document.createElement('div');
            mediaWrap.className = 'scroll-card-video-wrap';

            const video = document.createElement('video');
            video.className = 'scroll-card-video';
            video.src = String(item.video_path || '');
            video.muted = true;
            video.playsInline = true;
            video.preload = 'metadata';
            bindScrollPreviewVideo(video);
            mediaWrap.appendChild(video);

            const overlay = document.createElement('div');
            overlay.className = 'scroll-card-overlay';

            const copy = document.createElement('div');
            copy.className = 'scroll-card-copy';
            if (normalizedTitle) {
                const titleEl = document.createElement('div');
                titleEl.className = 'scroll-card-title';
                titleEl.textContent = normalizedTitle;
                copy.appendChild(titleEl);
            }

            const author = document.createElement('div');
            author.className = 'scroll-card-author';
            author.textContent = String(item.uploader_display_name || 'QuillTalk user');
            copy.appendChild(author);

            const stats = document.createElement('div');
            stats.className = 'scroll-card-stats';
            stats.innerHTML = `<span><i class="fa-solid fa-thumbs-up" aria-hidden="true"></i>${Math.max(0, Number(item.like_count || 0) || 0)}</span><span><i class="fa-solid fa-thumbs-down" aria-hidden="true"></i>${Math.max(0, Number(item.dislike_count || 0) || 0)}</span>`;
            copy.appendChild(stats);
            overlay.appendChild(copy);

            const actionRail = document.createElement('div');
            actionRail.className = 'scroll-card-actions';

            if (!isOwnScroll) {
                const followBtn = document.createElement('button');
                followBtn.type = 'button';
                followBtn.className = 'scroll-card-action-btn';
                followBtn.classList.toggle('is-active', !!item.is_following);
                followBtn.setAttribute('aria-label', item.is_following ? 'Following creator' : 'Follow creator');
                followBtn.setAttribute('title', item.is_following ? 'Following creator' : 'Follow creator');
                followBtn.innerHTML = item.is_following
                    ? '<i class="fa-solid fa-user-check" aria-hidden="true"></i>'
                    : '<i class="fa-solid fa-user-plus" aria-hidden="true"></i>';
                followBtn.addEventListener('click', event => {
                    event.preventDefault();
                    event.stopPropagation();
                    toggleScrollFollowState(normalizedScrollId);
                });
                actionRail.appendChild(followBtn);
            }

            const likeBtn = document.createElement('button');
            likeBtn.type = 'button';
            likeBtn.className = 'scroll-card-action-btn';
            likeBtn.classList.toggle('is-active', item.user_reaction === 'like');
            likeBtn.setAttribute('aria-label', 'Like Scroll');
            likeBtn.setAttribute('title', 'Like Scroll');
            likeBtn.innerHTML = `<i class="fa-solid fa-thumbs-up" aria-hidden="true"></i><span class="scrolls-action-count">${Math.max(0, Number(item.like_count || 0) || 0)}</span>`;
            likeBtn.addEventListener('click', event => {
                event.preventDefault();
                event.stopPropagation();
                submitScrollReaction(normalizedScrollId, 'like');
            });
            actionRail.appendChild(likeBtn);

            const dislikeBtn = document.createElement('button');
            dislikeBtn.type = 'button';
            dislikeBtn.className = 'scroll-card-action-btn';
            dislikeBtn.classList.toggle('is-active', item.user_reaction === 'dislike');
            dislikeBtn.setAttribute('aria-label', 'Dislike Scroll');
            dislikeBtn.setAttribute('title', 'Dislike Scroll');
            dislikeBtn.innerHTML = `<i class="fa-solid fa-thumbs-down" aria-hidden="true"></i><span class="scrolls-action-count">${Math.max(0, Number(item.dislike_count || 0) || 0)}</span>`;
            dislikeBtn.addEventListener('click', event => {
                event.preventDefault();
                event.stopPropagation();
                submitScrollReaction(normalizedScrollId, 'dislike');
            });
            actionRail.appendChild(dislikeBtn);

            overlay.appendChild(actionRail);
            mediaWrap.appendChild(overlay);
            card.appendChild(mediaWrap);

            card.addEventListener('click', event => {
                if (event.target && typeof event.target.closest === 'function' && event.target.closest('button')) {
                    return;
                }
                openCardViewer();
            });
            card.addEventListener('keydown', event => {
                if (event.target && typeof event.target.closest === 'function' && event.target.closest('button')) {
                    return;
                }
                if (event.key !== 'Enter' && event.key !== ' ') {
                    return;
                }
                event.preventDefault();
                openCardViewer();
            });

            scrollsGridEl.appendChild(card);
        });

        syncScrollViewerVisibility();
        if (activeScrollViewerId && getScrollFeedItem(activeScrollViewerId)) {
            syncScrollViewerState(activeScrollViewerId);
        }
    }

    async function submitScrollReaction(scrollId, reactionType) {
        const normalizedScrollId = Math.max(0, Number(scrollId || 0) || 0);
        if (!normalizedScrollId || !['like', 'dislike'].includes(String(reactionType || ''))) {
            return;
        }

        try {
            const response = await fetch('toggle_scroll_reaction.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    scroll_id: normalizedScrollId,
                    reaction_type: reactionType
                })
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(data && data.error ? data.error : 'Could not update the reaction.');
            }

            scrollsFeedItems = scrollsFeedItems.map(item => {
                if (Number(item && item.id ? item.id : 0) !== normalizedScrollId) {
                    return item;
                }
                return {
                    ...item,
                    like_count: Math.max(0, Number(data.like_count || 0) || 0),
                    dislike_count: Math.max(0, Number(data.dislike_count || 0) || 0),
                    user_reaction: String(data.user_reaction || '')
                };
            });
            renderScrollsFeed();
        } catch (error) {
            console.error('Unable to update scroll reaction.', error);
            showToast(error && error.message ? error.message : 'Could not update the reaction.', 'error');
        }
    }

    async function toggleScrollFollowState(scrollId) {
        const item = getScrollFeedItem(scrollId);
        const targetUserId = Math.max(0, Number(item && item.uploader_id ? item.uploader_id : 0) || 0);
        if (!targetUserId || targetUserId === Number(currentUserId || 0)) {
            return;
        }

        try {
            const response = await fetch('toggle_scroll_follow.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    target_user_id: targetUserId
                })
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(data && data.error ? data.error : 'Could not update follow state.');
            }

            scrollsFeedItems = scrollsFeedItems.map(feedItem => {
                if (Number(feedItem && feedItem.uploader_id ? feedItem.uploader_id : 0) !== targetUserId) {
                    return feedItem;
                }
                return {
                    ...feedItem,
                    is_following: !!data.is_following,
                    follower_count: Math.max(0, Number(data.follower_count || 0) || 0)
                };
            });
            renderScrollsFeed();
        } catch (error) {
            console.error('Unable to update follow state.', error);
            showToast(error && error.message ? error.message : 'Could not update follow state.', 'error');
        }
    }

    function ensureScrollsPanelUi() {
        if (scrollsPanel || !contactsList || !document.body) {
            return;
        }

        scrollsPanel = document.createElement('section');
        scrollsPanel.className = 'scrolls-panel';
        scrollsPanel.hidden = true;

        const head = document.createElement('div');
        head.className = 'scrolls-panel-head';

        const titleWrap = document.createElement('div');
        titleWrap.className = 'scrolls-panel-title';
        titleWrap.innerHTML = '<strong>Scrolls</strong><span>Short-form videos from across QuillTalk.</span>';
        head.appendChild(titleWrap);

        const actionWrap = document.createElement('div');
        actionWrap.className = 'scrolls-panel-actions';
        scrollsCreateBtn = document.createElement('button');
        scrollsCreateBtn.type = 'button';
        scrollsCreateBtn.className = 'sidebar-new-trigger scrolls-create-trigger';
