        scrollsGridEl.className = 'scrolls-grid';
        scrollsGridEl.hidden = true;

        gridWrap.appendChild(scrollsEmptyEl);
        gridWrap.appendChild(scrollsGridEl);

        scrollsPanel.appendChild(head);
        scrollsPanel.appendChild(scrollsStatusEl);
        scrollsPanel.appendChild(gridWrap);
        contactsList.insertAdjacentElement('afterend', scrollsPanel);

        scrollComposerModalEl = document.createElement('div');
        scrollComposerModalEl.className = 'friend-request-modal';
        scrollComposerModalEl.setAttribute('aria-hidden', 'true');
        scrollComposerModalEl.innerHTML = `
            <div class="friend-request-modal-dialog scrolls-compose-dialog" role="dialog" aria-modal="true" aria-labelledby="scrollComposerTitle">
                <button type="button" class="friend-request-modal-close" data-scroll-compose-close aria-label="Close scroll composer">
                    <i class="fa-solid fa-xmark" aria-hidden="true"></i>
                </button>
                <div class="friend-request-modal-head">
                    <p class="friend-request-modal-kicker">Scrolls</p>
                    <h2 id="scrollComposerTitle">Create a Scroll</h2>
                    <p><?= htmlspecialchars($scrollComposerIntroCopy, ENT_QUOTES) ?></p>
                </div>
                <div class="scrolls-compose-body">
                    <div class="scrolls-compose-picker">
