        document.body.appendChild(scrollComposerModalEl);

        scrollComposerVideoInput = scrollComposerModalEl.querySelector('[data-scroll-compose-input]');
        scrollComposerPreviewEl = scrollComposerModalEl.querySelector('[data-scroll-compose-preview]');
        scrollComposerTitleInput = scrollComposerModalEl.querySelector('[data-scroll-compose-title]');
        scrollComposerCaptionInput = scrollComposerModalEl.querySelector('[data-scroll-compose-caption]');
        scrollComposerStatusEl = scrollComposerModalEl.querySelector('[data-scroll-compose-status]');
        scrollComposerCancelBtn = scrollComposerModalEl.querySelector('[data-scroll-compose-cancel]');
