        const scrollComposeCloseBtn = scrollComposerModalEl.querySelector('[data-scroll-compose-close]');
        const scrollComposePickBtn = scrollComposerModalEl.querySelector('[data-scroll-compose-pick]');

        if (scrollComposeCloseBtn) {
            scrollComposeCloseBtn.addEventListener('click', closeScrollComposerModal);
        }
        if (scrollComposerCancelBtn) {
            scrollComposerCancelBtn.addEventListener('click', closeScrollComposerModal);
        }
        if (scrollComposePickBtn && scrollComposerVideoInput) {
            scrollComposePickBtn.addEventListener('click', () => scrollComposerVideoInput.click());
        }
        if (scrollComposerModalEl) {
            scrollComposerModalEl.addEventListener('click', event => {
                if (event.target === scrollComposerModalEl) {
                    closeScrollComposerModal();
                }
            });
        }
        if (scrollComposerVideoInput) {
            scrollComposerVideoInput.addEventListener('change', () => {
                const file = scrollComposerVideoInput.files && scrollComposerVideoInput.files[0]
                    ? scrollComposerVideoInput.files[0]
                    : null;
                if (!file) {
                    return;
                }
                if (file.type && !file.type.startsWith('video/')) {
                    scrollComposerSelectedFile = null;
                    releaseScrollComposerPreviewUrl();
                    if (scrollComposerPreviewEl) {
                        scrollComposerPreviewEl.innerHTML = '<span>Choose a vertical video to preview it here.</span>';
                    }
                    setScrollComposerStatus('Please choose a video file for your Scroll.', 'error');
                    scrollComposerVideoInput.value = '';
                    return;
                }
                if (scrollsMaxUploadBytes > 0 && Number(file.size || 0) > scrollsMaxUploadBytes) {
                    scrollComposerSelectedFile = null;
                    releaseScrollComposerPreviewUrl();
                    if (scrollComposerPreviewEl) {
                        scrollComposerPreviewEl.innerHTML = '<span>Choose a vertical video to preview it here.</span>';
                    }
                    setScrollComposerStatus(getScrollComposerUploadLimitMessage(), 'error');
                    scrollComposerVideoInput.value = '';
                    return;
                }

                scrollComposerSelectedFile = file;
                releaseScrollComposerPreviewUrl();
                scrollComposerPreviewUrl = URL.createObjectURL(file);
                if (scrollComposerPreviewEl) {
                    scrollComposerPreviewEl.innerHTML = '';
                    const previewVideo = document.createElement('video');
                    previewVideo.src = scrollComposerPreviewUrl;
                    previewVideo.controls = true;
                    previewVideo.muted = true;
                    previewVideo.playsInline = true;
                    previewVideo.preload = 'metadata';
                    scrollComposerPreviewEl.appendChild(previewVideo);
                }
                setScrollComposerStatus('Video ready. Add a caption and post it whenever you are ready.');
            });
        }
        if (scrollComposerPostBtn) {
            scrollComposerPostBtn.addEventListener('click', async () => {
                if (!scrollComposerSelectedFile) {
                    setScrollComposerStatus('Choose a video before posting your Scroll.', 'error');
                    return;
                }

                if (scrollsMaxUploadBytes > 0 && Number(scrollComposerSelectedFile.size || 0) > scrollsMaxUploadBytes) {
                    setScrollComposerStatus(getScrollComposerUploadLimitMessage(), 'error');
                    return;
                }

                setScrollComposerStatus('Posting your Scroll...');
                scrollComposerPostBtn.disabled = true;

                try {
                    const formData = new FormData();
                    formData.append('token', token);
                    formData.append('video_file', scrollComposerSelectedFile);
                    formData.append('title', scrollComposerTitleInput ? normalizeScrollTitle(scrollComposerTitleInput.value) : '');
                    formData.append('caption', scrollComposerCaptionInput ? scrollComposerCaptionInput.value.trim() : '');

                    const response = await fetch('create_scroll.php', {
                        method: 'POST',
                        body: formData
                    });
                    const data = await response.json().catch(() => ({}));
                    if (!response.ok || !data.success) {
                        throw new Error(data && data.error ? data.error : 'Could not post that Scroll right now.');
                    }

                    setScrollComposerStatus('Your Scroll is live.', 'success');
                    await loadScrollsFeed({ force: true });
                    closeScrollComposerModal();
                    showToast('Scroll posted', 'success');
                } catch (error) {
                    console.error('Unable to create Scroll.', error);
                    const errorMessage = getScrollComposerPostErrorMessage(error);
                    setScrollComposerStatus(errorMessage, 'error');
                    showToast(errorMessage, 'error');
                } finally {
                    if (scrollComposerPostBtn) {
                        scrollComposerPostBtn.disabled = false;
                    }
                }
            });
        }

