        if (scrollViewerCloseBtn) {
            scrollViewerCloseBtn.addEventListener('click', closeScrollViewer);
        }
        if (scrollViewerFollowBtn) {
            scrollViewerFollowBtn.addEventListener('click', () => toggleScrollFollowState(activeScrollViewerId));
        }
        if (scrollViewerMobileFollowBtn) {
            scrollViewerMobileFollowBtn.addEventListener('click', () => toggleScrollFollowState(activeScrollViewerId));
        }
        if (scrollViewerLikeBtn) {
            scrollViewerLikeBtn.addEventListener('click', () => submitScrollReaction(activeScrollViewerId, 'like'));
        }
        if (scrollViewerDislikeBtn) {
            scrollViewerDislikeBtn.addEventListener('click', () => submitScrollReaction(activeScrollViewerId, 'dislike'));
        }
        if (scrollViewerCommentsBtn) {
            scrollViewerCommentsBtn.addEventListener('click', async () => {
                if (isMobileViewport()) {
                    if (scrollCommentsSheetActiveScrollId === activeScrollViewerId) {
                        closeScrollCommentsSheet();
                        return;
                    }
                    await openScrollCommentsSheet(activeScrollViewerId);
                    return;
                }
                await setScrollViewerCommentsMode(!scrollViewerCommentsMode);
            });
        }
        if (scrollViewerMuteBtn && scrollViewerVideoEl) {
            scrollViewerMuteBtn.addEventListener('click', () => {
                scrollViewerVideoEl.muted = !scrollViewerVideoEl.muted;
                syncScrollViewerPlaybackUi();
            });
        }
        if (scrollViewerLoopBtn && scrollViewerVideoEl) {
            scrollViewerLoopBtn.addEventListener('click', () => {
                scrollViewerVideoEl.loop = !scrollViewerVideoEl.loop;
                syncScrollViewerPlaybackUi();
            });
        }
        if (scrollViewerPlayBtn) {
            scrollViewerPlayBtn.addEventListener('click', () => {
                toggleActiveScrollViewerPlayback();
            });
        }
        if (scrollViewerCommentsCloseBtn) {
            scrollViewerCommentsCloseBtn.addEventListener('click', () => {
                void setScrollViewerCommentsMode(false);
            });
        }
        if (scrollViewerCommentsSubmitBtn) {
            scrollViewerCommentsSubmitBtn.addEventListener('click', () => {
                void submitScrollComment(activeScrollViewerId, scrollViewerCommentsInputEl, scrollViewerCommentsStatusEl, scrollViewerCommentsSubmitBtn);
            });
        }
        if (scrollViewerCommentsListEl) {
            scrollViewerCommentsListEl.addEventListener('click', handleScrollCommentListClick);
        }
        if (scrollViewerCommentsInputEl) {
            scrollViewerCommentsInputEl.addEventListener('keydown', event => {
                if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') {
                    event.preventDefault();
                    void submitScrollComment(activeScrollViewerId, scrollViewerCommentsInputEl, scrollViewerCommentsStatusEl, scrollViewerCommentsSubmitBtn);
                }
            });
        }
        if (scrollViewerCommentsReplyClearBtn) {
            scrollViewerCommentsReplyClearBtn.addEventListener('click', () => {
                clearActiveScrollCommentReply();
                focusActiveScrollCommentInput(false);
            });
        }
        if (scrollViewerProgressEl && scrollViewerVideoEl) {
            scrollViewerProgressEl.addEventListener('input', () => {
                const nextTime = Math.max(0, Number(scrollViewerProgressEl.value || 0) || 0);
                try {
                    scrollViewerVideoEl.currentTime = nextTime;
                } catch (error) {}
                syncScrollViewerPlaybackUi();
            });
        }
        if (scrollViewerSpeedSelect && scrollViewerVideoEl) {
            scrollViewerSpeedSelect.addEventListener('change', () => {
                const nextRate = Number(scrollViewerSpeedSelect.value || 1) || 1;
                scrollViewerVideoEl.playbackRate = nextRate;
                syncScrollViewerPlaybackUi();
            });
        }
        if (scrollViewerVideoEl) {
            scrollViewerVideoEl.addEventListener('click', () => {
                toggleActiveScrollViewerPlayback();
            });
            ['loadedmetadata', 'durationchange', 'timeupdate', 'play', 'pause', 'volumechange', 'ended'].forEach(eventName => {
                scrollViewerVideoEl.addEventListener(eventName, () => {
                    syncScrollViewerPlaybackUi();
                });
            });
        }
        if (scrollViewerStageEl) {
            scrollViewerStageEl.addEventListener('wheel', handleScrollViewerWheelNavigation, { passive: false });
            scrollViewerStageEl.addEventListener('touchstart', handleScrollViewerTouchStart, { passive: true });
            scrollViewerStageEl.addEventListener('touchend', handleScrollViewerTouchEnd, { passive: true });
        }
        if (scrollCommentsOverlayEl) {
            scrollCommentsOverlayEl.addEventListener('click', event => {
                if (event.target === scrollCommentsOverlayEl) {
                    closeScrollCommentsSheet();
                }
            });
        }
        if (scrollCommentsSheetEl) {
            scrollCommentsSheetEl.addEventListener('click', event => {
                event.stopPropagation();
            });
        }
        if (scrollCommentsSheetCloseBtn) {
            scrollCommentsSheetCloseBtn.addEventListener('click', closeScrollCommentsSheet);
        }
        if (scrollCommentsSheetSubmitBtn) {
            scrollCommentsSheetSubmitBtn.addEventListener('click', () => {
                void submitScrollComment(scrollCommentsSheetActiveScrollId || activeScrollViewerId, scrollCommentsSheetInputEl, scrollCommentsSheetStatusEl, scrollCommentsSheetSubmitBtn);
            });
        }
        if (scrollCommentsSheetListEl) {
            scrollCommentsSheetListEl.addEventListener('click', handleScrollCommentListClick);
        }
        if (scrollCommentsSheetInputEl) {
            scrollCommentsSheetInputEl.addEventListener('keydown', event => {
                if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') {
                    event.preventDefault();
                    void submitScrollComment(scrollCommentsSheetActiveScrollId || activeScrollViewerId, scrollCommentsSheetInputEl, scrollCommentsSheetStatusEl, scrollCommentsSheetSubmitBtn);
                }
            });
        }
        if (scrollCommentsSheetReplyClearBtn) {
            scrollCommentsSheetReplyClearBtn.addEventListener('click', () => {
                clearActiveScrollCommentReply();
                focusActiveScrollCommentInput(true);
            });
        }
    }

    function restoreScrollsPanelToSidebar() {
        if (!scrollsPanel || !contactsList) {
            return;
        }

        if (scrollsPanel.parentElement === desktopContactViewHost) {
            contactsList.insertAdjacentElement('afterend', scrollsPanel);
        }
    }

    function renderDesktopArchivedContacts(contacts = null, query = getNormalizedContactsSearchQuery()) {
        ensureDesktopContactViewUi();
        if (!desktopArchivedListEl || !contactsList) {
            return;
        }

        const sourceContacts = Array.isArray(contacts)
            ? contacts
            : [...contactsList.querySelectorAll('.contact')].sort((a, b) => compareContactsForSort(a, b, query));
        const archivedContacts = sourceContacts.filter(contact => contactMatchesView(contact, 'archived', query));

        desktopArchivedListEl.innerHTML = '';

        if (!archivedContacts.length) {
            const emptyEl = document.createElement('div');
            emptyEl.className = 'sidebar-history-empty';
            emptyEl.textContent = query
                ? 'No archived chats match your search.'
                : 'Archived chats will show up here once you archive them.';
            desktopArchivedListEl.appendChild(emptyEl);
            return;
        }

        archivedContacts.forEach(contact => {
            const chatId = String(contact.dataset.id || '').trim();
            if (!chatId) {
                return;
            }

            const clone = contact.cloneNode(true);
            clone.classList.add('desktop-archived-item');
            clone.classList.remove('active');
            clone.hidden = false;
            clone.style.display = '';
            clone.setAttribute('role', 'button');
            clone.setAttribute('tabindex', '0');

            clone.querySelectorAll('.contact-more-btn, .contact-restore-btn').forEach(button => button.remove());

            const copy = document.createElement('div');
            copy.className = 'desktop-archived-item-copy';

            const avatarWrap = clone.querySelector('.contact-img-wrapper');
            const textWrap = clone.querySelector('.contact-text');
            if (avatarWrap) {
                avatarWrap.remove();
                copy.appendChild(avatarWrap);
            }
            if (textWrap) {
                textWrap.remove();
                copy.appendChild(textWrap);
            }

            const restoreBtn = document.createElement('button');
            restoreBtn.type = 'button';
            restoreBtn.className = 'desktop-archived-restore-btn';
            restoreBtn.textContent = 'Restore';
            restoreBtn.addEventListener('click', event => {
                event.preventDefault();
                event.stopPropagation();
                if (typeof window.__qtSetArchivedContactState === 'function') {
                    window.__qtSetArchivedContactState(chatId, false);
                }
            });

            clone.innerHTML = '';
            clone.appendChild(copy);
            clone.appendChild(restoreBtn);

            const openArchivedConversation = async event => {
                if (event && event.target && typeof event.target.closest === 'function' && event.target.closest('button')) {
                    return;
                }
                if (event && event.preventDefault) {
                    event.preventDefault();
                }
                await openConversation(chatId);
            };

            clone.addEventListener('click', openArchivedConversation);
            clone.addEventListener('keydown', event => {
                if (event.key === 'Enter' || event.key === ' ') {
                    openArchivedConversation(event);
                }
            });

            desktopArchivedListEl.appendChild(clone);
        });
    }

    window.__qtRenderDesktopArchivedContacts = renderDesktopArchivedContacts;

    function syncDesktopContactViewState(activeView = getActiveContactView()) {
        ensureDesktopContactViewUi();
        if (!desktopContactViewHost) {
            return;
        }

        const replyBarEl = document.getElementById('replyBar');

        const isDesktopAuxView = isDesktopAuxContactView(activeView);
        if (!isDesktopAuxView) {
            if (chatContainerEl) {
                chatContainerEl.classList.remove('desktop-contact-view-active');
            }
            restoreHistoryPanelToSidebar();
            restoreScrollsPanelToSidebar();
            if (desktopArchivedPanel) {
                desktopArchivedPanel.hidden = true;
            }
            desktopContactViewHost.hidden = true;
            if (chatHeaderEl) {
                chatHeaderEl.hidden = false;
            }
            if (chatBox) {
                chatBox.hidden = false;
            }
            if (typingRow) {
                typingRow.hidden = false;
            }
            if (replyBarEl) {
                replyBarEl.hidden = false;
                updateReplyBar();
            }
            if (chatForm) {
                chatForm.style.display = '';
            }
            updateHeaderContact(selectedUser || null);
            return;
        }

        if (chatContainerEl) {
            chatContainerEl.classList.add('desktop-contact-view-active');
        }
        if (chatHeaderEl) {
            chatHeaderEl.hidden = true;
        }
        if (chatBox) {
            chatBox.hidden = true;
        }
        if (typingRow) {
            typingRow.hidden = true;
        }
        if (replyBarEl) {
            replyBarEl.hidden = true;
        }
        if (typeof closeRightSidebar === 'function') {
            closeRightSidebar();
        }

        desktopContactViewHost.hidden = false;
        updateHeaderContact(null);
        if (chatForm) {
            chatForm.style.display = 'none';
        }
        if (attachmentPreviewRow) {
            attachmentPreviewRow.hidden = true;
        }

        if (activeView === 'history') {
            ensureHistoryPanelUi();
            ensureScrollsPanelUi();
            if (historyPanel && historyPanel.parentElement !== desktopContactViewHost) {
                desktopContactViewHost.insertBefore(historyPanel, desktopArchivedPanel || null);
            }
            if (historyPanel) {
                historyPanel.hidden = false;
            }
            if (scrollsPanel) {
                scrollsPanel.hidden = true;
            }
            if (desktopArchivedPanel) {
                desktopArchivedPanel.hidden = true;
            }
            loadSidebarHistory({ force: true });
            return;
        }

        restoreHistoryPanelToSidebar();
        if (historyPanel) {
            historyPanel.hidden = true;
        }

        if (activeView === 'scrolls') {
            ensureScrollsPanelUi();
            if (scrollsPanel && scrollsPanel.parentElement !== desktopContactViewHost) {
                desktopContactViewHost.insertBefore(scrollsPanel, desktopArchivedPanel || null);
            }
            if (scrollsPanel) {
                scrollsPanel.hidden = false;
            }
            if (desktopArchivedPanel) {
                desktopArchivedPanel.hidden = true;
            }
            loadScrollsFeed({ force: true });
            return;
        }

        restoreScrollsPanelToSidebar();
        if (scrollsPanel) {
            scrollsPanel.hidden = true;
        }
        if (desktopArchivedPanel) {
            desktopArchivedPanel.hidden = false;
        }
        renderDesktopArchivedContacts();
    }

    function syncSidebarViewState() {
        const activeView = getActiveContactView();
        const sidebarView = getSidebarContactView(activeView);
        const isHistoryView = sidebarView === 'history';
        const isScrollsView = activeView === 'scrolls';
        const isDesktopAuxView = isDesktopAuxContactView(activeView);
        const useCollapsedRail = shouldUseCollapsedDesktopContactRail(activeView);
        const searchShell = contactsSearchInput ? contactsSearchInput.closest('.sidebar-contact-search') : document.querySelector('.sidebar-contact-search');
        const footerNote = document.querySelector('.sidebar-footer-note');
        const sidebarEl = document.getElementById('sidebar');

        ensureHistoryPanelUi();
        ensureScrollsPanelUi();
        ensureContactsSortUi();
        updateContactTabsPlacement();
        syncDesktopContactViewState(activeView);

        if (sidebarEl) {
            sidebarEl.classList.toggle('is-contact-rail', useCollapsedRail);
        }

        if (contactsList) {
            contactsList.hidden = !useCollapsedRail && (sidebarView === 'history' || sidebarView === 'scrolls');
        }

        if (historyPanel && !isDesktopAuxView) {
            historyPanel.hidden = !isHistoryView;
        }

        if (scrollsPanel && !isDesktopAuxView) {
            scrollsPanel.hidden = !isScrollsView;
        }

        if (searchShell) {
            searchShell.hidden = useCollapsedRail || isHistoryView || isScrollsView;
        }

        if (contactsSortRow) {
            contactsSortRow.hidden = useCollapsedRail || isHistoryView || isScrollsView;
        }

        if (contactsSearchStatus && (useCollapsedRail || isHistoryView || isScrollsView)) {
            contactsSearchStatus.hidden = true;
            contactsSearchStatus.textContent = '';
            delete contactsSearchStatus.dataset.state;
        }

        if (footerNote) {
            footerNote.hidden = useCollapsedRail || isHistoryView || isScrollsView;
        }

        if (isHistoryView) {
            if (archivedContactsEmpty) {
                archivedContactsEmpty.hidden = true;
                archivedContactsEmpty.classList.remove('is-visible');
            }
            loadSidebarHistory({ force: true });
            return;
        }

        if (isScrollsView) {
            if (archivedContactsEmpty) {
                archivedContactsEmpty.hidden = true;
                archivedContactsEmpty.classList.remove('is-visible');
            }
            loadScrollsFeed({ force: true });
        }
    }

    function closeContactQuickActionsMenu() {
        contactQuickActionsActiveUser = '';
        if (!contactQuickActionsOverlay || !contactQuickActionsMenu) {
            return;
        }

        contactQuickActionsOverlay.hidden = true;
        contactQuickActionsOverlay.classList.remove('is-open', 'is-sheet');
        contactQuickActionsMenu.innerHTML = '';
        contactQuickActionsMenu.style.left = '';
        contactQuickActionsMenu.style.right = '';
        contactQuickActionsMenu.style.top = '';
        contactQuickActionsMenu.style.bottom = '';
    }

    function ensureContactQuickActionsUi() {
        if (contactQuickActionsOverlay || !document.body) {
            return;
        }

        contactQuickActionsOverlay = document.createElement('div');
        contactQuickActionsOverlay.className = 'contact-quick-actions-overlay';
        contactQuickActionsOverlay.hidden = true;

        contactQuickActionsMenu = document.createElement('div');
        contactQuickActionsMenu.className = 'contact-quick-actions-menu';
        contactQuickActionsMenu.setAttribute('role', 'menu');

        contactQuickActionsOverlay.appendChild(contactQuickActionsMenu);
        document.body.appendChild(contactQuickActionsOverlay);

        contactQuickActionsOverlay.addEventListener('click', event => {
            if (event.target === contactQuickActionsOverlay) {
                closeContactQuickActionsMenu();
            }
        });

        contactQuickActionsMenu.addEventListener('click', event => {
            event.stopPropagation();
        });

        window.addEventListener('resize', closeContactQuickActionsMenu);
        window.addEventListener('scroll', () => {
            if (
                contactQuickActionsOverlay
                && !contactQuickActionsOverlay.hidden
                && !contactQuickActionsOverlay.classList.contains('is-sheet')
            ) {
                closeContactQuickActionsMenu();
            }
        }, true);
    }

    function createContactSidebarTabs() {
        const sidebarEl = document.getElementById('sidebar');
        if (!contactsList || !sidebarEl) {
            return;
        }

        if (!archivedContactsEmpty) {
            archivedContactsEmpty = document.createElement('div');
            archivedContactsEmpty.className = 'archived-contacts-empty';
            archivedContactsEmpty.hidden = true;
            contactsList.insertAdjacentElement('afterend', archivedContactsEmpty);
        }

        ensureHistoryPanelUi();
        ensureContactsSortUi();

        if (contactViewTabsEl) {
            updateContactTabsPlacement();
            return;
        }

        contactViewTabsEl = document.createElement('div');
        contactViewTabsEl.className = 'sidebar-contact-tabs';

        contactsTabBtn = document.createElement('button');
        contactsTabBtn.type = 'button';
        contactsTabBtn.className = 'sidebar-contact-tab';
        contactsTabBtn.innerHTML = '<i class="fa-solid fa-address-book sidebar-contact-tab-icon" aria-hidden="true"></i><span class="sidebar-contact-tab-label">Contacts</span>';
        contactsTabBtn.setAttribute('aria-label', 'Show contacts');
        contactsTabBtn.addEventListener('click', () => {
            setActiveContactView('contacts');
        });

        scrollsTabBtn = document.createElement('button');
        scrollsTabBtn.type = 'button';
        scrollsTabBtn.className = 'sidebar-contact-tab';
        scrollsTabBtn.innerHTML = '<i class="fa-solid fa-clapperboard sidebar-contact-tab-icon" aria-hidden="true"></i><span class="sidebar-contact-tab-label">Scrolls</span>';
        scrollsTabBtn.setAttribute('aria-label', 'Show Scrolls');
        scrollsTabBtn.addEventListener('click', () => {
            setActiveContactView('scrolls');
        });

        historyTabBtn = document.createElement('button');
        historyTabBtn.type = 'button';
        historyTabBtn.className = 'sidebar-contact-tab';
        historyTabBtn.innerHTML = '<i class="fa-solid fa-clock-rotate-left sidebar-contact-tab-icon" aria-hidden="true"></i><span class="sidebar-contact-tab-label">History</span>';
        historyTabBtn.setAttribute('aria-label', 'Show history');
        historyTabBtn.addEventListener('click', () => {
            setActiveContactView('history');
        });

        archivedTabBtn = document.createElement('button');
        archivedTabBtn.type = 'button';
        archivedTabBtn.className = 'sidebar-contact-tab';
        archivedTabBtn.innerHTML = '<i class="fa-solid fa-box-archive sidebar-contact-tab-icon" aria-hidden="true"></i><span class="sidebar-contact-tab-label">Archived</span>';
        archivedTabBtn.setAttribute('aria-label', 'Show archived chats');
        archivedTabBtn.addEventListener('click', () => {
            setActiveContactView('archived');
        });

        contactViewTabsEl.appendChild(contactsTabBtn);
        contactViewTabsEl.appendChild(scrollsTabBtn);
        contactViewTabsEl.appendChild(historyTabBtn);
        contactViewTabsEl.appendChild(archivedTabBtn);
        updateContactTabsPlacement();
    }

    function updateContactTabsPlacement() {
        if (!contactViewTabsEl) {
            return;
        }

        const sidebarEl = document.getElementById('sidebar');
        const footerNote = sidebarEl ? sidebarEl.querySelector('.sidebar-footer-note') : null;
        const shouldUseDesktopHost = !isMobileViewport() && !!desktopSidebarTabsHost;

        if (shouldUseDesktopHost && desktopSidebarTabsHost) {
            if (contactViewTabsEl.parentElement !== desktopSidebarTabsHost) {
                desktopSidebarTabsHost.innerHTML = '';
                desktopSidebarTabsHost.appendChild(contactViewTabsEl);
            }
        } else if (sidebarEl) {
            if (footerNote) {
                footerNote.insertAdjacentElement('afterend', contactViewTabsEl);
            } else if (contactViewTabsEl.parentElement !== sidebarEl) {
                sidebarEl.appendChild(contactViewTabsEl);
            }
        }

        if (desktopSidebarTabsHost) {
            desktopSidebarTabsHost.hidden = !shouldUseDesktopHost;
        }
    }

    function updateContactViewTabs() {
        if (contactsTabBtn) {
            contactsTabBtn.classList.toggle('is-active', getActiveContactView() === 'contacts');
            contactsTabBtn.setAttribute('aria-pressed', getActiveContactView() === 'contacts' ? 'true' : 'false');
        }

        if (scrollsTabBtn) {
            scrollsTabBtn.classList.toggle('is-active', getActiveContactView() === 'scrolls');
            scrollsTabBtn.setAttribute('aria-pressed', getActiveContactView() === 'scrolls' ? 'true' : 'false');
        }

        if (historyTabBtn) {
            historyTabBtn.classList.toggle('is-active', getActiveContactView() === 'history');
            historyTabBtn.setAttribute('aria-pressed', getActiveContactView() === 'history' ? 'true' : 'false');
        }

        if (archivedTabBtn) {
            archivedTabBtn.classList.toggle('is-active', getActiveContactView() === 'archived');
            archivedTabBtn.setAttribute('aria-pressed', getActiveContactView() === 'archived' ? 'true' : 'false');
        }
    }

    function updateArchivedEmptyState({ visibleCount = 0, query = '' } = {}) {
        if (!archivedContactsEmpty || !contactsList) {
            return;
        }

        const isArchivedView = getSidebarContactView() === 'archived';
        const totalArchivedCount = Array.from(contactsList.querySelectorAll('.contact[data-id]')).filter(contactEl => {
            return isArchivedContactId(contactEl.dataset.id || '');
        }).length;

        if (!isArchivedView) {
            archivedContactsEmpty.hidden = true;
            archivedContactsEmpty.classList.remove('is-visible');
            archivedContactsEmpty.textContent = '';
            return;
        }

        if (visibleCount > 0) {
            archivedContactsEmpty.hidden = true;
            archivedContactsEmpty.classList.remove('is-visible');
            archivedContactsEmpty.textContent = '';
            return;
        }

        archivedContactsEmpty.hidden = false;
        archivedContactsEmpty.classList.add('is-visible');
        archivedContactsEmpty.textContent = query
            ? 'No archived chats match your search.'
            : (totalArchivedCount > 0
                ? 'No archived chats are visible right now.'
                : 'Archived chats will show up here once you archive them.');
    }

    function setActiveContactView(nextView, { skipSort = false } = {}) {
        activeContactView = nextView === 'archived'
            ? 'archived'
            : (nextView === 'history'
                ? 'history'
                : (nextView === 'scrolls' ? 'scrolls' : 'contacts'));
        const sidebarEl = document.getElementById('sidebar');
        if (sidebarEl) {
            sidebarEl.dataset.contactView = activeContactView;
        }
        updateContactViewTabs();
        syncSidebarViewState();
        closeContactQuickActionsMenu();
        if (!skipSort && typeof sortContactsList === 'function') {
            sortContactsList();
        }
        if (typeof renderMobileContactsStrip === 'function') {
            renderMobileContactsStrip();
        }
        if (typeof updateHeaderOverflow === 'function') {
            updateHeaderOverflow();
        }
    }

    function getContactArchiveDisplayName(userId) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId) {
            return 'contact';
        }

        try {
            if (typeof getContactMeta === 'function') {
                const meta = getContactMeta(normalizedUserId);
                if (meta) {
                    return getDisplayNameForUser(normalizedUserId, meta, normalizedUserId) || meta.displayName || normalizedUserId;
                }
            }
        } catch (error) {
            console.warn('Unable to resolve archived contact display name.', error);
        }

        return normalizedUserId;
    }

    function updateContactActionControls(contactEl) {
        if (!contactEl) {
            return;
        }

        const contactId = String(contactEl.dataset.id || '').trim();
        if (!contactId) {
            return;
        }

        const archived = isArchivedContactId(contactId);
        const pinned = isPinnedChatId(contactId);
        const displayName = getContactArchiveDisplayName(contactId);
        const moreBtn = contactEl.querySelector('.contact-more-btn');
        const restoreBtn = contactEl.querySelector('.contact-restore-btn');

        contactEl.dataset.archived = archived ? '1' : '0';
        contactEl.dataset.pinned = pinned ? '1' : '0';
        contactEl.classList.toggle('is-archived', archived);
        contactEl.classList.toggle('is-pinned', pinned);

        if (moreBtn) {
            moreBtn.setAttribute('aria-label', `More options for ${displayName}`);
            moreBtn.title = `More options for ${displayName}`;
        }

        if (restoreBtn) {
            restoreBtn.hidden = !archived;
            restoreBtn.setAttribute('aria-label', `Restore ${displayName}`);
            restoreBtn.title = `Restore ${displayName}`;
        }
    }

    function ensureContactActionControls(contactEl) {
        if (!contactEl || !contactEl.classList || !contactEl.classList.contains('contact')) {
            return;
        }

        const bindActionButton = (button, handler, markerKey) => {
            if (!button || button.dataset[markerKey] === '1') {
                return;
            }

            if (typeof addTapAndClickListener !== 'function') {
                return;
            }
            addTapAndClickListener(button, handler);
            button.dataset[markerKey] = '1';
        };

        let moreBtn = contactEl.querySelector('.contact-more-btn');
        if (!moreBtn) {
            moreBtn = document.createElement('button');
            moreBtn.type = 'button';
            moreBtn.className = 'contact-more-btn';
            moreBtn.dataset.contactActionTrigger = 'menu';
            moreBtn.innerHTML = '<i class="fa-solid fa-ellipsis-vertical" aria-hidden="true"></i>';
            contactEl.appendChild(moreBtn);
        }
        bindActionButton(moreBtn, event => {
            if (typeof openContactQuickActionsMenu === 'function') {
                openContactQuickActionsMenu(String(contactEl.dataset.id || ''), {
                    anchorEl: moreBtn,
                    event,
                    source: 'button'
                });
            }
        }, 'contactMenuBound');

        let restoreBtn = contactEl.querySelector('.contact-restore-btn');
        if (!restoreBtn) {
            restoreBtn = document.createElement('button');
            restoreBtn.type = 'button';
            restoreBtn.className = 'contact-restore-btn';
            restoreBtn.dataset.contactActionTrigger = 'restore';
            restoreBtn.innerHTML = '<i class="fa-solid fa-rotate-left" aria-hidden="true"></i>';
            contactEl.appendChild(restoreBtn);
        }
        bindActionButton(restoreBtn, event => {
            setArchivedContactState(String(contactEl.dataset.id || ''), false);
            if (event && typeof event.stopPropagation === 'function') {
                event.stopPropagation();
            }
        }, 'contactRestoreBound');

        updateContactActionControls(contactEl);
    }

    function applyStoredArchiveStateToContacts() {
        if (!contactsList) {
            return;
        }

        contactsList.querySelectorAll('.contact').forEach(contactEl => {
            ensureContactActionControls(contactEl);
            updateContactActionControls(contactEl);
        });
    }

    function clearSelectedConversationBecauseArchived(userId) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId || String(selectedUser || '') !== normalizedUserId) {
            return;
        }

        try {
            activeConversationLoadToken += 1;
        } catch (error) {}

        clearLocalTyping(true);
        hideTypingIndicator();
        hideEmojiPicker();
        clearPendingAttachment(true);
        pendingReply = null;
        updateReplyBar();
        hideContactInfoPanel();
        closeRightSidebar();

        if (isMobileViewport()) {
            restoreMobileContactsView({ clearSelection: true });
            return;
        }

        clearActiveContacts();
        selectedUser = null;
        lastId = 0;
        if (chatBox) {
            chatBox.innerHTML = '';
        }
        updateHeaderContact(null);
        updateMobileBackButtonState();
        _autoOpenedFirstContact = false;
        requestAnimationFrame(() => {
            Promise.resolve(maybeOpenTopDesktopContact()).catch(error => {
                console.error('Unable to open next desktop contact after archiving.', error);
            });
        });
    }

    function setArchivedContactState(userId, archived, { showToast = true } = {}) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId) {
            return false;
        }

        const shouldArchive = !!archived;
        const wasArchived = isArchivedContactId(normalizedUserId);
        if (shouldArchive === wasArchived) {
            return false;
        }

        if (shouldArchive) {
            archivedContactIds.add(normalizedUserId);
        } else {
            archivedContactIds.delete(normalizedUserId);
        }

        persistArchivedContactIdsToStorage();
        updateContactActionControls(getContactElement(normalizedUserId));
        clearSelectedConversationBecauseArchived(normalizedUserId);

        if (typeof sortContactsList === 'function') {
            sortContactsList();
        }
        if (typeof renderMobileContactsStrip === 'function') {
            renderMobileContactsStrip();
        }
        if (typeof updateHeaderOverflow === 'function') {
            updateHeaderOverflow();
        }
        if (typeof refreshOpenProfileViews === 'function') {
            refreshOpenProfileViews(normalizedUserId);
        }

        if (showToast) {
            showToast(
                shouldArchive
                    ? `Successfully archived contact ${getContactArchiveDisplayName(normalizedUserId)}`
                    : `Successfully restored contact ${getContactArchiveDisplayName(normalizedUserId)}`,
                'success'
            );
        }

        return true;
    }

    window.__qtGetActiveContactView = getActiveContactView;
    window.__qtIsArchivedContactId = isArchivedContactId;
    window.__qtIsPinnedChatId = isPinnedChatId;
    window.__qtEnsureContactActionControls = ensureContactActionControls;
    window.__qtUpdateContactActionControls = updateContactActionControls;
    window.__qtUpdateArchivedEmptyState = updateArchivedEmptyState;
    window.__qtSetActiveContactView = setActiveContactView;
    window.__qtSetArchivedContactState = setArchivedContactState;
    window.__qtOpenContactQuickActionsMenu = openContactQuickActionsMenu;

    let lastStableMobileViewportHeight = 0;
    let isMessageInputSelected = false;

    function isKeyboardThingTarget(target) {
        return !!(messageInput && target === messageInput);
    }

    function isMessageInputFocused() {
        return isKeyboardThingTarget(document.activeElement);
    }

    function syncMessageInputPlaceholder(forceFocused = null) {
        if (!messageInput) {
            return;
        }

        if (forceFocused !== null) {
            isMessageInputSelected = !!forceFocused;
        }

        const isFocused = !!isMessageInputSelected;

        messageInput.placeholder = isFocused
            ? 'Type a message...'
            : 'Message';
    }

    function isTextEntryTarget(target) {
        if (!(target instanceof HTMLElement)) {
            return false;
        }

        if (target === messageInput) {
            return true;
        }

        if (target.isContentEditable) {
            return true;
        }

        return target.matches('input, textarea, select');
    }

    function setAndroidKeyboardMode(mode) {
        const keyboardBridge = (typeof AndroidKeyboard !== 'undefined' && AndroidKeyboard && typeof AndroidKeyboard.setKeyboardMode === 'function')
            ? AndroidKeyboard
            : (window.QuillTalkAndroid && typeof window.QuillTalkAndroid.setKeyboardMode === 'function'
                ? window.QuillTalkAndroid
                : null);

        if (!keyboardBridge) {
            return;
        }

        keyboardBridge.setKeyboardMode(mode);
    }

    function syncMobileViewportHeight() {
        const viewportHeight = window.visualViewport
            ? Math.round(window.visualViewport.height)
            : window.innerHeight;

        if (!viewportHeight || viewportHeight < 200) {
            return;
        }

        const keyboardLikelyVisible = lastStableMobileViewportHeight > 0
            && (lastStableMobileViewportHeight - viewportHeight) > 120;

        if (!keyboardLikelyVisible) {
            lastStableMobileViewportHeight = viewportHeight;
        }

        const appliedHeight = isMessageInputFocused()
            ? viewportHeight
            : (lastStableMobileViewportHeight || viewportHeight);

        documentRoot.style.setProperty('--qt-app-height', `${appliedHeight}px`);
    }

    function resetMobileViewportHeight() {
        lastStableMobileViewportHeight = 0;
        syncMobileViewportHeight();
    }

    function stopComposerViewportSync() {
        if (composerViewportSyncFrameId) {
            cancelAnimationFrame(composerViewportSyncFrameId);
            composerViewportSyncFrameId = 0;
        }
    }

    function startComposerViewportSync() {
        if (composerViewportSyncFrameId || !messageInput || !isMobileViewport()) {
            return;
        }

        const tick = () => {
            syncMobileViewportHeight();
            if (!isMessageInputFocused() || !isMobileViewport()) {
                composerViewportSyncFrameId = 0;
                return;
            }
            composerViewportSyncFrameId = requestAnimationFrame(tick);
        };

        composerViewportSyncFrameId = requestAnimationFrame(tick);
    }

    function focusMessageInputPreservingSelection() {
        if (!messageInput) {
            return;
        }

        try {
            messageInput.focus({ preventScroll: true });
        } catch (error) {
            messageInput.focus();
        }

        const valueLength = String(messageInput.value || '').length;
        const selectionStart = typeof lastMessageSelectionStart === 'number'
            ? Math.max(0, Math.min(valueLength, lastMessageSelectionStart))
            : valueLength;
        const selectionEnd = typeof lastMessageSelectionEnd === 'number'
            ? Math.max(selectionStart, Math.min(valueLength, lastMessageSelectionEnd))
            : selectionStart;

        try {
            messageInput.setSelectionRange(selectionStart, selectionEnd);
        } catch (error) {}
    }

    window.focusMessageInputPreservingSelection = focusMessageInputPreservingSelection;

    window.setChatActionsDropdownOpen = function setChatActionsDropdownOpen(isOpen) {
        const dropdownButton = document.getElementById('chatActionsBtn');
        const dropdownMenu = document.getElementById('chatActionsDropdown');
        if (!dropdownButton || !dropdownMenu) {
            return;
        }

        if (!isOpen) {
            const activeEl = document.activeElement;
            if (activeEl && dropdownMenu.contains(activeEl)) {
                try {
                    dropdownButton.focus({ preventScroll: true });
                } catch (error) {
                    console.warn('Unable to restore focus before closing chat actions dropdown.', error);
                    if (typeof activeEl.blur === 'function') {
                        activeEl.blur();
                    }
                }
            }
        }

        dropdownMenu.classList.toggle('show', !!isOpen);
        dropdownMenu.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
        dropdownButton.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    };

    function setComposerActionsCollapsed(collapsed) {
        if (!chatForm || !composerActionsBackBtn) {
            return;
        }

        const shouldCollapse = !!collapsed && isMobileViewport();
        chatForm.classList.toggle('composer-actions-collapsed', shouldCollapse);
        composerActionsBackBtn.hidden = !shouldCollapse;
        composerActionsBackBtn.setAttribute('aria-hidden', shouldCollapse ? 'false' : 'true');

        if (composerActionButtons) {
            composerActionButtons.setAttribute('aria-hidden', shouldCollapse ? 'true' : 'false');
        }

        if (shouldCollapse) {
            hideEmojiPicker();
            closeVoiceActionMenu();
            window.setChatActionsDropdownOpen(false);
        }
    }

    function activateComposerKeyboard(options = {}) {
        if (!messageInput || !isMobileViewport()) {
            return;
        }

        if (options.collapseActions !== false) {
            setComposerActionsCollapsed(true);
        }

        setAndroidKeyboardMode('adjustResize');
        syncMobileViewportHeight();
        startComposerViewportSync();
    }

    window.activateComposerKeyboard = activateComposerKeyboard;

    function releaseComposerKeyboard() {
        stopComposerViewportSync();
        setAndroidKeyboardMode('adjustPan');
        syncMobileViewportHeight();
        setComposerActionsCollapsed(false);
        syncMessageInputPlaceholder(false);
    }

    function initializeAppStartup() {
        if (appStartupInitialized) {
            return;
        }

        appStartupInitialized = true;

        if (contactsList) {
            contactsList.querySelectorAll('.contact').forEach(contactEl => {
                syncContactMapsFromElement(contactEl);
                ensureContactActionControls(contactEl);
            });
        }

        syncInitialBlockedUsersFromDom();
        applyStoredArchiveStateToContacts();

        createContactSidebarTabs();
        ensureContactQuickActionsUi();
        {
            const sidebarEl = document.getElementById('sidebar');
            if (sidebarEl) {
                sidebarEl.dataset.contactView = activeContactView;
            }
        }
        updateContactViewTabs();

        if (contactsList) {
            contactsList.querySelectorAll('.contact').forEach(contactEl => {
                refreshPresenceIndicatorsForUser(String(contactEl.dataset.id || ''));
            });
        }

        sortContactsList();
        renderMobileContactsStrip();
        ensurePresenceIndicatorChildren(chatHeaderStatusDot);
        ensurePresenceIndicatorChildren(contactInfoStatusDot);
        syncSidebarViewState();
        syncMobileViewportHeight();
    }

    window.addEventListener('resize', syncMobileViewportHeight);
    window.addEventListener('orientationchange', resetMobileViewportHeight);
    window.addEventListener('resize', syncMessageInputPlaceholder);
    window.addEventListener('orientationchange', syncMessageInputPlaceholder);
    window.addEventListener('resize', () => {
        syncSidebarViewState();
        sortContactsList();
