    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', syncMobileViewportHeight);
        window.visualViewport.addEventListener('scroll', syncMobileViewportHeight);
        window.visualViewport.addEventListener('resize', syncMessageInputPlaceholder);
        window.visualViewport.addEventListener('resize', updateMobileContactsStripScrollbar);
    }
    document.addEventListener('focusin', event => {
        const target = event.target;

        if (isKeyboardThingTarget(target)) {
            activateComposerKeyboard();
            syncMessageInputPlaceholder(true);
            return;
        }

        if (isTextEntryTarget(target)) {
            releaseComposerKeyboard();
            syncMessageInputPlaceholder(false);
            return;
        }

        syncMessageInputPlaceholder(false);
    });
    if (messageInput) {
        const blurMessageInputOnOutsidePress = event => {
            if (!isMobileViewport()) {
                return;
            }

            const target = event.target;
            if (!(target instanceof Node) || !(target instanceof HTMLElement)) {
                return;
            }

            const composerRoot = messageInput.closest('.chat-input');
            if ((composerRoot && composerRoot.contains(target)) || target === messageInput || isTextEntryTarget(target)) {
                return;
            }

            if (!(messageInput.matches(':focus') || isMessageInputFocused())) {
                syncMessageInputPlaceholder(false);
                return;
            }

            requestAnimationFrame(() => {
                try {
                    messageInput.blur();
                } catch (error) {}
                syncMessageInputPlaceholder(false);
            });
        };

        document.addEventListener('pointerdown', blurMessageInputOnOutsidePress);
        document.addEventListener('touchstart', blurMessageInputOnOutsidePress, { passive: true });
    }
    if (messageInput) {
        const primeMessageInputForKeyboard = () => {
            activateComposerKeyboard();
            syncMessageInputPlaceholder(true);
        };

        messageInput.addEventListener('pointerdown', primeMessageInputForKeyboard);
        messageInput.addEventListener('touchstart', primeMessageInputForKeyboard, { passive: true });
        messageInput.addEventListener('click', primeMessageInputForKeyboard);
        messageInput.addEventListener('focus', () => {
            activateComposerKeyboard();
            syncMessageInputPlaceholder(true);
        });
        messageInput.addEventListener('blur', () => {
            requestAnimationFrame(() => {
                if (isMessageInputFocused()) {
                    return;
                }
                releaseComposerKeyboard();
                syncMessageInputPlaceholder(false);
            });
        });
    }
    syncMessageInputPlaceholder();
    if (composerActionsBackBtn) {
        composerActionsBackBtn.addEventListener('mousedown', event => {
            event.preventDefault();
            rememberMessageSelection();
        });
        addTapAndClickListener(composerActionsBackBtn, () => {
            setComposerActionsCollapsed(false);
            activateComposerKeyboard({ collapseActions: false });
            focusMessageInputPreservingSelection();
        });
    }

    function setMobileConversationVisibility(isConversationOpen) {
        if (!isMobileViewport()) {
            return;
        }

        const chatContainer = document.querySelector('.chat-container');
        if (chatContainer) {
            chatContainer.style.display = chatContainer.classList.contains('is-docked-in-chess-modal')
                ? 'flex'
                : (isConversationOpen ? 'flex' : 'none');
        }

        if (sidebar) {
            sidebar.style.display = isConversationOpen ? 'none' : 'flex';
        }

        if (mobileBackBtn) {
            mobileBackBtn.style.display = isConversationOpen ? 'inline-flex' : 'none';
        }

        updateMobileBackButtonState();
    }

    function updateMobileBackButtonState() {
        if (!mobileBackBtn) {
            return;
        }

        const infoOpen = !!(contactInfoPanel && contactInfoPanel.classList.contains('active'));
        mobileBackBtn.dataset.mode = infoOpen ? 'close' : 'back';
        mobileBackBtn.setAttribute('aria-label', infoOpen ? 'Close contact info' : 'Back to contacts');
        mobileBackBtn.title = infoOpen ? 'Close contact info' : 'Back to contacts';
        let icon = mobileBackBtn.querySelector('i');
        if (!icon) {
            icon = document.createElement('i');
            mobileBackBtn.textContent = '';
            mobileBackBtn.appendChild(icon);
        }
        icon.className = infoOpen ? 'fa-solid fa-xmark' : 'fa-solid fa-angle-left';
        icon.setAttribute('aria-hidden', 'true');
    }

    function updateMobileContactsStripScrollbar() {
        if (!mobileContactsStrip || !mobileContactsScrollbar) return;

        // If the strip isn't visible, hide the slider.
        if (mobileContactsStripWrap && mobileContactsStripWrap.hidden) {
            if (typeof mobileContactsScrollbar.hidden !== 'undefined') mobileContactsScrollbar.hidden = true;
            try { mobileContactsScrollbar.max = 0; mobileContactsScrollbar.value = 0; } catch (e) {}
            mobileContactsScrollbar.style.setProperty('--mobile-contacts-scroll-progress', '0%');
            return;
        }

        const visibleWidth = mobileContactsStrip.clientWidth;
        const totalWidth = mobileContactsStrip.scrollWidth;
        const scrollRange = Math.max(totalWidth - visibleWidth, 0);
        const progress = scrollRange > 0
            ? Math.max(0, Math.min(100, (Number(mobileContactsStrip.scrollLeft || 0) / scrollRange) * 100))
            : 0;
        mobileContactsScrollbar.style.setProperty('--mobile-contacts-scroll-progress', `${progress}%`);

        if (scrollRange <= 0) {
            if (typeof mobileContactsScrollbar.hidden !== 'undefined') mobileContactsScrollbar.hidden = true;
            try { mobileContactsScrollbar.max = 0; mobileContactsScrollbar.value = 0; } catch (e) {}
            return;
        }

        // Show and configure the range slider to map to strip.scrollLeft
        if (typeof mobileContactsScrollbar.hidden !== 'undefined') mobileContactsScrollbar.hidden = false;
        try {
            mobileContactsScrollbar.min = 0;
            mobileContactsScrollbar.max = String(Math.round(scrollRange));
            mobileContactsScrollbar.step = '1';
            mobileContactsScrollbar.value = String(Math.round(mobileContactsStrip.scrollLeft || 0));
        } catch (e) {
            // ignore
        }
    }

    if (mobileContactsStrip) {
        mobileContactsStrip.addEventListener('scroll', updateMobileContactsStripScrollbar, { passive: true });
    }
    if (mobileContactsScrollbar && mobileContactsScrollbar.tagName === 'INPUT') {
        // Slider controls horizontal scroll of the contacts strip
        mobileContactsScrollbar.addEventListener('input', (e) => {
            try { mobileContactsStrip.scrollLeft = Number(e.target.value || 0); } catch (err) {}
        });
        mobileContactsScrollbar.addEventListener('change', (e) => {
            try { mobileContactsStrip.scrollLeft = Number(e.target.value || 0); } catch (err) {}
        });
    }
    window.addEventListener('resize', updateMobileContactsStripScrollbar);

    let lastMobileBackActionAt = 0;

    function handleMobileBackAction(event) {
        console.log('DEBUG: handleMobileBackAction invoked', { type: event && event.type, lastMobileBackActionAt });
        if (event) {
            try {
                event.preventDefault();
                event.stopPropagation();
            } catch (e) {
                console.warn('DEBUG: event prevent/stop failed', e);
            }
        }
        const now = Date.now();
        if (now - lastMobileBackActionAt < 200) {
            console.log('DEBUG: handleMobileBackAction suppressed by debounce', { delta: now - lastMobileBackActionAt });
            return;
        }
        lastMobileBackActionAt = now;
        try {
            if (contactInfoPanel && contactInfoPanel.classList.contains('active')) {
                hideContactInfoPanel();
                updateMobileBackButtonState();
                console.log('DEBUG: mobileBackBtn closed the info panel');
                return;
            }
            restoreMobileContactsView();
            console.log('DEBUG: restoreMobileContactsView called from handleMobileBackAction');
        } catch (err) {
            console.error('DEBUG: restoreMobileContactsView threw', err);
        }
    }
