        try {
            inputEl.value = '';
        } catch (error) {
            console.warn('Unable to reset file input before opening the picker.', error);
        }

        try {
            if (typeof inputEl.showPicker === 'function') {
                inputEl.showPicker();
                return;
            }
        } catch (error) {
            console.warn('showPicker() failed. Falling back to click().', error);
        }

