    };

    // If opened from a push notification or external intent for a call,
    // auto-populate the incoming UI. Only explicit Accept actions should
    // auto-answer; plain incoming-call launches should just show the screen.
    const urlParams = new URLSearchParams(window.location.search);
    const shouldAutoAnswerIncomingCall = urlParams.get('auto_answer') === '1'
        || urlParams.get('_sw_action') === 'accept';

    function reportCallPushDebug(stage, details = {}) {
        try {
            fetch('/sw_action_log.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                keepalive: true,
                body: JSON.stringify({
                    action: 'call_push_debug',
                    stage,
                    ...details
                })
            }).catch(() => {});
        } catch (error) {}
    }

    if (urlParams.get('incoming_call') === '1') {
        const callerId = parseInt(urlParams.get('caller_id') || '0', 10);
        const callReqId = parseInt(urlParams.get('call_request_id') || '0', 10);
        const callerName = decodeURIComponent(urlParams.get('caller_name') || '');
        const callerUsername = decodeURIComponent(urlParams.get('caller_username') || '');
        const callerPic = decodeURIComponent(urlParams.get('caller_pic') || '') || 'images/default-profile.png';
        if (callerId && callReqId) {
            // Defer handling until after script initialization to avoid
            // accessing block-scoped call UI variables before they are set.
            setTimeout(async () => {
                try {
                    showIncomingCallRequest({
                        id: callReqId,
                        caller_id: callerId,
                        display_name: callerName || `User ${callerId}`,
                        username: callerUsername || '',
                        profile_pic: callerPic
                    });

                    // Give the UI a moment to wire up handlers (accept button, etc.)
                    await new Promise(r => setTimeout(r, 250));

                    if (!shouldAutoAnswerIncomingCall) {
                        return;
                    }

                    // Explicit Accept actions should reuse the same acceptance
                    // flow as the in-page button so the user joins immediately.
                    try {
                        const acceptBtn = document.getElementById('accept-call-btn');
                        if (acceptBtn) {
                            // Use the existing click handler to reuse logic.
                            acceptBtn.click();
                        } else {
                            // Fallback: directly mark the request accepted then set UI state
                            const accepted = await syncCallRequestStatus('accepted', callReqId);
                            if (accepted) {
                                // Mimic accepted UI state
                                ringtoneAudio.pause();
                                ringtoneAudio.currentTime = 0;
                                callStatus.innerText = 'Connecting...';
                                directCallUiMode = 'connecting';
                                showPendingDirectCallControls('connecting');
                                clearLocalTyping(true);
                                hideTypingIndicator();
                                selectedUser = callerId;
                                updateHeaderContact(selectedUser);
                            }
                        }
                    } catch (e) {}
                } catch (e) {
                    console.error('Incoming call URL handling failed', e);
                }
            }, 0);
        }
    }

    // Request mic permission on load for receiving calls
    navigator.mediaDevices.getUserMedia({ audio: true }).then(() => {
        console.log('Mic permission granted on load');
    }).catch(() => {
        console.log('Mic permission denied on load');
    });

    // Listen for service worker messages (e.g., notification actions)
    if (navigator.serviceWorker) {
        navigator.serviceWorker.addEventListener('message', (event) => {
            try { console.log('SW_MSG_RECEIVED', event.data); } catch (e) {}
            const { type, payload } = event.data || {};
            if (type === 'call_rejected_from_notification' && payload && payload.call_request_id) {
                    fetch('update_call_request.php', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            token,
                            id: payload.call_request_id,
                            status: 'rejected'
                        })
                    }).catch(() => {});
                    return;
                }

                if (type === 'call_accepted_from_notification' && payload && payload.call_request_id) {
                    // A notification action accepted the call. Show the incoming UI.
                    // Only auto-trigger the local accept flow if the SW explicitly
                    // marked this message as originating from the Accept action
                    // (payload._sw_action === 'accept'). Otherwise just show UI.
                    try {
                        const p = payload;
                        setTimeout(() => {
                            try {
                                showIncomingCallRequest({
                                    id: parseInt(p.call_request_id || '0', 10),
                                    caller_id: parseInt(p.caller_id || '0', 10),
                                    display_name: p.caller_name || p.caller_username || `User ${p.caller_id}`,
                                    username: p.caller_username || '',
                                    profile_pic: p.caller_pic || 'images/default-profile.png'
                                });
                            } catch (e) {}

                            const shouldAutoAccept = !!(p && (p._sw_action === 'accept' || p._accepted === true));
                            if (shouldAutoAccept) {
                                try { console.log('SW_AUTO_ACCEPT_TRIGGER', p); } catch (e) {}
                                setTimeout(() => {
                                    try {
                                        const acceptBtnEl = document.getElementById('accept-call-btn');
                                        if (acceptBtnEl) acceptBtnEl.click();
                                    } catch (err) {}
                                }, 250);
                            }
                        }, 0);
                    } catch (e) {}
                    return;
                }

                if (type === 'push_message') {
                pollContacts();
                if (selectedUser) {
                    pollMessages();
                } else {
                    refreshUnreadBadges();
                }
            }
        });
    }

    function clearUnreadBadgeForChat(chatKey) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) return;
        // Also clear any tracked mention count
        delete mentionUnreadCounts[normalizedChatKey];
        const contact = document.querySelector(`.contact[data-id="${normalizedChatKey}"]`);
        if (!contact) return;
        contact.classList.remove('unread');
        const badge = contact.querySelector('.unread-badge');
        if (badge) badge.remove();
        
        // Update page title after clearing badge
        updatePageTitleFromBadges();
    }
    
    function updatePageTitleFromBadges() {
        // Count all visible unread badges
        let totalUnread = 0;
        document.querySelectorAll('.contact .unread-badge').forEach(badge => {
            const count = parseInt(badge.textContent || '0', 10);
            totalUnread += count;
        });
        updatePageTitle(totalUnread);
        updateUnreadAttentionCue();
    }

    function ensureUnreadAttentionCueElement() {
        if (unreadAttentionCueEl && document.body.contains(unreadAttentionCueEl)) {
            return unreadAttentionCueEl;
        }

        unreadAttentionCueEl = document.createElement('div');
        unreadAttentionCueEl.className = 'unread-attention-cue';
        unreadAttentionCueEl.hidden = true;
        document.body.appendChild(unreadAttentionCueEl);
        return unreadAttentionCueEl;
    }

    function isAccountMenuOpenForUnread() {
        const accountMenuEl = document.getElementById('accountMenu');
        return !!(
            accountMenuEl
            && (document.body.classList.contains('account-menu-open')
                || window.getComputedStyle(accountMenuEl).display !== 'none')
        );
    }

    function isGifModalOpenForUnread() {
        const modal = document.getElementById('gifModal');
        return !!(modal && modal.classList.contains('open'));
    }

    function isMediaViewerOpenForUnread() {
        const modal = document.getElementById('mediaViewerModal');
        return !!(modal && modal.classList.contains('open'));
    }

    function isCallUiBlockingUnread() {
        const callUiEl = document.getElementById('call-ui');
        return !!(
            callUiEl
            && callUiEl.style.display === 'flex'
            && !callUiEl.classList.contains('is-minimized')
        );
    }

    function shouldDelaySelectedChatRead(chatKey = selectedUser) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey || String(selectedUser || '') !== normalizedChatKey) {
            return false;
        }

        return isAccountMenuOpenForUnread()
            || isGifModalOpenForUnread()
            || isMediaViewerOpenForUnread()
            || isCallUiBlockingUnread();
    }

    function getUnreadEffectiveCount(row) {
        const chatKey = String(row && (row.chat_key || row.sender_id || '') || '');
        if (!chatKey) {
            return 0;
        }

        if (getChatNotificationPref(chatKey) === 'mention') {
            return parseInt(row && row.mention_cnt || 0, 10) || 0;
        }

        return parseInt(row && row.cnt || 0, 10) || 0;
    }

    function buildUnreadAttentionPayload() {
        const rows = Array.isArray(unreadOverlayState.rows) ? unreadOverlayState.rows : [];
        const senders = Array.isArray(unreadOverlayState.senders) ? unreadOverlayState.senders : [];
        const includedChats = new Map();
        let totalUnread = 0;

        rows.forEach(row => {
            const chatKey = String(row && (row.chat_key || row.sender_id || '') || '');
            if (!chatKey) {
                return;
            }
            if (String(selectedUser || '') === chatKey && !shouldDelaySelectedChatRead(chatKey)) {
                return;
            }

            const effectiveCount = getUnreadEffectiveCount(row);
            if (effectiveCount <= 0) {
                return;
            }

            includedChats.set(chatKey, effectiveCount);
            totalUnread += effectiveCount;
        });

        manualUnreadChatIds.forEach(chatKey => {
            const normalizedChatKey = String(chatKey || '').trim();
            if (!normalizedChatKey) {
                return;
            }

            const previousCount = includedChats.get(normalizedChatKey) || 0;
            if (previousCount >= 1) {
                return;
            }

            includedChats.set(normalizedChatKey, 1);
            totalUnread += (1 - previousCount);
        });

        const uniqueSenders = new Map();
        senders.forEach(sender => {
            const chatKey = String(sender && sender.chat_key || '');
            const senderId = String(sender && sender.sender_id || '');
            if (!chatKey || !senderId || !includedChats.has(chatKey)) {
                return;
            }

            const effectiveCount = getChatNotificationPref(chatKey) === 'mention'
                ? (parseInt(sender && sender.mention_cnt || 0, 10) || 0)
                : (parseInt(sender && sender.cnt || 0, 10) || 0);
            if (effectiveCount <= 0) {
                return;
            }

            const existing = uniqueSenders.get(senderId);
            if (existing) {
                existing.contribution += effectiveCount;
                existing.isOnline = existing.isOnline || Number(sender.is_online) === 1;
                return;
            }

            uniqueSenders.set(senderId, {
                id: senderId,
                name: String(sender.display_name || sender.username || `User ${senderId}`),
                profilePic: String(sender.profile_pic || ''),
                isOnline: Number(sender.is_online) === 1,
                contribution: effectiveCount
            });
        });

        const sortedSenders = Array.from(uniqueSenders.values())
            .sort((a, b) => b.contribution - a.contribution)
            .slice(0, 4);

        return {
            totalUnread,
            senders: sortedSenders,
            overflowCount: Math.max(0, uniqueSenders.size - sortedSenders.length)
        };
    }

    function getUnreadAttentionTargetMeta() {
        const mediaViewerClose = document.getElementById('mediaViewerClose');
        if (isMediaViewerOpenForUnread() && mediaViewerClose) {
            return { element: mediaViewerClose, align: 'right' };
        }

        const gifModalClose = document.getElementById('gifModalClose');
        if (isGifModalOpenForUnread() && gifModalClose) {
            return { element: gifModalClose, align: 'right' };
        }

        const callMessageBtnEl = document.getElementById('call-message-btn');
        if (
            isCallUiBlockingUnread()
            && callMessageBtnEl
            && !callMessageBtnEl.hidden
            && !callMessageBtnEl.disabled
        ) {
            return { element: callMessageBtnEl, align: 'left' };
        }

        const settingsCloseBtn = document.querySelector('#accountMenu .close-btn');
        if (isAccountMenuOpenForUnread() && settingsCloseBtn) {
            return { element: settingsCloseBtn, align: 'right' };
        }

        return null;
    }

    function buildUnreadAttentionAvatar(sender) {
        const item = document.createElement('div');
        item.className = 'unread-attention-avatar';
        item.title = sender.name || 'Unread sender';

        const image = document.createElement('img');
        image.src = normalizeProfilePic(sender.profilePic || '', 'direct');
        image.alt = sender.name || 'Unread sender';

        const statusDot = document.createElement('span');
        statusDot.className = 'unread-attention-avatar-status';
        statusDot.classList.toggle('is-online', !!sender.isOnline);

        item.appendChild(image);
        item.appendChild(statusDot);
        return item;
    }

    function renderUnreadAttentionCue() {
        const cue = ensureUnreadAttentionCueElement();
        const targetMeta = getUnreadAttentionTargetMeta();
        const payload = buildUnreadAttentionPayload();

        if (!targetMeta || payload.totalUnread <= 0) {
            cue.hidden = true;
            cue.innerHTML = '';
            cue.style.display = 'none'; // Force hide
            return;
        }

        cue.hidden = false;
        cue.style.display = ''; // Reset display
        cue.className = `unread-attention-cue is-${targetMeta.align}`;
        cue.innerHTML = '';

        const avatarsWrap = document.createElement('div');
        avatarsWrap.className = 'unread-attention-avatars';
        payload.senders.forEach(sender => {
            avatarsWrap.appendChild(buildUnreadAttentionAvatar(sender));
        });
        if (payload.overflowCount > 0) {
            const overflow = document.createElement('div');
            overflow.className = 'unread-attention-overflow';
            overflow.textContent = `+${payload.overflowCount}`;
            avatarsWrap.appendChild(overflow);
        }

        const countBubble = document.createElement('div');
        countBubble.className = 'unread-attention-count';
        countBubble.textContent = payload.totalUnread > 99 ? '99+' : String(payload.totalUnread);

        const arrow = document.createElement('div');
        arrow.className = 'unread-attention-arrow';
        arrow.innerHTML = targetMeta.align === 'left'
            ? '<i class="fa-solid fa-arrow-left-long" aria-hidden="true"></i>'
            : '<i class="fa-solid fa-arrow-right-long" aria-hidden="true"></i>';

        if (targetMeta.align === 'left') {
            cue.appendChild(arrow);
            cue.appendChild(countBubble);
            cue.appendChild(avatarsWrap);
        } else {
            cue.appendChild(avatarsWrap);
            cue.appendChild(countBubble);
            cue.appendChild(arrow);
        }

        cue.style.visibility = 'hidden';
        cue.style.left = '0';
        cue.style.top = '0';

        const targetRect = targetMeta.element.getBoundingClientRect();
        const cueRect = cue.getBoundingClientRect();
        const gap = 12;
        let left = targetMeta.align === 'left'
            ? targetRect.right + gap
            : targetRect.left - cueRect.width - gap;
        let top = targetRect.top + ((targetRect.height - cueRect.height) / 2);

        left = Math.max(12, Math.min(window.innerWidth - cueRect.width - 12, left));
        top = Math.max(12, Math.min(window.innerHeight - cueRect.height - 12, top));

        cue.style.left = `${left}px`;
        cue.style.top = `${top}px`;
        cue.style.visibility = 'visible';
    }

    function updateUnreadAttentionCue() {
        renderUnreadAttentionCue();
    }

    window.addEventListener('resize', updateUnreadAttentionCue);
    document.addEventListener('scroll', updateUnreadAttentionCue, true);

    function incrementMentionBadge(chatKey) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) return;
        mentionUnreadCounts[normalizedChatKey] = (mentionUnreadCounts[normalizedChatKey] || 0) + 1;
        const contact = document.querySelector(`.contact[data-id="${normalizedChatKey}"]`);
        if (!contact) return;
        contact.classList.add('unread');
        let badge = contact.querySelector('.unread-badge');
        if (!badge) {
            badge = document.createElement('div');
            badge.className = 'unread-badge';
            contact.appendChild(badge);
        }
        badge.textContent = String(mentionUnreadCounts[normalizedChatKey]);
        
        // Update page title after incrementing badge
        updatePageTitleFromBadges();
    }

    async function markChatAsRead(chatKey, { captureLastSeen = false } = {}) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            if (captureLastSeen) {
                window.chatLastSeen = 0;
            }
            return { lastSeen: 0 };
        }

        try {
            const response = await fetch(`mark_read.php?token=${token}&with=${encodeURIComponent(normalizedChatKey)}`);
            const payload = await response.json().catch(() => ({}));
            const lastSeen = parseInt(payload.last_seen, 10) || 0;
            if (captureLastSeen) {
                window.chatLastSeen = lastSeen;
            }
            clearUnreadBadgeForChat(normalizedChatKey);
            return { lastSeen };
        } catch (error) {
            console.error('Unable to mark chat as read.', error);
            if (captureLastSeen) {
                window.chatLastSeen = 0;
            }
            return { lastSeen: 0 };
        }
    }

    function scheduleSelectedChatReadSync(chatKey, newestMessageId = 0) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey || String(selectedUser || '') !== normalizedChatKey) {
            return;
        }

        if (newestMessageId > 0) {
            window.chatLastSeen = Math.max(
                parseInt(window.chatLastSeen, 10) || 0,
                parseInt(newestMessageId, 10) || 0
            );
        }

        if (shouldDelaySelectedChatRead(normalizedChatKey)) {
            refreshUnreadBadges();
            return;
        }

        clearUnreadBadgeForChat(normalizedChatKey);

        if (activeChatReadSyncTimer) {
            clearTimeout(activeChatReadSyncTimer);
        }

        activeChatReadSyncTimer = window.setTimeout(() => {
            activeChatReadSyncTimer = null;
            markChatAsRead(normalizedChatKey).catch(() => {});
        }, 120);
    }

    // Function to update online status
    async function updateOnlineStatus(status) {
        console.log(`Updating online status to ${status}`);
        try {
            const res = await fetch('update_status.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: `token=${encodeURIComponent(token)}&online=${status}`
            });
            console.log(`Status update response: ${await res.text()}`);
        } catch (e) {
            console.error('Error updating status:', e);
        }
    }

    function sendOnlineStatusBeacon(status) {
        if (!navigator.sendBeacon || !token) {
            return false;
        }

        try {
            const payload = new URLSearchParams({
                token: String(token),
                online: String(status ? 1 : 0)
            });
            return navigator.sendBeacon('update_status.php', payload);
        } catch (error) {
            console.warn('Online status beacon failed:', error);
            return false;
        }
    }

    const ONLINE_STATUS_HEARTBEAT_MS = 45000;
    let onlineStatusHeartbeatTimer = null;

    function stopOnlineStatusHeartbeat() {
        if (onlineStatusHeartbeatTimer) {
            clearInterval(onlineStatusHeartbeatTimer);
            onlineStatusHeartbeatTimer = null;
        }
    }

    function startOnlineStatusHeartbeat() {
        stopOnlineStatusHeartbeat();
        if (document.visibilityState !== 'visible') {
            return;
        }

        // Send an immediate online status update and schedule recurring heartbeats.
        // Prefer the sendBeacon API when available for reliability during unload.
        try {
            if (sendOnlineStatusBeacon(1) === false) {
                updateOnlineStatus(1).catch(() => {});
            }
        } catch (err) {
            // If anything goes wrong, still attempt a fetch-based update
            try { updateOnlineStatus(1).catch(() => {}); } catch (e) {}
        }

        onlineStatusHeartbeatTimer = window.setInterval(() => {
            if (document.visibilityState === 'visible') {
                try {
                    if (sendOnlineStatusBeacon(1) === false) {
                        updateOnlineStatus(1).catch(() => {});
                    }
                } catch (e) {
                    try { updateOnlineStatus(1).catch(() => {}); } catch (err) {}
                }
            }
        }, ONLINE_STATUS_HEARTBEAT_MS);
    }

    const startCallBtnDesktop = document.getElementById('start-call-btn');
    const startCallBtnMobile = document.getElementById('start-call-btn-mobile');
    const startVideoCallBtnDesktop = document.getElementById('start-video-call-btn');
    const startVideoCallBtnMobile = document.getElementById('start-video-call-btn-mobile');
    const incomingCameraToggleWrap = document.getElementById('incomingCameraToggleWrap');
    const incomingCameraToggle = document.getElementById('incomingCameraToggle');
    const incomingActions = document.getElementById('incoming-actions');
    const acceptCallBtn = document.getElementById('accept-call-btn');
    const endCallBtn = document.getElementById('end-call-btn');
    const callUi = document.getElementById('call-ui');
    const callUsername = document.getElementById('call-username');
    const callStatus = document.getElementById('call-status');
    const leaveMessageBtn = document.getElementById('leave-message-btn');
    const callFollowupModal = document.getElementById('callFollowupModal');
    const callFollowupInput = document.getElementById('callFollowupInput');
    const callFollowupModalClose = document.getElementById('callFollowupModalClose');
    const callFollowupModalCancel = document.getElementById('callFollowupModalCancel');
    const callFollowupModalSend = document.getElementById('callFollowupModalSend');
    
    // New call UI elements
    const callCloseBtn = document.getElementById('call-close-btn');
    const callEndedControls = document.getElementById('call-ended-controls');
    const callAgainBtn = document.getElementById('call-again-btn');
    const callCloseBottomBtn = document.getElementById('call-close-bottom-btn');
    
    let callFollowupMessageId = null; // Store the call message ID to link the follow-up
    const remoteAudio = document.getElementById('remoteAudio');
    const callVideoStage = document.getElementById('callVideoStage');
    const callVideoGrid = document.getElementById('callVideoGrid');
    const callVideoLocalPreview = document.getElementById('callVideoLocalPreview');
    const callLocalPreviewVideo = document.getElementById('callLocalPreviewVideo');
    const callLocalPreviewAvatar = document.getElementById('callLocalPreviewAvatar');
    const callMessageBtn = document.getElementById('call-message-btn');

    if (callUi && callUi.parentElement !== document.body) {
        document.body.appendChild(callUi);
    }

    // --- Call-related variables and Audio elements ---
    const RINGING_DURATION = 30 * 1000; // 30 seconds in milliseconds
    let callTimeoutId = null; // Stores the setTimeout ID for ringing
    let callUiDismissTimeoutId = null;
    let localHangupInitiated = false; // Flag to track if local user initiated hangup
    let callConnectedFlag = false; // Flag to track if the call has actually connected (stream received)
    let pendingVideoCall = false; // Flag: auto-enable camera when call connects (outgoing)
    let pendingIncomingVideoCall = false; // Flag: auto-enable camera when call connects (incoming)
    let directCallUiMode = 'idle'; // idle | outgoing | incoming | connecting | connected | ended
    let suppressDirectCallCloseDuringPromotion = false;
    let suppressDirectCallCloseTimeoutId = null;
    let groupCallTeardownInProgress = false;

    function armDirectCallCloseSuppression(durationMs = 5000) {
        suppressDirectCallCloseDuringPromotion = true;
        if (suppressDirectCallCloseTimeoutId) {
            clearTimeout(suppressDirectCallCloseTimeoutId);
        }
        suppressDirectCallCloseTimeoutId = setTimeout(() => {
            suppressDirectCallCloseTimeoutId = null;
            suppressDirectCallCloseDuringPromotion = false;
        }, durationMs);
    }

    function showPendingDirectCallControls(mode) {
        directCallUiMode = mode;
        if (incomingActions) incomingActions.style.display = 'flex';
        if (acceptCallBtn) {
            acceptCallBtn.style.display = mode === 'incoming' ? 'inline-block' : 'none';
        }
        if (endCallBtn) {
            endCallBtn.style.display = 'inline-block';
            endCallBtn.style.backgroundColor = 'red';
        }
        hideInCallControls();
        updateCallMessageButtonState();
    }

    function showConnectedDirectCallControls() {
        if (groupCallTeardownInProgress) {
            return;
        }
        directCallUiMode = 'connected';
        if (incomingActions) incomingActions.style.display = 'none';
        if (acceptCallBtn) acceptCallBtn.style.display = 'none';
        if (inCallControls) {
            inCallControls.style.display = 'flex';
            inCallControls.dataset.restoreDisplay = 'flex';
        }
        updateCallMessageButtonState();
    }

    function isFollowupCallState(statusText) {
        const normalized = String(statusText || '').trim().toLowerCase();
        return normalized === 'call ended'
            || normalized === "didn't answer."
            || normalized === "didn't answer"
            || normalized === "call declined";
    }

    function bindDefaultEndCallButton() {
        if (!endCallBtn) {
            return;
        }
        endCallBtn.onclick = () => {
            localHangupInitiated = true;
            endPeerCall(true, "local_hangup");
        };
    }

    function canMinimizeCallUi() {
        if (!callUi || callUi.style.display !== 'flex') {
            return false;
        }

        return !!(
            activeGroupCallId
            || directCallUiMode === 'connected'
            || directCallUiMode === 'outgoing'
            || directCallUiMode === 'incoming'
            || directCallUiMode === 'connecting'
        );
    }

    function isCallUiMinimized() {
        return !!(callUi && callUi.classList.contains('is-minimized'));
    }

    function updateCallMessageButtonState() {
        if (!callMessageBtn) {
            return;
        }

        const isFollowupState = directCallUiMode === 'ended'
            || isFollowupCallState(callStatus ? callStatus.innerText : '');
        const showButton = !isFollowupState && canMinimizeCallUi() && !isCallUiMinimized();
        callMessageBtn.hidden = !showButton;
        callMessageBtn.disabled = !showButton;
        callMessageBtn.style.display = showButton ? '' : 'none';
        updateUnreadAttentionCue();
    }

    function clearPendingCallUiDismiss() {
        if (!callUiDismissTimeoutId) {
            return;
        }
        clearTimeout(callUiDismissTimeoutId);
        callUiDismissTimeoutId = null;
    }

    function closeCallUI() {
        clearPendingCallUiDismiss();
        clearPrivateInviteCallTimeout();
        hideInCallControls();
        clearActiveGroupCallState();
        if (callUi) {
            callUi.style.display = 'none';
        }
        directCallUiMode = 'idle';
        if (incomingActions) {
            incomingActions.style.display = 'none';
        }
        if (acceptCallBtn) {
            acceptCallBtn.style.display = 'none';
        }
        if (endCallBtn) {
            endCallBtn.style.display = 'none';
        }
        if (callStatus) {
            callStatus.innerText = '';
        }
        if (callUsername) {
            callUsername.innerText = '';
        }
        if (leaveMessageBtn) {
            leaveMessageBtn.style.display = 'none';
        }
        if (callEndedControls) {
            callEndedControls.style.display = 'none';
        }
        if (callCloseBtn) {
            callCloseBtn.style.display = 'none';
        }
        updateCallMessageButtonState();
    }

    function showTransientDirectCallState(statusText, {
        username = '',
        durationMs = 3000,
        callMessageId = null
    } = {}) {
        if (!callUi) {
            return;
        }

        clearPendingCallUiDismiss();
        hideInCallControls();
        directCallUiMode = 'ended';
        if (incomingActions) incomingActions.style.display = 'none';
        if (acceptCallBtn) acceptCallBtn.style.display = 'none';
        if (endCallBtn) endCallBtn.style.display = 'none';

        callUi.style.display = 'flex';
        if (username) {
            callUsername.innerText = username;
        }
        callStatus.innerText = statusText;
        updateCallMessageButtonState();
        
        const shouldShowFollowupControls = isFollowupCallState(statusText);
        if (shouldShowFollowupControls) {
            freezeStopwatch();
        }

        if (leaveMessageBtn && shouldShowFollowupControls) {
            leaveMessageBtn.style.display = 'flex';
            if (callMessageId) {
                callFollowupMessageId = callMessageId;
            }
        } else if (leaveMessageBtn) {
            leaveMessageBtn.style.display = 'none';
        }

        if (shouldShowFollowupControls) {
            if (callEndedControls) {
                callEndedControls.style.display = 'flex';
            }
            if (callCloseBtn) {
                callCloseBtn.style.display = 'inline-flex';
            }
            // Store the call message ID for the call again button
            if (callMessageId) {
                callFollowupMessageId = callMessageId;
            }
            // Don't auto-close for ended calls - user must manually close
            return;
        }

        // Auto-close for other statuses (like connecting, etc.)
        callUiDismissTimeoutId = setTimeout(() => {
            callUiDismissTimeoutId = null;
            if (callConnectedFlag || activeGroupCallId) {
                return;
            }
            closeCallUI();
        }, durationMs);
    }

    const outgoingVideoCalls = {};
    const remoteVideoFeeds = {};
    const remoteVisualStates = {};
    const speakingParticipantIds = new Set();
    let speakingDetectionRunId = 0;
    let localVideoPreviewDragState = {
        active: false,
        startX: 0,
        startY: 0,
        originLeft: 0,
        originTop: 0
    };
    let minimizedCallUiDragState = {
        active: false,
        pointerId: null,
        startX: 0,
        startY: 0,
        originLeft: 0,
        originTop: 0,
        moved: false
    };

    // Audio elements for call sounds
    const ringbackAudio = new Audio(RINGBACK_AUDIO_SRC);
    ringbackAudio.loop = true; // Ringback sound should loop
    const ringtoneAudio = new Audio(RINGTONE_AUDIO_SRC);
    ringtoneAudio.loop = true; // Ringtone should loop

    // Helper function to stop and reset audio
    function stopAndResetAudio(audioElement) {
        audioElement.pause();
        audioElement.currentTime = 0;
    }

    function startRingbackAudio() {
        if (!getAppSetting('callRingback')) {
            return;
        }

        if (!ringbackAudio.paused) {
            return;
        }

        ringbackAudio.currentTime = 0;
        ringbackAudio.play().catch(e => console.error("Ringback error:", e));
    }
    // --- End Call-related variables and Audio elements ---

    const LEGACY_APP_SETTINGS_KEY = 'quilltalk.appSettings.v1';
    const APP_SETTINGS_KEY = `quilltalk.appSettings.v2.user.${String(currentUserId || currentUsername || 'guest')}`;
    const DEFAULT_ACCENT_COLOR = '#2d58f5';
    const DEFAULT_APP_SETTINGS = Object.freeze({
        typingIndicators: true,
        enterToSend: true,
        enterToSendConfigured: false,
        confirmMediaSends: false,
        confirmVoiceSends: false,
        voicePlaybackSpeed: 1,
        messagePositionMode: 'split',
        messageSplitSelfSide: 'right',
        messageSingleSide: 'left',
        callRingtone: true,
        callRingback: true,
        messageSounds: true,
        friendRequestPopups: true,
        themeMode: 'system',
        accentColor: DEFAULT_ACCENT_COLOR
    });

    function normalizeHexColor(value, fallback = DEFAULT_ACCENT_COLOR) {
        const color = String(value || '').trim();
        return /^#[0-9a-fA-F]{6}$/.test(color) ? color.toLowerCase() : fallback;
    }

    function hexToRgb(hex) {
        const normalized = normalizeHexColor(hex);
        const numeric = parseInt(normalized.slice(1), 16);
        return {
            r: (numeric >> 16) & 255,
            g: (numeric >> 8) & 255,
            b: numeric & 255
        };
    }

    function rgbToHex(r, g, b) {
        const clamp = (value) => Math.max(0, Math.min(255, Math.round(value)));
        return `#${[clamp(r), clamp(g), clamp(b)].map(value => value.toString(16).padStart(2, '0')).join('')}`;
    }

    function invertHexColor(hex) {
        const normalized = hexToRgb(hex);
        return rgbToHex(255 - normalized.r, 255 - normalized.g, 255 - normalized.b);
    }

    function mixHexColors(baseHex, targetHex, amount) {
        const clampedAmount = Math.max(0, Math.min(1, Number(amount) || 0));
        const base = hexToRgb(baseHex);
        const target = hexToRgb(targetHex);
        return rgbToHex(
            base.r + ((target.r - base.r) * clampedAmount),
            base.g + ((target.g - base.g) * clampedAmount),
            base.b + ((target.b - base.b) * clampedAmount)
        );
    }

    function readableTextColor(hex) {
        const { r, g, b } = hexToRgb(hex);
        const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
        return luminance > 0.62 ? '#111827' : '#ffffff';
    }

    function buildAccentPalette(accentColor, themeMode = 'light') {
        const normalizedAccent = normalizeHexColor(accentColor);
        const rgb = hexToRgb(normalizedAccent);
        const isDarkTheme = String(themeMode || '').toLowerCase() === 'dark';

        return {
            accent: normalizedAccent,
            hover: mixHexColors(normalizedAccent, '#000000', 0.18),
            soft: isDarkTheme
                ? `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.18)`
                : mixHexColors(normalizedAccent, '#ffffff', 0.88),
            softStrong: isDarkTheme
                ? `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.28)`
                : mixHexColors(normalizedAccent, '#ffffff', 0.8),
            tokenHighlight: invertHexColor(normalizedAccent),
            mentionRowHighlight: mixHexColors(invertHexColor(normalizedAccent), '#ffffff', 0.62),
            shadow: `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.22)`,
            shadowStrong: `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.3)`,
            bubble: mixHexColors(normalizedAccent, '#ffffff', 0.84),
            messageSelectSelf: mixHexColors(invertHexColor(normalizedAccent), '#000000', 0.14),
            messageSelectOther: mixHexColors(invertHexColor(normalizedAccent), '#ffffff', 0.12),
            messageSelectText: readableTextColor(invertHexColor(normalizedAccent)),
            contrast: ((rgb.r * 299 + rgb.g * 587 + rgb.b * 114) / 1000 > 160) ? '#111827' : '#ffffff'
        };
    }

    const systemThemeMediaQuery = typeof window.matchMedia === 'function'
        ? window.matchMedia('(prefers-color-scheme: dark)')
        : null;

    function normalizeThemeModePreference(value, fallback = DEFAULT_APP_SETTINGS.themeMode) {
        const normalized = String(value || '').trim().toLowerCase();
        if (normalized === 'dark' || normalized === 'light' || normalized === 'system') {
            return normalized;
        }
        return fallback;
    }

    function normalizeMessagePositionMode(value, fallback = DEFAULT_APP_SETTINGS.messagePositionMode) {
        const normalized = String(value || '').trim().toLowerCase();
        if (normalized === 'split' || normalized === 'single') {
            return normalized;
        }
        return fallback;
    }

    function normalizeMessagePositionSide(value, fallback = DEFAULT_APP_SETTINGS.messageSplitSelfSide) {
        const normalized = String(value || '').trim().toLowerCase();
        if (normalized === 'left' || normalized === 'right') {
            return normalized;
        }
        return fallback;
    }

    function getMessagePositionSettingsSnapshot() {
        const mode = normalizeMessagePositionMode(getAppSetting('messagePositionMode'));
        const splitSelfSide = normalizeMessagePositionSide(
            getAppSetting('messageSplitSelfSide'),
            DEFAULT_APP_SETTINGS.messageSplitSelfSide
        );
        const singleSide = normalizeMessagePositionSide(
            getAppSetting('messageSingleSide'),
            DEFAULT_APP_SETTINGS.messageSingleSide
        );

        return {
            mode,
            splitSelfSide,
            singleSide
        };
    }

    function getMessageLayoutSide(isSelfMessage, settings = getMessagePositionSettingsSnapshot()) {
        if (settings.mode === 'single') {
            return settings.singleSide;
        }

        if (isSelfMessage) {
            return settings.splitSelfSide;
        }

        return settings.splitSelfSide === 'left' ? 'right' : 'left';
    }

    function applyMessageLayoutClasses(messageEl, isSelfMessage = null) {
        if (!messageEl || !messageEl.classList || messageEl.classList.contains('group-news-message')) {
            return;
        }

        const resolvedIsSelfMessage = typeof isSelfMessage === 'boolean'
            ? isSelfMessage
            : messageEl.classList.contains('self');
        const settings = getMessagePositionSettingsSnapshot();
        const side = getMessageLayoutSide(resolvedIsSelfMessage, settings);

        messageEl.classList.toggle('message-layout-single', settings.mode === 'single');
        messageEl.classList.toggle('message-layout-split', settings.mode !== 'single');
        messageEl.classList.toggle('message-side-left', side === 'left');
        messageEl.classList.toggle('message-side-right', side === 'right');
        messageEl.dataset.messageLayoutMode = settings.mode;
        messageEl.dataset.messageLayoutSide = side;
    }

    function applyMessageLayoutPreferences() {
        const settings = getMessagePositionSettingsSnapshot();
        const rootEl = document.documentElement;

        rootEl.dataset.messagePositionMode = settings.mode;
        rootEl.dataset.messagePositionSide = settings.mode === 'single'
            ? settings.singleSide
            : settings.splitSelfSide;

        if (!chatBox) {
            return;
        }

        chatBox.querySelectorAll('.message').forEach(messageEl => {
            applyMessageLayoutClasses(messageEl);
        });
    }

    function resolveThemeModePreference(value) {
        const normalized = normalizeThemeModePreference(value);
        if (normalized === 'system') {
            return systemThemeMediaQuery && systemThemeMediaQuery.matches ? 'dark' : 'light';
        }
        return normalized;
    }

    function applyThemeAppearance() {
        const themeMode = resolveThemeModePreference(getAppSetting('themeMode'));
        const accentPalette = buildAccentPalette(getAppSetting('accentColor'), themeMode);
        const rootEl = document.documentElement;

        rootEl.setAttribute('data-theme', themeMode);
        rootEl.dataset.themePreference = normalizeThemeModePreference(getAppSetting('themeMode'));
        rootEl.style.colorScheme = themeMode;
        rootEl.style.setProperty('--accent-color', accentPalette.accent);
        rootEl.style.setProperty('--accent-hover', accentPalette.hover);
        rootEl.style.setProperty('--accent-soft', accentPalette.soft);
        rootEl.style.setProperty('--accent-soft-strong', accentPalette.softStrong);
        rootEl.style.setProperty('--token-highlight-bg', accentPalette.tokenHighlight);
        rootEl.style.setProperty('--mention-row-highlight', accentPalette.mentionRowHighlight);
        rootEl.style.setProperty('--accent-contrast', accentPalette.contrast);
        rootEl.style.setProperty('--accent-shadow', accentPalette.shadow);
        rootEl.style.setProperty('--accent-shadow-strong', accentPalette.shadowStrong);
        rootEl.style.setProperty('--message-bubble-bg', themeMode === 'dark' ? 'rgba(255, 255, 255, 0.08)' : accentPalette.bubble);
        rootEl.style.setProperty('--message-bubble-text', themeMode === 'dark' ? '#e5eefc' : '#111827');
        rootEl.style.setProperty('--message-select-bg-self', accentPalette.messageSelectSelf);
        rootEl.style.setProperty('--message-select-bg-other', accentPalette.messageSelectOther);
        rootEl.style.setProperty('--message-select-text', accentPalette.messageSelectText);
        rootEl.style.setProperty('--voice-bar-bg', `rgba(${hexToRgb(accentPalette.accent).r}, ${hexToRgb(accentPalette.accent).g}, ${hexToRgb(accentPalette.accent).b}, 0.24)`);
        rootEl.style.setProperty('--voice-bar-bg-self', 'rgba(255, 255, 255, 0.32)');
    }

    function loadStoredAppSettings() {
        try {
            const raw = localStorage.getItem(APP_SETTINGS_KEY);
            if (raw) {
                return JSON.parse(raw);
            }

            const legacyRaw = localStorage.getItem(LEGACY_APP_SETTINGS_KEY);
            if (!legacyRaw) {
                return {};
            }

            const migratedSettings = JSON.parse(legacyRaw);
            localStorage.setItem(APP_SETTINGS_KEY, JSON.stringify(migratedSettings));
            localStorage.removeItem(LEGACY_APP_SETTINGS_KEY);
            return migratedSettings;
        } catch (e) {
            console.warn('Unable to read stored app settings.', e);
            return {};
        }
    }

    function normalizeAppSettings(rawSettings) {
        const next = { ...DEFAULT_APP_SETTINGS };
        const source = rawSettings && typeof rawSettings === 'object' ? rawSettings : {};
        const allowedVoiceSpeeds = [1, 1.25, 1.5, 1.75, 2];
        const voicePlaybackSpeed = Number(source.voicePlaybackSpeed);

        next.typingIndicators = source.typingIndicators !== false;
        next.enterToSendConfigured = source.enterToSendConfigured === true;
        next.enterToSend = next.enterToSendConfigured
            ? !!source.enterToSend
            : DEFAULT_APP_SETTINGS.enterToSend;
        next.confirmMediaSends = !!source.confirmMediaSends;
        next.confirmVoiceSends = !!source.confirmVoiceSends;
        next.voicePlaybackSpeed = allowedVoiceSpeeds.includes(voicePlaybackSpeed)
            ? voicePlaybackSpeed
            : DEFAULT_APP_SETTINGS.voicePlaybackSpeed;
        next.messagePositionMode = normalizeMessagePositionMode(
            source.messagePositionMode,
            DEFAULT_APP_SETTINGS.messagePositionMode
        );
        next.messageSplitSelfSide = normalizeMessagePositionSide(
            source.messageSplitSelfSide,
            DEFAULT_APP_SETTINGS.messageSplitSelfSide
        );
        next.messageSingleSide = normalizeMessagePositionSide(
            source.messageSingleSide,
            DEFAULT_APP_SETTINGS.messageSingleSide
        );
        next.callRingtone = source.callRingtone !== false;
        next.callRingback = source.callRingback !== false;
        next.messageSounds = source.messageSounds !== false;
        next.friendRequestPopups = source.friendRequestPopups !== false;
        next.themeMode = normalizeThemeModePreference(source.themeMode, DEFAULT_APP_SETTINGS.themeMode);
        next.accentColor = normalizeHexColor(source.accentColor, DEFAULT_ACCENT_COLOR);

        return next;
    }

    let appSettings = normalizeAppSettings(loadStoredAppSettings());
    let pendingChatActionConfirm = null;
    let blockedUsers = new Set();
    let blockedByUsers = new Set();

    function persistAppSettings() {
        try {
            localStorage.setItem(APP_SETTINGS_KEY, JSON.stringify(appSettings));
        } catch (e) {
            console.warn('Unable to store app settings.', e);
        }
    }

    function getAppSetting(key) {
        return Object.prototype.hasOwnProperty.call(appSettings, key)
            ? appSettings[key]
            : DEFAULT_APP_SETTINGS[key];
    }

    function applyAppSettings() {
        applyThemeAppearance();
        applyMessageLayoutPreferences();

        if (messageInput) {
            messageInput.dataset.enterToSend = getAppSetting('enterToSend') ? '1' : '0';
        }

        if (!getAppSetting('typingIndicators')) {
            clearLocalTyping(true);
            hideTypingIndicator();
        }

        if (!getAppSetting('messageSounds') && ding) {
            ding.pause();
            ding.currentTime = 0;
        }

        if (!getAppSetting('friendRequestPopups') && friendRequestPopups) {
            friendRequestPopups.innerHTML = '';
        }

        if (!getAppSetting('callRingtone')) {
            stopAndResetAudio(ringtoneAudio);
        }

        if (!getAppSetting('callRingback')) {
            stopAndResetAudio(ringbackAudio);
        }

        document.querySelectorAll('.voice-message-audio').forEach(audioEl => {
            audioEl.playbackRate = Number(getAppSetting('voicePlaybackSpeed')) || 1;
        });
    }

    function forceThemeModePreference(value, { persist = true, syncInput = false } = {}) {
        const normalizedThemeMode = normalizeThemeModePreference(value, DEFAULT_APP_SETTINGS.themeMode);

        appSettings = normalizeAppSettings({
            ...appSettings,
            themeMode: normalizedThemeMode
        });

        if (persist) {
            persistAppSettings();
        }

        applyAppSettings();

        if (syncInput) {
            const themeModeInput = document.getElementById('settingThemeMode');
            if (themeModeInput && themeModeInput.value !== normalizedThemeMode) {
                themeModeInput.value = normalizedThemeMode;
            }
        }

        return appSettings.themeMode;
    }

    function setAppSetting(key, value) {
        if (key === 'themeMode') {
            return forceThemeModePreference(value, { persist: true, syncInput: false });
        }

        const nextSettings = {
            ...appSettings,
            [key]: value
        };

        if (key === 'enterToSend') {
            nextSettings.enterToSendConfigured = true;
        }

        appSettings = normalizeAppSettings(nextSettings);
        persistAppSettings();
        applyAppSettings();
        return appSettings[key];
    }

    window.setQuillTalkThemeMode = (value) => forceThemeModePreference(value, { persist: true, syncInput: true });

    if (systemThemeMediaQuery) {
        const handleSystemThemeChange = () => {
            if (normalizeThemeModePreference(getAppSetting('themeMode')) === 'system') {
                applyThemeAppearance();
            }
        };

        if (typeof systemThemeMediaQuery.addEventListener === 'function') {
            systemThemeMediaQuery.addEventListener('change', handleSystemThemeChange);
        } else if (typeof systemThemeMediaQuery.addListener === 'function') {
            systemThemeMediaQuery.addListener(handleSystemThemeChange);
        }
    }

    window.QuillTalkSettings = {
        get: getAppSetting,
        set: setAppSetting,
        all: () => ({ ...appSettings }),
        defaults: () => ({ ...DEFAULT_APP_SETTINGS }),
        apply: applyAppSettings,
        reset: () => {
            appSettings = normalizeAppSettings(DEFAULT_APP_SETTINGS);
            persistAppSettings();
            applyAppSettings();
            return { ...appSettings };
        }
    };
    window.__qtGetDefaultAppSettings = () => ({ ...DEFAULT_APP_SETTINGS });
    window.__qtNormalizeThemeModePreference = normalizeThemeModePreference;
    window.__qtNormalizeMessagePositionMode = normalizeMessagePositionMode;
    window.__qtNormalizeMessagePositionSide = normalizeMessagePositionSide;

    function setMessagePositionControlRowVisibility(rowEl, shouldShow) {
        if (!rowEl) {
            return;
        }

        rowEl.hidden = !shouldShow;
        rowEl.style.display = shouldShow ? '' : 'none';
        rowEl.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');

        const selectEl = rowEl.querySelector('select');
        if (selectEl) {
            selectEl.disabled = !shouldShow;
        }
    }

    function previewMessageLayoutState(settings) {
        const nextSettings = settings || getMessagePositionSettingsSnapshot();
        const rootEl = document.documentElement;

        rootEl.dataset.messagePositionMode = nextSettings.mode;
        rootEl.dataset.messagePositionSide = nextSettings.mode === 'single'
            ? nextSettings.singleSide
            : nextSettings.splitSelfSide;

        if (!chatBox) {
            return;
        }

        chatBox.querySelectorAll('.message').forEach(messageEl => {
            if (!messageEl || !messageEl.classList || messageEl.classList.contains('group-news-message')) {
                return;
            }

            const isSelfMessage = messageEl.classList.contains('self');
            const side = getMessageLayoutSide(isSelfMessage, nextSettings);

            messageEl.classList.toggle('message-layout-single', nextSettings.mode === 'single');
            messageEl.classList.toggle('message-layout-split', nextSettings.mode !== 'single');
            messageEl.classList.toggle('message-side-left', side === 'left');
            messageEl.classList.toggle('message-side-right', side === 'right');
            messageEl.dataset.messageLayoutMode = nextSettings.mode;
            messageEl.dataset.messageLayoutSide = side;
        });
    }

    function syncMessagePositionControlsFromSettings(settings = getMessagePositionSettingsSnapshot()) {
        const modeSelect = document.getElementById('settingMessagePositionMode');
        const splitSideSelect = document.getElementById('settingMessageSplitSelfSide');
        const singleSideSelect = document.getElementById('settingMessageSingleSide');
        const splitRow = document.getElementById('settingMessageSplitSelfSideRow');
        const singleRow = document.getElementById('settingMessageSingleSideRow');

        if (modeSelect && modeSelect.value !== settings.mode) {
            modeSelect.value = settings.mode;
        }
        if (splitSideSelect && splitSideSelect.value !== settings.splitSelfSide) {
            splitSideSelect.value = settings.splitSelfSide;
        }
        if (singleSideSelect && singleSideSelect.value !== settings.singleSide) {
            singleSideSelect.value = settings.singleSide;
        }

        setMessagePositionControlRowVisibility(splitRow, settings.mode === 'split');
        setMessagePositionControlRowVisibility(singleRow, settings.mode === 'single');
        previewMessageLayoutState(settings);
    }

    function initializeMessagePositionControls() {
        if (document.documentElement.dataset.qtMessagePositionControlsBound === '1') {
            syncMessagePositionControlsFromSettings();
            return;
        }

        const modeSelect = document.getElementById('settingMessagePositionMode');
        const splitSideSelect = document.getElementById('settingMessageSplitSelfSide');
        const singleSideSelect = document.getElementById('settingMessageSingleSide');

        if (!modeSelect || !splitSideSelect || !singleSideSelect) {
            return;
        }

        document.documentElement.dataset.qtMessagePositionControlsBound = '1';
        [modeSelect, splitSideSelect, singleSideSelect].forEach(selectEl => {
            selectEl.dataset.qtMessagePositionBound = '1';
        });

        const applyFromControls = (changedKey = null) => {
            const nextSettings = {
                mode: normalizeMessagePositionMode(modeSelect.value, DEFAULT_APP_SETTINGS.messagePositionMode),
                splitSelfSide: normalizeMessagePositionSide(splitSideSelect.value, DEFAULT_APP_SETTINGS.messageSplitSelfSide),
                singleSide: normalizeMessagePositionSide(singleSideSelect.value, DEFAULT_APP_SETTINGS.messageSingleSide)
            };

            syncMessagePositionControlsFromSettings(nextSettings);

            if (!changedKey || !window.QuillTalkSettings || typeof window.QuillTalkSettings.set !== 'function') {
                return;
            }

            if (changedKey === 'messagePositionMode') {
                window.QuillTalkSettings.set('messagePositionMode', nextSettings.mode);
            } else if (changedKey === 'messageSplitSelfSide') {
                window.QuillTalkSettings.set('messageSplitSelfSide', nextSettings.splitSelfSide);
            } else if (changedKey === 'messageSingleSide') {
                window.QuillTalkSettings.set('messageSingleSide', nextSettings.singleSide);
            }

            syncMessagePositionControlsFromSettings(getMessagePositionSettingsSnapshot());
        };

        modeSelect.addEventListener('change', () => applyFromControls('messagePositionMode'));
        modeSelect.addEventListener('input', () => applyFromControls('messagePositionMode'));
        splitSideSelect.addEventListener('change', () => applyFromControls('messageSplitSelfSide'));
        splitSideSelect.addEventListener('input', () => applyFromControls('messageSplitSelfSide'));
        singleSideSelect.addEventListener('change', () => applyFromControls('messageSingleSide'));
        singleSideSelect.addEventListener('input', () => applyFromControls('messageSingleSide'));

        syncMessagePositionControlsFromSettings();
    }

    initializeMessagePositionControls();

    function normalizeBlockFlag(value) {
        return value === true || value === 1 || value === '1' || value === 'true';
    }

    function setContactBlockState(userId, { viewerHasBlocked = false, blockedViewer = false } = {}) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId) {
            return;
        }

        const nextViewerHasBlocked = normalizeBlockFlag(viewerHasBlocked);
        const nextBlockedViewer = normalizeBlockFlag(blockedViewer);

        if (nextViewerHasBlocked) {
            blockedUsers.add(normalizedUserId);
        } else {
            blockedUsers.delete(normalizedUserId);
        }

        if (nextBlockedViewer) {
            blockedByUsers.add(normalizedUserId);
        } else {
            blockedByUsers.delete(normalizedUserId);
        }

        const contactEl = getContactElement(normalizedUserId);
        if (contactEl) {
            contactEl.dataset.viewerBlocked = nextViewerHasBlocked ? '1' : '0';
            contactEl.dataset.blockedViewer = nextBlockedViewer ? '1' : '0';
        }
    }

    function syncInitialBlockedUsersFromDom() {
        blockedUsers.clear();
        blockedByUsers.clear();

        contactsList.querySelectorAll('.contact').forEach(contactEl => {
            setContactBlockState(contactEl.dataset.id, {
                viewerHasBlocked: contactEl.dataset.viewerBlocked,
                blockedViewer: contactEl.dataset.blockedViewer,
            });
        });
    }

    function isBlockedUser(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        try {
            return !!normalizedUserId && blockedUsers && typeof blockedUsers.has === 'function' && blockedUsers.has(normalizedUserId);
        } catch (err) {
            // If blockedUsers is in a temporal-dead-zone or not yet initialized,
            // don't let the app crash — assume not blocked and continue.
            if (err && err instanceof ReferenceError) return false;
            console.error('isBlockedUser error', err);
            return false;
        }
    }

    function hasBlockedCurrentUser(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        try {
            return !!normalizedUserId && blockedByUsers && typeof blockedByUsers.has === 'function' && blockedByUsers.has(normalizedUserId);
        } catch (err) {
            if (err && err instanceof ReferenceError) return false;
            console.error('hasBlockedCurrentUser error', err);
            return false;
        }
    }

    function isConversationBlocked(userId) {
        return isBlockedUser(userId) || hasBlockedCurrentUser(userId);
    }

    const TYPING_IDLE_MS = 3500;
    const TYPING_PING_MS = 2000;
    const TYPING_POLL_MS = 1500;
    let typingStopTimeout = null;
    let localTypingUser = null;
    
    // Group typing tracker: { groupKey: { userId: { displayName, timestamp } } }
    let groupTypingUsers = {};
    let lastTypingPingAt = 0;
    let typingIndicatorUser = null;

    applyAppSettings();

    function applyProfileImageFallback(imgEl, chatType = 'direct', onFallback = null) {
        if (!imgEl) {
            return;
        }

        const fallbackPic = getContactFallbackPic(chatType);
        imgEl.onerror = () => {
            imgEl.onerror = null;
            imgEl.src = fallbackPic;
            if (typeof onFallback === 'function') {
                try {
                    onFallback(fallbackPic);
                } catch (error) {}
            }
        };
    }

    function setProfileImage(imgEl, value, chatType = 'direct', onFallback = null) {
        if (!imgEl) {
            return;
        }

        applyProfileImageFallback(imgEl, chatType, onFallback);
        imgEl.src = normalizeProfilePic(value, chatType);
    }

    document.addEventListener('error', (event) => {
        const imgEl = event.target;
        if (!(imgEl instanceof HTMLImageElement)) {
            return;
        }

        const attemptedSrc = String(imgEl.getAttribute('src') || imgEl.currentSrc || '').trim();
        if (!/uploads\/profiles\//i.test(attemptedSrc)) {
            return;
        }

        const contactEl = imgEl.closest('.contact');
        const chatType = contactEl ? getContactChatType(contactEl) : 'direct';
        const fallbackPic = getContactFallbackPic(chatType);
        imgEl.onerror = null;
        imgEl.src = fallbackPic;

        if (contactEl) {
            const contactKey = String(contactEl.dataset.id || '').trim();
            if (contactKey) {
                if (chatType === 'group') {
                    groupIconsMap[contactKey] = fallbackPic;
                } else {
                    userProfilePics[contactKey] = fallbackPic;
                }
            }
        }

        if (imgEl.id === 'accountMenuProfileImg' || imgEl.classList.contains('profile-btn')) {
            currentUserProfilePic = fallbackPic;
        }
    }, true);

    function formatGroupRoleLabel(value) {
        const role = normalizeGroupRole(value);
        if (role === GROUP_ROLE_OWNER) {
            return 'Owner';
        }
        if (role === GROUP_ROLE_ADMIN) {
            return 'Admin';
        }
        return 'Member';
    }

    function isGroupOwnerMeta(meta) {
        return !!(meta && meta.isGroup && normalizeGroupRole(meta.viewerRole || '') === GROUP_ROLE_OWNER);
    }

    function syncContactMapsFromElement(contactEl) {
        if (!contactEl) {
            return;
        }

        const id = String(contactEl.dataset.id || '').trim();
        if (!id) {
            return;
        }

        const chatType = getContactChatType(contactEl);
        const nameEl = contactEl.querySelector('.contact-name');
        const imgEl = contactEl.querySelector('.contact-img');
        const indicatorEl = contactEl.querySelector('.online-indicator');
        const displayName = (contactEl.dataset.displayName || (nameEl ? nameEl.textContent.trim() : '')).trim();
        const username = (contactEl.dataset.username || '').trim();
        const bio = contactEl.dataset.bio || '';
        const createdAt = contactEl.dataset.createdAt || '';
        const isOnline = contactEl.dataset.online === '1';
        const profilePic = imgEl ? normalizeProfilePic(imgEl.currentSrc || imgEl.src, chatType) : getContactFallbackPic(chatType);
        const entityId = String(contactEl.dataset.entityId || '').trim();
        const memberCount = parseInt(contactEl.dataset.memberCount || '0', 10) || 0;
        const chatNickname = normalizeChatScopedNicknameValue(contactEl.dataset.chatNickname || '');
        const viewerChatNickname = normalizeChatScopedNicknameValue(contactEl.dataset.viewerChatNickname || '');

        contactEl.dataset.chatType = chatType;
        contactEl.dataset.chatNickname = chatNickname;
        contactEl.dataset.viewerChatNickname = viewerChatNickname;
        if (!contactEl.dataset.entityId) {
            contactEl.dataset.entityId = chatType === 'group'
                ? String(getGroupIdFromChatKey(id) || '')
                : id;
        }
        if (chatType === 'group' && !contactEl.dataset.memberCount) {
            contactEl.dataset.memberCount = String(memberCount);
        }
        contactEl.dataset.notificationMode = normalizeChatNotificationMode(contactEl.dataset.notificationMode || 'all');

        if (chatType === 'group') {
            contactEl.dataset.viewerRole = String(contactEl.dataset.viewerRole || '');
            contactEl.dataset.viewerMutedUntil = String(contactEl.dataset.viewerMutedUntil || '');
            contactEl.dataset.sendPermission = String(contactEl.dataset.sendPermission || GROUP_SEND_PERMISSION_ALL);
            contactEl.dataset.addMembersPermission = String(contactEl.dataset.addMembersPermission || GROUP_ADD_PERMISSION_ADMINS);
            contactEl.dataset.canManageGroup = contactEl.dataset.canManageGroup === '1' ? '1' : '0';
            contactEl.dataset.canChangeRoles = contactEl.dataset.canChangeRoles === '1' ? '1' : '0';
            contactEl.dataset.canDeleteGroup = contactEl.dataset.canDeleteGroup === '1' ? '1' : '0';
            contactEl.dataset.canSendGroup = contactEl.dataset.canSendGroup === '0' ? '0' : '1';
            groupNamesMap[id] = displayName || `Group ${entityId || getGroupIdFromChatKey(id) || ''}`.trim();
            groupDescriptionsMap[id] = bio;
            groupIconsMap[id] = profilePic || DEFAULT_GROUP_CHAT_ICON;
            groupCreatedAtMap[id] = createdAt;
            groupMemberCountMap[id] = memberCount;
            groupOnlineMap[id] = isOnline;
            rememberViewerChatNickname(id, viewerChatNickname);
        } else {
            userNamesMap[id] = displayName || username || `User ${id}`;
            userUsernamesMap[id] = username;
            userProfilePics[id] = normalizeProfilePic(profilePic, 'direct');
            userBiosMap[id] = bio;
            userCreatedAtMap[id] = createdAt;
            userOnlineMap[id] = isOnline;
            directContactOnlineMap[id] = isOnline;
            rememberChatNickname(id, id, chatNickname);
            rememberViewerChatNickname(id, viewerChatNickname);
        }

        ensurePresenceIndicatorChildren(indicatorEl);
    }

    // Cache right-sidebar elements before any bootstrap code can refresh sidebar state.
    const rightSidebar = document.getElementById('rightSidebar');
    const rightSidebarContent = document.getElementById('rightSidebarContent');
    const rightSidebarSearch = document.getElementById('rightSidebarSearch');
    const rightSidebarMobileClose = document.getElementById('rightSidebarMobileClose');
    const rightSidebarMobileTitle = document.getElementById('rightSidebarMobileTitle');

    async function maybeOpenTopDesktopContact() {
        if (isMobileViewport() || selectedUser || _autoOpenedFirstContact || !contactsList || getActiveContactView() !== 'contacts') {
            return;
        }

        const firstVisibleContact = Array.from(contactsList.querySelectorAll('.contact[data-id]')).find(contactEl => {
            return !contactEl.hidden && contactEl.style.display !== 'none';
        });

        if (!firstVisibleContact || !firstVisibleContact.dataset.id) {
            return;
        }

        await openConversation(firstVisibleContact.dataset.id);
        if (selectedUser && String(selectedUser) === String(firstVisibleContact.dataset.id)) {
            _autoOpenedFirstContact = true;
            // Explicitly open right sidebar after first contact opens
            if (rightSidebar && !isMobileViewport()) {
                openRightSidebar(selectedUser);
            }
        }
    }

    console.log('DEBUG: Initial userNamesMap after DOM scan:', userNamesMap);
    console.log('DEBUG: Initial userProfilePics after DOM scan:', userProfilePics);
    updateHeaderContact(null);
    // Note: maybeOpenTopDesktopContact is called in pollContacts after all elements are initialized

    function getUsernameById(userId) {
        if (!userId) {
            console.warn('Attempted to get username for null/undefined ID.');
            return 'Unknown';
        }
        const normalizedUserId = String(userId);
        if (isGroupChatKey(normalizedUserId)) {
            return groupNamesMap[normalizedUserId] || `Group ${getGroupIdFromChatKey(normalizedUserId) || ''}`.trim();
        }
        return userNamesMap[normalizedUserId] || `User ${normalizedUserId}`;
    }

    function getAccountUsernameById(userId) {
        if (!userId) {
            return '';
        }
        return userUsernamesMap[userId] || '';
    }

    function resolveGroupOnlineStateFromMembers(members, fallbackOnline = false) {
        if (!Array.isArray(members) || members.length === 0) {
            return !!fallbackOnline;
        }

        let hasViewer = false;
        let viewerOnline = false;
        let otherOnline = false;

        members.forEach(member => {
            const memberId = String(member.user_id || member.id || '').trim();
            if (!memberId) {
                return;
            }

            const isOnline = Number(member.online) === 1;
            if (memberId === String(currentUserId)) {
                hasViewer = true;
                viewerOnline = isOnline;
                return;
            }

            if (isOnline) {
                otherOnline = true;
            }
        });

        if (!hasViewer) {
            return !!fallbackOnline;
        }

        return viewerOnline && otherOnline;
    }

    function renderMobileContactsStrip() {
        console.log('[MOBILE_CONTACTS] renderMobileContactsStrip called');
        if (!mobileContactsStrip) {
            console.log('[MOBILE_CONTACTS] mobileContactsStrip element not found');
            return;
        }

        if (getActiveContactView() !== 'contacts') {
            if (mobileContactsStripWrap) {
                mobileContactsStripWrap.hidden = true;
            }
            mobileContactsStrip.innerHTML = '';
            updateMobileContactsStripScrollbar();
            return;
        }

        if (!contactsList) {
            console.log('[MOBILE_CONTACTS] contactsList not found');
            if (mobileContactsStripWrap) {
                mobileContactsStripWrap.hidden = true;
            }
            mobileContactsStrip.innerHTML = '';
            updateMobileContactsStripScrollbar();
            return;
        }

        const visibleContacts = Array.from(contactsList.querySelectorAll('.contact')).filter(contactEl => {
            return !contactEl.hidden && contactEl.style.display !== 'none';
        }).map(contactEl => {
            const id = String(contactEl.dataset.id || '').trim();
            if (!id) {
                return null;
            }

            // Get display name with nickname support
            const displayName = contactEl.dataset.displayName || contactEl.dataset.username || `User ${id}`;
            const finalName = getDisplayNameForUser(id, { 
                displayName: displayName, 
                username: contactEl.dataset.username,
                isGroup: id.startsWith('group:')
            });

            const imageEl = contactEl.querySelector('.contact-img');
            return {
                id,
                name: finalName,
                profilePic: (imageEl ? imageEl.src : defaultProfilePic) || defaultProfilePic,
                isOnline: getResolvedContactOnlineState(id, contactEl),
                isPinned: isPinnedChatId(id)
            };
        }).filter(Boolean);

        if (!visibleContacts.length) {
            if (mobileContactsStripWrap) {
                mobileContactsStripWrap.hidden = true;
            }
            mobileContactsStrip.innerHTML = '';
            updateMobileContactsStripScrollbar();
            return;
        }

        if (mobileContactsStripWrap) {
            mobileContactsStripWrap.hidden = false;
        }
        mobileContactsStrip.innerHTML = '';

        const orderedVisibleContacts = visibleContacts.slice().sort((left, right) => {
            if (!!left.isPinned !== !!right.isPinned) {
                return left.isPinned ? -1 : 1;
            }

            if (!!left.isOnline !== !!right.isOnline) {
                return left.isOnline ? -1 : 1;
            }

            return String(left.name || '').localeCompare(String(right.name || ''));
        });

        orderedVisibleContacts.forEach(contact => {
            const card = document.createElement('button');
            card.type = 'button';
            card.className = 'mobile-contact-status-card';
            card.dataset.contactId = contact.id;
            if (selectedUser && String(selectedUser) === contact.id) {
                card.classList.add('is-selected');
            }
            card.setAttribute('aria-label', contact.name);
            card.title = contact.name;

            const avatarWrap = document.createElement('div');
            avatarWrap.className = 'mobile-contact-status-avatar-wrap';

            const avatar = document.createElement('img');
            avatar.className = 'mobile-contact-status-avatar';
            avatar.src = contact.profilePic;
            avatar.alt = contact.name;

            const indicator = document.createElement('span');
            indicator.className = 'online-indicator';
            ensurePresenceIndicatorChildren(indicator);
            applyPresenceIndicatorState(indicator, contact.isOnline, false);

            avatarWrap.appendChild(avatar);
            avatarWrap.appendChild(indicator);

            const name = document.createElement('div');
            name.className = 'mobile-contact-status-name';
            name.textContent = contact.name;

            card.appendChild(avatarWrap);
            card.appendChild(name);
            console.log('[MOBILE_CONTACTS] Binding activation for contact:', contact.id);
            bindConversationActivation(card, () => contact.id);

            mobileContactsStrip.appendChild(card);
        });

        console.log('[MOBILE_CONTACTS] Rendered', orderedVisibleContacts.length, 'contacts');
        requestAnimationFrame(updateMobileContactsStripScrollbar);
        window.setTimeout(updateMobileContactsStripScrollbar, 60);
    }

    function formatMemberSinceDate(dateValue) {
        if (!dateValue) {
            return 'Unknown';
        }

        const date = new Date(dateValue);
        if (Number.isNaN(date.getTime())) {
            return 'Unknown';
        }

        return date.toLocaleDateString(undefined, {
            month: 'long',
            day: 'numeric',
            year: 'numeric'
        });
    }

    function getMessagePresenceData(userId, isSelf = false) {
        const normalizedUserId = userId ? String(userId) : '';

        if (isSelf || normalizedUserId === String(currentUserId)) {
            return {
                profilePic: normalizeProfilePic(currentUserProfilePic, 'direct'),
                isOnline: true
            };
        }

        const contactEl = getContactElement(normalizedUserId);
        const contactImgEl = contactEl ? contactEl.querySelector('.contact-img') : null;

        return {
            profilePic: normalizeProfilePic(userProfilePics[normalizedUserId] || (contactImgEl ? (contactImgEl.currentSrc || contactImgEl.src) : defaultProfilePic), 'direct'),
            isOnline: getResolvedContactOnlineState(normalizedUserId, contactEl)
        };
    }

    function ensurePresenceIndicatorChildren(indicatorEl) {
        if (!indicatorEl || indicatorEl.dataset.presenceDecorated === '1') {
            return;
        }

        if (!indicatorEl.querySelector('span')) {
            for (let i = 0; i < 3; i += 1) {
                const dot = document.createElement('span');
                dot.setAttribute('aria-hidden', 'true');
                indicatorEl.appendChild(dot);
            }
        }

        indicatorEl.dataset.presenceDecorated = '1';
    }

    function applyPresenceIndicatorState(indicatorEl, isOnline, isTyping = false) {
        if (!indicatorEl) {
            return;
        }

        ensurePresenceIndicatorChildren(indicatorEl);
        indicatorEl.classList.toggle('online', !!isOnline);
        indicatorEl.classList.toggle('typing', !!isTyping && !!isOnline);
    }

    function isUserCurrentlyTyping(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        return !!(
            normalizedUserId &&
            typingIndicatorUser &&
            String(typingIndicatorUser) === normalizedUserId &&
            typingPresence &&
            typingPresence.classList.contains('active')
        );
    }

    function getActiveGroupTypingEntries(groupKey) {
        const normalizedGroupKey = groupKey ? String(groupKey) : '';
        if (!normalizedGroupKey || !groupTypingUsers[normalizedGroupKey]) {
            return [];
        }

        return Object.entries(groupTypingUsers[normalizedGroupKey] || {})
            .filter(([, data]) => (Date.now() - Number(data.timestamp || 0)) < 5000)
            .map(([userId, data]) => ({
                userId,
                displayName: String(data.displayName || '').trim() || 'Someone',
                timestamp: Number(data.timestamp || 0)
            }))
            .sort((a, b) => a.timestamp - b.timestamp);
    }

    function getGroupTypingSummaryText(groupKey, typingEntries = null) {
        const typers = Array.isArray(typingEntries)
            ? typingEntries
            : getActiveGroupTypingEntries(groupKey);
        if (!typers.length) {
            return '';
        }

        if (typers.length === 1) {
            return `${typers[0].displayName} is typing...`;
        }
        if (typers.length === 2) {
            return `${typers[0].displayName} and ${typers[1].displayName} are typing...`;
        }
        if (typers.length === 3) {
            return `${typers[0].displayName}, ${typers[1].displayName}, and ${typers[2].displayName} are typing...`;
        }

        return `${typers[0].displayName}, ${typers[1].displayName}, and ${typers.length - 2} others are typing...`;
    }

    function isChatCurrentlyTyping(chatKey, meta = null) {
        const normalizedChatKey = chatKey ? String(chatKey) : '';
        if (!normalizedChatKey || !getAppSetting('typingIndicators')) {
            return false;
        }

        const resolvedMeta = meta || getContactMeta(normalizedChatKey);
        if (resolvedMeta && resolvedMeta.isGroup) {
            return getActiveGroupTypingEntries(normalizedChatKey).length > 0;
        }

        return isUserCurrentlyTyping(normalizedChatKey);
    }

    function getInfoSurfaceSecondaryText(userId, meta = null) {
        const normalizedUserId = userId ? String(userId) : '';
        const resolvedMeta = meta || getContactMeta(normalizedUserId);
        if (!resolvedMeta) {
            return '';
        }

        if (resolvedMeta.isGroup) {
            const typingText = getGroupTypingSummaryText(normalizedUserId);
            if (typingText) {
                return typingText;
            }

            const count = Number(resolvedMeta.memberCount || 0);
            return `${count} member${count === 1 ? '' : 's'}`;
        }

        if (isUserCurrentlyTyping(normalizedUserId)) {
            return 'Typing...';
        }

        return resolvedMeta.username ? `@${resolvedMeta.username}` : '';
    }

    function refreshTypingStatusSurfaces(chatKey) {
        const normalizedChatKey = chatKey ? String(chatKey) : '';
        if (!normalizedChatKey) {
            return;
        }

        if (
            contactInfoPanel
            && contactInfoPanel.classList.contains('active')
            && selectedUser
            && String(selectedUser) === normalizedChatKey
        ) {
            updateContactInfoPanel(normalizedChatKey);
        } else {
            refreshOpenProfileViews(normalizedChatKey);
        }
    }

    function refreshPresenceIndicatorsForUser(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId) {
            return;
        }

        const meta = getContactMeta(normalizedUserId);
        const isOnline = !!(meta && meta.isOnline);
        const isTyping = isUserCurrentlyTyping(normalizedUserId);
        const contactEl = getContactElement(normalizedUserId);

        if (contactEl) {
            contactEl.dataset.typing = isTyping ? '1' : '0';
            applyPresenceIndicatorState(contactEl.querySelector('.online-indicator'), isOnline, isTyping);
        }

        if (selectedUser && String(selectedUser) === normalizedUserId) {
            applyPresenceIndicatorState(chatHeaderStatusDot, isOnline, isTyping);
            applyPresenceIndicatorState(contactInfoStatusDot, isOnline, isTyping);
        }

        updateRenderedMessagePresence(normalizedUserId);
        updateRenderedReadReceiptPresence(normalizedUserId);
        if (!meta || !meta.isGroup) {
            renderMobileContactsStrip();
        }
        refreshTypingStatusSurfaces(normalizedUserId);
    }

    function updateRenderedMessagePresence(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId || !chatBox) {
            return;
        }

        const isSelf = normalizedUserId === String(currentUserId);
        const presence = getMessagePresenceData(normalizedUserId, isSelf);
        const avatarAlt = isSelf ? 'You' : getUsernameById(normalizedUserId);

        chatBox.querySelectorAll(`.message[data-sender-id="${normalizedUserId}"]`).forEach(messageEl => {
            const avatarEls = messageEl.querySelectorAll('.message-avatar, .message-inline-meta-avatar');
            const dotEl = messageEl.querySelector('.message-presence-dot');

            avatarEls.forEach(avatarEl => {
                avatarEl.src = presence.profilePic;
                avatarEl.alt = avatarAlt;
            });

            if (dotEl) {
                applyPresenceIndicatorState(dotEl, presence.isOnline, !isSelf && isUserCurrentlyTyping(normalizedUserId));
            }
        });
    }

    function updateRenderedReadReceiptPresence(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId || !chatBox) {
            return;
        }

        const isSelf = normalizedUserId === String(currentUserId);
        const presence = getMessagePresenceData(normalizedUserId, isSelf);
        const displayName = isSelf
            ? 'You'
            : getDisplayNameForUser(normalizedUserId, {
                displayName: getUsernameById(normalizedUserId) || normalizedUserId,
                username: '',
                isGroup: false
            });

        chatBox.querySelectorAll(`.read-receipt-mini[data-user-id="${normalizedUserId}"]`).forEach(receiptEl => {
            const avatarEl = receiptEl.querySelector('img');
            const dotEl = receiptEl.querySelector('.message-presence-dot');

            receiptEl.title = displayName;

            if (avatarEl) {
                avatarEl.src = presence.profilePic;
                avatarEl.alt = displayName;
            }

            if (dotEl) {
                applyPresenceIndicatorState(dotEl, presence.isOnline, false);
            }
        });
    }

    function beginCallHistory(otherUserId, callerUserId) {
        const normalizedUserId = otherUserId ? String(otherUserId) : '';
        const normalizedCallerId = callerUserId ? String(callerUserId) : '';
        if (!normalizedUserId || !normalizedCallerId) {
            activeCallHistory = null;
            return;
        }

        activeCallHistory = {
            otherUserId: normalizedUserId,
            callerId: normalizedCallerId,
            logged: false
        };
    }

    async function logCallHistoryEntry(type) {
        if (!activeCallHistory || activeCallHistory.logged || !activeCallHistory.otherUserId) {
            return false;
        }

        const history = {
            ...activeCallHistory,
            type
        };
        activeCallHistory.logged = true;

        try {
            const res = await fetch('log_call_event.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    recipient_id: history.otherUserId,
                    type: history.type,
                    caller_id: history.callerId
                })
            });

            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                console.warn('CALL_HISTORY: Failed to save call history entry.', data);
                activeCallHistory = null;
                return false;
            }

            if (data.message) {
                const loggedMessage = {
                    ...data.message,
                    self: String(data.message.sender_id) === String(currentUserId)
                };
                
                // Store message ID in activeCallHistory before clearing it
                if (activeCallHistory) {
                    activeCallHistory.messageId = data.message.id;
                }
                
                updateContactPreview(history.otherUserId, loggedMessage, true);
                if (selectedUser && String(selectedUser) === String(history.otherUserId)) {
                    appendMessage(loggedMessage);
                }
                
                // Missed call events should surface as unread right away.
                if (type === 'missed') {
                    refreshUnreadBadges().catch(() => {});
                    try {
                        await fetch('send_missed_call_notification.php', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                token,
                                caller_id: history.callerId,
                                recipient_id: history.otherUserId,
                                message_id: data.message.id
                            })
                        });
                    } catch (e) {
                        console.warn('Failed to send missed call notification:', e);
                    }
                }
            }

            const messageId = data.message ? data.message.id : null;
            activeCallHistory = null;
            return messageId;
        } catch (e) {
            console.error('CALL_HISTORY: Failed to log call history entry.', e);
            activeCallHistory = null;
            return false;
        }
    }

    function setContactInfoButtonState(enabled) {
        const rsToggleBtn = document.getElementById('right-sidebar-toggle-btn');
        [contactInfoBtn, contactInfoBtnMobile, rsToggleBtn].forEach(button => {
            if (!button) return;
            button.classList.toggle('icon-disabled', !enabled);
            button.disabled = !enabled;
        });
        if (enabled) updateRightSidebarToggleBtn();
    }

    function setContactInfoOpen(isOpen) {
        if (!contactInfoPanel) {
            return;
        }

        const shouldOpen = !!(isOpen && selectedUser);
        contactInfoPanel.classList.toggle('active', shouldOpen);
        contactInfoPanel.setAttribute('aria-hidden', shouldOpen ? 'false' : 'true');

        [contactInfoBtn, contactInfoBtnMobile].forEach(button => {
            if (button) {
                button.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
            }
        });

        updateMobileBackButtonState();
    }

    function hideContactInfoPanel() {
        setContactInfoOpen(false);
    }

    function setGroupMembersExpandedState(isExpanded) {
        if (!contactInfoMembersList || !contactInfoMembersToggle) {
            return;
        }

        const expanded = !!isExpanded;
        contactInfoMembersList.classList.toggle('is-collapsed', !expanded);
        // Remove inline style to let CSS class handle display
        if (expanded) {
            contactInfoMembersList.style.display = '';
        }
        contactInfoMembersList.setAttribute('aria-hidden', expanded ? 'false' : 'true');
        contactInfoMembersToggle.setAttribute('aria-expanded', expanded ? 'true' : 'false');
        contactInfoMembersToggle.textContent = expanded ? 'Hide members' : 'Show members';
    }

    function renderGroupMembersList(userId) {
        console.log('renderGroupMembersList called with userId:', userId);
        if (!contactInfoMembersSection || !contactInfoMembersSummary || !contactInfoMembersToggle || !contactInfoMembersList) {
            console.log('Missing elements:', {
                contactInfoMembersSection: !!contactInfoMembersSection,
                contactInfoMembersSummary: !!contactInfoMembersSummary,
                contactInfoMembersToggle: !!contactInfoMembersToggle,
                contactInfoMembersList: !!contactInfoMembersList
            });
            return;
        }

        const normalizedUserId = userId
            ? String(userId)
            : String((contactInfoMembersToggle && contactInfoMembersToggle.dataset.chatKey) || selectedUser || '');
        const meta = getContactMeta(normalizedUserId);
        const isGroup = !!(meta && meta.isGroup);
        console.log('Is group:', isGroup, 'meta:', meta);
        contactInfoMembersSection.hidden = !isGroup;

        if (!isGroup) {
            contactInfoMembersList.innerHTML = '';
            setGroupMembersExpandedState(false);
            return;
        }

        const members = Array.isArray(groupMembersMap[normalizedUserId]) ? groupMembersMap[normalizedUserId] : [];
        console.log('Members array:', members, 'length:', members.length, 'groupMembersExpanded:', groupMembersExpanded);
        const memberCount = Number(meta.memberCount || members.length || 0);
        contactInfoMembersSummary.textContent = `${memberCount} member${memberCount === 1 ? '' : 's'}`;
        setGroupMembersExpandedState(groupMembersExpanded);

        if (!groupMembersExpanded) {
            console.log('Members not expanded, returning');
            return;
        }

        contactInfoMembersList.innerHTML = '';
        if (!members.length) {
            const empty = document.createElement('div');
            empty.className = 'contact-info-member-empty';
            empty.textContent = 'Loading members...';
            contactInfoMembersList.appendChild(empty);
            return;
        }

        members.forEach(member => {
            const memberId = String(member.user_id || member.id || '');
            console.log('Member:', member.display_name, 'viewer_can_moderate:', member.viewer_can_moderate, 'viewer_can_change_role:', member.viewer_can_change_role);
            const card = document.createElement('div');
            card.className = 'contact-info-member-card';
            card.dataset.memberId = memberId;

            const avatarWrap = document.createElement('div');
            avatarWrap.className = 'contact-info-member-avatar-wrap';

            const avatar = document.createElement('img');
            avatar.className = 'contact-info-member-avatar';
            avatar.src = member.profile_pic || userProfilePics[memberId] || defaultProfilePic;
            avatar.alt = member.display_name || member.username || `User ${memberId}`;

            const indicator = document.createElement('span');
            indicator.className = 'online-indicator';
            ensurePresenceIndicatorChildren(indicator);
            applyPresenceIndicatorState(indicator, Number(member.online) === 1, false);

            avatarWrap.appendChild(avatar);
            avatarWrap.appendChild(indicator);

            const copy = document.createElement('div');
            copy.className = 'contact-info-member-copy';

            const name = document.createElement('div');
            name.className = 'contact-info-member-name';
            const memberDisplayName = getDisplayNameForUser(memberId, { 
                displayName: member.display_name, 
                username: member.username,
                isGroup: false 
            }, normalizedUserId);
            name.textContent = memberDisplayName;

            const metaLine = document.createElement('div');
            metaLine.className = 'contact-info-member-meta';
            const role = String(member.role || '').trim();
            const status = Number(member.online) === 1 ? 'Online' : 'Offline';
            metaLine.textContent = role ? `${role.charAt(0).toUpperCase()}${role.slice(1)} | ${status}` : status;

            copy.appendChild(name);
            copy.appendChild(metaLine);

            card.appendChild(avatarWrap);
            card.appendChild(copy);

            // ⋮ dots button for admins/owners on manageable members
            const canModerate = !!(Number(member.viewer_can_moderate) || member.viewer_can_moderate === true || member.viewer_can_moderate === '1');
            const canChangeRole = !!(Number(member.viewer_can_change_role) || member.viewer_can_change_role === true || member.viewer_can_change_role === '1');
            
            if (canModerate || canChangeRole) {
                const dotsBtn = document.createElement('button');
                dotsBtn.className = 'member-card-actions-btn';
                dotsBtn.setAttribute('aria-label', 'Member actions');
                dotsBtn.innerHTML = '<i class="fas fa-ellipsis-vertical"></i>';
                dotsBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    openMemberCtxMenu(
                        e,
                        normalizedUserId,
                        memberId,
                        memberDisplayName,
                        !!Number(member.is_muted || 0) || isFutureDateValue(member.muted_until),
                        canModerate,
                        canChangeRole
                    );
                });
                card.appendChild(dotsBtn);
            }

            contactInfoMembersList.appendChild(card);
        });
    }

    async function fetchGroupMembersForInfo(userId, { silent = true } = {}) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId || !isGroupChatKey(normalizedUserId)) {
            return null;
        }

        try {
            const res = await fetch(`get_group_details.php?token=${token}&with=${encodeURIComponent(normalizedUserId)}&t=${Date.now()}`);
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                throw new Error(data.error || 'Unable to load group members right now.');
            }

            const group = data.group || {};
            const members = Array.isArray(data.members) ? data.members : [];
            groupNamesMap[normalizedUserId] = String(group.display_name || `Group ${getGroupIdFromChatKey(normalizedUserId) || ''}`.trim());
            groupDescriptionsMap[normalizedUserId] = String(group.bio ?? '');
            groupIconsMap[normalizedUserId] = String(group.profile_pic || DEFAULT_GROUP_CHAT_ICON);
            groupCreatedAtMap[normalizedUserId] = String(group.created_at || '');
            groupMemberCountMap[normalizedUserId] = Number(group.member_count || members.length || 0);
            groupOnlineMap[normalizedUserId] = resolveGroupOnlineStateFromMembers(
            members,
            Number(group.online) === 1
        );
            groupMembersMap[normalizedUserId] = members;

            members.forEach(member => {
                const memberId = String(member.user_id || member.id || '');
                if (memberId) {
                    rememberChatNickname(normalizedUserId, memberId, member.chat_nickname || '');
                }
            });

            const contactEl = getContactElement(normalizedUserId);
            if (contactEl) {
                contactEl.dataset.memberCount = String(groupMemberCountMap[normalizedUserId] || 0);
                contactEl.dataset.bio = groupDescriptionsMap[normalizedUserId] || '';
                contactEl.dataset.viewerChatNickname = rememberViewerChatNickname(normalizedUserId, group.viewer_chat_nickname || contactEl.dataset.viewerChatNickname || '');
                contactEl.dataset.createdAt = groupCreatedAtMap[normalizedUserId] || '';
                contactEl.dataset.displayName = groupNamesMap[normalizedUserId] || contactEl.dataset.displayName || '';
                contactEl.dataset.online = groupOnlineMap[normalizedUserId] ? '1' : '0';
                contactEl.dataset.viewerRole = String(group.viewer_role || '');
                contactEl.dataset.viewerMutedUntil = String(group.viewer_muted_until ?? '');
                contactEl.dataset.sendPermission = String(group.send_permission || GROUP_SEND_PERMISSION_ALL);
                contactEl.dataset.addMembersPermission = String(group.add_members_permission || GROUP_ADD_PERMISSION_ADMINS);
                contactEl.dataset.canManageGroup = group.viewer_can_manage_group ? '1' : '0';
                contactEl.dataset.canChangeRoles = group.viewer_can_change_roles ? '1' : '0';
                contactEl.dataset.canDeleteGroup = group.viewer_can_delete_group ? '1' : '0';
                contactEl.dataset.canSendGroup = group.viewer_can_send ? '1' : '0';

                const contactNameEl = contactEl.querySelector('.contact-name');
                if (contactNameEl && groupNamesMap[normalizedUserId]) {
                    contactNameEl.textContent = groupNamesMap[normalizedUserId];
                }

                const contactImgEl = contactEl.querySelector('.contact-img');
                if (contactImgEl && groupIconsMap[normalizedUserId]) {
                    contactImgEl.src = groupIconsMap[normalizedUserId];
                    contactImgEl.alt = groupNamesMap[normalizedUserId] || 'Group chat';
                }
            }

            members.forEach(member => {
                const memberId = String(member.user_id || member.id || '');
                if (!memberId) {
                    return;
                }

                userNamesMap[memberId] = String(member.display_name || member.username || userNamesMap[memberId] || `User ${memberId}`);
                userUsernamesMap[memberId] = String(member.username || userUsernamesMap[memberId] || '');
                userProfilePics[memberId] = String(member.profile_pic || userProfilePics[memberId] || defaultProfilePic);
                userOnlineMap[memberId] = Number(member.online) === 1;
            });

            if (selectedUser && String(selectedUser) === normalizedUserId) {
                updateHeaderContact(normalizedUserId);
                renderGroupMembersList(normalizedUserId);
            }

            return data;
        } catch (error) {
            if (!silent) {
                console.warn('Unable to load group members.', error);
            }

            if (groupMembersExpanded && contactInfoMembersList) {
                contactInfoMembersList.innerHTML = '';
                const empty = document.createElement('div');
                empty.className = 'contact-info-member-empty';
                empty.textContent = 'Could not load the group members right now.';
                contactInfoMembersList.appendChild(empty);
            }
            return null;
        }
    }

    function applyGroupDetailsPayload(chatKey, payload) {
        const normalizedUserId = chatKey ? String(chatKey) : '';
        if (!normalizedUserId || !payload || !payload.group) {
            return null;
        }

        const group = payload.group || {};
        const members = Array.isArray(payload.members) ? payload.members : [];
        groupNamesMap[normalizedUserId] = String(group.display_name || `Group ${getGroupIdFromChatKey(normalizedUserId) || ''}`.trim());
        groupDescriptionsMap[normalizedUserId] = String(group.bio ?? '');
        groupIconsMap[normalizedUserId] = String(group.profile_pic || DEFAULT_GROUP_CHAT_ICON);
        groupCreatedAtMap[normalizedUserId] = String(group.created_at || '');
        groupMemberCountMap[normalizedUserId] = Number(group.member_count || members.length || 0);
        groupOnlineMap[normalizedUserId] = resolveGroupOnlineStateFromMembers(
            members,
            Number(group.online) === 1
        );
        groupMembersMap[normalizedUserId] = members;

        members.forEach(member => {
            const memberId = String(member.user_id || member.id || '');
            if (memberId) {
                rememberChatNickname(normalizedUserId, memberId, member.chat_nickname || '');
            }
        });

        const contactEl = getContactElement(normalizedUserId);
        if (contactEl) {
            contactEl.dataset.memberCount = String(groupMemberCountMap[normalizedUserId] || 0);
            contactEl.dataset.bio = groupDescriptionsMap[normalizedUserId] || '';
            contactEl.dataset.createdAt = groupCreatedAtMap[normalizedUserId] || '';
            contactEl.dataset.displayName = groupNamesMap[normalizedUserId] || contactEl.dataset.displayName || '';
            contactEl.dataset.viewerChatNickname = rememberViewerChatNickname(normalizedUserId, group.viewer_chat_nickname || contactEl.dataset.viewerChatNickname || '');
            contactEl.dataset.online = groupOnlineMap[normalizedUserId] ? '1' : '0';
            contactEl.dataset.viewerRole = String(group.viewer_role || '');
            contactEl.dataset.viewerMutedUntil = String(group.viewer_muted_until ?? '');
            contactEl.dataset.sendPermission = String(group.send_permission || GROUP_SEND_PERMISSION_ALL);
            contactEl.dataset.addMembersPermission = String(group.add_members_permission || GROUP_ADD_PERMISSION_ADMINS);
            contactEl.dataset.canManageGroup = group.viewer_can_manage_group ? '1' : '0';
            contactEl.dataset.canChangeRoles = group.viewer_can_change_roles ? '1' : '0';
            contactEl.dataset.canDeleteGroup = group.viewer_can_delete_group ? '1' : '0';
            contactEl.dataset.canSendGroup = group.viewer_can_send ? '1' : '0';
            contactEl.dataset.notificationMode = normalizeChatNotificationMode(group.notification_mode || contactEl.dataset.notificationMode || 'all');

            const contactNameEl = contactEl.querySelector('.contact-name');
            if (contactNameEl && groupNamesMap[normalizedUserId]) {
                contactNameEl.textContent = groupNamesMap[normalizedUserId];
            }

            const contactImgEl = contactEl.querySelector('.contact-img');
            if (contactImgEl && groupIconsMap[normalizedUserId]) {
                contactImgEl.src = groupIconsMap[normalizedUserId];
                contactImgEl.alt = groupNamesMap[normalizedUserId] || 'Group chat';
            }
        }

        members.forEach(member => {
            const memberId = String(member.user_id || member.id || '');
            if (!memberId) {
                return;
            }

            userNamesMap[memberId] = String(member.display_name || member.username || userNamesMap[memberId] || `User ${memberId}`);
            userUsernamesMap[memberId] = String(member.username || userUsernamesMap[memberId] || '');
            userProfilePics[memberId] = String(member.profile_pic || userProfilePics[memberId] || defaultProfilePic);
            userOnlineMap[memberId] = Number(member.online) === 1;
        });

        if (selectedUser && String(selectedUser) === normalizedUserId) {
            updateHeaderContact(normalizedUserId);
            renderGroupMembersList(normalizedUserId);
        }

        return payload;
    }

    // ─── Member context menu ──────────────────────────────────────────────────
    const memberCtxMenu = document.getElementById('memberCtxMenu');
    const memberCtxMenuHeader = document.getElementById('memberCtxMenuHeader');
    let ctxMenuGroupKey = '';
    let ctxMenuMemberId = '';

    function openMemberCtxMenu(e, groupKey, memberId, memberName, isMuted, canModerate, canChangeRole) {
        ctxMenuGroupKey = groupKey;
        ctxMenuMemberId = memberId;
        memberCtxMenuHeader.textContent = memberName;

        // Show/hide items based on permissions
        const changeRoleBtn = memberCtxMenu.querySelector('[data-action="change_role"]');
        const sepAfterRole = changeRoleBtn ? changeRoleBtn.nextElementSibling : null;
        if (changeRoleBtn) changeRoleBtn.style.display = canChangeRole ? 'flex' : 'none';
        if (sepAfterRole && sepAfterRole.classList.contains('member-ctx-menu-sep')) {
            sepAfterRole.style.display = (canChangeRole || canModerate) ? '' : 'none';
        }

        const timeoutBtn = memberCtxMenu.querySelector('[data-action="timeout"]');
        const banBtn = memberCtxMenu.querySelector('[data-action="ban"]');
        if (timeoutBtn) timeoutBtn.style.display = canModerate ? 'flex' : 'none';
        if (banBtn) banBtn.style.display = canModerate ? 'flex' : 'none';

        const clearBtn = memberCtxMenu.querySelector('[data-action="clear_timeout"]');
        if (clearBtn) clearBtn.style.display = (canModerate && isMuted) ? 'flex' : 'none';

        // Hide last sep if no moderation items visible
        const seps = memberCtxMenu.querySelectorAll('.member-ctx-menu-sep');
        if (seps.length > 1) seps[seps.length - 1].style.display = canModerate ? '' : 'none';

        memberCtxMenu.classList.add('is-open');
        ctxMenuJustOpened = true;

        // Position near button, keep inside viewport
        const rect = e.currentTarget ? e.currentTarget.getBoundingClientRect() : null;
        const menuW = 210, menuH = 260;
        let x = rect ? rect.right : e.clientX;
        let y = rect ? rect.bottom : e.clientY;
        if (x + menuW > window.innerWidth) x = (rect ? rect.left : e.clientX) - menuW;
        if (y + menuH > window.innerHeight) y = (rect ? rect.top : e.clientY) - menuH;
        memberCtxMenu.style.left = Math.max(4, x) + 'px';
        memberCtxMenu.style.top = Math.max(4, y) + 'px';
    }

    function closeMemberCtxMenu() {
        memberCtxMenu.classList.remove('is-open');
        // Don't clear ctxMenuGroupKey/ctxMenuMemberId here — they're read by the click handler
        // which fires after mousedown. They get overwritten on next openMemberCtxMenu call.
    }

    // Use mousedown so we can distinguish a click-outside from the right-click that opened the menu
    let ctxMenuJustOpened = false;
    document.addEventListener('mousedown', (e) => {
        if (ctxMenuJustOpened) { ctxMenuJustOpened = false; return; }
        if (!memberCtxMenu.contains(e.target)) closeMemberCtxMenu();
    });
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') closeMemberCtxMenu();
    });

    memberCtxMenu.addEventListener('click', async (e) => {
        const btn = e.target.closest('[data-action]');
        if (!btn || !ctxMenuGroupKey || !ctxMenuMemberId) return;
        const action = btn.dataset.action;
        const savedGroupKey = ctxMenuGroupKey;
        const savedMemberId = ctxMenuMemberId;
        closeMemberCtxMenu();

        // Change role: open group settings and scroll to that member
        if (action === 'change_role') {
            await openGroupSettingsModalFor(savedGroupKey);
            
            // Set higher z-index if members modal is open
            if (groupMembersModal && groupMembersModal.classList.contains('open')) {
                if (groupSettingsModal) {
                    bringOverlayToFront(groupSettingsModal, 6);
                }
            }
            
            // Scroll to the member's row in the settings list
            if (groupSettingsMembersList) {
                const targetRow = groupSettingsMembersList.querySelector(`[data-member-id="${savedMemberId}"], select[data-member-id="${savedMemberId}"]`);
                if (targetRow) {
                    const row = targetRow.closest('.group-settings-member-row') || targetRow;
                    row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    row.style.outline = '2px solid var(--accent-color)';
                    row.style.borderRadius = '18px';
                    setTimeout(() => { row.style.outline = ''; }, 1800);
                }
            }
            return;
        }

        // Timeout: open the duration picker modal
        if (action === 'timeout') {
            openTimeoutModal(savedGroupKey, savedMemberId, memberCtxMenuHeader.textContent);
            return;
        }

        const groupId = parseInt(savedGroupKey.replace('group:', ''), 10);
        const memberId = parseInt(savedMemberId, 10);

        try {
            const res = await fetch('moderate_group_member.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ token, group_id: groupId, member_id: memberId, action })
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                alert(data.error || 'Moderation action failed.');
                return;
            }
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
            await fetchGroupMembersForInfo(savedGroupKey, { silent: true });
        } catch {
            alert('Network error. Please try again.');
        }
    });

    // ─── Timeout modal ────────────────────────────────────────────────────────
    const timeoutModal = document.getElementById('timeoutModal');
    const timeoutModalSubtitle = document.getElementById('timeoutModalSubtitle');
    const timeoutDays = document.getElementById('timeoutDays');
    const timeoutHours = document.getElementById('timeoutHours');
    const timeoutMinutes = document.getElementById('timeoutMinutes');
    const timeoutModalCancel = document.getElementById('timeoutModalCancel');
    const timeoutModalApply = document.getElementById('timeoutModalApply');
    let timeoutTargetGroupKey = '';
    let timeoutTargetMemberId = '';

    function openTimeoutModal(groupKey, memberId, memberName) {
        timeoutTargetGroupKey = groupKey;
        timeoutTargetMemberId = memberId;
        if (timeoutModal) {
            timeoutModal.dataset.groupKey = groupKey;
            timeoutModal.dataset.memberId = memberId;
        }
        if (timeoutModalSubtitle) timeoutModalSubtitle.textContent = `Choose how long to time out ${memberName} for`;
        if (timeoutDays) timeoutDays.value = '0';
        if (timeoutHours) timeoutHours.value = '0';
        if (timeoutMinutes) timeoutMinutes.value = '15';
        if (timeoutModal) timeoutModal.classList.add('is-open');
    }

    function closeTimeoutModal() {
        if (timeoutModal) timeoutModal.classList.remove('is-open');
        timeoutTargetGroupKey = '';
        timeoutTargetMemberId = '';
    }

    if (timeoutModalCancel) timeoutModalCancel.addEventListener('click', closeTimeoutModal);
    // Removed backdrop click handler - modal only closes via buttons

    // Clamp inputs on blur
    [{ el: timeoutDays, max: 365 }, { el: timeoutHours, max: 23 }, { el: timeoutMinutes, max: 59 }].forEach(({ el, max }) => {
        if (!el) return;
        el.addEventListener('blur', () => {
            let v = parseInt(el.value, 10);
            if (isNaN(v) || v < 0) v = 0;
            if (v > max) v = max;
            el.value = v;
        });
    });

    if (timeoutModalApply) {
        timeoutModalApply.addEventListener('click', async () => {
            const days = Math.max(0, Math.min(365, parseInt(timeoutDays?.value || '0', 10) || 0));
            const hours = Math.max(0, Math.min(23, parseInt(timeoutHours?.value || '0', 10) || 0));
            const minutes = Math.max(0, Math.min(59, parseInt(timeoutMinutes?.value || '0', 10) || 0));
            const totalMinutes = days * 24 * 60 + hours * 60 + minutes;
            if (totalMinutes <= 0) { alert('Please set a duration greater than 0.'); return; }

            // Capture before closeTimeoutModal clears them — use data- as fallback
            const savedGroupKey = timeoutTargetGroupKey || (timeoutModal ? timeoutModal.dataset.groupKey : '');
            const savedMemberId = timeoutTargetMemberId || (timeoutModal ? timeoutModal.dataset.memberId : '');

            if (!savedGroupKey || !savedMemberId) {
                alert('Unable to apply timeout: missing target. Please try again.');
                closeTimeoutModal();
                return;
            }

            const groupId = parseInt(savedGroupKey.replace('group:', ''), 10);
            const memberId = parseInt(savedMemberId, 10);

            if (!groupId || !memberId) {
                alert('Unable to apply timeout: invalid group or member.');
                closeTimeoutModal();
                return;
            }

            closeTimeoutModal();

            try {
                const res = await fetch('moderate_group_member.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ token, group_id: groupId, member_id: memberId, action: 'timeout_custom', minutes: totalMinutes })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok || !data.success) { alert(data.error || 'Timeout failed.'); return; }
                invalidateSidebarHistoryCache({ reloadIfVisible: true });
                await fetchGroupMembersForInfo(savedGroupKey, { silent: true });
            } catch { alert('Network error. Please try again.'); }
        });
    }
    let activeGroupCallId = null;
    let activeGroupCallKey = null;
    let activeGroupCallConnected = false;
    let activeGroupCallIsPrivate = false;
    let groupCallPollInterval = null;
    let privateInviteCallTimeoutId = null;
    let groupCallSpeakingIntervals = {};
    const handledGroupCallIds = new Set();
    // Group IDs created just for ad-hoc calls (from the + menu) — hidden from contacts list
    const callOnlyGroupIds = new Set();
    const CALL_ONLY_GROUP_DESCRIPTION = '__CALL_ONLY_GROUP__';
    const ADHOC_GROUP_CALL_KEY_PREFIX = 'call:';
    let pendingDirectCallPromotionAckResolve = null;
    const groupCallParticipantsEl = document.getElementById('group-call-participants');
    // PeerJS mesh for group calls: userId -> { call, audioEl }
    const groupCallPeers = {};
    const resolvedPeerIdMap = new Map();
    const groupCallDialingUsers = new Set();
    let promotedDirectCallContext = null;

    function hasAcceptedRemoteGroupParticipants(participants = []) {
        return (Array.isArray(participants) ? participants : []).some(participant => {
            if (!participant || participant.invite_status !== 'accepted') {
                return false;
            }

            return String(participant.user_id || '').trim() !== String(currentUserId);
        });
    }

    function syncActiveGroupCallState(call = null, participants = []) {
        const normalizedParticipants = Array.isArray(participants) ? participants : [];
        const uniqueParticipantIds = new Set(
            normalizedParticipants
                .map(participant => String(participant && participant.user_id ? participant.user_id : '').trim())
                .filter(Boolean)
        );
        const groupId = Number(call && call.group_id ? call.group_id : 0);

        activeGroupCallConnected = hasAcceptedRemoteGroupParticipants(normalizedParticipants);
        activeGroupCallIsPrivate = groupId <= 0 && uniqueParticipantIds.size > 0 && uniqueParticipantIds.size <= 2;
    }

    function clearActiveGroupCallState() {
        activeGroupCallConnected = false;
        activeGroupCallIsPrivate = false;
    }

    function clearPrivateInviteCallTimeout() {
        if (!privateInviteCallTimeoutId) {
            return;
        }
        clearTimeout(privateInviteCallTimeoutId);
        privateInviteCallTimeoutId = null;
    }

    function getDirectLikeCallDisplayName(fallbackUserId = '') {
        const normalizedFallbackUserId = String(fallbackUserId || '').trim();
        const currentLabel = String(callUsername && callUsername.innerText ? callUsername.innerText : '')
            .replace(/^Calling\s+/i, '')
            .replace(/^Incoming(?:\s+video)?\s+call\s+from\s+/i, '')
            .replace(/\.\.\.$/, '')
            .trim();
        if (currentLabel) {
            return currentLabel;
        }

        if (normalizedFallbackUserId) {
            return getCallDisplayNameForUser(normalizedFallbackUserId, getContactMeta(normalizedFallbackUserId), {
                chatKey: normalizedFallbackUserId
            }) || getUsernameById(normalizedFallbackUserId) || `User ${normalizedFallbackUserId}`;
        }

        return '';
    }

    function getDirectLikeCallOutcomeContext(callId = activeGroupCallId) {
        const promotedContext = getPromotedDirectCallContext(callId);
        const fallbackUserId = promotedContext && promotedContext.otherUserId
            ? String(promotedContext.otherUserId)
            : String(selectedUser || '').trim();
        const callImageEl = document.getElementById('call-image');

        return {
            username: promotedContext && promotedContext.directName
                ? String(promotedContext.directName)
                : getDirectLikeCallDisplayName(fallbackUserId),
            profilePic: promotedContext && promotedContext.directProfilePic
                ? String(promotedContext.directProfilePic)
                : (callImageEl ? String(callImageEl.currentSrc || callImageEl.src || '') : ''),
            callMessageId: activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null
        };
    }

    function getDirectLikeCallOutcomeStatusText(outcome = 'ended') {
        if (outcome === 'declined') {
            return 'Call Declined';
        }
        if (outcome === 'missed') {
            return "Didn't answer.";
        }
        return 'Call ended';
    }

    function armPrivateInviteCallTimeout(callId) {
        const normalizedCallId = parseInt(callId, 10) || 0;
        clearPrivateInviteCallTimeout();
        if (!normalizedCallId) {
            return;
        }

        privateInviteCallTimeoutId = setTimeout(() => {
            privateInviteCallTimeoutId = null;

            const sameCallActive = !!(
                activeGroupCallId
                && String(activeGroupCallId) === String(normalizedCallId)
            );
            const shouldTimeoutPrivateCall = !!(
                sameCallActive
                && activeGroupCallIsPrivate
                && !activeGroupCallConnected
                && !groupCallTeardownInProgress
                && !getCurrentRemoteParticipantIds().length
            );

            if (!shouldTimeoutPrivateCall) {
                return;
            }

            endGroupCall(true, 'missed').catch(error => {
                console.warn('Failed to end unanswered private call cleanly.', error);
            });
        }, RINGING_DURATION);
    }

    function showInCallControlsBar() {
        if (!inCallControls) {
            return;
        }

        inCallControls.style.display = 'flex';
        inCallControls.dataset.restoreDisplay = 'flex';
    }

    function isCallOnlyGroupKey(groupKey) {
        const normalizedGroupKey = String(groupKey || '').trim();
        return !!(
            normalizedGroupKey
            && (
                callOnlyGroupIds.has(normalizedGroupKey)
                || String(groupDescriptionsMap[normalizedGroupKey] || '').trim() === CALL_ONLY_GROUP_DESCRIPTION
            )
        );
    }

    function buildAdhocGroupCallKey(callId) {
        const normalizedCallId = parseInt(callId, 10) || 0;
        return normalizedCallId > 0 ? `${ADHOC_GROUP_CALL_KEY_PREFIX}${normalizedCallId}` : '';
    }

    function buildGroupCallUiKey(callId, preferredKey = '', groupId = 0) {
        const normalizedPreferredKey = String(preferredKey || '').trim();
        if (normalizedPreferredKey) {
            return normalizedPreferredKey;
        }

        const normalizedGroupId = parseInt(groupId, 10) || 0;
        if (normalizedGroupId > 0) {
            return `group:${normalizedGroupId}`;
        }

        return buildAdhocGroupCallKey(callId);
    }

    function getGroupCallPeerId(userId) {
        return `user_${userId}`;
    }

    function capturePromotedDirectCallContext({ groupCallId = null, groupKey = '', otherUserId = '', callerId = '' } = {}) {
        const normalizedOtherUserId = String(otherUserId || '').trim();
        if (!normalizedOtherUserId) {
            return null;
        }

        const currentLabel = String(callUsername && callUsername.innerText ? callUsername.innerText : '')
            .replace(/^Calling\s+/i, '')
            .replace(/^Incoming(?:\s+video)?\s+call\s+from\s+/i, '')
            .replace(/\.\.\.$/, '')
            .trim();
        const fallbackMeta = getContactMeta(normalizedOtherUserId);
        const directName = currentLabel || getCallDisplayNameForUser(normalizedOtherUserId, fallbackMeta, {
            chatKey: normalizedOtherUserId
        }) || getUsernameById(normalizedOtherUserId) || `User ${normalizedOtherUserId}`;
        const callImageEl = document.getElementById('call-image');

        promotedDirectCallContext = {
            groupCallId: groupCallId ? String(groupCallId) : '',
            groupKey: String(groupKey || '').trim(),
            otherUserId: normalizedOtherUserId,
            callerId: String(callerId || (activeCallHistory && activeCallHistory.callerId) || currentUserId || '').trim(),
            directName,
            directProfilePic: callImageEl ? String(callImageEl.currentSrc || callImageEl.src || '') : '',
            groupUiActivated: false
        };

        return promotedDirectCallContext;
    }

    function syncPromotedDirectCallContext(updates = {}) {
        if (!promotedDirectCallContext || !updates || typeof updates !== 'object') {
            return promotedDirectCallContext;
        }

        promotedDirectCallContext = {
            ...promotedDirectCallContext,
            ...updates
        };

        if (Object.prototype.hasOwnProperty.call(updates, 'groupCallId')) {
            promotedDirectCallContext.groupCallId = updates.groupCallId ? String(updates.groupCallId) : '';
        }
        if (Object.prototype.hasOwnProperty.call(updates, 'groupKey')) {
            promotedDirectCallContext.groupKey = String(updates.groupKey || '').trim();
        }

        return promotedDirectCallContext;
    }

    function getPromotedDirectCallContext(callId = activeGroupCallId) {
        if (!promotedDirectCallContext) {
            return null;
        }

        if (callId && promotedDirectCallContext.groupCallId && String(promotedDirectCallContext.groupCallId) !== String(callId)) {
            return null;
        }

        return promotedDirectCallContext;
    }

    function clearPromotedDirectCallContext(callId = null) {
        if (!promotedDirectCallContext) {
            return;
        }

        if (callId && promotedDirectCallContext.groupCallId && String(promotedDirectCallContext.groupCallId) !== String(callId)) {
            return;
        }

        promotedDirectCallContext = null;
    }

    function shouldKeepPromotedDirectCallUi(participants = []) {
        const context = getPromotedDirectCallContext();
        if (!context || context.groupUiActivated) {
            return false;
        }

        const acceptedInvitedParticipants = (Array.isArray(participants) ? participants : [])
            .filter(p => {
                if (!p || p.invite_status !== 'accepted') {
                    return false;
                }

                const participantId = String(p.user_id || '').trim();
                return participantId
                    && participantId !== String(currentUserId)
                    && participantId !== String(context.otherUserId);
            });

        if (acceptedInvitedParticipants.length > 0) {
            syncPromotedDirectCallContext({ groupUiActivated: true });
            return false;
        }

        return true;
    }

    function applyPromotedDirectCallUi() {
        const context = getPromotedDirectCallContext();
        if (!context || groupCallTeardownInProgress) {
            return false;
        }
        activeGroupCallConnected = true;
        activeGroupCallIsPrivate = true;

        const callImageEl = document.getElementById('call-image');
        if (callImageEl) {
            callImageEl.src = context.directProfilePic || userProfilePics[String(context.otherUserId)] || defaultProfilePic;
            callImageEl.style.borderRadius = '50%';
        }

        if (callUsername) {
            callUsername.innerText = context.directName || getUsernameById(context.otherUserId) || `User ${context.otherUserId}`;
        }
        if (callStatus) {
            callStatus.innerText = 'Connected';
        }

        directCallUiMode = 'connected';
        callUi.style.display = 'flex';
        if (incomingActions) {
            incomingActions.style.display = 'none';
        }
        if (acceptCallBtn) {
            acceptCallBtn.style.display = 'none';
        }
        if (endCallBtn) {
            endCallBtn.style.display = 'none';
        }
        showInCallControlsBar();

        const endActiveBtn = document.getElementById('end-call-active');
        if (endActiveBtn) {
            endActiveBtn.onclick = () => endGroupCall(true);
        }

        renderAdhocCallParticipants([String(context.otherUserId)]);
        updateCallMessageButtonState();
        return true;
    }

    function maybeActivatePromotedGroupUi(remoteUserIds = null) {
        const context = getPromotedDirectCallContext();
        if (!context || context.groupUiActivated || groupCallTeardownInProgress) {
            return false;
        }

        const normalizedRemoteIds = Array.from(new Set(
            (Array.isArray(remoteUserIds) ? remoteUserIds : Object.keys(groupCallPeers))
                .map(id => String(id || '').trim())
                .filter(id => id && id !== String(currentUserId))
        ));

        const invitedParticipantJoined = normalizedRemoteIds.some(
            id => id !== String(context.otherUserId)
        );

        if (!invitedParticipantJoined) {
            return false;
        }

        return activatePromotedGroupUi();
    }

    function activatePromotedGroupUi() {
        const context = getPromotedDirectCallContext();
        if (!context || groupCallTeardownInProgress) {
            return false;
        }

        syncPromotedDirectCallContext({ groupUiActivated: true });
        activeGroupCallConnected = true;
        activeGroupCallIsPrivate = false;

        const callImageEl = document.getElementById('call-image');
        if (callImageEl) {
            callImageEl.src = (
                activeGroupCallKey && isGroupChatKey(String(activeGroupCallKey))
                    ? (groupIconsMap[String(activeGroupCallKey)] || DEFAULT_GROUP_CHAT_ICON)
                    : DEFAULT_GROUP_CHAT_ICON
            );
            callImageEl.style.borderRadius = '18px';
        }

        if (callUsername) {
            callUsername.innerText = getCallDisplayNameForChat(
                context.groupKey || activeGroupCallKey,
                'Group call'
            );
        }
        if (callStatus) {
            callStatus.innerText = 'Connected';
        }

        directCallUiMode = 'connected';
        callUi.style.display = 'flex';
        if (incomingActions) {
            incomingActions.style.display = 'none';
        }
        if (acceptCallBtn) {
            acceptCallBtn.style.display = 'none';
        }
        if (endCallBtn) {
            endCallBtn.style.display = 'none';
        }
        showInCallControlsBar();

        const endActiveBtn = document.getElementById('end-call-active');
        if (endActiveBtn) {
            endActiveBtn.onclick = () => endGroupCall(true);
        }

        updateCallMessageButtonState();
        return true;
    }

    function renderCurrentGroupCallParticipants(participants) {
        if (groupCallTeardownInProgress) {
            return;
        }
        const normalizedParticipants = Array.isArray(participants) ? participants : [];
        if (shouldKeepPromotedDirectCallUi(normalizedParticipants)) {
            applyPromotedDirectCallUi();
            return;
        }

        const context = getPromotedDirectCallContext();
        if (context && context.groupUiActivated) {
            activatePromotedGroupUi();
        }

        renderGroupCallParticipants(normalizedParticipants);
    }

    function getLiveAudioTrackFromStream(stream) {
        if (!stream || typeof stream.getAudioTracks !== 'function') {
            return null;
        }
        return stream.getAudioTracks().find(track => track && track.readyState === 'live') || null;
    }

    async function ensureLiveLocalAudioStream(preferredStream = null) {
        const existingStream = preferredStream || localAudioStream || null;
        const existingTrack = getLiveAudioTrackFromStream(existingStream);
        if (existingStream && existingTrack) {
            localAudioStream = existingStream;
            return { stream: existingStream, acquiredNew: false };
        }

        const refreshedStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        if (isMuted) {
            const refreshedTrack = getLiveAudioTrackFromStream(refreshedStream);
            if (refreshedTrack) {
                refreshedTrack.enabled = false;
            }
        }
        localAudioStream = refreshedStream;
        return { stream: refreshedStream, acquiredNew: true };
    }

    function rememberResolvedPeerId(userId, peerId) {
        const normalizedUserId = String(userId || '').trim();
        const normalizedPeerId = String(peerId || '').trim();
        if (!normalizedUserId || !normalizedPeerId) {
            return;
        }
        resolvedPeerIdMap.set(normalizedUserId, normalizedPeerId);
    }

    async function resolvePeerIdForUser(userId, options = {}) {
        const normalizedUserId = String(userId || '').trim();
        const basePeerId = getGroupCallPeerId(normalizedUserId);
        if (!normalizedUserId) {
            return basePeerId;
        }

        if (currentCall && currentCall.peer && getUserIdFromPeerId(currentCall.peer) === normalizedUserId) {
            rememberResolvedPeerId(normalizedUserId, currentCall.peer);
            return String(currentCall.peer);
        }

        if (activeDataConnection && activeDataConnection.peer && getUserIdFromPeerId(activeDataConnection.peer) === normalizedUserId) {
            rememberResolvedPeerId(normalizedUserId, activeDataConnection.peer);
            return String(activeDataConnection.peer);
        }

        if (!options.forceRefresh && resolvedPeerIdMap.has(normalizedUserId)) {
            return String(resolvedPeerIdMap.get(normalizedUserId) || basePeerId);
        }

        try {
            const peerRes = await fetch(`get_peer_id.php?token=${encodeURIComponent(token)}&user_id=${encodeURIComponent(normalizedUserId)}`);
            const peerData = await peerRes.json().catch(() => ({}));
            if (peerData && peerData.peer_id) {
                rememberResolvedPeerId(normalizedUserId, peerData.peer_id);
                return String(peerData.peer_id);
            }
        } catch {}

        return String(resolvedPeerIdMap.get(normalizedUserId) || basePeerId);
    }

    async function waitForDirectCallPeerId(userId, {
        timeoutMs = 6500,
        pollIntervalMs = 350,
        baseGraceMs = 2200
    } = {}) {
        const normalizedUserId = String(userId || '').trim();
        const basePeerId = getGroupCallPeerId(normalizedUserId);
        if (!normalizedUserId) {
            return basePeerId;
        }

        const startedAt = Date.now();
        let lastResolvedPeerId = String(resolvedPeerIdMap.get(normalizedUserId) || '').trim();

        while ((Date.now() - startedAt) < timeoutMs) {
            const resolvedPeerId = String(
                await resolvePeerIdForUser(normalizedUserId, { forceRefresh: true }) || ''
            ).trim();

            if (resolvedPeerId) {
                lastResolvedPeerId = resolvedPeerId;
                if (resolvedPeerId !== basePeerId) {
                    return resolvedPeerId;
                }

                if ((Date.now() - startedAt) >= baseGraceMs) {
                    return resolvedPeerId;
                }
            }

            await new Promise(resolve => setTimeout(resolve, pollIntervalMs));
        }

        return lastResolvedPeerId || basePeerId;
    }

    async function retryPendingDirectCallWithFreshPeerId({
        failedPeerId = '',
        metadata = null
    } = {}) {
        if (
            directCallPeerRetryInProgress
            || !peer
            || !localAudioStream
            || callConnectedFlag
            || localHangupInitiated
        ) {
            return false;
        }

        const remoteUserId = String(getDirectCallPeerUserId() || '').trim();
        if (!remoteUserId) {
            return false;
        }

        const basePeerId = getGroupCallPeerId(remoteUserId);
        const knownFallbackPeerId = String(window._callFallbackPeerId || '').trim();
        directCallPeerRetryInProgress = true;

        try {
            const freshPeerId = await waitForDirectCallPeerId(remoteUserId, {
                timeoutMs: 4500,
                pollIntervalMs: 400,
                baseGraceMs: 1200
            });

            const retryPeerId = [freshPeerId, knownFallbackPeerId]
                .map(candidate => String(candidate || '').trim())
                .find(candidate => candidate && candidate !== String(failedPeerId || '').trim());

            if (!retryPeerId) {
                return false;
            }

            rememberResolvedPeerId(remoteUserId, retryPeerId);
            window._callFallbackPeerId = retryPeerId !== basePeerId ? retryPeerId : null;

            const failedCall = currentCall;
            currentCall = null;
            if (failedCall) {
                try { failedCall.close(); } catch (error) {}
            }

            const retryCall = peer.call(retryPeerId, localAudioStream, {
                metadata: metadata || {
                    mediaKind: pendingVideoCall ? 'video' : 'audio',
                    call_request_id: activeCallRequestId || null
                }
            });

            if (!retryCall) {
                return false;
            }

            currentCall = retryCall;
            setupCallHandlers(retryCall);
            callUi.style.display = 'flex';
            callStatus.innerText = 'Ringing...';
            startRingbackAudio();
            return true;
        } catch (error) {
            console.warn('Direct call peer retry failed.', error);
            return false;
        } finally {
            directCallPeerRetryInProgress = false;
        }
    }

    function addGroupCallPeerAudio(userId, stream, options = {}) {
        const attachAudio = options && options.attachAudio !== false;
        // Remove existing if any
        removeGroupCallPeer(userId);
        let audioEl = null;
        if (attachAudio) {
            audioEl = document.createElement('audio');
            audioEl.autoplay = true;
            audioEl.srcObject = stream;
            audioEl.style.display = 'none';
            document.body.appendChild(audioEl);
            audioEl.play().catch(() => {});
        }
        groupCallPeers[String(userId)] = { audioEl };
        maybeActivatePromotedGroupUi();

        // Speaking detection for this remote participant
        if (window.AudioContext) {
            try {
                const ctx = new AudioContext();
                const analyser = ctx.createAnalyser();
                analyser.fftSize = 512;
                const src = ctx.createMediaStreamSource(stream);
                src.connect(analyser);
                const buf = new Uint8Array(analyser.frequencyBinCount);
                const tick = () => {
                    if (!groupCallPeers[String(userId)]) { ctx.close(); return; }
                    analyser.getByteFrequencyData(buf);
                    const avg = buf.reduce((a, b) => a + b, 0) / buf.length;
                    setParticipantSpeaking(userId, avg > 12);
                    requestAnimationFrame(tick);
                };
                requestAnimationFrame(tick);
            } catch {}
        }
    }

    function removeGroupCallPeer(userId) {
        const entry = groupCallPeers[String(userId)];
        if (entry && entry.audioEl) {
            entry.audioEl.srcObject = null;
            entry.audioEl.remove();
        }
        delete groupCallPeers[String(userId)];
    }

    function teardownAllGroupCallPeers() {
        Object.keys(groupCallPeers).forEach(uid => removeGroupCallPeer(uid));
    }

    // Called by the caller side when a new participant accepts — dial them via PeerJS
    async function dialGroupCallParticipant(userId, options = {}) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId || normalizedUserId === String(currentUserId)) return;
        if (groupCallPeers[normalizedUserId] || groupCallDialingUsers.has(normalizedUserId)) return;

        groupCallDialingUsers.add(normalizedUserId);
        try {
            const ensuredAudio = await ensureLiveLocalAudioStream(localAudioStream);
            const targetPeerId = await resolvePeerIdForUser(normalizedUserId, {
                forceRefresh: !!options.forceRefresh
            });
            if (groupCallPeers[normalizedUserId]) {
                return;
            }

            const call = peer.call(targetPeerId, ensuredAudio.stream, {
                metadata: {
                    mediaKind: 'audio',
                    callType: 'group',
                    groupCallId: activeGroupCallId || null
                }
            });
            groupCallPeers[normalizedUserId] = { call, audioEl: null };
            call.on('stream', (remoteStream) => {
                rememberResolvedPeerId(normalizedUserId, targetPeerId);
                addGroupCallPeerAudio(normalizedUserId, remoteStream);
            });
            call.on('close', () => removeGroupCallPeer(normalizedUserId));
            call.on('error', () => {
                if (String(targetPeerId) !== String(getGroupCallPeerId(normalizedUserId))) {
                    resolvedPeerIdMap.delete(normalizedUserId);
                }
                removeGroupCallPeer(normalizedUserId);
            });
        } catch {}
        finally {
            groupCallDialingUsers.delete(normalizedUserId);
        }
    }

    function renderGroupCallParticipants(participants) {
        if (!groupCallParticipantsEl) return;
        groupCallParticipantsEl.innerHTML = '';
        const accepted = Array.isArray(participants)
            ? participants.filter(p => p && p.invite_status === 'accepted')
            : [];
        const hasSelfParticipant = accepted.some(p => String(p.user_id || '') === String(currentUserId));
        if (!hasSelfParticipant) {
            accepted.unshift({
                user_id: currentUserId,
                display_name: currentUserDisplayName || currentUsername || 'You',
                username: currentUsername || '',
                profile_pic: currentUserProfilePic || defaultProfilePic,
                invite_status: 'accepted'
            });
        }
        if (!accepted.length) return;

        accepted.forEach(p => {
            const participantMeta = {
                displayName: p.display_name || p.username || `User ${p.user_id}`,
                username: p.username || '',
                isGroup: false
            };
            const wrap = document.createElement('div');
            wrap.className = 'gc-participant';
            wrap.dataset.userId = String(p.user_id);
            if (speakingParticipantIds.has(String(p.user_id))) {
                wrap.classList.add('is-speaking');
            }

            const avatarWrap = document.createElement('div');
            avatarWrap.className = 'gc-participant-avatar-wrap';

            const img = document.createElement('img');
            img.className = 'gc-participant-avatar';
            img.src = p.profile_pic || userProfilePics[String(p.user_id)] || 'images/default-profile.png';
            img.alt = getCallDisplayNameForUser(p.user_id, participantMeta, {
                chatKey: activeGroupCallKey
            });

            const nameTag = document.createElement('span');
            nameTag.className = 'gc-participant-name';
            nameTag.textContent = getCallDisplayNameForUser(p.user_id, participantMeta, {
                chatKey: activeGroupCallKey
            });

            avatarWrap.appendChild(img);
            wrap.appendChild(avatarWrap);
            wrap.appendChild(nameTag);
            groupCallParticipantsEl.appendChild(wrap);
        });

        groupCallParticipantsEl.style.display = (accepted.length && !callUi.classList.contains('has-video')) ? 'flex' : 'none';
        speakingParticipantIds.forEach(userId => setParticipantSpeaking(userId, true));
    }

    // Render participant strip for ad-hoc group calls (PeerJS mesh, no DB participants array)
    function renderAdhocCallParticipants(userIds) {
        if (!groupCallParticipantsEl) return;
        groupCallParticipantsEl.innerHTML = '';
        if (!userIds.length) { groupCallParticipantsEl.style.display = 'none'; return; }
        maybeActivatePromotedGroupUi(userIds);

        // Always include self
        const allIds = [String(currentUserId), ...userIds.map(String).filter(id => id !== String(currentUserId))];
        allIds.forEach(uid => {
            const wrap = document.createElement('div');
            wrap.className = 'gc-participant';
            wrap.dataset.userId = uid;
            if (speakingParticipantIds.has(String(uid))) {
                wrap.classList.add('is-speaking');
            }

            const avatarWrap = document.createElement('div');
            avatarWrap.className = 'gc-participant-avatar-wrap';

            const img = document.createElement('img');
            img.className = 'gc-participant-avatar';
            img.src = userProfilePics[uid] || 'images/default-profile.png';
            img.alt = userNamesMap[uid] || `User ${uid}`;

            const nameTag = document.createElement('span');
            nameTag.className = 'gc-participant-name';
            nameTag.textContent = userNamesMap[uid] || `User ${uid}`;

            avatarWrap.appendChild(img);
            wrap.appendChild(avatarWrap);
            wrap.appendChild(nameTag);
            groupCallParticipantsEl.appendChild(wrap);
        });

        groupCallParticipantsEl.style.display = callUi.classList.contains('has-video') ? 'none' : 'flex';
        speakingParticipantIds.forEach(userId => setParticipantSpeaking(userId, true));
    }

    // Mark a participant as speaking in the strip
    function setParticipantSpeaking(userId, isSpeaking) {
        const normalizedUserId = String(userId || '');
        if (!normalizedUserId) {
            return;
        }

        if (isSpeaking) {
            speakingParticipantIds.add(normalizedUserId);
        } else {
            speakingParticipantIds.delete(normalizedUserId);
        }

        if (groupCallParticipantsEl) {
            const participantEl = groupCallParticipantsEl.querySelector(`.gc-participant[data-user-id="${normalizedUserId}"]`);
            if (participantEl) {
                participantEl.classList.toggle('is-speaking', isSpeaking);
            }
        }

        callVideoGrid.querySelectorAll(`.call-media-tile[data-user-id="${normalizedUserId}"]`).forEach(tile => {
            tile.classList.toggle('is-speaking', isSpeaking);
        });

        if (callVideoLocalPreview && normalizedUserId === String(currentUserId)) {
            callVideoLocalPreview.classList.toggle('is-speaking', isSpeaking);
        }
    }

    function startCallSpeakingDetection(stream, participantId = currentUserId) {
        if (!stream || !window.AudioContext) return;
        const runId = ++speakingDetectionRunId;
        try {
            const ctx = new AudioContext();
            const analyser = ctx.createAnalyser();
            analyser.fftSize = 512;
            const src = ctx.createMediaStreamSource(stream);
            src.connect(analyser);
            const buf = new Uint8Array(analyser.frequencyBinCount);

            const tick = () => {
                const callStillActive = !!(activeGroupCallId || currentCall || callConnectedFlag || callUi.style.display === 'flex');
                if (runId !== speakingDetectionRunId || !callStillActive) {
                    setParticipantSpeaking(participantId, false);
                    ctx.close();
                    return;
                }
                analyser.getByteFrequencyData(buf);
                const avg = buf.reduce((a, b) => a + b, 0) / buf.length;
                setParticipantSpeaking(participantId, avg > 12);
                requestAnimationFrame(tick);
            };
            requestAnimationFrame(tick);
        } catch {}
    }

    async function pollGroupCallState() {
        const pollCallId = activeGroupCallId;
        if (!pollCallId || groupCallTeardownInProgress) return;
        try {
            const res = await fetch(`get_group_call_state.php?token=${encodeURIComponent(token)}&call_id=${pollCallId}&t=${Date.now()}`);
            const data = await res.json().catch(() => ({}));
            if (groupCallTeardownInProgress || !activeGroupCallId || String(activeGroupCallId) !== String(pollCallId)) {
                return;
            }
            if (!data.success) return;
            if (data.call && data.call.status === 'ended') {
                endGroupCall(false, 'ended');
                return;
            }
            if (data.participants) {
                syncActiveGroupCallState(data.call || null, data.participants);
                renderCurrentGroupCallParticipants(data.participants);
                const accepted = data.participants.filter(
                    p => p.invite_status === 'accepted' && String(p.user_id) !== String(currentUserId)
                );
                const acceptedIds = new Set(accepted.map(p => String(p.user_id)));
                Object.keys(outgoingVideoCalls).forEach(userId => {
                    if (!acceptedIds.has(String(userId))) {
                        closeVideoCallObject(outgoingVideoCalls[userId]);
                        delete outgoingVideoCalls[userId];
                    }
                });
                Object.keys(remoteVideoFeeds).forEach(userId => {
                    if (!acceptedIds.has(String(userId))) {
                        removeRemoteVideoFeed(userId);
                    }
                });
                // Dial any newly accepted participants we haven't connected to yet
                accepted.forEach(p => {
                    dialGroupCallParticipant(p.user_id);
                    if (cameraEnabled) {
                        ensureOutgoingVideoCall(p.user_id);
                    }
                });

                // Transition caller UI from ringing to connected when first person accepts
                if (accepted.length > 0 && callStatus.innerText === 'Ringing...') {
                    clearPrivateInviteCallTimeout();
                    stopAndResetAudio(ringbackAudio);
                    // Strip "Calling " prefix
                    if (callUsername.innerText.startsWith('Calling ')) {
                        callUsername.innerText = callUsername.innerText.replace(/^Calling\s+/, '').replace(/\.\.\.$/, '');
                    }
                    callStatus.innerText = 'Connected'; startStopwatch(data.call ? data.call.created_at : null, data.call ? data.call.created_at_unix : null);
                    document.getElementById('incoming-actions').style.display = 'none';
                    if (activeGroupCallConnected) {
                        showInCallControlsBar();
                        if (audioDevices.length === 0) { 
                            loadAudioDevices().then(() => {
                                populateAudioSelector();
                                setSpeakerMode('phone'); // Initialize to phone mode
                            }); 
                        } else {
                            setSpeakerMode('phone'); // Initialize to phone mode
                        }
                        if (audioIcon) audioIcon.onclick = toggleAudioDropdown;
                        bindMuteToggle();
                        updateVideoToggleButtonState();
                        updateCallMessageButtonState();
                        const endActiveBtn = document.getElementById('end-call-active');
                        if (endActiveBtn) endActiveBtn.onclick = () => endGroupCall(true);
                    }
                }
            }
        } catch {}
    }

    function preserveCurrentCallUiForGroupCall(endHandler) {
        clearPendingCallUiDismiss();
        stopAndResetAudio(ringbackAudio);
        stopAndResetAudio(ringtoneAudio);
        directCallUiMode = 'connected';
        callUi.style.display = 'flex';
        applyCallUiMinimizedState(false);

        if (incomingActions) incomingActions.style.display = 'none';
        if (acceptCallBtn) {
            acceptCallBtn.style.display = 'none';
            acceptCallBtn.onclick = null;
        }
        if (leaveMessageBtn) leaveMessageBtn.style.display = 'none';
        if (callEndedControls) callEndedControls.style.display = 'none';
        if (callCloseBtn) callCloseBtn.style.display = 'none';
        if (endCallBtn) endCallBtn.style.display = 'none';
        if (callConnectedFlag || directCallUiMode === 'connected' || activeGroupCallConnected) {
            showInCallControlsBar();
        } else {
            hideInCallControls();
        }

        const endActiveBtn = document.getElementById('end-call-active');
        if (endActiveBtn) {
            endActiveBtn.onclick = endHandler;
        }

        updateVideoToggleButtonState();
        updateCallMessageButtonState();
    }

    function showOutgoingGroupCallUi(groupName, groupIcon, endHandler) {
        clearPendingCallUiDismiss();
        hideInCallControls();
        activeGroupCallConnected = false;
        stopStopwatch();
        directCallUiMode = 'connecting';

        if (leaveMessageBtn) leaveMessageBtn.style.display = 'none';
        if (callEndedControls) callEndedControls.style.display = 'none';
        if (callCloseBtn) callCloseBtn.style.display = 'none';

        callUi.style.display = 'flex';
        applyCallUiMinimizedState(false);
        document.getElementById('call-image').src = groupIcon;
        document.getElementById('call-image').style.borderRadius = '18px';
        callUsername.innerText = `Calling ${groupName}...`;
        callStatus.innerText = 'Ringing...';
        document.getElementById('incoming-actions').style.display = 'flex';
        document.getElementById('accept-call-btn').style.display = 'none';
        endCallBtn.style.display = 'inline-block';
        endCallBtn.style.backgroundColor = 'red';
        endCallBtn.onclick = endHandler;
        updateCallMessageButtonState();
    }

    async function initiateDirectCallViaInvite(options = {}) {
        const suppressAlerts = !!(options && options.suppressAlerts);
        const normalizedSelectedUser = String(selectedUser || '').trim();

        if (!normalizedSelectedUser) {
            if (!suppressAlerts) {
                alert('Please select a contact to call.');
            }
            return false;
        }

        if (getChatTypeFromKey(normalizedSelectedUser) !== 'direct') {
            return initiateGroupCall(normalizedSelectedUser, options);
        }

        if (isConversationBlocked(normalizedSelectedUser)) {
            if (!suppressAlerts) {
                alert(getBlockedCallError(normalizedSelectedUser));
            }
            return false;
        }

        if (currentCall || activeGroupCallId || outgoingCallSetupInProgress) {
            if (!suppressAlerts) {
                alert('You are already in a call.');
            }
            return false;
        }

        outgoingCallSetupInProgress = true;
        groupCallTeardownInProgress = false;

        const contactName = getCallDisplayNameForUser(normalizedSelectedUser, getContactMeta(normalizedSelectedUser), {
            chatKey: normalizedSelectedUser
        });
        const contactPic = userProfilePics[normalizedSelectedUser] || 'images/default-profile.png';

        try {
            const started = await initiateAdhocGroupCall([normalizedSelectedUser], {
                existingStream: options && options.existingStream ? options.existingStream : null,
                suppressAlerts: true,
                preferredGroupName: contactName,
                preferredGroupIcon: contactPic
            });

            if (!started || !activeGroupCallId) {
                if (!suppressAlerts) {
                    alert('Unable to start that call right now.');
                }
                return false;
            }

            const inviteRes = await fetch('send_call_invites.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    invited_user_ids: [Number(normalizedSelectedUser)],
                    call_type: 'group',
                    group_call_id: activeGroupCallId,
                    current_participants: [
                        {
                            user_id: Number(currentUserId),
                            display_name: currentUserDisplayName || currentUsername || 'You'
                        }
                    ]
                })
            });
            const inviteData = await inviteRes.json().catch(() => ({}));
            if (!inviteRes.ok || !inviteData.success) {
                await endGroupCall(true);
                if (!suppressAlerts) {
                    alert(inviteData.error || 'Unable to start that call right now.');
                }
                return false;
            }

            armPrivateInviteCallTimeout(activeGroupCallId);

            return {
                callId: activeGroupCallId,
                groupKey: activeGroupCallKey,
                groupName: contactName,
                groupIcon: contactPic
            };
        } catch (error) {
            console.error('Direct call via invite failed.', error);
            if (activeGroupCallId) {
                try {
                    await endGroupCall(true);
                } catch (endError) {}
            }
            if (!suppressAlerts) {
                alert('Unable to start that call right now.');
            }
            return false;
        } finally {
            outgoingCallSetupInProgress = false;
        }
    }

    async function initiateGroupCall(groupKey, options = {}) {
        if (activeGroupCallId) return false;
        groupCallTeardownInProgress = false;
        // Block timed-out users from starting/joining group calls
        const groupMeta = getContactMeta(groupKey);
        if (groupMeta && groupMeta.viewerIsMuted) {
            alert('You cannot start or join a call while you are in timeout.');
            return false;
        }
        const groupId = parseInt(groupKey.replace('group:', ''), 10);
        const groupName = getCallDisplayNameForChat(groupKey, groupNamesMap[groupKey] || 'Group');
        const groupIcon = groupIconsMap[groupKey] || 'images/default-group.svg';
        const existingStream = options && options.existingStream ? options.existingStream : null;
        const ownsStream = !existingStream;
        const suppressAlerts = !!(options && options.suppressAlerts);
        const suppressMessage = !!(options && options.suppressMessage);
        const preserveCallUi = !!(options && options.preserveCallUi);
        const keepExistingCallUi = !!(options && options.keepExistingCallUi);
        const suppressRingback = !!(options && options.suppressRingback);

        if (!groupId) {
            if (!suppressAlerts) {
                alert('Unable to start group call.');
            }
            return false;
        }

        let stream = existingStream;
        try {
            if (!stream) {
                stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            }
            localAudioStream = stream;
        } catch {
            if (!suppressAlerts) {
                alert('Microphone permission denied. Cannot start call.');
            }
            return false;
        }

        try {
            const res = await fetch('start_group_call.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    group_id: groupId,
                    suppress_message: suppressMessage ? 1 : 0
                })
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                if (!suppressAlerts) {
                    alert(data.error || 'Unable to start group call.');
                }
                if (ownsStream && stream) {
                    stream.getTracks().forEach(t => t.stop());
                    localAudioStream = null;
                }
                return false;
            }

            activeGroupCallId = data.call.id;
            activeGroupCallKey = groupKey;
            syncPromotedDirectCallContext({
                groupCallId: activeGroupCallId,
                groupKey: activeGroupCallKey
            });
            syncActiveGroupCallState(data.call || null, data.participants || []);

            // Immediately inject the group call message into the chat
            if (data.started_new && data.call_msg_id && String(selectedUser || '') === groupKey) {
                const gcMsgPayload = {
                    id: data.call_msg_id,
                    message: GROUP_CALL_MESSAGE_PREFIX + JSON.stringify({
                        call_id: data.call.id,
                        group_id: groupId,
                        status: 'ongoing',
                        started_at: data.call.created_at || new Date().toISOString(),
                        started_at_unix: data.call.created_at_unix || Math.floor(Date.now() / 1000),
                        ended_at: null
                    }),
                    created_at: data.call.created_at || new Date().toISOString(),
                    sender_id: currentUserId,
                    group_id: groupId,
                    self: 1,
                    sender_display_name: currentUserDisplayName || 'You',
                    sender_profile_pic: currentUserProfilePic || defaultProfilePic,
                    sender_online: 1
                };
                appendMessage(gcMsgPayload, false);
                lastId = Math.max(Number(lastId || 0), Number(data.call_msg_id));
            }

            // Show call UI
            if (keepExistingCallUi) {
                preserveCurrentCallUiForGroupCall(() => endGroupCall(true));
            } else if (preserveCallUi) {
                showOutgoingGroupCallUi(groupName, groupIcon, () => endGroupCall(true));
            } else {
                resetCallUI();
                showOutgoingGroupCallUi(groupName, groupIcon, () => endGroupCall(true));
            }

            if (data.participants) {
                renderCurrentGroupCallParticipants(data.participants);
                data.participants
                    .filter(p => p.invite_status === 'accepted' && String(p.user_id) !== String(currentUserId))
                    .forEach(p => { dialGroupCallParticipant(p.user_id); });
            }

            startCallSpeakingDetection(stream, currentUserId);
            groupCallPollInterval = setInterval(pollGroupCallState, 3000);

            if (suppressRingback) {
                stopAndResetAudio(ringbackAudio);
            } else {
                startRingbackAudio();
            }
            return true;
        } catch {
            if (!suppressAlerts) {
                alert('Network error starting group call.');
            }
            if (ownsStream && stream) {
                stream.getTracks().forEach(t => t.stop());
                localAudioStream = null;
            }
            return false;
        }
    }

    async function initiateAdhocGroupCall(participantUserIds, options = {}) {
        if (activeGroupCallId) return false;
        groupCallTeardownInProgress = false;

        const normalizedParticipantIds = Array.from(new Set(
            (Array.isArray(participantUserIds) ? participantUserIds : [])
                .map(id => parseInt(id, 10))
                .filter(id => id > 0 && String(id) !== String(currentUserId))
        ));
        if (!normalizedParticipantIds.length) {
            if (!options.suppressAlerts) {
                alert('Unable to start group call.');
            }
            return false;
        }

        const existingStream = options && options.existingStream ? options.existingStream : null;
        const ownsStream = !existingStream;
        const suppressAlerts = !!(options && options.suppressAlerts);
        const preferredGroupName = String((options && options.preferredGroupName) || '').trim();
        const preferredGroupIcon = String((options && options.preferredGroupIcon) || '').trim();
        const preserveCallUi = !!(options && options.preserveCallUi);
        const keepExistingCallUi = !!(options && options.keepExistingCallUi);
        const suppressRingback = !!(options && options.suppressRingback);

        let stream = existingStream;
        try {
            if (!stream) {
                stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            }
            localAudioStream = stream;
        } catch {
            if (!suppressAlerts) {
                alert('Microphone permission denied. Cannot start call.');
            }
            return false;
        }

        try {
            const res = await fetch('start_group_call.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    participant_ids: normalizedParticipantIds
                })
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                if (!suppressAlerts) {
                    alert(data.error || 'Unable to start group call.');
                }
                if (ownsStream && stream) {
                    stream.getTracks().forEach(t => t.stop());
                    localAudioStream = null;
                }
                return false;
            }

            activeGroupCallId = data.call.id;
            activeGroupCallKey = buildGroupCallUiKey(
                data.call && data.call.id ? data.call.id : activeGroupCallId,
                data.group ? data.group.id : '',
                data.call ? data.call.group_id : 0
            );
            syncPromotedDirectCallContext({
                groupCallId: activeGroupCallId,
                groupKey: activeGroupCallKey
            });
            syncActiveGroupCallState(data.call || null, data.participants || []);

            const groupName = getCallDisplayNameForChat(
                activeGroupCallKey,
                preferredGroupName || (data.group ? (data.group.display_name || 'Group call') : 'Group call')
            );
            const groupIcon = preferredGroupIcon || (data.group ? (data.group.profile_pic || DEFAULT_GROUP_CHAT_ICON) : DEFAULT_GROUP_CHAT_ICON);

            if (keepExistingCallUi) {
                preserveCurrentCallUiForGroupCall(() => endGroupCall(true));
            } else if (preserveCallUi) {
                showOutgoingGroupCallUi(groupName, groupIcon, () => endGroupCall(true));
            } else {
                resetCallUI();
                showOutgoingGroupCallUi(groupName, groupIcon, () => endGroupCall(true));
            }

            if (data.participants) {
                renderCurrentGroupCallParticipants(data.participants);
                data.participants
                    .filter(p => p.invite_status === 'accepted' && String(p.user_id) !== String(currentUserId))
                    .forEach(p => { dialGroupCallParticipant(p.user_id); });
            }

            startCallSpeakingDetection(stream, currentUserId);
            groupCallPollInterval = setInterval(pollGroupCallState, 3000);

            if (suppressRingback) {
                stopAndResetAudio(ringbackAudio);
            } else {
                startRingbackAudio();
            }
            return {
                callId: activeGroupCallId,
                groupKey: activeGroupCallKey,
                groupName,
                groupIcon
            };
        } catch {
            if (!suppressAlerts) {
                alert('Network error starting group call.');
            }
            if (ownsStream && stream) {
                stream.getTracks().forEach(t => t.stop());
                localAudioStream = null;
            }
            return false;
        }
    }

    async function acceptGroupCall(callId, groupKey, options = {}) {
        handledGroupCallIds.add(String(callId));
        pendingIncomingGroupCallId = null;
        groupCallTeardownInProgress = false;
        const existingStream = options && options.existingStream ? options.existingStream : null;
        const suppressAlerts = !!(options && options.suppressAlerts);
        const preferredGroupName = String((options && options.groupName) || '');
        const preferredGroupIcon = String((options && options.groupIcon) || '');
        const preserveCallUi = !!(options && options.preserveCallUi);
        const keepExistingCallUi = !!(options && options.keepExistingCallUi);
        try {
            const res = await fetch('update_group_call_participant.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ token, call_id: callId, action: 'accept' })
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                if (!suppressAlerts) {
                    alert(data.error || 'Unable to join group call.');
                }
                return false;
            }

            let stream = existingStream;
            try {
                if (!stream) {
                    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                }
                localAudioStream = stream;
            } catch {
                if (!suppressAlerts) {
                    alert('Microphone permission denied.');
                }
                return false;
            }

            activeGroupCallId = callId;
            activeGroupCallKey = groupKey;
            syncPromotedDirectCallContext({
                groupCallId: activeGroupCallId,
                groupKey: activeGroupCallKey
            });
            syncActiveGroupCallState(data.call || null, data.participants || []);

            const groupBio = String(data.group && data.group.bio ? data.group.bio : '').trim();
            if (groupKey && groupBio === CALL_ONLY_GROUP_DESCRIPTION) {
                callOnlyGroupIds.add(String(groupKey));
                const tempContactEl = getContactElement(groupKey);
                if (tempContactEl) {
                    tempContactEl.remove();
                }
            }

            const groupName = getCallDisplayNameForChat(
                groupKey,
                preferredGroupName || (data.group ? (data.group.display_name || 'Group') : (groupNamesMap[groupKey] || 'Group'))
            );
            const groupIcon = preferredGroupIcon || (data.group ? (data.group.profile_pic || 'images/default-group.svg') : (groupIconsMap[groupKey] || 'images/default-group.svg'));
            const promotedContext = getPromotedDirectCallContext(callId);
            const keepDirectPresentation = !!(
                keepExistingCallUi
                && promotedContext
                && shouldKeepPromotedDirectCallUi(Array.isArray(data.participants) ? data.participants : [])
            );

            if (!preserveCallUi) {
                resetCallUI();
            } else if (keepExistingCallUi) {
                preserveCurrentCallUiForGroupCall(() => endGroupCall(true));
            } else {
                clearPendingCallUiDismiss();
                hideInCallControls();
                applyCallUiMinimizedState(false);
                callUi.style.display = 'flex';
                if (leaveMessageBtn) leaveMessageBtn.style.display = 'none';
                if (callEndedControls) callEndedControls.style.display = 'none';
                if (callCloseBtn) callCloseBtn.style.display = 'none';
            }

            if (keepDirectPresentation) {
                applyPromotedDirectCallUi();
                callUi.style.display = 'flex';
                if (callConnectedFlag || activeGroupCallConnected) {
                    showInCallControlsBar();
                } else {
                    hideInCallControls();
                }
                document.getElementById('incoming-actions').style.display = 'none';
                endCallBtn.style.display = 'none';
                updateVideoToggleButtonState();
                updateCallMessageButtonState();

                const endActiveBtn = document.getElementById('end-call-active');
                if (endActiveBtn) endActiveBtn.onclick = () => endGroupCall(true);

                renderAdhocCallParticipants([String(promotedContext.otherUserId)]);
                setParticipantSpeaking(currentUserId, speakingParticipantIds.has(String(currentUserId)));
                startCallSpeakingDetection(stream, currentUserId);
                groupCallPollInterval = setInterval(pollGroupCallState, 3000);

                if (audioDevices.length === 0) { 
                    loadAudioDevices().then(() => {
                        populateAudioSelector();
                        setSpeakerMode('phone');
                    }); 
                } else {
                    setSpeakerMode('phone');
                }
                if (audioIcon) audioIcon.onclick = toggleAudioDropdown;
                bindMuteToggle();

                stopAndResetAudio(ringbackAudio);
                ringtoneAudio.pause();
                ringtoneAudio.currentTime = 0;
                return true;
            }

            document.getElementById('call-image').src = groupIcon;
            document.getElementById('call-image').style.borderRadius = '18px';
            callUsername.innerText = groupName;
            if (activeGroupCallConnected) {
                callStatus.innerText = 'Connected';
                startStopwatch(data.call ? data.call.created_at : null, data.call ? data.call.created_at_unix : null);
            } else {
                callStatus.innerText = 'Ringing...';
                stopStopwatch();
            }
            callUi.style.display = 'flex';
            if (activeGroupCallConnected) {
                showInCallControlsBar();
            } else {
                hideInCallControls();
            }
            document.getElementById('incoming-actions').style.display = 'none';
            endCallBtn.style.display = 'none';
            updateVideoToggleButtonState();
            updateCallMessageButtonState();

            const endActiveBtn = document.getElementById('end-call-active');
            if (endActiveBtn) endActiveBtn.onclick = () => endGroupCall(true);

            if (data.participants) {
                renderCurrentGroupCallParticipants(data.participants);
                data.participants
                    .filter(p => p.invite_status === 'accepted' && String(p.user_id) !== String(currentUserId))
                    .forEach(p => { dialGroupCallParticipant(p.user_id); });
            }
            startCallSpeakingDetection(stream, currentUserId);
            groupCallPollInterval = setInterval(pollGroupCallState, 3000);

            // Wire up in-call controls (mute, audio selector)
            if (audioDevices.length === 0) { 
                loadAudioDevices().then(() => {
                    populateAudioSelector();
                    setSpeakerMode('phone'); // Initialize to phone mode
                }); 
            } else {
                setSpeakerMode('phone'); // Initialize to phone mode
            }
            if (audioIcon) audioIcon.onclick = toggleAudioDropdown;
            bindMuteToggle();

            stopAndResetAudio(ringbackAudio);
            ringtoneAudio.pause();
            ringtoneAudio.currentTime = 0;
            return true;
        } catch {
            if (!suppressAlerts) {
                alert('Network error joining group call.');
            }
            return false;
        }
    }

    async function rejectGroupCall(callId) {
        handledGroupCallIds.add(String(callId));
        pendingIncomingGroupCallId = null;
        try {
            await fetch('update_group_call_participant.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ token, call_id: callId, action: 'reject' })
            });
        } catch {}
        ringtoneAudio.pause();
        ringtoneAudio.currentTime = 0;
        callUi.style.display = 'none';
    }

    async function endGroupCall(sendLeave = true, outcome = 'ended') {
        if (groupCallTeardownInProgress) {
            return;
        }
        groupCallTeardownInProgress = true;
        clearPrivateInviteCallTimeout();
        pendingIncomingGroupCallId = null;
        const endingCallId = activeGroupCallId;
        const endingGroupKey = activeGroupCallKey;
        const endingPrivateGroupCall = activeGroupCallIsPrivate;
        const directPromotionContext = getPromotedDirectCallContext(endingCallId);
        const shouldShowDirectLikeOutcomeScreen = !!(
            endingPrivateGroupCall
            || (directPromotionContext && !directPromotionContext.groupUiActivated)
        );
        const directLikeOutcomeContext = shouldShowDirectLikeOutcomeScreen
            ? getDirectLikeCallOutcomeContext(endingCallId)
            : null;
        const isCallerForHistory = !!(
            directPromotionContext
            && activeCallHistory
            && String(activeCallHistory.callerId) === String(currentUserId)
        );
        const callMessageId = directLikeOutcomeContext && directLikeOutcomeContext.callMessageId
            ? directLikeOutcomeContext.callMessageId
            : null;
        activeGroupCallId = null;
        activeGroupCallKey = null;
        clearActiveGroupCallState();
        clearPromotedDirectCallContext(endingCallId);
        hideInCallControls();
        if (audioDropdown) {
            audioDropdown.style.display = 'none';
        }

        if (sendLeave && endingCallId && endingCallId !== 'adhoc') {
            try {
                const participantAction = endingPrivateGroupCall ? 'end' : 'leave';
                const leaveRes = await fetch('update_group_call_participant.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ token, call_id: endingCallId, action: participantAction })
                });
                const leaveData = await leaveRes.json().catch(() => ({}));
                if (!leaveRes.ok || !leaveData.success) {
                    console.warn('Failed to update group call participant state.', {
                        action: participantAction,
                        callId: endingCallId,
                        status: leaveRes.status,
                        response: leaveData
                    });
                }
                const callTrulyEnded = leaveData.call && leaveData.call.status === 'ended';

                // Only update the message tile if the call is truly over for everyone
                if (callTrulyEnded && endingGroupKey && isGroupChatKey(String(endingGroupKey))) {
                    const groupId = parseInt(String(endingGroupKey).replace('group:', ''), 10);
                    if (isCallOnlyGroupKey(String(endingGroupKey))) {
                        fetch('delete_group.php', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ token, group_id: groupId })
                        }).then(() => {
                            const tempContactEl = getContactElement(endingGroupKey);
                            if (tempContactEl) {
                                tempContactEl.remove();
                            }
                        }).catch(() => {});
                    } else {
                        fetch('update_group_call_message.php', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ token, call_id: endingCallId, group_id: groupId })
                        }).then(r => r.json()).then(data => {
                            if (data.success) updateGroupCallMessageTile(endingCallId, 'ended');
                        }).catch(() => {});
                    }
                }
            } catch {}
        }

        if (directPromotionContext) {
            if (isCallerForHistory) {
                logCallHistoryEntry('ended');
            } else {
                activeCallHistory = null;
            }
        } else {
            activeCallHistory = null;
        }

        if (groupCallPollInterval) { clearInterval(groupCallPollInterval); groupCallPollInterval = null; }
        if (localAudioStream) { localAudioStream.getTracks().forEach(t => t.stop()); localAudioStream = null; }
        resetCallVideoState();
        teardownAllGroupCallPeers();
        document.getElementById('call-image').style.borderRadius = '50%';
        if (groupCallParticipantsEl) { groupCallParticipantsEl.innerHTML = ''; groupCallParticipantsEl.style.display = 'none'; }
        stopAndResetAudio(ringbackAudio);
        stopAndResetAudio(ringtoneAudio);
        flushPendingPeerRecovery();

        if (shouldShowDirectLikeOutcomeScreen) {
            restoreMobileContactsView();
            closeCallUI();
            const callImageEl = document.getElementById('call-image');
            if (callImageEl) {
                callImageEl.src = directLikeOutcomeContext && directLikeOutcomeContext.profilePic
                    ? directLikeOutcomeContext.profilePic
                    : defaultProfilePic;
                callImageEl.style.borderRadius = '50%';
            }
            showTransientDirectCallState(getDirectLikeCallOutcomeStatusText(outcome), {
                username: directLikeOutcomeContext && directLikeOutcomeContext.username
                    ? directLikeOutcomeContext.username
                    : '',
                durationMs: 2600,
                callMessageId
            });
            groupCallTeardownInProgress = false;
            return;
        }

        resetCallUI();
        restoreMobileContactsView();
        groupCallTeardownInProgress = false;
    }

    function updateGroupCallMessageTile(callId, newStatus) {
        // Find the message element in the chat and re-render its tile
        const msgEl = chatBox ? chatBox.querySelector(`.message[data-group-call-id="${callId}"]`) : null;
        if (!msgEl) return;
        const bubble = msgEl.querySelector('.message-bubble');
        if (!bubble) return;
        const tile = bubble.querySelector('.group-call-tile');
        if (!tile) return;
        // Clear the live timer
        const msgId = msgEl.dataset.id;
        if (msgId && groupCallTileTimers[msgId]) {
            clearInterval(groupCallTileTimers[msgId]);
            delete groupCallTileTimers[msgId];
        }
        // Re-render with ended status
        const newGcMsg = { call_id: callId, status: newStatus, ended_at: new Date().toISOString() };
        bubble.innerHTML = '';
        bubble.appendChild(buildGroupCallMessageNode(newGcMsg, msgEl));
    }

    async function pollGroupCalls() {
        try {
            const res = await fetch(`poll_group_calls.php?token=${encodeURIComponent(token)}&t=${Date.now()}`);
            const calls = await res.json().catch(() => []);
            if (!Array.isArray(calls)) return;
            const acceptBtn = document.getElementById('accept-call-btn');
            const incomingGroupCallVisible = !!(
                callUi.style.display === 'flex'
                && pendingIncomingGroupCallId
                && !activeGroupCallId
                && acceptBtn
                && acceptBtn.style.display !== 'none'
            );

            if (incomingGroupCallVisible) {
                const stillPending = calls.some(call => String(call.id) === String(pendingIncomingGroupCallId));
                if (!stillPending) {
                    pendingIncomingGroupCallId = null;
                    endGroupCall(false);
                }
                return;
            }

            if (activeGroupCallId || callUi.style.display === 'flex') return;
            const pending = calls.find(c => !handledGroupCallIds.has(String(c.id)));
            if (pending) showIncomingGroupCall(pending);
        } catch {}
    }
    pollGroupCalls();
    setInterval(pollGroupCalls, 3000);

    function showIncomingGroupCall(call) {
        const callId = call.id;
        const groupKey = call.group_key ? String(call.group_key) : `group:${call.group_id}`;
        if (handledGroupCallIds.has(String(callId))) return;
        if (activeGroupCallId || callUi.style.display === 'flex') return;

        handledGroupCallIds.add(String(callId));
        pendingIncomingGroupCallId = String(callId);

        const groupName = getCallDisplayNameForChat(groupKey, call.group_name || 'Group');
        const groupIcon = call.group_icon || 'images/default-group.svg';
        const initiatorName = getCallDisplayNameForUser(call.initiator_id, {
            displayName: call.initiator_display_name || `User ${call.initiator_id}`,
            username: '',
            isGroup: false
        }, { chatKey: groupKey });

        resetCallUI();
        document.getElementById('call-image').src = groupIcon;
        document.getElementById('call-image').style.borderRadius = '18px';
        callUsername.innerText = `Incoming call from ${initiatorName}...`;

        // Build "Also in the call" subtitle
        const others = Array.isArray(call.other_participants) ? call.other_participants : [];
        if (others.length > 0) {
            const names = others.slice(0, 3).map(p => getCallDisplayNameForUser(p.user_id, {
                displayName: p.display_name || `User ${p.user_id}`,
                username: '',
                isGroup: false
            }, { chatKey: groupKey }));
            const extra = others.length > 3 ? ` +${others.length - 3}` : '';
            callStatus.innerText = `Also in the call: ${names.join(', ')}${extra}`;
        } else {
            callStatus.innerText = `Calling ${groupName}`;
        }
        callUi.style.display = 'flex';
        document.getElementById('incoming-actions').style.display = 'flex';
        document.getElementById('accept-call-btn').style.display = 'inline-block';
        endCallBtn.style.display = 'inline-block';
        endCallBtn.style.backgroundColor = 'red';

        if (getAppSetting('callRingtone')) {
            ringtoneAudio.play().catch(() => {});
        }

        document.getElementById('accept-call-btn').onclick = () => acceptGroupCall(callId, groupKey);
        endCallBtn.onclick = () => rejectGroupCall(callId);
    }

    function setGroupSettingsStatusMessage(message, state = '') {
        if (!groupSettingsStatus) {
            return;
        }

        groupSettingsStatus.textContent = message;
        if (state) {
            groupSettingsStatus.dataset.state = state;
        } else {
            delete groupSettingsStatus.dataset.state;
        }
    }

    function resetGroupSettingsIconPreview() {
        if (groupSettingsIconObjectUrl) {
            URL.revokeObjectURL(groupSettingsIconObjectUrl);
            groupSettingsIconObjectUrl = '';
        }

        groupSettingsSelectedIconFile = null;
        groupSettingsClearIconPending = false;
        if (groupSettingsIconInput) {
            groupSettingsIconInput.value = '';
        }
    }

    function renderGroupSettingsMembersList(chatKey) {
        if (!groupSettingsMembersList) {
            return;
        }

        const normalizedUserId = String(chatKey || '');
        const members = Array.isArray(groupMembersMap[normalizedUserId]) ? groupMembersMap[normalizedUserId] : [];
        groupSettingsMembersList.innerHTML = '';

        if (!members.length) {
            const empty = document.createElement('div');
            empty.className = 'contact-info-member-empty';
            empty.textContent = 'No members loaded yet.';
            groupSettingsMembersList.appendChild(empty);
            return;
        }

        members.forEach(member => {
            const memberId = String(member.user_id || member.id || '');
            const row = document.createElement('div');
            row.className = 'group-settings-member-row';
            row.dataset.memberId = memberId;

            const main = document.createElement('div');
            main.className = 'group-settings-member-main';

            const image = document.createElement('img');
            image.src = member.profile_pic || userProfilePics[memberId] || defaultProfilePic;
            image.alt = member.display_name || member.username || `User ${memberId}`;

            const copy = document.createElement('div');
            copy.className = 'group-settings-member-copy';

            const name = document.createElement('div');
            name.className = 'group-settings-member-name';
            const memberDisplayName = getDisplayNameForUser(memberId, { 
                displayName: member.display_name, 
                username: member.username,
                isGroup: false 
            }, normalizedUserId);
            name.textContent = memberDisplayName;

            const meta = document.createElement('div');
            meta.className = 'group-settings-member-meta';
            const status = Number(member.online) === 1 ? 'Online' : 'Offline';
            meta.textContent = `${formatGroupRoleLabel(member.role || GROUP_ROLE_MEMBER)} | ${status}`;

            copy.appendChild(name);
            copy.appendChild(meta);
            main.appendChild(image);
            main.appendChild(copy);
            row.appendChild(main);

            if (String(member.role || '').toLowerCase() === GROUP_ROLE_OWNER) {
                const ownerBadge = document.createElement('span');
                ownerBadge.className = 'contact-info-member-meta';
                ownerBadge.textContent = 'Owner';
                row.appendChild(ownerBadge);
            } else {
                const select = document.createElement('select');
                select.className = 'group-settings-role-select';
                select.dataset.memberId = memberId;

                [
                    { value: GROUP_ROLE_MEMBER, label: 'Member' },
                    { value: GROUP_ROLE_ADMIN, label: 'Admin' }
                ].forEach(optionMeta => {
                    const option = document.createElement('option');
                    option.value = optionMeta.value;
                    option.textContent = optionMeta.label;
                    option.selected = normalizeGroupRole(member.role || GROUP_ROLE_MEMBER) === optionMeta.value;
                    select.appendChild(option);
                });

                select.addEventListener('change', async () => {
                    await updateGroupMemberRole(memberId, select.value);
                });
                row.appendChild(select);
            }

            groupSettingsMembersList.appendChild(row);
        });
    }

    function populateGroupSettingsModal(chatKey) {
        const normalizedUserId = String(chatKey || '');
        const meta = getContactMeta(normalizedUserId);
        if (!meta || !meta.isGroup) {
            return;
        }

        activeGroupSettingsChatKey = normalizedUserId;
        resetGroupSettingsIconPreview();

        if (groupSettingsModalTitle) {
            groupSettingsModalTitle.textContent = 'Group Settings';
        }
        if (groupSettingsModalSubtitle) {
            groupSettingsModalSubtitle.textContent = `Manage ${meta.displayName}, its permissions, and its admins.`;
        }
        if (groupSettingsIconPreview) {
            groupSettingsIconPreview.src = meta.profilePic || DEFAULT_GROUP_CHAT_ICON;
        }
        if (groupSettingsNameInput) {
            groupSettingsNameInput.value = meta.displayName || '';
        }
        if (groupSettingsDescriptionInput) {
            groupSettingsDescriptionInput.value = meta.bio || '';
        }
        if (groupSettingsSendPermission) {
            groupSettingsSendPermission.value = meta.sendPermission || GROUP_SEND_PERMISSION_ALL;
        }
        if (groupSettingsAddPermission) {
            groupSettingsAddPermission.value = meta.addMembersPermission || GROUP_ADD_PERMISSION_ADMINS;
        }
        const viewerIsOwner = isGroupOwnerMeta(meta);
        if (groupSettingsDeleteBtn) {
            groupSettingsDeleteBtn.hidden = !viewerIsOwner;
        }
        if (groupSettingsSendPermission) {
            groupSettingsSendPermission.disabled = !canManageGroupMeta(meta);
        }
        if (groupSettingsAddPermission) {
            groupSettingsAddPermission.disabled = !canManageGroupMeta(meta);
        }

        renderGroupSettingsMembersList(normalizedUserId);
        setGroupSettingsStatusMessage('Ready to save changes.');
    }

    function closeGroupSettingsModal() {
        activeGroupSettingsChatKey = '';
        resetGroupSettingsIconPreview();
        if (!groupSettingsModal) {
            return;
        }

        groupSettingsModal.classList.remove('open');
        groupSettingsModal.setAttribute('aria-hidden', 'true');
        
        // Reset z-index
        groupSettingsModal.style.zIndex = '';
    }

    let activeGroupMembersChatKey = '';

    async function openGroupMembersModal(chatKey = selectedUser) {
        console.log('=== openGroupMembersModal called ===');
        console.log('chatKey:', chatKey);
        const normalizedUserId = String(chatKey || '');
        console.log('normalizedUserId:', normalizedUserId);
        const meta = getContactMeta(normalizedUserId);
        console.log('meta:', meta);
        
        if (!meta || !meta.isGroup) {
            console.log('Not a group or no meta, returning');
            return;
        }

        activeGroupMembersChatKey = normalizedUserId;

        // Fetch members if needed
        if (!groupMembersMap[normalizedUserId] || !groupMembersMap[normalizedUserId].length) {
            console.log('Fetching group members...');
            await fetchGroupMembersForInfo(normalizedUserId, { silent: true });
        }

        // Update subtitle with group name
        if (groupMembersModalSubtitle) {
            groupMembersModalSubtitle.textContent = `List of all members in ${meta.displayName || 'this group'}`;
        }

        // Render members
        console.log('Rendering members modal list...');
        renderGroupMembersModalList(normalizedUserId);

        // Open modal
        if (groupMembersModal) {
            console.log('Opening group members modal...');
            bringOverlayToFront(groupMembersModal, 6);
            groupMembersModal.classList.add('open');
            groupMembersModal.setAttribute('aria-hidden', 'false');
        } else {
            console.error('groupMembersModal element not found!');
        }
    }

    function closeGroupMembersModal() {
        activeGroupMembersChatKey = '';
        if (!groupMembersModal) {
            return;
        }

        groupMembersModal.classList.remove('open');
        groupMembersModal.setAttribute('aria-hidden', 'true');
        resetOverlayZIndex(groupMembersModal);
    }
    
    // User Info Modal (for clicking on profile pictures)
    function openUserInfoModal(userId, options = {}) {
        if (!userInfoModal || !userInfoModalContent) return;
        
        const normalizedUserId = String(userId || '');
        if (!normalizedUserId || normalizedUserId === String(currentUserId)) {
            return; // Don't open for self
        }
        
        const meta = getContactMeta(normalizedUserId);
        if (!meta) return;

        const chatContextKey = String(options.chatContextKey || selectedUser || '').trim();
        userInfoModal.dataset.activeUser = normalizedUserId;
        userInfoModal.dataset.chatContextKey = chatContextKey;
        buildRightSidebarContent(normalizedUserId, userInfoModalContent, {
            isModal: true,
            forceStandalone: true,
            chatContextKey
        });
        bringOverlayToFront(userInfoModal, 4);
        userInfoModal.classList.add('open');
        userInfoModal.setAttribute('aria-hidden', 'false');
    }
    
    function closeUserInfoModal() {
        if (!userInfoModal) return;
        userInfoModal.classList.remove('open');
        userInfoModal.setAttribute('aria-hidden', 'true');
        userInfoModal.dataset.activeUser = '';
        userInfoModal.dataset.chatContextKey = '';
        resetOverlayZIndex(userInfoModal);
    }

    function renderGroupMembersModalList(chatKey) {
        if (!groupMembersModalList) return;
        
        groupMembersModalList.innerHTML = '';
        const members = groupMembersMap[String(chatKey)] || [];
        
        if (!members.length) {
            groupMembersModalList.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-secondary);">No members found</div>';
            return;
        }

        members.forEach(m => {
            const memberId = String(m.user_id || m.id || '');
            const row = document.createElement('div');
            row.className = 'group-chat-member-row';
            row.dataset.memberId = memberId;
            row.style.cssText = 'display:flex;align-items:center;gap:12px;padding:12px;border-bottom:1px solid var(--border-color);';
            
            // Profile picture
            const img = document.createElement('img');
            img.src = m.profile_pic || userProfilePics[memberId] || 'images/default-profile.png';
            img.style.cssText = 'width:40px;height:40px;border-radius:50%;object-fit:cover;flex-shrink:0;';
            
            // Name and status container
            const nameContainer = document.createElement('div');
            nameContainer.style.cssText = 'flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;';
            
            const name = document.createElement('div');
            name.style.cssText = 'font-size:0.95rem;font-weight:500;';
            const memberDisplayName = getDisplayNameForUser(memberId, { 
                displayName: m.display_name, 
                username: m.username,
                isGroup: false 
            }, String(chatKey || ''));
            name.textContent = memberDisplayName;
            
            // Online/offline status
            const statusDot = document.createElement('span');
            statusDot.className = 'rs-status-dot';
            statusDot.style.cssText = 'display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;';
            
            // Get online status from member data or contact meta
            const memberMeta = getContactMeta(memberId);
            const isOnline = Number(m.online) === 1 || !!(memberMeta && memberMeta.isOnline);
            applyPresenceIndicatorState(statusDot, isOnline, false);
            
            const statusText = document.createElement('span');
            statusText.style.cssText = 'font-size:0.85rem;color:var(--text-secondary);display:flex;align-items:center;';
            statusText.appendChild(statusDot);
            statusText.appendChild(document.createTextNode(`${formatGroupRoleLabel(m.role || GROUP_ROLE_MEMBER)} | ${isOnline ? 'Online' : 'Offline'}`));
            
            nameContainer.appendChild(name);
            nameContainer.appendChild(statusText);
            
            row.appendChild(img);
            row.appendChild(nameContainer);
            
            // Determine if viewer can moderate based on viewer's role in the group
            const meta = getContactMeta(chatKey);
            const viewerRole = meta && meta.viewerRole ? String(meta.viewerRole).toLowerCase() : '';
            const viewerIsAdmin = viewerRole === 'admin' || viewerRole === 'owner';
            
            // Add three dots button if viewer can moderate or change role
            const canModerate = viewerIsAdmin || !!(Number(m.viewer_can_moderate) || m.viewer_can_moderate === true || m.viewer_can_moderate === '1');
            const canChangeRole = viewerIsAdmin || !!(Number(m.viewer_can_change_role) || m.viewer_can_change_role === true || m.viewer_can_change_role === '1');
            
            if (canModerate || canChangeRole) {
                const dotsBtn = document.createElement('button');
                dotsBtn.className = 'member-card-actions-btn';
                dotsBtn.style.cssText = 'background:none;border:none;color:var(--text-secondary);cursor:pointer;padding:8px;font-size:1.1rem;';
                dotsBtn.setAttribute('aria-label', 'Member actions');
                dotsBtn.innerHTML = '<i class="fas fa-ellipsis-vertical"></i>';
                dotsBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    openMemberCtxMenu(
                        e,
                        chatKey,
                        memberId,
                        m.display_name || m.username || `User ${memberId}`,
                        !!Number(m.is_muted || 0) || isFutureDateValue(m.muted_until),
                        canModerate,
                        canChangeRole,
                        m.role || 'member',
                        !!Number(m.viewer_is_owner || 0)
                    );
                });
                row.appendChild(dotsBtn);
            }
            
            groupMembersModalList.appendChild(row);
        });
    }

    function canManageGroupMeta(meta) {
        return !!(meta && meta.isGroup && (meta.canManageGroup || isGroupOwnerMeta(meta)));
    }

    async function openGroupSettingsModalFor(chatKey = selectedUser) {
        const normalizedUserId = String(chatKey || '');
        const meta = getContactMeta(normalizedUserId);
        if (!canManageGroupMeta(meta)) {
            return;
        }

        await fetchGroupMembersForInfo(normalizedUserId, { silent: false });
        if (!canManageGroupMeta(getContactMeta(normalizedUserId))) {
            return;
        }
        populateGroupSettingsModal(normalizedUserId);
        if (groupSettingsModal) {
            bringOverlayToFront(groupSettingsModal, 6);
            groupSettingsModal.classList.add('open');
            groupSettingsModal.setAttribute('aria-hidden', 'false');
        }
    }

    async function updateGroupMemberRole(memberId, role) {
        const chatKey = String(activeGroupSettingsChatKey || selectedUser || '');
        if (!chatKey || !memberId) {
            return;
        }

        setGroupSettingsStatusMessage('Updating member role...');
        try {
            const res = await fetch('update_group_member_role.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    group_id: getGroupIdFromChatKey(chatKey),
                    member_id: Number(memberId),
                    role
                })
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                throw new Error(data.error || 'Unable to update that member role.');
            }

            applyGroupDetailsPayload(chatKey, data);
            populateGroupSettingsModal(chatKey);
            setGroupSettingsStatusMessage('Member role updated.', 'success');
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
        } catch (error) {
            setGroupSettingsStatusMessage(error instanceof Error ? error.message : 'Unable to update that member role.', 'error');
        }
    }

    async function saveActiveGroupSettings() {
        const chatKey = String(activeGroupSettingsChatKey || '');
        if (!chatKey) {
            return;
        }

        const nextName = groupSettingsNameInput ? groupSettingsNameInput.value.trim() : '';
        if (nextName === '') {
            setGroupSettingsStatusMessage('Group chat name cannot be empty.', 'error');
            if (groupSettingsNameInput) {
                groupSettingsNameInput.focus();
            }
            return;
        }

        const originalLabel = groupSettingsSaveBtn ? groupSettingsSaveBtn.textContent : 'Save Changes';
        if (groupSettingsSaveBtn) {
            groupSettingsSaveBtn.disabled = true;
            groupSettingsSaveBtn.textContent = 'Saving...';
        }

        try {
            const formData = new FormData();
            formData.append('token', token);
            formData.append('group_id', String(getGroupIdFromChatKey(chatKey)));
            formData.append('name', nextName);
            formData.append('description', groupSettingsDescriptionInput ? groupSettingsDescriptionInput.value.trim() : '');
            formData.append('send_permission', groupSettingsSendPermission ? groupSettingsSendPermission.value : GROUP_SEND_PERMISSION_ALL);
            formData.append('add_members_permission', groupSettingsAddPermission ? groupSettingsAddPermission.value : GROUP_ADD_PERMISSION_ADMINS);
            formData.append('clear_icon', groupSettingsClearIconPending ? '1' : '0');
            if (groupSettingsSelectedIconFile) {
                formData.append('icon', groupSettingsSelectedIconFile);
            }

            const res = await fetch('update_group_settings.php', {
                method: 'POST',
                body: formData
            });
            const rawText = await res.text();
            let data = {};
            try {
                data = rawText ? JSON.parse(rawText) : {};
            } catch {
                data = { error: rawText.trim() || 'Unable to save group settings right now.' };
            }
            if (!res.ok || !data.success) {
                throw new Error(data.error || 'Unable to save group settings right now.');
            }

            applyGroupDetailsPayload(chatKey, data);
            populateGroupSettingsModal(chatKey);
            setGroupSettingsStatusMessage('Group settings saved.', 'success');
            sortContactsList();
        } catch (error) {
            setGroupSettingsStatusMessage(error instanceof Error ? error.message : 'Unable to save group settings right now.', 'error');
        } finally {
            if (groupSettingsSaveBtn) {
                groupSettingsSaveBtn.disabled = false;
                groupSettingsSaveBtn.textContent = originalLabel;
            }
        }
    }

    async function deleteActiveGroupChat() {
        const chatKey = String(activeGroupSettingsChatKey || '');
        if (!chatKey) {
            return;
        }

        const res = await fetch('delete_group.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                token,
                group_id: getGroupIdFromChatKey(chatKey)
            })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) {
            throw new Error(data.error || 'Unable to delete that group right now.');
        }

        if (activeGroupCallKey && String(activeGroupCallKey) === chatKey) {
            await endGroupCall(false);
        }

        const contactEl = getContactElement(chatKey);
        if (contactEl) {
            contactEl.remove();
        }

        delete groupNamesMap[chatKey];
        delete groupDescriptionsMap[chatKey];
        delete groupIconsMap[chatKey];
        delete groupCreatedAtMap[chatKey];
        delete groupMemberCountMap[chatKey];
        delete groupOnlineMap[chatKey];
        delete groupMembersMap[chatKey];

        closeGroupSettingsModal();
        hideContactInfoPanel();

        if (String(selectedUser || '') === chatKey) {
            selectedUser = null;
            chatBox.innerHTML = '';
            updateHeaderContact(null);
        }

        sortContactsList();
        refreshUnreadBadges();
    }

    function updateContactInfoPanel(userId) {
        const meta = getContactMeta(userId);
        setContactInfoButtonState(!!meta);

        if (!meta) {
            hideContactInfoPanel();
            return;
        }

        const normalizedUserId = String(userId || '');
        const isTyping = isChatCurrentlyTyping(normalizedUserId, meta);
        const isPresenceOnline = meta.isGroup ? (!!meta.isOnline || isTyping) : !!meta.isOnline;

        if (contactInfoAvatar) {
            contactInfoAvatar.src = meta.profilePic || defaultProfilePic;
            contactInfoAvatar.alt = meta.displayName || meta.username || 'Contact';
        }

        if (contactInfoStatusDot) {
            applyPresenceIndicatorState(contactInfoStatusDot, isPresenceOnline, isTyping);
        }

        if (contactInfoDisplayName) {
            contactInfoDisplayName.textContent = getDisplayNameForUser(userId, meta, normalizedUserId) || 'Unknown user';
        }

        if (contactInfoUsername) {
            const secondaryText = getInfoSurfaceSecondaryText(normalizedUserId, meta);
            contactInfoUsername.textContent = secondaryText;
            contactInfoUsername.hidden = secondaryText === '';
        }

        if (contactInfoBioLabel) {
            contactInfoBioLabel.textContent = meta.isGroup ? 'Description' : 'Bio';
        }

        if (contactInfoBio) {
            contactInfoBio.textContent = meta.bio && meta.bio.trim() !== ''
                ? meta.bio
                : (meta.isGroup ? 'No description yet.' : 'No bio yet.');
        }

        if (contactInfoMemberSinceLabel) {
            contactInfoMemberSinceLabel.textContent = meta.isGroup ? 'Created' : 'Member since';
        }

        if (contactInfoMemberSince) {
            contactInfoMemberSince.textContent = formatMemberSinceDate(meta.createdAt);
        }

        if (contactInfoGroupActions) {
            contactInfoGroupActions.hidden = !(meta.isGroup && (meta.canManageGroup || isGroupOwnerMeta(meta)));
        }

        if (meta.isGroup) {
            if (contactInfoMembersToggle) {
                contactInfoMembersToggle.dataset.chatKey = String(userId || '');
            }
            renderGroupMembersList(userId);
            if (!groupMembersMap[String(userId || '')] || !groupMembersMap[String(userId || '')].length) {
                fetchGroupMembersForInfo(userId, { silent: true });
            }
        } else {
            if (contactInfoMembersToggle) {
                contactInfoMembersToggle.dataset.chatKey = '';
            }
            renderGroupMembersList('');
        }

        if (contactInfoGroupNotifSection) {
            contactInfoGroupNotifSection.hidden = !meta.isGroup;
            if (meta.isGroup) updateGroupNotifUI(String(userId));
        }

        // Refresh right sidebar if open
        if (rightSidebar && rightSidebar.classList.contains('is-open')) {
            buildRightSidebarContent(userId);
        }
    }

    // ── Group notification settings ───────────────────────────────────────────
    const contactInfoGroupNotifSection = document.getElementById('contactInfoGroupNotifSection');
    const contactInfoGroupNotifLabel   = document.getElementById('contactInfoGroupNotifLabel');
    const groupNotifToggle             = document.getElementById('groupNotifToggle');

    function syncStoredNotificationPrefsToServer() {
        if (notificationPrefsBootstrapped) {
            return;
        }
        notificationPrefsBootstrapped = true;

        document.querySelectorAll('.contact').forEach(contactEl => {
            const chatKey = String(contactEl.dataset.id || '');
            const storedPref = getStoredChatNotificationPref(chatKey);
            if (!storedPref || storedPref !== 'mention') {
                return;
            }

            const serverPref = normalizeChatNotificationMode(contactEl.dataset.notificationMode || 'all');
            if (storedPref === serverPref) {
                setContactNotificationMode(chatKey, storedPref);
                return;
            }

            setContactNotificationMode(chatKey, storedPref);
            persistChatNotificationPref(chatKey, storedPref).catch(error => {
                console.warn('Unable to sync stored notification preference.', error);
            });
        });
    }

    const QUILLTALK_AI_MENTION_NAME = 'QuillTalk AI';

    function messageHasMentionToken(message, candidate) {
        const normalizedCandidate = String(candidate || '').trim();
        if (!normalizedCandidate) {
            return false;
        }

        const escapedCandidate = normalizedCandidate.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const mentionRegex = new RegExp(`(^|[^\\p{L}\\p{N}_])@${escapedCandidate}(?=[\\s,!?.,;:'"\\])}]|$)`, 'iu');
        return mentionRegex.test(String(message || ''));
    }

    function messageMentionsQuillTalkAi(message) {
        return messageHasMentionToken(message, QUILLTALK_AI_MENTION_NAME)
            || messageHasMentionToken(message, 'QuillTalkAI');
    }

    function normalizeQuillTalkAiPromptText(message) {
        const raw = String(message || '');
        const mentionPattern = /(^|[^\p{L}\p{N}_])@(?:QuillTalk\s+AI|QuillTalkAI)(?=[\s,!?.,;:'"\])}]|$)/giu;
        const cleaned = raw.replace(mentionPattern, '$1').replace(/\s+/g, ' ').trim();
        return cleaned || raw.replace(/\s+/g, ' ').trim();
    }

    function messageMentionsCurrentUser(message, chatKey = selectedUser) {
        const normalizedChatKey = String(chatKey || '').trim();
        const displayName = String(currentUserDisplayName || '').trim();
        const username = String(currentUsername || '').trim();
        const chatNickname = getViewerChatNickname(normalizedChatKey);

        return messageHasMentionToken(message, 'everyone')
            || (isGroupChatKey(normalizedChatKey) && messageHasMentionToken(message, 'here'))
            || (!!chatNickname && messageHasMentionToken(message, chatNickname))
            || (!!displayName && messageHasMentionToken(message, displayName))
            || (!!username && messageHasMentionToken(message, username));
    }

    function shouldHighlightMentionRow(msg, chatKey, options = {}) {
        if (!msg || options.isSelfMessage) {
            return false;
        }

        if (options.attachmentMessage || options.callEvent || options.groupCallMsg || options.pollMessage) {
            return false;
        }

        const rawMessage = String(msg.message || '').trim();
        if (!rawMessage) {
            return false;
        }

        return messageMentionsCurrentUser(rawMessage, chatKey);
    }

    function updateGroupNotifUI(groupKey) {
        if (!contactInfoGroupNotifSection || !groupNotifToggle || !contactInfoGroupNotifLabel) return;
        const pref = getGroupNotifPref(groupKey);
        groupNotifToggle.checked = pref === 'all';
        contactInfoGroupNotifLabel.textContent = pref === 'all'
            ? 'Receive notifications for all messages in this group chat'
            : 'Receive notifications from this group chat only when your name is mentioned';
    }

    if (groupNotifToggle) {
        groupNotifToggle.addEventListener('change', async () => {
            const groupKey = selectedUser && isGroupChatKey(String(selectedUser)) ? String(selectedUser) : null;
            if (!groupKey) return;
            const pref = groupNotifToggle.checked ? 'all' : 'mention';
            await setGroupNotifPref(groupKey, pref);
            updateGroupNotifUI(groupKey);
            refreshUnreadBadges();
        });
    }

    // Group notification section visibility is handled inside updateContactInfoPanel below

    const COMPOSER_COMMANDS = Object.freeze([
        {
            command: '/nick',
            insertText: '/nick ',
            description: 'Set your chat nickname'
        },
        {
            command: '/nick clear',
            insertText: '/nick clear',
            description: 'Clear your chat nickname'
        },
        {
            command: '/gif',
            insertText: '/gif',
            description: 'Open the GIF picker'
        },
        {
            command: '/ai',
            insertText: '/ai ',
            description: 'Get a reply everyone in the chat can see'
        },
        {
            command: '/ai imagine',
            insertText: '/ai imagine ',
            description: 'Create an image everyone in the chat can see'
        },
        {
            command: '/ai private',
            insertText: '/ai private ',
            description: 'Get a reply only you can see'
        },
        {
            command: '/ai private imagine',
            insertText: '/ai private imagine ',
            description: 'Create an image only you can see'
        }
    ]);
    const COMMAND_HIGHLIGHT_MATCH_ORDER = COMPOSER_COMMANDS.slice().sort((a, b) => b.command.length - a.command.length);

    function escapeRegExp(value) {
        return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    function rangesOverlap(left, right) {
        return !!left && !!right && left.start < right.end && right.start < left.end;
    }

    function keepNonOverlappingMatches(matches) {
        const accepted = [];
        const ordered = Array.isArray(matches)
            ? matches.slice().sort((a, b) => a.start - b.start || (b.end - b.start) - (a.end - a.start))
            : [];

        ordered.forEach(match => {
            if (!match || typeof match.start !== 'number' || typeof match.end !== 'number' || match.end <= match.start) {
                return;
            }
            if (accepted.some(existing => rangesOverlap(existing, match))) {
                return;
            }
            accepted.push(match);
        });

        return accepted.sort((a, b) => a.start - b.start);
    }

    function collectUrlMatches(text) {
        const raw = String(text || '');
        const matches = [];
        const urlPattern = /(\b(https?:\/\/|www\.)[^\s<]+[^\s<.,;:!?'")\]])/gi;
        let match;

        while ((match = urlPattern.exec(raw)) !== null) {
            matches.push({
                start: match.index,
                end: match.index + match[0].length,
                kind: 'url'
            });
            if (!match[0].length) {
                urlPattern.lastIndex += 1;
            }
        }

        return matches;
    }

    function buildLinkifiedSegmentHtml(urlText) {
        const rawUrl = String(urlText || '');
        const href = rawUrl.toLowerCase().startsWith('www.')
            ? `https://${rawUrl}`
            : rawUrl;
        return `<a href="${qtEscapeHtml(href)}" target="_blank" rel="noopener noreferrer" style="color: var(--text-primary); text-decoration: underline;">${qtEscapeHtml(rawUrl)}</a>`;
    }

    function collectCommandHighlightMatches(text, blockedRanges = [], options = {}) {
        const raw = String(text || '');
        if (!raw.includes('/')) {
            return [];
        }

        const leadingWhitespaceLength = (raw.match(/^\s*/) || [''])[0].length;
        const commandText = raw.slice(leadingWhitespaceLength);
        if (!commandText.startsWith('/')) {
            return [];
        }

        const lowerCommandText = commandText.toLowerCase();
        for (const definition of COMMAND_HIGHLIGHT_MATCH_ORDER) {
            const normalizedCommand = definition.command.toLowerCase();
            if (!lowerCommandText.startsWith(normalizedCommand)) {
                continue;
            }

            const boundaryChar = commandText.charAt(definition.command.length);
            if (boundaryChar && !/\s/.test(boundaryChar)) {
                continue;
            }

            const match = {
                start: leadingWhitespaceLength,
                end: leadingWhitespaceLength + definition.command.length,
                kind: 'token'
            };

            if (blockedRanges.some(range => rangesOverlap(range, match))) {
                return [];
            }

            return [match];
        }

        if (!options.allowCommandPrefix) {
            return [];
        }

        const partialMatch = commandText.match(/^\/[^\s]*(?:\s+[^\s]*){0,2}/);
        const partialCommand = partialMatch ? partialMatch[0].toLowerCase() : '';
        if (
            !partialCommand
            || !COMPOSER_COMMANDS.some(definition => definition.command.toLowerCase().startsWith(partialCommand))
        ) {
            return [];
        }

        const partialRange = {
            start: leadingWhitespaceLength,
            end: leadingWhitespaceLength + partialCommand.length,
            kind: 'token'
        };

        if (blockedRanges.some(range => rangesOverlap(range, partialRange))) {
            return [];
        }

        return [partialRange];
    }

    function collectMentionHighlightMatches(text, chatKey, blockedRanges = []) {
        const raw = String(text || '');
        const names = buildMentionNames(chatKey);
        if (!raw.includes('@') || !names.length) {
            return [];
        }

        const matches = [];
        names.forEach(name => {
            const regex = new RegExp(`(^|[^\\p{L}\\p{N}_])@(${escapeRegExp(name)})(?=[\\s,!?.;:'"\\])}]|$)`, 'giu');
            let match;

            while ((match = regex.exec(raw)) !== null) {
                const prefixLength = (match[1] || '').length;
                const start = match.index + prefixLength;
                const end = start + 1 + String(match[2] || '').length;
                const candidate = { start, end, kind: 'token' };

                if (!blockedRanges.some(range => rangesOverlap(range, candidate))) {
                    matches.push(candidate);
                }

                if (!match[0].length) {
                    regex.lastIndex += 1;
                }
            }
        });

        return keepNonOverlappingMatches(matches);
    }

    function renderHighlightedTextHtml(text, chatKey, options = {}) {
        const raw = String(text || '');
        if (!raw) {
            return '';
        }

        const shouldLinkify = options.linkify !== false;
        const urlMatches = shouldLinkify ? collectUrlMatches(raw) : [];
        const tokenMatches = keepNonOverlappingMatches(
            collectCommandHighlightMatches(raw, urlMatches, options)
                .concat(collectMentionHighlightMatches(raw, chatKey, urlMatches))
        );

        const segments = urlMatches
            .concat(tokenMatches)
            .sort((a, b) => a.start - b.start || (b.end - b.start) - (a.end - a.start));

        let cursor = 0;
        let html = '';
        segments.forEach(segment => {
            if (!segment || segment.start < cursor) {
                return;
            }

            html += qtEscapeHtml(raw.slice(cursor, segment.start));
            const segmentText = raw.slice(segment.start, segment.end);
            html += segment.kind === 'url'
                ? buildLinkifiedSegmentHtml(segmentText)
                : `<span class="token-highlight">${qtEscapeHtml(segmentText)}</span>`;
            cursor = segment.end;
        });
        html += qtEscapeHtml(raw.slice(cursor));

        return html;
    }

    function renderAiCommandIndicatorHtml(text) {
        const raw = String(text || '');
        if (!raw) {
            return '';
        }

        const commandMatch = raw.match(/\/ai\b/iu);
        if (!commandMatch || typeof commandMatch.index !== 'number') {
            return qtEscapeHtml(raw);
        }

        const start = commandMatch.index;
        const end = start + commandMatch[0].length;
        return (
            qtEscapeHtml(raw.slice(0, start))
            + `<span class="token-highlight">${qtEscapeHtml(raw.slice(start, end))}</span>`
            + qtEscapeHtml(raw.slice(end))
        );
    }

    function syncComposerHighlightOverlayScroll() {
        if (!messageInput || !composerHighlightOverlayContent) {
            return;
        }

        composerHighlightOverlayContent.style.transform = `translate(${-1 * (messageInput.scrollLeft || 0)}px, ${-1 * (messageInput.scrollTop || 0)}px)`;
    }

    function syncComposerTextareaHeight() {
        if (!messageInput) {
            return;
        }

        const computedStyle = window.getComputedStyle(messageInput);
        const minHeight = parseFloat(computedStyle.minHeight) || 40;
        const maxHeight = parseFloat(computedStyle.maxHeight) || 120;

        messageInput.style.height = 'auto';
        messageInput.style.height = `${Math.min(Math.max(messageInput.scrollHeight, minHeight), maxHeight)}px`;

        if (!String(messageInput.value || '')) {
            messageInput.scrollTop = 0;
        }
    }

    function updateComposerHighlightOverlay() {
        if (!messageInput) {
            return;
        }

        syncComposerTextareaHeight();

        if (!composerHighlightOverlay || !composerHighlightOverlayContent || !messageInput.parentElement) {
            return;
        }

        const rawValue = String(messageInput.value || '');
        if (!rawValue) {
            composerHighlightOverlay.hidden = true;
            composerHighlightOverlayContent.innerHTML = '';
            messageInput.parentElement.classList.remove('is-highlighting');
            return;
        }

        const chatKey = String(selectedUser || '');
        const highlightedHtml = renderHighlightedTextHtml(rawValue, chatKey, {
            linkify: false,
            allowCommandPrefix: true
        });
        const hasHighlights = highlightedHtml.includes('token-highlight');

        if (!hasHighlights) {
            composerHighlightOverlay.hidden = true;
            composerHighlightOverlayContent.innerHTML = '';
            messageInput.parentElement.classList.remove('is-highlighting');
            return;
        }

        composerHighlightOverlayContent.innerHTML = highlightedHtml;
        composerHighlightOverlay.hidden = false;
        messageInput.parentElement.classList.add('is-highlighting');
        syncComposerHighlightOverlayScroll();
    }

    // ── / Command picker ─────────────────────────────────────────────────────
    const commandPicker = document.getElementById('commandAutocomplete');
    let commandActive = false;
    let commandActiveIndex = -1;
    let commandReplaceStart = -1;
    let commandReplaceEnd = -1;

    if (commandPicker && messageInput && messageInput.parentElement && commandPicker.parentElement !== messageInput.parentElement) {
        messageInput.parentElement.appendChild(commandPicker);
    }

    // ── @ Mention picker ──────────────────────────────────────────────────────
    const mentionPicker = document.getElementById('mentionPicker');
    let mentionActive = false;
    let mentionStartPos = -1;
    let mentionActiveMemberIndex = -1;

    if (mentionPicker && messageInput && messageInput.parentElement && mentionPicker.parentElement !== messageInput.parentElement) {
        messageInput.parentElement.appendChild(mentionPicker);
    }

    function createEveryoneMentionCandidate() {
        return {
            user_id: 'everyone',
            display_name: 'everyone',
            username: '',
            profile_pic: '',
            mention_value: 'everyone',
            isEveryone: true
        };
    }

    function createHereMentionCandidate() {
        return {
            user_id: 'here',
            display_name: 'here',
            username: '',
            profile_pic: '',
            mention_value: 'here',
            isHere: true
        };
    }

    function createQuillTalkAiMentionCandidate() {
        return {
            user_id: '__qt_quilltalk_ai__',
            display_name: QUILLTALK_AI_MENTION_NAME,
            username: '',
            profile_pic: DEFAULT_AI_PROFILE_PIC,
            mention_value: QUILLTALK_AI_MENTION_NAME,
            isQuillTalkAi: true,
            searchable_names: [
                QUILLTALK_AI_MENTION_NAME,
                'QuillTalkAI',
                'QuillTalk',
                'AI'
            ]
        };
    }

    function buildMentionCandidateFromMember(member, chatKey) {
        const memberId = String(member.user_id || member.id || '');
        const mentionValue = getChatNicknameForUser(chatKey, memberId)
            || String(member.display_name || '').trim()
            || String(member.username || '').trim()
            || memberId;

        return {
            user_id: memberId,
            display_name: mentionValue,
            username: String(member.username || ''),
            profile_pic: member.profile_pic || userProfilePics[memberId] || defaultProfilePic,
            mention_value: mentionValue,
            searchable_names: Array.from(new Set([
                mentionValue,
                String(member.display_name || '').trim(),
                String(member.username || '').trim()
            ].filter(Boolean)))
        };
    }

    function buildMentionNames(chatKey) {
        const normalizedChatKey = String(chatKey || '');
        const names = [];

        if (isGroupChatKey(normalizedChatKey)) {
            names.push(QUILLTALK_AI_MENTION_NAME);
            names.push('everyone');
            names.push('here');
            const members = groupMembersMap[normalizedChatKey] || [];
            members.forEach(m => {
                const memberId = String(m.user_id || m.id || '');
                if (memberId) names.push(getChatNicknameForUser(normalizedChatKey, memberId));
                if (m.display_name) names.push(m.display_name);
                if (m.username && m.username !== m.display_name) names.push(m.username);
            });
        } else {
            names.push(QUILLTALK_AI_MENTION_NAME);
            const meta = getContactMeta(normalizedChatKey);
            if (meta && !meta.isGroup) {
                const directChatNickname = getChatNicknameForUser(normalizedChatKey, normalizedChatKey);
                if (directChatNickname) names.push(directChatNickname);
                if (meta.displayName) names.push(meta.displayName);
                if (meta.username && meta.username !== meta.displayName) names.push(meta.username);
            }
            const viewerChatNickname = getViewerChatNickname(normalizedChatKey);
            if (viewerChatNickname) names.push(viewerChatNickname);
            if (currentUserDisplayName) names.push(currentUserDisplayName);
            if (currentUsername && currentUsername !== currentUserDisplayName) names.push(currentUsername);
        }

        return Array.from(new Set(names.filter(Boolean))).sort((a, b) => b.length - a.length);
    }

    function applyMentionHighlights(text, chatKey) {
        return renderHighlightedTextHtml(text, chatKey, {
            linkify: true,
            allowCommandPrefix: true
        });
    }

    function closeCommandPicker() {
        commandActive = false;
        commandActiveIndex = -1;
        commandReplaceStart = -1;
        commandReplaceEnd = -1;
        if (commandPicker) {
            commandPicker.style.display = 'none';
        }
    }

    function getCommandAutocompleteContext() {
        if (!messageInput || !selectedUser) {
            return null;
        }

        const value = String(messageInput.value || '');
        const cursorPos = typeof messageInput.selectionStart === 'number'
            ? messageInput.selectionStart
            : value.length;
        const beforeCursor = value.slice(0, cursorPos);
        const leadingWhitespaceLength = (beforeCursor.match(/^\s*/) || [''])[0].length;
        const commandText = beforeCursor.slice(leadingWhitespaceLength);

        if (!commandText.startsWith('/') || /\s{2,}/.test(commandText)) {
            return null;
        }

        const parts = commandText.trim().split(/\s+/).filter(Boolean);
        if (parts.length > 3) {
            return null;
        }

        return {
            value,
            query: commandText.toLowerCase(),
            replaceStart: leadingWhitespaceLength,
            replaceEnd: cursorPos
        };
    }

    function getCommandCandidates(query) {
        const normalizedQuery = String(query || '').toLowerCase();
        return COMPOSER_COMMANDS.filter(definition => (
            !normalizedQuery || definition.command.toLowerCase().startsWith(normalizedQuery)
        ));
    }

    function renderCommandPicker(candidates) {
        if (!commandPicker) {
            return;
        }

        commandPicker.innerHTML = '';
        if (!candidates.length) {
            commandPicker.style.display = 'none';
            return;
        }

        candidates.forEach((candidate, index) => {
            const item = document.createElement('div');
            item.className = 'command-item';
            item.dataset.index = String(index);
            item.setAttribute('role', 'option');
            item.innerHTML = `
                <div class="command-item-icon"><i class="fa-solid fa-terminal" aria-hidden="true"></i></div>
                <div>
                    <div class="command-item-name">${qtEscapeHtml(candidate.command)}</div>
                    <div class="command-item-description">${qtEscapeHtml(candidate.description)}</div>
                </div>
            `;
            item.addEventListener('mousedown', (event) => {
                event.preventDefault();
                insertCommand(candidate);
            });
            commandPicker.appendChild(item);
        });

        commandPicker.style.display = 'block';
        commandActiveIndex = -1;
    }

    function insertCommand(candidate) {
        if (!messageInput || !candidate) {
            return;
        }

        const value = String(messageInput.value || '');
        const before = value.slice(0, Math.max(0, commandReplaceStart));
        const after = value.slice(Math.max(0, commandReplaceEnd));
        const nextValue = before + candidate.insertText + after;
        const nextCursor = before.length + candidate.insertText.length;

        messageInput.value = nextValue;
        messageInput.focus();
        messageInput.setSelectionRange(nextCursor, nextCursor);
        closeCommandPicker();
        rememberMessageSelection();
        messageInput.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function handleCommandInput() {
        const context = getCommandAutocompleteContext();
        if (!context) {
            closeCommandPicker();
            return;
        }

        const candidates = getCommandCandidates(context.query);
        if (!candidates.length) {
            closeCommandPicker();
            return;
        }

        commandActive = true;
        commandReplaceStart = context.replaceStart;
        commandReplaceEnd = context.replaceEnd;
        renderCommandPicker(candidates);
    }

    function handleCommandKeydown(event) {
        if (!commandActive || !commandPicker || commandPicker.style.display === 'none') {
            return false;
        }

        const items = commandPicker.querySelectorAll('.command-item');
        if (!items.length) {
            return false;
        }

        if (event.key === 'ArrowDown') {
            event.preventDefault();
            commandActiveIndex = Math.min(commandActiveIndex + 1, items.length - 1);
            items.forEach((element, index) => element.classList.toggle('active', index === commandActiveIndex));
            return true;
        }

        if (event.key === 'ArrowUp') {
            event.preventDefault();
            commandActiveIndex = Math.max(commandActiveIndex - 1, 0);
            items.forEach((element, index) => element.classList.toggle('active', index === commandActiveIndex));
            return true;
        }

        if (event.key === 'Enter' || event.key === 'Tab') {
            const selectedItem = commandActiveIndex >= 0 ? items[commandActiveIndex] : items[0];
            if (selectedItem) {
                event.preventDefault();
                selectedItem.dispatchEvent(new MouseEvent('mousedown'));
                return true;
            }
        }

        if (event.key === 'Escape') {
            closeCommandPicker();
            return true;
        }

        return false;
    }


    function getMentionCandidates(query) {
        const normalizedChatKey = String(selectedUser || '');
        if (!normalizedChatKey) return [];

        let members = [];
        if (isGroupChatKey(normalizedChatKey)) {
            members = groupMembersMap[normalizedChatKey] || [];
        } else {
            const meta = getContactMeta(normalizedChatKey);
            if (!meta || meta.isGroup) {
                return [];
            }

            members = [{
                user_id: normalizedChatKey,
                display_name: meta.displayName || '',
                username: meta.username || '',
                profile_pic: meta.profilePic || defaultProfilePic
            }];
        }

        const normalizedQuery = String(query || '').trim().toLowerCase();
        let candidates = members
            .map(member => buildMentionCandidateFromMember(member, normalizedChatKey))
            .filter(candidate => {
                return !normalizedQuery || candidate.searchable_names.some(name => String(name || '').toLowerCase().includes(normalizedQuery));
            });
        const aiCandidate = createQuillTalkAiMentionCandidate();
        if (!normalizedQuery || aiCandidate.searchable_names.some(name => String(name || '').toLowerCase().includes(normalizedQuery))) {
            candidates = [aiCandidate].concat(candidates);
        }

        if (isGroupChatKey(normalizedChatKey)) {
            const specials = [];
            if (!normalizedQuery || 'here'.includes(normalizedQuery)) {
                specials.push(createHereMentionCandidate());
            }
            if (!normalizedQuery || 'everyone'.includes(normalizedQuery)) {
                specials.push(createEveryoneMentionCandidate());
            }
            candidates = specials.concat(candidates);
        }

        const seen = new Set();
        return candidates.filter(candidate => {
            const key = String(candidate.mention_value || candidate.user_id || '').toLowerCase();
            if (!key || seen.has(key)) {
                return false;
            }
            seen.add(key);
            return true;
        }).slice(0, 8);
    }

    function renderMentionPicker(candidates) {
        if (!mentionPicker) return;
        mentionPicker.innerHTML = '';
        if (!candidates.length) { mentionPicker.style.display = 'none'; return; }
        candidates.forEach((m, i) => {
            const item = document.createElement('div');
            item.className = 'mention-item';
            item.dataset.index = i;
            item.setAttribute('role', 'option');
            const avatar = (m.isEveryone || m.isHere)
                ? document.createElement('div')
                : document.createElement('img');
            if (m.isEveryone || m.isHere) {
                avatar.className = 'mention-item-avatar';
                avatar.innerHTML = m.isHere
                    ? '<i class="fa-solid fa-bolt" aria-hidden="true"></i>'
                    : '<i class="fa-solid fa-users" aria-hidden="true"></i>';
            } else {
                avatar.src = m.profile_pic || userProfilePics[String(m.user_id)] || defaultProfilePic;
                avatar.alt = m.display_name || m.username || '';
            }
            const copy = document.createElement('div');
            const nameEl = document.createElement('div');
            nameEl.className = 'mention-item-name';
            nameEl.textContent = m.display_name || m.username || `User ${m.user_id}`;
            const unameEl = document.createElement('div');
            unameEl.className = 'mention-item-username';
            unameEl.textContent = m.isHere
                ? 'Notify online members'
                : (m.isEveryone
                    ? 'Notify all members'
                    : (m.isQuillTalkAi
                        ? 'AI assistant'
                        : (m.username ? `@${m.username}` : '')));
            copy.appendChild(nameEl);
            copy.appendChild(unameEl);
            item.appendChild(avatar);
            item.appendChild(copy);
            item.addEventListener('mousedown', (e) => {
                e.preventDefault();
                insertMention(m);
            });
            mentionPicker.appendChild(item);
        });
        mentionPicker.style.display = 'block';
        mentionActiveMemberIndex = -1;
    }

    function insertMention(member) {
        if (!messageInput) return;
        const val = messageInput.value;
        const before = val.slice(0, mentionStartPos);
        const after = val.slice(messageInput.selectionStart);
        const mentionValue = member && member.mention_value
            ? member.mention_value
            : (member && member.isEveryone)
                ? 'everyone'
                : (member.display_name || member.username || member.user_id);
        const mention = `@${mentionValue}`;
        messageInput.value = before + mention + '\u00A0' + after;
        // Move cursor after the mention
        const newPos = before.length + mention.length + 1;
        messageInput.setSelectionRange(newPos, newPos);
        closeMentionPicker();
        messageInput.focus();
        rememberMessageSelection();
        messageInput.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function closeMentionPicker() {
        mentionActive = false;
        mentionStartPos = -1;
        mentionActiveMemberIndex = -1;
        if (mentionPicker) mentionPicker.style.display = 'none';
    }

    function handleMentionInput() {
        if (!messageInput || !selectedUser) { closeMentionPicker(); return; }
        const val = messageInput.value;
        const pos = messageInput.selectionStart;
        // Find the @ before the cursor
        let atPos = -1;
        for (let i = pos - 1; i >= 0; i--) {
            if (val[i] === '@') { atPos = i; break; }
            if (val[i] === ' ' || val[i] === '\n') break;
        }
        if (atPos === -1) { closeMentionPicker(); return; }
        mentionActive = true;
        mentionStartPos = atPos;
        const query = val.slice(atPos + 1, pos);
        const candidates = getMentionCandidates(query);
        renderMentionPicker(candidates);
    }

    function handleMentionKeydown(event) {
        if (!mentionActive || !mentionPicker || mentionPicker.style.display === 'none') return false;
        const items = mentionPicker.querySelectorAll('.mention-item');
        if (!items.length) return false;
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            mentionActiveMemberIndex = Math.min(mentionActiveMemberIndex + 1, items.length - 1);
            items.forEach((el, i) => el.classList.toggle('active', i === mentionActiveMemberIndex));
            return true;
        }
        if (event.key === 'ArrowUp') {
            event.preventDefault();
            mentionActiveMemberIndex = Math.max(mentionActiveMemberIndex - 1, 0);
            items.forEach((el, i) => el.classList.toggle('active', i === mentionActiveMemberIndex));
            return true;
        }
        if (event.key === 'Enter' || event.key === 'Tab') {
            if (mentionActiveMemberIndex >= 0 && items[mentionActiveMemberIndex]) {
                event.preventDefault();
                items[mentionActiveMemberIndex].dispatchEvent(new MouseEvent('mousedown'));
                return true;
            }
        }
        if (event.key === 'Escape') { closeMentionPicker(); return true; }
        return false;
    }

    document.addEventListener('click', (event) => {
        if (commandPicker && !commandPicker.contains(event.target) && event.target !== messageInput) {
            closeCommandPicker();
        }
    });

    // Close mention picker when clicking outside
    document.addEventListener('click', (e) => {
        if (mentionPicker && !mentionPicker.contains(e.target) && e.target !== messageInput) {
            closeMentionPicker();
        }
    });

    // ── : Emoji picker ──────────────────────────────────────────────────────
    const emojiPicker = document.getElementById('emojiAutocomplete');
    let emojiActive = false;
    let emojiStartPos = -1;
    let emojiEndPos = -1;
    let emojiActiveIndex = -1;

    if (emojiPicker && messageInput && messageInput.parentElement && emojiPicker.parentElement !== messageInput.parentElement) {
        messageInput.parentElement.appendChild(emojiPicker);
    }
    if (emojiPicker) {
        bindEmojiHoverTooltipDelegation(emojiPicker);
    }

    window.addEventListener('quilltalk:emojis-loaded', () => {
        refreshRenderedMessageEmojiTooltips();
        if (!emojiPickerGrid || !emojiPickerGrid.classList.contains('active')) {
            return;
        }
        renderEmojiPickerTabs();
        renderEmojiPickerGrid(activeEmojiCategory);
    });

    // Load recent emojis from localStorage
    function loadRecentEmojis() {
        loadEmojiUsageStats();
        try {
            const stored = localStorage.getItem('quilltalk.recentEmojis');
            recentEmojis = stored ? JSON.parse(stored) : [];
        } catch (e) {
            recentEmojis = [];
        }
    }

    // Save recent emoji
    function saveRecentEmoji(emoji) {
        recordEmojiUsage(emoji);
        recentEmojis = recentEmojis.filter(e => e !== emoji);
        recentEmojis.unshift(emoji);
        recentEmojis = recentEmojis.slice(0, 20); // Keep only 20 most recent
        try {
            localStorage.setItem('quilltalk.recentEmojis', JSON.stringify(recentEmojis));
        } catch (e) {
            console.error('Failed to save recent emoji:', e);
        }
    }

    function isEmojiSubsequenceMatch(query, target) {
        if (!query || !target) {
            return false;
        }

        let queryIndex = 0;
        for (let i = 0; i < target.length && queryIndex < query.length; i++) {
            if (target[i] === query[queryIndex]) {
                queryIndex += 1;
            }
        }
        return queryIndex === query.length;
    }

    function scoreEmojiTerm(term, query) {
        if (!term || !query) {
            return -1;
        }

        if (term === query) {
            return 1200;
        }

        if (term.startsWith(query)) {
            return 1000 - Math.min(120, term.length - query.length);
        }

        const words = term.split(' ');
        const wordPrefixIndex = words.findIndex(word => word.startsWith(query));
        if (wordPrefixIndex !== -1) {
            return 900 - (wordPrefixIndex * 20);
        }

        const compactTerm = term.replace(/\s+/g, '');
        const compactQuery = query.replace(/\s+/g, '');
        if (compactTerm && compactTerm.startsWith(compactQuery)) {
            return 860 - Math.min(100, compactTerm.length - compactQuery.length);
        }

        const includesIndex = term.indexOf(query);
        if (includesIndex !== -1) {
            return 760 - Math.min(180, includesIndex * 8);
        }

        if (compactTerm && compactQuery && compactTerm.includes(compactQuery)) {
            return 700 - Math.min(160, compactTerm.indexOf(compactQuery) * 8);
        }

        if (compactTerm && compactQuery && isEmojiSubsequenceMatch(compactQuery, compactTerm)) {
            return 560 - Math.min(120, compactTerm.length - compactQuery.length);
        }

        return -1;
    }

    function scoreEmojiCandidate(emoji, query) {
        let bestScore = -1;

        (emoji.normalizedShortcodes || []).forEach(term => {
            const score = scoreEmojiTerm(term, query);
            if (score >= 0) {
                bestScore = Math.max(bestScore, score + 260);
            }
        });

        const labelScore = scoreEmojiTerm(emoji.normalizedLabel, query);
        if (labelScore >= 0) {
            bestScore = Math.max(bestScore, labelScore + 160);
        }

        (emoji.normalizedTags || []).forEach(term => {
            const score = scoreEmojiTerm(term, query);
            if (score >= 0) {
                bestScore = Math.max(bestScore, score + 80);
            }
        });

        return bestScore;
    }

    function getEmojiCandidates(query) {
        const normalizedQuery = normalizeEmojiSearchValue(query);
        if (!normalizedQuery) {
            return recentEmojis.slice(0, 8).map(emoji => {
                const data = emojiByValue.get(emoji);
                return data || { emoji, label: '', shortcodes: [] };
            }).filter(e => e.emoji);
        }

        return emojiData
            .map(emoji => ({ emoji, score: scoreEmojiCandidate(emoji, normalizedQuery) }))
            .filter(entry => entry.score >= 0)
            .sort((a, b) => b.score - a.score || a.emoji.order - b.emoji.order)
            .slice(0, 8)
            .map(entry => entry.emoji);
    }

    function findEmojiTokenAtCursor(value, cursor) {
        const safeValue = String(value || '');
        const safeCursor = Math.max(0, Math.min(safeValue.length, Number.isFinite(cursor) ? cursor : safeValue.length));
        const beforeCursor = safeValue.slice(0, safeCursor);
        const exactMatch = beforeCursor.match(/(^|[\s(\[{])(:[a-zA-Z0-9_+-]+(?: +[a-zA-Z0-9_+-]+)*:)$/);
        if (exactMatch && exactMatch[2]) {
            return {
                start: beforeCursor.length - exactMatch[2].length,
                end: safeCursor,
                query: exactMatch[2].slice(1, -1),
                isComplete: true
            };
        }

        const partialMatch = beforeCursor.match(/(^|[\s(\[{])(:(?:[a-zA-Z0-9_+-]+(?: +[a-zA-Z0-9_+-]*)*)?)$/);
        if (!partialMatch || !partialMatch[2]) {
            return null;
        }

        return {
            start: beforeCursor.length - partialMatch[2].length,
            end: safeCursor,
            query: partialMatch[2].slice(1),
            isComplete: false
        };
    }

    function findExactEmojiByQuery(query) {
        const normalizedQuery = normalizeEmojiSearchValue(query);
        if (!normalizedQuery) {
            return null;
        }

        const shortcodeMatch = emojiByShortcode.get(normalizedQuery);
        if (shortcodeMatch) {
            return shortcodeMatch;
        }

        return emojiData.find(emoji => (
            emoji
            && (
                emoji.normalizedLabel === normalizedQuery
                || (Array.isArray(emoji.normalizedShortcodes) && emoji.normalizedShortcodes.includes(normalizedQuery))
            )
        )) || null;
    }

    function replaceEmojiRange(startPos, endPos, emojiObj) {
        if (!messageInput || !emojiObj || !emojiObj.emoji) return;
        const value = messageInput.value || '';
        const safeStart = Math.max(0, Math.min(value.length, startPos));
        const safeEnd = Math.max(safeStart, Math.min(value.length, endPos));
        const nextValue = value.slice(0, safeStart) + emojiObj.emoji + value.slice(safeEnd);
        const nextCursor = safeStart + emojiObj.emoji.length;

        messageInput.value = nextValue;
        messageInput.focus();
        messageInput.setSelectionRange(nextCursor, nextCursor);
        saveRecentEmoji(emojiObj.emoji);
        closeEmojiPicker();
        rememberMessageSelection();
        messageInput.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function renderEmojiPicker(candidates) {
        if (!emojiPicker) return;
        emojiPicker.innerHTML = '';
        if (!candidates.length) { emojiPicker.style.display = 'none'; return; }
        
        candidates.forEach((emoji, i) => {
            const item = document.createElement('div');
            item.className = 'emoji-item';
            item.dataset.index = i;
            item.setAttribute('role', 'option');
            bindEmojiHoverTooltip(item, emoji);
            
            const icon = document.createElement('div');
            icon.className = 'emoji-item-icon';
            const iconImageUrl = getEmojiImageUrl(emoji);
            if (iconImageUrl) {
                const image = document.createElement('img');
                image.src = iconImageUrl;
                image.alt = emoji.label || emoji.emoji;
                icon.appendChild(image);
            } else {
                icon.textContent = emoji.emoji;
            }
            
            const copy = document.createElement('div');
            const nameEl = document.createElement('div');
            nameEl.className = 'emoji-item-name';
            nameEl.textContent = emoji.label || emoji.emoji;
            
            const shortcodeEl = document.createElement('div');
            shortcodeEl.className = 'emoji-item-shortcode';
            shortcodeEl.textContent = emoji.shortcodes && emoji.shortcodes.length > 0 
                ? `:${emoji.shortcodes[0]}:` 
                : '';
            
            copy.appendChild(nameEl);
            copy.appendChild(shortcodeEl);
            item.appendChild(icon);
            item.appendChild(copy);
            
            item.addEventListener('mousedown', (e) => {
                e.preventDefault();
                insertEmoji(emoji);
            });
            
            emojiPicker.appendChild(item);
        });
        
        emojiPicker.style.display = 'block';
        emojiActiveIndex = -1;
    }

    function insertEmoji(emojiObj) {
        if (!messageInput) return;
        const replaceEnd = emojiEndPos >= emojiStartPos ? emojiEndPos : messageInput.selectionStart;
        replaceEmojiRange(emojiStartPos, replaceEnd, emojiObj);
    }

    function closeEmojiPicker() {
        emojiActive = false;
        emojiStartPos = -1;
        emojiEndPos = -1;
        emojiActiveIndex = -1;
        if (emojiPicker) emojiPicker.style.display = 'none';
    }

    function handleEmojiInput() {
        if (!messageInput) { closeEmojiPicker(); return; }
        const val = messageInput.value || '';
        const pos = typeof messageInput.selectionStart === 'number' ? messageInput.selectionStart : val.length;
        const token = findEmojiTokenAtCursor(val, pos);
        if (!token) { closeEmojiPicker(); return; }

        if (token.isComplete) {
            const exactEmoji = findExactEmojiByQuery(token.query);
            if (exactEmoji) {
                replaceEmojiRange(token.start, token.end, exactEmoji);
                return;
            }
            closeEmojiPicker();
            return;
        }

        emojiActive = true;
        emojiStartPos = token.start;
        emojiEndPos = token.end;
        const candidates = getEmojiCandidates(token.query);
        renderEmojiPicker(candidates);
    }

    function handleEmojiKeydown(event) {
        if (!emojiActive || !emojiPicker || emojiPicker.style.display === 'none') return false;
        const items = emojiPicker.querySelectorAll('.emoji-item');
        if (!items.length) return false;
        
        if (event.key === 'ArrowDown') {
            event.preventDefault();
            emojiActiveIndex = Math.min(emojiActiveIndex + 1, items.length - 1);
            items.forEach((el, i) => el.classList.toggle('active', i === emojiActiveIndex));
            return true;
        }
        
        if (event.key === 'ArrowUp') {
            event.preventDefault();
            emojiActiveIndex = Math.max(emojiActiveIndex - 1, 0);
            items.forEach((el, i) => el.classList.toggle('active', i === emojiActiveIndex));
            return true;
        }
        
        if (event.key === 'Enter' || event.key === 'Tab') {
            if (emojiActiveIndex >= 0 && items[emojiActiveIndex]) {
                event.preventDefault();
                items[emojiActiveIndex].dispatchEvent(new MouseEvent('mousedown'));
                return true;
            }
        }
        
        if (event.key === 'Escape') { closeEmojiPicker(); return true; }
        return false;
    }

    // Close emoji picker when clicking outside
    document.addEventListener('click', (e) => {
        if (emojiPicker && !emojiPicker.contains(e.target) && e.target !== messageInput) {
            closeEmojiPicker();
        }
    });

    // Replace :shortcode: with emoji before sending
    function replaceShortcodesWithEmoji(text) {
        if (!text) return text;
        
        let result = text;
        const shortcodeRegex = /:([a-zA-Z0-9_+-]+(?: +[a-zA-Z0-9_+-]+)*):/g;
        
        result = result.replace(shortcodeRegex, (match, shortcode) => {
            const emoji = findExactEmojiByQuery(shortcode);
            return emoji ? emoji.emoji : match;
        });
        
        return result;
    }

    function getConversationBlockState(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId || isGroupChatKey(normalizedUserId)) {
            return {
                viewerHasBlocked: false,
                blockedViewer: false,
                eitherBlocked: false
            };
        }
        return {
            viewerHasBlocked: isBlockedUser(normalizedUserId),
            blockedViewer: hasBlockedCurrentUser(normalizedUserId),
            eitherBlocked: isConversationBlocked(normalizedUserId)
        };
    }

    function updateCallButtonState(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        const meta = normalizedUserId ? getContactMeta(normalizedUserId) : null;
        const isGroup = !!(meta && meta.isGroup);
        const isAiChat = !!(meta && meta.isAiChat);
        const isMutedInGroup = isGroup && meta && meta.viewerIsMuted;
        const isAvailable = !!normalizedUserId
            && !isAiChat
            && !isMutedInGroup
            && (isGroup || !isConversationBlocked(normalizedUserId));
        const displayName = meta ? meta.displayName : 'user';
        const title = !normalizedUserId
            ? 'Start call'
            : isMutedInGroup
                ? 'You cannot start a call while you are in timeout.'
                : (isGroup
                    ? `Call ${displayName}`
                    : (isAvailable ? `Call ${displayName}` : `Calling ${displayName} is unavailable`));

        [startCallBtnDesktop, startCallBtnMobile].forEach(button => {
            if (!button) {
                return;
            }

            button.classList.toggle('icon-disabled', !isAvailable);
            button.setAttribute('aria-disabled', isAvailable ? 'false' : 'true');
            button.title = title;
        });

        // Video call button — same availability as audio call
        [startVideoCallBtnDesktop, startVideoCallBtnMobile].forEach(button => {
            if (!button) return;
            button.classList.toggle('icon-disabled', !isAvailable);
            button.setAttribute('aria-disabled', isAvailable ? 'false' : 'true');
            button.title = !normalizedUserId ? 'Start video call'
                : isMutedInGroup ? 'You cannot start a call while you are in timeout.'
                : isAvailable ? `Video call ${displayName}` : `Video calling ${displayName} is unavailable`;
        });
    }

    function updateChatSearchButtonState(userId) {
        const ok = !!userId;
        [chatSearchBtn, chatSearchBtnMobile].forEach(button => {
            if (!button) {
                return;
            }
            button.classList.toggle('icon-disabled', !ok);
            button.disabled = !ok;
            button.title = ok ? 'Search messages' : 'Select a chat first';
        });
    }

    // -- Mobile header overflow collapse ──────────────────────────────────────
    const headerOverflowWrap = document.getElementById('headerOverflowWrap');
    const headerOverflowBtn  = document.getElementById('headerOverflowBtn');
    const headerOverflowMenu = document.getElementById('headerOverflowMenu');
    const chatHeaderInfo     = document.querySelector('.chat-header-info');
    const chatHeader         = document.querySelector('.chat-header');

    // Map of mobile button id → { label, icon class, danger }

function updateHeaderOverflow() {
        if (window.innerWidth > 768) {
            if (headerOverflowMenu) {
                headerOverflowMenu.style.display = 'none';
            }
            if (headerOverflowWrap) {
                headerOverflowWrap.style.display = 'none';
            }
            return;
        }

        // On mobile: block, search, add-members ALWAYS go in the ... menu
        var _collapsible = [
            { id: 'add-members-btn-mobile',  label: 'Add Members', icon: 'fa-solid fa-user-plus',        danger: false },
            { id: 'block-user-btn-mobile',   label: 'Block User',  icon: 'fa-solid fa-circle-xmark',     danger: true  },
            { id: 'chatSearchBtnMobile',     label: 'Search',      icon: 'fa-solid fa-magnifying-glass', danger: false },
        ];

        var _wrap = document.getElementById('headerOverflowWrap');
        var _menu = document.getElementById('headerOverflowMenu');
        if (!_wrap || !_menu) return;

        // Mobile now routes these actions through the fullscreen right sidebar.
        _collapsible.forEach(function(btn) {
            var el = document.getElementById(btn.id);
            if (!el) return;
            el.style.display = 'none';
        });

        _menu.innerHTML = '';
        _menu.style.display = 'none';
        _wrap.style.display = 'none';
    }

    if (headerOverflowBtn) {
        headerOverflowBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const isOpen = headerOverflowMenu.style.display !== 'none';
            headerOverflowMenu.style.display = isOpen ? 'none' : 'block';
        });
    }

    document.addEventListener('click', (e) => {
        if (headerOverflowMenu && headerOverflowWrap && !headerOverflowWrap.contains(e.target)) {
            headerOverflowMenu.style.display = 'none';
        }
    });

    window.addEventListener('resize', updateHeaderOverflow);
    // Run after initial render — use rAF to ensure layout is complete
    requestAnimationFrame(() => setTimeout(updateHeaderOverflow, 50));

    function updateBlockButtonState(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        const meta = normalizedUserId ? getContactMeta(normalizedUserId) : null;
        const isGroup = !!(meta && meta.isGroup);
        const isAvailable = !!normalizedUserId && !isGroup;
        const blocked = isAvailable && isBlockedUser(normalizedUserId);
        const displayName = meta ? meta.displayName : 'user';

        [blockUserBtn, blockUserBtnMobile].forEach(button => {
            if (!button) {
                return;
            }

            button.disabled = !isAvailable;
            button.classList.toggle('icon-disabled', !isAvailable);
            button.classList.toggle('is-blocked', blocked);
            button.setAttribute('aria-pressed', blocked ? 'true' : 'false');
            button.setAttribute('aria-label', !normalizedUserId
                ? 'Block user'
                : (isGroup
                    ? 'Group chats cannot be blocked'
                    : (blocked ? `${displayName} is blocked` : `Block ${displayName}`)));
            button.title = !normalizedUserId
                ? 'Block user'
                : (isGroup
                    ? 'Group chats cannot be blocked'
                    : (blocked ? `${displayName} is blocked` : `Block ${displayName}`));
        });
    }

    function stopBlockedComposerCountdown() {
        if (blockedComposerCountdownId) {
            clearTimeout(blockedComposerCountdownId);
            blockedComposerCountdownId = 0;
        }
    }

    function scheduleBlockedComposerCountdown(userId) {
        stopBlockedComposerCountdown();
        if (!userId || String(userId) !== String(selectedUser)) {
            return;
        }

        blockedComposerCountdownId = window.setTimeout(() => {
            blockedComposerCountdownId = 0;
            if (selectedUser && String(selectedUser) === String(userId)) {
                updateBlockedChatUi(userId);
            }
        }, 1000);
    }

    function updateBlockedChatUi(userId = selectedUser) {
        const normalizedUserId = userId ? String(userId) : '';
        const meta = normalizedUserId ? getContactMeta(normalizedUserId) : null;
        const isGroup = !!(meta && meta.isGroup);

        // Don't show any notice if no conversation is selected
        if (!normalizedUserId || !selectedUser) {
            stopBlockedComposerCountdown();
            if (chatForm) chatForm.style.display = '';
            if (blockedComposerNotice) blockedComposerNotice.hidden = true;
            if (attachmentPreviewRow) attachmentPreviewRow.hidden = false;
            return;
        }

        const blockState = isGroup
            ? { viewerHasBlocked: false, blockedViewer: false, eitherBlocked: false }
            : getConversationBlockState(normalizedUserId);
        const blocked = blockState.eitherBlocked;

        // Check group mute
        const isMutedInGroup = isGroup && meta && meta.viewerIsMuted;
        const canSend = isGroup ? !!(meta && meta.canSend) : true;
        const groupSendBlocked = isGroup && !canSend && !isMutedInGroup;

        const showNotice = blocked || isMutedInGroup || groupSendBlocked;

        let noticeText = '';
        let showUnblock = false;
        if (blocked) {
            noticeText = blockState.viewerHasBlocked
                ? 'You cannot send messages to users you have blocked.'
                : 'You cannot send messages to users who have blocked you.';
            showUnblock = blockState.viewerHasBlocked;
        } else if (isMutedInGroup) {
            const mutedUntilMs = parseServerDateTimeMs(meta.viewerMutedUntil);
            const timeLeftText = mutedUntilMs > Date.now()
                ? formatDurationParts(mutedUntilMs - Date.now())
                : '0s';
            noticeText = `You cannot send messages right now, as you are in timeout. Time left: ${timeLeftText}`;
        } else if (groupSendBlocked) {
            noticeText = 'Only admins can send messages in this group right now.';
        }

        if (chatForm) chatForm.style.display = showNotice ? 'none' : '';
        if (attachmentPreviewRow) attachmentPreviewRow.hidden = showNotice;

        if (blockedComposerNotice) {
            blockedComposerNotice.hidden = !showNotice;
            const textEl = document.getElementById('composerBlockedText');
            if (textEl) textEl.textContent = noticeText;
        }

        if (unblockUserLink) unblockUserLink.hidden = !showUnblock;

        stopBlockedComposerCountdown();
        if (showNotice) {
            hideEmojiPicker();
            clearPendingAttachment(true);
            clearLocalTyping(true);
            hideTypingIndicator();
            if (messageInput && typeof messageInput.blur === 'function') messageInput.blur();
            if (isMutedInGroup) {
                scheduleBlockedComposerCountdown(normalizedUserId);
            }
        }
    }

    function getBlockedMessageError(userId) {
        if (isBlockedUser(userId)) {
            return 'You cannot send messages to users you have blocked.';
        }

        if (hasBlockedCurrentUser(userId)) {
            return 'You cannot send messages to users who have blocked you.';
        }

        return 'You cannot send messages in this chat.';
    }

    function getBlockedCallError(userId) {
        if (isGroupChatKey(String(userId || ''))) {
            return 'Unable to call this group.';
        }

        if (isBlockedUser(userId)) {
            return 'You cannot call users you have blocked.';
        }

        if (hasBlockedCurrentUser(userId)) {
            return 'You cannot call users who have blocked you.';
        }

        return 'This call is unavailable.';
    }

    async function persistBlockRelationship(userId, action) {
        const normalizedUserId = userId ? String(userId) : '';
        if (!normalizedUserId || !['block', 'unblock'].includes(action)) {
            throw new Error('Invalid block request');
        }

        const res = await fetch('block_user.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                token,
                target_user_id: normalizedUserId,
                action
            })
        });
        const data = await res.json().catch(() => ({}));

        if (!res.ok || !data.success) {
            throw new Error(data.error || 'Unable to update block state');
        }

        setContactBlockState(normalizedUserId, {
            viewerHasBlocked: !!(data.relationship && data.relationship.viewer_has_blocked),
            blockedViewer: !!(data.relationship && data.relationship.blocked_viewer)
        });

        return data;
    }

    // ── Right sidebar ──────────────────────────────────────────────────────────
    let showingMembersForGroup = null; // Track if members are being shown

    // Event delegation for right sidebar buttons
    if (rightSidebarContent) {
        rightSidebarContent.addEventListener('click', (event) => {
            const actionButton = event.target.closest('.rs-action-btn');
            if (actionButton) {
                event.stopPropagation();
            }
        });
    }

    function createContactActionButton(item, className = 'rs-action-btn') {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = className;
        if (item && item.danger) {
            button.classList.add('danger');
        }
        if (item && item.rotateIconOnHover) {
            button.classList.add('has-rotating-icon');
        }
        button.setAttribute('role', 'menuitem');

        let leadingNode = null;
        if (item && item.iconText) {
            leadingNode = document.createElement('span');
            leadingNode.className = 'contact-action-leading-text';
            leadingNode.textContent = item.iconText;
        } else {
            leadingNode = document.createElement('i');
            leadingNode.className = item && item.iconClass ? item.iconClass : 'fa-solid fa-circle';
            leadingNode.setAttribute('aria-hidden', 'true');
        }

        const labelNode = document.createElement('span');
        labelNode.textContent = item && item.label ? item.label : 'Action';

        button.appendChild(leadingNode);
        button.appendChild(labelNode);
        return button;
    }

    function buildAdditionalChatOptionItems(userId, { chatContextKey = '' } = {}) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId) {
            return [];
        }

        const meta = getContactMeta(normalizedUserId);
        if (!meta) {
            return [];
        }

        const options = [];
        const resolvedChatContextKey = String(
            chatContextKey
            || (meta.isGroup ? normalizedUserId : normalizedUserId)
            || ''
        ).trim();
        const chatNicknameTargetKey = String(
            meta.isGroup
                ? normalizedUserId
                : resolvedChatContextKey
        ).trim();
        const isArchived = isArchivedContactId(normalizedUserId);
        const isAiChat = !meta.isGroup && normalizedUserId.startsWith('ai:');
        const displayNameForAction = getDisplayNameForUser(normalizedUserId, meta, resolvedChatContextKey);
        const viewerChatNickname = chatNicknameTargetKey ? getViewerChatNickname(chatNicknameTargetKey) : '';

        const addClearChatNicknameOption = () => {
            if (!chatNicknameTargetKey || !viewerChatNickname) {
                return;
            }

            options.push({
                label: 'Clear Chat Nickname',
                iconClass: 'fa-solid fa-eraser',
                onSelect: async () => {
                    await saveChatNicknameForCurrentUser(chatNicknameTargetKey, '');
                }
            });
        };

        if (meta.isGroup) {
            addClearChatNicknameOption();

            options.push({
                label: 'Add Members',
                iconClass: 'fa-solid fa-user-plus',
                onSelect: () => {
                    const metaForGroup = getContactMeta(normalizedUserId);
                    if (!metaForGroup || !metaForGroup.isGroup) {
                        return;
                    }
                    selectedUser = normalizedUserId;
                    updateHeaderContact(normalizedUserId);
                    const originalButton = document.getElementById('add-members-btn') || document.getElementById('add-members-btn-mobile');
                    if (originalButton && !originalButton.classList.contains('icon-disabled')) {
                        originalButton.click();
                    }
                }
            });

            options.push({
                label: 'Show Members',
                iconClass: 'fa-solid fa-users',
                onSelect: () => {
                    openGroupMembersModal(normalizedUserId);
                }
            });

            if (meta.canManageGroup || isGroupOwnerMeta(meta)) {
                options.push({
                    label: 'Group Settings',
                    iconClass: 'fa-solid fa-gear',
                    rotateIconOnHover: true,
                    onSelect: () => {
                        openGroupSettingsModalFor(normalizedUserId);
                    }
                });
            }
        } else if (isAiChat) {
            options.push({
                label: 'AI Settings',
                iconClass: 'fa-solid fa-gear',
                rotateIconOnHover: true,
                onSelect: () => {
                    openAiSettingsModal(normalizedUserId);
                }
            });
        } else {
            options.push({
                label: 'Set Nickname',
                iconText: 'Aa',
                onSelect: () => {
                    openNicknameModal(normalizedUserId);
                }
            });

            addClearChatNicknameOption();

            const notificationMode = getChatNotificationPref(normalizedUserId);
            const isMutedNotifications = notificationMode === 'mention';
            options.push({
                label: isMutedNotifications ? 'Unmute' : 'Mute',
                iconClass: isMutedNotifications ? 'fa-solid fa-bell' : 'fa-solid fa-bell-slash',
                onSelect: async () => {
                    const nextMode = isMutedNotifications ? 'all' : 'mention';
                    await setChatNotificationPref(normalizedUserId, nextMode);
                    showToast(
                        nextMode === 'mention'
                            ? 'Notifications muted unless this user mentions you with @.'
                            : 'Notifications restored for this chat.',
                        'success'
                    );
                    refreshOpenProfileViews(normalizedUserId);
                    refreshUnreadBadges();
                }
            });

            const isBlocked = isBlockedUser(normalizedUserId);
            options.push({
                label: isBlocked ? 'Unblock' : 'Block',
                iconClass: 'fa-solid fa-circle-xmark',
                danger: true,
                onSelect: () => {
                    const action = isBlocked ? 'unblock' : 'block';
                    openChatActionModal({
                        message: isBlocked
                            ? `Are you sure you want to unblock ${displayNameForAction}?`
                            : `Are you sure you want to block ${displayNameForAction}?`,
                        tone: isBlocked ? 'accent' : 'danger',
                        onConfirm: async () => {
                            await persistBlockRelationship(normalizedUserId, action);
                            if (String(selectedUser || '') === normalizedUserId) {
                                updateHeaderContact(normalizedUserId);
                                await refreshSelectedConversationFromServer();
                            }
                            refreshOpenProfileViews(normalizedUserId);
                        }
                    });
                }
            });
        }

        const isPinnedChat = isPinnedChatId(normalizedUserId);
        options.push({
            label: isPinnedChat ? 'Unpin Chat' : 'Pin Chat',
            iconClass: 'fa-solid fa-thumbtack',
            onSelect: () => {
                setPinnedChatState(normalizedUserId, !isPinnedChat);
            }
        });

        const chatIsUnread = isChatUnreadLocally(normalizedUserId);
        options.push({
            label: chatIsUnread ? 'Mark as Read' : 'Mark as Unread',
            iconClass: chatIsUnread ? 'fa-solid fa-envelope-open' : 'fa-solid fa-envelope',
            onSelect: async () => {
                if (chatIsUnread) {
                    await markChatAsReadExplicit(normalizedUserId);
                    return;
                }

                markChatAsUnreadExplicit(normalizedUserId);
            }
        });

        options.push({
            label: isArchived ? 'Restore' : 'Archive',
            iconClass: isArchived ? 'fa-solid fa-rotate-left' : 'fa-solid fa-box-archive',
            onSelect: () => {
                setArchivedContactState(normalizedUserId, !isArchived);
            }
        });

        return options;
    }

    function appendAdditionalChatOptionButtons(container, userId, options = {}) {
        if (!container) {
            return;
        }

        buildAdditionalChatOptionItems(userId, options).forEach(item => {
            const button = createContactActionButton(item, 'rs-action-btn');
            button.addEventListener('click', async () => {
                try {
                    await item.onSelect();
                } catch (error) {
                    console.error('Additional chat option failed.', error);
                }
            });
            container.appendChild(button);
        });
    }

    function openContactQuickActionsMenu(userId, { anchorEl = null, source = 'button', event = null, chatContextKey = '' } = {}) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId) {
            return;
        }

        ensureContactQuickActionsUi();
        if (!contactQuickActionsOverlay || !contactQuickActionsMenu) {
            return;
        }

        const meta = getContactMeta(normalizedUserId);
        const items = buildAdditionalChatOptionItems(normalizedUserId, { chatContextKey });
        if (!meta || !items.length) {
            return;
        }

        contactQuickActionsActiveUser = normalizedUserId;
        const useSheet = isMobileViewport() || source === 'longpress';
        const displayName = getDisplayNameForUser(normalizedUserId, meta, chatContextKey || normalizedUserId);
        const subtitle = meta.isGroup
            ? `${meta.memberCount || 0} member${Number(meta.memberCount || 0) === 1 ? '' : 's'}`
            : (meta.username ? `@${meta.username}` : (normalizedUserId.startsWith('ai:') ? 'AI chat' : 'Chat options'));

        contactQuickActionsOverlay.hidden = false;
        contactQuickActionsOverlay.classList.add('is-open');
        contactQuickActionsOverlay.classList.toggle('is-sheet', useSheet);
        contactQuickActionsMenu.innerHTML = '';

        const header = document.createElement('div');
        header.className = 'contact-quick-actions-header';

        const title = document.createElement('div');
        title.className = 'contact-quick-actions-title';
        title.textContent = displayName || meta.displayName || normalizedUserId;

        const subtitleEl = document.createElement('div');
        subtitleEl.className = 'contact-quick-actions-subtitle';
        subtitleEl.textContent = subtitle;

        header.appendChild(title);
        header.appendChild(subtitleEl);
        contactQuickActionsMenu.appendChild(header);

        items.forEach(item => {
            const button = createContactActionButton(item, 'contact-quick-actions-item');
            button.addEventListener('click', async clickEvent => {
                clickEvent.preventDefault();
                clickEvent.stopPropagation();
                closeContactQuickActionsMenu();
                try {
                    await item.onSelect();
                } catch (error) {
                    console.error('Quick contact action failed.', error);
                }
            });
            contactQuickActionsMenu.appendChild(button);
        });

        contactQuickActionsMenu.style.left = '';
        contactQuickActionsMenu.style.right = '';
        contactQuickActionsMenu.style.top = '';
        contactQuickActionsMenu.style.bottom = '';

        if (useSheet) {
            return;
        }

        const anchorRect = anchorEl && typeof anchorEl.getBoundingClientRect === 'function'
            ? anchorEl.getBoundingClientRect()
            : null;
        const menuRect = contactQuickActionsMenu.getBoundingClientRect();
        const fallbackX = event && typeof event.clientX === 'number' ? event.clientX : 16;
        const fallbackY = event && typeof event.clientY === 'number' ? event.clientY : 16;

        let left = anchorRect ? (anchorRect.right - menuRect.width) : fallbackX;
        left = Math.max(12, Math.min(left, window.innerWidth - menuRect.width - 12));

        let top = anchorRect ? (anchorRect.bottom + 8) : fallbackY;
        if (top + menuRect.height > window.innerHeight - 12) {
            top = anchorRect
                ? Math.max(12, anchorRect.top - menuRect.height - 8)
                : Math.max(12, window.innerHeight - menuRect.height - 12);
        }

        contactQuickActionsMenu.style.left = `${Math.round(left)}px`;
        contactQuickActionsMenu.style.top = `${Math.round(top)}px`;
    }

    function buildRightSidebarContent(userId, targetContainer = rightSidebarContent, options = {}) {
        const container = targetContainer || rightSidebarContent;
        const normalizedUserId = String(userId || '');
        const isPrimarySidebar = container === rightSidebarContent && !options.forceStandalone;

        if (!container) return;

        // Check if members were showing before clearing
        const wasShowingMembers = isPrimarySidebar && container.querySelector('.rs-members-section') !== null;

        container.innerHTML = '';
        if (!normalizedUserId) return;

        const meta = getContactMeta(normalizedUserId);
        if (!meta) return;
        const chatContextKey = String(
            options.chatContextKey
            || (!meta.isGroup ? normalizedUserId : '')
            || ''
        ).trim();

        if (isPrimarySidebar && rightSidebarMobileTitle) {
            rightSidebarMobileTitle.textContent = meta.isGroup ? 'Group info' : 'Chat info';
        }

        if (
            isPrimarySidebar
            && window.innerWidth <= 768
            && rightSidebar
            && rightSidebar.classList.contains('is-open')
            && rightSidebarSearch
            && (rightSidebarSearch.value.trim() || msgSearchActiveFilter !== 'all' || getActiveMsgSearchFilterValue())
            && String(rightSidebar.dataset.activeUser || '') === normalizedUserId
        ) {
            runRightSidebarMessageSearch(normalizedUserId);
            return;
        }

        // ── Profile row ──────────────────────────────────────────────────────
        const profile = document.createElement('div');
        profile.className = 'rs-profile';
        const isTyping = isChatCurrentlyTyping(normalizedUserId, meta);
        const isPresenceOnline = meta.isGroup ? (!!meta.isOnline || isTyping) : !!meta.isOnline;
        const secondaryText = getInfoSurfaceSecondaryText(normalizedUserId, meta);

        const avatarWrap = document.createElement('div');
        avatarWrap.className = 'rs-avatar-wrap';
        const avatar = document.createElement('img');
        avatar.className = 'rs-avatar';
        avatar.src = meta.profilePic || 'images/default-profile.png';
        avatar.alt = meta.displayName || '';
        const statusDot = document.createElement('span');
        statusDot.className = 'rs-status-dot chat-header-status-dot';
        applyPresenceIndicatorState(statusDot, isPresenceOnline, isTyping);
        avatarWrap.appendChild(avatar);
        avatarWrap.appendChild(statusDot);

        const identity = document.createElement('div');
        identity.className = 'rs-identity';
        const nameEl = document.createElement('div');
        nameEl.className = 'rs-display-name';
        
        // Show nickname or display name based on preference
        const displayName = getDisplayNameForUser(normalizedUserId, meta, chatContextKey);
        nameEl.textContent = displayName;
        
        const unameEl = document.createElement('div');
        unameEl.className = 'rs-username';
        unameEl.textContent = secondaryText;
        unameEl.hidden = secondaryText === '';
        identity.appendChild(nameEl);
        identity.appendChild(unameEl);
        
        // Add nickname toggle link for direct messages
        if (!meta.isGroup) {
            const nickname = getUserNickname(normalizedUserId);
            if (nickname) {
                const pref = getNicknameDisplayPref(normalizedUserId);
                const toggleLink = document.createElement('a');
                toggleLink.href = '#';
                toggleLink.className = 'rs-nickname-toggle';
                toggleLink.style.cssText = 'font-size:0.85rem;color:var(--accent-color);text-decoration:none;margin-top:4px;display:inline-block;';
                toggleLink.textContent = pref === 'nickname' ? 'Show display name' : 'Show nickname';
                
                toggleLink.addEventListener('click', (e) => {
                    e.preventDefault();
                    const currentPref = getNicknameDisplayPref(normalizedUserId);
                    const newPref = currentPref === 'nickname' ? 'display' : 'nickname';
                    setNicknameDisplayPref(normalizedUserId, newPref);
                    refreshAllDisplayNames(normalizedUserId);
                    refreshOpenProfileViews(normalizedUserId);
                });
                identity.appendChild(toggleLink);
            }
        }
        
        profile.appendChild(avatarWrap);
        profile.appendChild(identity);
        container.appendChild(profile);

        // ── Bio / Description ────────────────────────────────────────────────
        const bioSection = document.createElement('div');
        bioSection.className = 'rs-section';
        const bioLabel = document.createElement('div');
        bioLabel.className = 'rs-section-label';
        bioLabel.textContent = meta.isGroup ? 'Description' : 'Bio';
        const bioText = document.createElement('div');
        bioText.className = 'rs-section-text';
        bioText.textContent = (meta.bio && meta.bio.trim()) ? meta.bio : (meta.isGroup ? 'No description yet.' : 'No bio yet.');
        bioSection.appendChild(bioLabel);
        bioSection.appendChild(bioText);
        container.appendChild(bioSection);

        // ── Member since ─────────────────────────────────────────────────────
        const sinceSection = document.createElement('div');
        sinceSection.className = 'rs-section';
        const sinceLabel = document.createElement('div');
        sinceLabel.className = 'rs-section-label';
        sinceLabel.textContent = meta.isGroup ? 'Created' : 'Member since';
        const sinceText = document.createElement('div');
        sinceText.className = 'rs-section-text';
        sinceText.textContent = formatMemberSinceDate(meta.createdAt);
        sinceSection.appendChild(sinceLabel);
        sinceSection.appendChild(sinceText);
        container.appendChild(sinceSection);

        // ── Group notification toggle (groups only) ──────────────────────────
        if (meta.isGroup) {
            const notifSection = document.createElement('div');
            notifSection.className = 'rs-section';
            const notifLabel = document.createElement('div');
            notifLabel.className = 'rs-section-label';
            notifLabel.textContent = 'Notifications';
            const notifRow = document.createElement('div');
            notifRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:6px;';
            const notifText = document.createElement('p');
            notifText.className = 'rs-section-text';
            notifText.style.margin = '0';
            const pref = getGroupNotifPref(normalizedUserId);
            notifText.textContent = pref === 'all'
                ? 'Receive notifications for all messages'
                : 'Notify only when mentioned with @';
            const toggleLabel = document.createElement('label');
            toggleLabel.className = 'settings-toggle-label';
            toggleLabel.style.flexShrink = '0';
            const toggleInput = document.createElement('input');
            toggleInput.type = 'checkbox';
            toggleInput.checked = pref === 'all';
            const toggleTrack = document.createElement('span');
            toggleTrack.className = 'settings-toggle-track';
            toggleLabel.appendChild(toggleInput);
            toggleLabel.appendChild(toggleTrack);
            toggleInput.addEventListener('change', async function() {
                const newPref = this.checked ? 'all' : 'mention';
                await setGroupNotifPref(normalizedUserId, newPref);
                notifText.textContent = newPref === 'all'
                    ? 'Receive notifications for all messages'
                    : 'Notify only when mentioned with @';
                // Also sync the panel toggle if open
                const panelToggle = document.getElementById('groupNotifToggle');
                if (panelToggle) panelToggle.checked = this.checked;
                refreshOpenProfileViews(normalizedUserId);
                refreshUnreadBadges();
            });
            notifRow.appendChild(notifText);
            notifRow.appendChild(toggleLabel);
            notifSection.appendChild(notifLabel);
            notifSection.appendChild(notifRow);
            container.appendChild(notifSection);
        }

        // ── Additional options ───────────────────────────────────────────────
        const optLabel = document.createElement('div');
        optLabel.className = 'rs-divider-label';
        optLabel.textContent = 'Additional options';
        container.appendChild(optLabel);
        appendAdditionalChatOptionButtons(container, normalizedUserId, { chatContextKey });

        // Re-render members if they were showing before
        if (wasShowingMembers && meta && meta.isGroup) {
            renderRightSidebarMembers(normalizedUserId);
        }
    }

    function refreshOpenProfileViews(userId) {
        const normalizedUserId = String(userId || '');
        if (!normalizedUserId) {
            return;
        }

        // Safety check: rightSidebar might not be initialized yet
        if (typeof rightSidebar === 'undefined') {
            return;
        }

        if (
            rightSidebar
            && rightSidebar.classList.contains('is-open')
            && String(rightSidebar.dataset.activeUser || '') === normalizedUserId
        ) {
            buildRightSidebarContent(normalizedUserId);
        }

        if (
            userInfoModal
            && userInfoModal.classList.contains('open')
            && userInfoModalContent
            && String(userInfoModal.dataset.activeUser || '') === normalizedUserId
        ) {
            buildRightSidebarContent(normalizedUserId, userInfoModalContent, {
                isModal: true,
                forceStandalone: true,
                chatContextKey: String(userInfoModal.dataset.chatContextKey || '')
            });
        }
    }

    function refreshOpenProfileViewsForChatContext(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return;
        }

        refreshOpenProfileViews(normalizedChatKey);

        if (
            userInfoModal
            && userInfoModal.classList.contains('open')
            && userInfoModalContent
            && String(userInfoModal.dataset.chatContextKey || '') === normalizedChatKey
        ) {
            const modalActiveUser = String(userInfoModal.dataset.activeUser || '').trim();
            if (modalActiveUser) {
                buildRightSidebarContent(modalActiveUser, userInfoModalContent, {
                    isModal: true,
                    forceStandalone: true,
                    chatContextKey: normalizedChatKey
                });
            }
        }
    }

    function renderRightSidebarMembers(userId) {
        // Check if members section already exists
        const existing = rightSidebarContent && rightSidebarContent.querySelector('.rs-members-section');
        if (existing) { 
            // Already showing, don't duplicate
            return;
        }

        const members = groupMembersMap[String(userId)] || [];
        if (!members.length) return;

        const section = document.createElement('div');
        section.className = 'rs-section rs-members-section';
        section.dataset.persistent = 'true'; // Mark as persistent
        const label = document.createElement('div');
        label.className = 'rs-section-label';
        label.textContent = members.length + ' member' + (members.length === 1 ? '' : 's');
        section.appendChild(label);
        
        members.forEach(m => {
            const memberId = String(m.user_id || m.id || '');
            const row = document.createElement('div');
            row.style.cssText = 'display:flex;align-items:center;gap:8px;padding:8px 0;';
            
            const img = document.createElement('img');
            img.src = m.profile_pic || userProfilePics[memberId] || 'images/default-profile.png';
            img.style.cssText = 'width:32px;height:32px;border-radius:50%;object-fit:cover;flex-shrink:0;';
            
            const name = document.createElement('span');
            name.style.cssText = 'font-size:0.9rem;flex:1;min-width:0;';
            const memberDisplayName = getDisplayNameForUser(memberId, { 
                displayName: m.display_name, 
                username: m.username,
                isGroup: false 
            }, String(userId || ''));
            name.textContent = memberDisplayName;
            
            row.appendChild(img);
            row.appendChild(name);
            
            // Add three dots button if viewer can moderate or change role
            const canModerate = !!(Number(m.viewer_can_moderate) || m.viewer_can_moderate === true || m.viewer_can_moderate === '1');
            const canChangeRole = !!(Number(m.viewer_can_change_role) || m.viewer_can_change_role === true || m.viewer_can_change_role === '1');
            
            if (canModerate || canChangeRole) {
                const dotsBtn = document.createElement('button');
                dotsBtn.className = 'member-card-actions-btn';
                dotsBtn.setAttribute('aria-label', 'Member actions');
                dotsBtn.innerHTML = '<i class="fas fa-ellipsis-vertical"></i>';
                dotsBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    openMemberCtxMenu(
                        e,
                        userId,
                        memberId,
                        memberDisplayName,
                        !!Number(m.is_muted || 0) || isFutureDateValue(m.muted_until),
                        canModerate,
                        canChangeRole
                    );
                });
                row.appendChild(dotsBtn);
            }
            
            section.appendChild(row);
        });
        rightSidebarContent.appendChild(section);
    }

    function getMessageSearchTextForElement(messageEl) {
        if (!(messageEl instanceof HTMLElement)) {
            return '';
        }

        const record = messageEl._qtMessageRecord && typeof messageEl._qtMessageRecord === 'object'
            ? messageEl._qtMessageRecord
            : null;
        const rawMessage = String(record && record.message ? record.message : '');
        const textEl = messageEl.querySelector('.text');
        const visibleText = textEl ? String(textEl.textContent || '').trim() : '';
        const searchParts = [visibleText];
        const attachment = parseAttachmentMessage(rawMessage);

        if (attachment) {
            if (attachment.kind === 'image') {
                searchParts.push('photo', 'media', attachment.name || '');
            } else if (attachment.kind === 'video') {
                searchParts.push('video', 'media', attachment.name || '');
            } else if (attachment.kind === 'audio') {
                searchParts.push('voice', 'voice message', attachment.name || '');
            } else {
                searchParts.push(attachment.name || 'attachment');
            }
        }

        if (parsePollMessage(rawMessage)) {
            searchParts.push('poll');
        }

        const gameMessage = parseGameMessage(rawMessage);
        if (gameMessage) {
            searchParts.push('game', 'sidequest', getGameMessageLabel(gameMessage));
        }

        const tableMessage = parseTableMessage(rawMessage);
        if (tableMessage) {
            searchParts.push(getTableMessageSummary(tableMessage));
        }

        return searchParts.filter(Boolean).join(' ').trim();
    }

    function messageElementMatchesActiveSearchFilters(messageEl, query, chatKey = selectedUser) {
        if (!(messageEl instanceof HTMLElement)) {
            return false;
        }

        const record = messageEl._qtMessageRecord && typeof messageEl._qtMessageRecord === 'object'
            ? messageEl._qtMessageRecord
            : null;
        const rawMessage = String(record && record.message ? record.message : '');
        const visibleSearchText = getMessageSearchTextForElement(messageEl);
        const normalizedQuery = String(query || '').trim().toLowerCase();
        const filterConfig = getMsgSearchFilterConfig(msgSearchActiveFilter);
        const activeFilterValue = filterConfig.requiresValue ? getActiveMsgSearchFilterValue() : '';
        const normalizedFilterValue = String(activeFilterValue || '').trim().replace(/^@+/, '').toLowerCase();

        if (normalizedQuery && !visibleSearchText.toLowerCase().includes(normalizedQuery)) {
            return false;
        }

        if (filterConfig.requiresValue && !normalizedFilterValue) {
            return false;
        }

        if (filterConfig.key === 'all') {
            return true;
        }

        const attachment = parseAttachmentMessage(rawMessage);
        if (filterConfig.key === 'media') {
            return !!(attachment && (attachment.kind === 'image' || attachment.kind === 'video'));
        }

        if (filterConfig.key === 'links') {
            if (attachment || parsePollMessage(rawMessage) || parseGameMessage(rawMessage) || parseTableMessage(rawMessage)) {
                return false;
            }
            return /(https?:\/\/|www\.)/i.test(rawMessage || visibleSearchText);
        }

        if (filterConfig.key === 'polls') {
            return !!parsePollMessage(rawMessage);
        }

        if (filterConfig.key === 'voice') {
            return !!(attachment && attachment.kind === 'audio');
        }

        if (filterConfig.key === 'from_user') {
            const senderId = String(record && record.sender_id ? record.sender_id : (messageEl.dataset.senderId || '')).trim();
            const meta = senderId ? getContactMeta(senderId) : null;
            const senderHaystack = [
                record && record.sender_display_name ? record.sender_display_name : '',
                meta && meta.displayName ? meta.displayName : '',
                meta && meta.username ? meta.username : ''
            ].filter(Boolean).join(' ').toLowerCase();

            return senderHaystack.includes(normalizedFilterValue);
        }

        if (filterConfig.key === 'mentions_user') {
            return messageHasMentionToken(rawMessage, normalizedFilterValue);
        }

        return true;
    }

    function runRightSidebarMessageSearch(userId = selectedUser) {
        if (!rightSidebarSearch) {
            return false;
        }

        const query = String(rightSidebarSearch.value || '').trim();
        const filterConfig = getMsgSearchFilterConfig(msgSearchActiveFilter);
        const activeFilterValue = filterConfig.requiresValue ? getActiveMsgSearchFilterValue() : '';
        const shouldSearch = !!query || filterConfig.key !== 'all' || !!activeFilterValue;

        if (!shouldSearch) {
            buildRightSidebarContent(userId);
            return false;
        }

        if (window.innerWidth <= 768) {
            return renderRightSidebarSearchResults(query, userId);
        }

        return renderDesktopRightSidebarSearchResults(query);
    }

    function renderRightSidebarSearchResults(query, userId = selectedUser) {
        if (!rightSidebarContent) {
            return false;
        }

        const trimmedQuery = String(query || '').trim();
        const filterConfig = getMsgSearchFilterConfig(msgSearchActiveFilter);
        const activeFilterValue = filterConfig.requiresValue ? getActiveMsgSearchFilterValue() : '';
        if (!trimmedQuery && filterConfig.key === 'all' && !activeFilterValue) {
            return false;
        }

        rightSidebarContent.innerHTML = '';
        const messages = Array.from(document.querySelectorAll('#chatBox .message'));
        const results = messages.filter(el => messageElementMatchesActiveSearchFilters(el, trimmedQuery, userId));

        if (!results.length) {
            const empty = document.createElement('div');
            empty.className = 'rs-section-text';
            empty.style.padding = '12px 16px';
            empty.textContent = filterConfig.requiresValue && !activeFilterValue
                ? (msgSearchActiveFilter === 'from_user'
                    ? 'Type a sender name to filter messages.'
                    : 'Type a name to find messages that mention that user.')
                : 'No messages found.';
            rightSidebarContent.appendChild(empty);
            return true;
        }

        results.forEach(msgEl => {
            const resultWrap = document.createElement('div');
            resultWrap.className = 'right-sidebar-search-result';

            const ts = msgEl.dataset.timestamp || '';
            if (ts) {
                const tsEl = document.createElement('div');
                tsEl.className = 'timestamp';
                tsEl.style.cssText = 'font-size:0.75rem;color:var(--text-muted);text-align:center;padding:4px 0 2px;';
                tsEl.textContent = formatTimestamp(ts);
                resultWrap.appendChild(tsEl);
            }

            const clone = msgEl.cloneNode(true);
            clone.style.cursor = 'pointer';
            clone.style.marginBottom = '0';
            const actions = clone.querySelector('.message-actions-wrap');
            if (actions) {
                actions.remove();
            }

            resultWrap.appendChild(clone);
            resultWrap.addEventListener('click', () => {
                const targetMessageId = String(msgEl.dataset.id || '').trim();
                if (window.innerWidth <= 768) {
                    closeRightSidebar();
                    setMobileConversationVisibility(true);
                    window.setTimeout(() => {
                        if (targetMessageId) {
                            scrollChatToMessageId(targetMessageId);
                        }
                    }, 40);
                    return;
                }

                if (targetMessageId) {
                    scrollChatToMessageId(targetMessageId);
                }
            });

            rightSidebarContent.appendChild(resultWrap);
        });

        return true;
    }

    function renderDesktopRightSidebarSearchResults(query) {
        if (!rightSidebarContent) {
            return false;
        }

        const trimmedQuery = String(query || '').trim();
        const filterConfig = getMsgSearchFilterConfig(msgSearchActiveFilter);
        const activeFilterValue = filterConfig.requiresValue ? getActiveMsgSearchFilterValue() : '';
        if (!trimmedQuery && filterConfig.key === 'all' && !activeFilterValue) {
            return false;
        }

        rightSidebarContent.innerHTML = '';
        const messages = Array.from(document.querySelectorAll('#chatBox .message'));
        const results = messages.filter(el => messageElementMatchesActiveSearchFilters(el, trimmedQuery, selectedUser));

        if (!results.length) {
            const empty = document.createElement('div');
            empty.className = 'rs-section-text';
            empty.style.padding = '12px 0';
            empty.textContent = filterConfig.requiresValue && !activeFilterValue
                ? (msgSearchActiveFilter === 'from_user'
                    ? 'Type a sender name to filter messages.'
                    : 'Type a name to find messages that mention that user.')
                : 'No messages found.';
            rightSidebarContent.appendChild(empty);
            return true;
        }

        results.forEach(msgEl => {
            const ts = msgEl.dataset.timestamp || '';
            if (ts) {
                const tsEl = document.createElement('div');
                tsEl.className = 'timestamp';
                tsEl.style.cssText = 'font-size:0.75rem;color:var(--text-muted);text-align:center;padding:4px 0 2px;';
                tsEl.textContent = formatTimestamp(ts);
                rightSidebarContent.appendChild(tsEl);
            }

            const clone = msgEl.cloneNode(true);
            clone.style.cursor = 'pointer';
            clone.style.marginBottom = '8px';
            const actions = clone.querySelector('.message-actions-wrap');
            if (actions) {
                actions.remove();
            }
            clone.addEventListener('click', () => {
                const targetMessageId = String(msgEl.dataset.id || '').trim();
                if (targetMessageId) {
                    scrollChatToMessageId(targetMessageId);
                }
            });
            rightSidebarContent.appendChild(clone);
        });

        return true;
    }

    function openRightSidebar(userId) {
        if (!rightSidebar) return;
        const normalizedUserId = String(userId || '');
        const wasOpen = rightSidebar.classList.contains('is-open');
        const previousUserId = String(rightSidebar.dataset.activeUser || '');
        const shouldResetSearch = !wasOpen || previousUserId !== normalizedUserId || window.innerWidth > 768;
        hideContactInfoPanel();
        rightSidebar.classList.add('is-open');
        rightSidebar.dataset.activeUser = normalizedUserId;
        if (rightSidebarSearch && shouldResetSearch) {
            rightSidebarSearch.value = '';
        }
        buildRightSidebarContent(userId);
        [contactInfoBtn, contactInfoBtnMobile].forEach(button => {
            if (button) {
                button.setAttribute('aria-expanded', 'true');
            }
        });
        updateRightSidebarToggleBtn();
        
        // Hide mobile call/video/info buttons when sidebar opens on mobile
        if (window.innerWidth <= 768) {
            try {
                const callBtnMobile = document.getElementById('start-call-btn-mobile');
                const videoBtnMobile = document.getElementById('start-video-call-btn-mobile');
                const infoBtnMobile = document.getElementById('contact-info-btn-mobile');
                
                if (callBtnMobile) callBtnMobile.style.display = 'none';
                if (videoBtnMobile) videoBtnMobile.style.display = 'none';
                if (infoBtnMobile) infoBtnMobile.style.display = 'none';
            } catch (e) {
                console.error('Error hiding mobile buttons:', e);
            }
        }
        if (rightSidebarSearch) {
            rightSidebarSearch.oninput = function() {
                runRightSidebarMessageSearch(selectedUser || userId);
            };

            if (rightSidebarSearch.value.trim() || msgSearchActiveFilter !== 'all' || getActiveMsgSearchFilterValue()) {
                runRightSidebarMessageSearch(normalizedUserId);
            }
        }
    }

    function closeRightSidebar() {
        if (!rightSidebar) return;
        rightSidebar.classList.remove('is-open');
        syncMsgSearchControlsVisibility(false, rightSidebarSearchControls);
        [contactInfoBtn, contactInfoBtnMobile].forEach(button => {
            if (button) {
                button.setAttribute('aria-expanded', 'false');
            }
        });
        updateRightSidebarToggleBtn();
        
        // Show mobile call/video/info buttons when sidebar closes on mobile
        if (window.innerWidth <= 768) {
            try {
                const callBtnMobile = document.getElementById('start-call-btn-mobile');
                const videoBtnMobile = document.getElementById('start-video-call-btn-mobile');
                const infoBtnMobile = document.getElementById('contact-info-btn-mobile');
                
                if (callBtnMobile) callBtnMobile.style.display = '';
                if (videoBtnMobile) videoBtnMobile.style.display = '';
                if (infoBtnMobile) infoBtnMobile.style.display = '';
            } catch (e) {
                console.error('Error showing mobile buttons:', e);
            }
        }
    }

    function clearMsgSearchHighlights() {
        const msgSearchInput = document.getElementById('msgSearchInput');
        if (msgSearchInput) {
            msgSearchInput.value = '';
        }
        if (rightSidebarSearch) {
            rightSidebarSearch.value = '';
        }
        if (msgSearchFilterValue) {
            msgSearchFilterValue.value = '';
        }
        if (rightSidebarSearchFilterValue) {
            rightSidebarSearchFilterValue.value = '';
        }
        msgSearchFilterValues.from_user = '';
        msgSearchFilterValues.mentions_user = '';
        setMsgSearchFilter('all');
        if (msgSearchInput) {
            msgSearchInput.dispatchEvent(new Event('input'));
        }
        if (rightSidebarSearch) {
            runRightSidebarMessageSearch(String(rightSidebar && rightSidebar.dataset.activeUser ? rightSidebar.dataset.activeUser : (selectedUser || '')));
        }
        syncMsgSearchControlsVisibility(false);
    }

    function toggleRightSidebar(userId) {
        if (!rightSidebar) return;
        if (rightSidebar.classList.contains('is-open')) {
            closeRightSidebar();
        } else {
            openRightSidebar(userId);
        }
    }

    function updateRightSidebarToggleBtn() {
        const btn = document.getElementById('right-sidebar-toggle-btn');
        if (!btn) return;
        const isOpen = rightSidebar && rightSidebar.classList.contains('is-open');
        const icon = btn.querySelector('i');
        if (icon) {
            icon.className = isOpen ? 'fa-solid fa-angles-right' : 'fa-solid fa-angles-left';
        }
        btn.setAttribute('aria-label', isOpen ? 'Collapse sidebar' : 'Expand sidebar');
        btn.title = isOpen ? 'Collapse sidebar' : 'Expand sidebar';
    }

    if (rightSidebar && !isMobileViewport()) {
        rightSidebar.classList.add('is-open');
    }
    updateRightSidebarToggleBtn();

    const rightSidebarToggleBtnEl = document.getElementById('right-sidebar-toggle-btn');
    if (rightSidebarToggleBtnEl) {
        rightSidebarToggleBtnEl.addEventListener('click', () => {
            if (selectedUser) toggleRightSidebar(selectedUser);
        });
    }

    if (rightSidebarMobileClose) {
        rightSidebarMobileClose.addEventListener('click', () => {
            closeRightSidebar();
        });
    }

    // ── Sidebar resize (left) ─────────────────────────────────────────────────
    (function() {
        const handle = document.getElementById('leftSidebarHandle');
        const sidebar = document.getElementById('sidebar');
        if (!handle || !sidebar) return;
        let dragging = false, startX = 0, startW = 0;
        handle.addEventListener('mousedown', function(e) {
            dragging = true; startX = e.clientX; startW = sidebar.offsetWidth;
            handle.classList.add('is-dragging');
            document.body.style.cursor = 'col-resize';
            document.body.style.userSelect = 'none';
        });
        document.addEventListener('mousemove', function(e) {
            if (!dragging) return;
            const w = Math.max(180, Math.min(480, startW + (e.clientX - startX)));
            sidebar.style.width = w + 'px';
        });
        document.addEventListener('mouseup', function() {
            if (!dragging) return;
            dragging = false;
            handle.classList.remove('is-dragging');
            document.body.style.cursor = '';
            document.body.style.userSelect = '';
        });
    })();

    // ── Sidebar resize (right) ────────────────────────────────────────────────
    (function() {
        const handle = document.getElementById('rightSidebarHandle');
        const rs = document.getElementById('rightSidebar');
        if (!handle || !rs) return;
        let dragging = false, startX = 0, startW = 0;
        handle.addEventListener('mousedown', function(e) {
            // If sidebar is closed, open it on drag
            if (!rs.classList.contains('is-open') && selectedUser) {
                openRightSidebar(selectedUser);
            }
            dragging = true;
            startX = e.clientX;
            startW = rs.offsetWidth || 280;
            handle.classList.add('is-dragging');
            document.body.style.cursor = 'col-resize';
            document.body.style.userSelect = 'none';
            e.preventDefault();
        });
        // Click (no drag) toggles the sidebar
        handle.addEventListener('click', function(e) {
            if (Math.abs(e.clientX - startX) < 4) {
                if (selectedUser) toggleRightSidebar(selectedUser);
            }
        });
        document.addEventListener('mousemove', function(e) {
            if (!dragging) return;
            const w = Math.max(180, Math.min(480, startW - (e.clientX - startX)));
            rs.style.width = w + 'px';
        });
        document.addEventListener('mouseup', function() {
            if (!dragging) return;
            dragging = false;
            handle.classList.remove('is-dragging');
            document.body.style.cursor = '';
            document.body.style.userSelect = '';
        });
    })();

    let activeConversationLoadToken = 0;

    function renderConversationLoadingState(chatKey) {
        if (!chatBox) {
            return;
        }

        chatBox.innerHTML = '';

        const loading = document.createElement('div');
        loading.className = 'conversation-loading-state';
        loading.setAttribute('aria-live', 'polite');

        const spinner = document.createElement('i');
        spinner.className = 'fa-solid fa-spinner fa-spin conversation-loading-state-icon';
        spinner.setAttribute('aria-hidden', 'true');

        const label = document.createElement('span');
        label.textContent = 'Loading messages...';

        loading.appendChild(spinner);
        loading.appendChild(label);
        chatBox.appendChild(loading);
    }

    function beginConversationLoad(chatKey, {
        showLoadingState = false,
        loadingStateDelayMs = 0,
        scrollToBottomOnInitialLoad = false
    } = {}) {
        const normalizedChatKey = String(chatKey || '');
        if (!normalizedChatKey) {
            return Promise.resolve();
        }

        const loadToken = ++activeConversationLoadToken;
        lastId = 0;
        isInitialConversationLoad = true;
        initialLoadMessageCount = 0;
        let loadingStateTimer = 0;

        if (chatBox) {
            chatBox.innerHTML = '';
            // Disable animations during initial load to prevent double animations
            chatBox.style.setProperty('--disable-message-animations', '1');
        }

        if (showLoadingState && chatBox) {
            const showLoadingIndicator = () => {
                if (String(selectedUser || '') !== normalizedChatKey || activeConversationLoadToken !== loadToken) {
                    return;
                }

                if (!chatBox.querySelector('.message, .timestamp')) {
                    renderConversationLoadingState(normalizedChatKey);
                }
            };
            const delayMs = Math.max(0, Number(loadingStateDelayMs) || 0);
            if (delayMs === 0) {
                showLoadingIndicator();
            } else {
                loadingStateTimer = window.setTimeout(showLoadingIndicator, delayMs);
            }
        }

        const clearLoadingStateTimer = () => {
            if (loadingStateTimer) {
                window.clearTimeout(loadingStateTimer);
                loadingStateTimer = 0;
            }
        };
        const snapConversationToBottom = () => {
            if (!chatBox) {
                return;
            }

            if (typeof scrollChatToBottomAfterSend === 'function') {
                scrollChatToBottomAfterSend();
                return;
            }

            const syncToBottom = () => {
                chatBox.scrollTop = chatBox.scrollHeight;
            };

            syncToBottom();
            window.requestAnimationFrame(syncToBottom);
            window.setTimeout(syncToBottom, 120);
        };

        const markReadPromise = markChatAsRead(normalizedChatKey, { captureLastSeen: true });

        return (async () => {
            try {
                await pollMessages(true, normalizedChatKey);
                await markReadPromise;

                if (String(selectedUser || '') !== normalizedChatKey || activeConversationLoadToken !== loadToken) {
                    return;
                }

                pollTypingState();
                window.setTimeout(() => {
                    if (String(selectedUser || '') === normalizedChatKey && activeConversationLoadToken === loadToken) {
                        placeUnreadDivider();
                    }
                }, 100);
                if (scrollToBottomOnInitialLoad) {
                    // Skip snapConversationToBottom during initial load if we have messages to animate
                    // Our animation system handles scrolling to bottom
                    console.log('Skipping snapConversationToBottom - animation system handling scroll');
                }
                refreshUnreadBadges();
            } finally {
                clearLoadingStateTimer();
                // Reset initial load state after a delay to allow animations to complete
                setTimeout(() => {
                    isInitialConversationLoad = false;
                    initialLoadMessageCount = 0;
                }, 2000); // 2 seconds should be enough for all animations
            }
        })();
    }

    async function refreshSelectedConversationFromServer() {
        if (!selectedUser) {
            return;
        }

        await beginConversationLoad(selectedUser, { showLoadingState: true });
    }

    function openChatActionModal({ message, tone = 'danger', onConfirm = null }) {
        if (!chatActionModal || !chatActionModalMessage || !chatActionModalConfirm) {
            if (typeof onConfirm === 'function') {
                onConfirm();
            }
            return;
        }

        pendingChatActionConfirm = typeof onConfirm === 'function' ? onConfirm : null;
        chatActionModalMessage.textContent = message || '';
        chatActionModalConfirm.dataset.tone = tone === 'accent' ? 'accent' : 'danger';
        bringOverlayToFront(chatActionModal, 12);
        chatActionModal.classList.add('open');
        chatActionModal.setAttribute('aria-hidden', 'false');

        // Blur call/video/info buttons when modal opens
        try {
            const callBtn = document.getElementById('start-call-btn');
            const videoBtn = document.getElementById('start-video-call-btn');
            const infoBtn = document.getElementById('contact-info-btn');
            const callBtnMobile = document.getElementById('start-call-btn-mobile');
            const videoBtnMobile = document.getElementById('start-video-call-btn-mobile');
            const infoBtnMobile = document.getElementById('contact-info-btn-mobile');
            const collapseBtn = document.getElementById('right-sidebar-toggle-btn');
            
            [callBtn, videoBtn, infoBtn, callBtnMobile, videoBtnMobile, infoBtnMobile, collapseBtn].forEach(btn => {
                if (btn) btn.style.filter = 'blur(4px)';
            });
        } catch (e) {
            console.error('Error blurring buttons:', e);
        }

        requestAnimationFrame(() => {
            chatActionModalConfirm.focus();
        });
    }

    function closeChatActionModal() {
        pendingChatActionConfirm = null;
        if (!chatActionModal) {
            return;
        }

        chatActionModal.classList.remove('open');
        chatActionModal.setAttribute('aria-hidden', 'true');
        resetOverlayZIndex(chatActionModal);

        // Remove blur from call/video/info buttons when modal closes
        try {
            const callBtn = document.getElementById('start-call-btn');
            const videoBtn = document.getElementById('start-video-call-btn');
            const infoBtn = document.getElementById('contact-info-btn');
            const callBtnMobile = document.getElementById('start-call-btn-mobile');
            const videoBtnMobile = document.getElementById('start-video-call-btn-mobile');
            const infoBtnMobile = document.getElementById('contact-info-btn-mobile');
            const collapseBtn = document.getElementById('right-sidebar-toggle-btn');
            
            [callBtn, videoBtn, infoBtn, callBtnMobile, videoBtnMobile, infoBtnMobile, collapseBtn].forEach(btn => {
                if (btn) btn.style.filter = '';
            });
        } catch (e) {
            console.error('Error removing blur from buttons:', e);
        }
    }

    function openSelectedContactInfo(forceOpen = false) {
        if (!selectedUser) {
            return;
        }

        if (window.innerWidth <= 768) {
            openRightSidebar(selectedUser);
            return;
        }

        updateContactInfoPanel(selectedUser);
        if (forceOpen) {
            setContactInfoOpen(true);
            return;
        }

        setContactInfoOpen(!(contactInfoPanel && contactInfoPanel.classList.contains('active')));
    }

    function handleContactInfoButtonClick() {
        if (!selectedUser) {
            return;
        }

        if (!isGroupChatKey(String(selectedUser || '')) && isBlockedUser(selectedUser)) {
            const displayName = getDisplayNameForUser(selectedUser);
            openChatActionModal({
                message: `You have blocked ${displayName}. Are you sure you want to view their profile?`,
                tone: 'accent',
                onConfirm: () => {
                    openSelectedContactInfo(true);
                }
            });
            return;
        }

        openSelectedContactInfo();
