    function handleBlockUserButtonClick() {
        console.log('Block button clicked, selectedUser:', selectedUser);
        
        if (!selectedUser || isGroupChatKey(String(selectedUser || ''))) {
            console.log('Block button click ignored - no user selected or selected chat is a group');
            return;
        }

        const targetUserId = String(selectedUser);
        const displayName = getDisplayNameForUser(targetUserId);
        hideContactInfoPanel();

        if (isBlockedUser(targetUserId)) {
            openChatActionModal({
                message: `Are you sure you want to unblock ${displayName}?`,
                tone: 'accent',
                onConfirm: async () => {
                    await handleUnblockSelectedUser();
                }
            });
            return;
        }

        openChatActionModal({
            message: `Are you sure you want to block ${displayName}?`,
            tone: 'danger',
            onConfirm: async () => {
                await persistBlockRelationship(targetUserId, 'block');

                if (String(selectedUser || '') === targetUserId) {
                    updateHeaderContact(targetUserId);
                    await refreshSelectedConversationFromServer();
                }
            }
        });
    }

    async function handleUnblockSelectedUser() {
        if (!selectedUser) {
            return;
        }

        const targetUserId = String(selectedUser);
        await persistBlockRelationship(targetUserId, 'unblock');

        updateHeaderContact(targetUserId);
        await refreshSelectedConversationFromServer();

        if (messageInput) {
            messageInput.focus();
        }
    }

    function updateHeaderContact(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        const meta = normalizedUserId ? getContactMeta(normalizedUserId) : null;
        const displayName = meta ? getDisplayNameForUser(normalizedUserId, meta) : selectContactLabel;
        const profilePic = meta ? normalizeProfilePic(meta.profilePic, meta && meta.isGroup ? 'group' : 'direct') : defaultProfilePic;
        const isOnline = !!(meta && meta.isOnline);

        currentChatUserSpan.textContent = displayName;

        if (chatHeaderAvatar) {
            setProfileImage(chatHeaderAvatar, profilePic, meta && meta.isGroup ? 'group' : 'direct');
            chatHeaderAvatar.alt = displayName;
        }

        if (chatHeaderStatusDot) {
            applyPresenceIndicatorState(
                chatHeaderStatusDot,
                isOnline,
                !!(meta && !meta.isGroup && isUserCurrentlyTyping(normalizedUserId))
            );
        }

        if (chatHeaderContact) {
            chatHeaderContact.classList.toggle('empty', !normalizedUserId);
        }

        renderPinnedMessageBar(normalizedUserId);
        renderMobileContactsStrip();
        updateContactInfoPanel(normalizedUserId);
        updateBlockButtonState(normalizedUserId);
        updateBlockedChatUi(normalizedUserId);
        updateCallButtonState(normalizedUserId);
        updateAddMembersButtonState(normalizedUserId);
        updateChatSearchButtonState(normalizedUserId);
        requestAnimationFrame(updateHeaderOverflow);
    }

