        // Show step 1
        if (changePasswordStep1) changePasswordStep1.style.display = 'block';
        if (changePasswordStep2) changePasswordStep2.style.display = 'none';
        if (changePasswordNext) changePasswordNext.style.display = 'inline-flex';
        if (changePasswordSubmit) changePasswordSubmit.style.display = 'none';
        
        changePasswordModal.classList.add('open');
        changePasswordModal.setAttribute('aria-hidden', 'false');
    }

    function closeChangePasswordModal() {
        if (!changePasswordModal) return;
        changePasswordModal.classList.remove('open');
        changePasswordModal.setAttribute('aria-hidden', 'true');
    }

    if (changePasswordBtn) {
        changePasswordBtn.addEventListener('click', () => {
            openChangePasswordModal();
        });
