    if (changePasswordNext) {
        changePasswordNext.addEventListener('click', async () => {
            const currentPassword = currentPasswordInput ? currentPasswordInput.value : '';
            
            if (!currentPassword) {
                if (changePasswordError) {
                    changePasswordError.textContent = 'Please enter your current password.';
                    changePasswordError.style.display = 'block';
                }
                return;
            }

            // Verify current password
            try {
                const res = await fetch('verify_password.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ token, password: currentPassword })
                });
                
                if (!res.ok) {
                    throw new Error(`Server returned ${res.status}`);
                }
                
                const data = await res.json();

                if (data && data.success) {
                    // Password correct, show step 2
                    if (changePasswordError) changePasswordError.style.display = 'none';
                    if (changePasswordStep1) changePasswordStep1.style.display = 'none';
                    if (changePasswordStep2) changePasswordStep2.style.display = 'block';
                    if (changePasswordNext) changePasswordNext.style.display = 'none';
                    if (changePasswordSubmit) changePasswordSubmit.style.display = 'inline-flex';
                } else {
                    // Password incorrect
                    if (changePasswordError) {
                        changePasswordError.textContent = 'Invalid password.';
                        changePasswordError.style.display = 'block';
                    }
                }
            } catch (err) {
                console.error('Error verifying password:', err);
                if (changePasswordError) {
                    changePasswordError.textContent = 'Network error. Please try again.';
                    changePasswordError.style.display = 'block';
                }
            }
        });
