    // Change Email Modal
    function maskEmail(email) {
        if (!email || typeof email !== 'string') return '••••••••';
        
        const atIndex = email.indexOf('@');
        if (atIndex === -1) return '••••••••';
        
        const localPart = email.substring(0, atIndex);
        const domainPart = email.substring(atIndex);
        
        if (localPart.length <= 4) {
            // If 4 or fewer characters, show first char + asterisks
            return localPart.charAt(0) + '*'.repeat(Math.max(7, localPart.length - 1)) + domainPart;
        } else {
            // Show first 4 characters + asterisks for the rest
            const visiblePart = localPart.substring(0, 4);
            const hiddenLength = localPart.length - 4;
            return visiblePart + '*'.repeat(hiddenLength) + domainPart;
        }
    }
    
