        }
        if (typingPresenceDot) {
            typingPresenceDot.classList.remove('typing');
        }
        if (typingDots) {
            typingDots.classList.remove('active');
        }
        typingIndicatorUser = null;
        if (previousTypingUser) {
            refreshPresenceIndicatorsForUser(previousTypingUser);
        }
    }

    function showTypingIndicator(userId) {
        if (!typingIndicator || !getAppSetting('typingIndicators')) {
            hideTypingIndicator();
            return;
        }
        
        // Handle group chats differently
        if (isGroupChatKey(String(userId || ''))) {
            showGroupTypingIndicator(userId);
            return;
        }

        const meta = getContactMeta(userId);
        const username = getDisplayNameForUser(userId, meta);
        try {
            const contactEl = getContactElement(userId);
            const contactImg = contactEl ? contactEl.querySelector('.contact-img') : null;
            const profilePic = userProfilePics[userId] || (contactImg ? contactImg.src : defaultProfilePic);
            const isOnline = getResolvedContactOnlineState(userId, contactEl);

            if (typingAvatar) {
                typingAvatar.src = profilePic;
                typingAvatar.alt = username;
            }

            if (typingPresenceDot) {
                if (isOnline) {
                    typingPresenceDot.classList.add('online');
                } else {
                    typingPresenceDot.classList.remove('online');
                }
                typingPresenceDot.classList.add('typing');
            }
        } catch (e) {
            console.error('Typing presence render failed:', e);
        }

        typingIndicator.textContent = `${getDisplayNameForUser(userId, { displayName: username })} is typing...`;
        typingIndicator.classList.add('active');
        if (typingPresence) {
            typingPresence.classList.add('active');
            typingPresence.classList.remove('group-typing');
        }
        if (typingDots) {
            typingDots.classList.add('active');
        }
        typingIndicatorUser = String(userId);
        refreshPresenceIndicatorsForUser(userId);
    }

    function showSyntheticTypingIndicator(indicatorKey, displayName, profilePic, isOnline = true) {
        if (!typingIndicator || !getAppSetting('typingIndicators')) {
            hideTypingIndicator();
            return '';
        }

        const normalizedKey = String(indicatorKey || '').trim();
        const normalizedName = String(displayName || 'QuillTalk AI').trim() || 'QuillTalk AI';
        const normalizedProfilePic = normalizeProfilePic(profilePic || DEFAULT_AI_PROFILE_PIC, 'direct');

        if (typingAvatar) {
            typingAvatar.src = normalizedProfilePic;
            typingAvatar.alt = normalizedName;
        }

        if (typingPresenceDot) {
            typingPresenceDot.classList.toggle('online', !!isOnline);
            typingPresenceDot.classList.add('typing');
        }

        typingIndicator.textContent = `${normalizedName} is typing...`;
        typingIndicator.classList.add('active');
        if (typingPresence) {
            typingPresence.classList.add('active');
            typingPresence.classList.remove('group-typing');
        }
        if (typingDots) {
            typingDots.classList.add('active');
        }
        typingIndicatorUser = normalizedKey;
        return normalizedKey;
    }

    function showAiTypingIndicator(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return '';
        }

        const identity = getAiAssistantIdentityForChat(normalizedChatKey);
        return showSyntheticTypingIndicator(
            `__qt_ai_typing__:${normalizedChatKey}`,
            identity.displayName,
            identity.profilePic,
            true
        );
    }

    function hideTypingIndicatorByKey(indicatorKey = '') {
        const normalizedKey = String(indicatorKey || '').trim();
        if (normalizedKey && String(typingIndicatorUser || '') === normalizedKey) {
            hideTypingIndicator();
        }
    }
    
    function showGroupTypingIndicator(groupKey) {
        if (!typingIndicator || !groupTypingUsers[groupKey]) {
            hideTypingIndicator();
            return;
        }
        
        const typers = getActiveGroupTypingEntries(groupKey);
        
        if (typers.length === 0) {
            hideTypingIndicator();
            return;
        }
        
        const text = getGroupTypingSummaryText(groupKey, typers);
        
        typingIndicator.textContent = text;
        typingIndicator.classList.add('active');
        
        // Keep the parent visible; the group class hides only the direct-message avatar.
        if (typingPresence) {
            typingPresence.classList.add('active');
            typingPresence.classList.add('group-typing');
        }
        if (typingDots) {
            typingDots.classList.add('active');
        }
        typingIndicatorUser = String(groupKey);
    }

    async function sendTypingState(chatKey, isTyping) {
        if (!chatKey) return;
        if (isTyping && !getAppSetting('typingIndicators')) return;
        
        const chatType = getChatTypeFromKey(chatKey);
        if (chatType === 'ai') {
            return;
        }

        try {
            if (chatType === 'group') {
                // Send group typing status
                const groupId = getGroupIdFromChatKey(chatKey);
                const body = new FormData();
                body.append('token', token);
                body.append('group_id', groupId);
                body.append('is_typing', isTyping ? '1' : '0');

                const res = await fetch('group_typing_status.php', {
                    method: 'POST',
                    body
                });

                if (!res.ok) {
                    console.error('Group typing state update returned status', res.status);
                }
            } else {
                // Send direct chat typing status
                const body = new FormData();
                body.append('token', token);
                body.append('with', chatKey);
                body.append('is_typing', isTyping ? '1' : '0');

                const res = await fetch('typing_status.php', {
                    method: 'POST',
                    body
                });

                if (!res.ok) {
                    console.error('Typing state update returned status', res.status);
                }
            }
        } catch (e) {
            console.error('Typing state update failed:', e);
        }
    }

    function clearLocalTyping(notifyServer = true) {
        if (typingStopTimeout) {
            clearTimeout(typingStopTimeout);
            typingStopTimeout = null;
        }

        if (notifyServer && localTypingUser) {
            sendTypingState(localTypingUser, false);
        }

        localTypingUser = null;
        lastTypingPingAt = 0;
    }

    function scheduleTypingStop(friendId) {
        if (typingStopTimeout) {
            clearTimeout(typingStopTimeout);
        }

        typingStopTimeout = setTimeout(() => {
            if (localTypingUser && String(localTypingUser) === String(friendId)) {
                sendTypingState(friendId, false);
                localTypingUser = null;
                lastTypingPingAt = 0;
            }
        }, TYPING_IDLE_MS);
    }

    function handleTypingInput() {
        if (!selectedUser || !messageInput) return;
        const chatType = getChatTypeFromKey(selectedUser);
        if (chatType === 'group' && getGroupIdFromChatKey(selectedUser) <= 0) {
            clearLocalTyping(true);
            return;
        }
        if (chatType === 'ai') {
            clearLocalTyping(true);
            return;
        }
        if (chatType === 'direct' && isConversationBlocked(selectedUser)) {
            clearLocalTyping(true);
            return;
        }
        if (!getAppSetting('typingIndicators')) {
            clearLocalTyping(true);
            return;
        }

        const text = messageInput.value.trim();
        if (!text) {
            clearLocalTyping(true);
            return;
        }

        const now = Date.now();
        const switchedChats = localTypingUser && String(localTypingUser) !== String(selectedUser);

        if (switchedChats) {
            sendTypingState(localTypingUser, false);
            localTypingUser = null;
            lastTypingPingAt = 0;
        }

        if (!localTypingUser || (now - lastTypingPingAt) >= TYPING_PING_MS) {
            sendTypingState(selectedUser, true);
            localTypingUser = selectedUser;
            lastTypingPingAt = now;
        }

        scheduleTypingStop(selectedUser);
    }

    function getEmojiPickerCategories() {
        return [EMOJI_FAVORITES_CATEGORY].concat(EMOJI_PICKER_FULL_CATEGORIES);
    }

    function getEmojiPickerSearchQuery() {
        return emojiPickerSearch ? emojiPickerSearch.value.trim() : '';
    }

    function isFlagEmojiRecord(emojiObj) {
        return !!(emojiObj && Number(emojiObj.group) === EMOJI_GROUP.FLAGS);
    }

    function getEmojiCodepointSlug(emoji) {
        return Array.from(String(emoji || ''))
            .map(char => char.codePointAt(0).toString(16))
            .join('-');
    }

    function getEmojiImageUrl(emojiObj) {
        if (!isFlagEmojiRecord(emojiObj)) {
            return '';
        }

        const slug = getEmojiCodepointSlug(emojiObj.emoji);
        return slug ? `${TWEMOJI_CDN_BASE}/${slug}.svg` : '';
    }

    function buildDefaultEmojiTooltipText(emojiObj) {
        const preferredShortcode = Array.isArray(emojiObj && emojiObj.shortcodes) && emojiObj.shortcodes.length
            ? String(emojiObj.shortcodes[0] || '').trim()
            : '';
        const fallbackName = String(emojiObj && emojiObj.label ? emojiObj.label : '')
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '_')
            .replace(/^_+|_+$/g, '');
        const tooltipName = preferredShortcode || fallbackName || 'emoji';
        return `:${tooltipName}:\nDefault emoji`;
    }

    let pinnedEmojiTooltipAnchor = null;

    function getEmojiHoverTooltipElement() {
        return document.getElementById('emojiHoverTooltip');
    }

    function isEmojiHoverTooltipPinned(anchorEl = null) {
        return !!(pinnedEmojiTooltipAnchor && (!anchorEl || pinnedEmojiTooltipAnchor === anchorEl));
    }

    function clearPinnedEmojiHoverTooltip(anchorEl = null) {
        if (anchorEl && pinnedEmojiTooltipAnchor !== anchorEl) {
            return;
        }

        if (pinnedEmojiTooltipAnchor) {
            pinnedEmojiTooltipAnchor.classList.remove('is-tooltip-pinned');
            pinnedEmojiTooltipAnchor.setAttribute('aria-pressed', 'false');
        }

        pinnedEmojiTooltipAnchor = null;
        const tooltip = getEmojiHoverTooltipElement();
        if (tooltip) {
            tooltip.dataset.pinned = '0';
        }
    }

    function positionEmojiHoverTooltip(tooltip, anchorEl) {
        if (!tooltip || !anchorEl) {
            return;
        }

        const rect = anchorEl.getBoundingClientRect();
        const tooltipWidth = tooltip.offsetWidth || 160;
        const tooltipHeight = tooltip.offsetHeight || 48;
        let left = rect.left + (rect.width / 2) - (tooltipWidth / 2);
        let top = rect.top - tooltipHeight - 8;

        if (left < 6) {
            left = 6;
        }
        if (left + tooltipWidth > window.innerWidth - 6) {
            left = window.innerWidth - tooltipWidth - 6;
        }
        if (top < 6) {
            top = rect.bottom + 8;
        }

        tooltip.style.left = `${left}px`;
        tooltip.style.top = `${top}px`;
    }

    function renderEmojiHoverTooltipContent(tooltip, emojiValue, tooltipText) {
        if (!tooltip) {
            return;
        }

        const lines = String(tooltipText || '')
            .split(/\n+/)
            .map(line => line.trim())
            .filter(Boolean);
        const titleText = lines[0] || String(tooltipText || '').trim();
        const subtitleText = lines.slice(1).join(' ');

        tooltip.textContent = '';

        const content = document.createElement('div');
        content.className = 'emoji-hover-tooltip-content';

        if (emojiValue) {
            const icon = document.createElement('span');
            icon.className = 'emoji-hover-tooltip-icon';
            icon.textContent = emojiValue;
            content.appendChild(icon);
        }

        const copy = document.createElement('div');
        copy.className = 'emoji-hover-tooltip-copy';

        const title = document.createElement('span');
        title.className = 'emoji-hover-tooltip-title';
        title.textContent = titleText || 'emoji';
        copy.appendChild(title);

        if (subtitleText) {
            const subtitle = document.createElement('span');
            subtitle.className = 'emoji-hover-tooltip-subtitle';
            subtitle.textContent = subtitleText;
            copy.appendChild(subtitle);
        }

        content.appendChild(copy);
        tooltip.appendChild(content);
    }

    function hideEmojiHoverTooltip(options = {}) {
        const tooltip = getEmojiHoverTooltipElement();
        if (!tooltip) {
            return;
        }

        const normalizedOptions = typeof options === 'boolean'
            ? { force: options }
            : (options || {});
        const force = !!normalizedOptions.force;
        const anchorEl = normalizedOptions.anchorEl || null;

        if (!force && isEmojiHoverTooltipPinned(anchorEl)) {
            return;
        }

        if (force && (!anchorEl || pinnedEmojiTooltipAnchor === anchorEl)) {
            clearPinnedEmojiHoverTooltip(anchorEl);
        }

        tooltip.style.display = 'none';
        tooltip.setAttribute('aria-hidden', 'true');
    }

    function showEmojiHoverTooltip(anchorEl, tooltipText, options = {}) {
        const tooltip = getEmojiHoverTooltipElement();
        if (!tooltip || !anchorEl || !tooltipText) {
            return;
        }

        if (pinnedEmojiTooltipAnchor && pinnedEmojiTooltipAnchor !== anchorEl && !options.allowPinnedOverride) {
            return;
        }

        const emojiValue = String(options.emojiValue || anchorEl.dataset.emojiValue || '').trim();
        renderEmojiHoverTooltipContent(tooltip, emojiValue, tooltipText);
        tooltip.style.display = 'block';
        tooltip.setAttribute('aria-hidden', 'false');
        tooltip.dataset.pinned = options.pinned ? '1' : (isEmojiHoverTooltipPinned(anchorEl) ? '1' : '0');
        positionEmojiHoverTooltip(tooltip, anchorEl);

        if (options.pinned) {
            if (pinnedEmojiTooltipAnchor && pinnedEmojiTooltipAnchor !== anchorEl) {
                clearPinnedEmojiHoverTooltip();
            }
            pinnedEmojiTooltipAnchor = anchorEl;
            pinnedEmojiTooltipAnchor.classList.add('is-tooltip-pinned');
            pinnedEmojiTooltipAnchor.setAttribute('aria-pressed', 'true');
        }
    }

    function togglePinnedEmojiHoverTooltip(anchorEl) {
        if (!anchorEl) {
            return;
        }

        const tooltipText = anchorEl.dataset.emojiTooltip || '';
        if (!tooltipText) {
            return;
        }

        if (isEmojiHoverTooltipPinned(anchorEl)) {
            hideEmojiHoverTooltip({ force: true, anchorEl });
            return;
        }

        clearPinnedEmojiHoverTooltip();
        showEmojiHoverTooltip(anchorEl, tooltipText, {
            emojiValue: anchorEl.dataset.emojiValue || '',
            pinned: true,
            allowPinnedOverride: true
        });
    }

    function bindEmojiHoverTooltip(button, emojiObj, options = {}) {
        if (!button || !emojiObj) {
            return;
        }

        const tooltipText = buildDefaultEmojiTooltipText(emojiObj);
        if (!tooltipText) {
            return;
        }

        button.dataset.emojiTooltip = tooltipText;
        button.dataset.emojiValue = String(emojiObj.emoji || button.dataset.emojiValue || '').trim();
        button.dataset.emojiTooltipAllowPinnedToggle = options.allowPinnedToggle ? '1' : '0';
        button.title = tooltipText.replace(/\s*\n+\s*/g, ' ');

        if (button.dataset.emojiTooltipEventsBound === '1') {
            return;
        }

        button.dataset.emojiTooltipEventsBound = '1';

        const showTooltip = () => {
            showEmojiHoverTooltip(button, button.dataset.emojiTooltip || '', {
                emojiValue: button.dataset.emojiValue || '',
                allowPinnedOverride: isEmojiHoverTooltipPinned(button)
            });
        };

        button.addEventListener('mouseenter', showTooltip);
        button.addEventListener('mouseleave', () => {
            hideEmojiHoverTooltip({ anchorEl: button });
        });
        button.addEventListener('focus', showTooltip);
        button.addEventListener('blur', () => {
            hideEmojiHoverTooltip({ anchorEl: button });
        });

        if (button.dataset.emojiTooltipAllowPinnedToggle !== '1') {
            button.addEventListener('pointerdown', () => {
                hideEmojiHoverTooltip({ force: true });
            });
        }
    }

    function bindEmojiHoverTooltipDelegation(container) {
        if (!container || container.dataset.emojiTooltipBound === '1') {
            return;
        }

        container.dataset.emojiTooltipBound = '1';

        const findTooltipButton = target => {
            return target && typeof target.closest === 'function'
                ? target.closest('.emoji-picker-emoji[data-emoji-tooltip], .emoji-item[data-emoji-tooltip]')
                : null;
        };

        container.addEventListener('pointerover', event => {
            const button = findTooltipButton(event.target);
            if (!button) {
                return;
            }
            showEmojiHoverTooltip(button, button.dataset.emojiTooltip || '', {
                emojiValue: button.dataset.emojiValue || '',
                allowPinnedOverride: isEmojiHoverTooltipPinned(button)
            });
        });

        container.addEventListener('pointermove', event => {
            const button = findTooltipButton(event.target);
            if (!button) {
                return;
            }
            showEmojiHoverTooltip(button, button.dataset.emojiTooltip || '', {
                emojiValue: button.dataset.emojiValue || '',
                allowPinnedOverride: isEmojiHoverTooltipPinned(button)
            });
        });

        container.addEventListener('pointerout', event => {
            const button = findTooltipButton(event.target);
            if (!button) {
                return;
            }
            const relatedTarget = event.relatedTarget;
            if (relatedTarget && button.contains(relatedTarget)) {
                return;
            }
            hideEmojiHoverTooltip({ anchorEl: button });
        });

        container.addEventListener('focusin', event => {
            const button = findTooltipButton(event.target);
            if (!button) {
                return;
            }
            showEmojiHoverTooltip(button, button.dataset.emojiTooltip || '', {
                emojiValue: button.dataset.emojiValue || '',
                allowPinnedOverride: isEmojiHoverTooltipPinned(button)
            });
        });

        container.addEventListener('focusout', () => {
            hideEmojiHoverTooltip({ force: true });
        });
        container.addEventListener('pointerdown', () => {
            hideEmojiHoverTooltip({ force: true });
        });
        container.addEventListener('scroll', () => {
            hideEmojiHoverTooltip({ force: true });
        }, { passive: true });
    }

    function getEmojiTooltipRecord(emojiValue) {
        const normalizedEmoji = String(emojiValue || '').trim();
        if (!normalizedEmoji) {
            return null;
        }

        return emojiByValue.get(normalizedEmoji) || {
            emoji: normalizedEmoji,
            label: '',
            shortcodes: []
        };
    }

    function bindInlineMessageEmojiTooltip(target, emojiValue) {
        if (!target) {
            return;
        }

        const normalizedEmoji = String(emojiValue || '').trim();
        if (!normalizedEmoji) {
            return;
        }

        const emojiRecord = getEmojiTooltipRecord(normalizedEmoji);
        if (!emojiRecord) {
            return;
        }

        target.classList.add('message-inline-emoji');
        target.dataset.emojiValue = normalizedEmoji;
        target.dataset.emojiTooltipToggle = '1';
        target.setAttribute('role', 'button');
        target.setAttribute('tabindex', '0');
        target.setAttribute('aria-label', `Show emoji details for ${emojiRecord.label || normalizedEmoji}`);
        target.setAttribute('aria-pressed', isEmojiHoverTooltipPinned(target) ? 'true' : 'false');
        bindEmojiHoverTooltip(target, emojiRecord, { allowPinnedToggle: true });

        if (target.dataset.emojiTooltipToggleBound === '1') {
            return;
        }

        target.dataset.emojiTooltipToggleBound = '1';
        addTapAndClickListener(target, event => {
            event.preventDefault();
            event.stopPropagation();
            togglePinnedEmojiHoverTooltip(target);
        });
        target.addEventListener('keydown', event => {
            if (event.key !== 'Enter' && event.key !== ' ') {
                return;
            }
            event.preventDefault();
            event.stopPropagation();
            togglePinnedEmojiHoverTooltip(target);
        });
    }

    function decorateInlineEmojiText(rootEl) {
        if (!rootEl) {
            return;
        }

        rootEl.querySelectorAll('.message-inline-emoji').forEach(node => {
            bindInlineMessageEmojiTooltip(node, node.dataset.emojiValue || node.textContent || '');
        });

        if (!emojiInlinePattern) {
            return;
        }

        const textNodes = [];
        const walker = document.createTreeWalker(rootEl, NodeFilter.SHOW_TEXT, {
            acceptNode(node) {
                if (!node || !node.nodeValue || !node.parentElement || node.parentElement.closest('.message-inline-emoji')) {
                    return NodeFilter.FILTER_REJECT;
                }

                emojiInlinePattern.lastIndex = 0;
                const hasEmoji = emojiInlinePattern.test(node.nodeValue);
                emojiInlinePattern.lastIndex = 0;
                return hasEmoji ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
            }
        });

        let currentNode = walker.nextNode();
        while (currentNode) {
            textNodes.push(currentNode);
            currentNode = walker.nextNode();
        }

        textNodes.forEach(node => {
            const rawText = String(node.nodeValue || '');
            if (!rawText || !node.parentNode) {
                return;
            }

            const fragment = document.createDocumentFragment();
            let lastIndex = 0;
            let hasEmoji = false;
            let match;

            emojiInlinePattern.lastIndex = 0;
            while ((match = emojiInlinePattern.exec(rawText)) !== null) {
                const matchedEmoji = String(match[0] || '');
                if (!matchedEmoji) {
                    emojiInlinePattern.lastIndex += 1;
                    continue;
                }

                hasEmoji = true;
                if (match.index > lastIndex) {
                    fragment.appendChild(document.createTextNode(rawText.slice(lastIndex, match.index)));
                }

                const emojiSpan = document.createElement('span');
                emojiSpan.textContent = matchedEmoji;
                bindInlineMessageEmojiTooltip(emojiSpan, matchedEmoji);
                fragment.appendChild(emojiSpan);
                lastIndex = match.index + matchedEmoji.length;
            }
            emojiInlinePattern.lastIndex = 0;

            if (!hasEmoji) {
                return;
            }

            if (lastIndex < rawText.length) {
                fragment.appendChild(document.createTextNode(rawText.slice(lastIndex)));
            }

            node.parentNode.replaceChild(fragment, node);
        });
    }

    function refreshRenderedMessageEmojiTooltips() {
        if (!chatBox) {
            return;
        }

        chatBox.querySelectorAll('.message-text-content, .message-text').forEach(textNode => {
            decorateInlineEmojiText(textNode);
        });
    }

    document.addEventListener('pointerdown', event => {
        if (!pinnedEmojiTooltipAnchor) {
            return;
        }

        const target = event.target;
        if (target && pinnedEmojiTooltipAnchor.contains(target)) {
            return;
        }

        hideEmojiHoverTooltip({ force: true });
    });

    document.addEventListener('keydown', event => {
        if (event.key !== 'Escape' || !pinnedEmojiTooltipAnchor) {
            return;
        }

        hideEmojiHoverTooltip({ force: true });
    });

    window.addEventListener('resize', () => {
        if (!pinnedEmojiTooltipAnchor) {
            return;
        }

        showEmojiHoverTooltip(pinnedEmojiTooltipAnchor, pinnedEmojiTooltipAnchor.dataset.emojiTooltip || '', {
            emojiValue: pinnedEmojiTooltipAnchor.dataset.emojiValue || '',
            pinned: true,
            allowPinnedOverride: true
        });
    });

    window.addEventListener('scroll', () => {
        if (!pinnedEmojiTooltipAnchor) {
            return;
        }

        hideEmojiHoverTooltip({ force: true });
    }, true);

    function resolveActiveEmojiCategory(categoryKey = activeEmojiCategory) {
        const categories = getEmojiPickerCategories();
        const category = categories.find(item => item.key === categoryKey) || categories[0] || null;
        activeEmojiCategory = category ? category.key : EMOJI_FAVORITES_CATEGORY.key;
        return { categories, category };
    }

    function getEmojiRecordsForCategory(category) {
        if (!category) {
            return [];
        }

        if (category.key === EMOJI_FAVORITES_CATEGORY.key) {
            return getFavoriteEmojiRecords(80);
        }

        const allowedGroups = new Set(category.groups || []);
        return emojiData.filter(emojiObj => (
            allowedGroups.has(emojiObj.group)
            || (emojiObj.group == null && category.key === 'objects')
        ));
    }

    function buildEmojiPickerButton(emojiObj) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'emoji-picker-emoji';
        button.setAttribute('aria-label', `Insert ${emojiObj.label || emojiObj.emoji}`);
        bindEmojiHoverTooltip(button, emojiObj);
        button.addEventListener('mousedown', (event) => {
            event.preventDefault();
        });
        addTapAndClickListener(button, () => {
            insertEmojiIntoMessage(emojiObj.emoji);
            saveRecentEmoji(emojiObj.emoji);
        });

        const imageUrl = getEmojiImageUrl(emojiObj);
        if (imageUrl) {
            const image = document.createElement('img');
            image.className = 'emoji-picker-emoji-image';
            image.src = imageUrl;
            image.alt = emojiObj.label || emojiObj.emoji;
            button.appendChild(image);
        } else {
            const glyph = document.createElement('span');
            glyph.className = 'emoji-picker-emoji-glyph';
            glyph.textContent = emojiObj.emoji;
            button.appendChild(glyph);
        }

        return button;
    }

    function buildEmojiPickerSection(category, emojisToShow) {
        const section = document.createElement('section');
        section.className = 'emoji-picker-section';
        section.dataset.categoryKey = category.key;

        const title = document.createElement('div');
        title.className = 'emoji-picker-section-title';
        title.textContent = category.label;

        const grid = document.createElement('div');
        grid.className = 'emoji-picker-section-grid';

        if (!emojisToShow.length) {
            const empty = document.createElement('div');
            empty.className = 'emoji-picker-empty';
            empty.textContent = category.key === EMOJI_FAVORITES_CATEGORY.key
                ? 'Use a few emojis and your favorites will show up here.'
                : 'No emojis in this category yet.';
            grid.appendChild(empty);
        } else {
            emojisToShow.forEach(emojiObj => {
                grid.appendChild(buildEmojiPickerButton(emojiObj));
            });
        }

        section.appendChild(title);
        section.appendChild(grid);
        return section;
