    function renderEmojiPickerSearchResults(searchQuery) {
        const emojisToShow = emojiData
            .map(emoji => ({ emoji, score: scoreEmojiCandidate(emoji, searchQuery) }))
            .filter(entry => entry.score >= 0)
            .sort((a, b) => b.score - a.score || a.emoji.order - b.emoji.order)
            .slice(0, 200)
            .map(entry => entry.emoji);

        if (!emojisToShow.length) {
            const empty = document.createElement('div');
            empty.className = 'emoji-picker-empty';
            empty.textContent = `No emojis matched "${getEmojiPickerSearchQuery()}".`;
            emojiGrid.appendChild(empty);
            return;
        }

        const section = document.createElement('section');
        section.className = 'emoji-picker-section';
        const title = document.createElement('div');
        title.className = 'emoji-picker-section-title';
        title.textContent = 'Search results';
        const grid = document.createElement('div');
        grid.className = 'emoji-picker-section-grid';

        emojisToShow.forEach(emojiObj => {
            grid.appendChild(buildEmojiPickerButton(emojiObj));
        });

        section.appendChild(title);
        section.appendChild(grid);
        emojiGrid.appendChild(section);
    }

    function syncActiveEmojiCategoryFromScroll() {
        if (!emojiGrid || normalizeEmojiSearchValue(getEmojiPickerSearchQuery())) {
            return;
        }

        const sections = Array.from(emojiGrid.querySelectorAll('.emoji-picker-section[data-category-key]'));
        if (!sections.length) {
            return;
        }

        const scrollTop = emojiGrid.scrollTop;
        let nextActiveKey = sections[0].dataset.categoryKey || EMOJI_FAVORITES_CATEGORY.key;
        sections.forEach(section => {
            if ((section.offsetTop - 28) <= scrollTop) {
                nextActiveKey = section.dataset.categoryKey || nextActiveKey;
            }
        });

        if (nextActiveKey && nextActiveKey !== activeEmojiCategory) {
            activeEmojiCategory = nextActiveKey;
            renderEmojiPickerTabs();
        }
    }

    function scrollEmojiCategoryIntoView(categoryKey) {
        if (!emojiGrid) {
            return;
        }

        if (emojiPickerSearch && emojiPickerSearch.value.trim()) {
            emojiPickerSearch.value = '';
            renderEmojiPickerGrid(categoryKey);
        }

        const targetSection = emojiGrid.querySelector(`.emoji-picker-section[data-category-key="${categoryKey}"]`);
        if (!targetSection) {
            return;
        }

        activeEmojiCategory = categoryKey;
        renderEmojiPickerTabs();
        emojiGrid.scrollTo({
            top: Math.max(0, targetSection.offsetTop - 2),
            behavior: 'smooth'
        });
    }

    function renderEmojiPickerGrid(categoryKey = activeEmojiCategory) {
        if (!emojiGrid) {
            return;
        }

        const { categories } = resolveActiveEmojiCategory(categoryKey);
        const searchQuery = normalizeEmojiSearchValue(getEmojiPickerSearchQuery());
        emojiGrid.innerHTML = '';

        if (!emojiData.length) {
            const empty = document.createElement('div');
            empty.className = 'emoji-picker-empty';
            empty.textContent = 'Loading emojis...';
            emojiGrid.appendChild(empty);
            return;
        }

        if (searchQuery) {
            renderEmojiPickerSearchResults(searchQuery);
            return;
        }

        categories.forEach(category => {
            emojiGrid.appendChild(buildEmojiPickerSection(category, getEmojiRecordsForCategory(category)));
        });

        requestAnimationFrame(() => {
            syncActiveEmojiCategoryFromScroll();
        });
    }

