        const { categories } = resolveActiveEmojiCategory();
        emojiCategoryTabs.innerHTML = '';
        categories.forEach(category => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'emoji-picker-tab' + (category.key === activeEmojiCategory ? ' active' : '');
        button.title = category.label;
        button.setAttribute('aria-label', category.label);
        button.innerHTML = `<i class="${category.icon}" aria-hidden="true"></i>`;
        addTapAndClickListener(button, () => {
            scrollEmojiCategoryIntoView(category.key);
        });
        emojiCategoryTabs.appendChild(button);
    });
    }

    function getReactPickerSearchQuery() {
        return reactPickerSearchInput ? reactPickerSearchInput.value.trim() : '';
    }

    function resolveActiveReactPickerCategory(categoryKey = reactPickerActiveCategory) {
        const categories = getEmojiPickerCategories();
        const category = categories.find(item => item.key === categoryKey) || categories[0] || null;
        reactPickerActiveCategory = category ? category.key : EMOJI_FAVORITES_CATEGORY.key;
        return { categories, category };
