    function buildReactPickerEmojiButton(emojiObj) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'emoji-picker-emoji react-picker-emoji';
        button.setAttribute('aria-label', `React with ${emojiObj.label || emojiObj.emoji}`);
        bindEmojiHoverTooltip(button, emojiObj);
        button.classList.toggle('selected', reactPickerSelectedEmojis.has(emojiObj.emoji));
        button.addEventListener('mousedown', event => {
            event.preventDefault();
        });
        addTapAndClickListener(button, () => {
            if (reactPickerSelectedEmojis.has(emojiObj.emoji)) {
                reactPickerSelectedEmojis.delete(emojiObj.emoji);
            } else {
                reactPickerSelectedEmojis.add(emojiObj.emoji);
            }
            button.classList.toggle('selected', reactPickerSelectedEmojis.has(emojiObj.emoji));
            syncReactPickerApplyButton();
        });

        const imageUrl = getEmojiImageUrl(emojiObj);
        if (imageUrl) {
            const image = document.createElement('img');
            image.className = 'emoji-picker-emoji-image';
            image.src = imageUrl;
            image.alt = emojiObj.label || emojiObj.emoji;
            button.appendChild(image);
        } else {
            const glyph = document.createElement('span');
            glyph.className = 'emoji-picker-emoji-glyph';
            glyph.textContent = emojiObj.emoji;
            button.appendChild(glyph);
        }

        return button;
    }

