    function setEmojiPickerOpen(isOpen) {
        if (!emojiPickerGrid || !emojiBtn) {
            return;
        }

        hideEmojiHoverTooltip();
        emojiPickerGrid.classList.toggle('active', isOpen);
        emojiPickerGrid.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
        emojiBtn.classList.toggle('open', isOpen);
        emojiBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');

        if (isOpen) {
            activeEmojiCategory = EMOJI_FAVORITES_CATEGORY.key;
            if (emojiPickerSearch) {
                emojiPickerSearch.value = '';
            }
            renderEmojiPickerTabs();
            renderEmojiPickerGrid(activeEmojiCategory);
            if (emojiGrid) {
                emojiGrid.scrollTop = 0;
            }
            if (emojiPickerSearch) {
                window.setTimeout(() => {
                    if (emojiPickerSearch && emojiPickerGrid && emojiPickerGrid.classList.contains('active')) {
                        emojiPickerSearch.focus();
                    }
                }, 30);
            }
        } else if (emojiPickerSearch) {
            emojiPickerSearch.value = '';
        }
    }

    function hideEmojiPicker() {
        setEmojiPickerOpen(false);
    }

    function toggleEmojiPicker() {
        if (!emojiPickerGrid) {
            return;
        }

        setEmojiPickerOpen(!emojiPickerGrid.classList.contains('active'));
    }

    function insertEmojiIntoMessage(emoji) {
        if (!messageInput) {
            return;
        }

        const value = messageInput.value || '';
        const start = typeof lastMessageSelectionStart === 'number'
            ? lastMessageSelectionStart
            : (typeof messageInput.selectionStart === 'number' ? messageInput.selectionStart : value.length);
        const end = typeof lastMessageSelectionEnd === 'number'
            ? lastMessageSelectionEnd
            : (typeof messageInput.selectionEnd === 'number' ? messageInput.selectionEnd : start);
        const safeStart = Math.max(0, Math.min(value.length, start));
        const safeEnd = Math.max(safeStart, Math.min(value.length, end));
        const nextValue = value.slice(0, safeStart) + emoji + value.slice(safeEnd);
        const nextCursor = safeStart + emoji.length;

        messageInput.value = nextValue;
        messageInput.focus();
        messageInput.setSelectionRange(nextCursor, nextCursor);
        rememberMessageSelection();
        messageInput.dispatchEvent(new Event('input', { bubbles: true }));
    }

    async function pollTypingState() {
        const chatType = selectedUser ? getChatTypeFromKey(selectedUser) : '';
        if (
            !selectedUser
            || !getAppSetting('typingIndicators')
            || (chatType === 'direct' && isConversationBlocked(selectedUser))
        ) {
            hideTypingIndicator();
            return;
        }

        if (chatType === 'ai') {
            const expectedAiTypingKey = `__qt_ai_typing__:${selectedUser}`;
            if (typingIndicatorUser && String(typingIndicatorUser) !== expectedAiTypingKey) {
                hideTypingIndicator();
            }
            return;
        }

        try {
            if (chatType === 'group') {
                // Poll group typing status
                const groupId = getGroupIdFromChatKey(selectedUser);
                const res = await fetch(`group_typing_status.php?token=${encodeURIComponent(token)}&group_id=${groupId}&t=${Date.now()}`);
                if (!res.ok) {
                    console.error('Group typing poll returned status', res.status);
                    hideTypingIndicator();
                    return;
                }
                
                const data = await res.json();
                if (data.success && data.typing_users && Array.isArray(data.typing_users)) {
                    // Update group typing users
                    groupTypingUsers[selectedUser] = {};
                    const receivedAt = Date.now();
                    data.typing_users.forEach((typer, index) => {
                        if (String(typer.user_id) !== String(currentUserId)) {
                            groupTypingUsers[selectedUser][typer.user_id] = {
                                displayName: getDisplayNameForUser(typer.user_id, { displayName: typer.display_name }),
                                timestamp: receivedAt + index
                            };
                        }
                    });
                    
                    if (Object.keys(groupTypingUsers[selectedUser]).length > 0) {
                        showGroupTypingIndicator(selectedUser);
                    } else {
                        hideTypingIndicator();
                    }
                } else {
                    delete groupTypingUsers[selectedUser];
                    hideTypingIndicator();
                }
            } else {
                // Poll direct chat typing status
                const res = await fetch(`typing_status.php?token=${token}&with=${selectedUser}&t=${Date.now()}`);
                if (!res.ok) {
                    console.error('Typing indicator poll returned status', res.status);
                    hideTypingIndicator();
                    return;
                }

                const data = await res.json();
                if (data.success && data.is_typing) {
                    showTypingIndicator(selectedUser);
                } else if (typingIndicatorUser && String(typingIndicatorUser) === String(selectedUser)) {
                    hideTypingIndicator();
                }
            }
        } catch (e) {
            console.error('Typing indicator poll failed:', e);
            hideTypingIndicator();
        }
    }

    // --- Message Handling and UI ---
    function formatTimestamp(ts) {
        const parsedTimestamp = parseServerDateTimeMs(ts);
        if (!parsedTimestamp) {
            return '';
        }
        const date = new Date(parsedTimestamp);
        const now = new Date();
        const sameDay = date.toDateString() === now.toDateString();
        if (sameDay) {
            return 'Today, ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }
        const yesterday = new Date(now);
        yesterday.setDate(now.getDate() - 1);
        if (date.toDateString() === yesterday.toDateString()) {
            return 'Yesterday, ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }
        const oneWeekAgo = new Date();
        oneWeekAgo.setDate(now.getDate() - 7);
        if (date > oneWeekAgo) {
            return date.toLocaleDateString(undefined, { weekday: 'long', hour: '2-digit', minute: '2-digit' });
        }
        if (date.getFullYear() === now.getFullYear()) {
            return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
        }
        return date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
    }

    function getCallEventTitle(callEvent) {
        if (!callEvent) return 'Call';
        if (callEvent.type === 'missed') return 'Missed call';
        if (callEvent.type === 'ended') {
            return isOutgoingCallEventForUser(callEvent, currentUserId) ? 'Outgoing call' : 'Incoming call';
        }
        return 'Call';
    }

    function getCallEventSubtitle(callEvent, createdAt) {
        const formattedTimestamp = formatTimestamp(createdAt);
        if (callEvent && callEvent.type === 'missed') {
            return `No answer ${formattedTimestamp}`;
        }
        return `Ended ${formattedTimestamp}`;
    }

    function getCallEventIconType(callEvent) {
        if (!callEvent) return 'outgoing';
        if (callEvent.type === 'missed') return 'missed';
        return isOutgoingCallEventForUser(callEvent, currentUserId) ? 'outgoing' : 'incoming';
    }

    function formatAttachmentSize(bytes) {
        const normalizedBytes = Number(bytes || 0);
        if (!normalizedBytes || normalizedBytes < 1024) {
            return normalizedBytes ? `${normalizedBytes} B` : '';
        }

        const units = ['KB', 'MB', 'GB'];
        let value = normalizedBytes / 1024;
        let unitIndex = 0;

        while (value >= 1024 && unitIndex < units.length - 1) {
            value /= 1024;
            unitIndex += 1;
        }

        return `${value >= 10 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
    }

    function formatVoiceMessageDuration(totalSeconds) {
        const safeSeconds = Number.isFinite(Number(totalSeconds)) && Number(totalSeconds) > 0
            ? Math.round(Number(totalSeconds))
            : 0;
        const minutes = Math.floor(safeSeconds / 60);
        const seconds = safeSeconds % 60;
        return `${minutes}:${String(seconds).padStart(2, '0')}`;
    }

    function normalizeWaveformSamples(samples, targetCount = VOICE_WAVEFORM_BAR_COUNT) {
        const numericSamples = Array.isArray(samples)
            ? samples
                .map(sample => Number(sample))
                .filter(sample => Number.isFinite(sample) && sample >= 0)
            : [];

        if (!numericSamples.length) {
            return DEFAULT_VOICE_WAVEFORM.slice(0, targetCount);
        }

        const bucketed = [];
        for (let index = 0; index < targetCount; index += 1) {
            const start = Math.floor((index * numericSamples.length) / targetCount);
            const end = Math.floor(((index + 1) * numericSamples.length) / targetCount);
            const safeEnd = Math.max(start + 1, end);
            const chunk = numericSamples.slice(start, safeEnd);
            const average = chunk.reduce((sum, value) => sum + value, 0) / Math.max(chunk.length, 1);
            bucketed.push(average);
        }

        const peak = Math.max(...bucketed, 0.001);
        return bucketed.map(value => {
            const normalized = Math.max(0.12, Math.min(1, value / peak));
            return Number(normalized.toFixed(3));
        });
    }

    function createVoiceAttachmentMeta({ waveform = [], duration = 0 } = {}) {
        return {
            waveform: normalizeWaveformSamples(waveform),
            duration: Number.isFinite(Number(duration)) && Number(duration) > 0
                ? Number(Number(duration).toFixed(2))
                : 0
        };
    }

    function updateVoiceMessageProgress(player, progress) {
        if (!player) {
            return;
        }

        const clampedProgress = Math.max(0, Math.min(1, Number(progress || 0)));
        const bars = Array.from(player.querySelectorAll('.voice-message-bar'));
        if (!bars.length) {
            return;
        }

        const playedBars = Math.round(clampedProgress * bars.length);
        bars.forEach((bar, index) => {
            bar.classList.toggle('played', index < playedBars);
        });
    }

    function updateVoiceMessageDurationLabel(durationLabel, audio, fallbackDuration = 0, { forceProgress = false } = {}) {
        if (!durationLabel) {
            return;
        }

        const totalDuration = Math.max(0, Number((audio && audio.duration) || fallbackDuration || 0));
        const currentTime = Math.max(0, Number(audio && audio.currentTime || 0));
        const hasProgress = totalDuration > 0
            && (forceProgress || (currentTime > 0 && currentTime < totalDuration));
        const labelText = hasProgress
            ? `${formatVoiceMessageDuration(currentTime)}/${formatVoiceMessageDuration(totalDuration)}`
            : formatVoiceMessageDuration(totalDuration);

        durationLabel.textContent = labelText;
        durationLabel.title = labelText;
    }

    function setVoiceMessageButtonState(button, isPlaying) {
        if (!button) {
            return;
        }

        button.innerHTML = `<i class="fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'}"></i>`;
        button.setAttribute('aria-label', isPlaying ? 'Pause voice message' : 'Play voice message');
    }

    function pauseActiveVoiceMessage(exceptAudio = null) {
        if (activeVoiceMessageAudio && activeVoiceMessageAudio !== exceptAudio) {
            try {
                activeVoiceMessageAudio.pause();
            } catch (e) {
                console.warn('Unable to pause the active voice message.', e);
            }
        }
    }

    function resolveAttachmentUrl(rawUrl) {
        const normalizedUrl = typeof rawUrl === 'string'
            ? rawUrl.trim().replace(/\\/g, '/')
            : '';
        if (!normalizedUrl) {
            return '';
        }

        try {
            if (/^(blob:|data:|mediastream:)/i.test(normalizedUrl)) {
                return normalizedUrl;
            }

            const currentUrl = new URL(window.location.href);
            const parsedUrl = new URL(normalizedUrl, `${currentUrl.origin}/`);
            const isHttpUrl = parsedUrl.protocol === 'http:' || parsedUrl.protocol === 'https:';
            const isSameHost = parsedUrl.hostname === currentUrl.hostname;
            const isUploadPath = parsedUrl.pathname.startsWith('/uploads/');

            if ((isHttpUrl && isSameHost) || isUploadPath) {
                return `${currentUrl.origin}${parsedUrl.pathname}${parsedUrl.search}${parsedUrl.hash}`;
            }

            return parsedUrl.href;
        } catch (e) {
            console.warn('Unable to normalize attachment URL.', e);
            return normalizedUrl;
        }
    }

    function buildAttachmentRetryUrl(rawUrl) {
        const normalizedUrl = resolveAttachmentUrl(rawUrl);
        if (!normalizedUrl) {
            return '';
        }

        try {
            const parsedUrl = new URL(normalizedUrl);
            if (!/^https?:$/i.test(parsedUrl.protocol)) {
                return normalizedUrl;
            }
            parsedUrl.searchParams.set('_qtcb', String(Date.now()));
            return parsedUrl.href;
        } catch (e) {
            console.warn('Unable to build cache-busted attachment URL.', e);
            return normalizedUrl;
        }
    }

    function getAttachmentDownloadName(itemOrUrl, fallbackName = 'download') {
        if (itemOrUrl && typeof itemOrUrl === 'object' && itemOrUrl.name) {
            return String(itemOrUrl.name);
        }

        const resolvedUrl = resolveAttachmentUrl(
            itemOrUrl && typeof itemOrUrl === 'object'
                ? itemOrUrl.url
                : itemOrUrl
        );
        if (!resolvedUrl) {
            return fallbackName;
        }

        try {
            const parsedUrl = new URL(resolvedUrl, window.location.href);
            const pathnameParts = parsedUrl.pathname.split('/');
            const lastSegment = pathnameParts[pathnameParts.length - 1] || '';
            return decodeURIComponent(lastSegment) || fallbackName;
        } catch (error) {
            console.warn('Unable to derive attachment filename.', error);
            const lastSegment = String(resolvedUrl).split('/').pop() || '';
            return lastSegment.split('?')[0] || fallbackName;
        }
    }

    async function triggerAttachmentDownload(rawUrl, suggestedName = 'download') {
        const downloadUrl = resolveAttachmentUrl(rawUrl);
        if (!downloadUrl) {
            throw new Error('No attachment URL available for download.');
        }

        const finalName = suggestedName || 'download';
        const attemptUrl = buildAttachmentRetryUrl(downloadUrl);

        const clickDownloadLink = (href, { target = '', revokeUrl = '' } = {}) => {
            const downloadLink = document.createElement('a');
            downloadLink.style.display = 'none';
            downloadLink.rel = 'noopener';
            downloadLink.download = finalName;
            downloadLink.href = href;
            if (target) {
                downloadLink.target = target;
            }

            try {
                document.body.appendChild(downloadLink);
                downloadLink.click();
            } finally {
                if (downloadLink.parentNode) {
                    downloadLink.parentNode.removeChild(downloadLink);
                }
                if (revokeUrl) {
                    window.setTimeout(() => {
                        try {
                            URL.revokeObjectURL(revokeUrl);
                        } catch (error) {}
                    }, 2000);
                }
            }
        };

        let target = '';
        try {
            const parsedUrl = new URL(attemptUrl, window.location.href);
            if (parsedUrl.origin !== window.location.origin) {
                target = '_blank';
            }
        } catch (error) {
            console.warn('Unable to inspect attachment URL before download.', error);
        }

        // Trigger the browser download while the original user gesture is
        // still active. Some mobile browsers drop async blob-download flows.
        clickDownloadLink(attemptUrl, { target });
    }

    async function toggleVoiceMessagePlayback(player, triggerButton = null) {
        if (!player) {
            return;
        }

        const playBtn = triggerButton || player.querySelector('.voice-message-play');
        const audio = player.querySelector('audio');
        if (!playBtn || !audio || !audio.src) {
            return;
        }

        if (!audio.paused) {
            audio.pause();
            return;
        }

        pauseActiveVoiceMessage(audio);

        if (audio.readyState < 2) {
            const originalIcon = playBtn.innerHTML;
            playBtn.disabled = true;
            playBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';

            try {
                await new Promise((resolve, reject) => {
                    const timeout = setTimeout(() => {
                        reject(new Error('Audio load timeout'));
                    }, 10000);

                    const onCanPlay = () => {
                        clearTimeout(timeout);
                        audio.removeEventListener('canplay', onCanPlay);
                        audio.removeEventListener('error', onError);
                        resolve();
                    };

                    const onError = (event) => {
                        clearTimeout(timeout);
                        audio.removeEventListener('canplay', onCanPlay);
                        audio.removeEventListener('error', onError);
                        reject(event);
                    };

                    if (audio.readyState >= 2) {
                        clearTimeout(timeout);
                        resolve();
                    } else {
                        audio.addEventListener('canplay', onCanPlay, { once: true });
                        audio.addEventListener('error', onError, { once: true });
                        audio.load();
                    }
                });
            } catch (error) {
                console.warn('Failed to load audio:', error);
                playBtn.innerHTML = originalIcon;
                playBtn.disabled = false;
                return;
            }

            playBtn.innerHTML = originalIcon;
            playBtn.disabled = false;
        }

        try {
            await audio.play();
        } catch (error) {
            console.warn('Unable to play voice message.', error);
        }
    }

    function buildVoiceMessagePlayer(attachment) {
        const player = document.createElement('div');
        player.className = 'voice-message-player';
        
        // Mark as unheard initially (will be updated based on localStorage)
        player.classList.add('unheard');

        const playBtn = document.createElement('button');
        playBtn.type = 'button';
        playBtn.className = 'voice-message-play';
        setVoiceMessageButtonState(playBtn, false);

        const waveform = document.createElement('div');
        waveform.className = 'voice-message-waveform';

        const voiceMeta = createVoiceAttachmentMeta({
            waveform: attachment && attachment.waveform,
            duration: attachment && attachment.duration
        });

        voiceMeta.waveform.forEach(level => {
            const bar = document.createElement('span');
            bar.className = 'voice-message-bar';
            bar.style.setProperty('--voice-level', String(level));
            waveform.appendChild(bar);
        });

        const durationLabel = document.createElement('div');
        durationLabel.className = 'voice-message-duration';
        updateVoiceMessageDurationLabel(durationLabel, null, voiceMeta.duration);

        const audio = document.createElement('audio');
        audio.className = 'voice-message-audio';
        const attachmentUrl = resolveAttachmentUrl(attachment && attachment.url);
        audio.preload = 'auto'; // Changed from 'metadata' to 'auto' for better loading
        audio.playsInline = true;
        audio.playbackRate = Number(getAppSetting('voicePlaybackSpeed')) || 1;
        if (attachmentUrl) {
            audio.src = attachmentUrl;
            audio.load();
        }

        const requestPlayback = async (event) => {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }
            await toggleVoiceMessagePlayback(player, playBtn);
        };

        playBtn.addEventListener('click', requestPlayback);
        waveform.addEventListener('click', requestPlayback);
        durationLabel.addEventListener('click', requestPlayback);

        audio.addEventListener('play', () => {
            activeVoiceMessageAudio = audio;
            setVoiceMessageButtonState(playBtn, true);
            updateVoiceMessageDurationLabel(durationLabel, audio, voiceMeta.duration, { forceProgress: true });
            // Mark as heard when playback starts and save to localStorage
            player.classList.remove('unheard');
            if (attachmentUrl) {
                try {
                    const heardVoices = JSON.parse(localStorage.getItem('heardVoiceMessages') || '[]');
                    if (!heardVoices.includes(attachmentUrl)) {
                        heardVoices.push(attachmentUrl);
                        localStorage.setItem('heardVoiceMessages', JSON.stringify(heardVoices));
                    }
                } catch (e) {
                    console.warn('Failed to save heard voice message state', e);
                }
            }
        });

        audio.addEventListener('pause', () => {
            if (activeVoiceMessageAudio === audio) {
                activeVoiceMessageAudio = null;
            }
            setVoiceMessageButtonState(playBtn, false);
            updateVoiceMessageDurationLabel(durationLabel, audio, voiceMeta.duration, {
                forceProgress: (audio.currentTime || 0) > 0
            });
        });

        audio.addEventListener('timeupdate', () => {
            const duration = audio.duration || voiceMeta.duration || 0;
            const progress = duration > 0 ? (audio.currentTime / duration) : 0;
            updateVoiceMessageProgress(player, progress);
            updateVoiceMessageDurationLabel(durationLabel, audio, voiceMeta.duration, { forceProgress: true });
        });

        audio.addEventListener('loadedmetadata', () => {
            updateVoiceMessageDurationLabel(durationLabel, audio, voiceMeta.duration);
        });

        audio.addEventListener('error', () => {
            if (attachmentUrl && audio.dataset.retryAttempted !== '1' && !/^blob:/i.test(attachmentUrl)) {
                audio.dataset.retryAttempted = '1';
                audio.src = buildAttachmentRetryUrl(attachmentUrl);
                audio.load();
                return;
            }

            console.warn('Voice message audio failed to load.', {
                url: attachmentUrl,
                mime: attachment && attachment.mime ? attachment.mime : ''
            });
        });

        audio.addEventListener('ended', () => {
            audio.currentTime = 0;
            updateVoiceMessageProgress(player, 0);
            setVoiceMessageButtonState(playBtn, false);
            updateVoiceMessageDurationLabel(durationLabel, audio, voiceMeta.duration);
        });

        player.appendChild(playBtn);
        player.appendChild(waveform);
        player.appendChild(durationLabel);
        player.appendChild(audio);

        // Check if this voice message has been heard before
        if (attachmentUrl) {
            try {
                const heardVoices = JSON.parse(localStorage.getItem('heardVoiceMessages') || '[]');
                if (heardVoices.includes(attachmentUrl)) {
                    player.classList.remove('unheard');
                }
            } catch (e) {
                console.warn('Failed to load heard voice message state', e);
            }
        }

        return player;
    }

    const mediaViewerState = {
        items: [],
        activeKey: ''
    };

    function buildMediaViewerItemKey(item) {
        if (!item) {
            return '';
        }
        return `${String(item.messageId || '')}::${String(item.url || '')}`;
    }

    function getChatMediaGalleryItems() {
        const chatBoxEl = document.getElementById('chatBox');
        if (!chatBoxEl) {
            return [];
        }

        const seenKeys = new Set();
        const items = [];
        chatBoxEl.querySelectorAll('.attachment-image-trigger, .attachment-file[data-media-url]').forEach((trigger, index) => {
            const url = String(trigger.dataset.mediaUrl || '');
            if (!url) {
                return;
            }

            const item = {
                url,
                name: String(trigger.dataset.mediaName || 'Shared attachment'),
                kind: String(trigger.dataset.mediaKind || 'image'),
                mime: String(trigger.dataset.mediaMime || ''),
                size: Number(trigger.dataset.mediaSize || 0),
                messageId: String(trigger.dataset.messageId || index)
            };
            const key = buildMediaViewerItemKey(item);
            if (!key || seenKeys.has(key)) {
                return;
            }
            seenKeys.add(key);
            items.push(item);
        });

        return items;
    }

    function getMediaViewerActiveItem() {
        const items = Array.isArray(mediaViewerState.items) ? mediaViewerState.items : [];
        return items.find(item => buildMediaViewerItemKey(item) === mediaViewerState.activeKey) || items[0] || null;
    }

    function getMediaViewerFileExtension(item) {
        const name = String(item && item.name ? item.name : '');
        const source = name || String(item && item.url ? item.url : '');
        const parts = source.split('.');
        const lastPart = parts.length > 1 ? parts.pop() : '';
        return lastPart ? lastPart.slice(0, 8).toUpperCase() : 'FILE';
    }

    function getAttachmentDownloadMeta(itemOrUrl, fallbackName = 'download') {
        const href = buildAttachmentRetryUrl(
            itemOrUrl && typeof itemOrUrl === 'object'
                ? itemOrUrl.url
                : itemOrUrl
        );
        const downloadName = getAttachmentDownloadName(itemOrUrl, fallbackName);
        let target = '';

        try {
            const parsedUrl = new URL(href, window.location.href);
            if (parsedUrl.origin !== window.location.origin) {
                target = '_blank';
            }
        } catch (error) {
            console.warn('Unable to inspect attachment URL before preparing download link.', error);
        }

        return {
            href: href || '#',
            downloadName,
            target
        };
    }

    function syncMediaViewerDownloadButton(activeItem) {
        const downloadBtn = document.getElementById('mediaViewerDownload');
        if (!downloadBtn) {
            return;
        }

        if (!activeItem || !activeItem.url) {
            downloadBtn.setAttribute('href', '#');
            downloadBtn.removeAttribute('download');
            downloadBtn.removeAttribute('target');
            downloadBtn.setAttribute('aria-disabled', 'true');
            downloadBtn.classList.add('is-disabled');
            return;
        }

        const downloadMeta = getAttachmentDownloadMeta(activeItem);
        downloadBtn.setAttribute('href', downloadMeta.href);
        downloadBtn.setAttribute('download', downloadMeta.downloadName);
        downloadBtn.setAttribute('aria-disabled', 'false');
        downloadBtn.classList.remove('is-disabled');

        if (downloadMeta.target) {
            downloadBtn.setAttribute('target', downloadMeta.target);
        } else {
            downloadBtn.removeAttribute('target');
        }
    }

    function renderMediaViewerStage(activeItem, viewerStage) {
        if (!viewerStage) {
            return;
        }

        viewerStage.querySelectorAll('video').forEach(videoEl => {
            try {
                videoEl.pause();
            } catch (error) {}
        });
        viewerStage.innerHTML = '';
        if (!activeItem) {
            return;
        }

        if (activeItem.kind === 'image') {
            const image = document.createElement('img');
            image.src = activeItem.url;
            image.alt = activeItem.name || 'Selected media';
            viewerStage.appendChild(image);
            return;
        }

        if (activeItem.kind === 'video') {
            const video = document.createElement('video');
            video.src = activeItem.url;
            video.controls = true;
            video.autoplay = true;
            video.playsInline = true;
            video.preload = 'auto';
            video.setAttribute('playsinline', '');
            video.setAttribute('aria-label', activeItem.name || 'Selected video');
            hydrateVideoPreviewElement(video, activeItem.url, { preload: 'auto' });
            viewerStage.appendChild(video);
            video.play().catch(() => {});
            return;
        }

        const fileCard = document.createElement('div');
        fileCard.className = 'media-viewer-file-card';

        const fileIcon = document.createElement('div');
        fileIcon.className = 'media-viewer-file-icon';
        fileIcon.innerHTML = '<i class="fa-regular fa-file-lines" aria-hidden="true"></i>';

        const fileName = document.createElement('div');
        fileName.className = 'media-viewer-file-name';
        fileName.textContent = activeItem.name || 'File';

        const metaParts = [];
        if (activeItem.mime) {
            metaParts.push(activeItem.mime);
        }
        const sizeText = formatAttachmentSize(activeItem.size);
        if (sizeText) {
            metaParts.push(sizeText);
        }

        const fileMeta = document.createElement('div');
        fileMeta.className = 'media-viewer-file-meta';
        fileMeta.textContent = metaParts.join(' | ') || 'File attachment';

        const actionRow = document.createElement('div');
        actionRow.className = 'media-viewer-file-actions';

        const openLink = document.createElement('a');
        openLink.className = 'media-viewer-file-action';
        openLink.href = activeItem.url;
        openLink.target = '_blank';
        openLink.rel = 'noopener noreferrer';
        openLink.innerHTML = '<i class="fa-solid fa-up-right-from-square" aria-hidden="true"></i><span>Open file</span>';

        const downloadMeta = getAttachmentDownloadMeta(activeItem, 'attachment');
        const downloadLink = document.createElement('a');
        downloadLink.className = 'media-viewer-file-action';
        downloadLink.href = downloadMeta.href;
        downloadLink.download = downloadMeta.downloadName;
        downloadLink.rel = 'noopener';
        if (downloadMeta.target) {
            downloadLink.target = downloadMeta.target;
        }
        downloadLink.innerHTML = '<i class="fa-solid fa-download" aria-hidden="true"></i><span>Download</span>';
        downloadLink.addEventListener('click', (event) => {
            event.stopPropagation();
            showToast('Download started', 'success');
        });

        actionRow.appendChild(openLink);
        actionRow.appendChild(downloadLink);

        fileCard.appendChild(fileIcon);
        fileCard.appendChild(fileName);
        fileCard.appendChild(fileMeta);
        fileCard.appendChild(actionRow);
        viewerStage.appendChild(fileCard);
    }

    function renderMediaViewer() {
        const viewerStage = document.getElementById('mediaViewerStageContent');
        const viewerStrip = document.getElementById('mediaViewerStrip');
        if (!viewerStage || !viewerStrip) {
            return;
        }

        const items = Array.isArray(mediaViewerState.items) ? mediaViewerState.items : [];
        const activeItem = getMediaViewerActiveItem();

        if (!activeItem) {
            viewerStage.innerHTML = '';
            viewerStrip.innerHTML = '<div class="media-viewer-strip-empty">No attachments in this chat yet.</div>';
            syncMediaViewerDownloadButton(null);
            return;
        }

        mediaViewerState.activeKey = buildMediaViewerItemKey(activeItem);
        syncMediaViewerDownloadButton(activeItem);
        renderMediaViewerStage(activeItem, viewerStage);

        viewerStrip.innerHTML = '';
        items.forEach(item => {
            const thumbBtn = document.createElement('button');
            thumbBtn.type = 'button';
            thumbBtn.className = 'media-viewer-thumb';
            thumbBtn.dataset.mediaKey = buildMediaViewerItemKey(item);
            if (thumbBtn.dataset.mediaKey === mediaViewerState.activeKey) {
                thumbBtn.classList.add('is-selected');
            }

            if (item.kind === 'image') {
                const thumbImage = document.createElement('img');
                thumbImage.src = item.url;
                thumbImage.alt = item.name || 'Chat media';
                thumbImage.loading = 'lazy';
                thumbBtn.appendChild(thumbImage);
            } else if (item.kind === 'video') {
                thumbBtn.classList.add('has-media-preview');
                const thumbVideo = document.createElement('video');
                thumbVideo.src = item.url;
                thumbVideo.muted = true;
                thumbVideo.playsInline = true;
                thumbVideo.preload = 'auto';
                thumbVideo.setAttribute('playsinline', '');
                thumbVideo.setAttribute('aria-hidden', 'true');
                hydrateVideoPreviewElement(thumbVideo, item.url, { preload: 'auto', primeFrame: true });

                const playBadge = document.createElement('div');
                playBadge.className = 'media-viewer-thumb-play-badge';
                playBadge.innerHTML = '<i class="fa-solid fa-play" aria-hidden="true"></i>';

                thumbBtn.appendChild(thumbVideo);
                thumbBtn.appendChild(playBadge);
            } else {
                thumbBtn.classList.add('is-file');
                const fileIcon = document.createElement('div');
                fileIcon.className = 'media-viewer-thumb-file-icon';
                fileIcon.innerHTML = '<i class="fa-regular fa-file-lines" aria-hidden="true"></i>';

                const fileLabel = document.createElement('div');
                fileLabel.className = 'media-viewer-thumb-file-label';
                fileLabel.textContent = getMediaViewerFileExtension(item);

                thumbBtn.appendChild(fileIcon);
                thumbBtn.appendChild(fileLabel);
            }

            thumbBtn.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopPropagation();
                mediaViewerState.activeKey = String(thumbBtn.dataset.mediaKey || '');
                renderMediaViewer();
            });

            viewerStrip.appendChild(thumbBtn);
        });
        
        updateMediaViewerNavButtons();
    }

    function openMediaViewer(initialUrl = '', initialMessageId = '', initialMeta = {}) {
        const viewerModal = document.getElementById('mediaViewerModal');
        if (!viewerModal) {
            return;
        }

        const items = getChatMediaGalleryItems();
        const requestedKey = buildMediaViewerItemKey({
            url: String(initialUrl || ''),
            messageId: String(initialMessageId || '')
        });

        mediaViewerState.items = items;
        mediaViewerState.activeKey = requestedKey && items.some(item => buildMediaViewerItemKey(item) === requestedKey)
            ? requestedKey
            : (items[0] ? buildMediaViewerItemKey(items[0]) : requestedKey);

        if (!items.length && initialUrl) {
            mediaViewerState.items = [{
                url: String(initialUrl),
                name: String(initialMeta.name || 'Selected attachment'),
                kind: String(initialMeta.kind || 'image'),
                mime: String(initialMeta.mime || ''),
                size: Number(initialMeta.size || 0),
                messageId: String(initialMessageId || 'standalone')
            }];
            mediaViewerState.activeKey = buildMediaViewerItemKey(mediaViewerState.items[0]);
        }

        renderMediaViewer();
        viewerModal.classList.add('open');
        viewerModal.setAttribute('aria-hidden', 'false');
        updateUnreadAttentionCue();
    }

    function closeMediaViewer() {
        const viewerModal = document.getElementById('mediaViewerModal');
        const viewerStage = document.getElementById('mediaViewerStageContent');
        const viewerStrip = document.getElementById('mediaViewerStrip');
        if (!viewerModal) {
            return;
        }

        viewerModal.classList.remove('open');
        viewerModal.setAttribute('aria-hidden', 'true');
        mediaViewerState.items = [];
        mediaViewerState.activeKey = '';
        syncMediaViewerDownloadButton(null);
        if (viewerStage) {
            viewerStage.innerHTML = '';
        }
        if (viewerStrip) {
            viewerStrip.innerHTML = '';
        }
        updateUnreadAttentionCue();
        if (selectedUser && !shouldDelaySelectedChatRead(selectedUser)) {
            scheduleSelectedChatReadSync(selectedUser);
        }
    }
    
    function navigateMediaViewer(direction) {
        const items = mediaViewerState.items || [];
        if (items.length <= 1) return;
        
        const currentIndex = items.findIndex(item => 
            buildMediaViewerItemKey(item) === mediaViewerState.activeKey
        );
        
        if (currentIndex === -1) return;
        
        let newIndex;
        if (direction === 'prev') {
            newIndex = currentIndex > 0 ? currentIndex - 1 : items.length - 1;
        } else {
            newIndex = currentIndex < items.length - 1 ? currentIndex + 1 : 0;
        }
        
        mediaViewerState.activeKey = buildMediaViewerItemKey(items[newIndex]);
        renderMediaViewer();
    }

    function updateMediaViewerNavButtons() {
        const prevBtn = document.getElementById('mediaViewerPrev');
        const nextBtn = document.getElementById('mediaViewerNext');
        const items = mediaViewerState.items || [];
        
        if (!prevBtn || !nextBtn) return;
        
        if (items.length <= 1) {
            prevBtn.style.display = 'none';
            nextBtn.style.display = 'none';
        } else {
            prevBtn.style.display = 'flex';
            nextBtn.style.display = 'flex';
        }
    }

    window.openMediaViewer = openMediaViewer;
    window.closeMediaViewer = closeMediaViewer;
    window.navigateMediaViewer = navigateMediaViewer;

    function createVideoPlayBadge(className) {
        const badge = document.createElement('div');
        badge.className = className;
        badge.innerHTML = '<i class="fa-solid fa-play" aria-hidden="true"></i>';
        return badge;
    }

    const videoPreviewPosterCache = new Map();

    function getVideoPreviewSeekTime(duration) {
        if (!Number.isFinite(duration) || duration <= 0.08) {
            return 0;
        }

        return Math.max(0, Math.min(duration - 0.01, Math.min(0.35, Math.max(0.08, duration * 0.05))));
    }

    function captureVideoPreviewPoster(url) {
        return new Promise(resolve => {
            const sourceUrl = resolveAttachmentUrl(url);
            if (!sourceUrl) {
                resolve('');
                return;
            }

            const video = document.createElement('video');
            let settled = false;
            let timeoutId = 0;

            const cleanup = () => {
                try {
                    video.pause();
                } catch (e) {}
                try {
                    video.removeAttribute('src');
                    video.load();
                } catch (e) {}
            };

            const settle = result => {
                if (settled) {
                    return;
                }
                settled = true;
                if (timeoutId) {
                    window.clearTimeout(timeoutId);
                }
                cleanup();
                resolve(typeof result === 'string' ? result : '');
            };

            const captureFrame = () => {
                try {
                    const width = Number(video.videoWidth || 0);
                    const height = Number(video.videoHeight || 0);
                    if (!(width > 0) || !(height > 0)) {
                        settle('');
                        return;
                    }

                    const canvas = document.createElement('canvas');
                    canvas.width = width;
                    canvas.height = height;
                    const context = canvas.getContext('2d');
                    if (!context) {
                        settle('');
                        return;
                    }

                    context.drawImage(video, 0, 0, width, height);
                    settle(canvas.toDataURL('image/jpeg', 0.84));
                } catch (error) {
                    console.warn('Unable to capture a video preview frame.', error);
                    settle('');
                }
            };

            const seekTarget = () => {
                const targetTime = getVideoPreviewSeekTime(video.duration);
                if (!(targetTime > 0)) {
                    captureFrame();
                    return;
                }

                try {
                    if (Math.abs((video.currentTime || 0) - targetTime) < 0.01) {
                        captureFrame();
                    } else {
                        video.currentTime = targetTime;
                    }
                } catch (error) {
                    captureFrame();
                }
            };

            video.addEventListener('loadeddata', seekTarget, { once: true });
            video.addEventListener('seeked', captureFrame, { once: true });
            video.addEventListener('error', () => settle(''), { once: true });

            timeoutId = window.setTimeout(() => settle(''), 7000);

            video.preload = 'auto';
            video.muted = true;
            video.playsInline = true;
            video.setAttribute('playsinline', '');
            video.src = sourceUrl;

            try {
                video.load();
            } catch (error) {
                settle('');
            }
        });
    }

    function getVideoPreviewPoster(url) {
        const sourceUrl = resolveAttachmentUrl(url);
        if (!sourceUrl) {
            return Promise.resolve('');
        }

        const cached = videoPreviewPosterCache.get(sourceUrl);
        if (cached instanceof Promise) {
            return cached;
        }
        if (typeof cached === 'string') {
            return Promise.resolve(cached);
        }

        const posterPromise = captureVideoPreviewPoster(sourceUrl)
            .then(posterData => {
                const normalizedPoster = typeof posterData === 'string' ? posterData : '';
                videoPreviewPosterCache.set(sourceUrl, normalizedPoster);
                return normalizedPoster;
            })
            .catch(error => {
                console.warn('Unable to build a cached video preview poster.', error);
                videoPreviewPosterCache.delete(sourceUrl);
                return '';
            });

        videoPreviewPosterCache.set(sourceUrl, posterPromise);
        return posterPromise;
    }

    function hydrateVideoPreviewElement(videoEl, url, options = {}) {
        if (!videoEl) {
            return;
        }

        const sourceUrl = resolveAttachmentUrl(url);
        if (!sourceUrl) {
            return;
        }

        videoEl.dataset.previewUrl = sourceUrl;
        videoEl.preload = options.preload || 'auto';
        videoEl.setAttribute('preload', videoEl.preload);
        videoEl.playsInline = true;
        videoEl.setAttribute('playsinline', '');

        if (options.primeFrame && videoEl.dataset.previewFrameBound !== '1') {
            videoEl.dataset.previewFrameBound = '1';
            const primeFrame = () => {
                const targetTime = getVideoPreviewSeekTime(videoEl.duration);
                if (!(targetTime > 0)) {
                    return;
                }

                try {
                    if (Math.abs((videoEl.currentTime || 0) - targetTime) >= 0.01) {
                        videoEl.currentTime = targetTime;
                    }
                } catch (error) {}
            };

            videoEl.addEventListener('loadeddata', primeFrame);
            videoEl.addEventListener('loadedmetadata', primeFrame);
        }

        getVideoPreviewPoster(sourceUrl).then(posterData => {
            if (!posterData || videoEl.dataset.previewUrl !== sourceUrl) {
                return;
            }
            videoEl.poster = posterData;
        });

        try {
            videoEl.load();
        } catch (error) {}
    }

    // ── Nickname Management ──────────────────────────────────────────────────
    function buildAttachmentNode(attachment) {
        const wrapper = document.createElement('div');
        wrapper.className = 'attachment-body';
        const attachmentUrl = resolveAttachmentUrl(attachment && attachment.url);

        if (attachment && attachment.pending && attachment.kind === 'image') {
            const placeholder = document.createElement('div');
            placeholder.className = 'attachment-image attachment-image-placeholder';
            if (attachment.aiGenerated) {
                placeholder.classList.add('is-ai-generated');
            }
            placeholder.setAttribute('role', 'status');
            placeholder.setAttribute('aria-live', 'polite');

            const spinner = document.createElement('span');
            spinner.className = 'attachment-image-placeholder-spinner';
            spinner.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i>';
            placeholder.appendChild(spinner);

            const srLabel = document.createElement('span');
            srLabel.className = 'sr-only';
            srLabel.textContent = attachment.loadingLabel || 'Generating image';
            placeholder.appendChild(srLabel);

            wrapper.appendChild(placeholder);
            return wrapper;
        }

        if (attachment.kind === 'image' || attachment.kind === 'video') {
            const mediaTrigger = document.createElement('button');
            mediaTrigger.type = 'button';
            mediaTrigger.className = 'attachment-image-trigger';
            if (attachment.aiGenerated) {
                mediaTrigger.classList.add('is-ai-generated');
            }
            mediaTrigger.dataset.mediaUrl = attachmentUrl;
            mediaTrigger.dataset.mediaName = attachment.name || (attachment.kind === 'video' ? 'Shared video' : 'Shared image');
            mediaTrigger.dataset.mediaKind = attachment.kind;
            mediaTrigger.dataset.mediaMime = attachment.mime || '';
            mediaTrigger.dataset.mediaSize = String(attachment.size || 0);
            mediaTrigger.dataset.messageId = String(attachment.messageId || '');
            mediaTrigger.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopPropagation();
                openMediaViewer(attachmentUrl, String(attachment.messageId || ''), {
                    name: attachment.name || (attachment.kind === 'video' ? 'Shared video' : 'Shared image'),
                    kind: attachment.kind,
                    mime: attachment.mime || '',
                    size: attachment.size || 0
                });
            });

            if (attachment.kind === 'video') {
                const video = document.createElement('video');
                video.className = 'attachment-image attachment-video-preview';
                video.src = attachmentUrl;
                video.muted = true;
                video.playsInline = true;
                video.preload = 'auto';
                video.setAttribute('playsinline', '');
                video.setAttribute('aria-hidden', 'true');
                hydrateVideoPreviewElement(video, attachmentUrl, { preload: 'auto', primeFrame: true });
                mediaTrigger.appendChild(video);
                mediaTrigger.appendChild(createVideoPlayBadge('attachment-video-play-badge'));
            } else {
                const image = document.createElement('img');
                image.className = 'attachment-image';
                if (attachment.aiGenerated) {
                    image.classList.add('is-ai-generated');
                }
                image.src = attachmentUrl;
                image.alt = attachment.name || 'Shared image';
                mediaTrigger.appendChild(image);
            }

            wrapper.appendChild(mediaTrigger);
        }
        if (attachment.kind === 'audio') {
            wrapper.appendChild(buildVoiceMessagePlayer(attachment));
        }

        if (attachment.kind !== 'audio' && attachment.kind !== 'image' && attachment.kind !== 'video') {
            const fileLink = document.createElement('a');
            fileLink.className = 'attachment-file';
            fileLink.href = attachmentUrl;
            fileLink.target = '_blank';
            fileLink.rel = 'noopener noreferrer';
            fileLink.dataset.mediaUrl = attachmentUrl;
            fileLink.dataset.mediaName = attachment.name || 'File';
            fileLink.dataset.mediaKind = attachment.kind || 'file';
            fileLink.dataset.mediaMime = attachment.mime || '';
            fileLink.dataset.mediaSize = String(attachment.size || 0);
            fileLink.dataset.messageId = String(attachment.messageId || '');
            fileLink.addEventListener('click', (event) => {
                if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
                    return;
                }
                event.preventDefault();
                event.stopPropagation();
                openMediaViewer(attachmentUrl, String(attachment.messageId || ''), {
                    name: attachment.name || 'File',
                    kind: attachment.kind || 'file',
                    mime: attachment.mime || '',
                    size: attachment.size || 0
                });
            });

            const fileIcon = document.createElement('i');
            fileIcon.className = 'fa-regular fa-file';

            const meta = document.createElement('div');
            meta.className = 'attachment-meta';

            const name = document.createElement('div');
            name.className = 'attachment-name';
            name.textContent = attachment.name || 'File';

            meta.appendChild(name);

            const sizeText = formatAttachmentSize(attachment.size);
            if (sizeText) {
                const size = document.createElement('div');
                size.className = 'attachment-size';
                size.textContent = sizeText;
                meta.appendChild(size);
            }

            fileLink.appendChild(fileIcon);
            fileLink.appendChild(meta);
            wrapper.appendChild(fileLink);
        }

        if (attachment.caption) {
            const caption = document.createElement('div');
            caption.className = 'attachment-caption';
            caption.textContent = attachment.caption;
            wrapper.appendChild(caption);
        }

        return wrapper;
    }

    function buildTableMessageNode(tableData, messageChatKey = '', options = {}) {
        const normalized = normalizeTableMessagePayload(tableData);
        if (!normalized) {
            return createTextElement('Table unavailable');
        }

        const wrapper = document.createElement('div');
        wrapper.className = 'message-table-wrap' + (options.editable ? ' is-editable' : '');

        if (normalized.caption) {
            const caption = document.createElement('div');
            caption.className = 'message-table-caption';
            caption.innerHTML = renderHighlightedTextHtml(normalized.caption, messageChatKey);
            wrapper.appendChild(caption);
        }

        const scroll = document.createElement('div');
        scroll.className = 'message-table-scroll';

        const table = document.createElement('table');
        table.className = 'message-table-grid';

        const body = document.createElement('tbody');
        normalized.cells.forEach((row, rowIndex) => {
            const tr = document.createElement('tr');
            row.forEach((cellValue, colIndex) => {
                const td = document.createElement('td');
                td.className = 'message-table-cell';
                td.dataset.rowIndex = String(rowIndex);
                td.dataset.colIndex = String(colIndex);
                td.setAttribute('aria-label', `Row ${rowIndex + 1}, column ${colIndex + 1}`);
                td.textContent = cellValue;
                td.classList.toggle('is-empty', !cellValue);

                if (options.editable) {
                    td.contentEditable = 'true';
                    td.spellcheck = false;
                    td.setAttribute('role', 'textbox');
                    td.addEventListener('keydown', (event) => {
                        if (event.key === 'Enter') {
                            event.preventDefault();
                            td.blur();
                        }
                    });
                    td.addEventListener('input', () => {
                        const nextValue = sanitizeTableMessageCellValue(td.textContent || '');
                        td.classList.toggle('is-empty', !nextValue);
                        if (typeof options.onCellChange === 'function') {
                            options.onCellChange(rowIndex, colIndex, nextValue);
                        }
                    });
                    td.addEventListener('blur', () => {
                        const nextValue = sanitizeTableMessageCellValue(td.textContent || '');
                        td.textContent = nextValue;
                        td.classList.toggle('is-empty', !nextValue);
                    });
                }

                tr.appendChild(td);
            });
            body.appendChild(tr);
        });

        table.appendChild(body);
        scroll.appendChild(table);
        wrapper.appendChild(scroll);
        return wrapper;
    }

    function buildCallEventNode(callEvent, createdAt, sourceMessage = null) {
        const wrapper = document.createElement('div');
        wrapper.className = 'call-event-body';

        const icon = document.createElement('div');
        icon.className = `call-event-icon ${getCallEventIconType(callEvent)}`;

        const phoneIcon = document.createElement('i');
        phoneIcon.className = 'fa-solid fa-phone';
        icon.appendChild(phoneIcon);

        if (callEvent.type === 'missed') {
            const arrow = document.createElement('span');
            arrow.className = 'missed-call-arrow';
            icon.appendChild(arrow);
        }

        const copy = document.createElement('div');
        copy.className = 'call-event-copy';

        const title = document.createElement('div');
        title.className = 'call-event-title';
        title.textContent = getCallEventTitle(callEvent);

        const subtitle = document.createElement('div');
        subtitle.className = 'call-event-subtitle';
        subtitle.textContent = getCallEventSubtitle(callEvent, createdAt);

        copy.appendChild(title);
        copy.appendChild(subtitle);

        // Add "Call back" button for missed calls (incoming only)
        const callBackTargetId = sourceMessage ? getConversationOtherUserId(sourceMessage) : String(selectedUser || '');
        if (
            callEvent.type === 'missed'
            && !isOutgoingCallEventForUser(callEvent, currentUserId)
            && callBackTargetId
            && getChatTypeFromKey(callBackTargetId) === 'direct'
        ) {
            const callBackBtn = document.createElement('button');
            callBackBtn.className = 'group-call-join-btn';
            callBackBtn.textContent = 'Call back';
            callBackBtn.style.marginTop = '8px';
            addTapAndClickListener(callBackBtn, (e) => {
                e.stopPropagation();
                const previousChatKey = String(selectedUser || '');
                if (previousChatKey !== String(callBackTargetId)) {
                    selectedUser = String(callBackTargetId);
                    updateHeaderContact(selectedUser);
                }
                initiateCall();
            });
            copy.appendChild(callBackBtn);
        }

        wrapper.appendChild(icon);
        wrapper.appendChild(copy);

        return wrapper;
    }

    // Live elapsed time for ongoing group call messages
    const groupCallTileTimers = {};

    function buildGroupCallMessageNode(gcMsg, msgEl) {
        const tile = document.createElement('div');
        tile.className = 'group-call-tile';

        const iconWrap = document.createElement('div');
        iconWrap.className = 'group-call-tile-icon';
        iconWrap.innerHTML = '<i class="fas fa-phone"></i>';

        const copy = document.createElement('div');
        copy.className = 'group-call-tile-copy';

        const titleEl = document.createElement('div');
        titleEl.className = 'group-call-tile-title';
        titleEl.textContent = 'Group Call';

        const subtitleEl = document.createElement('div');
        subtitleEl.className = 'group-call-tile-subtitle';

        const isOngoing = gcMsg.status === 'ongoing';

        if (isOngoing) {
            // Use Unix timestamp if available (no timezone ambiguity), else parse ISO string as UTC
            let safeStart;
            if (gcMsg.started_at_unix && gcMsg.started_at_unix > 0) {
                safeStart = gcMsg.started_at_unix * 1000;
            } else if (gcMsg.started_at) {
                const normalized = String(gcMsg.started_at).replace(' ', 'T') + 'Z';
                const parsed = new Date(normalized).getTime();
                safeStart = (!isNaN(parsed) && parsed > 0) ? parsed : Date.now();
            } else {
                safeStart = Date.now();
            }
            const updateTimer = () => {
                const elapsed = Math.max(0, Date.now() - safeStart);
                subtitleEl.textContent = 'Ongoing ' + formatStopwatch(elapsed);
            };
            updateTimer();
            const timerId = setInterval(updateTimer, 1000);
            // Store timer so we can clear it when the message is updated
            const msgId = msgEl ? msgEl.dataset.id : null;
            if (msgId) {
                if (groupCallTileTimers[msgId]) clearInterval(groupCallTileTimers[msgId]);
                groupCallTileTimers[msgId] = timerId;
            }
        } else {
            const endedAt = gcMsg.ended_at ? new Date(gcMsg.ended_at) : null;
            if (endedAt) {
                subtitleEl.textContent = 'Ended ' + endedAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            } else {
                subtitleEl.textContent = 'Ended';
            }
        }

        copy.appendChild(titleEl);
        copy.appendChild(subtitleEl);

        if (isOngoing) {
            const joinBtn = document.createElement('button');
            joinBtn.className = 'group-call-join-btn';
            joinBtn.textContent = 'Join';
            joinBtn.addEventListener('click', () => {
                const groupKey = selectedUser && isGroupChatKey(String(selectedUser)) ? String(selectedUser) : null;
                if (groupKey) initiateGroupCall(groupKey);
            });
            copy.appendChild(joinBtn);
        }

        tile.appendChild(iconWrap);
        tile.appendChild(copy);
        return tile;
    }

    function buildGroupNewsNode(groupNews, createdAt) {
        const card = document.createElement('div');
        card.className = 'group-news-card';

        const text = document.createElement('span');
        text.className = 'group-news-text';
        text.textContent = getGroupNewsSentence(groupNews);

        const separator = document.createElement('span');
        separator.className = 'group-news-separator';
        separator.textContent = '|';

        const meta = document.createElement('div');
        meta.className = 'group-news-meta';
        meta.textContent = formatContactPreviewTime(createdAt) || 'now';

        card.appendChild(text);
        card.appendChild(separator);
        card.appendChild(meta);
        return card;
    }

    function getConversationOtherUserId(msg) {
        const senderId = msg && msg.sender_id ? String(msg.sender_id) : '';
        const recipientId = msg && msg.recipient_id ? String(msg.recipient_id) : '';

        if (senderId === String(currentUserId)) {
            return recipientId;
        }

        if (recipientId === String(currentUserId)) {
            return senderId;
        }

        return String(selectedUser || senderId || recipientId || '');
    }

    function hydrateMessageSenderData(msg) {
        if (!msg || !msg.sender_id) {
            return;
        }

        const senderId = String(msg.sender_id);
        const messageChatKey = getMessageChatKey(msg);
        if (messageChatKey) {
            rememberChatNickname(messageChatKey, senderId, msg.sender_chat_nickname || '');
        }
        if (!senderId || senderId === String(currentUserId)) {
            return;
        }

        if (msg.sender_display_name) {
            userNamesMap[senderId] = String(msg.sender_display_name);
        }

        if (msg.sender_profile_pic) {
            userProfilePics[senderId] = String(msg.sender_profile_pic);
        }

        if (msg.sender_online !== undefined && msg.sender_online !== null) {
            userOnlineMap[senderId] = Number(msg.sender_online) === 1;
        }
    }

    function getBlockedMessageCountLabel(count) {
        const safeCount = Math.max(1, Number(count) || 1);
        return safeCount === 1 ? '1 blocked message.' : `${safeCount} blocked messages.`;
    }

    function updateBlockedMessageGroupSummary(group) {
        if (!group) {
            return;
        }

        const countEl = group.querySelector('.blocked-message-count');
        const toggleEl = group.querySelector('.blocked-message-toggle');
        const stackEl = group.querySelector('.blocked-message-stack');
        const count = Number(group.dataset.count || 0);

        if (countEl) {
            countEl.textContent = getBlockedMessageCountLabel(count);
        }

        if (toggleEl) {
            const isRevealed = !!(stackEl && !stackEl.hidden);
            toggleEl.textContent = isRevealed ? 'Hide' : 'Show';
        }
    }

    function getLastBlockedMessageGroup(senderId) {
        const lastChild = chatBox.lastElementChild;
        if (!lastChild || !lastChild.classList || !lastChild.classList.contains('blocked-message-group')) {
            return null;
        }

        if (String(lastChild.dataset.senderId || '') !== String(senderId || '')) {
            return null;
        }

        return lastChild;
    }

    function appendBlockedMessageElement(messageElement, senderId, createdAt) {
        let group = getLastBlockedMessageGroup(senderId);
        let isNewGroup = false;

        if (!group) {
            isNewGroup = true;
            group = document.createElement('div');
            group.className = 'blocked-message-group';
            group.dataset.senderId = String(senderId || '');
            group.dataset.count = '0';
            group.dataset.timestamp = createdAt || '';

            const summary = document.createElement('div');
            summary.className = 'blocked-message-summary';

            const countEl = document.createElement('span');
            countEl.className = 'blocked-message-count';

            const toggleBtn = document.createElement('button');
            toggleBtn.type = 'button';
            toggleBtn.className = 'blocked-message-toggle';
            toggleBtn.textContent = 'Show';

            const stack = document.createElement('div');
            stack.className = 'blocked-message-stack';
            stack.hidden = true;

            summary.appendChild(countEl);
            summary.appendChild(toggleBtn);
            group.appendChild(summary);
            group.appendChild(stack);
            
            chatBox.appendChild(group);
        }

        const stackEl = group.querySelector('.blocked-message-stack');
        if (stackEl) {
            stackEl.appendChild(messageElement);
        }

        group.dataset.count = String(Number(group.dataset.count || 0) + 1);
        group.dataset.timestamp = createdAt || group.dataset.timestamp || '';
        updateBlockedMessageGroupSummary(group);
        return group;
    }

    function qtEscapeHtml(s) {
        return String(s || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function linkifyText(text) {
        // Escape HTML first
        const escaped = qtEscapeHtml(text);
        
        // URL regex pattern - matches http://, https://, and www. URLs
        const urlPattern = /(\b(https?:\/\/|www\.)[^\s<]+[^\s<.,;:!?'")\]])/gi;
        
        return escaped.replace(urlPattern, (url) => {
            let href = url;
            // Add https:// if URL starts with www.
            if (url.toLowerCase().startsWith('www.')) {
                href = 'https://' + url;
            }
            return `<a href="${href}" target="_blank" rel="noopener noreferrer" style="color: var(--text-primary); text-decoration: underline;">${url}</a>`;
        });
    }

    function getMessageSnippetForReply(raw) {
        if (!raw || typeof raw !== 'string') return '';
        const att = parseAttachmentMessage(raw);
        if (att) {
            if (att.kind === 'image') return 'Photo';
            if (att.kind === 'video') return 'Video';
            if (att.kind === 'audio') return 'Voice message';
            return att.name || 'Attachment';
        }
        const tableMessage = parseTableMessage(raw);
        if (tableMessage) return getTableMessageSummary(tableMessage);
        const gameMessage = parseGameMessage(raw);
        if (gameMessage) return getGameMessageLabel(gameMessage);
        if (parsePollMessage(raw)) return 'Poll';
        if (parseGroupCallMessage(raw)) return 'Group call';
        if (parseCallEventMessage(raw)) return 'Call';
        const groupNews = parseGroupNewsMessage(raw);
        if (groupNews) return getGroupNewsSentence(groupNews);
        const div = document.createElement('div');
        div.innerHTML = raw;
        const text = (div.textContent || '').trim();
        if (text.length > 140) return text.slice(0, 137) + '…';
        return text;
    }

    function getMessageTranslationKey(msg) {
        if (!msg || !msg.id) {
            return '';
        }

        if (String(getMessageChatKey(msg) || '').startsWith('ai:')) {
            return `ai:${msg.id}`;
        }

        return msg.group_id ? `group:${msg.id}` : `direct:${msg.id}`;
    }

    function getTranslateLanguageOption(languageCode) {
        const normalizedCode = String(languageCode || '').trim().toLowerCase();
        return MESSAGE_TRANSLATION_LANGUAGES.find(language => language.code === normalizedCode) || null;
    }

    function escapeMessageTranslationSelectorValue(value) {
        const normalizedValue = String(value || '');
        if (window.CSS && typeof window.CSS.escape === 'function') {
            return window.CSS.escape(normalizedValue);
        }

        return normalizedValue.replace(/["\\]/g, '\\$&');
    }

    function getTranslatableMessageText(rawMessage) {
        if (typeof rawMessage !== 'string') {
            return '';
        }

        if (
            parseAttachmentMessage(rawMessage)
            || parseGameMessage(rawMessage)
            || parseTableMessage(rawMessage)
            || parseCallEventMessage(rawMessage)
            || parseGroupCallMessage(rawMessage)
            || parseGroupNewsMessage(rawMessage)
            || parsePollMessage(rawMessage)
        ) {
            return '';
        }

        const temp = document.createElement('div');
        temp.innerHTML = rawMessage.replace(/<br\s*\/?>/gi, '\n');
        return String(temp.textContent || temp.innerText || rawMessage || '')
            .replace(/\u00a0/g, ' ')
            .replace(/\r\n?/g, '\n')
            .replace(/[ \t]+\n/g, '\n')
            .replace(/\n[ \t]+/g, '\n')
            .replace(/\n{3,}/g, '\n\n')
            .trim();
    }

    function countTranslationHintMatches(text, pattern) {
        if (!text || !pattern) {
            return 0;
        }
        const matches = String(text).match(pattern);
        return matches ? matches.length : 0;
    }

    function detectCyrillicTranslationLanguage(text) {
        const normalized = String(text || '').toLowerCase();
        const ukrainianScore = countTranslationHintMatches(normalized, /[іїєґ]/giu)
            + countTranslationHintMatches(normalized, /\b(?:це|привіт|дякую|будь|ласка|що|як|ти|ви|мене)\b/giu);
        const russianScore = countTranslationHintMatches(normalized, /[ыэёъ]/giu)
            + countTranslationHintMatches(normalized, /\b(?:это|привет|спасибо|пожалуйста|что|как|ты|вы|меня)\b/giu);
        return ukrainianScore > russianScore ? 'uk' : 'ru';
    }

    function detectMessageSourceLanguage(rawMessage) {
        const text = getTranslatableMessageText(rawMessage);
        if (!text) {
            return 'en';
        }

        if (/[؀-ۿݐ-ݿࢠ-ࣿ]/u.test(text)) {
            return 'ar';
        }
        if (/[ऀ-ॿ]/u.test(text)) {
            return 'hi';
        }
        if (/[ぁ-ゖゝゞァ-ヺー]/u.test(text)) {
            return 'ja';
        }
        if (/[ㄱ-ㅎㅏ-ㅣ가-힣]/u.test(text)) {
            return 'ko';
        }
        if (/[一-龯]/u.test(text)) {
            return 'zh';
        }
        if (/[Ѐ-ӿ]/u.test(text)) {
            return detectCyrillicTranslationLanguage(text);
        }

        const normalized = text.toLowerCase();
        let bestLanguage = 'en';
        let bestScore = 0;

        Object.entries(MESSAGE_TRANSLATION_LANGUAGE_HINTS).forEach(([languageCode, hint]) => {
            const score = countTranslationHintMatches(normalized, hint.pattern);
            if (score > bestScore) {
                bestScore = score;
                bestLanguage = languageCode;
            }
        });

        return bestLanguage;
    }

    function buildMessageTranslationToggle(messageTranslationKey) {
        const translationState = messageTranslationKey
            ? messageTranslationStates.get(messageTranslationKey)
            : null;
        if (!translationState) {
            return null;
        }

        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'message-translation-toggle';
        button.dataset.translationKey = messageTranslationKey;
        button.textContent = translationState.showTranslated
            ? 'See original'
            : `Translate to ${translationState.targetLanguageLabel}`;
        addTapAndClickListener(button, event => {
            event.stopPropagation();
            toggleMessageTranslation(messageTranslationKey);
        });
        return button;
    }

    function renderMessageTextContent(textEl, rawHtml, messageChatKey, options = {}) {
        if (!textEl) {
            return false;
        }

        const translationState = options.translationKey
            ? messageTranslationStates.get(options.translationKey)
            : null;
        if (translationState && translationState.showTranslated && translationState.translatedText) {
            textEl.textContent = translationState.translatedText;
            textEl.dataset.translationMode = 'translated';
            decorateInlineEmojiText(textEl);
            return false;
        }

        delete textEl.dataset.translationMode;
        textEl.innerHTML = '';

        const isAiCommand = !!options.isLocalAiMessage
            && options.localAiRole === 'prompt'
            && (rawHtml.includes(' used /ai') || rawHtml.includes('You used /ai'));
        const isReceivedAiCommand = !options.isLocalAiMessage
            && (rawHtml.includes(' used /ai') || rawHtml.includes('You used /ai'));
        const isEmojiOnlyMessage = !options.replyId
            && !(options.forwardFromUserId > 0 && options.forwardFromDisplayName)
            && !isAiCommand
            && !isReceivedAiCommand
            && isEmojiOnlyMessageText(rawHtml);

        if (isAiCommand || isReceivedAiCommand) {
            const lines = rawHtml.split('\n');
            let commandLine = lines[0];
            const promptContent = lines.slice(2).join('\n');

            if (isReceivedAiCommand && commandLine.includes('You used /ai')) {
                const senderName = options.displayName || 'Someone';
                commandLine = commandLine.replace('You used /ai', `${senderName} used /ai`);
            }

            const replyQuote = document.createElement('div');
            replyQuote.className = 'reply-quote';

            const replyQuoteName = document.createElement('div');
            replyQuoteName.className = 'reply-quote-name';
            replyQuoteName.innerHTML = renderAiCommandIndicatorHtml(commandLine);

            const replyQuoteText = document.createElement('div');
            replyQuoteText.className = 'reply-quote-text';
            replyQuoteText.innerHTML = applyMentionHighlights(promptContent, messageChatKey);

            replyQuote.appendChild(replyQuoteName);
            replyQuote.appendChild(replyQuoteText);
            textEl.appendChild(replyQuote);
            decorateInlineEmojiText(textEl);
            return false;
        }

        textEl.innerHTML = applyMentionHighlights(rawHtml, messageChatKey);
        decorateInlineEmojiText(textEl);
        return isEmojiOnlyMessage;
    }

    function syncRenderedMessageTranslation(messageEl) {
        if (!messageEl || !messageEl._qtMessageRenderContext) {
            return;
        }

        const textEl = messageEl.querySelector('.message-text-content');
        if (!textEl) {
            return;
        }

        const context = messageEl._qtMessageRenderContext;
        const isEmojiOnlyMessage = renderMessageTextContent(
            textEl,
            context.rawHtml,
            context.messageChatKey,
            context
        );
        const translationToggle = buildMessageTranslationToggle(context.translationKey);
        const existingToggle = messageEl.querySelector('.message-translation-toggle');

        if (existingToggle) {
            existingToggle.remove();
        }

        if (translationToggle && textEl.parentNode) {
            textEl.insertAdjacentElement('afterend', translationToggle);
        }

        const translationState = context.translationKey
            ? messageTranslationStates.get(context.translationKey)
            : null;
        messageEl.classList.toggle('emoji-only-message', !translationState || !translationState.showTranslated ? !!isEmojiOnlyMessage : false);
    }

    function toggleMessageTranslation(messageTranslationKey) {
        const translationState = messageTranslationStates.get(messageTranslationKey);
        if (!translationState) {
            return;
        }

        translationState.showTranslated = !translationState.showTranslated;
        const selector = `.message[data-translation-key="${escapeMessageTranslationSelectorValue(messageTranslationKey)}"]`;
        document.querySelectorAll(selector).forEach(messageEl => {
            syncRenderedMessageTranslation(messageEl);
        });
    }

    async function logClientHistoryEvent(eventType, { chatKey = '', subjectUserId = null, eventValue = null } = {}) {
        if (!eventType) {
            return;
        }

        try {
            await fetch('log_client_history_event.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    event_type: eventType,
                    chat_key: chatKey,
                    subject_user_id: subjectUserId,
                    event_value: eventValue
                })
            });
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
        } catch (error) {
            console.warn('Unable to log client history event.', error);
        }
    }

    function getCurrentChatMessageType() {
        return getChatMessageType(String(selectedUser || ''));
    }

    function loadRecentReactionEmojis() {
        try {
            const raw = localStorage.getItem(RECENT_EMOJI_STORAGE_KEY);
            const arr = raw ? JSON.parse(raw) : [];
            if (!Array.isArray(arr)) return [];
            return arr.filter(e => typeof e === 'string' && e.length);
        } catch (e) {
            return [];
        }
    }

    function saveRecentReactionEmoji(emoji) {
        if (!emoji) return;
        let list = loadRecentReactionEmojis().filter(e => e !== emoji);
        list.unshift(emoji);
        list = list.slice(0, 24);
        try {
            localStorage.setItem(RECENT_EMOJI_STORAGE_KEY, JSON.stringify(list));
        } catch (e) {}
    }

    function pickFiveReactionEmojis() {
        const recent = loadRecentReactionEmojis();
        const out = [];
        const defaults = DEFAULT_REACTION_EMOJIS.slice();
        for (let i = 0; i < recent.length && out.length < 5; i++) {
            const e = recent[i];
            if (e && !out.includes(e)) out.push(e);
        }
        for (let j = 0; j < defaults.length && out.length < 5; j++) {
            const e = defaults[j];
            if (!out.includes(e)) out.push(e);
        }
        return out.slice(0, 5);
    }

    function closeOpenMessageActionsMenu() {
        if (openMessageActionsMenuEl) {
            const owner = openMessageActionsMenuEl.closest('.message-actions-wrap');
            if (owner) {
                owner.classList.remove('is-open');
                owner.classList.remove('is-hover-visible');
            }
            openMessageActionsMenuEl.classList.remove('is-open');
            openMessageActionsMenuEl = null;
        }
    }

    function isMessageSelectable(messageEl) {
        return !!(
            messageEl
            && messageEl.classList
            && messageEl.classList.contains('message')
            && !messageEl.classList.contains('group-news-message')
            && !messageEl.classList.contains('local-ai-message')
            && !messageEl.dataset.scheduledId
            && getMessageServerId(messageEl) > 0
        );
    }

    function getSelectedMessageElements() {
        if (!chatBox) {
            return [];
        }

        const selectedElements = [];
        const seenIds = new Set();
        Array.from(chatBox.querySelectorAll('.message')).forEach(messageEl => {
            const messageId = String(getMessageServerId(messageEl) || '');
            if (!messageId || seenIds.has(messageId) || !selectedMessageIds.has(messageId) || !isMessageSelectable(messageEl)) {
                messageEl.classList.remove('is-selected');
                return;
            }
            seenIds.add(messageId);
            messageEl.classList.add('is-selected');
            selectedElements.push(messageEl);
        });

        Array.from(selectedMessageIds).forEach(messageId => {
            if (!seenIds.has(String(messageId))) {
                selectedMessageIds.delete(String(messageId));
            }
        });

        return selectedElements;
    }

    function getSelectedMessageDetails() {
        return getSelectedMessageElements().map(messageEl => ({
            messageEl,
            messageId: getMessageServerId(messageEl),
            messageRecord: messageEl._qtMessageRecord || null,
            translationKey: String(messageEl.dataset.translationKey || ''),
            rawMessage: String((messageEl._qtMessageRecord && messageEl._qtMessageRecord.message) || '')
        }));
    }

    function normalizeSelectedSummaryContextText(text, maxChars = 680) {
        const normalized = String(text || '')
            .replace(/\s+/g, ' ')
            .trim();

        if (!normalized) {
            return '';
        }

        if (normalized.length <= maxChars) {
            return normalized;
        }

        return normalized.slice(0, Math.max(0, maxChars - 3)).trimEnd() + '...';
    }

    function getSummaryVoiceAttachment(rawMessage) {
        const attachment = parseAttachmentMessage(String(rawMessage || ''));
        return attachment && attachment.kind === 'audio' ? attachment : null;
    }

    function getSelectedSummaryVoiceAttachment(detail) {
        const rawMessage = String(
            (detail && detail.rawMessage)
            || (detail && detail.messageRecord && detail.messageRecord.message)
            || ''
        );
        return getSummaryVoiceAttachment(rawMessage);
    }

    function getSelectedSummaryVoiceFallbackText(attachment) {
        if (attachment && attachment.caption) {
            return `Voice message: ${attachment.caption}`;
        }
        return 'Voice message (transcription unavailable)';
    }

    async function buildSummaryContextEntry({
        messageEl = null,
        messageRecord = null,
        rawMessage = '',
        senderLabel = '',
        timestamp = ''
    } = {}, {
        maxChars = 680
    } = {}) {
        const resolvedRawMessage = String(
            rawMessage
            || (messageRecord && messageRecord.message)
            || ''
        );
        const resolvedTimestamp = String(
            timestamp
            || (messageRecord && messageRecord.created_at)
            || (messageEl && messageEl.dataset ? messageEl.dataset.timestamp : '')
            || ''
        );
        const resolvedSenderLabel = String(senderLabel || '').trim()
            || getUnreadDividerSenderLabel(messageEl, messageRecord);
        const voiceAttachment = getSummaryVoiceAttachment(resolvedRawMessage);
        let bodyText = getUnreadDividerMessageBody(messageRecord, messageEl);
        let usedVoiceTranscription = false;
        let usedVoiceFallback = false;

        if (voiceAttachment) {
            try {
                const transcription = await requestVoiceMessageTranscription(voiceAttachment);
                if (isUsableVoiceMessageTranscription(transcription)) {
                    bodyText = `Voice message transcription: ${transcription}`;
                    usedVoiceTranscription = true;
                } else {
                    bodyText = getSelectedSummaryVoiceFallbackText(voiceAttachment);
                    usedVoiceFallback = true;
                }
            } catch (error) {
                console.warn('Unable to transcribe voice message for summary context.', error);
                bodyText = getSelectedSummaryVoiceFallbackText(voiceAttachment);
                usedVoiceFallback = true;
            }
        }

        return {
            senderLabel: resolvedSenderLabel,
            bodyText: normalizeSelectedSummaryContextText(bodyText, maxChars),
            timestamp: resolvedTimestamp,
            wasVoiceMessage: !!voiceAttachment,
            usedVoiceTranscription,
            usedVoiceFallback
        };
    }

    function canBulkEditSelectedMessageDetail(detail) {
        if (!(detail && detail.messageEl && detail.messageEl.classList && detail.messageEl.classList.contains('self'))) {
            return false;
        }

        const rawMessage = String(detail && detail.rawMessage ? detail.rawMessage : '').trim();
        if (!rawMessage) {
            return false;
        }

        if (parseAttachmentMessage(rawMessage)) {
            return false;
        }
        if (parsePollMessage(rawMessage)) {
            return false;
        }
        if (parseGameMessage(rawMessage)) {
            return false;
        }
        if (parseTableMessage(rawMessage)) {
            return false;
        }
        if (parseGroupCallMessage(rawMessage)) {
            return false;
        }
        if (parseCallEventMessage(rawMessage)) {
            return false;
        }
        if (parseGroupNewsMessage(rawMessage)) {
            return false;
        }

        return true;
    }

    function canBulkEditCurrentSelection(selectedDetails = null) {
        const details = Array.isArray(selectedDetails) ? selectedDetails : getSelectedMessageDetails();
        return details.some(canBulkEditSelectedMessageDetail);
    }

    function syncMessageSelectionActionAvailability() {
        if (!messageSelectionToolbarEl) {
            return;
        }

        const editBtn = messageSelectionToolbarEl.querySelector('[data-selection-action="edit"]');
        if (!editBtn) {
            return;
        }

        const canEditSelection = canBulkEditCurrentSelection();
        editBtn.disabled = !canEditSelection;
        editBtn.setAttribute('title', canEditSelection ? 'Edit' : 'Only your own text messages can be edited');
        editBtn.setAttribute('aria-label', canEditSelection ? 'Edit' : 'Only your own text messages can be edited');

        if (!canEditSelection && messageSelectionActionMode === 'edit') {
            closeMessageSelectionPopover();
        }
    }

    function applyMessageTextUpdateToElement(messageEl, newText) {
        if (!messageEl || !messageEl._qtMessageRenderContext) {
            return false;
        }

        const normalizedNewText = String(newText || '').trim();
        if (!normalizedNewText) {
            return false;
        }

        const nextContext = {
            ...messageEl._qtMessageRenderContext,
            rawHtml: normalizedNewText
        };

        if (nextContext.translationKey) {
            messageTranslationStates.delete(nextContext.translationKey);
        }

        messageEl._qtMessageRenderContext = nextContext;
        if (messageEl._qtMessageRecord) {
            messageEl._qtMessageRecord.message = normalizedNewText;
        }

        syncRenderedMessageTranslation(messageEl);
        return true;
    }

    async function buildSelectedMessagesSummaryState(selectedDetails = getSelectedMessageDetails()) {
        const safeSelectedDetails = Array.isArray(selectedDetails) ? selectedDetails : [];
        const summaryEntries = await Promise.all(safeSelectedDetails.map(async detail => {
            return buildSummaryContextEntry({
                messageEl: detail && detail.messageEl ? detail.messageEl : null,
                messageRecord: detail && detail.messageRecord ? detail.messageRecord : null,
                rawMessage: detail && detail.rawMessage ? detail.rawMessage : ''
            });
        }));

        const usableEntries = summaryEntries.filter(entry => entry && entry.bodyText);

        if (!usableEntries.length) {
            return null;
        }

        return {
            selectedCount: usableEntries.length,
            voiceMessageCount: usableEntries.filter(entry => entry.wasVoiceMessage).length,
            transcribedVoiceCount: usableEntries.filter(entry => entry.usedVoiceTranscription).length,
            voiceFallbackCount: usableEntries.filter(entry => entry.usedVoiceFallback).length,
            contextLines: usableEntries.map((entry, index) => {
                const timeLabel = formatUnreadDividerTime(entry.timestamp);
                return `${index + 1}. ${timeLabel} - ${entry.senderLabel}: ${entry.bodyText}`;
            })
        };
    }

    function closeMessageSelectionPopover() {
        messageSelectionActionMode = '';
        if (!messageSelectionPopoverEl) {
            return;
        }
        messageSelectionPopoverEl.hidden = true;
        messageSelectionPopoverEl.innerHTML = '';
    }

    function syncMessageSelectionCount() {
        ensureMessageSelectionToolbar();
        if (messageSelectionCountEl) {
            const count = selectedMessageIds.size;
            messageSelectionCountEl.textContent = count === 1
                ? '1 message selected'
                : `${count} messages selected`;
        }
    }

    function activateMessageSelectionModeUi() {
        ensureMessageSelectionToolbar();
        messageSelectMode = true;
        if (chatContainerEl) {
            chatContainerEl.classList.add('message-select-mode');
        }
        if (chatHeaderEl) {
            chatHeaderEl.classList.add('is-message-select-mode');
        }
        syncMessageSelectionCount();
    }

    function exitMessageSelectionMode() {
        selectedMessageIds.clear();
        messageSelectMode = false;
        closeMessageSelectionPopover();
        if (chatContainerEl) {
            chatContainerEl.classList.remove('message-select-mode');
        }
        if (chatHeaderEl) {
            chatHeaderEl.classList.remove('is-message-select-mode');
        }
        if (chatBox) {
            chatBox.querySelectorAll('.message.is-selected').forEach(messageEl => {
                messageEl.classList.remove('is-selected');
            });
        }
    }

    function syncMessageSelectionUi() {
        const selectedElements = getSelectedMessageElements();
        if (!selectedElements.length) {
            exitMessageSelectionMode();
            return;
        }

        activateMessageSelectionModeUi();
        syncMessageSelectionActionAvailability();
    }

    function setMessageSelected(messageEl, shouldSelect) {
        if (!isMessageSelectable(messageEl)) {
            return false;
        }

        const messageId = String(getMessageServerId(messageEl) || '');
        if (!messageId) {
            return false;
        }

        if (shouldSelect) {
            selectedMessageIds.add(messageId);
        } else {
            selectedMessageIds.delete(messageId);
        }
        messageEl.classList.toggle('is-selected', shouldSelect);
        return true;
    }

    function toggleMessageSelected(messageEl, forceValue = null) {
        if (!isMessageSelectable(messageEl)) {
            return;
        }

        const messageId = String(getMessageServerId(messageEl) || '');
        if (!messageId) {
            return;
        }

        const nextValue = typeof forceValue === 'boolean'
            ? forceValue
            : !selectedMessageIds.has(messageId);

        if (!nextValue && selectedMessageIds.size === 1 && selectedMessageIds.has(messageId)) {
            exitMessageSelectionMode();
            return;
        }

        setMessageSelected(messageEl, nextValue);
        syncMessageSelectionUi();
    }

    function enterMessageSelectionMode(messageEl) {
        if (!isMessageSelectable(messageEl)) {
            return;
        }

        closeOpenMessageActionsMenu();
        removeInlineReactPicker();
        activateMessageSelectionModeUi();
        setMessageSelected(messageEl, true);
        syncMessageSelectionUi();
    }

    function enterEmptyMessageSelectionMode() {
        closeOpenMessageActionsMenu();
        removeInlineReactPicker();
        closeMessageSelectionPopover();
        selectedMessageIds.clear();
        if (chatBox) {
            chatBox.querySelectorAll('.message.is-selected').forEach(messageEl => {
                messageEl.classList.remove('is-selected');
            });
        }
        activateMessageSelectionModeUi();
    }

    function getClientPointDistanceToRect(clientX, clientY, rect) {
        const deltaX = clientX < rect.left
            ? (rect.left - clientX)
            : (clientX > rect.right ? (clientX - rect.right) : 0);
        const deltaY = clientY < rect.top
            ? (rect.top - clientY)
            : (clientY > rect.bottom ? (clientY - rect.bottom) : 0);

        return Math.hypot(deltaX, deltaY);
    }

    function getClosestSelectableMessageToClientPoint(clientX, clientY) {
        if (!chatBox) {
            return null;
        }

        let closestMessageEl = null;
        let closestDistance = Number.POSITIVE_INFINITY;
        let closestVerticalDistance = Number.POSITIVE_INFINITY;

        Array.from(chatBox.querySelectorAll('.message')).forEach(messageEl => {
            if (!isMessageSelectable(messageEl)) {
                return;
            }

            const rect = messageEl.getBoundingClientRect();
            if (!rect || (!rect.width && !rect.height)) {
                return;
            }

            const distance = getClientPointDistanceToRect(clientX, clientY, rect);
            const verticalDistance = Math.abs((rect.top + (rect.height / 2)) - clientY);

            if (
                distance < closestDistance
                || (distance === closestDistance && verticalDistance < closestVerticalDistance)
            ) {
                closestMessageEl = messageEl;
                closestDistance = distance;
                closestVerticalDistance = verticalDistance;
            }
        });

        return closestMessageEl;
    }

    function selectClosestMessageToClientPoint(clientX, clientY) {
        if (!Number.isFinite(clientX) || !Number.isFinite(clientY)) {
            return false;
        }

        const closestMessageEl = getClosestSelectableMessageToClientPoint(clientX, clientY);
        if (!closestMessageEl) {
            return false;
        }

        if (!messageSelectMode) {
            enterMessageSelectionMode(closestMessageEl);
            return true;
        }

        closeOpenMessageActionsMenu();
        removeInlineReactPicker();
        setMessageSelected(closestMessageEl, true);
        syncMessageSelectionUi();
        return true;
    }

    function canDeleteMessageForEveryone(messageEl) {
        if (!isMessageSelectable(messageEl)) {
            return false;
        }

        if (messageEl.classList.contains('self')) {
            return true;
        }

        const activeChatKey = String(selectedUser || '').trim();
        if (!activeChatKey) {
            return false;
        }

        if (activeChatKey.startsWith('ai:')) {
            return true;
        }

        if (!isGroupChatKey(activeChatKey)) {
            return false;
        }

        const meta = getContactMeta(activeChatKey);
        return !!(meta && (meta.canManageGroup || isGroupOwnerMeta(meta)));
    }

    async function deleteSelectedMessageElement(messageEl, scope) {
        const messageId = getMessageServerId(messageEl);
        if (!(messageId > 0)) {
            return false;
        }

        const formData = new FormData();
        formData.append('token', token);
        formData.append('message_id', String(messageId));
        formData.append('scope', scope);

        try {
            const response = await fetch('delete_message.php', {
                method: 'POST',
                body: formData
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                return false;
            }
            removeMessageElementWithTimestampCleanup(messageEl);
            return true;
        } catch (error) {
            console.error('Bulk delete failed for message', messageId, error);
            return false;
        }
    }

    async function applyBulkDelete(scope = 'me') {
        const selectedElements = getSelectedMessageElements();
        if (!selectedElements.length) {
            exitMessageSelectionMode();
            return;
        }

        let deletedCount = 0;
        let skippedCount = 0;

        for (const messageEl of selectedElements) {
            if (scope === 'everyone' && !canDeleteMessageForEveryone(messageEl)) {
                skippedCount += 1;
                continue;
            }

            const deleted = await deleteSelectedMessageElement(messageEl, scope);
            if (deleted) {
                deletedCount += 1;
            }
        }

        exitMessageSelectionMode();
        invalidateSidebarHistoryCache({ reloadIfVisible: true });
        loadContactPreviews().catch(() => {});
        sortContactsList();

        if (scope === 'everyone' && deletedCount === 0) {
            showToast('No selected messages could be deleted for everyone.', 'error');
            return;
        }

        if (deletedCount > 0 && skippedCount > 0) {
            showToast(`Deleted ${deletedCount} message${deletedCount === 1 ? '' : 's'}. Skipped ${skippedCount} without permission.`, 'info');
            return;
        }

        if (deletedCount > 0) {
            showToast(`Deleted ${deletedCount} message${deletedCount === 1 ? '' : 's'}.`, 'success');
        }
    }

    async function applyBulkEditMessages(nextText) {
        const selectedDetails = getSelectedMessageDetails();
        if (!selectedDetails.length) {
            exitMessageSelectionMode();
            return;
        }

        if (!canBulkEditCurrentSelection(selectedDetails)) {
            showToast('You can only change your own text messages.', 'error');
            closeMessageSelectionPopover();
            return;
        }

        const processedNewText = String(nextText || '').trim();
        if (!processedNewText) {
            showToast('Please enter a new message.', 'error');
            return;
        }

        let updatedCount = 0;
        let skippedCount = 0;
        let lastErrorMessage = '';

        for (const detail of selectedDetails) {
            if (!canBulkEditSelectedMessageDetail(detail)) {
                skippedCount += 1;
                continue;
            }

            try {
                const body = new URLSearchParams();
                body.append('token', token);
                body.append('message_id', String(detail.messageId));
                body.append('message', processedNewText);

                const response = await fetch('update_message.php', {
                    method: 'POST',
                    body
                });
                const data = await response.json().catch(() => ({}));
                if (!response.ok || !data.success) {
                    skippedCount += 1;
                    if (!lastErrorMessage) {
                        lastErrorMessage = data && data.error
                            ? String(data.error)
                            : 'Could not change one of those messages.';
                    }
                    continue;
                }

                applyMessageTextUpdateToElement(detail.messageEl, processedNewText);
                updatedCount += 1;
            } catch (error) {
                skippedCount += 1;
                if (!lastErrorMessage) {
                    lastErrorMessage = error && error.message
                        ? String(error.message)
                        : 'Could not change one of those messages.';
                }
                console.error('Bulk edit failed.', error);
            }
        }

        if (!updatedCount) {
            showToast(lastErrorMessage || `Failed to edit ${skippedCount} message${skippedCount === 1 ? '' : 's'}.`, 'error');
            return;
        }

        closeMessageSelectionPopover();
        exitMessageSelectionMode();
        invalidateSidebarHistoryCache({ reloadIfVisible: true });
        loadContactPreviews().catch(() => {});
        sortContactsList();

        if (skippedCount > 0) {
            showToast(
                `Successfully edited ${updatedCount} message${updatedCount === 1 ? '' : 's'}. Failed to edit ${skippedCount} message${skippedCount === 1 ? '' : 's'}.`,
                'success'
            );
            return;
        }

        showToast(`Successfully edited ${updatedCount} message${updatedCount === 1 ? '' : 's'}.`, 'success');
    }

    async function applyBulkReactionToMessages(emojis = []) {
        const messageIds = getSelectedMessageElements()
            .map(messageEl => getMessageServerId(messageEl))
            .filter(messageId => messageId > 0);
        const uniqueEmojis = Array.from(new Set((Array.isArray(emojis) ? emojis : []).map(emoji => String(emoji || '').trim()).filter(Boolean)));
        if (!messageIds.length || !uniqueEmojis.length) {
            return;
        }

        const messageType = getCurrentChatMessageType();

        for (const messageId of messageIds) {
            for (const emoji of uniqueEmojis) {
                await fetch('message_react.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        token,
                        message_type: messageType,
                        message_id: messageId,
                        emoji,
                        action: 'add'
                    })
                }).catch(error => {
                    console.warn('Bulk reaction failed.', error);
                });
                saveRecentReactionEmoji(emoji);
            }
        }

        closeMessageSelectionPopover();
        exitMessageSelectionMode();
        fetchReactionsForMessageIds(messageIds).catch(() => {});
    }

    async function sendBulkReplies(replyText) {
        const selectedDetails = getSelectedMessageDetails();
        if (!selectedDetails.length) {
            exitMessageSelectionMode();
            return;
        }

        if (selectedDetails.length > 5) {
            showToast('You can only reply to 5 messages or less at a time', 'error');
            return;
        }

        const processedReplyText = replaceShortcodesWithEmoji(String(replyText || '').trim());
        if (!processedReplyText) {
            showToast('Please enter a reply.', 'error');
            return;
        }

        const activeChatKey = String(selectedUser || '').trim();
        if (!activeChatKey) {
            showToast('Please select a chat first', 'error');
            return;
        }

        const isAiChat = activeChatKey.startsWith('ai:');
        const endpoint = isAiChat ? 'send_ai_message.php' : 'send_message.php';
        let sentCount = 0;

        for (const detail of selectedDetails) {
            const formData = new FormData();
            formData.append('token', token);
            if (isAiChat) {
                formData.append('ai_chat_key', activeChatKey);
            } else {
                formData.append('recipient_id', activeChatKey);
            }
            formData.append('message', processedReplyText);
            // Only send reply_to_id if it's a valid positive ID (not a local AI message ID)
            const messageId = Number(detail.messageId || 0);
            if (Number.isFinite(messageId) && messageId > 0) {
                formData.append('reply_to_id', String(messageId));
            }

            try {
                const response = await fetch(endpoint, {
                    method: 'POST',
                    body: formData
                });
                const data = await response.json().catch(() => ({}));
                if (!response.ok || !data.success) {
                    throw new Error(data && data.error ? data.error : 'Could not send reply.');
                }
                handleSuccessfulOutgoingNewMessage(data, null, activeChatKey);
                sentCount += 1;
            } catch (error) {
                console.error('Bulk reply failed.', error);
                showToast(error && error.message ? error.message : 'Could not send those replies.', 'error');
                break;
            }
        }

        if (sentCount > 0) {
            closeMessageSelectionPopover();
            exitMessageSelectionMode();
            showToast(`Sent ${sentCount} repl${sentCount === 1 ? 'y' : 'ies'}.`, 'success');
        }
    }

    function getSelectedTranslationTargets() {
        return getSelectedMessageDetails().map(detail => {
            const rawMessage = getTranslatableMessageText(detail.rawMessage);
            if (!rawMessage || !detail.translationKey) {
                return null;
            }

            return {
                messageTranslationKey: detail.translationKey,
                chatKey: String(selectedUser || ''),
                rawMessage
            };
        }).filter(Boolean);
    }

    function normalizeTranslateModalTargets(state) {
        const seenKeys = new Set();
        const targets = [];

        const appendTarget = source => {
            const messageTranslationKey = String(
                source && (source.messageTranslationKey || source.translationKey || '')
            ).trim();
            const rawMessage = source && typeof source.rawMessage === 'string'
                ? getTranslatableMessageText(source.rawMessage)
                : '';
            if (!messageTranslationKey || !rawMessage || seenKeys.has(messageTranslationKey)) {
                return;
            }

            seenKeys.add(messageTranslationKey);
            targets.push({
                messageTranslationKey,
                chatKey: String(source && (source.chatKey || '') || selectedUser || ''),
                rawMessage
            });
        };

        if (state && Array.isArray(state.messageTargets)) {
            state.messageTargets.forEach(appendTarget);
        }

        if (!targets.length) {
            appendTarget(state);
        }

        return targets;
    }

    function positionMessageSelectionPopover(anchorBtn) {
        if (!messageSelectionPopoverEl || !anchorBtn) {
            return;
        }

        const rect = anchorBtn.getBoundingClientRect();
        messageSelectionPopoverEl.style.left = '-9999px';
        messageSelectionPopoverEl.style.top = '0px';
        const popoverRect = messageSelectionPopoverEl.getBoundingClientRect();

        let left = rect.right - popoverRect.width;
        if (left < 12) {
            left = 12;
        }
        if (left + popoverRect.width > window.innerWidth - 12) {
            left = window.innerWidth - popoverRect.width - 12;
        }

        let top = rect.bottom + 10;
        if (top + popoverRect.height > window.innerHeight - 12) {
            top = rect.top - popoverRect.height - 10;
        }
        top = Math.max(12, top);

        messageSelectionPopoverEl.style.left = `${left}px`;
        messageSelectionPopoverEl.style.top = `${top}px`;
    }

    function ensureMessageSelectionToolbar() {
        if (messageSelectionToolbarEl || !chatHeaderEl) {
            return;
        }

        const toolbar = document.createElement('div');
        toolbar.className = 'message-select-toolbar';

        const closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.className = 'message-select-close';
        closeBtn.setAttribute('aria-label', 'Exit select mode');
        closeBtn.innerHTML = '<i class="fa-solid fa-xmark" aria-hidden="true"></i>';
        addTapAndClickListener(closeBtn, event => {
            event.stopPropagation();
            exitMessageSelectionMode();
        });

        const countEl = document.createElement('div');
        countEl.className = 'message-select-count';
        countEl.textContent = '0 messages selected';

        const actionsEl = document.createElement('div');
        actionsEl.className = 'message-select-actions';

        const createActionButton = (label, iconClass, onActivate) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'message-select-action-btn';
            button.dataset.selectionAction = String(label || '').trim().toLowerCase();
            button.setAttribute('aria-label', label);
            button.setAttribute('title', label);
            button.innerHTML = `<i class="${iconClass}" aria-hidden="true"></i>`;
            addTapAndClickListener(button, event => {
                event.stopPropagation();
                onActivate(button);
            });
            return button;
        };

        const reactBtn = createActionButton('React', 'fa-regular fa-face-smile', button => {
            toggleMessageSelectionPopover('react', button);
        });
        const replyBtn = createActionButton('Reply', 'fa-solid fa-reply', button => {
            if (getSelectedMessageElements().length > 5) {
                showToast('You can only reply to 5 messages or less at a time', 'error');
                closeMessageSelectionPopover();
                return;
            }
            toggleMessageSelectionPopover('reply', button);
        });
        const translateBtn = createActionButton('Translate', 'fa-solid fa-language', () => {
            const targets = getSelectedTranslationTargets();
            if (!targets.length) {
                showToast('Those messages cannot be translated.', 'error');
                return;
            }
            closeMessageSelectionPopover();
            openTranslateModal({
                chatKey: String(selectedUser || ''),
                messageTargets: targets
            });
        });
        const summaryBtn = createActionButton('AI Summary', 'fa-solid fa-wand-magic-sparkles', () => {
            closeMessageSelectionPopover();
            openSelectedMessagesSummaryModal().catch(error => {
                console.error('Selected message summary failed.', error);
            });
        });
        const editBtn = createActionButton('Edit', 'fa-solid fa-pen-to-square', button => {
            toggleMessageSelectionPopover('edit', button);
        });
        const deleteBtn = createActionButton('Delete', 'fa-solid fa-trash', button => {
            toggleMessageSelectionPopover('delete', button);
        });

        actionsEl.appendChild(reactBtn);
        actionsEl.appendChild(replyBtn);
        actionsEl.appendChild(translateBtn);
        actionsEl.appendChild(summaryBtn);
        actionsEl.appendChild(editBtn);
        actionsEl.appendChild(deleteBtn);

        toolbar.appendChild(closeBtn);
        toolbar.appendChild(countEl);
        toolbar.appendChild(actionsEl);
        chatHeaderEl.appendChild(toolbar);

        const popover = document.createElement('div');
        popover.className = 'message-select-popover';
        popover.hidden = true;
        popover.addEventListener('mousedown', event => {
            event.stopPropagation();
        });
        popover.addEventListener('click', event => {
            event.stopPropagation();
        });
        document.body.appendChild(popover);

        document.addEventListener('mousedown', event => {
            if (!messageSelectionPopoverEl || messageSelectionPopoverEl.hidden) {
                return;
            }
            if (messageSelectionPopoverEl.contains(event.target) || event.target.closest('.message-select-action-btn')) {
                return;
            }
            closeMessageSelectionPopover();
        });

        messageSelectionToolbarEl = toolbar;
        messageSelectionCountEl = countEl;
        messageSelectionPopoverEl = popover;
        syncMessageSelectionActionAvailability();
    }

    function toggleMessageSelectionPopover(mode, anchorBtn) {
        ensureMessageSelectionToolbar();
        if (!messageSelectionPopoverEl || !anchorBtn) {
            return;
        }

        if (mode === 'edit' && !canBulkEditCurrentSelection()) {
            showToast('You can only change your own text messages.', 'error');
            closeMessageSelectionPopover();
            return;
        }

        const isSameModeOpen = !messageSelectionPopoverEl.hidden && messageSelectionActionMode === mode;
        if (isSameModeOpen) {
            closeMessageSelectionPopover();
            return;
        }

        messageSelectionActionMode = mode;
        messageSelectionPopoverEl.hidden = false;
        messageSelectionPopoverEl.innerHTML = '';

        if (mode === 'delete') {
            messageSelectionDeleteScope = 'me';

            const title = document.createElement('div');
            title.className = 'message-select-popover-title';
            title.textContent = 'Delete selected messages';

            const options = document.createElement('div');
            options.className = 'message-select-delete-options';

            const createScopeButton = (scope, label) => {
                const button = document.createElement('button');
                button.type = 'button';
                button.className = 'message-select-scope-btn';
                button.textContent = label;
                button.classList.toggle('is-active', messageSelectionDeleteScope === scope);
                addTapAndClickListener(button, () => {
                    messageSelectionDeleteScope = scope;
                    options.querySelectorAll('.message-select-scope-btn').forEach(optionButton => {
                        optionButton.classList.toggle('is-active', optionButton === button);
                    });
                });
                return button;
            };

            const meButton = createScopeButton('me', 'Delete for me');
            const everyoneButton = createScopeButton('everyone', 'Delete for everyone');
            const confirmButton = document.createElement('button');
            confirmButton.type = 'button';
            confirmButton.className = 'message-select-confirm-btn';
            confirmButton.textContent = 'Confirm';
            addTapAndClickListener(confirmButton, () => {
                applyBulkDelete(messageSelectionDeleteScope).catch(error => {
                    console.error('Bulk delete failed.', error);
                });
            });

            options.appendChild(meButton);
            options.appendChild(everyoneButton);
            options.appendChild(confirmButton);
            messageSelectionPopoverEl.appendChild(title);
            messageSelectionPopoverEl.appendChild(options);
        } else if (mode === 'reply') {
            const title = document.createElement('div');
            title.className = 'message-select-popover-title';
            title.textContent = 'Reply';

            const form = document.createElement('div');
            form.className = 'message-select-reply-form';

            const input = document.createElement('textarea');
            input.className = 'message-select-reply-input';
            input.placeholder = 'Reply with';

            const confirmButton = document.createElement('button');
            confirmButton.type = 'button';
            confirmButton.className = 'message-select-reply-confirm';
            confirmButton.textContent = 'Confirm';
            addTapAndClickListener(confirmButton, () => {
                sendBulkReplies(input.value).catch(error => {
                    console.error('Bulk reply failed.', error);
                });
            });

            form.appendChild(input);
            form.appendChild(confirmButton);
            messageSelectionPopoverEl.appendChild(title);
            messageSelectionPopoverEl.appendChild(form);
            window.setTimeout(() => {
                try {
                    input.focus({ preventScroll: true });
                } catch (error) {}
            }, 20);
        } else if (mode === 'edit') {
            const title = document.createElement('div');
            title.className = 'message-select-popover-title';
            title.textContent = 'Change to...';

            const form = document.createElement('div');
            form.className = 'message-select-reply-form';

            const input = document.createElement('textarea');
            input.className = 'message-select-reply-input';
            input.placeholder = 'New message';
            input.addEventListener('keydown', event => {
                if (event.key === 'Enter' && !event.shiftKey) {
                    event.preventDefault();
                    confirmButton.click();
                }
            });

            const confirmButton = document.createElement('button');
            confirmButton.type = 'button';
            confirmButton.className = 'message-select-reply-confirm';
            confirmButton.textContent = 'Confirm';
            addTapAndClickListener(confirmButton, () => {
                applyBulkEditMessages(input.value).catch(error => {
                    console.error('Bulk edit failed.', error);
                });
            });

            form.appendChild(input);
            form.appendChild(confirmButton);
            messageSelectionPopoverEl.appendChild(title);
            messageSelectionPopoverEl.appendChild(form);
            window.setTimeout(() => {
                try {
                    input.focus({ preventScroll: true });
                } catch (error) {}
            }, 20);
        } else if (mode === 'react') {
            const title = document.createElement('div');
            title.className = 'message-select-popover-title';
            title.textContent = 'React';

            const grid = document.createElement('div');
            grid.className = 'message-select-react-grid';

            pickFiveReactionEmojis().forEach(emoji => {
                const button = document.createElement('button');
                button.type = 'button';
                button.className = 'message-select-react-emoji';
                button.textContent = emoji;
                button.setAttribute('aria-label', `React with ${emoji}`);
                addTapAndClickListener(button, () => {
                    applyBulkReactionToMessages([emoji]).catch(error => {
                        console.error('Bulk react failed.', error);
                    });
                });
                grid.appendChild(button);
            });

            const moreButton = document.createElement('button');
            moreButton.type = 'button';
            moreButton.className = 'message-select-react-more';
            moreButton.textContent = '+';
            moreButton.setAttribute('aria-label', 'More reactions');
            addTapAndClickListener(moreButton, () => {
                const selectedIds = getSelectedMessageElements()
                    .map(messageEl => getMessageServerId(messageEl))
                    .filter(messageId => messageId > 0);
                closeMessageSelectionPopover();
                openReactPickerModal(selectedIds);
            });
            grid.appendChild(moreButton);

            messageSelectionPopoverEl.appendChild(title);
            messageSelectionPopoverEl.appendChild(grid);
        }

        positionMessageSelectionPopover(anchorBtn);
    }

    function openMessageActionsMenu(menu, actionsWrap, anchorBtn) {
        if (!menu || !actionsWrap || !anchorBtn) {
            return;
        }

        if (openMessageActionsMenuEl && openMessageActionsMenuEl !== menu) {
            closeOpenMessageActionsMenu();
        }

        actionsWrap.classList.add('is-open');
        menu.classList.add('is-open');
        openMessageActionsMenuEl = menu;
        positionMessageActionsMenu(menu, anchorBtn);
    }

    function toggleMessageActionsMenu(menu, actionsWrap, anchorBtn) {
        if (!menu || !actionsWrap || !anchorBtn) {
            return;
        }

        if (menu.classList.contains('is-open')) {
            menu.classList.remove('is-open');
            actionsWrap.classList.remove('is-open');
            if (openMessageActionsMenuEl === menu) {
                openMessageActionsMenuEl = null;
            }
            return;
        }

        removeInlineReactPicker();
        openMessageActionsMenu(menu, actionsWrap, anchorBtn);
    }

    function isQuillTalkAiDisplayName(value) {
        return String(value || '').trim().toLowerCase() === QUILLTALK_AI_MENTION_NAME.toLowerCase();
    }

    function isQuillTalkAiMessageRecord(messageRecord) {
        if (!messageRecord || typeof messageRecord !== 'object') {
            return false;
        }

        if (isLocalAiMessageRecord(messageRecord)) {
            return messageRecord._localAiRole !== 'prompt';
        }

        return messageRecord.is_ai_response === true
            || messageRecord.is_ai_response === 1
            || messageRecord.is_ai_response === '1'
            || String(messageRecord.sender_type || '').toLowerCase() === 'ai'
            || isQuillTalkAiDisplayName(messageRecord.sender_display_name || messageRecord.display_name || '');
    }

    function messageRepliesToQuillTalkAi(messageRecord) {
        if (!messageRecord || !messageRecord.reply_to_id) {
            return false;
        }

        return isQuillTalkAiDisplayName(messageRecord.reply_to_display_name || '');
    }

    function beginReplyToMessage(messageId, displayName, rawMessage, options = {}) {
        pendingReply = {
            id: messageId,
            name: displayName,
            snippet: getMessageSnippetForReply(rawMessage),
            message: rawMessage,
            isAi: !!(options && options.isAi) || isQuillTalkAiDisplayName(displayName)
        };
        updateReplyBar();
    }

    function normalizeReplyReferenceId(value) {
        const parsed = Number(value || 0);
        return Number.isFinite(parsed) && parsed !== 0 ? Math.trunc(parsed) : 0;
    }

    function normalizeReplyReference(reference) {
        if (!reference || typeof reference !== 'object') {
            return null;
        }

        const replyId = normalizeReplyReferenceId(reference.id ?? reference.reply_to_id ?? reference.replyId);
        if (!replyId) {
            return null;
        }

        return {
            id: replyId,
            name: String(reference.name || reference.displayName || reference.reply_to_display_name || '').trim(),
            message: String(reference.message || reference.body || reference.snippet || reference.reply_to_message_body || '').trim()
        };
    }

    function applyReplyReferenceToMessage(messageRecord, reference) {
        if (!messageRecord || typeof messageRecord !== 'object') {
            return messageRecord;
        }

        const normalizedReference = normalizeReplyReference(reference);
        if (!normalizedReference) {
            return messageRecord;
        }

        if (!normalizeReplyReferenceId(messageRecord.reply_to_id)) {
            messageRecord.reply_to_id = normalizedReference.id;
        }
        if (!normalizeReplyReferenceId(messageRecord.reply_to_ref_id)) {
            messageRecord.reply_to_ref_id = normalizedReference.id;
        }
        if (!String(messageRecord.reply_to_display_name || '').trim()) {
            messageRecord.reply_to_display_name = normalizedReference.name || 'Message';
        }
        if (!String(messageRecord.reply_to_message_body || '').trim()) {
            messageRecord.reply_to_message_body = normalizedReference.message || '';
        }

        return messageRecord;
    }

    function attachPrivateLocalAiMessageActions({
        messageEl,
        bubbleEl,
        bubbleRowEl,
        messageRecord,
        displayName,
        messageChatKey,
        messageTranslationKey,
        attachmentMessage,
        isSelfMessage
    }) {
        const canUseLocalOnlyActions = supportsLocalAiLocalOnlyActions(messageRecord);
        if (
            !messageEl
            || !bubbleEl
            || !bubbleRowEl
            || !messageRecord
            || !canUseLocalOnlyActions
        ) {
            return null;
        }

        const messageId = getMessageServerId(messageRecord);
        if (!Number.isFinite(messageId) || messageId === 0 || !messageChatKey) {
            return null;
        }

        let aiImageImproviserShell = null;
        let aiImageImproviserInput = null;
        if (
            attachmentMessage
            && attachmentMessage.aiGenerated
            && attachmentMessage.kind === 'image'
            && !attachmentMessage.pending
        ) {
            aiImageImproviserShell = document.createElement('div');
            aiImageImproviserShell.className = 'message-ai-improvise-shell';
            aiImageImproviserShell.dataset.messageId = String(messageId);
            aiImageImproviserShell.addEventListener('mousedown', ev => ev.stopPropagation());
            aiImageImproviserShell.addEventListener('pointerdown', stopEventPropagation);
            aiImageImproviserShell.addEventListener('pointerup', stopEventPropagation);
            aiImageImproviserShell.addEventListener('touchstart', stopEventPropagation, { passive: true });

            const aiImageImproviserForm = document.createElement('div');
            aiImageImproviserForm.className = 'message-ai-improvise-form';

            aiImageImproviserInput = document.createElement('input');
            aiImageImproviserInput.type = 'text';
            aiImageImproviserInput.className = 'message-ai-improvise-input';
            aiImageImproviserInput.placeholder = 'Improvise';
            aiImageImproviserInput.setAttribute('aria-label', 'Improvise this AI image');

            const aiImageImproviserSend = document.createElement('button');
            aiImageImproviserSend.type = 'button';
            aiImageImproviserSend.className = 'message-actions-btn message-ai-improvise-send';
            aiImageImproviserSend.innerHTML = '<i class="fa-solid fa-paper-plane"></i>';
            aiImageImproviserSend.setAttribute('aria-label', 'Send improvise request');

            const setImproviserBusyState = busy => {
                aiImageImproviserInput.disabled = !!busy;
                aiImageImproviserSend.disabled = !!busy;
            };

            const submitImprovisation = async event => {
                if (event) {
                    event.preventDefault();
                    event.stopPropagation();
                }

                const nextInstructions = String(aiImageImproviserInput.value || '').trim();
                if (!nextInstructions) {
                    aiImageImproviserInput.focus();
                    return;
                }

                setImproviserBusyState(true);
                try {
                    await requestAiImageImprovisation(messageEl, nextInstructions);
                } catch (error) {
                    alert(error && error.message ? error.message : 'Unable to improvise that AI image right now.');
                    setImproviserBusyState(false);
                }
            };

            aiImageImproviserInput.addEventListener('keydown', event => {
                if (event.key === 'Enter') {
                    submitImprovisation(event);
                }
            });
            addTapAndClickListener(aiImageImproviserSend, submitImprovisation);

            aiImageImproviserForm.appendChild(aiImageImproviserInput);
            aiImageImproviserForm.appendChild(aiImageImproviserSend);
            aiImageImproviserShell.appendChild(aiImageImproviserForm);
            bubbleEl.appendChild(aiImageImproviserShell);
        }

        const actionsWrap = document.createElement('div');
        actionsWrap.className = 'message-actions-wrap message-quick-actions';

        const reactBtn = document.createElement('button');
        reactBtn.type = 'button';
        reactBtn.className = 'message-actions-btn';
        reactBtn.innerHTML = '<i class="fa-regular fa-face-smile"></i>';
        reactBtn.setAttribute('aria-label', 'React to message');

        const replyBtn = document.createElement('button');
        replyBtn.type = 'button';
        replyBtn.className = 'message-actions-btn';
        replyBtn.innerHTML = '<i class="fa-solid fa-reply"></i>';
        replyBtn.setAttribute('aria-label', 'Reply to message');

        const menuBtn = document.createElement('button');
        menuBtn.type = 'button';
        menuBtn.className = 'message-actions-btn';
        menuBtn.classList.add('mobile-message-menu-btn');
        menuBtn.innerHTML = '<i class="fa-solid fa-ellipsis-vertical"></i>';
        menuBtn.setAttribute('aria-label', 'Message actions');

        const improviseBtn = aiImageImproviserShell ? document.createElement('button') : null;
        if (improviseBtn) {
            improviseBtn.type = 'button';
            improviseBtn.className = 'message-actions-btn';
            improviseBtn.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i>';
            improviseBtn.setAttribute('aria-label', 'Improvise AI image');
            improviseBtn.title = 'Improvise AI image';
        }

        const menu = document.createElement('div');
        menu.className = 'message-actions-menu';
        const isPinnedMessage = isPinnedMessageForChat(messageChatKey, messageId);
        const translatableMessageText = getTranslatableMessageText(messageRecord.message);
        let menuHtml = ''
            + '<button type="button" class="message-actions-item mobile-only-message-action" data-act="react"><i class="fa-regular fa-face-smile"></i> React</button>'
            + '<button type="button" class="message-actions-item mobile-only-message-action" data-act="reply"><i class="fa-solid fa-reply"></i> Reply</button>'
            + '<button type="button" class="message-actions-item" data-act="forward"><i class="fa-solid fa-share"></i> Forward</button>';
        if (aiImageImproviserShell) {
            menuHtml += '<button type="button" class="message-actions-item" data-act="improvise"><i class="fa-solid fa-wand-magic-sparkles"></i> Improvise</button>';
        }
        menuHtml += `<button type="button" class="message-actions-item" data-act="${isPinnedMessage ? 'unpin-message' : 'pin-message'}"><i class="fa-solid fa-thumbtack"></i> ${isPinnedMessage ? 'Unpin message' : 'Pin message'}</button>`;
        if (translatableMessageText) {
            menuHtml += '<button type="button" class="message-actions-item" data-act="translate"><i class="fa-solid fa-language"></i> Translate</button>';
        }
        menuHtml += '<button type="button" class="message-actions-item" data-act="delete-local-ai"><i class="fa-solid fa-trash"></i> Delete</button>';
        menu.innerHTML = menuHtml;

        const openReactionMenu = (anchorEl = reactBtn) => {
            closeOpenMessageActionsMenu();
            removeInlineReactPicker();
            openInlineReactPicker(anchorEl, messageId, {
                localOnly: true,
                chatKey: messageChatKey
            });
        };

        const queueReplyAction = () => {
            beginReplyToMessage(messageId, displayName, messageRecord.message, {
                isAi: isQuillTalkAiMessageRecord(messageRecord)
            });
        };

        const toggleAiImageImproviserShell = () => {
            if (!aiImageImproviserShell) {
                return;
            }

            const nextIsOpen = !aiImageImproviserShell.classList.contains('is-open');
            closeOpenAiImageImproviser(nextIsOpen ? messageId : 0);
            aiImageImproviserShell.classList.toggle('is-open', nextIsOpen);
            if (nextIsOpen && aiImageImproviserInput) {
                window.setTimeout(() => {
                    try {
                        aiImageImproviserInput.focus();
                        aiImageImproviserInput.select();
                    } catch (error) {}
                }, 0);
            }
        };

        if (window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
            const syncHoverVisibility = visible => {
                if (menu.classList.contains('is-open')) {
                    actionsWrap.classList.add('is-hover-visible');
                    return;
                }
                actionsWrap.classList.toggle('is-hover-visible', !!visible);
            };
            messageEl.addEventListener('pointerenter', () => syncHoverVisibility(true));
            messageEl.addEventListener('pointerleave', () => syncHoverVisibility(false));
            bubbleRowEl.addEventListener('pointerenter', () => syncHoverVisibility(true));
            bubbleRowEl.addEventListener('pointerleave', () => syncHoverVisibility(false));
            messageEl.addEventListener('mouseenter', () => syncHoverVisibility(true));
            messageEl.addEventListener('mouseleave', () => syncHoverVisibility(false));
            bubbleRowEl.addEventListener('mouseenter', () => syncHoverVisibility(true));
            bubbleRowEl.addEventListener('mouseleave', () => syncHoverVisibility(false));
        }

        [menuBtn, reactBtn, replyBtn, improviseBtn].forEach(button => {
            if (!button) {
                return;
            }
            button.addEventListener('mousedown', ev => ev.stopPropagation());
            button.addEventListener('pointerdown', stopEventPropagation);
            button.addEventListener('pointerup', stopEventPropagation);
            button.addEventListener('touchstart', stopEventPropagation, { passive: true });
        });
        menu.addEventListener('mousedown', ev => ev.stopPropagation());
        menu.addEventListener('pointerdown', stopEventPropagation);
        menu.addEventListener('pointerup', stopEventPropagation);
        menu.addEventListener('touchstart', stopEventPropagation, { passive: true });

        addTapAndClickListener(menuBtn, ev => {
            ev.stopPropagation();
            toggleMessageActionsMenu(menu, actionsWrap, menuBtn);
        });
        addTapAndClickListener(reactBtn, ev => {
            ev.stopPropagation();
            openReactionMenu(reactBtn);
        });
        addTapAndClickListener(replyBtn, ev => {
            ev.stopPropagation();
            closeOpenMessageActionsMenu();
            removeInlineReactPicker();
            queueReplyAction();
        });
        if (improviseBtn) {
            addTapAndClickListener(improviseBtn, ev => {
                ev.stopPropagation();
                closeOpenMessageActionsMenu();
                removeInlineReactPicker();
                toggleAiImageImproviserShell();
            });
        }

        Array.from(menu.querySelectorAll('.message-actions-item')).forEach(item => {
            item.addEventListener('pointerdown', stopEventPropagation);
            item.addEventListener('touchstart', stopEventPropagation, { passive: true });
            addTapAndClickListener(item, ev => {
                ev.stopPropagation();
                const act = item.dataset.act;
                menu.classList.remove('is-open');
                actionsWrap.classList.remove('is-open');
                actionsWrap.classList.remove('is-hover-visible');
                if (openMessageActionsMenuEl === menu) {
                    openMessageActionsMenuEl = null;
                }

                if (act === 'react') {
                    openReactionMenu(bubbleEl);
                } else if (act === 'reply') {
                    queueReplyAction();
                } else if (act === 'forward') {
                    forwardMessagePayload = {
                        messageBody: messageRecord.message,
                        forwardFromUserId: Number(messageRecord.sender_id || 0),
                        forwardFromDisplayName: isSelfMessage ? 'You' : displayName
                    };
                    openForwardModal();
                } else if (act === 'improvise') {
                    toggleAiImageImproviserShell();
                } else if (act === 'pin-message') {
                    const pinnedRecord = buildPinnedMessageRecord(messageRecord, displayName);
                    if (pinnedRecord) {
                        setPinnedMessageForChat(messageChatKey, pinnedRecord);
                    }
                } else if (act === 'unpin-message') {
                    clearPinnedMessageForChat(messageChatKey);
                } else if (act === 'translate') {
                    openTranslateModal({
                        messageTranslationKey,
                        messageId,
                        chatKey: messageChatKey,
                        rawMessage: messageRecord.message
                    });
                } else if (act === 'delete-local-ai') {
                    const deletePrompt = messageRecord._localAiPrivate
                        ? 'Delete this private AI message on this device only?'
                        : 'Delete this local AI message on this device only?';
                    if (!confirm(deletePrompt)) {
                        return;
                    }
                    if (!removeStoredLocalAiMessage(messageChatKey, messageId)) {
                        alert(messageRecord._localAiPrivate
                            ? 'Could not delete that private AI message.'
                            : 'Could not delete that local AI message.');
                        return;
                    }
                    removeStoredLocalAiReactions(messageChatKey, messageId);
                    if (pendingReply && String(pendingReply.id || '') === String(messageId)) {
                        pendingReply = null;
                        updateReplyBar();
                    }
                    clearPinnedMessageIfMatches(messageChatKey, messageId);
                    closeOpenAiImageImproviser();
                    removeMessageElementWithTimestampCleanup(messageEl);
                    invalidateSidebarHistoryCache({ reloadIfVisible: true });
                    loadContactPreviews().catch(() => {});
                    sortContactsList();
                }
            });
        });

        actionsWrap.appendChild(reactBtn);
        actionsWrap.appendChild(replyBtn);
        if (improviseBtn) {
            actionsWrap.appendChild(improviseBtn);
        }
        actionsWrap.appendChild(menuBtn);
        actionsWrap.appendChild(menu);
        bubbleRowEl.appendChild(actionsWrap);

        bindMobileMessageGestures(messageEl, bubbleEl, {
            onLongPress: () => {
                if (!menu.classList.contains('is-open')) {
                    openMessageActionsMenu(menu, actionsWrap, bubbleEl);
                }
            },
            onDoubleTap: () => {
                openReactionMenu(bubbleEl);
            }
        });

        return actionsWrap;
    }

    function shouldIgnoreMessageLongPressTarget(target) {
        if (!target) {
            return false;
        }

        if (target.closest('.attachment-image-trigger, .attachment-file')) {
            return false;
        }

        return !!target.closest(
            'a, button, input, textarea, select, label, audio, .message-actions-wrap, .message-actions-menu, .message-ai-improvise-shell, .reaction-bubble, .reaction-picker-inline, .voice-message-play, .group-call-join-btn, .message-inline-emoji'
        );
    }

    function shouldIgnoreMessageDoubleTapTarget(target) {
        return !!(target && target.closest(
            'a, button, input, textarea, select, label, audio, .message-actions-wrap, .message-actions-menu, .message-ai-improvise-shell, .reaction-bubble, .reaction-picker-inline, .message-inline-emoji'
        ));
    }

    function bindMobileMessageGestures(messageEl, anchorEl, { onLongPress = null, onDoubleTap = null, onTripleTap = null } = {}) {
        if (!messageEl || !anchorEl || (!onLongPress && !onDoubleTap && !onTripleTap)) {
            return;
        }

        const longPressDelay = 420;
        const doubleTapDelay = 280;
        const moveTolerance = 12;
        let longPressTimer = null;
        let longPressTriggered = false;
        let trackingTouch = false;
        let touchStartX = 0;
        let touchStartY = 0;
        let lastTapAt = 0;
        let tapCount = 0;
        let tapActionTimer = null;

        const applySelectionGuard = () => {
            anchorEl.classList.add('qt-mobile-pressing');
        };

        const clearSelectionGuard = () => {
            anchorEl.classList.remove('qt-mobile-pressing');
        };

        const clearLongPress = () => {
            if (longPressTimer) {
                window.clearTimeout(longPressTimer);
                longPressTimer = null;
            }
        };

        const clearTapActionTimer = () => {
            if (tapActionTimer) {
                window.clearTimeout(tapActionTimer);
                tapActionTimer = null;
            }
        };

        const resetTouchTracking = () => {
            trackingTouch = false;
            longPressTriggered = false;
            clearLongPress();
            clearTapActionTimer();
            tapCount = 0;
            clearSelectionGuard();
        };

        anchorEl.addEventListener('touchstart', event => {
            if (!isMobileViewport() || shouldIgnoreMessageLongPressTarget(event.target)) {
                resetTouchTracking();
                return;
            }

            if (event.touches && event.touches.length !== 1) {
                resetTouchTracking();
                return;
            }

            trackingTouch = true;
            longPressTriggered = false;
            const touch = event.touches ? event.touches[0] : null;
            touchStartX = touch ? touch.clientX : 0;
            touchStartY = touch ? touch.clientY : 0;
            clearLongPress();
            applySelectionGuard();

            if (typeof onLongPress === 'function') {
                longPressTimer = window.setTimeout(() => {
                    longPressTimer = null;
                    longPressTriggered = true;
                    clearSelectionGuard();
                    try {
                        const selection = window.getSelection ? window.getSelection() : null;
                        if (selection && typeof selection.removeAllRanges === 'function') {
                            selection.removeAllRanges();
                        }
                    } catch (error) {}
                    try {
                        onLongPress(event);
                    } catch (error) {
                        console.error('Mobile long-press handler failed.', error);
                    }
                    try {
                        if (navigator.vibrate) {
                            navigator.vibrate(8);
                        }
                    } catch (error) {}
                    clearTapActionTimer();
                    tapCount = 0;
                }, longPressDelay);
            }
        }, { passive: true });

        anchorEl.addEventListener('touchmove', event => {
            if (!trackingTouch) {
                return;
            }

            const touch = event.touches ? event.touches[0] : null;
            if (!touch) {
                clearLongPress();
                return;
            }

            if (
                Math.abs(touch.clientX - touchStartX) > moveTolerance
                || Math.abs(touch.clientY - touchStartY) > moveTolerance
            ) {
                clearLongPress();
                clearSelectionGuard();
            }
        }, { passive: true });

        anchorEl.addEventListener('touchend', event => {
            if (!isMobileViewport()) {
                resetTouchTracking();
                return;
            }

            clearLongPress();
            trackingTouch = false;
            clearSelectionGuard();

            if (longPressTriggered) {
                longPressTriggered = false;
                try {
                    if (event.cancelable) {
                        event.preventDefault();
                    }
                } catch (error) {}
                stopEventPropagation(event);
                return;
            }

            if (typeof onDoubleTap !== 'function') {
                return;
            }

            if (shouldIgnoreMessageDoubleTapTarget(event.target)) {
                return;
            }

            const now = Date.now();
            if (typeof onTripleTap === 'function') {
                tapCount += 1;

                if (tapCount === 1) {
                    lastTapAt = now;
                    clearTapActionTimer();
                    tapActionTimer = window.setTimeout(() => {
                        tapActionTimer = null;
                        tapCount = 0;
                    }, doubleTapDelay);
                    return;
                }

                if ((now - lastTapAt) > doubleTapDelay) {
                    lastTapAt = now;
                    tapCount = 1;
                    clearTapActionTimer();
                    tapActionTimer = window.setTimeout(() => {
                        tapActionTimer = null;
                        tapCount = 0;
                    }, doubleTapDelay);
                    return;
                }

                lastTapAt = now;

                if (tapCount >= 3) {
                    tapCount = 0;
                    clearTapActionTimer();
                    try {
                        if (event.cancelable) {
                            event.preventDefault();
                        }
                    } catch (error) {}
                    stopEventPropagation(event);
                    try {
                        onTripleTap(event);
                    } catch (error) {
                        console.error('Mobile triple-tap handler failed.', error);
                    }
                    return;
                }

                clearTapActionTimer();
                tapActionTimer = window.setTimeout(() => {
                    tapActionTimer = null;
                    const shouldFireDoubleTap = tapCount === 2 && typeof onDoubleTap === 'function';
                    tapCount = 0;
                    if (!shouldFireDoubleTap) {
                        return;
                    }
                    try {
                        onDoubleTap(event);
                    } catch (error) {
                        console.error('Mobile double-tap handler failed.', error);
                    }
                }, doubleTapDelay);
                return;
            }

            if ((now - lastTapAt) <= doubleTapDelay) {
                lastTapAt = 0;
                try {
                    if (event.cancelable) {
                        event.preventDefault();
                    }
                } catch (error) {}
                stopEventPropagation(event);
                try {
                    onDoubleTap(event);
                } catch (error) {
                    console.error('Mobile double-tap handler failed.', error);
                }
            } else {
                lastTapAt = now;
            }
        }, { passive: false });

        anchorEl.addEventListener('touchcancel', resetTouchTracking, { passive: true });
        anchorEl.addEventListener('contextmenu', event => {
            if (!isMobileViewport() || shouldIgnoreMessageLongPressTarget(event.target)) {
                return;
            }
            if (event.cancelable) {
                event.preventDefault();
            }
            stopEventPropagation(event);
        });
    }

    function bindChatBackgroundSelectionGestures(containerEl) {
        if (!containerEl || containerEl.dataset.qtBackgroundSelectionBound === '1') {
            return;
        }

        containerEl.dataset.qtBackgroundSelectionBound = '1';

        const longPressDelay = 420;
        const moveTolerance = 12;
        let longPressTimer = null;
        let trackingTouch = false;
        let longPressTriggered = false;
        let touchStartX = 0;
        let touchStartY = 0;
        let startScrollTop = 0;
        let startScrollLeft = 0;

        const clearLongPress = () => {
            if (longPressTimer) {
                window.clearTimeout(longPressTimer);
                longPressTimer = null;
            }
        };

        const resetTouchTracking = () => {
            trackingTouch = false;
            longPressTriggered = false;
            clearLongPress();
        };

        const shouldTrackBackgroundPress = target => {
            if (!isMobileViewport() || !target) {
                return false;
            }

            if (typeof target.closest !== 'function') {
                return false;
            }

            return !target.closest(
                '.message-bubble, .message-actions-wrap, .message-actions-menu, .message-ai-improvise-shell, .reaction-picker-inline, .reaction-bubble, .voice-message-play, .attachment-image-trigger, .attachment-file, a, button, input, textarea, select, label, audio'
            );
        };

        containerEl.addEventListener('touchstart', event => {
            const touch = event.touches ? event.touches[0] : null;
            if (!touch || !shouldTrackBackgroundPress(event.target) || (event.touches && event.touches.length !== 1)) {
                resetTouchTracking();
                return;
            }

            trackingTouch = true;
            longPressTriggered = false;
            touchStartX = touch.clientX;
            touchStartY = touch.clientY;
            startScrollTop = containerEl.scrollTop;
            startScrollLeft = containerEl.scrollLeft;
            clearLongPress();

            longPressTimer = window.setTimeout(() => {
                longPressTimer = null;
                if (
                    !trackingTouch
                    || Math.abs(containerEl.scrollTop - startScrollTop) > 0
                    || Math.abs(containerEl.scrollLeft - startScrollLeft) > 0
                ) {
                    return;
                }

                try {
                    const selection = window.getSelection ? window.getSelection() : null;
                    if (selection && typeof selection.removeAllRanges === 'function') {
                        selection.removeAllRanges();
                    }
                } catch (error) {}
                if (!selectClosestMessageToClientPoint(touchStartX, touchStartY)) {
                    return;
                }

                longPressTriggered = true;
                try {
                    if (navigator.vibrate) {
                        navigator.vibrate(8);
                    }
                } catch (error) {}
            }, longPressDelay);
        }, { passive: true });

        containerEl.addEventListener('touchmove', event => {
            if (!trackingTouch) {
                return;
            }

            const touch = event.touches ? event.touches[0] : null;
            if (
                !touch
                || Math.abs(touch.clientX - touchStartX) > moveTolerance
                || Math.abs(touch.clientY - touchStartY) > moveTolerance
                || Math.abs(containerEl.scrollTop - startScrollTop) > 0
                || Math.abs(containerEl.scrollLeft - startScrollLeft) > 0
            ) {
                clearLongPress();
            }
        }, { passive: true });

        containerEl.addEventListener('touchend', event => {
            const didTrigger = longPressTriggered;
            resetTouchTracking();
            if (!didTrigger) {
                return;
            }
            try {
                if (event.cancelable) {
                    event.preventDefault();
                }
            } catch (error) {}
            stopEventPropagation(event);
        }, { passive: false });

        containerEl.addEventListener('touchcancel', resetTouchTracking, { passive: true });
    }

    function addTapAndClickListener(element, handler) {
        if (!element || typeof handler !== 'function') {
            return;
        }

        let lastGestureHandledAt = 0;
        let lastTouchHandledAt = 0;
        let suppressClickUntil = 0;
        let touchTracking = false;
        let touchMoved = false;
        let touchStartX = 0;
        let touchStartY = 0;
        // Allow 1px browser jitter while treating any visible drag as a drag.
        const touchMoveTolerance = 1;

        const getClientPoint = event => {
            if (event && event.changedTouches && event.changedTouches.length) {
                return {
                    x: Number(event.changedTouches[0].clientX || 0),
                    y: Number(event.changedTouches[0].clientY || 0)
                };
            }
            if (event && event.touches && event.touches.length) {
                return {
                    x: Number(event.touches[0].clientX || 0),
                    y: Number(event.touches[0].clientY || 0)
                };
            }
            if (event && typeof event.clientX === 'number' && typeof event.clientY === 'number') {
                return { x: event.clientX, y: event.clientY };
            }
            return null;
        };

        const isPrimaryActivationEvent = event => {
            if (!event) {
                return true;
            }
            if (event.touches && event.touches.length > 1) {
                return false;
            }
            if (typeof event.button === 'number' && event.button !== 0) {
                return false;
            }
            return true;
        };

        const resetTouchTracking = () => {
            touchTracking = false;
            touchMoved = false;
            touchStartX = 0;
            touchStartY = 0;
        };

        const startTouchTracking = event => {
            if (!isPrimaryActivationEvent(event)) {
                resetTouchTracking();
                return;
            }

            const point = getClientPoint(event);
            if (!point) {
                resetTouchTracking();
                return;
            }

            touchTracking = true;
            touchMoved = false;
            touchStartX = point.x;
            touchStartY = point.y;
        };

        const updateTouchTracking = event => {
            if (!touchTracking) {
                return;
            }

            const point = getClientPoint(event);
            if (!point) {
                return;
            }

            if (
                Math.abs(point.x - touchStartX) > touchMoveTolerance
                || Math.abs(point.y - touchStartY) > touchMoveTolerance
            ) {
                touchMoved = true;
            }
        };

        const releasedInsideElement = event => {
            const point = getClientPoint(event);
            if (!point || typeof document.elementFromPoint !== 'function') {
                return true;
            }

            const releaseTarget = document.elementFromPoint(point.x, point.y);
            return !!(releaseTarget && (releaseTarget === element || element.contains(releaseTarget)));
        };

        const releasedAtOriginalPoint = event => {
            const point = getClientPoint(event);
            if (!touchTracking || !point) {
                return true;
            }

            return (
                Math.abs(point.x - touchStartX) <= touchMoveTolerance
                && Math.abs(point.y - touchStartY) <= touchMoveTolerance
            );
        };

        const wrappedHandler = event => {
            const eventType = String(event && event.type || '');
            const pointerType = String(event && event.pointerType || '');
            const now = Date.now();
            const isTouchEvent = eventType.startsWith('touch') || pointerType === 'touch';
            const isActivationReleaseEvent = eventType === 'touchend' || eventType === 'pointerup' || eventType === 'click';
            const suppressDuplicateEvent = () => {
                try {
                    if (event && event.cancelable) {
                        event.preventDefault();
                    }
                } catch (error) {}
                try {
                    if (event) {
                        event.stopPropagation();
                    }
                } catch (error) {}
            };

            if (eventType === 'pointerup' && pointerType === 'touch') {
                return;
            }

            if (eventType === 'click' && now < suppressClickUntil) {
                suppressDuplicateEvent();
                return;
            }

            if (eventType === 'click' && (now - lastTouchHandledAt) < 420) {
                suppressDuplicateEvent();
                return;
            }

            if (isActivationReleaseEvent && touchTracking) {
                if (touchMoved || !releasedInsideElement(event) || !releasedAtOriginalPoint(event)) {
                    suppressClickUntil = now + 420;
                    if (eventType === 'click') {
                        suppressDuplicateEvent();
                    }
                    resetTouchTracking();
                    return;
                }
            }

            if (isTouchEvent) {
                lastTouchHandledAt = now;
            }

            if ((now - lastGestureHandledAt) < 280) {
                suppressDuplicateEvent();
                if (isTouchEvent) {
                    resetTouchTracking();
                }
                return;
            }

            try {
                if (event.cancelable) {
                    event.preventDefault();
                }
            } catch (error) {}
            try {
                event.stopPropagation();
            } catch (error) {}

            lastGestureHandledAt = now;
            handler(event);

            if (
                eventType === 'pointerup'
                || eventType === 'touchend'
                || eventType === 'pointercancel'
                || eventType === 'touchcancel'
            ) {
                resetTouchTracking();
            }
        };

        element.addEventListener('touchstart', startTouchTracking, { passive: true });
        element.addEventListener('touchmove', updateTouchTracking, { passive: true });
        element.addEventListener('touchcancel', resetTouchTracking, { passive: true });
        element.addEventListener('pointerdown', startTouchTracking);
        element.addEventListener('pointermove', updateTouchTracking);
        element.addEventListener('pointercancel', resetTouchTracking);
        element.addEventListener('click', wrappedHandler);
        element.addEventListener('touchend', wrappedHandler, { passive: false });
        element.addEventListener('pointerup', wrappedHandler);
    }

    window.addTapAndClickListener = addTapAndClickListener;

    function stopEventPropagation(event) {
        if (!event) {
            return;
        }
        try {
            event.stopPropagation();
        } catch (error) {}
    }

    function removeMessageElementWithTimestampCleanup(messageElement) {
        if (!messageElement || !messageElement.parentNode) {
            return;
        }

        const previousSibling = messageElement.previousElementSibling;
        messageElement.parentNode.removeChild(messageElement);

        if (
            previousSibling
            && previousSibling.classList
            && previousSibling.classList.contains('timestamp')
        ) {
            const nextSibling = previousSibling.nextElementSibling;
            if (!nextSibling || nextSibling.classList.contains('timestamp')) {
                previousSibling.remove();
            }
        }
    }

    function removeInlineReactPicker() {
        if (inlineReactPickerEl && inlineReactPickerEl.parentNode) {
            inlineReactPickerEl.parentNode.removeChild(inlineReactPickerEl);
        }
        inlineReactPickerEl = null;
    }

    function positionMessageActionsMenu(menu, anchorBtn) {
        const r = anchorBtn.getBoundingClientRect();
        const mw = 170;
        const mh = menu.scrollHeight || 200; // Use actual menu height
        
        // Horizontal positioning (left or right of button)
        let left = r.right + 6;
        if (left + mw > window.innerWidth - 8) {
            left = r.left - mw - 6;
        }
        
        // Vertical positioning - try down first, then up if no room
        let top = r.bottom + 6; // Position below button by default
        const spaceBelow = window.innerHeight - r.bottom;
        const spaceAbove = r.top;
        
        // If menu would overflow bottom and there's more space above, position above
        if (top + mh > window.innerHeight - 8 && spaceAbove > spaceBelow) {
            top = r.top - mh - 6; // Position above button
        }
        
        // Ensure menu stays within viewport bounds
        top = Math.max(8, Math.min(top, window.innerHeight - mh - 8));
        
        menu.style.left = `${Math.max(8, left)}px`;
        menu.style.top = `${top}px`;
    }

    async function fetchReactionsForMessageIds(ids, chatKey = String(selectedUser || '')) {
        if (!ids.length || !chatKey) return;
        const mt = getChatMessageType(chatKey);
        const res = await fetch(`get_reactions.php?token=${encodeURIComponent(token)}&message_type=${mt}&message_ids=${ids.join(',')}`);
        if (!res.ok) return;
        const grouped = await res.json();
        ids.forEach(id => {
            const row = findMessageElementByServerId(id);
            if (!row) return;
            const list = grouped[String(id)] || grouped[id] || [];
            renderMessageReactions(row, list, id);
        });
    }

    async function toggleMessageReaction(messageId, emoji, chatKey = String(selectedUser || '')) {
        const normalizedMessageId = Number(messageId || 0);
        const normalizedChatKey = String(chatKey || '').trim();
        if (normalizedMessageId < 0) {
            saveRecentReactionEmoji(emoji);
            const row = findMessageElementByAnyId(normalizedMessageId);
            const reactions = toggleStoredLocalAiReaction(normalizedChatKey, normalizedMessageId, emoji);
            if (row) {
                renderMessageReactions(row, reactions, normalizedMessageId);
            }
            return;
        }

        const mt = getChatMessageType(chatKey);
        const res = await fetch('message_react.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token, message_type: mt, message_id: normalizedMessageId, emoji, action: 'toggle' })
        });
        if (res.ok) {
            const data = await res.json().catch(() => ({}));
            saveRecentReactionEmoji(emoji);
            if (data.success && Array.isArray(data.reactions)) {
                const row = findMessageElementByServerId(normalizedMessageId);
                if (row) renderMessageReactions(row, data.reactions, normalizedMessageId);
            } else {
                await fetchReactionsForMessageIds([normalizedMessageId], normalizedChatKey);
            }
        }
    }

    let pendingRightSidebarRestoreUser = '';
    let pendingRightSidebarRestoreAttempts = 0;
    let pendingRightSidebarRestoreTimer = 0;

    function clearPendingRightSidebarRestore() {
        pendingRightSidebarRestoreUser = '';
        pendingRightSidebarRestoreAttempts = 0;
        if (pendingRightSidebarRestoreTimer) {
            clearTimeout(pendingRightSidebarRestoreTimer);
            pendingRightSidebarRestoreTimer = 0;
        }
    }

    function runPendingRightSidebarRestore() {
        const normalizedUserId = String(pendingRightSidebarRestoreUser || '').trim();
        if (!normalizedUserId || isMobileViewport()) {
            clearPendingRightSidebarRestore();
            return;
        }

        if (String(selectedUser || '').trim() !== normalizedUserId) {
            if (pendingRightSidebarRestoreAttempts >= 8) {
                clearPendingRightSidebarRestore();
                return;
            }
            pendingRightSidebarRestoreAttempts += 1;
            pendingRightSidebarRestoreTimer = window.setTimeout(runPendingRightSidebarRestore, 140);
            return;
        }

        openRightSidebar(normalizedUserId);
        const sidebarOpen = !!(rightSidebar && rightSidebar.classList.contains('is-open'));
        const activeSidebarUser = String((rightSidebar && rightSidebar.dataset && rightSidebar.dataset.activeUser) || '').trim();
        if (sidebarOpen && activeSidebarUser === normalizedUserId) {
            clearPendingRightSidebarRestore();
            return;
        }

        if (pendingRightSidebarRestoreAttempts >= 8) {
            clearPendingRightSidebarRestore();
            return;
        }

        pendingRightSidebarRestoreAttempts += 1;
        pendingRightSidebarRestoreTimer = window.setTimeout(runPendingRightSidebarRestore, 140);
    }

    function requestRightSidebarRestore(userId) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId || isMobileViewport()) {
            clearPendingRightSidebarRestore();
            return;
        }

        pendingRightSidebarRestoreUser = normalizedUserId;
        pendingRightSidebarRestoreAttempts = 0;
        if (pendingRightSidebarRestoreTimer) {
            clearTimeout(pendingRightSidebarRestoreTimer);
            pendingRightSidebarRestoreTimer = 0;
        }
        runPendingRightSidebarRestore();
    }

    async function readJsonResponseSafely(response) {
        const rawText = await response.text();
        let data = {};

        if (rawText) {
            try {
                data = JSON.parse(rawText);
            } catch (error) {
                data = {};
            }
        }

        return {
            data,
            rawText
        };
    }

    function cloneMessageRecordWithRawMessage(messageRecord, rawMessage) {
        if (!messageRecord || typeof messageRecord !== 'object') {
            return null;
        }

        return Object.assign({}, messageRecord, {
            message: String(rawMessage || '')
        });
    }

    function replaceRenderedMessage(messageRecord) {
        if (!chatBox || !messageRecord || typeof messageRecord !== 'object') {
            return null;
        }

        hydrateMessageSenderData(messageRecord);
        const messageClientId = getMessageClientId(messageRecord, getMessageChatKey(messageRecord));
        const currentElement = messageClientId
            ? chatBox.querySelector(`.message[data-id="${messageClientId}"]`)
            : findMessageElementByServerId(Number(messageRecord.id || 0));

        if (!currentElement || !currentElement.parentNode) {
            return null;
        }

        const messageData = buildMessageElementSafe(messageRecord);
        currentElement.parentNode.replaceChild(messageData.element, currentElement);
        if (typeof applyConsecutiveClassToAllMessages === 'function') {
            applyConsecutiveClassToAllMessages();
        }
        const normalizedMessageId = Math.max(0, Number(messageRecord.id || 0) || 0);
        if (normalizedMessageId > 0 && typeof fetchReactionsForMessageIds === 'function') {
            fetchReactionsForMessageIds([normalizedMessageId], String(getMessageChatKey(messageRecord) || selectedUser || '')).catch(() => {});
        }

        return messageData.element;
    }

    async function applyAiReactionToMessage(messageId, emoji, chatKey = String(selectedUser || '')) {
        const normalizedEmoji = String(emoji || '').trim();
        const normalizedMessageId = Number(messageId || 0);
        const normalizedChatKey = String(chatKey || '').trim();
        if (!(normalizedMessageId > 0) || !normalizedEmoji || !normalizedChatKey) {
            return false;
        }

        const mt = getChatMessageType(normalizedChatKey);
        const res = await fetch('message_react.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                token,
                message_type: mt,
                message_id: normalizedMessageId,
                emoji: normalizedEmoji,
                action: 'add',
                reactor_mode: 'ai',
                chat_key: normalizedChatKey
            })
        });

        if (!res.ok) {
            return false;
        }

        const data = await res.json().catch(() => ({}));
        if (data.success && Array.isArray(data.reactions)) {
            const row = findMessageElementByServerId(normalizedMessageId);
            if (row) {
                renderMessageReactions(row, data.reactions, normalizedMessageId);
            }
            return true;
        }

        await fetchReactionsForMessageIds([normalizedMessageId], normalizedChatKey);
        return true;
    }

    function renderMessageReactions(messageEl, reactions, messageId) {
        let container = messageEl.querySelector('.message-reactions');
        if (!container) {
            container = document.createElement('div');
            container.className = 'message-reactions';
            const stack = messageEl.querySelector('.message-body-stack');
            if (stack) stack.appendChild(container);
            else messageEl.appendChild(container);
        }
        container.innerHTML = '';
        container.dataset.messageId = String(messageId);
        messageEl.dataset.reactionsLoaded = '1';

        const tooltip = document.getElementById('reactionTooltip');

        reactions.forEach(r => {
            const bubble = document.createElement('div');
            bubble.className = 'reaction-bubble';
            if (Number(r.self_reacted)) bubble.classList.add('self-reacted');

            const em = document.createElement('span');
            em.className = 'r-emoji';
            em.textContent = r.emoji;

            const cnt = document.createElement('span');
            cnt.className = 'r-count';
            const cntNum = Number(r.cnt || 0);
            cnt.textContent = String(cntNum);

            bubble.appendChild(em);
            bubble.appendChild(cnt);

            // Build tooltip data
            const reactors = (r.reactors || '').split('||').filter(Boolean);
            const hasOthers = cntNum > 3;
            const shown = reactors.slice(0, 3);
            const othersCount = cntNum - 3;

            // Show custom tooltip on hover
            bubble.addEventListener('mouseenter', (ev) => {
                if (!tooltip) return;
                tooltip.innerHTML = '';
                const prefix = document.createTextNode(
                    cntNum <= 3
                        ? `Reacted by ${reactors.join(', ')}`
                        : `Reacted by ${shown.join(', ')} and `
                );
                tooltip.appendChild(prefix);

                if (hasOthers) {
                    tooltip.classList.add('has-link');
                    const othersLink = document.createElement('span');
                    othersLink.className = 'reaction-tooltip-others';
                    othersLink.textContent = `${othersCount} other${othersCount === 1 ? '' : 's'}`;
                    othersLink.addEventListener('click', (e) => {
                        e.stopPropagation();
                        tooltip.style.display = 'none';
                        openReactionUsersModal(messageId, r.emoji);
                    });
                    tooltip.appendChild(othersLink);
                } else {
                    tooltip.classList.remove('has-link');
                }

                tooltip.style.display = 'block';
                const rect = bubble.getBoundingClientRect();
                const tw = tooltip.offsetWidth || 200;
                let left = rect.left + rect.width / 2 - tw / 2;
                let top = rect.top - tooltip.offsetHeight - 6;
                if (left < 4) left = 4;
                if (left + tw > window.innerWidth - 4) left = window.innerWidth - tw - 4;
                if (top < 4) top = rect.bottom + 6;
                tooltip.style.left = left + 'px';
                tooltip.style.top = top + 'px';
            });

            bubble.addEventListener('mouseleave', (ev) => {
                // Delay hide so user can move mouse to the tooltip (for the link)
                setTimeout(() => {
                    if (tooltip && !tooltip.matches(':hover')) {
                        tooltip.style.display = 'none';
                    }
                }, 120);
            });

            if (tooltip) {
                tooltip.addEventListener('mouseleave', () => {
                    tooltip.style.display = 'none';
                });
            }

            // Click the bubble to toggle reaction
            addTapAndClickListener(bubble, () => {
                if (tooltip) tooltip.style.display = 'none';
                toggleMessageReaction(messageId, r.emoji);
            });

            container.appendChild(bubble);
        });
    }

    async function openReactionUsersModal(messageId, emoji) {
        const mt = getCurrentChatMessageType();
        const res = await fetch(`get_reaction_users.php?token=${encodeURIComponent(token)}&message_type=${mt}&message_id=${encodeURIComponent(messageId)}&emoji=${encodeURIComponent(emoji)}`);
        if (!res.ok) return;
        const data = await res.json();
        const users = data.users || [];
        if (reactionUsersModalTitle) {
            reactionUsersModalTitle.textContent = `${users.length} people reacted to this message`;
        }
        if (!reactionUsersModalList) return;
        reactionUsersModalList.innerHTML = '';
        users.forEach(u => {
            const row = document.createElement('div');
            row.className = 'forward-contact-row';
            row.style.cursor = 'pointer';
            const uid = String(u.user_id || '');
            const img = document.createElement('img');
            img.src = u.profile_pic || defaultProfilePic;
            const name = document.createElement('div');
            name.className = 'forward-contact-name';
            const displayNameForReaction = getDisplayNameForUser(uid, {
                displayName: u.display_name || uid,
                username: '',
                isGroup: false
            });
            name.textContent = displayNameForReaction;
            const wrap = document.createElement('div');
            wrap.className = 'message-avatar-wrapper';
            wrap.style.width = '36px';
            wrap.style.height = '36px';
            const dot = document.createElement('span');
            dot.className = 'message-presence-dot' + (Number(u.online) ? ' online' : '');
            ensurePresenceIndicatorChildren(dot);
            wrap.appendChild(img);
            wrap.appendChild(dot);
            row.appendChild(wrap);
            row.appendChild(name);
            row.addEventListener('click', () => {
                reactionUsersModal.classList.remove('open');
                reactionUsersModal.setAttribute('aria-hidden', 'true');
                userNamesMap[uid] = u.display_name || uid;
                userProfilePics[uid] = u.profile_pic || defaultProfilePic;
                userOnlineMap[uid] = Number(u.online) ? 1 : 0;
                updateContactInfoPanel(uid);
                setContactInfoOpen(true);
            });
            reactionUsersModalList.appendChild(row);
        });
        reactionUsersModal.classList.add('open');
        reactionUsersModal.setAttribute('aria-hidden', 'false');
    }

    async function refreshReadReceipts() {
        if (!selectedUser) return;
        try {
            const res = await fetch(`get_read_receipts.php?token=${encodeURIComponent(token)}&with=${encodeURIComponent(selectedUser)}`);
            if (!res.ok) return;
            const rows = await res.json();
            chatBox.querySelectorAll('.message-read-receipts-slot').forEach(el => {
                el.innerHTML = '';
            });
            rows.forEach(row => {
                const mid = Number(row.last_seen_message_id || 0);
                if (!mid) return;
                const msgEl = findMessageElementByServerId(mid) || chatBox.querySelector(`.message[data-id="${mid}"]`);
                if (!msgEl) return;
                const readerId = String(row.user_id || '');
                let slot = msgEl.querySelector('.message-read-receipts-slot');
                if (!slot) {
                    slot = document.createElement('div');
                    slot.className = 'message-read-receipts-slot read-receipts-row';
                    const stack = msgEl.querySelector('.message-body-stack');
                    if (stack) stack.appendChild(slot);
                    else msgEl.appendChild(slot);
                }
                const mini = document.createElement('div');
                mini.className = 'read-receipt-mini';
                if (readerId) {
                    mini.dataset.userId = readerId;
                }
                const displayNameForReceipt = readerId
                    ? getDisplayNameForUser(readerId, { displayName: row.display_name || '', username: '', isGroup: false })
                    : (row.display_name || '');
                mini.title = displayNameForReceipt;
                const presence = readerId
                    ? getMessagePresenceData(readerId, readerId === String(currentUserId))
                    : {
                        profilePic: normalizeProfilePic(row.profile_pic || defaultProfilePic, 'direct'),
                        isOnline: false
                    };
                const img = document.createElement('img');
                img.src = presence.profilePic;
                img.alt = displayNameForReceipt;
                const dot = document.createElement('span');
                dot.className = 'message-presence-dot';
                applyPresenceIndicatorState(dot, presence.isOnline, false);
                mini.appendChild(img);
                mini.appendChild(dot);
                slot.appendChild(mini);
            });
            applyConsecutiveClassToAllMessages();
        } catch (e) {
            console.warn('read receipts', e);
        }
    }

    const MESSAGE_GROUP_WINDOW_MS = 5 * 60 * 1000;

    function getMessageElementTimestampMs(messageEl) {
        if (!messageEl || !messageEl.dataset) {
            return 0;
        }

        return parseServerDateTimeMs(messageEl.dataset.timestamp || '');
    }

    function canRenderMessageConsecutively(previousMessage, messageEl, hasTimestampBetween = false) {
        if (
            !previousMessage
            || !messageEl
            || hasTimestampBetween
            || !previousMessage.classList
            || !messageEl.classList
        ) {
            return false;
        }

        if (
            !previousMessage.classList.contains('message')
            || previousMessage.classList.contains('call-event')
            || previousMessage.classList.contains('group-news-message')
            || messageEl.classList.contains('call-event')
            || messageEl.classList.contains('group-news-message')
        ) {
            return false;
        }

        if (previousMessage.dataset.senderId !== messageEl.dataset.senderId) {
            return false;
        }

        const previousTimestamp = getMessageElementTimestampMs(previousMessage);
        const currentTimestamp = getMessageElementTimestampMs(messageEl);
        if (
            previousTimestamp
            && currentTimestamp
            && Math.abs(currentTimestamp - previousTimestamp) >= MESSAGE_GROUP_WINDOW_MS
        ) {
            return false;
        }

        return true;
    }

    function scrollChatToMessageId(messageId) {
        const el = chatBox.querySelector(`.message[data-id="${messageId}"], .message[data-message-id="${messageId}"]`);
        if (!el) {
            alert('Message is not loaded yet. Scroll up to load older messages.');
            return;
        }
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('message-highlight-flash');
        setTimeout(() => el.classList.remove('message-highlight-flash'), 1100);
    }

    function updateReplyBar() {
        const replyBarEl = document.getElementById('replyBar');
        if (!replyBarEl) return;
        const replyBarNameEl = document.getElementById('replyBarName');
        const replyBarMsgEl = document.getElementById('replyBarMsg');
        if (!pendingReply) {
            replyBarEl.classList.remove('is-open');
            replyBarEl.setAttribute('aria-hidden', 'true');
            return;
        }
        replyBarEl.classList.add('is-open');
        replyBarEl.setAttribute('aria-hidden', 'false');
        if (replyBarNameEl) replyBarNameEl.textContent = pendingReply.name;
        if (replyBarMsgEl) replyBarMsgEl.textContent = pendingReply.snippet;
    }

    function buildForwardContactRows() {
        if (!forwardModalList) return;
        const q = (forwardModalSearch && forwardModalSearch.value.trim().toLowerCase()) || '';
        forwardModalList.innerHTML = '';
        const rows = Array.from(contactsList.querySelectorAll('.contact')).filter(el => {
            const id = el.dataset.id || '';
            if (!id || id === selectedUser) return false;
            const name = (el.querySelector('.contact-name') && el.querySelector('.contact-name').textContent) || '';
            return !q || name.toLowerCase().includes(q) || id.toLowerCase().includes(q);
        });
        rows.forEach(el => {
            const id = el.dataset.id || '';
            const name = (el.querySelector('.contact-name') && el.querySelector('.contact-name').textContent.trim()) || id;
            const img = el.querySelector('img');
            const pic = img ? img.src : defaultProfilePic;
            const row = document.createElement('label');
            row.className = 'forward-contact-row';
            const cb = document.createElement('input');
            cb.type = 'checkbox';
            cb.dataset.chatKey = id;
            cb.addEventListener('change', () => updateForwardSendButtonLabel());
            const avatar = document.createElement('img');
            avatar.src = pic;
            const nm = document.createElement('div');
            nm.className = 'forward-contact-name';
            nm.textContent = name;
            row.appendChild(cb);
            row.appendChild(avatar);
            row.appendChild(nm);
            forwardModalList.appendChild(row);
        });
    }

    function updateForwardSendButtonLabel() {
        if (!forwardModalSend || !forwardModalList) return;
        const boxes = forwardModalList.querySelectorAll('input[type=checkbox]:checked');
        const keys = Array.from(boxes).map(b => b.dataset.chatKey).filter(Boolean);
        const metas = keys.map(k => {
            const el = Array.from(contactsList.querySelectorAll('.contact')).find(c => String(c.dataset.id) === String(k));
            const name = el && el.querySelector('.contact-name') ? el.querySelector('.contact-name').textContent.trim() : k;
            return { key: k, name };
        });
        if (keys.length === 0) {
            forwardModalSend.textContent = 'Forward';
            forwardModalSend.disabled = true;
            return;
        }
        forwardModalSend.disabled = false;
        if (keys.length === 1) {
            forwardModalSend.textContent = `Forward to ${metas[0].name}`;
        } else if (keys.length === 2) {
            forwardModalSend.textContent = `Forward to ${metas[0].name} and ${metas[1].name}`;
        } else {
            forwardModalSend.textContent = `Forward to ${keys.length} users`;
        }
    }

    function openForwardModal() {
        if (!forwardModal || !forwardMessagePayload) return;
        buildForwardContactRows();
        if (forwardSelectAll) forwardSelectAll.checked = false;
        updateForwardSendButtonLabel();
        forwardModal.classList.add('open');
        forwardModal.setAttribute('aria-hidden', 'false');
    }

    function openInlineReactPicker(anchorBtn, messageId, options = {}) {
        removeInlineReactPicker();
        const wrap = document.createElement('div');
        wrap.className = 'reaction-picker-inline is-open';
        const normalizedMessageId = Number(messageId || 0);
        const normalizedChatKey = String(options.chatKey || selectedUser || '').trim();
        const isLocalOnlyMessage = !!options.localOnly || normalizedMessageId < 0;

        const updateBtnStates = async () => {
            if (isLocalOnlyMessage) {
                const selfReacted = new Set(buildLocalAiReactionRows(normalizedChatKey, normalizedMessageId).map(r => r.emoji));
                wrap.querySelectorAll('.rpi-emoji').forEach(b => {
                    b.classList.toggle('self-reacted', selfReacted.has(b.dataset.emoji));
                });
                return;
            }

            // Fetch current reactions to show which emojis are already reacted
            const mt = getCurrentChatMessageType();
            const res = await fetch(`get_reactions.php?token=${encodeURIComponent(token)}&message_type=${mt}&message_ids=${messageId}`).catch(() => null);
            if (!res || !res.ok) return;
            const grouped = await res.json().catch(() => ({}));
            const list = grouped[String(messageId)] || grouped[messageId] || [];
            const selfReacted = new Set(list.filter(r => Number(r.self_reacted)).map(r => r.emoji));
            wrap.querySelectorAll('.rpi-emoji').forEach(b => {
                b.classList.toggle('self-reacted', selfReacted.has(b.dataset.emoji));
            });
        };

        pickFiveReactionEmojis().forEach(em => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'rpi-emoji';
            b.dataset.emoji = em;
            b.textContent = em;
            b.addEventListener('click', async ev => {
                ev.stopPropagation();
                await toggleMessageReaction(normalizedMessageId, em, normalizedChatKey);
                // Update visual state without closing the picker
                updateBtnStates();
            });
            wrap.appendChild(b);
        });

        const more = document.createElement('button');
        more.type = 'button';
        more.className = 'rpi-more';
        more.textContent = '+';
        more.addEventListener('click', ev => {
            ev.stopPropagation();
            removeInlineReactPicker();
            if (!isLocalOnlyMessage) {
                openReactPickerModal(normalizedMessageId);
            }
        });
        wrap.appendChild(more);
        wrap.addEventListener('mousedown', ev => ev.stopPropagation());
        document.body.appendChild(wrap);
        inlineReactPickerEl = wrap;

        // Initial state
        updateBtnStates();

        const r = anchorBtn.getBoundingClientRect();
        wrap.style.position = 'fixed';
        wrap.style.left = '-9999px';
        wrap.style.top = '0';
        const rw = wrap.getBoundingClientRect();
        let left = r.right + 6;
        if (left + rw.width > window.innerWidth - 8) {
            left = r.left - rw.width - 6;
        }
        let top = r.top;
        if (top + rw.height > window.innerHeight - 8) top = window.innerHeight - rw.height - 8;
        wrap.style.left = `${Math.max(8, left)}px`;
        wrap.style.top = `${Math.max(8, top)}px`;
    }

    function closeReactPickerModal() {
        reactPickerMessageId = 0;
        reactPickerMessageIds = [];
        reactPickerSelectedEmojis = new Set();
        reactPickerActiveCategory = EMOJI_FAVORITES_CATEGORY.key;
        if (reactPickerGrid) {
            reactPickerGrid.innerHTML = '';
        }
        if (reactPickerCategoryTabs) {
            reactPickerCategoryTabs.innerHTML = '';
        }
        if (reactPickerSearchInput) {
            reactPickerSearchInput.value = '';
        }
        syncReactPickerApplyButton();
        if (reactPickerModal) {
            reactPickerModal.classList.remove('open');
            reactPickerModal.setAttribute('aria-hidden', 'true');
        }
    }

    function openReactPickerModal(messageId) {
        closeReactPickerModal();
        const normalizedMessageIds = (Array.isArray(messageId) ? messageId : [messageId])
            .map(value => Number(value))
            .filter(value => value > 0);
        reactPickerMessageIds = Array.from(new Set(normalizedMessageIds));
        reactPickerMessageId = reactPickerMessageIds[0] || 0;
        if (!reactPickerMessageIds.length) {
            return;
        }
        reactPickerActiveCategory = EMOJI_FAVORITES_CATEGORY.key;
        renderReactPickerTabs();
        renderReactPickerGrid(reactPickerActiveCategory);
        syncReactPickerApplyButton();
        reactPickerModal.classList.add('open');
        reactPickerModal.setAttribute('aria-hidden', 'false');
        if (reactPickerGrid) {
            reactPickerGrid.scrollTop = 0;
        }
        if (reactPickerSearchInput) {
            window.setTimeout(() => {
                if (reactPickerSearchInput && reactPickerModal && reactPickerModal.classList.contains('open')) {
                    reactPickerSearchInput.focus();
                }
            }, 30);
        }
    }

    function buildMessageInlineMetaRow({
        displayName = '',
        profilePic = '',
        isSelfMessage = false,
        senderId = '',
        chatContextKey = '',
        isLocalAiMessage = false
    } = {}) {
        const metaRow = document.createElement('div');
        metaRow.className = 'message-inline-meta';

        const avatarImg = document.createElement('img');
        avatarImg.className = 'message-inline-meta-avatar';
        avatarImg.src = normalizeProfilePic(String(profilePic || defaultProfilePic), 'direct');
        avatarImg.alt = String(displayName || 'User');

        const nameEl = document.createElement('div');
        nameEl.className = 'message-inline-meta-name';
        nameEl.textContent = String(displayName || 'User');

        metaRow.appendChild(avatarImg);
        metaRow.appendChild(nameEl);

        const normalizedSenderId = String(senderId || '').trim();
        if (!isSelfMessage && normalizedSenderId && /^\d+$/.test(normalizedSenderId) && !isLocalAiMessage) {
            metaRow.classList.add('is-clickable');
            metaRow.addEventListener('click', event => {
                event.stopPropagation();
                openUserInfoModal(normalizedSenderId, { chatContextKey });
            });
        }

        return metaRow;
    }

    function buildMessageElement(msg) {
        const d = document.createElement('div');
        const isLocalAiMessage = isLocalAiMessageRecord(msg);
        const isAiResponseMessage = !!(msg && (msg.is_ai_response === true || msg.is_ai_response === 1 || msg.is_ai_response === '1'));
        const localAiRole = isLocalAiMessage && msg._localAiRole === 'prompt' ? 'prompt' : 'assistant';
        const attachmentMessage = parseAttachmentMessage(msg.message);
        const callEvent = parseCallEventMessage(msg.message);
        const groupCallMsg = parseGroupCallMessage(msg.message);
        const groupNewsMsg = parseGroupNewsMessage(msg.message);
        const gameMessage = parseGameMessage(msg.message);
        const tableMessage = parseTableMessage(msg.message);
        const pollMessage = parsePollMessage(msg.message);
        const isGroupMessage = !!msg.group_id;
        const messageChatKey = getMessageChatKey(msg);
        const messageClientId = getMessageClientId(msg, messageChatKey);
        const messageId = getMessageServerId(msg);
        const isSelfMessage = isLocalAiMessage
            ? localAiRole === 'prompt'
            : callEvent
            ? isOutgoingCallEventForUser(callEvent, currentUserId)
            : (msg.self === true || msg.self === 1 || msg.self === '1' || String(msg.sender_id || '') === String(currentUserId));
        const messageAvatarUserId = isLocalAiMessage
            ? (isSelfMessage ? String(currentUserId) : LOCAL_AI_BOT_ID)
            : (callEvent || groupCallMsg)
            ? (isSelfMessage ? String(currentUserId) : getConversationOtherUserId(msg))
            : String(isSelfMessage ? currentUserId : (msg.sender_id || ''));
        const showExternalGroupSender = isGroupMessage && !isSelfMessage;
        const shouldHighlightMention = shouldHighlightMentionRow(msg, messageChatKey, {
            isSelfMessage,
            attachmentMessage,
            callEvent,
            groupCallMsg,
            pollMessage
        });

        d.className = 'message' + (isSelfMessage ? ' self' : '');
        if (shouldHighlightMention) {
            d.classList.add('mention-highlight');
        }
        if (isAiResponseMessage) {
            d.classList.add('ai-response');
        }
        if (isLocalAiMessage) {
            d.classList.add('local-ai-message');
            d.classList.add(localAiRole === 'prompt' ? 'local-ai-prompt' : 'local-ai-assistant');
            if (msg._localAiPrivate) {
                d.classList.add('local-ai-private');
            }
        }
        if (isGroupMessage) {
            d.classList.add('group-message');
        }
        if (pollMessage) {
            d.classList.add('poll-message');
        }
        if (gameMessage) {
            d.classList.add('game-message');
        }
        if (tableMessage) {
            d.classList.add('table-message');
        }
        
        // Ensure message ID is valid
        if (!isLocalAiMessage && (!messageId || messageId <= 0)) {
            console.error('[BUILD MESSAGE] Invalid message ID:', msg.id, 'Message:', msg);
        }
        
        d.dataset.id = messageClientId;
        d.dataset.messageId = String(messageId || '');
        d.dataset.timestamp = msg.created_at;
        d.dataset.senderId = messageAvatarUserId;
        const messageTranslationKey = getMessageTranslationKey(msg);
        if (messageTranslationKey) {
            d.dataset.translationKey = messageTranslationKey;
        }
        if (messageSelectMode && selectedMessageIds.has(String(messageId || '')) && isMessageSelectable(d)) {
            d.classList.add('is-selected');
        }
        d._qtMessageRecord = msg;

        if (groupNewsMsg) {
            d.className = 'message group-news-message';
            d.dataset.senderId = 'group-news';

            const bodyStack = document.createElement('div');
            bodyStack.className = 'message-body-stack';

            const bubbleRow = document.createElement('div');
            bubbleRow.className = 'message-bubble-row';
            bubbleRow.appendChild(buildGroupNewsNode(groupNewsMsg, msg.created_at));

            bodyStack.appendChild(bubbleRow);
            const readSlot = document.createElement('div');
            readSlot.className = 'message-read-receipts-slot read-receipts-row';
            bodyStack.appendChild(readSlot);
            d.appendChild(bodyStack);

            return {
                element: d,
                isSelfMessage: false,
                senderId: 'group-news'
            };
        }

        const displayName = isSelfMessage
            ? 'You'
            : isLocalAiMessage
                ? String(msg.sender_display_name || LOCAL_AI_BOT_NAME)
            : (msg.sender_display_name && isAiResponseMessage)
                ? msg.sender_display_name  // Use AI's display name for AI responses
            : (isAiResponseMessage && activeChatKey && activeChatKey.startsWith('ai:') && window.aiChatsMap && window.aiChatsMap[activeChatKey])
                ? window.aiChatsMap[activeChatKey].displayName  // Use AI chat display name
            : getDisplayNameForUser(String(messageAvatarUserId), {
                displayName: String(msg.sender_display_name || getUsernameById(messageAvatarUserId)),
                username: getUsernameById(messageAvatarUserId),
                isGroup: false
            }, messageChatKey);
        const presence = isLocalAiMessage && !isSelfMessage
            ? {
                profilePic: normalizeProfilePic(String(msg.sender_profile_pic || defaultProfilePic), 'direct'),
                isOnline: false
            }
            : getMessagePresenceData(d.dataset.senderId, isSelfMessage);

        const avatarWrapper = document.createElement('div');
        avatarWrapper.className = 'message-avatar-wrapper';
        
        // Make avatar clickable to open user info
        if (!isSelfMessage && /^\d+$/.test(String(messageAvatarUserId || '').trim()) && !isLocalAiMessage) {
            avatarWrapper.style.cursor = 'pointer';
            avatarWrapper.addEventListener('click', (e) => {
                e.stopPropagation();
                openUserInfoModal(messageAvatarUserId, { chatContextKey: messageChatKey });
            });
        }

        const avatarImg = document.createElement('img');
        avatarImg.className = 'message-avatar';
        avatarImg.src = presence.profilePic;
        avatarImg.alt = displayName;

        const presenceDot = document.createElement('span');
        presenceDot.className = 'message-presence-dot' + (presence.isOnline ? ' online' : '');
        ensurePresenceIndicatorChildren(presenceDot);

        avatarWrapper.appendChild(avatarImg);
        avatarWrapper.appendChild(presenceDot);

        const bubble = document.createElement('div');
        bubble.className = 'message-bubble';

        const replyId = normalizeReplyReferenceId(msg.reply_to_id);
        const replyRef = normalizeReplyReferenceId(msg.reply_to_ref_id);
        const replyName = msg.reply_to_display_name || '';
        const replyBody = msg.reply_to_message_body || '';
        const fwdUid = msg.forward_from_user_id ? Number(msg.forward_from_user_id) : 0;
        const fwdName = msg.forward_from_display_name || '';
        let aiImageImproviserShell = null;
        let aiImageImproviserInput = null;

        if (callEvent) {
            d.classList.add('call-event');
            if (callEvent.type === 'missed' && !isOutgoingCallEventForUser(callEvent, currentUserId)) {
                d.dataset.unreadCallEvent = '1';
            }
            bubble.appendChild(buildCallEventNode(callEvent, msg.created_at, msg));
        } else if (groupCallMsg) {
            d.classList.add('call-event');
            d.dataset.groupCallId = String(groupCallMsg.call_id || '');
            bubble.appendChild(buildGroupCallMessageNode(groupCallMsg, d));
        } else if (pollMessage) {
            // Poll message - will be rendered async
            if (!showExternalGroupSender) {
                const usernameEl = document.createElement('div');
                usernameEl.className = 'username';
                usernameEl.textContent = displayName;
                bubble.appendChild(usernameEl);
            }
            
            const loadingDiv = document.createElement('div');
            loadingDiv.className = 'poll-container';
            loadingDiv.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-secondary);"><i class="fas fa-spinner fa-spin"></i> Loading poll...</div>';
            bubble.appendChild(loadingDiv);
            
            // Load poll data async
            buildPollMessageElement(pollMessage, msg.id, msg.sender_id).then(pollEl => {
                if (pollEl) {
                    loadingDiv.replaceWith(pollEl);
                }
            }).catch(e => {
                console.error('Failed to build poll message:', e);
                loadingDiv.innerHTML = '<div style="padding:20px;text-align:center;color:#dc2626;">Failed to load poll</div>';
            });
        } else if (gameMessage) {
            if (!showExternalGroupSender) {
                const usernameEl = document.createElement('div');
                usernameEl.className = 'username';
                usernameEl.textContent = displayName;
                bubble.appendChild(usernameEl);
            }

            const loadingDiv = document.createElement('div');
            loadingDiv.className = 'game-invite-card';
            loadingDiv.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-secondary);"><i class="fas fa-spinner fa-spin"></i> Loading game...</div>';
            bubble.appendChild(loadingDiv);

            const gameStarterName = isSelfMessage
                ? String(currentUserDisplayName || displayName || 'You')
                : displayName;
            buildGameMessageElement(gameMessage, {
                senderDisplayName: gameStarterName,
                isSelfMessage,
                messageEl: d
            }).then(gameEl => {
                if (gameEl) {
                    loadingDiv.replaceWith(gameEl);
                }
            }).catch(error => {
                console.error('Failed to build game message:', error);
                loadingDiv.innerHTML = '<div style="padding:20px;text-align:center;color:#dc2626;">Failed to load game</div>';
            });
        } else if (tableMessage) {
            if (!showExternalGroupSender) {
                const usernameEl = document.createElement('div');
                usernameEl.className = 'username';
                usernameEl.textContent = displayName;
                bubble.appendChild(usernameEl);
            }

            bubble.appendChild(buildTableMessageNode(tableMessage, messageChatKey));
        } else {
            if (replyId !== 0) {
                const rq = document.createElement('div');
                rq.className = 'reply-quote';
                rq.dataset.replyToId = String(replyId);
                if (replyRef || replyName || replyBody) {
                    // Check if this is a call follow-up (replying to a call event)
                    const isCallFollowup = replyBody && (
                        replyBody.includes('__CALL_EVENT__') ||
                        replyBody.includes('__GROUP_CALL__')
                    );
                    
                    const labelText = isCallFollowup ? 'Call follow-up' : 'Replied to ' + qtEscapeHtml(replyName);
                    rq.innerHTML = '<div class="reply-quote-name">' + labelText + '</div>'
                        + '<div class="reply-quote-text">' + qtEscapeHtml(getMessageSnippetForReply(replyBody)) + '</div>';
                    rq.addEventListener('click', () => scrollChatToMessageId(replyId));
                } else {
                    rq.innerHTML = '<div class="reply-quote-text">Original message unavailable</div>';
                }
                bubble.appendChild(rq);
            }
            if (fwdUid > 0 && fwdName) {
                const fl = document.createElement('div');
                fl.className = 'forwarded-label';
                fl.innerHTML = '<i class="fa-solid fa-share"></i> Forwarded from ' + qtEscapeHtml(String(fwdName));
                bubble.appendChild(fl);
            }
            if (attachmentMessage) {
                d.classList.add('attachment-message');
                if (attachmentMessage.aiGenerated) {
                    d.classList.add('ai-generated-image');
                }
                if (attachmentMessage.kind === 'audio') {
                    d.classList.add('voice-message');
                }
                if ((attachmentMessage.kind === 'image' || attachmentMessage.kind === 'video') && !attachmentMessage.caption) {
                    d.classList.add('media-only-message');
                }
                if (!showExternalGroupSender) {
                    const usernameEl = document.createElement('div');
                    usernameEl.className = 'username';
                    usernameEl.textContent = displayName;
                    bubble.appendChild(usernameEl);
                }
                // Use local blob URL for immediate playback if available (voice messages just sent)
                const attachmentRenderMessageId = messageId || msg.id;
                const attachmentToRender = (msg._localBlobUrl && attachmentMessage.kind === 'audio')
                    ? Object.assign({}, attachmentMessage, { url: msg._localBlobUrl, messageId: attachmentRenderMessageId })
                    : Object.assign({}, attachmentMessage, { messageId: attachmentRenderMessageId });
                const attachmentNode = buildAttachmentNode(attachmentToRender);
                
                // Remove unheard class from self voice messages
                if (isSelfMessage && attachmentMessage.kind === 'audio') {
                    const voicePlayer = attachmentNode.querySelector('.voice-message-player');
                    if (voicePlayer) {
                        voicePlayer.classList.remove('unheard');
                    }
                }
                
                bubble.appendChild(attachmentNode);

                if (
                    attachmentMessage.aiGenerated
                    && attachmentMessage.kind === 'image'
                    && !attachmentMessage.pending
                    && (messageId > 0 || (isLocalAiMessage && !!msg._localAiPrivate))
                ) {
                    aiImageImproviserShell = document.createElement('div');
                    aiImageImproviserShell.className = 'message-ai-improvise-shell';
                    aiImageImproviserShell.dataset.messageId = String(messageId);
                    aiImageImproviserShell.addEventListener('mousedown', ev => ev.stopPropagation());
                    aiImageImproviserShell.addEventListener('pointerdown', stopEventPropagation);
                    aiImageImproviserShell.addEventListener('pointerup', stopEventPropagation);
                    aiImageImproviserShell.addEventListener('touchstart', stopEventPropagation, { passive: true });

                    const aiImageImproviserForm = document.createElement('div');
                    aiImageImproviserForm.className = 'message-ai-improvise-form';

                    aiImageImproviserInput = document.createElement('input');
                    aiImageImproviserInput.type = 'text';
                    aiImageImproviserInput.className = 'message-ai-improvise-input';
                    aiImageImproviserInput.placeholder = 'Improvise';
                    aiImageImproviserInput.setAttribute('aria-label', 'Improvise this AI image');

                    const aiImageImproviserSend = document.createElement('button');
                    aiImageImproviserSend.type = 'button';
                    aiImageImproviserSend.className = 'message-actions-btn message-ai-improvise-send';
                    aiImageImproviserSend.innerHTML = '<i class="fa-solid fa-paper-plane"></i>';
                    aiImageImproviserSend.setAttribute('aria-label', 'Send improvise request');

                    const setImproviserBusyState = busy => {
                        aiImageImproviserInput.disabled = !!busy;
                        aiImageImproviserSend.disabled = !!busy;
                    };

                    const submitImprovisation = async event => {
                        if (event) {
                            event.preventDefault();
                            event.stopPropagation();
                        }

                        const nextInstructions = String(aiImageImproviserInput.value || '').trim();
                        if (!nextInstructions) {
                            aiImageImproviserInput.focus();
                            return;
                        }

                        setImproviserBusyState(true);
                        try {
                            await requestAiImageImprovisation(d, nextInstructions);
                        } catch (error) {
                            alert(error && error.message ? error.message : 'Unable to improvise that AI image right now.');
                            setImproviserBusyState(false);
                        }
                    };

                    aiImageImproviserInput.addEventListener('keydown', event => {
                        if (event.key === 'Enter') {
                            submitImprovisation(event);
                        }
                    });
                    addTapAndClickListener(aiImageImproviserSend, submitImprovisation);

                    aiImageImproviserForm.appendChild(aiImageImproviserInput);
                    aiImageImproviserForm.appendChild(aiImageImproviserSend);
                    aiImageImproviserShell.appendChild(aiImageImproviserForm);
                    bubble.appendChild(aiImageImproviserShell);
                }
            } else {
                const textEl = document.createElement('div');
                textEl.className = 'text message-text-content';
                const rawHtml = msg.message;
                let isEmojiOnlyMessage = false;
                try {
                    isEmojiOnlyMessage = renderMessageTextContent(textEl, rawHtml, messageChatKey, {
                        translationKey: messageTranslationKey,
                        isLocalAiMessage,
                        localAiRole,
                        displayName,
                        replyId,
                        forwardFromUserId: fwdUid,
                        forwardFromDisplayName: fwdName
                    });
                } catch (messageRenderError) {
                    console.error('Inline message render failed, falling back to plain text content.', messageRenderError, msg);
                    textEl.textContent = String(rawHtml || '');
                }
                
                if (!showExternalGroupSender) {
                    const usernameEl = document.createElement('div');
                    usernameEl.className = 'username';
                    usernameEl.textContent = displayName;
                    bubble.appendChild(usernameEl);
                }
                if (isEmojiOnlyMessage) {
                    d.classList.add('emoji-only-message');
                }
                bubble.appendChild(textEl);
                const translationToggle = buildMessageTranslationToggle(messageTranslationKey);
                if (translationToggle) {
                    bubble.appendChild(translationToggle);
                }
                d._qtMessageRenderContext = {
                    rawHtml,
                    messageChatKey,
                    translationKey: messageTranslationKey,
                    isLocalAiMessage,
                    localAiRole,
                    displayName,
                    replyId,
                    forwardFromUserId: fwdUid,
                    forwardFromDisplayName: fwdName
                };
            }
        }

        const bodyStack = document.createElement('div');
        bodyStack.className = 'message-body-stack';
        bodyStack.appendChild(buildMessageInlineMetaRow({
            displayName,
            profilePic: presence.profilePic,
            isSelfMessage,
            senderId: String(messageAvatarUserId || ''),
            chatContextKey: messageChatKey,
            isLocalAiMessage
        }));

        if (showExternalGroupSender) {
            const senderLabel = document.createElement('div');
            senderLabel.className = 'group-message-sender';
            senderLabel.textContent = displayName;
            bodyStack.appendChild(senderLabel);
        }

        const bubbleRow = document.createElement('div');
        bubbleRow.className = 'message-bubble-row';
        bubbleRow.appendChild(bubble);

        if (!callEvent && !groupCallMsg) {
            const supportsLocalOnlyActions = supportsLocalAiLocalOnlyActions(msg) || isAiGeneratedImage(msg);
            const canUseServerMessageActions = !isLocalAiMessage;
            if (supportsLocalOnlyActions) {
                attachPrivateLocalAiMessageActions({
                    messageEl: d,
                    bubbleEl: bubble,
                    bubbleRowEl: bubbleRow,
                    messageRecord: msg,
                    displayName,
                    messageChatKey,
                    messageTranslationKey,
                    attachmentMessage,
                    isSelfMessage
                });
            } else if (!canUseServerMessageActions) {
                // Keep non-private local AI messages lightweight and local-only.
            } else {
            const actionsWrap = document.createElement('div');
            actionsWrap.className = 'message-actions-wrap message-quick-actions';
            const menuBtn = document.createElement('button');
            menuBtn.type = 'button';
            menuBtn.className = 'message-actions-btn';
            menuBtn.innerHTML = '<i class="fa-solid fa-ellipsis-vertical"></i>';
            menuBtn.setAttribute('aria-label', 'Message actions');
            const showReactReplyButtons = (canUseServerMessageActions && messageId > 0) || supportsLocalOnlyActions;
            const reactBtn = showReactReplyButtons ? document.createElement('button') : null;
            if (reactBtn) {
                reactBtn.type = 'button';
                reactBtn.className = 'message-actions-btn';
                reactBtn.innerHTML = '<i class="fa-regular fa-face-smile"></i>';
                reactBtn.setAttribute('aria-label', 'React to message');
            }
            const replyBtn = showReactReplyButtons ? document.createElement('button') : null;
            if (replyBtn) {
                replyBtn.type = 'button';
                replyBtn.className = 'message-actions-btn';
                replyBtn.innerHTML = '<i class="fa-solid fa-reply"></i>';
                replyBtn.setAttribute('aria-label', 'Reply to message');
            }
            const improviseBtn = aiImageImproviserShell ? document.createElement('button') : null;
            if (improviseBtn) {
                improviseBtn.type = 'button';
                improviseBtn.className = 'message-actions-btn';
                improviseBtn.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i>';
                improviseBtn.setAttribute('aria-label', 'Improvise AI image');
                improviseBtn.title = 'Improvise AI image';
            }
            const menu = document.createElement('div');
            menu.className = 'message-actions-menu';
            const openReactionMenu = (anchorEl = reactBtn) => {
                if (!supportsLocalOnlyActions && messageId <= 0) {
                    console.error('[REACT MESSAGE] Invalid message ID:', messageId, 'msg.id:', msg.id);
                    alert('Error: Invalid message ID. Cannot react to message.');
                    return;
                }

                closeOpenMessageActionsMenu();
                removeInlineReactPicker();
                openInlineReactPicker(anchorEl, messageId, {
                    localOnly: supportsLocalOnlyActions,
                    chatKey: messageChatKey
                });
            };

            const queueReplyAction = () => {
                // Allow replying to AI generated images (local AI messages) even if messageId <= 0
                if (!supportsLocalOnlyActions && messageId <= 0) {
                    console.error('[REPLY MESSAGE] Invalid message ID:', messageId, 'msg.id:', msg.id);
                    alert('Error: Invalid message ID. Cannot reply to message.');
                    return;
                }

                beginReplyToMessage(messageId, displayName, msg.message, {
                    isAi: isQuillTalkAiMessageRecord(msg)
                });
            };

            const toggleAiImageImproviserShell = () => {
                if (!aiImageImproviserShell) {
                    return;
                }

                const nextIsOpen = !aiImageImproviserShell.classList.contains('is-open');
                closeOpenAiImageImproviser(nextIsOpen ? messageId : 0);
                aiImageImproviserShell.classList.toggle('is-open', nextIsOpen);
                if (nextIsOpen && aiImageImproviserInput) {
                    window.setTimeout(() => {
                        try {
                            aiImageImproviserInput.focus();
                            aiImageImproviserInput.select();
                        } catch (error) {}
                    }, 0);
                }
            };

            // Build the menu and include mobile-only reply/react entries plus overflow actions.
            const isPinnedMessage = messageId !== 0 && isPinnedMessageForChat(messageChatKey, messageId);
            let menuHtml = '';
            if (showReactReplyButtons) {
                menuHtml += ''
                    + '<button type="button" class="message-actions-item mobile-only-message-action" data-act="react"><i class="fa-regular fa-face-smile"></i> React</button>'
                    + '<button type="button" class="message-actions-item mobile-only-message-action" data-act="reply"><i class="fa-solid fa-reply"></i> Reply</button>';
            }
            if (canUseServerMessageActions || supportsLocalOnlyActions) {
                menuHtml += '<button type="button" class="message-actions-item" data-act="forward"><i class="fa-solid fa-share"></i> Forward</button>';
            }
            if (aiImageImproviserShell) {
                menuHtml += '<button type="button" class="message-actions-item" data-act="improvise"><i class="fa-solid fa-wand-magic-sparkles"></i> Improvise</button>';
            }
            if ((canUseServerMessageActions && messageId > 0) || supportsLocalOnlyActions) {
                menuHtml += `<button type="button" class="message-actions-item" data-act="${isPinnedMessage ? 'unpin-message' : 'pin-message'}"><i class="fa-solid fa-thumbtack"></i> ${isPinnedMessage ? 'Unpin message' : 'Pin message'}</button>`;
            }
            if (canUseServerMessageActions && isMessageSelectable(d)) {
                menuHtml += '<button type="button" class="message-actions-item" data-act="select"><i class="fa-solid fa-check-double"></i> Select</button>';
            }
            const translatableMessageText = getTranslatableMessageText(msg.message);
            if (translatableMessageText) {
                menuHtml += '<button type="button" class="message-actions-item" data-act="translate"><i class="fa-solid fa-language"></i> Translate</button>';
            }
            
            // Add transcribe option for voice messages
            if (canUseServerMessageActions && attachmentMessage && attachmentMessage.kind === 'audio') {
                menuHtml += '<button type="button" class="message-actions-item" data-act="transcribe"><i class="fa-solid fa-t"></i> Transcribe</button>';
            }
            
            // Check if user can delete this message
            const selectedChatIsGroup = isGroupChatKey(String(selectedUser || ''));
            let canModerateGroup = false;
            if (selectedChatIsGroup) {
                const groupMeta = getContactMeta(selectedUser);
                canModerateGroup = groupMeta && (groupMeta.canManageGroup || isGroupOwnerMeta(groupMeta));
            }
            
            // Check if this is a scheduled message
            const isScheduledMessage = d.classList.contains('scheduled');
            
            if (supportsLocalOnlyActions) {
                menuHtml += '<button type="button" class="message-actions-item" data-act="delete-local-ai"><i class="fa-solid fa-trash"></i> Delete</button>';
            } else if (isSelfMessage && !pollMessage && !tableMessage && (!attachmentMessage || (attachmentMessage && attachmentMessage.kind === 'audio'))) {
                if (attachmentMessage && attachmentMessage.kind === 'audio') {
                    // Voice messages can be edited (re-recorded) and deleted
                    menuHtml += ''
                        + '<button type="button" class="message-actions-item" data-act="edit"><i class="fa-solid fa-microphone"></i> Re-record</button>'
                        + '<button type="button" class="message-actions-item" data-act="delete"><i class="fa-solid fa-trash"></i> Delete</button>';
                } else {
                    // Text messages can be edited and deleted
                    menuHtml += ''
                        + '<button type="button" class="message-actions-item" data-act="edit"><i class="fa-solid fa-pen-to-square"></i> Edit</button>'
                        + '<button type="button" class="message-actions-item" data-act="delete"><i class="fa-solid fa-trash"></i> Delete</button>';
                }
                
                // Add "Send now" option for scheduled messages
                if (isScheduledMessage) {
                    menuHtml += '<button type="button" class="message-actions-item" data-act="send-now"><i class="fa-solid fa-paper-plane"></i> Send now</button>';
                }
            } else if (isSelfMessage && (pollMessage || tableMessage)) {
                // Poll and table messages can only be deleted, not edited
                menuHtml += '<button type="button" class="message-actions-item" data-act="delete"><i class="fa-solid fa-trash"></i> Delete</button>';
            } else if (canModerateGroup) {
                // Group admins/owners can delete any message
                menuHtml += '<button type="button" class="message-actions-item" data-act="delete"><i class="fa-solid fa-trash"></i> Delete</button>';
            } else if (!isSelfMessage) {
                // Anyone can delete other people's messages for themselves only
                menuHtml += '<button type="button" class="message-actions-item" data-act="delete-for-me"><i class="fa-solid fa-trash"></i> Delete for me</button>';
            }
            menu.innerHTML = menuHtml;
            menuBtn.addEventListener('mousedown', ev => ev.stopPropagation());
            menuBtn.addEventListener('pointerdown', stopEventPropagation);
            menuBtn.addEventListener('pointerup', stopEventPropagation);
            menuBtn.addEventListener('touchstart', stopEventPropagation, { passive: true });
            if (reactBtn) {
                reactBtn.addEventListener('mousedown', ev => ev.stopPropagation());
                reactBtn.addEventListener('pointerdown', stopEventPropagation);
                reactBtn.addEventListener('pointerup', stopEventPropagation);
                reactBtn.addEventListener('touchstart', stopEventPropagation, { passive: true });
            }
            if (replyBtn) {
                replyBtn.addEventListener('mousedown', ev => ev.stopPropagation());
                replyBtn.addEventListener('pointerdown', stopEventPropagation);
                replyBtn.addEventListener('pointerup', stopEventPropagation);
                replyBtn.addEventListener('touchstart', stopEventPropagation, { passive: true });
            }
            if (improviseBtn) {
                improviseBtn.addEventListener('mousedown', ev => ev.stopPropagation());
                improviseBtn.addEventListener('pointerdown', stopEventPropagation);
                improviseBtn.addEventListener('pointerup', stopEventPropagation);
                improviseBtn.addEventListener('touchstart', stopEventPropagation, { passive: true });
            }
            menu.addEventListener('mousedown', ev => ev.stopPropagation());
            menu.addEventListener('pointerdown', stopEventPropagation);
            menu.addEventListener('pointerup', stopEventPropagation);
            menu.addEventListener('touchstart', stopEventPropagation, { passive: true });
            addTapAndClickListener(menuBtn, ev => {
                ev.stopPropagation();
                toggleMessageActionsMenu(menu, actionsWrap, menuBtn);
            });
            if (reactBtn) {
                addTapAndClickListener(reactBtn, ev => {
                    ev.stopPropagation();
                    openReactionMenu(reactBtn);
                });
            }
            if (replyBtn) {
                addTapAndClickListener(replyBtn, ev => {
                    ev.stopPropagation();
                    closeOpenMessageActionsMenu();
                    removeInlineReactPicker();
                    queueReplyAction();
                });
            }
            if (improviseBtn) {
                addTapAndClickListener(improviseBtn, ev => {
                    ev.stopPropagation();
                    closeOpenMessageActionsMenu();
                    removeInlineReactPicker();
                    toggleAiImageImproviserShell();
                });
            }
            Array.from(menu.querySelectorAll('.message-actions-item')).forEach(item => {
                item.addEventListener('pointerdown', stopEventPropagation);
                item.addEventListener('touchstart', stopEventPropagation, { passive: true });
                addTapAndClickListener(item, async ev => {
                    ev.stopPropagation();
                    const act = item.dataset.act;
                    menu.classList.remove('is-open');
                    actionsWrap.classList.remove('is-open');
                    if (openMessageActionsMenuEl === menu) {
                        openMessageActionsMenuEl = null;
                    }
                    
                    // Debug: Log message ID extraction
                    console.log('[DEBUG] Message ID extraction:', {
                        'msg.id': msg.id,
                        'messageId': messageId,
                        'msg': msg
                    });

                    const actionsRequiringServerId = new Set([
                        'edit',
                        'delete',
                        'delete-for-me',
                        'transcribe',
                        'send-now'
                    ]);
                    if (!supportsLocalOnlyActions) {
                        actionsRequiringServerId.add('react');
                        actionsRequiringServerId.add('reply');
                        actionsRequiringServerId.add('forward');
                        actionsRequiringServerId.add('pin-message');
                        actionsRequiringServerId.add('unpin-message');
                    }
                    if (actionsRequiringServerId.has(String(act || '')) && messageId <= 0) {
                        console.error('[MESSAGE ACTION] Invalid message ID:', messageId, 'action:', act, 'msg.id:', msg.id);
                        alert('Error: Invalid message ID. Cannot use that action right now.');
                        return;
                    }
                    if (act === 'react') {
                        openReactionMenu(bubble);
                    } else if (act === 'reply') {
                        queueReplyAction();
                    } else if (act === 'improvise') {
                        toggleAiImageImproviserShell();
                    } else if (act === 'forward') {
                        forwardMessagePayload = {
                            messageBody: msg.message,
                            forwardFromUserId: Number(msg.sender_id || 0),
                            forwardFromDisplayName: isSelfMessage ? 'You' : displayName
                        };
                        openForwardModal();
                    } else if (act === 'pin-message') {
                        const pinnedRecord = buildPinnedMessageRecord(msg, displayName);
                        if (pinnedRecord) {
                            setPinnedMessageForChat(messageChatKey, pinnedRecord);
                        }
                    } else if (act === 'unpin-message') {
                        clearPinnedMessageForChat(messageChatKey);
                    } else if (act === 'select') {
                        enterMessageSelectionMode(d);
                    } else if (act === 'translate') {
                        openTranslateModal({
                            messageTranslationKey,
                            messageId,
                            chatKey: messageChatKey,
                            rawMessage: msg.message
                        });
                    } else if (act === 'delete-local-ai') {
                        if (!confirm('Delete this private AI message on this device only?')) {
                            return;
                        }
                        if (!removeStoredLocalAiMessage(messageChatKey, messageId)) {
                            alert('Could not delete that private AI message.');
                            return;
                        }
                        removeStoredLocalAiReactions(messageChatKey, messageId);
                        if (pendingReply && String(pendingReply.id || '') === String(messageId)) {
                            pendingReply = null;
                            updateReplyBar();
                        }
                        clearPinnedMessageIfMatches(messageChatKey, messageId);
                        closeOpenAiImageImproviser();
                        removeMessageElementWithTimestampCleanup(d);
                        invalidateSidebarHistoryCache({ reloadIfVisible: true });
                        loadContactPreviews().catch(() => {});
                        sortContactsList();
                    } else if (act === 'edit') {
                        // For voice messages, start re-recording
                        if (attachmentMessage && attachmentMessage.kind === 'audio') {
                            // Store the message ID for replacement
                            window._editingVoiceMessageId = messageId;
                            window._editingVoiceMessageElement = d;
                            
                            // Start voice recording
                            const voiceBtn = document.getElementById('voiceRecordBtn');
                            if (voiceBtn) {
                                closeVoiceActionMenu();
                                startVoiceRecording().catch(error => {
                                    console.error('Unable to start voice re-recording.', error);
                                });
                            }
                            
                            menu.classList.remove('is-open');
                            actionsWrap.classList.remove('is-open');
                            return;
                        }
                        
                        // Turn the message bubble text into an editable textarea (only for own text messages)
                        if (attachmentMessage || tableMessage) { alert('This message cannot be edited'); return; }
                        const textEl = bubble.querySelector('.text');
                        if (!textEl) { alert('This message cannot be edited'); return; }
                        const originalHTML = textEl.innerHTML;
                        const originalRaw = msg.message || '';
                        const editInput = document.createElement('textarea');
                        editInput.className = 'message-edit-input';
                        editInput.value = originalRaw;
                        editInput.rows = 1;
                        
                        // Auto-resize textarea
                        const autoResize = () => {
                            editInput.style.height = 'auto';
                            editInput.style.height = Math.min(editInput.scrollHeight, 120) + 'px';
                        };
                        editInput.addEventListener('input', autoResize);
                        
                        // Handle Shift+Enter for new line, Enter to save
                        editInput.addEventListener('keydown', (e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                doneBtn.click();
                            }
                        });
                        // Replace the text element with the input
                        textEl.parentNode.replaceChild(editInput, textEl);

                        // Hide the actions while editing and show a small toolbar
                        actionsWrap.style.display = 'none';
                        const editToolbar = document.createElement('div');
                        editToolbar.className = 'message-edit-toolbar';
                        const doneBtn = document.createElement('button');
                        doneBtn.type = 'button';
                        doneBtn.className = 'message-actions-btn';
                        doneBtn.title = 'Done';
                        doneBtn.innerHTML = '<i class="fa-solid fa-check"></i>';
                        const cancelBtn = document.createElement('button');
                        cancelBtn.type = 'button';
                        cancelBtn.className = 'message-actions-btn';
                        cancelBtn.title = 'Cancel';
                        cancelBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
                        editToolbar.appendChild(doneBtn);
                        editToolbar.appendChild(cancelBtn);
                        bubbleRow.appendChild(editToolbar);

                        cancelBtn.addEventListener('click', () => {
                            const restored = document.createElement('div');
                            restored.className = 'text message-text-content';
                            restored.innerHTML = originalHTML;
                            editInput.parentNode.replaceChild(restored, editInput);
                            editToolbar.remove();
                            actionsWrap.style.display = '';
                        });

                        doneBtn.addEventListener('click', async () => {
                            const newText = String(editInput.value || '').trim();
                            if (newText === '') { alert('Message cannot be empty'); return; }
                            let data2 = null;
                            try {
                                const body = new URLSearchParams();
                                body.append('token', token);
                                body.append('message_id', String(messageId));
                                body.append('message', newText);
                                const res = await fetch('update_message.php', { method: 'POST', body });
                                if (!res.ok) {
                                    console.error('[edit message] HTTP error:', res.status, res.statusText);
                                    alert('Server error: ' + res.status);
                                    return;
                                }
                                data2 = await res.json();
                            } catch (err) {
                                console.error('[edit message] error:', err);
                                alert('Network error while editing message');
                                return;
                        }
                        
                        if (data2 && data2.success) {
                            if (messageTranslationKey) {
                                messageTranslationStates.delete(messageTranslationKey);
                            }
                            const newTextEl = document.createElement('div');
                            newTextEl.className = 'text message-text-content';
                            renderMessageTextContent(newTextEl, newText, getMessageChatKey(msg), {
                                translationKey: messageTranslationKey,
                                isLocalAiMessage,
                                localAiRole,
                                displayName,
                                replyId,
                                forwardFromUserId: fwdUid,
                                forwardFromDisplayName: fwdName
                            });
                            editInput.parentNode.replaceChild(newTextEl, editInput);
                            const existingTranslationToggle = bubble.querySelector('.message-translation-toggle');
                            if (existingTranslationToggle) {
                                existingTranslationToggle.remove();
                            }
                            d.classList.toggle('emoji-only-message', !replyId && !(fwdUid > 0 && fwdName) && isEmojiOnlyMessageText(newText));
                            editToolbar.remove();
                            actionsWrap.style.display = '';
                            // Update local message model for later interactions
                            msg.message = newText;
                            if (d._qtMessageRecord) {
                                d._qtMessageRecord.message = newText;
                            }
                            d._qtMessageRenderContext = {
                                rawHtml: newText,
                                messageChatKey: getMessageChatKey(msg),
                                translationKey: messageTranslationKey,
                                isLocalAiMessage,
                                localAiRole,
                                displayName,
                                replyId,
                                forwardFromUserId: fwdUid,
                                forwardFromDisplayName: fwdName
                            };
                            invalidateSidebarHistoryCache({ reloadIfVisible: true });
                            // Refresh preview text without changing recency ordering for an old message edit
                            try { updateContactPreview(selectedUser, { message: newText, sender_id: currentUserId, created_at: msg.created_at, self: true }, false); } catch (e) {}
                            syncPinnedMessageRecordForMessage(messageChatKey, msg, displayName);
                        } else {
                            alert((data2 && data2.error) ? data2.error : 'Failed to edit message');
                        }
                    });

                    // Focus input, select text, and trigger auto-resize
                    setTimeout(() => { 
                        try { 
                            editInput.focus(); 
                            editInput.setSelectionRange(0, editInput.value.length);
                            if (editInput.tagName === 'TEXTAREA') {
                                editInput.style.height = 'auto';
                                editInput.style.height = Math.min(editInput.scrollHeight, 120) + 'px';
                            }
                        } catch (e) {} 
                    }, 20);

                    } else if (act === 'transcribe') {
                        // Open transcribe modal
                        openTranscribeModal(messageId, attachmentMessage);
                    } else if (act === 'delete-for-me') {
                        // Delete for me immediately without modal
                        if (confirm('Delete this message for yourself only?')) {
                            // Validate message ID
                            if (messageId <= 0) {
                                console.error('[DELETE FOR ME] Invalid message ID:', messageId);
                                alert('Error: Invalid message ID. Cannot delete message.');
                                return;
                            }
                            
                            const fd = new FormData();
                            fd.append('token', token);
                            fd.append('message_id', String(messageId));
                            fd.append('scope', 'me');
                            
                            console.log('[DELETE FOR ME] Sending request:', {
                                token: token ? 'present' : 'missing',
                                message_id: messageId,
                                scope: 'me'
                            });
                            
                            try {
                                const res = await fetch('delete_message.php', { method: 'POST', body: fd });
                                const { data, rawText } = await readJsonResponseSafely(res);
                                
                                if (res.ok && data && data.success) {
                                    clearPinnedMessageIfMatches(messageChatKey, messageId);
                                    removeMessageElementWithTimestampCleanup(d);
                                    invalidateSidebarHistoryCache({ reloadIfVisible: true });
                                    loadContactPreviews().catch(() => {});
                                    sortContactsList();
                                } else {
                                    const fallbackMessage = rawText
                                        ? rawText.trim().replace(/\s+/g, ' ').slice(0, 220)
                                        : '';
                                    alert((data && data.error) || fallbackMessage || 'Failed to delete message');
                                }
                            } catch (err) {
                                console.error('[delete for me] error:', err);
                                alert('Network error while deleting message');
                            }
                        }
                    } else if (act === 'delete') {
                        // Open delete modal with options
                        const deleteMessageId = messageId;
                        
                        // Debug: Log message ID extraction for delete modal
                        console.log('[DEBUG] Delete modal message ID:', {
                            'msg.id': msg.id,
                            'deleteMessageId': deleteMessageId,
                            'msg': msg
                        });
                        
                        // Validate message ID before opening modal
                        if (deleteMessageId <= 0) {
                            console.error('[DELETE MODAL] Invalid message ID:', deleteMessageId, 'msg.id:', msg.id);
                            alert('Error: Invalid message ID. Cannot delete message.');
                            return;
                        }
                        
                        openDeleteMessageModal(deleteMessageId, d, false);
                    }
                });
            });
            d.addEventListener('click', event => {
                if (!isMessageSelectable(d)) {
                    return;
                }
                if (event.target && typeof event.target.closest === 'function' && event.target.closest('.message-actions-wrap, .message-actions-menu, .message-ai-improvise-shell, .reaction-picker-inline')) {
                    return;
                }
                if (
                    !isMobileViewport()
                    && event.shiftKey
                    && !event.metaKey
                    && !event.ctrlKey
                    && !event.altKey
                    && !messageSelectMode
                    && !shouldIgnoreMessageLongPressTarget(event.target)
                ) {
                    event.preventDefault();
                    event.stopPropagation();
                    enterMessageSelectionMode(d);
                    return;
                }
                if (!messageSelectMode) {
                    return;
                }
                event.preventDefault();
                event.stopPropagation();
                toggleMessageSelected(d);
            });
            if (reactBtn) {
                actionsWrap.appendChild(reactBtn);
            }
            if (replyBtn) {
                actionsWrap.appendChild(replyBtn);
            }
            if (improviseBtn) {
                actionsWrap.appendChild(improviseBtn);
            }
            actionsWrap.appendChild(menuBtn);
            actionsWrap.appendChild(menu);
            bubbleRow.appendChild(actionsWrap);
            bindMobileMessageGestures(d, bubble, {
                onLongPress: () => {
                    if (!menu.classList.contains('is-open')) {
                        openMessageActionsMenu(menu, actionsWrap, bubble);
                    }
                },
                onDoubleTap: () => {
                    if ((canUseServerMessageActions && messageId > 0) || supportsLocalOnlyActions) {
                        openReactionMenu(bubble);
                    }
                }
            });
            }
        } else {
            // Call events and group call messages: react-only button (no reply/forward)
            const actionsWrap = document.createElement('div');
            actionsWrap.className = 'message-actions-wrap';
            const reactBtn = document.createElement('button');
            reactBtn.type = 'button';
            reactBtn.className = 'message-actions-btn';
            reactBtn.innerHTML = '<i class="fa-regular fa-face-smile"></i>';
            reactBtn.setAttribute('aria-label', 'React');
            reactBtn.addEventListener('mousedown', ev => ev.stopPropagation());
            reactBtn.addEventListener('touchstart', stopEventPropagation, { passive: true });
            addTapAndClickListener(reactBtn, ev => {
                ev.stopPropagation();
                openInlineReactPicker(reactBtn, messageId);
            });
            actionsWrap.appendChild(reactBtn);
            bubbleRow.appendChild(actionsWrap);
            bindMobileMessageGestures(d, bubble, {
                onLongPress: () => {},
                onDoubleTap: () => {
                    const reactionMessageId = messageId;
                    if (reactionMessageId > 0) {
                        closeOpenMessageActionsMenu();
                        openInlineReactPicker(bubble, reactionMessageId);
                    }
                }
            });
        }

        bodyStack.appendChild(bubbleRow);

        const reactionsSlot = document.createElement('div');
        reactionsSlot.className = 'message-reactions';
        bodyStack.appendChild(reactionsSlot);

        const readSlot = document.createElement('div');
        readSlot.className = 'message-read-receipts-slot read-receipts-row';
        bodyStack.appendChild(readSlot);

        d.appendChild(avatarWrapper);
        d.appendChild(bodyStack);
        applyMessageLayoutClasses(d, isSelfMessage);
        if (supportsLocalAiLocalOnlyActions(msg) || isAiGeneratedImage(msg)) {
            renderMessageReactions(d, buildLocalAiReactionRows(messageChatKey, messageId), messageId);
        }

        return {
            element: d,
            isSelfMessage,
            senderId: String(messageAvatarUserId || '')
        };
    }

    function buildMessageElementFallback(msg, error = null) {
        if (error) {
            console.error('Falling back to stable message renderer.', error, msg);
        }

        const isLocalAiMessage = isLocalAiMessageRecord(msg);
        const isAiResponseMessage = !!(msg && (msg.is_ai_response === true || msg.is_ai_response === 1 || msg.is_ai_response === '1'));
        const localAiRole = isLocalAiMessage && msg._localAiRole === 'prompt' ? 'prompt' : 'assistant';
        const isGroupMessage = !!(msg && msg.group_id);
        const attachmentMessage = parseAttachmentMessage(msg && msg.message);
        const callEvent = parseCallEventMessage(msg && msg.message);
        const groupCallMsg = parseGroupCallMessage(msg && msg.message);
        const groupNewsMsg = parseGroupNewsMessage(msg && msg.message);
        const gameMessage = parseGameMessage(msg && msg.message);
        const tableMessage = parseTableMessage(msg && msg.message);
        const pollMessage = parsePollMessage(msg && msg.message);
        const chatKey = getMessageChatKey(msg);
        const rawMessageId = getMessageServerId(msg);
        const messageClientId = getMessageClientId(msg, chatKey);
        const isSelfMessage = isLocalAiMessage
            ? localAiRole === 'prompt'
            : !!(
                msg
                && (msg.self === true || msg.self === 1 || msg.self === '1' || String(msg.sender_id || '') === String(currentUserId))
            );
        const senderId = isLocalAiMessage
            ? (isSelfMessage ? String(currentUserId) : LOCAL_AI_BOT_ID)
            : String(isSelfMessage ? currentUserId : (msg && msg.sender_id ? msg.sender_id : ''));
        const shouldHighlightMention = shouldHighlightMentionRow(msg, chatKey, {
            isSelfMessage,
            attachmentMessage,
            callEvent,
            groupCallMsg,
            gameMessage,
            pollMessage
        });
        const isEmojiOnlyMessage = !attachmentMessage
            && !gameMessage
            && !tableMessage
            && !callEvent
            && !groupCallMsg
            && !pollMessage
            && isEmojiOnlyMessageText(String((msg && msg.message) || ''));
        const messageTranslationKey = getMessageTranslationKey(msg);
        const fallbackName = isSelfMessage
            ? 'You'
            : isLocalAiMessage
                ? String((msg && msg.sender_display_name) || LOCAL_AI_BOT_NAME)
            : (() => {
                const nickname = getChatNicknameForUser(chatKey, senderId);
                if (nickname) return nickname;
                // Check if this is an AI response and use the AI display name
                if (msg && msg.is_ai_response && msg.sender_display_name) {
                    return msg.sender_display_name;
                }
                // For AI chats, use the AI chat display name
                if (msg && msg.is_ai_response && chatKey && chatKey.startsWith('ai:') && window.aiChatsMap && window.aiChatsMap[chatKey]) {
                    return window.aiChatsMap[chatKey].displayName;
                }
                return String(msg && (msg.sender_display_name || getUsernameById(senderId) || `User ${senderId}`) || 'User');
            })();

        const root = document.createElement('div');
        root.className = 'message' + (isSelfMessage ? ' self' : '');
        if (shouldHighlightMention) {
            root.classList.add('mention-highlight');
        }
        if (isAiResponseMessage) {
            root.classList.add('ai-response');
        }
        if (isLocalAiMessage) {
            root.classList.add('local-ai-message');
            root.classList.add(localAiRole === 'prompt' ? 'local-ai-prompt' : 'local-ai-assistant');
            if (msg._localAiPrivate) {
                root.classList.add('local-ai-private');
            }
        }
        if (isGroupMessage) {
            root.classList.add('group-message');
        }
        if (gameMessage) {
            root.classList.add('game-message');
        }
        if (isEmojiOnlyMessage && !(messageTranslationKey && messageTranslationStates.get(messageTranslationKey)?.showTranslated)) {
            root.classList.add('emoji-only-message');
        }
        root.dataset.id = messageClientId;
        root.dataset.messageId = String(rawMessageId || '');
        root.dataset.timestamp = String((msg && msg.created_at) || '');
        root.dataset.senderId = senderId;
        if (messageTranslationKey) {
            root.dataset.translationKey = messageTranslationKey;
        }
        root._qtMessageRecord = msg;

        if (groupNewsMsg) {
            root.className = 'message group-news-message';
            root.dataset.senderId = 'group-news';

            const bodyStack = document.createElement('div');
            bodyStack.className = 'message-body-stack';

            const bubbleRow = document.createElement('div');
            bubbleRow.className = 'message-bubble-row';
            bubbleRow.appendChild(buildGroupNewsNode(groupNewsMsg, msg && msg.created_at ? msg.created_at : ''));

            bodyStack.appendChild(bubbleRow);
            const readSlot = document.createElement('div');
            readSlot.className = 'message-read-receipts-slot read-receipts-row';
            bodyStack.appendChild(readSlot);
            root.appendChild(bodyStack);

            return {
                element: root,
                isSelfMessage: false,
                senderId: 'group-news'
            };
        }

        const avatarWrapper = document.createElement('div');
        avatarWrapper.className = 'message-avatar-wrapper';
        if (!isSelfMessage) {
            const avatarImg = document.createElement('img');
            avatarImg.className = 'message-avatar';
            avatarImg.src = normalizeProfilePic(
                String((msg && msg.sender_profile_pic) || userProfilePics[senderId] || defaultProfilePic),
                'direct'
            );
            avatarImg.alt = fallbackName;
            avatarWrapper.appendChild(avatarImg);
        }

        const bodyStack = document.createElement('div');
        bodyStack.className = 'message-body-stack';
        bodyStack.appendChild(buildMessageInlineMetaRow({
            displayName: fallbackName,
            profilePic: normalizeProfilePic(
                String((msg && msg.sender_profile_pic) || userProfilePics[senderId] || defaultProfilePic),
                'direct'
            ),
            isSelfMessage,
            senderId,
            chatContextKey: chatKey,
            isLocalAiMessage
        }));

        if (isGroupMessage && !isSelfMessage) {
            const senderLabel = document.createElement('div');
            senderLabel.className = 'group-message-sender';
            senderLabel.textContent = fallbackName;
            bodyStack.appendChild(senderLabel);
        }

        const bubbleRow = document.createElement('div');
        bubbleRow.className = 'message-bubble-row';

        const bubble = document.createElement('div');
        bubble.className = 'message-bubble';

        if (!isGroupMessage || isSelfMessage) {
            const usernameEl = document.createElement('div');
            usernameEl.className = 'username';
            // For AI responses, use the AI display name
            if (msg && msg.is_ai_response && msg.sender_display_name) {
                usernameEl.textContent = msg.sender_display_name;
            } else if (msg && msg.is_ai_response && chatKey && chatKey.startsWith('ai:') && window.aiChatsMap && window.aiChatsMap[chatKey]) {
                usernameEl.textContent = window.aiChatsMap[chatKey].displayName;
            } else {
                usernameEl.textContent = fallbackName;
            }
            bubble.appendChild(usernameEl);
        }

        if (attachmentMessage) {
            try {
                const attachmentNode = buildAttachmentNode(Object.assign({}, attachmentMessage, { messageId: msg && msg.id ? msg.id : null }));
                bubble.appendChild(attachmentNode);
            } catch (attachmentError) {
                console.error('Fallback attachment render failed.', attachmentError, msg);
                const textEl = document.createElement('div');
                textEl.className = 'text';
                textEl.textContent = '[Attachment]';
                bubble.appendChild(textEl);
            }
        } else if (gameMessage) {
            const loadingDiv = document.createElement('div');
            loadingDiv.className = 'game-invite-card';
            loadingDiv.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-secondary);"><i class="fas fa-spinner fa-spin"></i> Loading game...</div>';
            bubble.appendChild(loadingDiv);
            const gameStarterName = isSelfMessage
                ? String(currentUserDisplayName || fallbackName || 'You')
                : fallbackName;
            buildGameMessageElement(gameMessage, {
                senderDisplayName: gameStarterName,
                isSelfMessage,
                messageEl: root
            }).then(gameEl => {
                if (gameEl) {
                    loadingDiv.replaceWith(gameEl);
                }
            }).catch(gameError => {
                console.error('Fallback game render failed.', gameError, msg);
                loadingDiv.innerHTML = '<div style="padding:20px;text-align:center;color:#dc2626;">Failed to load game</div>';
            });
        } else if (tableMessage) {
            bubble.appendChild(buildTableMessageNode(tableMessage, chatKey));
        } else {
            const textEl = document.createElement('div');
            textEl.className = 'text message-text-content';
            try {
                renderMessageTextContent(textEl, String((msg && msg.message) || ''), chatKey, {
                    translationKey: messageTranslationKey,
                    isLocalAiMessage,
                    localAiRole,
                    displayName: fallbackName,
                    replyId: msg && msg.reply_to_id ? Number(msg.reply_to_id) : 0,
                    forwardFromUserId: msg && msg.forward_from_user_id ? Number(msg.forward_from_user_id) : 0,
                    forwardFromDisplayName: String((msg && msg.forward_from_display_name) || '')
                });
            } catch (mentionError) {
                console.error('Fallback mention render failed.', mentionError, msg);
                textEl.textContent = String((msg && msg.message) || '');
            }
            bubble.appendChild(textEl);
            const translationToggle = buildMessageTranslationToggle(messageTranslationKey);
            if (translationToggle) {
                bubble.appendChild(translationToggle);
            }
            root._qtMessageRenderContext = {
                rawHtml: String((msg && msg.message) || ''),
                messageChatKey: chatKey,
                translationKey: messageTranslationKey,
                isLocalAiMessage,
                localAiRole,
                displayName: fallbackName,
                replyId: msg && msg.reply_to_id ? Number(msg.reply_to_id) : 0,
                forwardFromUserId: msg && msg.forward_from_user_id ? Number(msg.forward_from_user_id) : 0,
                forwardFromDisplayName: String((msg && msg.forward_from_display_name) || '')
            };
        }

        bubbleRow.appendChild(bubble);
        if ((supportsLocalAiLocalOnlyActions(msg) || isAiGeneratedImage(msg)) && !callEvent && !groupCallMsg) {
            attachPrivateLocalAiMessageActions({
                messageEl: root,
                bubbleEl: bubble,
                bubbleRowEl: bubbleRow,
                messageRecord: msg,
                displayName: fallbackName,
                messageChatKey: chatKey,
                messageTranslationKey,
                attachmentMessage,
                isSelfMessage
            });
        }
        bodyStack.appendChild(bubbleRow);
        root.appendChild(avatarWrapper);
        root.appendChild(bodyStack);
        applyMessageLayoutClasses(root, isSelfMessage);

        return {
            element: root,
            isSelfMessage,
            senderId
        };
    }

    function buildMessageElementSafe(msg) {
        try {
            return buildMessageElement(msg);
        } catch (error) {
            return buildMessageElementFallback(msg, error);
        }
    }

    // Apply consecutive class to all messages in the chat
    function applyConsecutiveClassToAllMessages() {
        if (!chatBox) return;
        
        const allMessages = chatBox.querySelectorAll('.message');
        let previousMessage = null;
        
        allMessages.forEach((message) => {
            message.classList.remove('consecutive');

            // Skip call events and timestamps
            if (message.classList.contains('call-event')) {
                previousMessage = null;
                return;
            }
            
            // Check if there's a timestamp between this and previous message
            if (previousMessage) {
                let hasTimestampBetween = false;
                let sibling = previousMessage.nextElementSibling;
                while (sibling && sibling !== message) {
                    if (sibling.classList.contains('timestamp')) {
                        hasTimestampBetween = true;
                        break;
                    }
                    sibling = sibling.nextElementSibling;
                }
                
                if (canRenderMessageConsecutively(previousMessage, message, hasTimestampBetween)) {
                    message.classList.add('consecutive');
                    console.log('Applied consecutive class to message:', message.dataset.id, 'sender:', message.dataset.senderId);
                }
            }
            
            previousMessage = message;
        });
    }

    // FIX: Added 'isInitialLoad = false' inside the parentheses
    function appendMessage(msg, isInitialLoad = false) {
        const messageClientId = getMessageClientId(msg, getMessageChatKey(msg));
        if (messageClientId && chatBox.querySelector(`[data-id="${messageClientId}"]`)) return;
        const isLocalAiMessage = isLocalAiMessageRecord(msg);

        // Clear loading indicator on first message append during initial load
        let clearedLoadingIndicator = false;
        if (isInitialLoad) {
            const loadingIndicator = chatBox.querySelector('.chat-loading-indicator, .conversation-loading-state');
            if (loadingIndicator) {
                chatBox.innerHTML = '';
                clearedLoadingIndicator = true;
            }
        }

        const lastMsg = clearedLoadingIndicator ? null : chatBox.lastElementChild;
        let showTimestamp = false;

        if (!lastMsg || lastMsg.classList.contains('timestamp')) showTimestamp = true;
        else {
            const lastTs = lastMsg.dataset.timestamp;
            if (!lastTs) showTimestamp = true;
            else {
                const diffMs = parseServerDateTimeMs(msg.created_at) - parseServerDateTimeMs(lastTs);
                if (diffMs >= MESSAGE_GROUP_WINDOW_MS) showTimestamp = true;
            }
        }

        if (showTimestamp) {
            const tsEl = document.createElement('div');
            tsEl.className = 'timestamp';
            tsEl.textContent = formatTimestamp(msg.created_at);
            chatBox.appendChild(tsEl);
        }

        const messageData = buildMessageElementSafe(msg);
        const shouldCollapseBlockedMessage = !messageData.isSelfMessage
            && !msg.group_id
            && isBlockedUser(messageData.senderId)
            && String(selectedUser || '') === String(messageData.senderId || '');

        // Check if this message is consecutive (same sender as previous message)
        const previousMessage = chatBox.lastElementChild;
        if (canRenderMessageConsecutively(previousMessage, messageData.element, showTimestamp)) {
            messageData.element.classList.add('consecutive');
            console.log('Added consecutive class to message', msg.id, 'sender:', messageData.element.dataset.senderId);
        }

        if (shouldCollapseBlockedMessage) {
            appendBlockedMessageElement(messageData.element, messageData.senderId, msg.created_at);
        } else {
            chatBox.appendChild(messageData.element);
        }

        if (!isLocalAiMessage) {
            lastId = Math.max(Number(lastId || 0), Number(msg.id || 0));
        }

        const isPassiveSystemMessage = !!parseCallEventMessage(msg.message) || !!parseGroupNewsMessage(msg.message);

        if (!isInitialLoad && !isLocalAiMessage && !messageData.isSelfMessage && !shouldCollapseBlockedMessage && !isPassiveSystemMessage) {
            // Check mention-only preference before playing ding
            const _chatKey = String(getMessageChatKey(msg) || selectedUser || '');
            const _notifPref = getChatNotificationPref(_chatKey);
            const _mentioned = messageMentionsCurrentUser(msg.message, _chatKey);
            const _shouldDing = _notifPref === 'all' || _mentioned;

            if (_shouldDing) {
                ding.pause();
                ding.currentTime = 0;
                if (getAppSetting('messageSounds')) {
                    ding.play().catch(() => {});
                }
            }
            chatBox.scrollTop = chatBox.scrollHeight;
        }
    }

    async function pollMessages(isInitialLoad = false, chatKeyOverride = null) {
        const activeChatKey = String(chatKeyOverride || selectedUser || '').trim();
        if (!activeChatKey) return;

        try {
            // Check if this is an AI chat
            const isAiChat = activeChatKey.startsWith('ai:');
            const endpoint = isAiChat 
                ? `fetch_ai_messages.php?token=${encodeURIComponent(token)}&ai_chat_key=${encodeURIComponent(activeChatKey)}&last_id=${encodeURIComponent(lastId)}&t=${Date.now()}`
                : `fetch_messages.php?token=${encodeURIComponent(token)}&with=${encodeURIComponent(activeChatKey)}&last_id=${encodeURIComponent(lastId)}&t=${Date.now()}`;
                
            const res = await fetch(endpoint);
            if (!res.ok) return;
            const messages = await res.json();
            const renderableMessages = isAiChat ? messages : getRenderableMessagesForChat(messages, activeChatKey, isInitialLoad);
            
            let newestIncomingMessageId = 0;
            const idsForReactions = [];

            const notifPref = getChatNotificationPref(activeChatKey);

            renderableMessages.forEach(msg => {
                hydrateMessageSenderData(msg);
                const isLocalAiMessage = isLocalAiMessageRecord(msg);
                const chatKey = getMessageChatKey(msg) || activeChatKey; // Use activeChatKey for AI chats
                const isFreshActivity = !isInitialLoad && !isLocalAiMessage && Number(msg.id) > Number(lastId || 0);
                const isTargetConversationSelected = String(selectedUser || '') === activeChatKey;

                // Update lastId to track the highest message ID
                if (msg.id && Number(msg.id) > Number(lastId || 0)) {
                    lastId = Number(msg.id);
                }

                // Check if this is a received public AI command that needs a response.
                const receivedAiCommand = isFreshActivity && !msg.self
                    ? parseStoredAiCommandMessage(msg.message)
                    : null;
                if (receivedAiCommand && !receivedAiCommand.isPrivate && receivedAiCommand.prompt) {
                    if (receivedAiCommand.mode === 'image') {
                        requestAiGeneratedImage(activeChatKey, receivedAiCommand.prompt, {
                            mode: 'public',
                            originMessageId: Number(msg.id || 0)
                        }).catch(error => {
                            console.error('Failed to generate AI image for received command:', error);
                        });
                        return;
                    }

                    queueLocalAiReply(activeChatKey, receivedAiCommand.prompt, {
                        isPublicCommand: true,
                        reactionTargetMessageId: Number(msg.id || 0),
                        originMessageId: Number(msg.id || 0),
                        originUserId: Number(msg.sender_id || 0),
                        originDisplayName: msg.sender_display_name || '',
                        originMessageBody: msg.message || ''
                    }).catch(error => {
                        console.error('Failed to generate AI reply for received command:', error);
                    });
                }

                if (
                    isFreshActivity
                    && !isAiChat
                    && !msg.self
                    && !receivedAiCommand
                    && !isQuillTalkAiMessageRecord(msg)
                    && shouldTriggerQuillTalkAiResponse(msg.message, msg)
                ) {
                    triggerQuillTalkAiResponseForMessage(
                        activeChatKey,
                        msg.message,
                        Number(msg.id || 0),
                        Number(msg.sender_id || 0),
                        msg.sender_display_name || '',
                        msg.message || ''
                    ).catch(error => {
                        console.error('Failed to trigger QuillTalk AI from incoming message:', error);
                    });
                }

                if (!isLocalAiMessage && !isAiChat) {
                    // For mention-only chats, only promote contact preview if mentioned
                    const isMentioned = messageMentionsCurrentUser(msg.message, chatKey);
                    const shouldPromote = isFreshActivity && (notifPref === 'all' || isMentioned || !!msg.self);
                    updateContactPreview(chatKey, msg, shouldPromote);
                } else if (isAiChat && !isLocalAiMessage) {
                    // For AI chats, always update preview with latest message
                    updateContactPreview(chatKey, msg, isFreshActivity);
                }

                if (isTargetConversationSelected && String(chatKey || '') === activeChatKey) {
                    appendMessage(msg, isInitialLoad);
                    if (!isLocalAiMessage && msg.id && !parseCallEventMessage(msg.message) && !parseGroupNewsMessage(msg.message)) {
                        idsForReactions.push(Number(msg.id));
                    }
                    if (!isLocalAiMessage && !msg.self && !parseCallEventMessage(msg.message) && !parseGroupNewsMessage(msg.message) && !isAiChat) {
                        newestIncomingMessageId = Math.max(newestIncomingMessageId, Number(msg.id || 0));
                    }
                }
            });

            // Remove loading indicator if no messages were appended (empty chat)
            if (isInitialLoad && chatBox) {
                const loadingIndicator = chatBox.querySelector('.chat-loading-indicator, .conversation-loading-state');
                if (loadingIndicator) {
                    // For AI chats and docked sidequest chats, keep loading until we snap to the live bottom.
                    if ((isAiChat || isChessConversationDockMounted()) && renderableMessages.length > 0) {
                        // Keep loading indicator, will be removed after scroll
                    } else {
                        loadingIndicator.remove();
                    }
                }
                
                // Apply consecutive class to all messages after initial load
                applyConsecutiveClassToAllMessages();
                
                // Simple animation system - scroll to bottom then animate
                if (chatBox) {
                    // Force scroll to bottom immediately and maintain it
                    const forceScrollToBottom = () => {
                        chatBox.scrollTop = chatBox.scrollHeight;
                    };
                    
                    forceScrollToBottom();
                    chatBox.style.removeProperty('--disable-message-animations');
                    
                    // Ensure we stay at bottom with multiple attempts
                    requestAnimationFrame(forceScrollToBottom);
                    setTimeout(forceScrollToBottom, 10);
                    setTimeout(forceScrollToBottom, 50);
                    
                    // Simple animation trigger after ensuring we're at bottom
                    setTimeout(() => {
                        // Final scroll before animation
                        forceScrollToBottom();
                        
                        const messages = chatBox.querySelectorAll('.message');
                        messages.forEach((message, index) => {
                            message.style.animationDelay = `${index * 0.05}s`;
                            
                            // Clean up
                            setTimeout(() => {
                                if (message.parentNode) {
                                    message.classList.remove('initial-load');
                                    message.style.animationDelay = '';
                                }
                            }, (index * 0.05 + 0.5) * 1000);
                        });
                    }, 100);
                }
            }

            // SPEED FIX: Scroll to bottom ONCE here, instead of 50 times inside the loop
            // But skip this during initial load since we handle scrolling above
            if(renderableMessages.length > 0 && !isInitialLoad){
                chatBox.scrollTop = chatBox.scrollHeight;
            }
            
            // For AI chats and docked sidequest chats, scroll to the live bottom on initial load.
            // Skip this if we already handled scrolling in our main animation system above
            if(renderableMessages.length > 0 && isInitialLoad && (isAiChat || isChessConversationDockMounted())){
                // Only do this scroll if our main animation system didn't run (chatBox was null above)
                // The main animation system handles both regular and AI chats when chatBox exists
                console.log('AI chat scroll - skipped because main animation system handled it');
                // Remove loading indicator that might still be there
                setTimeout(() => {
                    if (chatBox) {
                        const loadingIndicator = chatBox.querySelector('.chat-loading-indicator, .conversation-loading-state');
                        if (loadingIndicator) {
                            loadingIndicator.remove();
                        }
                    }
                }, 150);
            }

            if (!isInitialLoad && newestIncomingMessageId > 0 && String(selectedUser || '') === activeChatKey) {
                scheduleSelectedChatReadSync(activeChatKey, newestIncomingMessageId);
            }

            if (idsForReactions.length) {
                fetchReactionsForMessageIds(idsForReactions).catch(() => {});
            }
            refreshReadReceipts();
            
            // Dispatch event for scheduled messages to reload
            window.dispatchEvent(new Event('messagesLoaded'));

        } catch (e) {
            console.error("Poll Error:", e);
        }
        refreshUnreadBadges();
    }

    setInterval(pollMessages, 3000);
    setInterval(pollTypingState, TYPING_POLL_MS);

    if (chatBox) {
        bindChatBackgroundSelectionGestures(chatBox);
        chatBox.addEventListener('click', async event => {
