    }
    if (messageInput) {
        messageInput.addEventListener('keydown', (event) => {
            if (handleCommandKeydown(event)) return; // command picker consumed the key
            if (handleMentionKeydown(event)) return; // mention picker consumed the key
            if (handleEmojiKeydown(event)) return; // emoji picker consumed the key
            
            // Handle Shift+Enter for new line
            if (event.key === 'Enter' && event.shiftKey) {
                // Allow default behavior (new line)
                return;
            }
            
            // Handle Enter to send
            if (event.key === 'Enter' && !event.shiftKey) {
