                    }
                }
            }
        });
    }
    if (messageInput) {
        messageInput.addEventListener('blur', () => {
            clearLocalTyping(true);
            closeCommandPicker();
            // Restore original draft preview when input loses focus (unless it was just sent)
            try {
                if (messageInput && messageInput.value.trim() === '') {
                    const chatKey = String(selectedUser || '');
                    clearDraftPreview(chatKey, true);
                }
            } catch (e) {
                console.error('[blur] draft cleanup error:', e);
            }
        });
    }
    ['click', 'keyup', 'select', 'focus'].forEach((eventName) => {
        messageInput.addEventListener(eventName, rememberMessageSelection);
    });
    if (messageInput) {
        messageInput.addEventListener('scroll', syncComposerHighlightOverlayScroll);
    }

    if (emojiBtn) {
        emojiBtn.addEventListener('mousedown', (event) => {
            event.preventDefault();
            event.stopPropagation();
            rememberMessageSelection();
        });
        addTapAndClickListener(emojiBtn, (event) => {
            event.preventDefault();
            event.stopPropagation();
            if (!selectedUser) {
                alert('Select a contact or accept a friend request first.');
                return;
            }
            toggleEmojiPicker();
        });
    }

    if (emojiPickerGrid) {
        emojiPickerGrid.addEventListener('mousedown', (event) => {
