        }
    });

    function getVoiceRecordingMimeType() {
        if (typeof MediaRecorder === 'undefined') {
            return '';
        }

        const candidates = [
            'audio/webm;codecs=opus',
            'audio/ogg;codecs=opus',
            'audio/webm',
            'audio/ogg'
        ];

        for (const candidate of candidates) {
            if (MediaRecorder.isTypeSupported(candidate)) {
                return candidate;
            }
        }

        return '';
    }

    function getVoiceRecordingExtension(mimeType) {
        if (mimeType.includes('ogg')) return 'ogg';
        if (mimeType.includes('mp4')) return 'm4a';
        if (mimeType.includes('wav')) return 'wav';
        return 'webm';
    }

    function stopVoiceRecordingAnalysis() {
        if (voiceRecordingFrameId) {
            cancelAnimationFrame(voiceRecordingFrameId);
            voiceRecordingFrameId = 0;
        }

        if (voiceRecordingSourceNode) {
            try {
                voiceRecordingSourceNode.disconnect();
            } catch (e) {
                console.warn('Unable to disconnect recording source.', e);
            }
            voiceRecordingSourceNode = null;
        }

        if (voiceRecordingAnalyser) {
            try {
                voiceRecordingAnalyser.disconnect();
            } catch (e) {
                console.warn('Unable to disconnect recording analyser.', e);
            }
            voiceRecordingAnalyser = null;
        }

        if (voiceRecordingAudioContext) {
            try {
                voiceRecordingAudioContext.close();
            } catch (e) {
                console.warn('Unable to close recording audio context.', e);
            }
            voiceRecordingAudioContext = null;
        }
    }

    function startVoiceRecordingAnalysis(stream) {
        stopVoiceRecordingAnalysis();
        voiceRecordingSampleLevels = [];
        voiceRecordingStartedAt = Date.now();

        const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextCtor || !stream) {
            return;
        }

        try {
            voiceRecordingAudioContext = new AudioContextCtor();
            voiceRecordingAnalyser = voiceRecordingAudioContext.createAnalyser();
            voiceRecordingAnalyser.fftSize = 2048;
            voiceRecordingAnalyser.smoothingTimeConstant = 0.78;
            voiceRecordingSourceNode = voiceRecordingAudioContext.createMediaStreamSource(stream);
            voiceRecordingSourceNode.connect(voiceRecordingAnalyser);

            const buffer = new Uint8Array(voiceRecordingAnalyser.fftSize);
            const sample = () => {
                if (!voiceRecordingAnalyser) {
                    return;
                }

                voiceRecordingAnalyser.getByteTimeDomainData(buffer);
                let sum = 0;
                for (let index = 0; index < buffer.length; index += 1) {
                    const normalized = (buffer[index] - 128) / 128;
                    sum += normalized * normalized;
                }

                voiceRecordingSampleLevels.push(Math.sqrt(sum / buffer.length));
                voiceRecordingFrameId = requestAnimationFrame(sample);
            };

            sample();
        } catch (e) {
            console.warn('Voice waveform analysis could not start.', e);
            stopVoiceRecordingAnalysis();
        }
    }

    function buildVoiceRecordingMeta(rawDuration = 0, rawWaveform = []) {
        const safeDuration = Number(rawDuration || 0) > 0
            ? Number(rawDuration)
            : (voiceRecordingStartedAt ? (Date.now() - voiceRecordingStartedAt) / 1000 : 0);

        return createVoiceAttachmentMeta({
            duration: safeDuration,
            waveform: rawWaveform
        });
    }

    async function analyzeAudioFile(file) {
        const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
        if (!file || !AudioContextCtor) {
            return createVoiceAttachmentMeta();
        }

        const audioContext = new AudioContextCtor();
        try {
            const arrayBuffer = await file.arrayBuffer();
            const decodedBuffer = await audioContext.decodeAudioData(arrayBuffer.slice(0));
            const channelData = decodedBuffer.getChannelData(0);
            const step = Math.max(1, Math.floor(channelData.length / (VOICE_WAVEFORM_BAR_COUNT * 18)));
            const rawSamples = [];

            for (let start = 0; start < channelData.length; start += step) {
                const end = Math.min(channelData.length, start + step);
                let sum = 0;
                for (let index = start; index < end; index += 1) {
                    sum += Math.abs(channelData[index]);
                }
                rawSamples.push(sum / Math.max(1, end - start));
            }

            return createVoiceAttachmentMeta({
                duration: decodedBuffer.duration,
                waveform: rawSamples
            });
        } catch (e) {
            console.warn('Unable to analyze selected audio file.', e);
            return createVoiceAttachmentMeta();
        } finally {
            try {
                await audioContext.close();
            } catch (e) {
                console.warn('Unable to close audio file context.', e);
            }
        }
    }

    function stopVoiceRecordingStream() {
        stopVoiceRecordingAnalysis();
        if (voiceRecordingStream) {
            voiceRecordingStream.getTracks().forEach(track => track.stop());
            voiceRecordingStream = null;
        }
    }

    function isVoiceRecordingActive() {
        return !!(voiceMediaRecorder && voiceMediaRecorder.state !== 'inactive');
    }

    function updateVoiceRecordButton() {
        if (!voiceRecordBtn) {
            return;
        }

        if (isVoiceRecordingActive() || isLiveVoiceTranscriptionActive()) {
            voiceRecordBtn.classList.add('recording');
            voiceRecordBtn.setAttribute('aria-pressed', 'true');
        } else {
            voiceRecordBtn.classList.remove('recording');
            voiceRecordBtn.setAttribute('aria-pressed', 'false');
        }
    }

    function isLiveVoiceTranscriptionActive() {
        return !!(liveVoiceTranscriptionSession && liveVoiceTranscriptionSession.active);
    }

    function closeVoiceActionMenu() {
        if (!voiceActionMenu) {
            return;
        }

        voiceActionMenu.classList.remove('is-open');
        voiceActionMenu.setAttribute('aria-hidden', 'true');
        if (voiceRecordBtn) {
            voiceRecordBtn.setAttribute('aria-expanded', 'false');
        }
    }

    function openVoiceActionMenu() {
        if (!voiceActionMenu) {
            return;
        }

        voiceActionMenu.classList.add('is-open');
        voiceActionMenu.setAttribute('aria-hidden', 'false');
        if (voiceRecordBtn) {
            voiceRecordBtn.setAttribute('aria-expanded', 'true');
        }
    }

    function toggleVoiceActionMenu() {
        if (!voiceActionMenu) {
            return;
        }

        if (voiceActionMenu.classList.contains('is-open')) {
            closeVoiceActionMenu();
            return;
        }

        openVoiceActionMenu();
    }

    function getLiveVoiceTranscriptionText(session) {
        if (!session) {
            return '';
        }

        const finalizedTurns = Array.from(session.turns.entries())
            .sort((left, right) => left[0] - right[0])
            .map(([, transcript]) => String(transcript || '').trim())
            .filter(Boolean);
        const interimTranscript = String(session.interimTranscript || '').trim();
        if (interimTranscript) {
            finalizedTurns.push(interimTranscript);
        }

        return finalizedTurns.join(' ').trim();
    }

    function buildComposerValueWithTranscript(snapshot, transcript) {
        const originalValue = snapshot ? String(snapshot.value || '') : '';
        if (!transcript) {
            return originalValue;
        }

        const start = snapshot && Number.isFinite(Number(snapshot.start))
            ? Math.max(0, Number(snapshot.start))
            : originalValue.length;
        const end = snapshot && Number.isFinite(Number(snapshot.end))
            ? Math.max(start, Number(snapshot.end))
            : start;
        const before = originalValue.slice(0, start);
        const after = originalValue.slice(end);
        const needsSpaceBefore = before && !/\s$/.test(before) && !/^[,.;!?)/\]}]/.test(transcript);
        const needsSpaceAfter = after && !/^\s/.test(after) && !/^[,.;!?)/\]}]/.test(after);

        return `${before}${needsSpaceBefore ? ' ' : ''}${transcript}${needsSpaceAfter ? ' ' : ''}${after}`;
    }

    function applyLiveVoiceTranscriptToComposer(session) {
        if (!session || !messageInput) {
            return;
        }

        const transcript = getLiveVoiceTranscriptionText(session);
        const nextValue = buildComposerValueWithTranscript(session.composerSnapshot, transcript);
        if (messageInput.value !== nextValue) {
            messageInput.value = nextValue;
        }
        const cursor = session.composerSnapshot
            ? Math.min(nextValue.length, Math.max(0, Number(session.composerSnapshot.start || 0) + nextValue.length - String(session.composerSnapshot.value || '').length))
            : nextValue.length;
        try {
            messageInput.setSelectionRange(cursor, cursor);
        } catch (error) {}
        updateComposerHighlightOverlay();
        messageInput.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function restoreAttachmentPreviewAfterTransientState() {
        if (pendingGifAttachments.length) {
            renderPendingGifAttachmentPreview();
            return;
        }

        if (pendingAttachmentFile) {
            renderPendingAttachmentPreview(pendingAttachmentFile);
            return;
        }

        if (attachmentPreviewCard) {
            attachmentPreviewCard.innerHTML = '';
        }
        if (attachmentPreviewRow) {
            attachmentPreviewRow.classList.remove('active');
        }
    }

    function renderLiveVoiceTranscriptionPreview(session) {
        if (!session || !attachmentPreviewCard || !attachmentPreviewRow) {
            return;
        }

        const transcript = getLiveVoiceTranscriptionText(session);
        const card = document.createElement('div');
        card.className = 'attachment-preview-card transcription-preview';

        const icon = document.createElement('div');
        icon.className = 'attachment-preview-file-icon';
        icon.innerHTML = '<i class="fa-solid fa-wave-square"></i>';
        card.appendChild(icon);

        const meta = document.createElement('div');
        meta.className = 'attachment-preview-meta';

        const title = document.createElement('div');
        title.className = 'attachment-preview-title';
        title.textContent = 'Transcribing your voice';

        const subtitle = document.createElement('div');
        subtitle.className = 'attachment-preview-subtitle';
        subtitle.textContent = session.wsReady
            ? 'Tap the microphone again to stop'
            : 'Connecting to live transcription...';

        const liveBadge = document.createElement('div');
        liveBadge.className = 'attachment-preview-live-badge';
        liveBadge.textContent = session.wsReady ? 'Listening live' : 'Starting';

        const transcriptEl = document.createElement('div');
        transcriptEl.className = 'attachment-preview-transcript' + (transcript ? '' : ' is-placeholder');
        transcriptEl.textContent = transcript || 'Start speaking and your words will appear here.';

        meta.appendChild(title);
        meta.appendChild(subtitle);
        meta.appendChild(liveBadge);
        meta.appendChild(transcriptEl);
        card.appendChild(meta);

        const clearBtn = document.createElement('button');
        clearBtn.type = 'button';
        clearBtn.className = 'attachment-preview-clear';
        clearBtn.setAttribute('aria-label', 'Cancel voice transcription');
        clearBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
        clearBtn.addEventListener('click', () => {
            stopLiveVoiceTranscription({ discardTranscript: true });
        });
        card.appendChild(clearBtn);

        attachmentPreviewCard.innerHTML = '';
        attachmentPreviewCard.appendChild(card);
        attachmentPreviewRow.classList.add('active');
    }

    function stopLiveVoiceTranscription({ discardTranscript = false } = {}) {
        const session = liveVoiceTranscriptionSession;
        if (!session) {
            return '';
        }

        liveVoiceTranscriptionSession = null;
        session.active = false;
        closeVoiceActionMenu();

        try {
            if (session.ws && session.ws.readyState === WebSocket.OPEN) {
                session.ws.send(JSON.stringify({ type: 'Terminate' }));
            }
        } catch (error) {
            console.warn('Unable to terminate live transcription cleanly.', error);
        }

        try {
            if (session.ws) {
                session.ws.close();
            }
        } catch (error) {
            console.warn('Unable to close the live transcription socket cleanly.', error);
        }

        if (session.processorNode) {
            try {
                session.processorNode.disconnect();
            } catch (error) {}
        }
        if (session.sourceNode) {
            try {
                session.sourceNode.disconnect();
            } catch (error) {}
        }
        if (session.silenceNode) {
            try {
                session.silenceNode.disconnect();
            } catch (error) {}
        }
        if (session.stream) {
            try {
                session.stream.getTracks().forEach(track => track.stop());
            } catch (error) {}
        }
        if (session.audioContext) {
            session.audioContext.close().catch(() => {});
        }

        const transcript = getLiveVoiceTranscriptionText(session);
        if (messageInput) {
            messageInput.value = discardTranscript
                ? String(session.composerSnapshot && session.composerSnapshot.value ? session.composerSnapshot.value : '')
                : buildComposerValueWithTranscript(session.composerSnapshot, transcript);
            updateComposerHighlightOverlay();
            messageInput.dispatchEvent(new Event('input', { bubbles: true }));
        }

        if (!discardTranscript && transcript) {
            logClientHistoryEvent('voice_transcription_used', {
                chatKey: String(selectedUser || ''),
                eventValue: 'Live transcription'
            }).catch(() => {});
        } else if (!discardTranscript) {
            showToast('No speech was detected.', 'info');
        }

        restoreAttachmentPreviewAfterTransientState();
        updateVoiceRecordButton();
        return transcript;
    }

    async function fetchAssemblyAiStreamingToken() {
        const response = await fetch('get_assemblyai_stream_token.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.success || !data.token) {
            throw new Error(data && data.error ? data.error : 'Could not start AssemblyAI streaming.');
        }
        return String(data.token);
    }

    async function createAssemblyAiPcmCapture(audioContext, stream, onChunk) {
        const sourceNode = audioContext.createMediaStreamSource(stream);
        const silenceNode = audioContext.createGain();
        silenceNode.gain.value = 0;
        const minSamplesPerChunk = Math.max(800, Math.floor(VOICE_TRANSCRIPTION_SAMPLE_RATE * 0.05));
        let bufferedSamples = new Int16Array(0);

        const pushSamples = arrayBuffer => {
            const incomingSamples = new Int16Array(arrayBuffer);
            if (!incomingSamples.length) {
                return;
            }

            const mergedSamples = new Int16Array(bufferedSamples.length + incomingSamples.length);
            mergedSamples.set(bufferedSamples, 0);
            mergedSamples.set(incomingSamples, bufferedSamples.length);
            bufferedSamples = mergedSamples;

            while (bufferedSamples.length >= minSamplesPerChunk) {
                const chunk = bufferedSamples.slice(0, minSamplesPerChunk);
                onChunk(chunk.buffer);
                bufferedSamples = bufferedSamples.slice(minSamplesPerChunk);
            }
        };

        if (audioContext.audioWorklet && typeof audioContext.audioWorklet.addModule === 'function') {
            await audioContext.audioWorklet.addModule('assemblyai-pcm-worklet.js');
            const processorNode = new AudioWorkletNode(audioContext, 'assemblyai-pcm16-processor');
            processorNode.port.onmessage = event => {
                if (event && event.data) {
                    pushSamples(event.data);
                }
            };
            sourceNode.connect(processorNode);
            processorNode.connect(silenceNode);
            silenceNode.connect(audioContext.destination);
            return { sourceNode, processorNode, silenceNode };
        }

        const processorNode = audioContext.createScriptProcessor(4096, 1, 1);
        processorNode.onaudioprocess = event => {
            const input = event.inputBuffer.getChannelData(0);
            const pcm16 = new Int16Array(input.length);
            for (let index = 0; index < input.length; index += 1) {
                const sample = Math.max(-1, Math.min(1, input[index]));
                pcm16[index] = sample < 0
                    ? Math.round(sample * 32768)
                    : Math.round(sample * 32767);
            }
            pushSamples(pcm16.buffer);
        };
        sourceNode.connect(processorNode);
        processorNode.connect(silenceNode);
        silenceNode.connect(audioContext.destination);
        return { sourceNode, processorNode, silenceNode };
    }

    async function startLiveVoiceTranscription() {
        if (!selectedUser) {
            showToast('Select a contact or accept a friend request first.', 'error');
            return;
        }

        if (isVoiceRecordingActive()) {
            showToast('Finish recording the voice message first.', 'error');
            return;
        }

        closeVoiceActionMenu();
        clearPendingAttachment(true);

        const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextCtor || !navigator.mediaDevices || typeof navigator.mediaDevices.getUserMedia !== 'function') {
            showToast('Live voice transcription is not supported on this device.', 'error');
            return;
        }

        try {
            const streamToken = await fetchAssemblyAiStreamingToken();
            const audioContext = new AudioContextCtor({ sampleRate: VOICE_TRANSCRIPTION_SAMPLE_RATE });
            await audioContext.resume();
            const stream = await navigator.mediaDevices.getUserMedia({
                audio: {
                    channelCount: 1,
                    echoCancellation: true,
                    noiseSuppression: true,
                    autoGainControl: true,
                    sampleRate: VOICE_TRANSCRIPTION_SAMPLE_RATE
                }
            });

            const session = {
                active: true,
                wsReady: false,
                turns: new Map(),
                interimTranscript: '',
                composerSnapshot: {
                    value: messageInput ? String(messageInput.value || '') : '',
                    start: messageInput && typeof messageInput.selectionStart === 'number'
                        ? messageInput.selectionStart
                        : (messageInput ? messageInput.value.length : 0),
                    end: messageInput && typeof messageInput.selectionEnd === 'number'
                        ? messageInput.selectionEnd
                        : (messageInput ? messageInput.value.length : 0)
                },
                audioContext,
                stream,
                ws: null,
                sourceNode: null,
                processorNode: null,
                silenceNode: null
            };

            liveVoiceTranscriptionSession = session;
            updateVoiceRecordButton();
            renderLiveVoiceTranscriptionPreview(session);

            const captureNodes = await createAssemblyAiPcmCapture(audioContext, stream, audioChunk => {
                if (liveVoiceTranscriptionSession !== session || !session.wsReady || !session.ws || session.ws.readyState !== WebSocket.OPEN) {
                    return;
                }

                try {
                    session.ws.send(audioChunk);
                } catch (error) {
                    console.warn('Unable to send live transcription audio chunk.', error);
                }
            });
            session.sourceNode = captureNodes.sourceNode;
            session.processorNode = captureNodes.processorNode;
            session.silenceNode = captureNodes.silenceNode;

            const socketUrl = new URL('wss://streaming.assemblyai.com/v3/ws');
            socketUrl.searchParams.set('token', streamToken);
            socketUrl.searchParams.set('sample_rate', String(VOICE_TRANSCRIPTION_SAMPLE_RATE));
            socketUrl.searchParams.set('encoding', 'pcm_s16le');
            socketUrl.searchParams.set('format_turns', 'true');
            socketUrl.searchParams.set('speech_model', 'u3-rt-pro');
            socketUrl.searchParams.set('inactivity_timeout', '15');
            const ws = new WebSocket(socketUrl.toString());
            ws.binaryType = 'arraybuffer';
            session.ws = ws;

            ws.addEventListener('open', () => {
                if (liveVoiceTranscriptionSession !== session) {
                    return;
                }

                session.wsReady = true;
                renderLiveVoiceTranscriptionPreview(session);
            });

            ws.addEventListener('message', event => {
                if (liveVoiceTranscriptionSession !== session) {
                    return;
                }

                try {
                    const payload = JSON.parse(event.data);
                    if (payload.type !== 'Turn') {
                        return;
                    }

                    const turnOrder = Number(payload.turn_order || 0);
                    const transcript = String(payload.transcript || '').trim();
                    if (payload.end_of_turn) {
                        if (transcript) {
                            session.turns.set(turnOrder, transcript);
                        }
                        session.interimTranscript = '';
                    } else {
                        session.interimTranscript = transcript;
                    }

                    applyLiveVoiceTranscriptToComposer(session);
                    renderLiveVoiceTranscriptionPreview(session);
                } catch (error) {
                    console.warn('Unable to parse AssemblyAI live transcription event.', error);
                }
            });

            ws.addEventListener('error', error => {
                console.error('AssemblyAI live transcription error:', error);
                if (liveVoiceTranscriptionSession === session) {
                    stopLiveVoiceTranscription({ discardTranscript: true });
                    showToast('Could not start live transcription right now.', 'error');
                }
            });

            ws.addEventListener('close', () => {
                if (liveVoiceTranscriptionSession !== session) {
                    return;
                }

                const transcript = getLiveVoiceTranscriptionText(session);
                stopLiveVoiceTranscription({ discardTranscript: !transcript });
                if (!transcript) {
                    showToast('Live transcription ended.', 'info');
                }
            });
        } catch (error) {
            console.error('Live voice transcription start failed:', error);
            if (liveVoiceTranscriptionSession) {
                stopLiveVoiceTranscription({ discardTranscript: true });
            }
            showToast(error && error.message ? error.message : 'Microphone access is required for live transcription.', 'error');
        }
    }

    function clearPendingAttachment(resetInput = true) {
        if (isLiveVoiceTranscriptionActive()) {
            stopLiveVoiceTranscription({ discardTranscript: true });
        }

        if (isVoiceRecordingActive()) {
            discardVoiceRecording = true;
            try {
                voiceMediaRecorder.stop();
            } catch (e) {
                console.warn('Unable to stop voice recorder cleanly.', e);
            }
        }

        pendingAttachmentVersion += 1;
        pendingAttachmentFile = null;
        pendingAttachmentMeta = null;
        pendingAttachmentMetaPromise = null;
        pendingGifAttachments = [];
        pendingTableDraft = null;

        if (attachmentPreviewCard && activeVoiceMessageAudio && attachmentPreviewCard.contains(activeVoiceMessageAudio)) {
            try {
                activeVoiceMessageAudio.pause();
            } catch (e) {
                console.warn('Unable to pause pending voice preview.', e);
            }
            activeVoiceMessageAudio = null;
        }

        if (pendingAttachmentObjectUrl) {
            URL.revokeObjectURL(pendingAttachmentObjectUrl);
            pendingAttachmentObjectUrl = null;
        }

        if (attachmentPreviewCard) {
            attachmentPreviewCard.innerHTML = '';
        }

        if (attachmentPreviewRow) {
            attachmentPreviewRow.classList.remove('active');
        }

        if (resetInput && attachmentInput) {
            attachmentInput.value = '';
        }
    }

    function updatePendingTableDraftCell(rowIndex, colIndex, value) {
        if (!pendingTableDraft || !pendingTableDraft.cells || !pendingTableDraft.cells[rowIndex]) {
            return;
        }

        pendingTableDraft.cells[rowIndex][colIndex] = sanitizeTableMessageCellValue(value);
    }

    function renderPendingTableDraftPreview() {
        if (!attachmentPreviewCard || !attachmentPreviewRow) {
            return;
        }

        if (!pendingTableDraft) {
            attachmentPreviewCard.innerHTML = '';
            attachmentPreviewRow.classList.remove('active');
            return;
        }

        if (activeVoiceMessageAudio && attachmentPreviewCard.contains(activeVoiceMessageAudio)) {
            try {
                activeVoiceMessageAudio.pause();
            } catch (error) {
                console.warn('Unable to pause voice preview before table render.', error);
            }
            activeVoiceMessageAudio = null;
        }

        attachmentPreviewCard.innerHTML = '';

        const card = document.createElement('div');
        card.className = 'attachment-preview-card table-preview';

        const meta = document.createElement('div');
        meta.className = 'attachment-preview-table-meta';

        const title = document.createElement('div');
        title.className = 'attachment-preview-title';
        title.textContent = `${pendingTableDraft.rows} x ${pendingTableDraft.cols} table`;

        const subtitle = document.createElement('div');
        subtitle.className = 'attachment-preview-subtitle';
        subtitle.textContent = 'Edit each cell before sending';

        meta.appendChild(title);
        meta.appendChild(subtitle);
        card.appendChild(meta);

        const shell = document.createElement('div');
        shell.className = 'attachment-preview-table-shell';
        shell.appendChild(buildTableMessageNode(pendingTableDraft, String(selectedUser || ''), {
            editable: true,
            onCellChange: updatePendingTableDraftCell
        }));
        card.appendChild(shell);

        const clearBtn = document.createElement('button');
        clearBtn.type = 'button';
        clearBtn.className = 'attachment-preview-clear';
        clearBtn.setAttribute('aria-label', 'Remove table');
        clearBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
        clearBtn.addEventListener('click', () => {
            clearPendingAttachment(true);
        });
        card.appendChild(clearBtn);

        attachmentPreviewCard.appendChild(card);
        attachmentPreviewRow.classList.add('active');

        window.requestAnimationFrame(() => {
            const firstCell = card.querySelector('.message-table-wrap.is-editable .message-table-cell');
            if (firstCell && typeof firstCell.focus === 'function') {
                firstCell.focus({ preventScroll: true });
            }
        });
    }

    function queuePendingTableDraft(tableData) {
        const normalized = normalizeTableMessagePayload(tableData);
        if (!normalized) {
            showToast('Could not create that table right now.', 'error');
            return;
        }

        const replacedAttachment = !!pendingAttachmentFile || !!pendingAttachmentMeta || !!pendingAttachmentMetaPromise;
        const replacedGifs = pendingGifAttachments.length > 0;
        const replacedTable = !!pendingTableDraft;

        if (replacedAttachment || replacedGifs || replacedTable) {
            clearPendingAttachment(false);
        }

        pendingTableDraft = normalized;
        renderPendingTableDraftPreview();

        if (replacedAttachment || replacedGifs) {
            showToast('Table replaced the current attachment.', 'info');
        } else if (replacedTable) {
            showToast('Table draft updated.', 'success');
        } else {
            showToast('Table ready to send.', 'success');
        }
    }

    function getPendingTableDraftSnapshot() {
        if (!pendingTableDraft) {
            return null;
        }

        return normalizeTableMessagePayload({
            rows: pendingTableDraft.rows,
            cols: pendingTableDraft.cols,
            cells: pendingTableDraft.cells
        });
    }

    function renderPendingGifAttachmentPreview() {
        if (!attachmentPreviewCard || !attachmentPreviewRow) {
            return;
        }

        if (!pendingGifAttachments.length) {
            attachmentPreviewCard.innerHTML = '';
            attachmentPreviewRow.classList.remove('active');
            return;
        }

        if (activeVoiceMessageAudio && attachmentPreviewCard.contains(activeVoiceMessageAudio)) {
            try {
                activeVoiceMessageAudio.pause();
            } catch (e) {
                console.warn('Unable to pause pending voice preview before GIF render.', e);
            }
            activeVoiceMessageAudio = null;
        }

        attachmentPreviewCard.innerHTML = '';

        const list = document.createElement('div');
        list.className = 'attachment-preview-card-list';

        const summary = document.createElement('div');
        summary.className = 'attachment-preview-gif-summary';
        summary.textContent = pendingGifAttachments.length === 1
            ? '1 GIF ready'
            : `${pendingGifAttachments.length} GIFs ready`;
        list.appendChild(summary);

        pendingGifAttachments.forEach((item, index) => {
            const card = document.createElement('div');
            card.className = 'attachment-preview-card gif-preview';
            if (isSubmitting) {
                card.classList.add('is-sending');
            }

            const image = document.createElement('img');
            image.className = 'attachment-preview-thumb';
            image.src = item.previewUrl;
            image.alt = item.title || `Selected GIF ${index + 1}`;
            image.loading = 'lazy';
            card.appendChild(image);

            const clearBtn = document.createElement('button');
            clearBtn.type = 'button';
            clearBtn.className = 'attachment-preview-clear';
            clearBtn.setAttribute('aria-label', `Remove GIF ${index + 1}`);
            clearBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
            clearBtn.disabled = isSubmitting;
            clearBtn.addEventListener('click', () => {
                if (isSubmitting) {
                    return;
                }

                pendingGifAttachments = pendingGifAttachments.filter((_, gifIndex) => gifIndex !== index);
                if (pendingGifAttachments.length) {
                    renderPendingGifAttachmentPreview();
                } else {
                    clearPendingAttachment(true);
                }
            });
            card.appendChild(clearBtn);

            list.appendChild(card);
        });

        attachmentPreviewCard.appendChild(list);
        attachmentPreviewRow.classList.add('active');
    }

    function queuePendingGifAttachments(items) {
        const normalizedItems = Array.isArray(items)
            ? items.filter(item => item && item.sendUrl && item.previewUrl)
            : [];
        if (!normalizedItems.length) {
            return;
        }

        recordGifUsage(normalizedItems);

        const hadSingleAttachment = !!pendingAttachmentFile || !!pendingTableDraft;
        if (pendingAttachmentFile || pendingAttachmentMeta || pendingAttachmentMetaPromise || pendingTableDraft) {
            clearPendingAttachment(false);
        }

        pendingGifAttachments = mergeGifSelectionItems(pendingGifAttachments, normalizedItems);
        renderPendingGifAttachmentPreview();

        if (hadSingleAttachment) {
            showToast('Selected GIFs replaced the current attachment.', 'info');
        } else {
            showToast(`${pendingGifAttachments.length} GIF${pendingGifAttachments.length === 1 ? '' : 's'} ready to send.`, 'success');
        }
    }

    function showRecordingPreview() {
        if (!attachmentPreviewCard || !attachmentPreviewRow) {
            return;
        }

        attachmentPreviewCard.innerHTML = '';

        const card = document.createElement('div');
        card.className = 'attachment-preview-card';

