        const title = document.createElement('div');
        title.className = 'attachment-preview-title';
        title.textContent = 'Recording voice message';

        const subtitle = document.createElement('div');
        subtitle.className = 'attachment-preview-subtitle';
        subtitle.textContent = 'Tap the microphone again to stop';

        meta.appendChild(title);
        meta.appendChild(subtitle);
        card.appendChild(meta);

        const clearBtn = document.createElement('button');
        clearBtn.type = 'button';
        clearBtn.className = 'attachment-preview-clear';
