        clearBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
        clearBtn.addEventListener('click', () => {
            clearPendingAttachment(true);
        });
        card.appendChild(clearBtn);

        attachmentPreviewCard.appendChild(card);
        attachmentPreviewRow.classList.add('active');
    }

    function renderPendingAttachmentPreview(file) {
        if (!file || !attachmentPreviewCard || !attachmentPreviewRow) {
            return;
        }

        if (activeVoiceMessageAudio && attachmentPreviewCard.contains(activeVoiceMessageAudio)) {
            try {
                activeVoiceMessageAudio.pause();
            } catch (e) {
                console.warn('Unable to pause voice preview before rerender.', e);
            }
            activeVoiceMessageAudio = null;
        }

        const card = document.createElement('div');
        card.className = 'attachment-preview-card';

        if (file.type && (file.type.startsWith('image/') || file.type.startsWith('video/'))) {
            pendingAttachmentObjectUrl = URL.createObjectURL(file);
            const mediaShell = document.createElement('div');
            mediaShell.className = 'attachment-preview-media-shell';

            if (file.type.startsWith('video/')) {
                const video = document.createElement('video');
                video.className = 'attachment-preview-thumb';
                video.src = pendingAttachmentObjectUrl;
                video.muted = true;
                video.playsInline = true;
                video.preload = 'auto';
                video.setAttribute('playsinline', '');
                video.setAttribute('aria-hidden', 'true');
                hydrateVideoPreviewElement(video, pendingAttachmentObjectUrl, { preload: 'auto', primeFrame: true });
                mediaShell.appendChild(video);
                mediaShell.appendChild(createVideoPlayBadge('attachment-preview-play-badge'));
            } else {
                const image = document.createElement('img');
                image.className = 'attachment-preview-thumb';
                image.src = pendingAttachmentObjectUrl;
                image.alt = file.name || 'Selected image';
                mediaShell.appendChild(image);
            }

            card.appendChild(mediaShell);
        } else if (file.type && file.type.startsWith('audio/')) {
            pendingAttachmentObjectUrl = URL.createObjectURL(file);
            card.classList.add('voice-preview');
            card.appendChild(buildVoiceMessagePlayer({
                kind: 'audio',
                url: pendingAttachmentObjectUrl,
                name: file.name || 'Voice message',
                mime: file.type || '',
                duration: pendingAttachmentMeta && pendingAttachmentMeta.duration,
                waveform: pendingAttachmentMeta && pendingAttachmentMeta.waveform
            }));
        } else {
            const icon = document.createElement('div');
            icon.className = 'attachment-preview-file-icon';
            icon.innerHTML = '<i class="fa-regular fa-file"></i>';
            card.appendChild(icon);
        }

        if (!(file.type && file.type.startsWith('audio/'))) {
            const meta = document.createElement('div');
            meta.className = 'attachment-preview-meta';

            const title = document.createElement('div');
            title.className = 'attachment-preview-title';
            title.textContent = file.name || 'Selected file';

            const subtitle = document.createElement('div');
            subtitle.className = 'attachment-preview-subtitle';
            if (file.type && file.type.startsWith('image/')) {
                subtitle.textContent = 'Ready to send';
            } else {
                subtitle.textContent = formatAttachmentSize(file.size) || 'Ready to send';
            }

            meta.appendChild(title);
            meta.appendChild(subtitle);
            card.appendChild(meta);
        }

        const clearBtn = document.createElement('button');
        clearBtn.type = 'button';
        clearBtn.className = 'attachment-preview-clear';
        clearBtn.setAttribute('aria-label', 'Remove attachment');
        clearBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
        clearBtn.addEventListener('click', () => {
            clearPendingAttachment(true);
        });
        card.appendChild(clearBtn);

        attachmentPreviewCard.innerHTML = '';
        attachmentPreviewCard.appendChild(card);
        attachmentPreviewRow.classList.add('active');
    }

    function showPendingAttachment(file, meta = null) {
        if (!file || !attachmentPreviewCard || !attachmentPreviewRow) {
            return;
        }

        clearPendingAttachment(false);
        const attachmentVersion = pendingAttachmentVersion;
        pendingAttachmentFile = file;
        pendingAttachmentMeta = file.type && file.type.startsWith('audio/')
            ? createVoiceAttachmentMeta(meta || {})
            : null;
        pendingAttachmentMetaPromise = null;
        renderPendingAttachmentPreview(file);

        if (file.type && file.type.startsWith('audio/') && !meta) {
            pendingAttachmentMetaPromise = analyzeAudioFile(file)
                .then(resolvedMeta => {
                    if (pendingAttachmentVersion !== attachmentVersion || pendingAttachmentFile !== file) {
                        return resolvedMeta;
                    }

                    pendingAttachmentMeta = resolvedMeta;
                    if (pendingAttachmentObjectUrl) {
                        URL.revokeObjectURL(pendingAttachmentObjectUrl);
                        pendingAttachmentObjectUrl = null;
                    }
                    renderPendingAttachmentPreview(file);
                    return resolvedMeta;
                })
                .catch(error => {
                    console.warn('Voice attachment preview metadata failed.', error);
                    return createVoiceAttachmentMeta();
                });
        }
    }

    function handleSuccessfulOutgoingNewMessage(data, attachmentFileToSend, recipientKey, replyReference = null) {
        const outgoingGroupId = getGroupIdFromChatKey(recipientKey);
        const isVoiceMsg = !!(attachmentFileToSend && attachmentFileToSend.type && attachmentFileToSend.type.startsWith('audio/'));
        const localBlobUrl = isVoiceMsg ? URL.createObjectURL(attachmentFileToSend) : null;
        const newMessageObj = {
            id: data.message.id,
            client_id: data.message.client_id || '',
            message: data.message.message,
            sender_id: currentUserId,
            recipient_id: getChatTypeFromKey(recipientKey) === 'direct' ? recipientKey : null,
            group_id: data.message.group_id || (outgoingGroupId || null),
            chat_key: data.message.chat_key || recipientKey,
            sender_display_name: currentUserDisplayName,
            sender_profile_pic: currentUserProfilePic || defaultProfilePic,
            sender_online: 1,
            sender_chat_nickname: data.message.sender_chat_nickname || '',
            self: true,
            created_at: data.message.created_at,
            reply_to_id: data.message.reply_to_id || null,
            forward_from_user_id: data.message.forward_from_user_id || null,
            forward_from_display_name: data.message.forward_from_display_name || null,
            reply_to_ref_id: data.message.reply_to_ref_id || null,
            reply_to_display_name: data.message.reply_to_display_name || null,
            reply_to_message_body: data.message.reply_to_message_body || null,
            _localBlobUrl: localBlobUrl
        };
        applyReplyReferenceToMessage(newMessageObj, replyReference);

        hydrateMessageSenderData(newMessageObj);
        appendMessage(newMessageObj);
        lastId = Math.max(Number(lastId || 0), Number(newMessageObj.id || 0));
        fetchReactionsForMessageIds([Number(newMessageObj.id)]).catch(() => {});
        window.chatLastSeen = newMessageObj.id;
        updateContactPreview(recipientKey, newMessageObj, true);
        scrollChatToBottomAfterSend();
    }

    function clearComposerAfterSend(recipientKey, clearAttachments = true, options = {}) {
        const normalizedOptions = typeof options === 'boolean'
            ? { preserveTypingIndicator: options }
            : (options && typeof options === 'object' ? options : {});
        const preserveTypingIndicator = !!normalizedOptions.preserveTypingIndicator;
        const activeTypingKey = String(typingIndicatorUser || '').trim();
        const expectedTypingKey = `__qt_ai_typing__:${String(recipientKey || '').trim()}`;
        const shouldPreserveTypingIndicator = preserveTypingIndicator && activeTypingKey !== '' && activeTypingKey === expectedTypingKey;
        clearLocalTyping(true);
        if (!shouldPreserveTypingIndicator) {
            hideTypingIndicator();
        }
        hideEmojiPicker();
        closeCommandPicker();
        closeMentionPicker();
        if (messageInput) {
            messageInput.value = '';
            messageInput.scrollTop = 0;
        }
        updateComposerHighlightOverlay();
        if (clearAttachments) {
            clearPendingAttachment(true);
        }
        pendingReply = null;
        updateReplyBar();
        if (recipientKey) {
            setComposerDraft(recipientKey, '');
            clearDraftPreview(recipientKey, false);
        }
    }

    async function sendPendingGifQueue(messageText = '') {
        if (!selectedUser || !pendingGifAttachments.length) {
            return;
        }

        const recipientKey = selectedUser;
        const replyToId = pendingReply && pendingReply.id ? Number(pendingReply.id) : 0;
        let composerCleared = false;

        while (pendingGifAttachments.length) {
            const gifItem = pendingGifAttachments[0];
            const gifResponse = await fetch(String(gifItem.sendUrl || ''));
            if (!gifResponse.ok) {
                throw new Error('Could not download that GIF right now.');
            }

            const blob = await gifResponse.blob();
            const blobType = String(blob.type || gifResponse.headers.get('content-type') || '').toLowerCase();
            const fileType = blobType.startsWith('image/') ? blobType : 'image/gif';
            const fileName = String(gifItem.fileName || buildGifFileName(gifItem.title || 'GIF'));
            const file = new File([blob], fileName, { type: fileType });

            const formData = new FormData();
            formData.append('token', token);
            formData.append('recipient_id', recipientKey);
            formData.append('message', composerCleared ? '' : messageText);
            formData.append('attachment', file);
            if (!composerCleared && replyToId > 0) {
                formData.append('reply_to_id', String(replyToId));
            }

            const res = await fetch('send_message.php', {
                method: 'POST',
                body: formData
            });
            const data = await res.json().catch(() => ({}));

            if (!data.success) {
                if (data && typeof data.error === 'string' && data.error.toLowerCase().includes('blocked')) {
                    await pollContacts();
                    if (selectedUser) {
                        updateHeaderContact(selectedUser);
                    }
                }
                throw new Error(data.error || 'Error sending GIF');
            }

            handleSuccessfulOutgoingNewMessage(data, file, recipientKey);
            pendingGifAttachments.shift();

            if (!composerCleared) {
                clearComposerAfterSend(recipientKey, false);
                composerCleared = true;
            }

            if (pendingGifAttachments.length) {
                renderPendingGifAttachmentPreview();
            }
        }

        clearPendingAttachment(true);
    }

    function parseComposerNicknameCommand(text) {
        const normalizedText = String(text || '').trim();
        if (/^\/nick\s+clear$/i.test(normalizedText)) {
            return {
                nickname: '',
                isClear: true
            };
        }

        const match = normalizedText.match(/^\/nick(?:\s+(.*))?$/i);
        if (!match) {
            return null;
        }

        return {
            nickname: normalizeChatScopedNicknameValue(match[1] || ''),
            isClear: !normalizeChatScopedNicknameValue(match[1] || '')
        };
    }

    const LOCAL_AI_BOT_ID = '__qt_local_ai__';
    const LOCAL_AI_BOT_NAME = 'QuillTalk AI';
    const LOCAL_AI_STORAGE_KEY = `quilltalk.localAiMessages.v1.${currentUserId}`;
    const LOCAL_AI_REACTIONS_STORAGE_KEY = `quilltalk.localAiReactions.v1.${currentUserId}`;
    const LOCAL_AI_MAX_MESSAGES_PER_CHAT = 120;
    const LOCAL_AI_REPLY_MIN_DELAY_MS = 2000;
    const LOCAL_AI_REPLY_MAX_DELAY_MS = 3000;
    const LOCAL_AI_STOPWORDS = new Set([
        'a', 'about', 'after', 'all', 'also', 'an', 'and', 'any', 'are', 'as', 'at',
        'be', 'because', 'been', 'before', 'being', 'but', 'by', 'can', 'could',
        'did', 'do', 'does', 'for', 'from', 'get', 'had', 'has', 'have', 'how',
        'i', 'if', 'in', 'into', 'is', 'it', 'its', 'just', 'like', 'make', 'me',
        'more', 'my', 'need', 'of', 'on', 'or', 'our', 'out', 'please', 'so',
        'some', 'something', 'that', 'the', 'their', 'them', 'then', 'there',
        'these', 'they', 'this', 'to', 'up', 'us', 'want', 'was', 'we', 'well',
        'what', 'when', 'where', 'which', 'who', 'why', 'with', 'would', 'you',
        'your'
    ]);
    let localAiMessageSequence = 0;
    let localAiThreadsCache = loadLocalAiThreads();
    let localAiReactionsCache = loadLocalAiReactions();

    function isLocalAiMessageRecord(msg) {
        return !!(msg && msg._localAiMessage);
    }

    function supportsLocalAiLocalOnlyActions(messageRecord) {
        if (!isLocalAiMessageRecord(messageRecord)) {
            return false;
        }

        const messageId = getMessageServerId(messageRecord);
        return Number.isFinite(messageId) && messageId < 0;
    }

    function isAiGeneratedImage(messageRecord) {
        return !!(messageRecord && messageRecord._localAiMessage && messageRecord._localAiMessage.kind === 'image');
    }

    function nextLocalAiMessageId() {
        localAiMessageSequence = (localAiMessageSequence + 1) % 1000;
        return -1 * ((Date.now() * 1000) + localAiMessageSequence);
    }

    function normalizeLocalAiMessageText(text) {
        return String(text || '')
            .replace(/\r\n/g, '\n')
            .replace(/\r/g, '\n')
            .replace(/[ \t]+\n/g, '\n')
            .replace(/\n{3,}/g, '\n\n')
            .trim();
    }

    function normalizeLocalAiPromptText(text) {
        return normalizeLocalAiMessageText(text).replace(/\s+/g, ' ').trim();
    }

    function parseStoredAiCommandMessage(text) {
        const normalizedText = String(text || '')
            .replace(/\r\n/g, '\n')
            .replace(/\r/g, '\n')
            .trim();

        if (!normalizedText) {
            return null;
        }

        const privateImagineMatch = normalizedText.match(/^You used \/ai privately imagine\s*\n\n([\s\S]+)$/i);
        if (privateImagineMatch) {
            return {
                prompt: normalizeLocalAiPromptText(privateImagineMatch[1] || ''),
                isPrivate: true,
                mode: 'image'
            };
        }

        const publicImagineMatch = normalizedText.match(/^You used \/ai imagine\s*\n\n([\s\S]+)$/i);
        if (publicImagineMatch) {
            return {
                prompt: normalizeLocalAiPromptText(publicImagineMatch[1] || ''),
                isPrivate: false,
                mode: 'image'
            };
        }

        const privateTextMatch = normalizedText.match(/^You used \/ai privately\s*\n\n([\s\S]+)$/i);
        if (privateTextMatch) {
            return {
                prompt: normalizeLocalAiPromptText(privateTextMatch[1] || ''),
                isPrivate: true,
                mode: 'text'
            };
        }

        const publicTextMatch = normalizedText.match(/^You used \/ai\s*\n\n([\s\S]+)$/i);
        if (publicTextMatch) {
            return {
                prompt: normalizeLocalAiPromptText(publicTextMatch[1] || ''),
                isPrivate: false,
                mode: 'text'
            };
        }

        return null;
    }

    function extractAiImageIntentPrompt(text) {
        const normalizedText = normalizeLocalAiMessageText(text);
        if (!normalizedText) {
            return '';
        }

        const patterns = [
            /^(?:please\s+)?(?:can you\s+|could you\s+|would you\s+)?(?:draw|paint|sketch|illustrate|render|imagine|visualize)\s+(?:me\s+)?(?:an?\s+)?(?:image|picture|photo|illustration|drawing|sketch|artwork|logo|poster|scene)?\s*(?:of|for)?\s*(.+)$/i,
            /^(?:please\s+)?(?:can you\s+|could you\s+|would you\s+)?(?:generate|create|make|show|design)\s+(?:me\s+)?(?:an?\s+)?(?:image|picture|photo|illustration|drawing|sketch|artwork|logo|poster|scene)\s*(?:of|for)?\s*(.+)$/i,
            /\b(?:generate|create|make|show|design|visualize)\s+(?:an?\s+)?(?:image|picture|photo|illustration|drawing|sketch|artwork|logo|poster|scene)\s*(?:of|for)?\s+(.+)$/i,
            /^(?:image|picture|photo|artwork|illustration|logo|poster)\s+(?:of|for)\s+(.+)$/i
        ];

        for (const pattern of patterns) {
            const match = normalizedText.match(pattern);
            if (match) {
                return normalizeLocalAiPromptText(match[1] || '');
            }
        }

        return '';
    }

    const pendingAiImageRequests = new Map();

    function buildAiImageRequestKey(chatKey, prompt, mode, originMessageId, editMessageId = 0) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedPrompt = normalizeLocalAiPromptText(prompt).toLowerCase();
        const normalizedMode = String(mode || '').trim().toLowerCase();
        const normalizedOriginMessageId = Math.max(0, Number(originMessageId || 0) || 0);
        const parsedEditMessageId = Number(editMessageId || 0);
        const normalizedEditMessageId = Number.isFinite(parsedEditMessageId) ? Math.trunc(parsedEditMessageId) : 0;
        return [normalizedMode, normalizedChatKey, normalizedOriginMessageId, normalizedEditMessageId, normalizedPrompt].join('::');
    }

    function buildPendingAiImageAttachmentMessage(statusLabel = 'Generating image') {
        return ATTACHMENT_MESSAGE_PREFIX + JSON.stringify({
            kind: 'image',
            pending: true,
            loading_label: String(statusLabel || 'Generating image'),
            ai_generated: true
        });
    }

    function buildPendingAiImageMessageRecord(messageRecord, statusLabel = 'Generating image') {
        return cloneMessageRecordWithRawMessage(messageRecord, buildPendingAiImageAttachmentMessage(statusLabel));
    }

    function closeOpenAiImageImproviser(exceptMessageId = 0) {
        if (!chatBox) {
            return;
        }

        const normalizedExceptMessageId = String(exceptMessageId || '').trim();
        chatBox.querySelectorAll('.message-ai-improvise-shell.is-open').forEach(shell => {
            const shellMessageId = String(shell.dataset.messageId || '').trim();
            if (normalizedExceptMessageId && shellMessageId === normalizedExceptMessageId) {
                return;
            }
            shell.classList.remove('is-open');
        });
    }

    function removeEphemeralMessageByClientId(clientId) {
        if (!chatBox) {
            return;
        }

        const normalizedClientId = String(clientId || '').trim();
        if (!normalizedClientId) {
            return;
        }

        const messageEl = chatBox.querySelector(`.message[data-id="${normalizedClientId}"]`);
        if (!messageEl) {
            return;
        }

        const previousEl = messageEl.previousElementSibling;
        const nextEl = messageEl.nextElementSibling;
        messageEl.remove();

        if (
            previousEl
            && previousEl.classList
            && previousEl.classList.contains('timestamp')
            && (!nextEl || (nextEl.classList && nextEl.classList.contains('timestamp')))
        ) {
            previousEl.remove();
        }

        if (typeof applyConsecutiveClassToAllMessages === 'function') {
            applyConsecutiveClassToAllMessages();
        }
    }

    function showPendingAiImageMessage(chatKey, options = {}) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey || String(selectedUser || '') !== normalizedChatKey) {
            return '';
        }

        const identity = getAiAssistantIdentityForChat(normalizedChatKey);
        const pendingMessage = sanitizeStoredLocalAiMessage({
            id: nextLocalAiMessageId(),
            message: buildPendingAiImageAttachmentMessage(options.statusLabel || 'Generating image'),
            chat_key: normalizedChatKey,
            sender_display_name: String(options.displayName || identity.displayName || 'QuillTalk AI'),
            sender_profile_pic: String(options.profilePic || identity.profilePic || DEFAULT_AI_PROFILE_PIC),
            created_at: new Date().toISOString(),
            _localAiMessage: true,
            _localAiRole: 'assistant',
            _localAiPrivate: false
        }, normalizedChatKey);
        if (!pendingMessage) {
            return '';
        }

        appendMessage(pendingMessage);
        scrollChatToBottomAfterSend();
        return getMessageClientId(pendingMessage, normalizedChatKey);
    }

    async function requestAiGeneratedImage(chatKey, prompt, options = {}) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedPrompt = normalizeLocalAiPromptText(prompt);
        const mode = String(options.mode || (normalizedChatKey.startsWith('ai:') ? 'ai_chat' : 'public')).trim().toLowerCase();
        const originMessageId = Math.max(0, Number(options.originMessageId || 0) || 0);
        const parsedEditMessageId = Number(options.editMessageId || 0);
        const editMessageId = Number.isFinite(parsedEditMessageId) ? Math.trunc(parsedEditMessageId) : 0;
        const isImprovisation = editMessageId !== 0;
        const originalMessageRecord = isImprovisation && options.existingMessageRecord && typeof options.existingMessageRecord === 'object'
            ? Object.assign({}, options.existingMessageRecord)
            : null;
        const sourceAttachmentUrl = String(options.sourceAttachmentUrl || '').trim();
        const sourcePrompt = String(options.sourcePrompt || '').trim();

        if (!normalizedChatKey || !normalizedPrompt) {
            throw new Error('Type an image prompt first.');
        }

        const requestKey = buildAiImageRequestKey(normalizedChatKey, normalizedPrompt, mode, originMessageId, editMessageId);
        if (pendingAiImageRequests.has(requestKey)) {
            return pendingAiImageRequests.get(requestKey);
        }

        const identity = getAiAssistantIdentityForChat(normalizedChatKey);
        const placeholderClientId = isImprovisation ? '' : showPendingAiImageMessage(normalizedChatKey, {
            displayName: identity.displayName,
            profilePic: identity.profilePic,
            statusLabel: mode === 'private' ? 'Generating private image' : 'Generating image'
        });
        if (isImprovisation && originalMessageRecord) {
            replaceRenderedMessage(
                buildPendingAiImageMessageRecord(
                    originalMessageRecord,
                    String(options.statusLabel || 'Improvising image')
                )
            );
        }
        let placeholderCleared = false;
        const clearPlaceholder = () => {
            if (placeholderCleared) {
                return;
            }
            placeholderCleared = true;
            if (placeholderClientId) {
                removeEphemeralMessageByClientId(placeholderClientId);
            }
        };

        const requestPromise = (async () => {
            const response = await fetch('generate_ai_image.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    chat_key: normalizedChatKey,
                    prompt: normalizedPrompt,
                    mode,
                    origin_message_id: originMessageId,
                    edit_message_id: Math.max(0, editMessageId),
                    source_attachment_url: sourceAttachmentUrl,
                    source_prompt: sourcePrompt
                })
            });
            const { data, rawText: rawResponseText } = await readJsonResponseSafely(response);

            if (!response.ok || !data.success) {
                const nestedErrorMessage = data && typeof data.error === 'object' && data.error && typeof data.error.message === 'string'
                    ? data.error.message
                    : '';
                const rawFallbackMessage = rawResponseText
                    ? rawResponseText.trim().replace(/\s+/g, ' ').slice(0, 220)
                    : '';
                const emptyServerFailureMessage = !rawFallbackMessage && response.status >= 500
                    ? 'The AI image endpoint returned an empty HTTP ' + response.status + ' response. This usually means generate_ai_image.php crashed on the server before it could return JSON.'
                    : '';
                throw new Error(
                    (typeof data.error === 'string' && data.error)
                    || nestedErrorMessage
                    || emptyServerFailureMessage
                    || rawFallbackMessage
                    || `Could not generate that image right now (HTTP ${response.status}).`
                );
            }

            if (mode === 'private') {
                clearPlaceholder();
                if (isImprovisation && originalMessageRecord) {
                    const updatedLocalMessage = cloneMessageRecordWithRawMessage(originalMessageRecord, String(data.attachment_message || ''));
                    if (!updatedLocalMessage) {
                        return null;
                    }
                    updatedLocalMessage._localAiPrivate = true;
                    const storedUpdatedMessage = storeLocalAiMessage(normalizedChatKey, updatedLocalMessage);
                    if (storedUpdatedMessage) {
                        replaceRenderedMessage(storedUpdatedMessage);
                        invalidateSidebarHistoryCache({ reloadIfVisible: true });
                    }
                    return storedUpdatedMessage;
                }
                const replyMessage = createLocalAiMessage(normalizedChatKey, 'assistant', String(data.attachment_message || ''));
                if (!replyMessage) {
                    return null;
                }
                replyMessage._localAiPrivate = true;
                const storedReply = storeLocalAiMessage(normalizedChatKey, replyMessage);
                if (storedReply) {
                    appendLocalAiMessageToActiveChat(storedReply, { scrollToBottom: true });
                }
                return storedReply;
            }

            if (data.message) {
                clearPlaceholder();
                if (isImprovisation) {
                    replaceRenderedMessage(data.message);
                    invalidateSidebarHistoryCache({ reloadIfVisible: true });
                    if (typeof updateContactPreview === 'function') {
                        updateContactPreview(normalizedChatKey, data.message, String(selectedUser || '') === normalizedChatKey);
                    }
                    return data.message;
                }
                if (String(selectedUser || '') === normalizedChatKey) {
                    appendMessage(data.message);
                    lastId = Math.max(Number(lastId || 0), Number(data.message.id || 0));
                    scrollChatToBottomAfterSend();
                }
                if (typeof updateContactPreview === 'function') {
                    updateContactPreview(normalizedChatKey, data.message, String(selectedUser || '') === normalizedChatKey);
                }
                return data.message;
            }

            clearPlaceholder();
            return null;
        })();

        const trackedRequest = requestPromise
            .catch(error => {
                if (isImprovisation && originalMessageRecord) {
                    replaceRenderedMessage(originalMessageRecord);
                }
                throw error;
            })
            .finally(() => {
                clearPlaceholder();
                pendingAiImageRequests.delete(requestKey);
            });
        pendingAiImageRequests.set(requestKey, trackedRequest);
        return trackedRequest;
    }

    async function requestAiImageImprovisation(messageEl, instructions) {
        const messageRecord = messageEl && messageEl._qtMessageRecord && typeof messageEl._qtMessageRecord === 'object'
            ? messageEl._qtMessageRecord
            : null;
        const normalizedInstructions = normalizeLocalAiPromptText(instructions);
        const parsedMessageId = Number(messageRecord && messageRecord.id ? messageRecord.id : (messageEl && messageEl.dataset ? messageEl.dataset.messageId : 0));
        const messageId = Number.isFinite(parsedMessageId) ? Math.trunc(parsedMessageId) : 0;
        const chatKey = String((messageRecord && getMessageChatKey(messageRecord)) || selectedUser || '').trim();
        const attachmentPayload = parseAttachmentMessage(messageRecord && messageRecord.message ? messageRecord.message : '');
        const isPrivateLocalMessage = !!(messageRecord && messageRecord._localAiPrivate);

        if (!messageRecord || !messageId || !chatKey || !attachmentPayload || attachmentPayload.kind !== 'image') {
            throw new Error('That AI image could not be improvised right now.');
        }
        if (!normalizedInstructions) {
            throw new Error('Type how you want to improvise the image first.');
        }

        closeOpenAiImageImproviser();
        return requestAiGeneratedImage(chatKey, normalizedInstructions, {
            mode: isPrivateLocalMessage ? 'private' : (chatKey.startsWith('ai:') ? 'ai_chat' : 'public'),
            editMessageId: messageId,
            existingMessageRecord: messageRecord,
            statusLabel: 'Improvising image',
            sourceAttachmentUrl: String(attachmentPayload.url || ''),
            sourcePrompt: String(attachmentPayload.ai_prompt || '')
        });
    }

    function compareMessagesByCreatedAt(left, right) {
        const leftTs = parseServerDateTimeMs(left && left.created_at ? left.created_at : '');
        const rightTs = parseServerDateTimeMs(right && right.created_at ? right.created_at : '');
        if (leftTs !== rightTs) {
            return leftTs - rightTs;
        }

        const leftId = Number(left && left.id ? left.id : 0);
        const rightId = Number(right && right.id ? right.id : 0);
        if (Number.isFinite(leftId) && Number.isFinite(rightId) && leftId !== rightId) {
            return leftId - rightId;
        }

        return 0;
    }

    function sanitizeStoredLocalAiMessage(rawMessage, fallbackChatKey = '') {
        if (!rawMessage || typeof rawMessage !== 'object') {
            return null;
        }

        const chatKey = String(rawMessage.chat_key || fallbackChatKey || '').trim();
        if (!chatKey) {
            return null;
        }

        const role = rawMessage._localAiRole === 'prompt' ? 'prompt' : 'assistant';
        const messageText = normalizeLocalAiMessageText(rawMessage.message || '');
        if (!messageText) {
            return null;
        }

        const numericId = Number(rawMessage.id);
        const safeId = Number.isFinite(numericId) && numericId < 0
            ? Math.trunc(numericId)
            : nextLocalAiMessageId();
        const groupId = isGroupChatKey(chatKey) ? (getGroupIdFromChatKey(chatKey) || null) : null;
        const createdAt = String(rawMessage.created_at || new Date().toISOString());
        const aiIdentity = getAiAssistantIdentityForChat(chatKey);
        const assistantDisplayName = String(rawMessage.sender_display_name || aiIdentity.displayName || LOCAL_AI_BOT_NAME).trim() || LOCAL_AI_BOT_NAME;
        const assistantProfilePic = normalizeProfilePic(
            String(rawMessage.sender_profile_pic || aiIdentity.profilePic || DEFAULT_AI_PROFILE_PIC).trim() || DEFAULT_AI_PROFILE_PIC,
            'direct'
        );
        const replyToId = normalizeReplyReferenceId(rawMessage.reply_to_id);
        const replyToRefId = normalizeReplyReferenceId(rawMessage.reply_to_ref_id || replyToId);

        return {
            id: safeId,
            message: messageText,
            sender_id: role === 'assistant' ? LOCAL_AI_BOT_ID : String(currentUserId),
            recipient_id: groupId ? null : chatKey,
            group_id: groupId,
            chat_key: chatKey,
            self: role === 'prompt',
            sender_display_name: role === 'assistant'
                ? assistantDisplayName
                : String(rawMessage.sender_display_name || currentUserDisplayName || 'You'),
            sender_profile_pic: role === 'assistant'
                ? assistantProfilePic
                : normalizeProfilePic(String(rawMessage.sender_profile_pic || currentUserProfilePic || defaultProfilePic), 'direct'),
            created_at: createdAt,
            reply_to_id: replyToId || null,
            reply_to_ref_id: replyToRefId || null,
            reply_to_display_name: rawMessage.reply_to_display_name || null,
            reply_to_message_body: rawMessage.reply_to_message_body || null,
            _localAiMessage: true,
            _localAiRole: role,
            _localAiPrivate: !!rawMessage._localAiPrivate
        };
    }

    function limitLocalAiThread(messages) {
        const safeMessages = Array.isArray(messages)
            ? messages.filter(Boolean).sort(compareMessagesByCreatedAt)
            : [];
        return safeMessages.slice(-1 * LOCAL_AI_MAX_MESSAGES_PER_CHAT);
    }

    function loadLocalAiThreads() {
        try {
            const raw = localStorage.getItem(LOCAL_AI_STORAGE_KEY);
            if (!raw) {
                return {};
            }

            const parsed = JSON.parse(raw);
            if (!parsed || typeof parsed !== 'object') {
                return {};
            }

            const nextThreads = {};
            Object.entries(parsed).forEach(([chatKey, messages]) => {
                if (!Array.isArray(messages)) {
                    return;
                }

                const sanitizedMessages = limitLocalAiThread(
                    messages
                        .map(message => sanitizeStoredLocalAiMessage(message, chatKey))
                        .filter(Boolean)
                );

                if (sanitizedMessages.length) {
                    nextThreads[String(chatKey)] = sanitizedMessages;
                }
            });

            return nextThreads;
        } catch (error) {
            console.warn('Failed to load local AI threads.', error);
            return {};
        }
    }

    function persistLocalAiThreads() {
        try {
            localStorage.setItem(LOCAL_AI_STORAGE_KEY, JSON.stringify(localAiThreadsCache));
        } catch (error) {
            console.warn('Failed to persist local AI threads.', error);
        }
    }

    function loadLocalAiReactions() {
        try {
            const raw = localStorage.getItem(LOCAL_AI_REACTIONS_STORAGE_KEY);
            if (!raw) {
                return {};
            }

            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (error) {
            console.warn('Failed to load local AI reactions.', error);
            return {};
        }
    }

    function persistLocalAiReactions() {
        try {
            localStorage.setItem(LOCAL_AI_REACTIONS_STORAGE_KEY, JSON.stringify(localAiReactionsCache));
        } catch (error) {
            console.warn('Failed to persist local AI reactions.', error);
        }
    }

    function buildLocalAiReactionStorageKey(chatKey, messageId) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedMessageId = String(messageId || '').trim();
        return normalizedChatKey && normalizedMessageId
            ? `${normalizedChatKey}::${normalizedMessageId}`
            : '';
    }

    function getStoredLocalAiReactionSet(chatKey, messageId) {
        const storageKey = buildLocalAiReactionStorageKey(chatKey, messageId);
        const rawValue = storageKey ? localAiReactionsCache[storageKey] : null;
        return new Set(Array.isArray(rawValue) ? rawValue.map(value => String(value || '').trim()).filter(Boolean) : []);
    }

    function buildLocalAiReactionRows(chatKey, messageId) {
        return Array.from(getStoredLocalAiReactionSet(chatKey, messageId)).map(emoji => ({
            emoji,
            cnt: 1,
            self_reacted: 1,
            reactors: 'You'
        }));
    }

    function toggleStoredLocalAiReaction(chatKey, messageId, emoji) {
        const storageKey = buildLocalAiReactionStorageKey(chatKey, messageId);
        const normalizedEmoji = String(emoji || '').trim();
        if (!storageKey || !normalizedEmoji) {
            return [];
        }

        const nextSet = getStoredLocalAiReactionSet(chatKey, messageId);
        if (nextSet.has(normalizedEmoji)) {
            nextSet.delete(normalizedEmoji);
        } else {
            nextSet.add(normalizedEmoji);
        }

        if (nextSet.size > 0) {
            localAiReactionsCache[storageKey] = Array.from(nextSet);
        } else {
            delete localAiReactionsCache[storageKey];
        }
        persistLocalAiReactions();

        return buildLocalAiReactionRows(chatKey, messageId);
    }

    function removeStoredLocalAiReactions(chatKey, messageId) {
        const storageKey = buildLocalAiReactionStorageKey(chatKey, messageId);
        if (!storageKey || !Object.prototype.hasOwnProperty.call(localAiReactionsCache, storageKey)) {
            return false;
        }

        delete localAiReactionsCache[storageKey];
        persistLocalAiReactions();
        return true;
    }

    function getStoredLocalAiMessages(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return [];
        }

        return limitLocalAiThread(localAiThreadsCache[normalizedChatKey] || []);
    }

    function storeLocalAiMessage(chatKey, message) {
        const normalizedChatKey = String(chatKey || '').trim();
        const sanitizedMessage = sanitizeStoredLocalAiMessage(message, normalizedChatKey);
        if (!normalizedChatKey || !sanitizedMessage) {
            return null;
        }

        const existingThread = getStoredLocalAiMessages(normalizedChatKey)
            .filter(existing => String(existing.id) !== String(sanitizedMessage.id));
        existingThread.push(sanitizedMessage);
        localAiThreadsCache[normalizedChatKey] = limitLocalAiThread(existingThread);
        persistLocalAiThreads();
        return sanitizedMessage;
    }

    function removeStoredLocalAiMessage(chatKey, messageId) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedMessageId = String(messageId || '').trim();
        if (!normalizedChatKey || !normalizedMessageId) {
            return false;
        }

        const existingThread = getStoredLocalAiMessages(normalizedChatKey);
        const nextThread = existingThread.filter(message => String(message && message.id ? message.id : '') !== normalizedMessageId);
        if (nextThread.length === existingThread.length) {
            return false;
        }

        if (nextThread.length) {
            localAiThreadsCache[normalizedChatKey] = limitLocalAiThread(nextThread);
        } else {
            delete localAiThreadsCache[normalizedChatKey];
        }
        persistLocalAiThreads();
        return true;
    }

    function getRenderableMessagesForChat(serverMessages, chatKey, includeLocalAi = false) {
        const safeMessages = Array.isArray(serverMessages) ? serverMessages.slice() : [];
        if (!includeLocalAi) {
            return safeMessages;
        }

        return safeMessages
            .concat(getStoredLocalAiMessages(chatKey))
            .sort(compareMessagesByCreatedAt);
    }

    function pickRandomLocalAiValue(values, fallback = '') {
        if (!Array.isArray(values) || !values.length) {
            return fallback;
        }
        return values[Math.floor(Math.random() * values.length)] || fallback;
    }

    function joinLocalAiList(values) {
        const safeValues = Array.isArray(values)
            ? values.map(value => String(value || '').trim()).filter(Boolean)
            : [];
        if (safeValues.length <= 1) {
            return safeValues[0] || '';
        }
        if (safeValues.length === 2) {
            return `${safeValues[0]} and ${safeValues[1]}`;
        }
        return `${safeValues.slice(0, -1).join(', ')}, and ${safeValues[safeValues.length - 1]}`;
    }

    function extractLocalAiKeywords(text, maxKeywords = 6) {
        const matches = String(text || '')
            .toLowerCase()
            .replace(/[^a-z0-9\s'-]/g, ' ')
            .split(/\s+/)
            .map(token => token.replace(/^'+|'+$/g, ''))
            .filter(token => token.length > 2 && !LOCAL_AI_STOPWORDS.has(token));

        return Array.from(new Set(matches)).slice(0, maxKeywords);
    }

    function detectLocalAiIntent(prompt) {
        const normalizedPrompt = String(prompt || '').trim().toLowerCase();
        if (/\b(story|poem|scene|dialogue|character|fiction|verse|monologue)\b/.test(normalizedPrompt)) {
            return 'creative';
        }
        if (/\b(reply|caption|bio|message|email|text|apology|dm|intro|introduction)\b/.test(normalizedPrompt)) {
            return 'writing';
        }
        if (/\b(list|brainstorm|ideas|plan|steps|outline|roadmap)\b/.test(normalizedPrompt)) {
            return 'brainstorm';
        }
        if (/[?]$/.test(normalizedPrompt) || /^(how|what|why|when|where|who|can|should|could|would|is|are|do|does|did)\b/.test(normalizedPrompt)) {
            return 'question';
        }
        return 'default';
    }

    function buildLocalAiTopicPhrase(keywords, prompt) {
        if (keywords.length >= 3) {
            return joinLocalAiList(keywords.slice(0, 3));
        }
        if (keywords.length) {
            return joinLocalAiList(keywords);
        }

        const fallbackPrompt = normalizeLocalAiPromptText(prompt);
        if (!fallbackPrompt) {
            return 'your idea';
        }

        return fallbackPrompt.length > 42
            ? `${fallbackPrompt.slice(0, 39)}...`
            : fallbackPrompt;
    }

    function collectLocalAiContext(chatKey) {
        const snippets = [];
        getStoredLocalAiMessages(chatKey).forEach(message => {
            const normalized = normalizeLocalAiPromptText(message.message);
            if (normalized) {
                snippets.push(normalized);
            }
        });

        return Array.from(new Set(snippets));
    }

    function buildLocalAiDraftLine(keywords, prompt) {
        const greeting = pickRandomLocalAiValue(['Hey', 'Hi', 'Quick note', 'Honestly'], 'Hey');
        const focus = keywords[0] || 'this';
        const secondary = keywords[1] || 'the tone';
        const intent = keywords[2] || 'what matters most';
        const fallbackPrompt = normalizeLocalAiPromptText(prompt).toLowerCase();
        const softener = /apology|sorry|repair|hurt/.test(fallbackPrompt)
            ? 'I want to be direct and own my part in it.'
            : pickRandomLocalAiValue([
                'I wanted to keep this simple and clear.',
                'I figured it was better to say this directly.',
                'I wanted the message to feel honest, not overworked.'
            ]);

        return `${greeting}, I want to make sure ${focus} comes through without losing ${secondary}. ${softener} My main point is ${intent}.`;
    }

    function buildLocalAiCreativeLine(keywords) {
        const subject = keywords[0] || pickRandomLocalAiValue(['rain', 'memory', 'firelight', 'quiet']);
        const detail = keywords[1] || pickRandomLocalAiValue(['a hallway', 'a window', 'the last train', 'a soft echo']);
        const motion = pickRandomLocalAiValue(['tilted toward', 'drifted through', 'folded into', 'waited inside']);
        const mood = pickRandomLocalAiValue(['warm', 'restless', 'cinematic', 'dreamy', 'sharp']);
        return `A ${mood} version could let ${subject} sit close to ${detail}, then have the scene ${motion} a small turning point.`;
    }

    function buildLocalAiActionLine(keywords, intent) {
        const actionVerb = pickRandomLocalAiValue(['tighten', 'stretch', 'clarify', 'anchor', 'shape'], 'shape');
        const focus = keywords[0] || 'the core idea';
        const secondary = keywords[1] || 'the rhythm';

        if (intent === 'brainstorm') {
            return `I'd break it into three quick lanes: ${focus}, ${secondary}, and one bolder variation that feels a little more unexpected.`;
        }

        if (intent === 'creative') {
            return `From there, keep one image doing the heavy lifting so ${focus} feels memorable instead of over-explained.`;
        }

        if (intent === 'writing') {
            return `If you want it sharper, ${actionVerb} the opening and let ${secondary} do the emotional work instead of adding extra filler.`;
        }

        return `The clearest next move is to ${actionVerb} around ${focus} first, then layer in ${secondary} once the core direction feels solid.`;
    }

    function buildLocalAiClosingLine(intent, contextSnippets) {
        const contextualCloser = contextSnippets.length
            ? pickRandomLocalAiValue([
                'I can keep building on the vibe already in this chat if you want another pass.',
                'If you want, I can push this closer to the tone the chat already has.'
            ])
            : pickRandomLocalAiValue([
                'If you want, send another /ai prompt and I can take it in a different direction.',
                'If you want another pass, I can make it softer, bolder, or more specific.'
            ]);

        if (intent === 'question') {
            return pickRandomLocalAiValue([
                'If you want, I can turn that into a shorter answer or a step-by-step version.',
                contextualCloser
            ]);
        }

        if (intent === 'creative') {
            return pickRandomLocalAiValue([
                'If you want, I can spin that into a full paragraph, poem, or short scene next.',
                contextualCloser
            ]);
        }

        return contextualCloser;
    }

    function generateLocalAiResponse(prompt, chatKey) {
        const normalizedPrompt = normalizeLocalAiPromptText(prompt);
        const keywords = extractLocalAiKeywords(normalizedPrompt);
        const intent = detectLocalAiIntent(normalizedPrompt);
        const contextSnippets = collectLocalAiContext(chatKey);
        const topicPhrase = buildLocalAiTopicPhrase(keywords, normalizedPrompt);
        const existingAssistantReplies = getStoredLocalAiMessages(chatKey).filter(message => message._localAiRole === 'assistant');
        const intro = existingAssistantReplies.length === 0
            ? "Here's a lightweight take."
            : pickRandomLocalAiValue([
                `Here's a fresh angle on ${topicPhrase}.`,
                `A quick take on ${topicPhrase}.`,
                `I'd approach ${topicPhrase} like this.`
            ], `Here's a quick take on ${topicPhrase}.`);

        if (intent === 'creative') {
            return [
                intro,
                buildLocalAiCreativeLine(keywords),
                buildLocalAiActionLine(keywords, intent),
                buildLocalAiClosingLine(intent, contextSnippets)
            ].filter(Boolean).join(' ');
        }

        if (intent === 'writing') {
            return [
                intro,
                `A clean draft for ${topicPhrase} could sound like this: "${buildLocalAiDraftLine(keywords, normalizedPrompt)}"`,
                buildLocalAiActionLine(keywords, intent),
                buildLocalAiClosingLine(intent, contextSnippets)
            ].filter(Boolean).join(' ');
        }

        if (intent === 'brainstorm') {
            return [
                intro,
                `The strongest thread I see is ${topicPhrase}.`,
                buildLocalAiActionLine(keywords, intent),
                buildLocalAiClosingLine(intent, contextSnippets)
            ].filter(Boolean).join(' ');
        }

        if (intent === 'question') {
            return [
                intro,
                `My short answer is to focus on ${topicPhrase} before you worry about polishing everything else.`,
                buildLocalAiActionLine(keywords, intent),
                buildLocalAiClosingLine(intent, contextSnippets)
            ].filter(Boolean).join(' ');
        }

        return [
            intro,
            `I'd start with ${topicPhrase} and keep the first version simple enough that you can react to it quickly.`,
            buildLocalAiActionLine(keywords, intent),
            buildLocalAiClosingLine(intent, contextSnippets)
        ].filter(Boolean).join(' ');
    }

    function createLocalAiMessage(chatKey, role, text) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return null;
        }

        const normalizedRole = role === 'prompt' ? 'prompt' : 'assistant';
        const normalizedMessage = normalizeLocalAiMessageText(text);
        if (!normalizedMessage) {
            return null;
        }

        const groupId = isGroupChatKey(normalizedChatKey)
            ? (getGroupIdFromChatKey(normalizedChatKey) || null)
            : null;
        const aiIdentity = getAiAssistantIdentityForChat(normalizedChatKey);

        return sanitizeStoredLocalAiMessage({
            id: nextLocalAiMessageId(),
            message: normalizedMessage,
            sender_id: normalizedRole === 'assistant' ? LOCAL_AI_BOT_ID : String(currentUserId),
            recipient_id: groupId ? null : normalizedChatKey,
            group_id: groupId,
            chat_key: normalizedChatKey,
            self: normalizedRole === 'prompt',
            sender_display_name: normalizedRole === 'assistant' 
                ? aiIdentity.displayName
                : currentUserDisplayName,
            sender_profile_pic: normalizedRole === 'assistant' ? aiIdentity.profilePic : currentUserProfilePic,
            created_at: new Date().toISOString(),
            _localAiMessage: true,
            _localAiRole: normalizedRole,
            _localAiPrivate: false // Default to public, will be overridden if needed
        }, normalizedChatKey);
    }

    function appendLocalAiMessageToActiveChat(message, { scrollToBottom = true } = {}) {
        if (!message) {
            return;
        }

        const messageChatKey = String(getMessageChatKey(message) || message.chat_key || '').trim();
        if (!messageChatKey || String(selectedUser || '') !== messageChatKey) {
            return;
        }

        appendMessage(message, false);
        if (scrollToBottom) {
            scrollChatToBottomAfterSend();
        }
    }

    async function queueLocalAiReply(chatKey, prompt, options = {}) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedPrompt = normalizeLocalAiPromptText(prompt);
        const normalizedOptions = typeof options === 'boolean'
            ? { isPublicCommand: options }
            : (options && typeof options === 'object' ? options : {});
        const isPublicCommand = !!normalizedOptions.isPublicCommand;
        const isPrivateCommand = !!normalizedOptions.isPrivateCommand;
        const reactionTargetMessageId = Number(normalizedOptions.reactionTargetMessageId || 0);
        const parsedOriginMessageId = Number(normalizedOptions.originMessageId || 0);
        const originMessageId = Number.isFinite(parsedOriginMessageId) ? Math.trunc(parsedOriginMessageId) : 0;
        const originUserId = Math.max(0, Number(normalizedOptions.originUserId || 0) || 0);
        if (!normalizedChatKey || !normalizedPrompt) {
            return;
        }
        const originReplyReference = normalizeReplyReference(normalizedOptions.replyReference) || normalizeReplyReference({
            id: originMessageId,
            name: normalizedOptions.originDisplayName || (originUserId && String(originUserId) !== String(currentUserId) ? getDisplayNameForUser(String(originUserId)) : 'You'),
            message: normalizedOptions.originMessageBody || normalizedOptions.originMessage || normalizedPrompt
        });

        const replyStartedAt = Number(normalizedOptions.replyStartedAt || 0) > 0
            ? Number(normalizedOptions.replyStartedAt)
            : Date.now();
        const aiTypingIndicatorKey = String(normalizedOptions.typingIndicatorKey || '').trim()
            || (String(selectedUser || '') === normalizedChatKey
                ? showAiTypingIndicator(normalizedChatKey)
                : '');
        const aiReplyDelayMs = LOCAL_AI_REPLY_MIN_DELAY_MS
            + Math.floor(Math.random() * ((LOCAL_AI_REPLY_MAX_DELAY_MS - LOCAL_AI_REPLY_MIN_DELAY_MS) + 1));
        let aiTypingIndicatorHidden = false;
        const waitForMinimumAiReplyDelay = async () => {
            const elapsed = Date.now() - replyStartedAt;
            const remaining = aiReplyDelayMs - elapsed;
            if (remaining > 0) {
                await new Promise(resolve => window.setTimeout(resolve, remaining));
            }
        };
        const finishAiTypingIndicator = () => {
            if (aiTypingIndicatorHidden) {
                return;
            }
            aiTypingIndicatorHidden = true;
            hideTypingIndicatorByKey(aiTypingIndicatorKey);
        };

        try {
            // Collect context from recent messages
            const contextSnippets = collectLocalAiContext(normalizedChatKey);
            const appendContextSnippets = values => {
                if (!Array.isArray(values)) {
                    return;
                }
                values.forEach(value => {
                    const normalizedValue = normalizeLocalAiMessageText(value);
                    if (!normalizedValue || contextSnippets.includes(normalizedValue)) {
                        return;
                    }
                    contextSnippets.push(normalizedValue);
                });
            };
            appendContextSnippets(normalizedOptions.contextLines);
            
            // Check if this is an AI chat
            const isAiChat = normalizedChatKey.startsWith('ai:');
            const aiChatId = isAiChat && window.aiChatsMap && window.aiChatsMap[normalizedChatKey]
                ? window.aiChatsMap[normalizedChatKey].id
                : 0;
            
            // Get chat label for context
            let chatLabel = isGroupChatKey(normalizedChatKey) 
                ? (groupNamesMap[normalizedChatKey] || 'Group Chat')
                : (getDisplayNameForUser(normalizedChatKey) || 'Chat');

            if (isAiChat) {
                const aiContext = await resolveAiChatSupplementalContext(normalizedChatKey);
                if (aiContext) {
                    appendContextSnippets(aiContext.contextLines);
                    if (aiContext.chatLabel) {
                        chatLabel = aiContext.chatLabel;
                    }
                }
            }

            // Call the AI API (Groq-backed)
            const response = await fetch('ai_chat.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token: token,
                    prompt: normalizedPrompt,
                    chat_key: normalizedChatKey,
                    chat_label: chatLabel,
                    ai_chat_id: aiChatId,
                    context: contextSnippets,
                    allow_reaction: reactionTargetMessageId > 0
                })
            });

            const data = await response.json();

            if (!data.success) {
                throw new Error(data.error || 'AI request failed');
            }

            const aiMessage = data.message;
            const aiReaction = typeof data.reaction === 'string' ? data.reaction.trim() : '';
            await waitForMinimumAiReplyDelay();
            
                if (isAiChat && aiChatId > 0) {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('ai_chat_key', normalizedChatKey);
                formData.append('message', aiMessage);
                formData.append('sender_type', 'ai');
                // Only send reply_to_id if it's a valid positive ID
                if (originMessageId > 0) {
                    formData.append('reply_to_id', String(originMessageId));
                }
                
                const saveResponse = await fetch('send_ai_message.php', {
                    method: 'POST',
                    body: formData
                });
                
                const saveData = await saveResponse.json();
                
                if (saveData.success && saveData.message) {
                    applyReplyReferenceToMessage(saveData.message, originReplyReference);
                    finishAiTypingIndicator();
                    // Append the AI message to the chat
                    if (selectedUser === normalizedChatKey) {
                        appendMessage(saveData.message);
                        lastId = Math.max(Number(lastId || 0), Number(saveData.message.id || 0));
                        scrollChatToBottomAfterSend();
                    }
                    // Update contact preview with AI response (don't promote to top unless active)
                    if (typeof updateContactPreview === 'function') {
                        const shouldPromote = selectedUser === normalizedChatKey;
                        updateContactPreview(normalizedChatKey, saveData.message, shouldPromote);
                    }
                    if (aiReaction && reactionTargetMessageId > 0) {
                        applyAiReactionToMessage(reactionTargetMessageId, aiReaction, normalizedChatKey).catch(error => {
                            console.warn('Failed to apply AI chat reaction.', error);
                        });
                    }
                } else {
                    console.error('Failed to save AI response:', saveData.error);
                }
            } else if (isPublicCommand && !isAiChat) {
                // For public AI commands in regular chats, send AI response to server
                try {
                    console.log('[AI DEBUG] Preparing to send AI response to server');
                    console.log('[AI DEBUG] Chat key:', normalizedChatKey);
                    console.log('[AI DEBUG] AI message length:', aiMessage.length);
                    
                    const formData = new FormData();
                    formData.append('token', token);
                    formData.append('message', aiMessage);
                    formData.append('sender_display_name', 'QuillTalk AI');
                    formData.append('is_ai_response', '1');
                    formData.append('original_user_id', String(originUserId > 0 ? originUserId : currentUserId));
                    if (originMessageId > 0) {
                        formData.append('origin_message_id', String(originMessageId));
                    }
                    if (originMessageId > 0 && isGroupChatKey(normalizedChatKey)) {
                        // Only send reply_to_id if it's a valid positive ID
                        formData.append('reply_to_id', String(originMessageId));
                    }

                    const normalizedCurrentUserId = String(currentUserId || '').trim();
                    const publicAiRecipientKey = !isGroupChatKey(normalizedChatKey) && originUserId > 0
                        ? (String(originUserId) === normalizedCurrentUserId
                            ? normalizedChatKey
                            : normalizedCurrentUserId)
                        : normalizedChatKey;
                    formData.append('recipient_id', publicAiRecipientKey);

                    if (isGroupChatKey(normalizedChatKey)) {
                        console.log('[AI DEBUG] Sending to group:', normalizedChatKey);
                    } else {
                        console.log('[AI DEBUG] Sending to user:', publicAiRecipientKey);
                    }

                    console.log('[AI DEBUG] Making request to send_message.php');
                    
                    // Create timeout promise
                    const timeoutPromise = new Promise((_, reject) => {
                        setTimeout(() => reject(new Error('Request timeout after 30 seconds')), 30000);
                    });
                    
                    const fetchPromise = fetch('send_message.php', {
                        method: 'POST',
                        body: formData
                    });
                    
                    const aiResponse = await Promise.race([fetchPromise, timeoutPromise]);

                    console.log('[AI DEBUG] Response status:', aiResponse.status);
                    console.log('[AI DEBUG] Response ok:', aiResponse.ok);

                    if (!aiResponse.ok) {
                        const responseText = await aiResponse.text();
                        console.error('[AI DEBUG] Response error text:', responseText);
                        throw new Error(`HTTP ${aiResponse.status}: ${responseText}`);
                    }

                    const aiData = await aiResponse.json();
                    console.log('[AI DEBUG] Response data:', aiData);
                    
                    if (!aiData.success) {
                        throw new Error(aiData.error || 'Failed to send AI response');
                    }
                    
                    console.log('[AI DEBUG] AI response sent successfully');
                    if (aiData.message) {
                        applyReplyReferenceToMessage(aiData.message, originReplyReference);
                    }
                    
                    // Add the AI message to the chat immediately
                    if (selectedUser === normalizedChatKey && aiData.message) {
                        finishAiTypingIndicator();
                        console.log('[AI DEBUG] Adding AI message to chat');
                        appendMessage(aiData.message);
                        lastId = Math.max(Number(lastId || 0), Number(aiData.message.id || 0));
                        scrollChatToBottomAfterSend();
                        
                        // Update contact preview (don't promote to top unless it's the active chat)
                        if (typeof updateContactPreview === 'function') {
                            const shouldPromote = selectedUser === normalizedChatKey;
                            updateContactPreview(normalizedChatKey, aiData.message, shouldPromote);
                        }
                    }
                    if (aiReaction && reactionTargetMessageId > 0) {
                        applyAiReactionToMessage(reactionTargetMessageId, aiReaction, normalizedChatKey).catch(error => {
                            console.warn('Failed to apply AI reaction.', error);
                        });
                    }
                } catch (error) {
                    console.error('Failed to send public AI response:', error);
                    console.error('Error details:', {
                        message: error.message,
                        chatKey: normalizedChatKey,
                        aiMessage: aiMessage.substring(0, 100) + '...'
                    });
                    
                    // Don't show error toast for group chats to avoid confusion
                    if (!isGroupChatKey(normalizedChatKey)) {
                        showToast('Failed to send AI response: ' + error.message, 'error');
                    }
                    
                }
            } else {
                // For old local AI system (private commands)
                finishAiTypingIndicator();
                const replyMessage = createLocalAiMessage(
                    normalizedChatKey,
                    'assistant',
                    aiMessage
                );
                if (replyMessage && isPrivateCommand) {
                    replyMessage._localAiPrivate = true;
                }
                applyReplyReferenceToMessage(replyMessage, originReplyReference);

                const storedReply = storeLocalAiMessage(normalizedChatKey, replyMessage);
                if (!storedReply) {
                    return;
                }

                appendLocalAiMessageToActiveChat(storedReply, { scrollToBottom: true });
            }
            
        } catch (error) {
            console.error('AI error:', error);
            showToast('AI unavailable: ' + error.message, 'error');
        } finally {
            finishAiTypingIndicator();
        }
    }

    function parseComposerAiCommand(text) {
        const normalizedText = String(text || '').trim();

        const privateImagineMatch = normalizedText.match(/^\/ai\s+private\s+imagine(?:\s+([\s\S]*))?$/i);
        if (privateImagineMatch) {
            return {
                prompt: normalizeLocalAiMessageText(privateImagineMatch[1] || ''),
                isPrivate: true,
                mode: 'image'
            };
        }

        const publicImagineMatch = normalizedText.match(/^\/ai\s+imagine(?:\s+([\s\S]*))?$/i);
        if (publicImagineMatch) {
            return {
                prompt: normalizeLocalAiMessageText(publicImagineMatch[1] || ''),
                isPrivate: false,
                mode: 'image'
            };
        }
        
        // Check for /ai private command first (more specific)
        const privateMatch = normalizedText.match(/^\/ai\s+private(?:\s+([\s\S]*))?$/i);
        if (privateMatch) {
            return {
                prompt: normalizeLocalAiMessageText(privateMatch[1] || ''),
                isPrivate: true,
                mode: 'text'
            };
        }
        
        // Check for regular /ai command
        const publicMatch = normalizedText.match(/^\/ai(?:\s+([\s\S]*))?$/i);
        if (publicMatch) {
            return {
                prompt: normalizeLocalAiMessageText(publicMatch[1] || ''),
                isPrivate: false,
                mode: 'text'
            };
        }

        return null;
    }

    function getCurrentUserDisplayName() {
        return currentUserDisplayName || currentUsername || 'You';
    }

    function shouldTriggerQuillTalkAiResponse(messageText, replyContext = null) {
        const normalizedText = String(messageText || '').trim();
        if (!normalizedText) {
            return false;
        }

        return messageMentionsQuillTalkAi(normalizedText)
            || !!(replyContext && replyContext.isAi)
            || messageRepliesToQuillTalkAi(replyContext);
    }

    function getQuillTalkAiPromptFromMessage(messageText) {
        return normalizeLocalAiPromptText(normalizeQuillTalkAiPromptText(messageText));
    }

    async function triggerQuillTalkAiResponseForMessage(chatKey, messageText, originMessageId, originUserId = 0, originDisplayName = '', originMessageBody = '') {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedOriginMessageId = Math.max(0, Number(originMessageId || 0) || 0);
        const normalizedPrompt = getQuillTalkAiPromptFromMessage(messageText);
        
        console.log('[QuillTalk AI Trigger] Called with:', {
            normalizedChatKey,
            normalizedOriginMessageId,
            normalizedPrompt,
            messageText: messageText.substring(0, 100)
        });
        
        if (!normalizedChatKey || normalizedChatKey.startsWith('ai:') || !normalizedOriginMessageId || !normalizedPrompt) {
            console.log('[QuillTalk AI Trigger] Returning early - missing required fields', {
                noChat: !normalizedChatKey,
                isAiChat: normalizedChatKey.startsWith('ai:'),
                noMessageId: !normalizedOriginMessageId,
                noPrompt: !normalizedPrompt
            });
            return;
        }

        // Show AI typing indicator if this is the active chat
        let aiTypingIndicatorKey = '';
        if (String(selectedUser || '') === normalizedChatKey || normalizedChatKey.startsWith('ai:')) {
            aiTypingIndicatorKey = showAiTypingIndicator(normalizedChatKey);
        }

        const aiImagePrompt = extractAiImageIntentPrompt(normalizedPrompt);
        if (aiImagePrompt) {
            await requestAiGeneratedImage(normalizedChatKey, aiImagePrompt, {
                mode: 'public',
                originMessageId: normalizedOriginMessageId
            }).catch(error => {
                console.error('Failed to generate AI image:', error);
                if (aiTypingIndicatorKey) hideTypingIndicatorByKey(aiTypingIndicatorKey);
            });
            return;
        }

        // Pass typing indicator key to show it while AI is processing
        const replyStartedAt = Date.now();
        await queueLocalAiReply(normalizedChatKey, normalizedPrompt, {
            isPublicCommand: true,
            reactionTargetMessageId: normalizedOriginMessageId,
            originMessageId: normalizedOriginMessageId,
            originUserId: Math.max(0, Number(originUserId || currentUserId || 0) || 0),
            originDisplayName: originDisplayName || (String(originUserId || '') === String(currentUserId || '') ? 'You' : ''),
            originMessageBody: originMessageBody || messageText,
            typingIndicatorKey: aiTypingIndicatorKey,
            replyStartedAt: replyStartedAt
        }).catch(error => {
            console.error('[QuillTalk AI] Failed to queue reply:', error);
            if (aiTypingIndicatorKey) hideTypingIndicatorByKey(aiTypingIndicatorKey);
        });
    }

    async function handleComposerAiCommand(chatKey, aiCommand) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedPrompt = normalizeLocalAiPromptText(aiCommand.prompt);
        const isPrivate = aiCommand.isPrivate || false;
        const isAiChat = normalizedChatKey.startsWith('ai:');
        const aiCommandMode = String(aiCommand.mode || 'text').trim().toLowerCase() === 'image' ? 'image' : 'text';

        if (!normalizedChatKey) {
            showToast('Please select a chat first', 'error');
            return false;
        }

        if (!normalizedPrompt) {
            showToast(aiCommandMode === 'image' ? 'Type /ai imagine followed by a prompt.' : 'Type /ai followed by a prompt.', 'error');
            return false;
        }

        if (pendingAttachmentFile || pendingGifAttachments.length || pendingTableDraft) {
            showToast(aiCommandMode === 'image'
                ? 'Send the image command on its own so it can work cleanly.'
                : 'That AI command only supports text prompts right now.', 'error');
            return false;
        }

        // Create the AI command message with privacy indicator
        const commandIndicator = aiCommandMode === 'image'
            ? (isPrivate ? 'You used /ai privately imagine' : 'You used /ai imagine')
            : (isPrivate ? 'You used /ai privately' : 'You used /ai');
        const fullMessage = `${commandIndicator}\n\n${normalizedPrompt}`;

        if (isPrivate) {
            // Private AI commands: Store locally only
            const promptMessage = createLocalAiMessage(normalizedChatKey, 'prompt', fullMessage);
            if (promptMessage) {
                promptMessage._localAiPrivate = isPrivate;
            }
            
            const storedPromptMessage = storeLocalAiMessage(normalizedChatKey, promptMessage);
            if (!storedPromptMessage) {
                showToast('Could not start the AI reply.', 'error');
                return false;
            }

            appendLocalAiMessageToActiveChat(storedPromptMessage, { scrollToBottom: true });
            clearComposerAfterSend(normalizedChatKey, true);
            if (aiCommandMode === 'image') {
                requestAiGeneratedImage(normalizedChatKey, normalizedPrompt, { mode: 'private' }).catch(error => {
                    console.error('Private AI image generation failed.', error);
                    showToast(error && error.message ? error.message : 'Could not generate that image.', 'error');
                });
            } else {
                queueLocalAiReply(normalizedChatKey, normalizedPrompt, {
                    isPublicCommand: false,
                    isPrivateCommand: true,
                    originMessageId: storedPromptMessage.id,
                    originDisplayName: 'You',
                    originMessageBody: fullMessage
                }).catch(error => {
                    console.error('Local AI reply failed.', error);
                    showToast('The AI reply hit an error.', 'error');
                });
            }
        } else {
            // Public AI commands: Send to server so others can see
            const publicAiReplyStartedAt = Date.now();
            const initialAiTypingIndicatorKey = aiCommandMode === 'text' && !isPrivate && String(selectedUser || '') === normalizedChatKey
                ? showAiTypingIndicator(normalizedChatKey)
                : '';
            try {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('message', fullMessage);

                if (isAiChat) {
                    formData.append('ai_chat_key', normalizedChatKey);
                } else {
                    formData.append('recipient_id', normalizedChatKey);
                }

                const res = await fetch(isAiChat ? 'send_ai_message.php' : 'send_message.php', {
                    method: 'POST',
                    body: formData
                });
                const rawResponseText = await res.text();
                let data = {};
                if (rawResponseText) {
                    try {
                        data = JSON.parse(rawResponseText);
                    } catch (error) {
                        data = {};
                    }
                }
                if (!res.ok || !data.success) {
                    const nestedErrorMessage = data && typeof data.error === 'object' && data.error && typeof data.error.message === 'string'
                        ? data.error.message
                        : '';
                    const rawFallbackMessage = rawResponseText
                        ? rawResponseText.trim().replace(/\s+/g, ' ').slice(0, 220)
                        : '';
                    const emptyServerFailureMessage = !rawFallbackMessage && res.status >= 500
                        ? 'The AI command endpoint crashed before it could finish.'
                        : '';
                    throw new Error(
                        (typeof data.error === 'string' && data.error)
                        || nestedErrorMessage
                        || emptyServerFailureMessage
                        || rawFallbackMessage
                        || `HTTP ${res.status}`
                    );
                }

                if (data.message && String(selectedUser || '') === normalizedChatKey) {
                    handleSuccessfulOutgoingNewMessage(data, null, normalizedChatKey);
                } else if (data.message && typeof updateContactPreview === 'function') {
                    updateContactPreview(normalizedChatKey, data.message, true);
                }

                clearComposerAfterSend(normalizedChatKey, true, { preserveTypingIndicator: !!initialAiTypingIndicatorKey });
                const originMessageId = Number(data.message && data.message.id ? data.message.id : 0);

                if (aiCommandMode === 'image') {
                    requestAiGeneratedImage(normalizedChatKey, normalizedPrompt, {
                        mode: isAiChat ? 'ai_chat' : 'public',
                        originMessageId
                    }).catch(error => {
                        console.error('Public AI image generation failed.', error);
                        showToast(error && error.message ? error.message : 'Could not generate that image.', 'error');
                    });
                } else {
                    queueLocalAiReply(normalizedChatKey, normalizedPrompt, {
                        isPublicCommand: true,
                        reactionTargetMessageId: originMessageId,
                        originMessageId,
                        originUserId: Number(currentUserId || 0),
                        originDisplayName: 'You',
                        originMessageBody: fullMessage,
                        replyStartedAt: publicAiReplyStartedAt,
                        typingIndicatorKey: initialAiTypingIndicatorKey
                    }).catch(error => {
                        console.error('Local AI reply failed.', error);
                        showToast('The AI reply hit an error.', 'error');
                    });
                }
                
            } catch (error) {
                hideTypingIndicatorByKey(initialAiTypingIndicatorKey);
                console.error('Failed to send public AI command:', error);
                showToast(error && error.message ? error.message : 'Failed to send AI command. Please try again.', 'error');
                return false;
            }
        }
        
        return true;
    }

    function applyLocalChatNicknameUpdate(chatKey, userId, nickname) {
        const normalizedChatKey = String(chatKey || '').trim();
        const normalizedUserId = String(userId || '').trim();
        const normalizedNickname = rememberChatNickname(normalizedChatKey, normalizedUserId, nickname);

        if (!normalizedChatKey || !normalizedUserId) {
            return normalizedNickname;
        }

        const contactEl = getContactElement(normalizedChatKey);
        if (contactEl && normalizedUserId === String(currentUserId)) {
            contactEl.dataset.viewerChatNickname = normalizedNickname;
        }
        if (contactEl && !isGroupChatKey(normalizedChatKey) && normalizedUserId === normalizedChatKey) {
            contactEl.dataset.chatNickname = normalizedNickname;
        }

        const members = groupMembersMap[normalizedChatKey];
        if (Array.isArray(members)) {
            members.forEach(member => {
                const memberId = String(member.user_id || member.id || '');
                if (memberId === normalizedUserId) {
                    member.chat_nickname = normalizedNickname;
                }
            });
        }

        return normalizedNickname;
    }

    async function setChatNicknameForCurrentUser(chatKey, nickname) {
        const normalizedChatKey = String(chatKey || '').trim();
        const res = await fetch('set_chat_nickname.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                token,
                chat_key: normalizedChatKey,
                nickname: normalizeChatScopedNicknameValue(nickname)
            })
        });
        const data = await res.json().catch(() => ({}));

        if (!res.ok || !data.success) {
            throw new Error(data.error || 'Could not save chat nickname.');
        }

        const resolvedChatKey = String(data.chat_key || normalizedChatKey);
        applyLocalChatNicknameUpdate(resolvedChatKey, currentUserId, data.nickname || '');

        if (selectedUser && String(selectedUser) === resolvedChatKey && isGroupChatKey(resolvedChatKey)) {
            renderGroupMembersList(resolvedChatKey);
            if (groupMembersModal && groupMembersModal.classList.contains('open')) {
                renderGroupMembersModalList(resolvedChatKey);
            }
            if (activeGroupSettingsChatKey && String(activeGroupSettingsChatKey) === resolvedChatKey) {
                renderGroupSettingsMembersList(resolvedChatKey);
            }
        }
        refreshOpenProfileViews(currentUserId);
        refreshOpenProfileViewsForChatContext(resolvedChatKey);

        return data;
    }

    function getChatNicknameToastMessage(nickname) {
        const normalizedNickname = normalizeChatScopedNicknameValue(nickname);
        return normalizedNickname
            ? `Chat nickname set to ${normalizedNickname}`
            : 'Chat nickname cleared';
    }

    async function saveChatNicknameForCurrentUser(chatKey, nickname, options = {}) {
        const normalizedNickname = normalizeChatScopedNicknameValue(nickname);
        const data = await setChatNicknameForCurrentUser(chatKey, normalizedNickname);

        if (!options.silent) {
            showToast(getChatNicknameToastMessage(normalizedNickname), 'success');
        }

        return data;
    }

    function maybeHandleComposerGifShortcut() {
        if (!messageInput || !selectedUser) {
            return false;
        }

        if (String(messageInput.value || '').trim().toLowerCase() !== '/gif') {
            return false;
        }

        if (isVoiceRecordingActive()) {
            showToast('Finish recording the voice message first.', 'error');
            return false;
        }

        messageInput.value = '';
        closeCommandPicker();
        closeMentionPicker();
        hideEmojiPicker();
        updateComposerHighlightOverlay();
        setComposerDraft(selectedUser, '');
        clearDraftPreview(selectedUser, false);
        updateDraftPreview();
        openGifModal();
        return true;
    }

    async function startVoiceRecording() {
        if (!selectedUser) {
            alert('Select a contact or accept a friend request first.');
            return;
        }

        if (typeof MediaRecorder === 'undefined') {
            alert('Voice messages are not supported in this browser.');
            return;
        }

        clearPendingAttachment(true);

        try {
            voiceRecordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            voiceRecordingChunks = [];
            voiceRecordingSampleLevels = [];
            discardVoiceRecording = false;
            voiceRecordingMimeType = getVoiceRecordingMimeType();
            voiceMediaRecorder = voiceRecordingMimeType
                ? new MediaRecorder(voiceRecordingStream, { mimeType: voiceRecordingMimeType })
                : new MediaRecorder(voiceRecordingStream);
            startVoiceRecordingAnalysis(voiceRecordingStream);

            voiceMediaRecorder.ondataavailable = (event) => {
                if (event.data && event.data.size > 0) {
                    voiceRecordingChunks.push(event.data);
                }
            };

            voiceMediaRecorder.onstop = () => {
                const shouldDiscard = discardVoiceRecording;
                const chunks = voiceRecordingChunks.slice();
                const waveformSamples = voiceRecordingSampleLevels.slice();
                const durationSeconds = voiceRecordingStartedAt
                    ? ((Date.now() - voiceRecordingStartedAt) / 1000)
                    : 0;
                const mimeType = voiceMediaRecorder && voiceMediaRecorder.mimeType
                    ? voiceMediaRecorder.mimeType
                    : (voiceRecordingMimeType || 'audio/webm');

                voiceMediaRecorder = null;
                voiceRecordingChunks = [];
                voiceRecordingSampleLevels = [];
                voiceRecordingStartedAt = 0;
                voiceRecordingMimeType = '';
                discardVoiceRecording = false;
                stopVoiceRecordingStream();
                updateVoiceRecordButton();

                if (shouldDiscard || chunks.length === 0) {
                    return;
                }

                const blob = new Blob(chunks, { type: mimeType });
                const extension = getVoiceRecordingExtension(mimeType);
                const file = new File([blob], `voice-message-${Date.now()}.${extension}`, { type: mimeType });
                showPendingAttachment(file, buildVoiceRecordingMeta(durationSeconds, waveformSamples));
            };

            voiceMediaRecorder.onerror = (event) => {
                console.error('Voice recording error:', event.error || event);
                discardVoiceRecording = true;
                clearPendingAttachment(true);
                stopVoiceRecordingStream();
                voiceMediaRecorder = null;
                voiceRecordingChunks = [];
                voiceRecordingSampleLevels = [];
                voiceRecordingStartedAt = 0;
                voiceRecordingMimeType = '';
                updateVoiceRecordButton();
                alert('Could not record a voice message.');
            };

            voiceMediaRecorder.start();
            updateVoiceRecordButton();
            showRecordingPreview();
        } catch (e) {
            console.error('Voice recording start failed:', e);
            stopVoiceRecordingStream();
            voiceMediaRecorder = null;
            voiceRecordingChunks = [];
            voiceRecordingSampleLevels = [];
            voiceRecordingStartedAt = 0;
            voiceRecordingMimeType = '';
            discardVoiceRecording = false;
            updateVoiceRecordButton();
            alert('Microphone access is required to record a voice message.');
        }
    }

    if (attachmentBtn) {
        attachmentBtn.addEventListener('mousedown', event => {
            if (!isMobileViewport() || !messageInput || !isMessageInputFocused()) {
                return;
            }
            event.preventDefault();
            rememberMessageSelection();
        });
        attachmentBtn.addEventListener('click', (event) => {
            if (!selectedUser) {
                event.preventDefault();
                alert('Select a contact or accept a friend request first.');
                return;
            }
            if (isLiveVoiceTranscriptionActive()) {
                event.preventDefault();
                showToast('Stop live transcription before sending another attachment.', 'error');
                return;
            }
            if (isVoiceRecordingActive()) {
                event.preventDefault();
                alert('Finish recording the voice message first.');
                return;
            }
            try {
                attachmentInput.value = '';
            } catch (error) {
                console.warn('Unable to reset attachment input before opening picker.', error);
            }
        });
    }

    if (voiceRecordBtn) {
        voiceRecordBtn.addEventListener('mousedown', event => {
            if (!isMobileViewport() || !messageInput || !isMessageInputFocused()) {
                return;
            }
            event.preventDefault();
            rememberMessageSelection();
        });
        voiceRecordBtn.addEventListener('click', async () => {
            if (isVoiceRecordingActive()) {
                try {
                    voiceMediaRecorder.stop();
                } catch (e) {
                    console.warn('Unable to stop voice recording.', e);
                }
                return;
            }

            if (isLiveVoiceTranscriptionActive()) {
                stopLiveVoiceTranscription({ discardTranscript: false });
                return;
            }

            if (!selectedUser) {
                showToast('Select a contact or accept a friend request first.', 'error');
                return;
            }

            toggleVoiceActionMenu();
            focusMessageInputPreservingSelection();
        });
    }

    if (voiceActionMenu) {
        Array.from(voiceActionMenu.querySelectorAll('[data-voice-action]')).forEach(item => {
            addTapAndClickListener(item, async event => {
                event.preventDefault();
                event.stopPropagation();
                const action = item.dataset.voiceAction;
                closeVoiceActionMenu();
                if (action === 'transcribe') {
                    await startLiveVoiceTranscription();
                    return;
                }
                await startVoiceRecording();
            });
        });
    }

    document.addEventListener('click', event => {
        if (!voiceActionMenu || !voiceActionMenu.classList.contains('is-open')) {
            return;
        }

        const target = event.target;
        if (voiceActionMenu.contains(target) || (voiceRecordBtn && voiceRecordBtn.contains(target))) {
            return;
        }

        closeVoiceActionMenu();
    });

    document.addEventListener('keydown', event => {
        if (event.key === 'Escape') {
            closeVoiceActionMenu();
        }
    });

    if (attachmentInput) {
        attachmentInput.addEventListener('change', () => {
            const file = attachmentInput.files && attachmentInput.files[0];
            if (file) {
                showPendingAttachment(file);
            }
        });
    }

    if (sendBtn && chatForm) {
        sendBtn.addEventListener('mousedown', event => {
            event.preventDefault();
            rememberMessageSelection();
        });
        addTapAndClickListener(sendBtn, () => {
            rememberMessageSelection();
            activateComposerKeyboard({ collapseActions: false });
            focusMessageInputPreservingSelection();
            if (typeof chatForm.requestSubmit === 'function') {
                chatForm.requestSubmit(sendBtn);
            } else {
                chatForm.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
            }
        });
    }

    let isSubmitting = false; // Flag to prevent duplicate submissions
    
    if (chatForm) {
        chatForm.onsubmit = async (e) => {
            e.preventDefault();
            
            // Prevent duplicate submissions
            if (isSubmitting) {
                console.log('Message send already in progress, ignoring duplicate submit');
                return;
            }

            if (isLiveVoiceTranscriptionActive()) {
                showToast('Tap the microphone again to stop transcribing first.', 'error');
                return;
            }
            
            if (!selectedUser) return alert('Select a contact or accept a friend request first.');
            const rawComposerText = messageInput ? String(messageInput.value || '') : '';
            const msgText = rawComposerText.trim(); // Renamed to msgText to avoid confusion
            const nicknameCommand = parseComposerNicknameCommand(rawComposerText);
            if (nicknameCommand && !pendingAttachmentFile && !pendingGifAttachments.length && !pendingTableDraft) {
                isSubmitting = true;
                try {
                    await saveChatNicknameForCurrentUser(selectedUser, nicknameCommand.nickname);
                    clearComposerAfterSend(selectedUser, true);
                } catch (error) {
                    console.error('Failed to save chat nickname:', error);
                    showToast(error && error.message ? error.message : 'Could not save chat nickname.', 'error');
                } finally {
                    isSubmitting = false;
                }
                return;
            }
            const aiCommand = parseComposerAiCommand(rawComposerText);
            if (aiCommand && !pendingAttachmentFile && !pendingGifAttachments.length && !pendingTableDraft) {
                if (isVoiceRecordingActive()) {
                    alert('Tap the microphone again to finish recording before sending.');
                    return;
                }
                isSubmitting = true;
                try {
                    await handleComposerAiCommand(selectedUser, aiCommand);
                } finally {
                    isSubmitting = false;
                }
                return;
            }
            if (isConversationBlocked(selectedUser)) {
                updateBlockedChatUi(selectedUser);
                alert(getBlockedMessageError(selectedUser));
                return;
            }
            if (isVoiceRecordingActive()) {
                alert('Tap the microphone again to finish recording before sending.');
                return;
            }
            if (!msgText && !pendingAttachmentFile && !pendingGifAttachments.length && !pendingTableDraft) return;
            
            // Replace emoji shortcodes with actual emojis
            const processedText = msgText ? replaceShortcodesWithEmoji(msgText) : '';
            const tableDraftToSend = pendingTableDraft ? normalizeTableMessagePayload(pendingTableDraft) : null;
            const structuredTableMessage = tableDraftToSend ? buildTableMessageString(tableDraftToSend, processedText) : '';
            
            // Set flag to prevent duplicate submissions
            isSubmitting = true;

        if (pendingGifAttachments.length) {
            if (getAppSetting('confirmMediaSends')) {
                const prompt = pendingGifAttachments.length > 1
                    ? `Send these ${pendingGifAttachments.length} GIFs?`
                    : 'Send this GIF?';
                if (!window.confirm(prompt)) {
                    isSubmitting = false;
                    return;
                }
            }

            renderPendingGifAttachmentPreview();

            try {
                await sendPendingGifQueue(processedText);
                isSubmitting = false;
            } catch (error) {
                console.error('Unable to send selected GIFs:', error);
                renderPendingGifAttachmentPreview();
                alert(error && error.message ? error.message : 'Could not send GIFs right now.');
                isSubmitting = false;
            }
            return;
        }

        const attachmentFileToSend = pendingAttachmentFile;
        if (attachmentFileToSend) {
            const isVoiceAttachment = !!(attachmentFileToSend.type && attachmentFileToSend.type.startsWith('audio/'));
            if (isVoiceAttachment && getAppSetting('confirmVoiceSends')) {
                if (!window.confirm('Send this voice message?')) {
                    isSubmitting = false; // Reset flag if cancelled
                    return;
                }
            } else if (!isVoiceAttachment && getAppSetting('confirmMediaSends')) {
                if (!window.confirm('Send this attachment?')) {
                    isSubmitting = false; // Reset flag if cancelled
                    return;
                }
            }
        }
        let voiceAttachmentMetaToSend = null;
        if (attachmentFileToSend && attachmentFileToSend.type && attachmentFileToSend.type.startsWith('audio/')) {
            if (pendingAttachmentMetaPromise) {
                voiceAttachmentMetaToSend = await pendingAttachmentMetaPromise;
            } else if (pendingAttachmentMeta) {
                voiceAttachmentMetaToSend = pendingAttachmentMeta;
            } else {
                voiceAttachmentMetaToSend = createVoiceAttachmentMeta();
            }
        }

        const outgoingReplyContext = pendingReply ? { ...pendingReply } : null;
        const formData = new FormData();
        formData.append('token', token);
        
        // Check if this is an AI chat
        const isAiChat = selectedUser && String(selectedUser).startsWith('ai:');
        
        // Check if we're editing a voice message
        const isEditingVoiceMessage = !!(window._editingVoiceMessageId && attachmentFileToSend && attachmentFileToSend.type && attachmentFileToSend.type.startsWith('audio/'));
        
        if (isEditingVoiceMessage) {
            // Update existing voice message
            formData.append('message_id', String(window._editingVoiceMessageId));
            formData.append('attachment', attachmentFileToSend);
            if (voiceAttachmentMetaToSend) {
                formData.append('attachment_waveform', JSON.stringify(voiceAttachmentMetaToSend.waveform || []));
                if (voiceAttachmentMetaToSend.duration) {
                    formData.append('attachment_duration', String(voiceAttachmentMetaToSend.duration));
                }
            }
        } else {
            // Send new message
            if (isAiChat) {
                // AI chat uses different parameters
                formData.append('ai_chat_key', selectedUser);
                formData.append('message', structuredTableMessage || processedText);
            } else {
                formData.append('recipient_id', selectedUser);
                formData.append('message', structuredTableMessage || processedText);
            }
            
            if (attachmentFileToSend) {
                formData.append('attachment', attachmentFileToSend);
            }
            if (voiceAttachmentMetaToSend) {
                formData.append('attachment_waveform', JSON.stringify(voiceAttachmentMetaToSend.waveform || []));
                if (voiceAttachmentMetaToSend.duration) {
                    formData.append('attachment_duration', String(voiceAttachmentMetaToSend.duration));
                }
            }
            // Only send reply_to_id for server-side messages (skip local AI messages)
            if (pendingReply && !pendingReply.isAi) {
                const replyId = Number(pendingReply.id || 0);
                if (Number.isFinite(replyId) && replyId > 0) {
                    formData.append('reply_to_id', String(replyId));
                }
            }
        }

        try {
            const endpoint = isEditingVoiceMessage 
                ? 'update_voice_message.php' 
                : (isAiChat ? 'send_ai_message.php' : 'send_message.php');
            const res = await fetch(endpoint, {
                method: 'POST',
                body: formData
            });
            const data = await res.json();

            if (data.success) {
                if (isEditingVoiceMessage) {
                    // Find and update the existing message element instead of removing it
                    const existingMsg = findMessageElementByServerId(window._editingVoiceMessageId);
                    if (existingMsg) {
                        // Parse the new attachment data
                        const newAttachmentData = data.message.message.startsWith('__ATTACHMENT__:') 
                            ? JSON.parse(data.message.message.substring('__ATTACHMENT__:'.length))
                            : null;
                        
                        if (newAttachmentData && newAttachmentData.kind === 'audio') {
                            // Update the voice player with new audio
                            const voicePlayer = existingMsg.querySelector('.voice-message-player');
                            if (voicePlayer) {
                                const audioEl = voicePlayer.querySelector('audio');
                                const localBlobUrl = URL.createObjectURL(attachmentFileToSend);
                                
                                // Update audio source
                                if (audioEl) {
                                    audioEl.src = localBlobUrl;
                                    audioEl.load();
                                }
                                
                                // Update waveform bars with new data
                                const waveformContainer = voicePlayer.querySelector('.voice-waveform');
                                if (waveformContainer && newAttachmentData.waveform && Array.isArray(newAttachmentData.waveform)) {
                                    // Clear existing bars and create new ones
                                    waveformContainer.innerHTML = '';
                                    newAttachmentData.waveform.forEach((level) => {
                                        const bar = document.createElement('div');
                                        bar.className = 'voice-bar';
                                        bar.style.height = `${Math.max(2, level * 100)}%`;
                                        waveformContainer.appendChild(bar);
                                    });
                                }
                                
                                // Update duration if available
                                if (newAttachmentData.duration) {
                                    const durationEl = voicePlayer.querySelector('.voice-duration');
                                    if (durationEl) {
                                        durationEl.textContent = formatVoiceDuration(newAttachmentData.duration);
                                    }
                                }
                                
                                // Reset player state
                                voicePlayer.classList.remove('playing', 'unheard');
                                const playBtn = voicePlayer.querySelector('.voice-play-btn i');
                                if (playBtn) {
                                    playBtn.className = 'fa-solid fa-play';
                                }
                            }
                        }
                    }
                    
                    // Clear editing state
                    window._editingVoiceMessageId = null;
                    window._editingVoiceMessageElement = null;
                    invalidateSidebarHistoryCache({ reloadIfVisible: true });
                } else {
                    handleSuccessfulOutgoingNewMessage(data, attachmentFileToSend, selectedUser, outgoingReplyContext);
                    const outgoingMessageId = Number(data.message && data.message.id ? data.message.id : 0);
                    const shouldTriggerPublicAiReply = !isAiChat && shouldTriggerQuillTalkAiResponse(processedText, outgoingReplyContext);
                    
                    console.log('[QuillTalk AI Debug] shouldTriggerPublicAiReply:', shouldTriggerPublicAiReply, {
                        isAiChat,
                        messageMentions: messageMentionsQuillTalkAi(processedText),
                        replyContextIsAi: outgoingReplyContext && outgoingReplyContext.isAi,
                        replyToQuillTalkAi: messageRepliesToQuillTalkAi(outgoingReplyContext)
                    });
                    
                    // Trigger AI reply if this is an AI chat
                    if (isAiChat && data.trigger_ai_reply && data.ai_chat_key) {
                        const aiImagePrompt = extractAiImageIntentPrompt(processedText);
                        console.log('[AI REPLY] Triggering AI reply for:', data.ai_chat_key, 'with message:', processedText);
                        (async () => {
                            try {
                                if (aiImagePrompt) {
                                    await requestAiGeneratedImage(data.ai_chat_key, aiImagePrompt, {
                                        mode: 'ai_chat',
                                        originMessageId: Number(data.message && data.message.id ? data.message.id : 0)
                                    });
                                    return;
                                }
                                await queueLocalAiReply(data.ai_chat_key, processedText, {
                                    reactionTargetMessageId: Number(data.message && data.message.id ? data.message.id : 0),
                                    originMessageId: Number(data.message && data.message.id ? data.message.id : 0),
                                    originDisplayName: 'You',
                                    originMessageBody: structuredTableMessage || processedText
                                });
                            } catch (e) {
                                console.error('Failed to get AI reply:', e);
                            }
                        })();
                    } else {
                        console.log('[AI REPLY] Not triggering:', { isAiChat, trigger_ai_reply: data.trigger_ai_reply, ai_chat_key: data.ai_chat_key });
                    }

                    if (shouldTriggerPublicAiReply) {
                        // Show AI typing indicator before triggering the response
                        const aiTypingIndicatorKey = showAiTypingIndicator(selectedUser);
                        triggerQuillTalkAiResponseForMessage(
                            selectedUser,
                            processedText,
                            outgoingMessageId,
                            Number(currentUserId || 0),
                            'You',
                            structuredTableMessage || processedText
                        ).catch(error => {
                            console.error('Failed to trigger QuillTalk AI from outgoing message:', error);
                            if (aiTypingIndicatorKey) hideTypingIndicatorByKey(aiTypingIndicatorKey);
                        });
                    }
                }
                
                clearComposerAfterSend(selectedUser, true, { preserveTypingIndicator: isAiChat || shouldTriggerPublicAiReply });
                invalidateSidebarHistoryCache({ reloadIfVisible: true });
                isSubmitting = false; // Reset flag after successful send
            } else {
                if (data && typeof data.error === 'string' && data.error.toLowerCase().includes('blocked')) {
                    await pollContacts();
                    if (selectedUser) {
                        updateHeaderContact(selectedUser);
                    }
                }
                alert(data.error || 'Error sending message');
                isSubmitting = false; // Reset flag on error
            }
        } catch (e) {
            alert('Network error.');
            isSubmitting = false; // Reset flag on network error
        }
        };
    }

