        all: { key: 'all', requiresValue: false },
        media: { key: 'media', requiresValue: false },
        links: { key: 'links', requiresValue: false },
        polls: { key: 'polls', requiresValue: false },
        voice: { key: 'voice', requiresValue: false },
        from_user: {
            key: 'from_user',
            requiresValue: true,
            placeholder: 'Sender name or @username'
        },
