    function getAllMessageSearchControlElements() {
        return [msgSearchControls, rightSidebarSearchControls].filter(Boolean);
    }

    function getAllMessageSearchFilterGroups() {
        return [msgSearchFilters, rightSidebarSearchFilters].filter(Boolean);
    }

    function getAllMessageSearchFilterValueInputs() {
        return [msgSearchFilterValue, rightSidebarSearchFilterValue].filter(Boolean);
    }

    function syncMsgSearchControlsVisibility(forceExpanded = null, preferredControl = null) {
        const controls = getAllMessageSearchControlElements();
        if (!controls.length) {
            return;
        }

        if (forceExpanded === null) {
            controls.forEach(controlEl => {
                const shouldExpand = String(controlEl.dataset.searchActive || '') === '1';
                controlEl.classList.toggle('is-expanded', shouldExpand);
            });
            return;
        }

        if (preferredControl) {
            preferredControl.dataset.searchActive = forceExpanded ? '1' : '0';
            preferredControl.classList.toggle('is-expanded', !!forceExpanded);
            return;
        }

        controls.forEach(controlEl => {
            controlEl.dataset.searchActive = forceExpanded ? '1' : '0';
            controlEl.classList.toggle('is-expanded', !!forceExpanded);
        });
    }

    function syncMsgSearchFilterButtons() {
        getAllMessageSearchFilterGroups().forEach(groupEl => {
            groupEl.querySelectorAll('.msg-search-filter').forEach(button => {
                const isActive = String(button.dataset.filter || '') === msgSearchActiveFilter;
                button.classList.toggle('is-active', isActive);
                button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
            });
        });
    }

    function syncMsgSearchFilterInput() {
        const config = getMsgSearchFilterConfig(msgSearchActiveFilter);
        getAllMessageSearchFilterValueInputs().forEach(inputEl => {
            if (!config.requiresValue) {
                inputEl.hidden = true;
                inputEl.value = '';
                return;
            }

            inputEl.hidden = false;
            inputEl.placeholder = config.placeholder || 'Filter value';
            inputEl.value = msgSearchFilterValues[msgSearchActiveFilter] || '';
        });
    }

    function getActiveMsgSearchFilterValue() {
        const storedValue = String(msgSearchFilterValues[msgSearchActiveFilter] || '').trim();
        if (storedValue) {
            return storedValue;
        }

        const liveValue = getAllMessageSearchFilterValueInputs()
            .map(inputEl => String(inputEl.value || '').trim())
            .find(Boolean);

        return liveValue || '';
    }

    function setMsgSearchFilter(filterKey, options = {}) {
        const nextConfig = getMsgSearchFilterConfig(filterKey);
        const previousConfig = getMsgSearchFilterConfig(msgSearchActiveFilter);

        if (previousConfig.requiresValue) {
            msgSearchFilterValues[msgSearchActiveFilter] = getActiveMsgSearchFilterValue();
        }

        msgSearchActiveFilter = nextConfig.key;
        syncMsgSearchFilterButtons();
        syncMsgSearchFilterInput();

        const focusTarget = options.focusFilterValueInput || msgSearchFilterValue;
        if (options.focusFilterValue && focusTarget && !focusTarget.hidden) {
            focusTarget.focus();
        }
    }

    function updateMsgSearchPerPage() {
        if (!msgSearchResults) return;
        const h = msgSearchResults.clientHeight || 400;
        msgSearchPerPage = Math.max(5, Math.min(80, Math.floor(h / 56)));
    }

    async function fetchMsgSearchPage() {
        if (!selectedUser || !msgSearchResults) return;
        msgSearchQuery = msgSearchInput ? msgSearchInput.value.trim() : '';

        const activeFilterConfig = getMsgSearchFilterConfig(msgSearchActiveFilter);
        const activeFilterValue = activeFilterConfig.requiresValue
            ? getActiveMsgSearchFilterValue()
            : '';

        if (!msgSearchQuery && msgSearchActiveFilter === 'all') {
            showMsgSearchEmptyState('Type to search.');
            return;
        }

        if (activeFilterConfig.requiresValue && !activeFilterValue) {
            showMsgSearchEmptyState(
                msgSearchActiveFilter === 'from_user'
                    ? 'Type a sender name to filter messages.'
                    : 'Type a name to find messages that mention that user.'
            );
            return;
        }

        updateMsgSearchPerPage();
        try {
            const params = new URLSearchParams({
                token: String(token || ''),
                with: String(selectedUser || ''),
                page: String(msgSearchPage),
                per_page: String(msgSearchPerPage)
            });

            if (msgSearchQuery) {
                params.set('q', msgSearchQuery);
            }
            if (msgSearchActiveFilter !== 'all') {
                params.set('filter', msgSearchActiveFilter);
            }
            if (activeFilterValue) {
                params.set('filter_value', activeFilterValue);
            }

            const res = await fetch(`search_messages.php?${params.toString()}`);
            if (!res.ok) return;
            const data = await res.json();
            const pages = data.pages || 0;
            if (msgSearchPageLabel) {
                msgSearchPageLabel.textContent = `Page ${data.page || msgSearchPage} / ${Math.max(1, pages || 1)}`;
            }
            if (msgSearchPrev) msgSearchPrev.disabled = (data.page || msgSearchPage) <= 1;
            if (msgSearchNext) msgSearchNext.disabled = pages ? (data.page || 1) >= pages : true;
            msgSearchResults.innerHTML = '';
            if (!(data.results || []).length) {
                const empty = document.createElement('div');
                empty.className = 'msg-search-empty';
                empty.textContent = (msgSearchActiveFilter !== 'all' || activeFilterValue)
                    ? 'No messages match the selected filters.'
                    : 'No messages found.';
                msgSearchResults.appendChild(empty);
                return;
            }
            (data.results || []).forEach(row => {
                const wrap = document.createElement('div');
                wrap.className = 'msg-search-result';
                hydrateMessageSenderData(row);
                const built = buildMessageElementSafe(row);
                const inner = document.createElement('div');
                inner.className = 'msg-search-result-inner';
                inner.appendChild(built.element);
                wrap.appendChild(inner);
                const time = document.createElement('div');
                time.className = 'msg-search-result-time';
                time.textContent = formatTimestamp(row.created_at);
                wrap.appendChild(time);
                wrap.addEventListener('click', () => {
                    if (msgSearchPanel) {
                        msgSearchPanel.classList.remove('is-open');
                        msgSearchPanel.setAttribute('aria-hidden', 'true');
                    }
                    syncMsgSearchControlsVisibility(false, msgSearchControls);
                    scrollChatToMessageId(row.id);
                });
                msgSearchResults.appendChild(wrap);
            });
        } catch (e) {
            console.warn('msg search', e);
        }
    }

    function scheduleMsgSearch() {
        clearTimeout(msgSearchDebounceId);
        msgSearchDebounceId = window.setTimeout(() => {
            msgSearchPage = 1;
            fetchMsgSearchPage();
        }, 280);
    }

    function openMsgSearchPanel() {
        if (!msgSearchPanel || !selectedUser) return;
        msgSearchPanel.classList.add('is-open');
        msgSearchPanel.setAttribute('aria-hidden', 'false');
        syncMsgSearchControlsVisibility(true, msgSearchControls);
        syncMsgSearchFilterButtons();
        syncMsgSearchFilterInput();
        msgSearchPage = 1;
        fetchMsgSearchPage();
        if (msgSearchInput) {
            msgSearchInput.focus();
        }
    }

    [chatSearchBtn, chatSearchBtnMobile].forEach(btn => {
