    if (forwardModalSend) {
        forwardModalSend.addEventListener('click', async () => {
            if (!forwardMessagePayload || !forwardModalList) return;
            const boxes = forwardModalList.querySelectorAll('input[type=checkbox]:checked');
            const keys = Array.from(boxes).map(b => b.dataset.chatKey).filter(Boolean);
            if (!keys.length) return;
            for (const k of keys) {
