        function closeDeleteMessageModal() {
            if (deleteMessageModal) {
                deleteMessageModal.classList.remove('open');
                deleteMessageModal.setAttribute('aria-hidden', 'true');
            }
            deletingMessageState = null;
        }

        const voiceMessageTranscriptionPromiseCache = new Map();
        let activeSummarySpeechButton = null;
        let activeSummarySpeechUtterance = null;

        function isUsableVoiceMessageTranscription(text) {
            const normalized = String(text || '')
                .replace(/\s+/g, ' ')
                .trim();

            if (!normalized) {
                return false;
            }

            if (/^\[(transcription service not configured|no transcription available|audio was silent or could not be transcribed)/i.test(normalized)) {
                return false;
            }

            if (/^error:/i.test(normalized)) {
                return false;
            }

            return true;
        }

        function supportsSummarySpeechPlayback() {
            return typeof window !== 'undefined'
                && typeof window.speechSynthesis !== 'undefined'
                && typeof window.SpeechSynthesisUtterance === 'function';
        }

        async function requestVoiceMessageTranscription(attachmentData, { forceRefresh = false } = {}) {
            const audioUrl = attachmentData && attachmentData.url
                ? String(attachmentData.url).trim()
                : '';

            if (!token) {
                throw new Error('You need to be signed in to transcribe voice messages.');
            }

            if (!audioUrl) {
                throw new Error('Could not find audio file.');
            }

            if (/^(blob:|data:|mediastream:)/i.test(audioUrl)) {
                throw new Error('This voice message cannot be transcribed from the current source.');
            }

            if (!forceRefresh && voiceMessageTranscriptionPromiseCache.has(audioUrl)) {
                return voiceMessageTranscriptionPromiseCache.get(audioUrl);
            }

            let transcriptionPromise = null;
            transcriptionPromise = (async () => {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('audio_url', audioUrl);

                const response = await fetch('transcribe_voice.php', {
                    method: 'POST',
                    body: formData
                });

                const data = await response.json().catch(() => ({}));
                if (!response.ok || !data.success) {
                    throw new Error(data.error || 'Transcription failed');
                }

                const transcription = String(data.transcription || '').trim();
                if (!transcription) {
                    throw new Error('Transcription came back empty.');
                }

                return transcription;
            })().catch(error => {
                if (voiceMessageTranscriptionPromiseCache.get(audioUrl) === transcriptionPromise) {
                    voiceMessageTranscriptionPromiseCache.delete(audioUrl);
                }
                throw error;
            });

            voiceMessageTranscriptionPromiseCache.set(audioUrl, transcriptionPromise);
            return transcriptionPromise;
        }

        function setSummarySpeechButtonState(button, isSpeaking, {
            idleLabel = 'Read summary aloud',
            activeLabel = 'Stop reading summary aloud'
        } = {}) {
            if (!button) {
                return;
            }

            button.dataset.idleLabel = idleLabel;
            button.dataset.activeLabel = activeLabel;
            button.classList.toggle('is-speaking', !!isSpeaking);
            button.setAttribute('aria-pressed', isSpeaking ? 'true' : 'false');
            button.setAttribute('aria-label', isSpeaking ? activeLabel : idleLabel);
            button.setAttribute('title', isSpeaking ? activeLabel : idleLabel);
            button.innerHTML = `<i class="fa-solid ${isSpeaking ? 'fa-stop' : 'fa-volume-high'}" aria-hidden="true"></i>`;
        }

        function stopSummarySpeechPlayback() {
            if (!supportsSummarySpeechPlayback()) {
                return;
            }

            const lastButton = activeSummarySpeechButton;
            activeSummarySpeechButton = null;
            activeSummarySpeechUtterance = null;

            if (lastButton) {
                setSummarySpeechButtonState(lastButton, false, {
                    idleLabel: lastButton.dataset.idleLabel || 'Read summary aloud',
                    activeLabel: lastButton.dataset.activeLabel || 'Stop reading summary aloud'
                });
            }

            try {
                window.speechSynthesis.cancel();
            } catch (error) {
                console.warn('Unable to stop summary speech playback cleanly.', error);
            }
        }

        function stopSummarySpeechPlaybackIfWithin(root) {
            if (!root || !activeSummarySpeechButton || !root.contains(activeSummarySpeechButton)) {
                return;
            }

            stopSummarySpeechPlayback();
        }

        function toggleSummarySpeechPlayback(button, text) {
            const normalizedText = String(text || '').trim();
            if (!normalizedText) {
                showToast('There is no summary text to read aloud yet.', 'info');
                return;
            }

            if (!supportsSummarySpeechPlayback()) {
                showToast('Read-aloud is not supported on this device.', 'error');
                return;
            }

            if (activeSummarySpeechButton === button) {
                stopSummarySpeechPlayback();
                return;
            }

            stopSummarySpeechPlayback();

            const utterance = new SpeechSynthesisUtterance(normalizedText);
            utterance.lang = document.documentElement.lang || 'en-US';
            utterance.rate = 1;
            utterance.onend = () => {
                if (activeSummarySpeechUtterance !== utterance) {
                    return;
                }
                const finishedButton = activeSummarySpeechButton;
                activeSummarySpeechButton = null;
                activeSummarySpeechUtterance = null;
                if (finishedButton) {
                    setSummarySpeechButtonState(finishedButton, false, {
                        idleLabel: finishedButton.dataset.idleLabel || 'Read summary aloud',
                        activeLabel: finishedButton.dataset.activeLabel || 'Stop reading summary aloud'
                    });
                }
            };
            utterance.onerror = () => {
                if (activeSummarySpeechUtterance !== utterance) {
                    return;
                }
                const failedButton = activeSummarySpeechButton;
                activeSummarySpeechButton = null;
                activeSummarySpeechUtterance = null;
                if (failedButton) {
                    setSummarySpeechButtonState(failedButton, false, {
                        idleLabel: failedButton.dataset.idleLabel || 'Read summary aloud',
                        activeLabel: failedButton.dataset.activeLabel || 'Stop reading summary aloud'
                    });
                }
                showToast('Could not read that summary aloud.', 'error');
            };

            activeSummarySpeechButton = button;
            activeSummarySpeechUtterance = utterance;
            setSummarySpeechButtonState(button, true, {
                idleLabel: button.dataset.idleLabel || 'Read summary aloud',
                activeLabel: button.dataset.activeLabel || 'Stop reading summary aloud'
            });

            try {
                window.speechSynthesis.speak(utterance);
            } catch (error) {
                console.error('Summary speech playback failed:', error);
                stopSummarySpeechPlayback();
                showToast('Could not read that summary aloud.', 'error');
            }
        }

        function createSummarySpeechButton(summaryText, {
            idleLabel = 'Read summary aloud',
            activeLabel = 'Stop reading summary aloud'
        } = {}) {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'summary-speech-btn';
            setSummarySpeechButtonState(button, false, { idleLabel, activeLabel });

            if (!supportsSummarySpeechPlayback()) {
                button.hidden = true;
                return button;
            }

            button.addEventListener('click', event => {
                event.preventDefault();
                event.stopPropagation();
                toggleSummarySpeechPlayback(button, summaryText);
            });

            return button;
        }

        function renderSummarySpeechContent(container, summaryText, {
            textClassName = '',
            idleLabel = 'Read summary aloud',
            activeLabel = 'Stop reading summary aloud'
        } = {}) {
            if (!container) {
                return;
            }

            stopSummarySpeechPlaybackIfWithin(container);
            container.innerHTML = '';

            const wrapper = document.createElement('div');
            wrapper.className = 'summary-speech-shell';

            const textEl = document.createElement('p');
            textEl.className = ['summary-speech-text', textClassName].filter(Boolean).join(' ');
            textEl.textContent = summaryText;

            wrapper.appendChild(textEl);
            wrapper.appendChild(createSummarySpeechButton(summaryText, { idleLabel, activeLabel }));
            container.appendChild(wrapper);
        }

        async function requestContextOnlyAiSummary({
            prompt,
            chatKey = '',
            chatLabel = 'Chat',
            contextLines = []
        } = {}) {
            const response = await fetch('ai_chat.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    prompt,
                    chat_key: chatKey,
                    chat_label: chatLabel,
                    context: contextLines,
                    context_only: true
                })
            });

            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(data.error || 'Unable to summarize those messages right now.');
            }

            const summaryText = String(data.message || '').trim();
            if (!summaryText) {
                throw new Error('The summary came back empty.');
            }

            return summaryText;
        }

        // Open transcribe modal and handle transcription
        async function openTranscribeModal(messageId, attachmentData) {
            const modal = document.getElementById('transcribeModal');
            const loadingContainer = document.getElementById('transcribeLoadingContainer');
            const textContainer = document.getElementById('transcribeTextContainer');
            
            if (!modal) return;
            
            // Show modal with loading state
            modal.classList.add('open');
            modal.setAttribute('aria-hidden', 'false');
            loadingContainer.style.display = 'flex';
            textContainer.style.display = 'none';
            textContainer.textContent = '';
            
            if (!(attachmentData && attachmentData.url)) {
                textContainer.textContent = 'Error: Could not find audio file.';
                loadingContainer.style.display = 'none';
                textContainer.style.display = 'block';
                return;
            }
            
            try {
                const transcription = await requestVoiceMessageTranscription(attachmentData);
                loadingContainer.style.display = 'none';
                textContainer.style.display = 'block';
                textContainer.textContent = transcription;
                logClientHistoryEvent('voice_message_transcribed', {
                    chatKey: String(selectedUser || ''),
                    eventValue: 'Voice message'
                }).catch(() => {});
            } catch (error) {
                console.error('Transcription error:', error);
                loadingContainer.style.display = 'none';
                textContainer.style.display = 'block';
                textContainer.textContent = 'Error: Unable to transcribe this voice message. ' + (error.message || '');
            }
        }
        
        function closeTranscribeModal() {
            const modal = document.getElementById('transcribeModal');
            if (modal) {
                modal.classList.remove('open');
                modal.setAttribute('aria-hidden', 'true');
            }
        }

        async function openSelectedMessagesSummaryModal() {
            const modal = document.getElementById('messageSummaryModal');
            const subtitle = document.getElementById('messageSummaryModalSubtitle');
            const loadingContainer = document.getElementById('messageSummaryLoadingContainer');
            const textContainer = document.getElementById('messageSummaryTextContainer');
            const activeChatKey = String(selectedUser || '').trim();
            const selectedDetails = getSelectedMessageDetails();
            const selectedCount = selectedDetails.length;
            const selectedVoiceCount = selectedDetails.filter(detail => !!getSelectedSummaryVoiceAttachment(detail)).length;

            if (!modal || !loadingContainer || !textContainer) {
                return;
            }

            if (!selectedCount) {
                showToast('Select at least one message first.', 'error');
                return;
            }

            modal.classList.add('open');
            modal.setAttribute('aria-hidden', 'false');
            if (subtitle) {
                if (selectedVoiceCount > 0) {
                    subtitle.textContent = `Transcribing ${selectedVoiceCount} voice message${selectedVoiceCount === 1 ? '' : 's'} and summarizing ${selectedCount} selected message${selectedCount === 1 ? '' : 's'}`;
                } else {
                    subtitle.textContent = selectedCount === 1
                        ? 'Summarizing 1 selected message'
                        : `Summarizing ${selectedCount} selected messages`;
                }
            }
            loadingContainer.style.display = 'flex';
            textContainer.style.display = 'none';
            stopSummarySpeechPlaybackIfWithin(textContainer);
            textContainer.textContent = '';

            try {
                const summaryState = await buildSelectedMessagesSummaryState(selectedDetails);
                if (!summaryState || !summaryState.contextLines.length) {
                    throw new Error('No selected messages could be summarized.');
                }

                const summaryText = await requestContextOnlyAiSummary({
                    prompt: `There are ${summaryState.selectedCount} selected messages in the supplemental local-only context. Summarize only those selected messages. Treat any line labeled "Voice message transcription" as the full content of that voice message. The only allowed evidence is the supplemental local-only context, so do not use any earlier conversation history or outside details. Keep it concise and stylish in 2 to 4 short sentences. Focus on what happened, open questions, requests, and anything urgent. Do not mention that you are summarizing selected messages.`,
                    chatKey: activeChatKey,
                    chatLabel: activeChatKey ? getUnreadDividerChatLabel(activeChatKey) : 'Selected messages',
                    contextLines: summaryState.contextLines
                });

                loadingContainer.style.display = 'none';
                textContainer.style.display = 'block';
                renderSummarySpeechContent(textContainer, summaryText, {
                    idleLabel: 'Read selected summary aloud',
                    activeLabel: 'Stop reading selected summary aloud'
                });

                if (subtitle) {
                    const fallbackNote = summaryState.voiceFallbackCount > 0
                        ? ` Voice transcription was unavailable for ${summaryState.voiceFallbackCount} selected voice message${summaryState.voiceFallbackCount === 1 ? '' : 's'}.`
                        : '';
                    subtitle.textContent = summaryState.selectedCount === 1
                        ? `Summary for 1 selected message.${fallbackNote}`.trim()
                        : `Summary for ${summaryState.selectedCount} selected messages.${fallbackNote}`.trim();
                }
            } catch (error) {
                console.error('Selected message summary error:', error);
                stopSummarySpeechPlaybackIfWithin(textContainer);
                loadingContainer.style.display = 'none';
                textContainer.style.display = 'block';
                textContainer.textContent = 'Error: Unable to summarize those messages right now. ' + (error && error.message ? error.message : '');
            }
        }

