        function closeTranslateModal() {
            if (!translateModal) {
                return;
            }

            translateModal.classList.remove('open');
            translateModal.setAttribute('aria-hidden', 'true');
            translateModalState = null;
        }

        function renderTranslateLanguageChoices() {
            if (!translateModalState || !translateLanguageList) {
                return;
            }

            const translateTargets = Array.isArray(translateModalState.targets)
                ? translateModalState.targets
                : [];
            const isBulkTranslate = translateTargets.length > 1;
            const sourceLanguageOption = isBulkTranslate
                ? null
                : getTranslateLanguageOption(translateModalState.sourceLanguageCode);
            const isChoosingSourceLanguage = !isBulkTranslate && !sourceLanguageOption;

            if (translateModalSubtitle) {
                translateModalSubtitle.textContent = isBulkTranslate
                    ? `Translate ${translateTargets.length} selected message${translateTargets.length === 1 ? '' : 's'} to...`
                    : (isChoosingSourceLanguage
                        ? 'Choose the current language of this message'
                        : `Detected current language: ${sourceLanguageOption.label}. Translate to...`);
            }

            translateLanguageList.innerHTML = '';

            if (!isBulkTranslate && !isChoosingSourceLanguage) {
                const changeSourceButton = document.createElement('button');
                changeSourceButton.type = 'button';
                changeSourceButton.className = 'translate-language-btn';
                changeSourceButton.innerHTML = `
                    <span class="translate-language-name">Detected: ${qtEscapeHtml(sourceLanguageOption.label)}</span>
                    <span class="translate-language-native">Wrong guess? Choose a different source language</span>
                `;
                addTapAndClickListener(changeSourceButton, event => {
                    event.preventDefault();
                    translateModalState.sourceLanguageCode = '';
                    translateModalState.sourceLanguageLabel = '';
                    renderTranslateLanguageChoices();
                });
                translateLanguageList.appendChild(changeSourceButton);
            }

            MESSAGE_TRANSLATION_LANGUAGES.forEach(language => {
                if (!isBulkTranslate && !isChoosingSourceLanguage && language.code === sourceLanguageOption.code) {
                    return;
                }

                const button = document.createElement('button');
                button.type = 'button';
                button.className = 'translate-language-btn';
                button.innerHTML = `
                    <span class="translate-language-name">${qtEscapeHtml(language.label)}</span>
                    <span class="translate-language-native">${qtEscapeHtml(language.nativeLabel)}</span>
                `;
                addTapAndClickListener(button, event => {
                    event.preventDefault();
                    if (!isBulkTranslate && isChoosingSourceLanguage) {
                        translateModalState.sourceLanguageCode = language.code;
                        translateModalState.sourceLanguageLabel = language.label;
                        renderTranslateLanguageChoices();
                        return;
                    }

                    applyMessageTranslation(isBulkTranslate ? '' : sourceLanguageOption.code, language.code);
                });
                translateLanguageList.appendChild(button);
            });
        }

        async function applyMessageTranslation(sourceLanguageCode, targetLanguageCode) {
            if (!translateModalState || !Array.isArray(translateModalState.targets) || !translateModalState.targets.length) {
                return;
            }

            const targetLanguageOption = getTranslateLanguageOption(targetLanguageCode);
            const fixedSourceLanguageOption = sourceLanguageCode
                ? getTranslateLanguageOption(sourceLanguageCode)
                : null;
            if ((!fixedSourceLanguageOption && sourceLanguageCode) || !targetLanguageOption) {
                showToast('That language is not available right now.', 'error');
                return;
            }
            if (fixedSourceLanguageOption && fixedSourceLanguageOption.code === targetLanguageOption.code) {
                showToast('Choose a different target language.', 'error');
                return;
            }

            const translateTargets = translateModalState.targets.slice();
            const chatKey = translateModalState.chatKey;
            let translatedCount = 0;
            let skippedCount = 0;
            let lastError = null;

            try {
                for (const target of translateTargets) {
                    const detectedSourceLanguageCode = fixedSourceLanguageOption
                        ? fixedSourceLanguageOption.code
                        : detectMessageSourceLanguage(target.rawMessage);
                    const detectedSourceLanguageOption = getTranslateLanguageOption(detectedSourceLanguageCode);
                    if (!detectedSourceLanguageOption) {
                        skippedCount += 1;
                        continue;
                    }

                    if (detectedSourceLanguageOption.code === targetLanguageOption.code) {
                        messageTranslationStates.set(target.messageTranslationKey, {
                            translatedText: target.rawMessage,
                            targetLanguageCode: targetLanguageOption.code,
                            targetLanguageLabel: targetLanguageOption.label,
                            detectedLanguage: detectedSourceLanguageOption.code,
                            sourceLanguageCode: detectedSourceLanguageOption.code,
                            sourceLanguageLabel: detectedSourceLanguageOption.label,
                            showTranslated: true
                        });
                        translatedCount += 1;
                        continue;
                    }

                    try {
                        const response = await fetch('translate_message.php', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                token,
                                text: target.rawMessage,
                                source_language: detectedSourceLanguageOption.code,
                                target_language: targetLanguageOption.code
                            })
                        });
                        const data = await response.json().catch(() => ({}));
                        if (!response.ok || !data.success || !data.translated_text) {
                            throw new Error(data && data.error ? data.error : 'Translation failed');
                        }
                        const translatedText = String(data.translated_text || '').trim();
                        if (!translatedText) {
                            throw new Error('Translation failed');
                        }

                        messageTranslationStates.set(target.messageTranslationKey, {
                            translatedText,
                            targetLanguageCode: targetLanguageOption.code,
                            targetLanguageLabel: targetLanguageOption.label,
                            detectedLanguage: String(data.detected_language || detectedSourceLanguageOption.code).trim().toLowerCase(),
                            sourceLanguageCode: detectedSourceLanguageOption.code,
                            sourceLanguageLabel: detectedSourceLanguageOption.label,
                            showTranslated: true
                        });
                        translatedCount += 1;
                    } catch (error) {
                        lastError = error;
                        skippedCount += 1;
                    }
                }

                if (!translatedCount) {
                    throw lastError || new Error('Translation failed');
                }

                closeTranslateModal();
                translateTargets.forEach(target => {
                    const translatedSelector = `.message[data-translation-key="${escapeMessageTranslationSelectorValue(target.messageTranslationKey)}"]`;
                    document.querySelectorAll(translatedSelector).forEach(messageEl => {
                        syncRenderedMessageTranslation(messageEl);
                    });
                });
                await logClientHistoryEvent('message_translated', {
                    chatKey,
                    eventValue: `${targetLanguageOption.label}`
                });
                if (skippedCount > 0) {
                    showToast(`Translated ${translatedCount} message${translatedCount === 1 ? '' : 's'}. Skipped ${skippedCount}.`, 'info');
                }
            } catch (error) {
                console.error('Translation error:', error);
                showToast(error && error.message ? error.message : 'Could not translate this message.', 'error');
            }
        }

        function openTranslateModal(state) {
            const translateTargets = normalizeTranslateModalTargets(state);
            if (!translateModal || !translateTargets.length || !translateLanguageList) {
                showToast('This message cannot be translated.', 'error');
                return;
            }

            const primaryTarget = translateTargets[0];
            translateModalState = {
                messageTranslationKey: String(primaryTarget.messageTranslationKey || ''),
                chatKey: String(state && state.chatKey || primaryTarget.chatKey || selectedUser || ''),
                rawMessage: primaryTarget.rawMessage,
                sourceLanguageCode: translateTargets.length > 1
                    ? ''
                    : detectMessageSourceLanguage(primaryTarget.rawMessage),
                sourceLanguageLabel: '',
                targets: translateTargets
            };

            const detectedSourceLanguage = getTranslateLanguageOption(translateModalState.sourceLanguageCode);
            translateModalState.sourceLanguageLabel = detectedSourceLanguage ? detectedSourceLanguage.label : '';

            renderTranslateLanguageChoices();

            translateModal.classList.add('open');
            translateModal.setAttribute('aria-hidden', 'false');
        }

        if (translateModalClose) {
            addTapAndClickListener(translateModalClose, closeTranslateModal);
        }

        // ── Nickname Modal ───────────────────────────────────────────────────
        let nicknameModalTargetUserId = null;
        
        function openNicknameModal(userId) {
            const modal = document.getElementById('nicknameModal');
            const input = document.getElementById('nicknameInput');
            const clearBtn = document.getElementById('clearNicknameBtn');
            
            if (!modal || !input) return;
            
            nicknameModalTargetUserId = userId;
            const currentNickname = getUserNickname(userId);
            
            input.value = currentNickname || '';
            clearBtn.style.display = currentNickname ? 'flex' : 'none';
            
            bringOverlayToFront(modal, 12);
            modal.classList.add('open');
            modal.setAttribute('aria-hidden', 'false');
            
            setTimeout(() => {
                input.focus();
            }, 100);
        }
        
        function closeNicknameModal() {
            const modal = document.getElementById('nicknameModal');
            if (modal) {
                modal.classList.remove('open');
                modal.setAttribute('aria-hidden', 'true');
                resetOverlayZIndex(modal);
                nicknameModalTargetUserId = null;
            }
        }
        
        async function applyNickname() {
            if (!nicknameModalTargetUserId) return;
            
            const input = document.getElementById('nicknameInput');
            const nickname = input ? input.value.trim() : '';
            
            await setUserNickname(nicknameModalTargetUserId, nickname);
            setNicknameDisplayPref(nicknameModalTargetUserId, 'nickname');
            
            // Refresh all UI elements
            refreshAllDisplayNames(nicknameModalTargetUserId);
            
            closeNicknameModal();
        }
        
        async function clearNicknameAndClose() {
            if (!nicknameModalTargetUserId) return;
            
            await clearUserNickname(nicknameModalTargetUserId);
            setNicknameDisplayPref(nicknameModalTargetUserId, 'display');
            
            // Refresh all UI elements
            refreshAllDisplayNames(nicknameModalTargetUserId);
            
            closeNicknameModal();
        }
        
        function refreshAllDisplayNames(userId) {
            const meta = getContactMeta(userId);
            if (!meta) return;
            
            const displayName = getDisplayNameForUser(userId, meta);
            
            // Update header
            if (selectedUser === userId) {
                updateHeaderContact(userId);
            }
            
            // Update contact list
            const contactEl = document.querySelector(`.contact[data-id="${userId}"]`);
            if (contactEl) {
                const nameEl = contactEl.querySelector('.contact-name');
                if (nameEl) {
                    console.log('Updating contact list name to:', displayName);
                    nameEl.textContent = displayName;
                }
            }
            
            // Update mobile contacts strip
            const mobileContactEl = document.querySelector(`#mobileContactsStrip .mobile-contact-status-card[data-contact-id="${userId}"]`);
            if (mobileContactEl) {
                const mobileNameEl = mobileContactEl.querySelector('.mobile-contact-status-name');
                if (mobileNameEl) {
                    mobileNameEl.textContent = displayName;
                }
            }
            
            // Update right sidebar if open
            if (rightSidebar && rightSidebar.dataset.activeUser === String(userId)) {
                buildRightSidebarContent(userId);
            }
            
            // Update typing indicator if showing
            const typingIndicator = document.getElementById('typingIndicator');
            if (typingIndicator && typingIndicator.style.display !== 'none') {
                const typingName = typingIndicator.querySelector('.typing-name');
                if (typingName && selectedUser === userId) {
                    typingName.textContent = displayName;
                }
            }
            
            // Update group members lists if this user is a member
            document.querySelectorAll('.contact-info-member-name, .group-settings-member-name').forEach(nameEl => {
                const card = nameEl.closest('[data-member-id]') || nameEl.closest('.contact-info-member-card') || nameEl.closest('.group-settings-member-row');
                if (card) {
                    const memberId = card.dataset.memberId || card.querySelector('[data-member-id]')?.dataset.memberId;
                    if (String(memberId) === String(userId)) {
                        nameEl.textContent = displayName;
                    }
                }
            });
        }
        
        const nicknameModalClose = document.getElementById('nicknameModalClose');
        if (nicknameModalClose) {
            addTapAndClickListener(nicknameModalClose, closeNicknameModal);
        }
        
        const nicknameModalCancel = document.getElementById('nicknameModalCancel');
        if (nicknameModalCancel) {
            addTapAndClickListener(nicknameModalCancel, closeNicknameModal);
        }
        
        const nicknameModalDone = document.getElementById('nicknameModalDone');
        if (nicknameModalDone) {
            addTapAndClickListener(nicknameModalDone, applyNickname);
        }
        
        const clearNicknameBtn = document.getElementById('clearNicknameBtn');
        if (clearNicknameBtn) {
            addTapAndClickListener(clearNicknameBtn, clearNicknameAndClose);
