        // ── Call Follow-up Modal ───────────────────────────────────────────────
        
        function openCallFollowupModal() {
            if (!callFollowupModal || !callFollowupInput) return;
            
            // Close the call UI when opening the follow-up modal
            closeCallUI();
            
            // Find the most recent call event message in the current chat
            if (!callFollowupMessageId && chatBox) {
                const callEventMessages = chatBox.querySelectorAll('.message.call-event');
                if (callEventMessages.length > 0) {
                    const lastCallEvent = callEventMessages[callEventMessages.length - 1];
                    callFollowupMessageId = Number(lastCallEvent.dataset.id) || null;
                    console.log('Found call event message ID:', callFollowupMessageId);
                }
            }
            
            callFollowupInput.value = '';
            callFollowupModal.classList.add('open');
            callFollowupModal.setAttribute('aria-hidden', 'false');
            
            // Focus input after a brief delay
            setTimeout(() => {
                if (callFollowupInput) callFollowupInput.focus();
            }, 100);
        }
        
        function closeCallFollowupModal() {
            if (!callFollowupModal) return;
            
            callFollowupModal.classList.remove('open');
            callFollowupModal.setAttribute('aria-hidden', 'true');
            if (callFollowupInput) callFollowupInput.value = '';
        }
        
        async function sendCallFollowup() {
            if (!callFollowupInput || !selectedUser) return;
            
            const message = callFollowupInput.value.trim();
            if (!message) return;
            
            if (!callFollowupMessageId) {
                alert('Unable to link follow-up to call');
                return;
            }
            
            try {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('recipient_id', selectedUser);
                formData.append('message', message);
                formData.append('reply_to_id', String(callFollowupMessageId));
                formData.append('call_followup', '1'); // Flag to indicate this is a call follow-up
                
                const res = await fetch('send_message.php', {
                    method: 'POST',
                    body: formData
                });
                
                const data = await res.json();
                
                if (data.success) {
                    closeCallFollowupModal();
                    
                    // Hide the call UI and leave message button
                    if (callUi) callUi.style.display = 'none';
                    if (leaveMessageBtn) leaveMessageBtn.style.display = 'none';
                    
                    // Refresh messages to show the new follow-up
                    if (selectedUser) {
                        await refreshSelectedConversationFromServer();
                    }
                } else {
                    alert(data.error || 'Failed to send message');
                }
            } catch (e) {
                console.error('Error sending call follow-up:', e);
                alert('Network error');
            }
        }
        
        // Leave message button
        if (leaveMessageBtn) {
            leaveMessageBtn.addEventListener('click', () => {
                openCallFollowupModal();
            });
        }
        
        // Call close buttons
        if (callCloseBtn) {
            callCloseBtn.addEventListener('click', () => {
                closeCallUI();
            });
        }
        
        if (callCloseBottomBtn) {
            callCloseBottomBtn.addEventListener('click', () => {
                closeCallUI();
            });
        }
        
        // Call again button
        if (callAgainBtn) {
            callAgainBtn.addEventListener('click', () => {
                if (selectedUser && getChatTypeFromKey(selectedUser) === 'direct') {
                    initiateCall();
                }
            });
        }
        
        // Call follow-up modal event listeners
        if (callFollowupModalClose) {
            addTapAndClickListener(callFollowupModalClose, closeCallFollowupModal);
        }
        
        if (callFollowupModalCancel) {
            addTapAndClickListener(callFollowupModalCancel, closeCallFollowupModal);
        }
        
        if (callFollowupModalSend) {
            addTapAndClickListener(callFollowupModalSend, sendCallFollowup);
        }
        
        if (callFollowupInput) {
            callFollowupInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                    e.preventDefault();
                    sendCallFollowup();
                } else if (e.key === 'Escape') {
                    e.preventDefault();
                    closeCallFollowupModal();
                }
            });
        }
        
        // Close nickname modal when clicking backdrop
        const nicknameModal = document.getElementById('nicknameModal');
        // Disabled backdrop click to close - only X or Cancel buttons should close
        // if (nicknameModal) {
        //     nicknameModal.addEventListener('click', (e) => {
        //         if (e.target === nicknameModal) {
        //             closeNicknameModal();
        //         }
        //     });
