        // Open delete message modal and handle delete actions
        function openDeleteMessageModal(messageId, messageElement, forceDeleteForMe = false) {
            try {
                deletingMessageState = { id: Number(messageId || 0), el: messageElement, forceDeleteForMe };
                if (!deleteMessageModal) return;
                deleteMessageModal.style.zIndex = '12000';
                deleteMessageModal.style.pointerEvents = 'auto';
                deleteMessageModal.classList.add('open');
                deleteMessageModal.setAttribute('aria-hidden', 'false');
                
                // If forceDeleteForMe, hide the radio buttons and only allow delete for me
                const radioContainer = deleteMessageModal.querySelector('.delete-message-scope-options');
                if (radioContainer) {
                    radioContainer.style.display = forceDeleteForMe ? 'none' : '';
                }
                
                const r = deleteMessageModal.querySelector('input[name="deleteScope"][value="me"]');
                if (r) r.checked = true;
                window.setTimeout(() => {
                    try {
                        deleteMessageConfirm.focus({ preventScroll: true });
                    } catch (focusError) {}
                }, 0);
            } catch (err) {
                console.error('openDeleteMessageModal error', err);
            }
        }

        if (deleteMessageModalClose) {
            addTapAndClickListener(deleteMessageModalClose, () => {
                closeDeleteMessageModal();
            });
        }

        if (deleteMessageCancel) {
            addTapAndClickListener(deleteMessageCancel, () => {
                closeDeleteMessageModal();
            });
        }

        if (deleteMessageConfirm) {
            addTapAndClickListener(deleteMessageConfirm, async () => {
                if (!deletingMessageState || !deletingMessageState.id) return;
                
                // Check if this is a scheduled message
                const isScheduled = deletingMessageState.el && deletingMessageState.el.dataset.scheduledId;
                
                if (isScheduled) {
                    // Handle scheduled message deletion
                    const scheduledId = parseInt(deletingMessageState.el.dataset.scheduledId);
                    const scopeEl = deleteMessageModal && deleteMessageModal.querySelector('input[name="deleteScope"]:checked');
                    let scope = scopeEl ? (scopeEl.value || 'me') : 'me';
                    
                    if (deletingMessageState.forceDeleteForMe) {
                        scope = 'me';
                    }
                    
                    console.log('[SCHEDULED DELETE] Deleting scheduled message:', {
                        scheduledId,
                        scope,
                        hasMap: !!window.scheduledMessagesMap,
                        hasHidden: !!window.hiddenScheduledMessages
                    });
                    
                    try {
                        const sessionToken = getSessionTokenValue();
                        if (!sessionToken) {
                            alert('Missing session token. Please refresh and sign in again.');
                            return;
                        }

                        const res = await fetch(`delete_scheduled_message.php?token=${encodeURIComponent(sessionToken)}`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                token: sessionToken,
                                scheduled_id: scheduledId,
                                scope: scope
                            })
                        });
                        
                        const data = await res.json();
                        console.log('[SCHEDULED DELETE] Response:', data);
                        
                        if (data.success) {
                            if (scope === 'everyone') {
                                // Remove from map and DOM completely
                                if (window.scheduledMessagesMap) {
                                    window.scheduledMessagesMap.delete(scheduledId);
                                }
                                if (deletingMessageState.el) {
                                    deletingMessageState.el.remove();
                                }
                            } else {
                                // Just hide it locally
                                if (deletingMessageState.el) {
                                    deletingMessageState.el.remove();
                                }
                                // Add to hidden list so it doesn't reappear
                                if (!window.hiddenScheduledMessages) {
                                    window.hiddenScheduledMessages = new Set();
                                }
                                window.hiddenScheduledMessages.add(scheduledId);
                            }
                            invalidateSidebarHistoryCache({ reloadIfVisible: true });
                            showToast('Scheduled message deleted', 'success');
                        } else {
                            alert(data.error || 'Failed to delete scheduled message');
                        }
                    } catch (error) {
                        console.error('[delete scheduled message] error:', error);
                        alert('Network error while deleting scheduled message');
                    }
                    
                    closeDeleteMessageModal();
                    return;
                }
                
                // Regular message deletion
                const scopeEl = deleteMessageModal && deleteMessageModal.querySelector('input[name="deleteScope"]:checked');
                let scope = scopeEl ? (scopeEl.value || 'me') : 'me';
                
                // If forceDeleteForMe is true, always use 'me' scope
                if (deletingMessageState.forceDeleteForMe) {
                    scope = 'me';
                }
                
                const fd = new FormData();
                fd.append('token', token);
                fd.append('message_id', String(deletingMessageState.id));
                fd.append('scope', scope);
                
                // Debug: Log what we're sending
                console.log('[DELETE MESSAGE] Sending request:', {
                    token: token ? 'present' : 'missing',
                    message_id: deletingMessageState.id,
                    scope: scope
                });
                
                // Validate before sending
                if (!token || !deletingMessageState.id || deletingMessageState.id <= 0) {
                    console.error('[DELETE MESSAGE] Invalid parameters:', {
                        token: token ? 'present' : 'missing',
                        message_id: deletingMessageState.id,
                        scope: scope
                    });
                    alert('Error: Cannot delete message - invalid parameters');
                    closeDeleteMessageModal();
                    return;
                }
            
            let data = null;
            try {
                const res = await fetch('delete_message.php', { method: 'POST', body: fd });
                const responsePayload = await readJsonResponseSafely(res);
                data = responsePayload.data;
                if (!res.ok || !data || !data.success) {
                    const fallbackMessage = responsePayload.rawText
                        ? responsePayload.rawText.trim().replace(/\s+/g, ' ').slice(0, 220)
                        : '';
                    console.error('[delete message] HTTP error:', res.status, res.statusText, fallbackMessage);
                    alert((data && data.error) || fallbackMessage || ('Server error: ' + res.status));
                    closeDeleteMessageModal();
                    return;
                }
            } catch (err) {
                console.error('[delete message] error:', err);
                alert('Network error while deleting message');
                closeDeleteMessageModal();
                return;
            }
            
            if (data && data.success) {
                try {
                    const deletedChatKey = deletingMessageState.el && deletingMessageState.el._qtMessageRecord
                        ? String(getMessageChatKey(deletingMessageState.el._qtMessageRecord) || selectedUser || '')
                        : String(selectedUser || '');
                    clearPinnedMessageIfMatches(deletedChatKey, deletingMessageState.id);
                    if (deletingMessageState.el) {
                        removeMessageElementWithTimestampCleanup(deletingMessageState.el);
                    }
                } catch (e) { }
                invalidateSidebarHistoryCache({ reloadIfVisible: true });
                loadContactPreviews().catch(() => {});
            } else {
                alert((data && data.error) ? data.error : 'Failed to delete message');
            }
            
            closeDeleteMessageModal();
        });
    }

    if (reactionUsersModalClose) {
        reactionUsersModalClose.addEventListener('click', () => {
            if (reactionUsersModal) {
                reactionUsersModal.classList.remove('open');
                reactionUsersModal.setAttribute('aria-hidden', 'true');
            }
        });
    }

    if (reactPickerModalClose) {
        reactPickerModalClose.addEventListener('click', closeReactPickerModal);
    }

    if (reactPickerCancel) {
        reactPickerCancel.addEventListener('click', closeReactPickerModal);
    }

    if (reactPickerModal) {
        reactPickerModal.addEventListener('click', (event) => {
            if (event.target === reactPickerModal) {
                closeReactPickerModal();
            }
        });
    }

    if (reactPickerSearchInput) {
        reactPickerSearchInput.addEventListener('input', () => {
            renderReactPickerGrid(reactPickerActiveCategory);
        });
    }

    if (reactPickerGrid) {
        bindEmojiHoverTooltipDelegation(reactPickerGrid);
        reactPickerGrid.addEventListener('scroll', syncActiveReactPickerCategoryFromScroll);
    }

    window.addEventListener('quilltalk:emojis-loaded', () => {
        if (reactPickerModal && reactPickerModal.classList.contains('open')) {
            renderReactPickerTabs();
            renderReactPickerGrid(reactPickerActiveCategory);
            syncReactPickerApplyButton();
        }
    });
    
    // Listen for custom event to open delete modal for scheduled messages
    window.addEventListener('openScheduledDeleteModal', (e) => {
        console.log('[SCHEDULED DELETE EVENT] Custom event received:', e.detail);
        if (e.detail && e.detail.scheduledId && e.detail.messageElement) {
            openDeleteMessageModal(e.detail.scheduledId, e.detail.messageElement, false);
        }
    });

    if (reactPickerApply) {
        reactPickerApply.addEventListener('click', async () => {
            const messageIds = reactPickerMessageIds.length
                ? reactPickerMessageIds.slice()
                : [reactPickerMessageId].filter(value => Number(value) > 0);
            const mt = getCurrentChatMessageType();
            if (!messageIds.length) {
                closeReactPickerModal();
                return;
            }
            for (const mid of messageIds) {
                for (const em of reactPickerSelectedEmojis) {
                    await fetch('message_react.php', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ token, message_type: mt, message_id: mid, emoji: em, action: 'add' })
                    });
                    saveRecentReactionEmoji(em);
                }
            }
            closeReactPickerModal();
            if (messageSelectMode) {
                exitMessageSelectionMode();
            }
            await fetchReactionsForMessageIds(messageIds);
        });
    }

    setInterval(() => {
        if (selectedUser) {
            refreshReadReceipts();
            const ids = Array.from(chatBox.querySelectorAll('.message[data-id]'))
                .map(el => Number(el.dataset.messageId || el.dataset.id))
                .filter(id => id > 0);
            const slice = ids.slice(-80);
            if (slice.length) fetchReactionsForMessageIds(slice).catch(() => {});
        }
    }, 6000);

    // --- End Message Handling and UI ---

    // --- Contact and Friend Request Handling ---
    function clearActiveContacts() {
        contactsList.querySelectorAll('.contact').forEach(c => c.classList.remove('active'));
    }

    async function openConversation(contactRef, options = {}) {
        const directContactEl = contactRef && typeof contactRef === 'object' && contactRef.nodeType === 1
            ? contactRef
            : null;
        const normalizedContactId = directContactEl
            ? String(directContactEl.dataset && directContactEl.dataset.id ? directContactEl.dataset.id : '')
            : (contactRef ? String(contactRef) : '');
        const contactEl = directContactEl || (normalizedContactId ? getContactElement(normalizedContactId) : null);
        if (!normalizedContactId) {
            return;
        }

        if (!isMobileViewport() && getActiveContactView() !== 'contacts') {
            setActiveContactView('contacts');
        }

        const previousSelectedUser = selectedUser ? String(selectedUser) : '';
        if (messageSelectMode && previousSelectedUser && previousSelectedUser !== normalizedContactId) {
            exitMessageSelectionMode();
        }

        if (selectedUser && String(selectedUser) !== normalizedContactId) {
            if (messageInput) {
                setComposerDraft(previousSelectedUser, messageInput.value || '');
            }
            clearLocalTyping(true);
            hideTypingIndicator();
            hideEmojiPicker();
            clearPendingAttachment(true);
            pendingReply = null;
            updateReplyBar();
        }

        if (previousSelectedUser && previousSelectedUser !== normalizedContactId) {
            stopSummarySpeechPlayback();
        }

        clearActiveContacts();
        if (contactEl) {
            contactEl.classList.add('active');
        }
        selectedUser = normalizedContactId;
        groupMembersExpanded = false;

        // Mark notifications as read for this chat
        if (token) {
            fetch('mark_notifications_read.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token: token,
                    chat_key: normalizedContactId
                })
            }).then(response => response.json())
            .then(data => {
                if (data.success && data.notifications_marked_read > 0) {
                    console.log('[NOTIFICATIONS] Marked', data.notifications_marked_read, 'notifications as read for', data.chat_identifier);
                }
            })
            .catch(err => {
                console.log('[NOTIFICATIONS] Failed to mark notifications as read:', err);
            });
        }

        // For AI chats, ensure no unread dividers are placed
        if (normalizedContactId.startsWith('ai:')) {
            // Clear any existing unread dividers that might interfere
            setTimeout(() => {
                const existingDivider = chatBox.querySelector('.unread-divider');
                if (existingDivider) {
                    existingDivider.remove();
                }
            }, 200);
        }

        updateHeaderContact(selectedUser);
        hideTypingIndicator();
        hideEmojiPicker();
        restoreComposerDraft(selectedUser);
        updateDraftPreview();

        if (msgSearchPanel) {
            msgSearchPanel.classList.remove('is-open');
            msgSearchPanel.setAttribute('aria-hidden', 'true');
        }
        syncMsgSearchControlsVisibility(false, msgSearchControls);

        if (isMobileViewport()) {
            setMobileConversationVisibility(true);
        }

        const loadPromise = beginConversationLoad(normalizedContactId, {
            showLoadingState: true,
            loadingStateDelayMs: 0,
            scrollToBottomOnInitialLoad: !!(options && options.scrollToBottomOnInitialLoad)
        }).catch(err => {
            console.error('Failed to load messages:', err);
        });

        refreshUnreadBadges();

        // Dispatch event for scheduled messages
        window.dispatchEvent(new Event('conversationOpened'));

        // Open right sidebar on desktop for manually clicked contacts
        if (rightSidebar && !isMobileViewport() && selectedUser === normalizedContactId) {
            openRightSidebar(normalizedContactId);
        }

        return loadPromise;
    }

    // Make openConversation globally accessible for AI chat loading
    window.openConversation = openConversation;

    window.addEventListener('conversationOpened', () => {
        if (pendingRightSidebarRestoreUser) {
            window.setTimeout(runPendingRightSidebarRestore, 40);
        }
    });

    window.addEventListener('messagesLoaded', () => {
        if (pendingRightSidebarRestoreUser) {
            window.setTimeout(runPendingRightSidebarRestore, 40);
        }
    });

    function bindConversationActivation(element, resolveChatId) {
        if (!element || typeof resolveChatId !== 'function') {
            console.log('[BIND_ACTIVATION] Invalid element or resolveChatId');
            return;
        }

        if (element.dataset.conversationActivatorBound === '1') {
            console.log('[BIND_ACTIVATION] Already bound, skipping');
            return;
        }
        element.dataset.conversationActivatorBound = '1';
        const requiresDragGuard = element.classList.contains('mobile-contact-status-card') || element.classList.contains('contact');
        console.log('[BIND_ACTIVATION] Binding with dragGuard:', requiresDragGuard);

        const resolveConversationTarget = event => {
            const resolvedTarget = resolveChatId(event);
            const chatTarget = resolvedTarget && typeof resolvedTarget === 'object' && resolvedTarget.nodeType === 1
                ? resolvedTarget
                : String(resolvedTarget || '').trim();
            const chatId = chatTarget && typeof chatTarget === 'object' && chatTarget.nodeType === 1
                ? String(chatTarget.dataset.id || chatTarget.dataset.contactId || '')
                : String(chatTarget || '').trim();
            return { chatTarget, chatId };
        };

        const isInteractiveChildTarget = event => {
            const eventTarget = event && event.target && typeof event.target.closest === 'function'
                ? event.target.closest('button, a, input, textarea, select, label, [data-contact-action-trigger]')
                : null;
            return !!(eventTarget && eventTarget !== element);
        };

        const activateConversation = async event => {
            if (isInteractiveChildTarget(event)) {
                return false;
            }

            try {
                if (event && event.cancelable) event.preventDefault();
            } catch (error) {}
            try {
                if (event) event.stopPropagation();
            } catch (error) {}

            const { chatTarget, chatId } = resolveConversationTarget(event);
            if (!chatTarget) {
                return false;
            }

            if (
                chatId
                && (element.classList.contains('contact') || element.classList.contains('mobile-contact-status-card'))
                && ((isMobileViewport() && getActiveContactView() !== 'contacts') || isArchivedContactId(chatId))
            ) {
                return false;
            }

            try {
                await openConversation(chatTarget);
            } catch (error) {
                console.error('Conversation activation failed:', error);
            }

            return false;
        };

        if (!requiresDragGuard) {
            if (!element.hasAttribute('role')) {
                element.setAttribute('role', 'button');
            }
            if (!element.hasAttribute('tabindex')) {
                element.setAttribute('tabindex', '0');
            }

            addTapAndClickListener(element, activateConversation);
            element.addEventListener('keydown', event => {
                if (event.key === 'Enter' || event.key === ' ') {
                    activateConversation(event);
                }
            });
            return;
        }

        const scrollContainer = element.classList.contains('contact') ? contactsList : null;
        let pressTrackingActive = false;
        let hasRecordedPress = false;
        let pressInvalidated = false;
        let pressStartScrollTop = 0;
        let pressStartScrollLeft = 0;
        let longPressTimer = null;
        let longPressTriggered = false;
        const longPressDelay = 420;
        const longPressMoveTolerance = 10;

        const getClientPoint = event => {
            if (event && event.changedTouches && event.changedTouches.length) {
                return {
                    x: Number(event.changedTouches[0].clientX || 0),
                    y: Number(event.changedTouches[0].clientY || 0)
                };
            }
            if (event && event.touches && event.touches.length) {
                return {
                    x: Number(event.touches[0].clientX || 0),
                    y: Number(event.touches[0].clientY || 0)
                };
            }
            if (event && typeof event.clientX === 'number' && typeof event.clientY === 'number') {
                return {
                    x: event.clientX,
                    y: event.clientY
                };
            }
            return null;
        };

        const clearLongPress = () => {
            if (longPressTimer) {
                clearTimeout(longPressTimer);
                longPressTimer = null;
            }
        };

        const didScrollDuringPress = () => {
            if (!hasRecordedPress || !scrollContainer) {
                return false;
            }

            return (
                Math.abs(scrollContainer.scrollTop - pressStartScrollTop) > 0
                || Math.abs(scrollContainer.scrollLeft - pressStartScrollLeft) > 0
            );
        };

        const stopActivePressTracking = () => {
            pressTrackingActive = false;
            clearLongPress();
        };

        const clearPressState = () => {
            pressTrackingActive = false;
            hasRecordedPress = false;
            pressInvalidated = false;
            pressStartScrollTop = 0;
            pressStartScrollLeft = 0;
            clearLongPress();
        };

        const beginPressTracking = event => {
            if (isInteractiveChildTarget(event)) {
                clearPressState();
                return;
            }

            if (event && event.touches && event.touches.length !== 1) {
                clearPressState();
                return;
            }
            if (typeof event?.button === 'number' && event.button !== 0) {
                clearPressState();
                return;
            }

            pressTrackingActive = true;
            hasRecordedPress = true;
            pressInvalidated = false;
            if (scrollContainer) {
                pressStartScrollTop = scrollContainer.scrollTop;
                pressStartScrollLeft = scrollContainer.scrollLeft;
            }
        };

        const handleLongPressStart = event => {
            beginPressTracking(event);

            const isTouchSequence = !!(event && event.touches) || String(event && event.pointerType || '') === 'touch';
            if (!isTouchSequence || !isMobileViewport() || typeof openContactQuickActionsMenu !== 'function') {
                return;
            }

            longPressTriggered = false;
            const point = getClientPoint(event);
            if (!point) {
                clearLongPress();
                return;
            }

            const startX = point.x;
            const startY = point.y;
            const startScrollTop = scrollContainer ? scrollContainer.scrollTop : 0;
            const startScrollLeft = scrollContainer ? scrollContainer.scrollLeft : 0;
            clearLongPress();
            let longPressListenersBound = false;

            const cancelLongPressIfMoved = moveEvent => {
                const movePoint = getClientPoint(moveEvent);
                if (!movePoint) {
                    clearLongPress();
                    return;
                }

                if (
                    Math.abs(movePoint.x - startX) > longPressMoveTolerance
                    || Math.abs(movePoint.y - startY) > longPressMoveTolerance
                    || didScrollDuringPress()
                ) {
                    pressInvalidated = true;
                    clearLongPress();
                    unbindLongPressListeners();
                }
            };

            const cancelLongPress = () => {
                clearLongPress();
                unbindLongPressListeners();
            };

            const unbindLongPressListeners = () => {
                if (!longPressListenersBound) {
                    return;
                }
                longPressListenersBound = false;
                element.removeEventListener('touchmove', cancelLongPressIfMoved);
                element.removeEventListener('pointermove', cancelLongPressIfMoved);
                element.removeEventListener('touchend', cancelLongPress);
                element.removeEventListener('touchcancel', cancelLongPress);
                element.removeEventListener('pointerup', cancelLongPress);
                element.removeEventListener('pointercancel', cancelLongPress);
            };

            longPressTimer = window.setTimeout(() => {
                longPressTimer = null;
                if (
                    !pressTrackingActive
                    || didScrollDuringPress()
                    || (scrollContainer && (
                        Math.abs(scrollContainer.scrollTop - startScrollTop) > 0
                        || Math.abs(scrollContainer.scrollLeft - startScrollLeft) > 0
                    ))
                ) {
                    return;
                }

                const { chatId } = resolveConversationTarget(event);
                if (!chatId) {
                    return;
                }

                longPressTriggered = true;
                openContactQuickActionsMenu(chatId, {
                    source: 'longpress',
                    event,
                    chatContextKey: chatId
                });
                try {
                    if (navigator.vibrate) {
                        navigator.vibrate(8);
                }
                } catch (error) {}
                unbindLongPressListeners();
            }, longPressDelay);
            longPressListenersBound = true;
            element.addEventListener('touchmove', cancelLongPressIfMoved, { passive: true });
            element.addEventListener('pointermove', cancelLongPressIfMoved);
            element.addEventListener('touchend', cancelLongPress, { passive: true });
            element.addEventListener('touchcancel', cancelLongPress, { passive: true });
            element.addEventListener('pointerup', cancelLongPress);
            element.addEventListener('pointercancel', cancelLongPress);
        };

        if (!element.hasAttribute('role')) {
            element.setAttribute('role', 'button');
        }
        if (!element.hasAttribute('tabindex')) {
            element.setAttribute('tabindex', '0');
        }

        element.addEventListener('touchstart', handleLongPressStart, { passive: true });
        element.addEventListener('pointerdown', handleLongPressStart);
        element.addEventListener('touchcancel', () => {
            longPressTriggered = false;
            if (hasRecordedPress) {
                pressInvalidated = true;
            }
            stopActivePressTracking();
        }, { passive: true });
        element.addEventListener('pointercancel', () => {
            longPressTriggered = false;
            if (hasRecordedPress) {
                pressInvalidated = true;
            }
            stopActivePressTracking();
        });

        if (scrollContainer) {
            scrollContainer.addEventListener('scroll', () => {
                if (hasRecordedPress) {
                    pressInvalidated = true;
                }
            }, { passive: true });
        }

        addTapAndClickListener(element, async event => {
            if (longPressTriggered) {
                longPressTriggered = false;
                clearPressState();
                return false;
            }

            if (pressInvalidated || didScrollDuringPress()) {
                clearPressState();
                return false;
            }

            try {
                await activateConversation(event);
            } finally {
                clearPressState();
            }
            return false;
        });
        element.addEventListener('keydown', event => {
            if (event.key === 'Enter' || event.key === ' ') {
                activateConversation(event);
            }
        });
    }

    if (contactsList) {
        Array.from(contactsList.querySelectorAll('.contact')).forEach(contactEl => {
            bindConversationActivation(contactEl, () => contactEl);
            ensureContactActionControls(contactEl);
        });
    }

    function addContact(id, displayName, username, profilePic, online = 0, bio = '', createdAt = '', lastActivity = '', viewerHasBlocked = 0, blockedViewer = 0) {
        const contactKey = String(id || '').trim();
        if (!contactKey) {
            return null;
        }

        const normalizedOptions = arguments.length > 10 && typeof arguments[10] === 'object' && arguments[10] !== null
            ? arguments[10]
            : {};
        const chatType = normalizedOptions.chatType || getChatTypeFromKey(contactKey);
        const isCallOnlyGroup = chatType === 'group'
            && (
                callOnlyGroupIds.has(contactKey)
                || String(bio || '').trim() === CALL_ONLY_GROUP_DESCRIPTION
            );

        // Skip call-only groups (created for ad-hoc calls from the + menu)
        if (isCallOnlyGroup) {
            groupNamesMap[contactKey] = displayName || `Group ${getGroupIdFromChatKey(contactKey) || ''}`.trim();
            groupDescriptionsMap[contactKey] = String(bio || '');
            groupIconsMap[contactKey] = profilePic || DEFAULT_GROUP_CHAT_ICON;
            groupCreatedAtMap[contactKey] = createdAt || '';
            return null;
        }

        const entityId = Number(
            normalizedOptions.entityId
            || (
                chatType === 'group'
                    ? getGroupIdFromChatKey(contactKey)
                    : (chatType === 'ai' ? getAiChatIdFromChatKey(contactKey) : parseInt(contactKey, 10) || 0)
            )
        ) || 0;
        const memberCount = Number(normalizedOptions.memberCount || 0) || 0;
        const viewerRole = normalizeGroupRole(normalizedOptions.viewerRole || '');
        const viewerMutedUntil = String(normalizedOptions.viewerMutedUntil || '');
        const sendPermission = normalizeGroupSendPermission(normalizedOptions.sendPermission || '');
        const addMembersPermission = normalizeGroupAddPermission(normalizedOptions.addMembersPermission || '');
        const canManageGroup = !!normalizedOptions.canManageGroup;
        const canChangeRoles = !!normalizedOptions.canChangeRoles;
        const canDeleteGroup = !!normalizedOptions.canDeleteGroup;
        const canSendGroup = normalizedOptions.canSendGroup !== undefined ? !!normalizedOptions.canSendGroup : true;
        const notificationMode = normalizeChatNotificationMode(normalizedOptions.notificationMode || '');
        const chatNickname = normalizeChatScopedNicknameValue(normalizedOptions.chatNickname || '');
        const viewerChatNickname = normalizeChatScopedNicknameValue(normalizedOptions.viewerChatNickname || '');
        const safeDisplayName = displayName
            || username
            || (chatType === 'group'
                ? `Group ${entityId || ''}`.trim()
                : `User ${contactKey}`);
        const safeUsername = chatType === 'group' ? '' : (username || '');
        const safeProfilePic = normalizeProfilePic(profilePic, chatType);

        let contactEl = contactsList.querySelector(`.contact[data-id="${contactKey}"]`);
        if (!contactEl) {
            contactEl = document.createElement('div');
            contactEl.className = 'contact';

            const avatarWrap = document.createElement('div');
            avatarWrap.className = 'contact-img-wrapper';

            const image = document.createElement('img');
            image.className = 'contact-img';
            avatarWrap.appendChild(image);

            const indicator = document.createElement('span');
            indicator.className = 'online-indicator';
            avatarWrap.appendChild(indicator);

            const textWrap = document.createElement('div');
            textWrap.className = 'contact-text';

            const nameEl = document.createElement('div');
            nameEl.className = 'contact-name';
            textWrap.appendChild(nameEl);

            const previewEl = document.createElement('div');
            previewEl.className = 'contact-preview';
            textWrap.appendChild(previewEl);

            contactEl.appendChild(avatarWrap);
            contactEl.appendChild(textWrap);
            contactsList.appendChild(contactEl);
        }

        contactEl.dataset.id = contactKey;
        contactEl.dataset.chatType = chatType;
        contactEl.dataset.entityId = String(entityId || '');
        contactEl.dataset.memberCount = String(memberCount || 0);
        contactEl.dataset.online = online ? '1' : '0';
        contactEl.dataset.displayName = safeDisplayName;
        contactEl.dataset.username = safeUsername;
        contactEl.dataset.chatNickname = chatNickname;
        contactEl.dataset.viewerChatNickname = viewerChatNickname;
        contactEl.dataset.bio = bio || '';
        contactEl.dataset.createdAt = createdAt || '';
        const incomingLastActivity = parseContactActivityValue(lastActivity || createdAt || '');
        const currentLastActivity = parseContactActivityValue(contactEl.dataset.lastActivity || '');
        contactEl.dataset.lastActivity = String(Math.max(incomingLastActivity, currentLastActivity));
        contactEl.dataset.viewerBlocked = normalizeBlockFlag(viewerHasBlocked) ? '1' : '0';
        contactEl.dataset.blockedViewer = normalizeBlockFlag(blockedViewer) ? '1' : '0';
        contactEl.dataset.viewerRole = chatType === 'group' ? viewerRole : '';
        contactEl.dataset.viewerMutedUntil = chatType === 'group' ? viewerMutedUntil : '';
        contactEl.dataset.sendPermission = chatType === 'group' ? sendPermission : '';
        contactEl.dataset.addMembersPermission = chatType === 'group' ? addMembersPermission : '';
        contactEl.dataset.canManageGroup = chatType === 'group' && canManageGroup ? '1' : '0';
        contactEl.dataset.canChangeRoles = chatType === 'group' && canChangeRoles ? '1' : '0';
        contactEl.dataset.canDeleteGroup = chatType === 'group' && canDeleteGroup ? '1' : '0';
        contactEl.dataset.canSendGroup = chatType === 'group' && !canSendGroup ? '0' : '1';
        contactEl.dataset.notificationMode = notificationMode;
        bindConversationActivation(contactEl, () => contactEl.dataset.id || '');
        ensureContactActionControls(contactEl);

        const existingName = contactEl.querySelector('.contact-name');
        const existingImg = contactEl.querySelector('.contact-img');
        if (existingName) {
            // Use nickname if available, otherwise use display name
            const finalDisplayName = getDisplayNameForUser(contactKey, { displayName: safeDisplayName, username, isGroup: chatType === 'group' });
            console.log(`addContact(${contactKey}): Setting contact name to "${finalDisplayName}"`);
            existingName.textContent = finalDisplayName;
        }

        if (existingImg) {
            setProfileImage(existingImg, safeProfilePic, chatType, (fallbackPic) => {
                if (chatType === 'group') {
                    groupIconsMap[contactKey] = fallbackPic;
                } else {
                    userProfilePics[contactKey] = fallbackPic;
                }
            });
            existingImg.alt = safeDisplayName;
        }

        ensurePresenceIndicatorChildren(contactEl.querySelector('.online-indicator'));
        syncContactMapsFromElement(contactEl);
        setContactBlockState(contactKey, {
            viewerHasBlocked,
            blockedViewer
        });
        updateRenderedMessagePresence(contactKey);

        if (selectedUser && String(selectedUser) === contactKey) {
            contactEl.classList.add('active');
            updateHeaderContact(contactKey);
        }

        if (typingIndicatorUser && String(typingIndicatorUser) === contactKey && chatType === 'direct') {
            showTypingIndicator(contactKey);
        }

        updateContactActionControls(contactEl);
        refreshPresenceIndicatorsForUser(contactKey);
        sortContactsList();
    }

    // Make addContact globally accessible for AI chat loading
    window.addContact = addContact;

    async function pollContacts() {
        try {
            const res = await fetch(`fetch_contacts.php?token=${token}&t=${Date.now()}`);
            const contacts = await res.json();

            contacts.forEach(c => {
                const displayName = c.display_name || c.username;
                console.log(`Contact ${displayName}: online=${c.online}`);
                addContact(
                    c.id,
                    displayName,
                    c.username,
                    c.profile_pic,
                    c.online ? 1 : 0,
                    c.bio || '',
                    c.created_at || '',
                    c.last_message_at || '',
                    c.viewer_has_blocked || 0,
                    c.blocked_viewer || 0,
                    {
                        chatType: c.chat_type || getChatTypeFromKey(c.id),
                        entityId: c.entity_id || '',
                        memberCount: c.member_count || 0,
                        viewerRole: c.viewer_role || '',
                        viewerMutedUntil: c.viewer_muted_until || '',
                        sendPermission: c.send_permission || '',
                        addMembersPermission: c.add_members_permission || '',
                        canManageGroup: !!c.viewer_can_manage_group,
                        canChangeRoles: !!c.viewer_can_change_roles,
                        canDeleteGroup: !!c.viewer_can_delete_group,
                        canSendGroup: !!c.viewer_can_send,
                        notificationMode: c.notification_mode || 'all',
                        chatNickname: c.chat_nickname || '',
                        viewerChatNickname: c.viewer_chat_nickname || ''
                    }
                );
            });

            // Check if pending call user is now online
            if (pendingCallTo) {
                const pendingEl = contactsList.querySelector(`.contact[data-id="${pendingCallTo}"]`);
                if (pendingEl && getResolvedContactOnlineState(pendingCallTo, pendingEl) && !isConversationBlocked(pendingCallTo)) {
                    selectedUser = pendingCallTo;
                    updateHeaderContact(selectedUser);
                    if (!currentCall && !outgoingCallSetupInProgress) {
                        pendingCallTo = null;
                        skipOfflineCheck = true;
                        try {
                            await initiateCall();
                        } finally {
                            skipOfflineCheck = false;
                        }
                    }
                } else if (pendingEl && isConversationBlocked(pendingCallTo)) {
                    pendingCallTo = null;
                }
            }

            // NEW: Load AI chats first, then load previews and auto-select
            await loadAiChatsIfReady();
            await loadContactPreviews();
            await maybeOpenTopDesktopContact();
            syncStoredNotificationPrefsToServer();
			refreshUnreadBadges();

        } catch (e) {
            console.error('DEBUG: Error polling contacts:', e);
        }
    }
    pollContacts();
    setInterval(pollContacts, 10000);

    function setFriendRequestSearchStatus(message, state = '') {
        if (!friendRequestSearchStatus) return;
        friendRequestSearchStatus.textContent = message;
        if (state) {
            friendRequestSearchStatus.dataset.state = state;
        } else {
            delete friendRequestSearchStatus.dataset.state;
        }
    }

    function renderFriendRequestSearchEmpty(message) {
        if (!friendRequestSearchResults) return;
        friendRequestSearchResults.innerHTML = '';
        const empty = document.createElement('div');
        empty.className = 'friend-request-search-empty';
        empty.textContent = message;
        friendRequestSearchResults.appendChild(empty);
    }

    function closeAnyOpenDropdownMenus() {
        document.querySelectorAll('.dropdown-menu.show').forEach(menu => {
            menu.classList.remove('show');
        });
        document.querySelectorAll('[data-dropdown-toggle]').forEach(toggle => {
            toggle.setAttribute('aria-expanded', 'false');
            toggle.blur();
        });
    }

    function resetFriendRequestModalState() {
        clearTimeout(friendRequestSearchDebounceId);
        friendRequestSearchSequence += 1;
        if (friendRequestSearchInput) {
            friendRequestSearchInput.value = '';
        }
        setFriendRequestSearchStatus('Start typing to find someone.');
        renderFriendRequestSearchEmpty('Search results will appear here as you type.');
    }

    function openFriendRequestModal() {
        if (!friendRequestModal) return;
        closeAnyOpenDropdownMenus();
        resetFriendRequestModalState();
        friendRequestModal.classList.add('open');
        friendRequestModal.setAttribute('aria-hidden', 'false');
        if (friendRequestSearchInput) {
            setTimeout(() => friendRequestSearchInput.focus(), 20);
        }
    }

    function closeFriendRequestModal() {
        if (!friendRequestModal) return;
        clearTimeout(friendRequestSearchDebounceId);
        friendRequestSearchSequence += 1;
        friendRequestModal.classList.remove('open');
        friendRequestModal.setAttribute('aria-hidden', 'true');
    }

    function setGroupChatStatusMessage(message, state = '') {
        if (!groupChatStatus) return;
        groupChatStatus.textContent = message;
        if (state) {
            groupChatStatus.dataset.state = state;
        } else {
            delete groupChatStatus.dataset.state;
        }
    }

    function isGroupChatSingleFlowMode() {
        return !!(groupChatModal && groupChatModal.classList.contains('group-chat-modal-single-flow'));
    }

    function getAvailableGroupChatContacts() {
        return Array.from(contactsList.querySelectorAll('.contact')).filter(contactEl => {
            return getContactChatType(contactEl) === 'direct'
                && !isArchivedContactId(contactEl.dataset.id || '')
                && !normalizeBlockFlag(contactEl.dataset.viewerBlocked)
                && !normalizeBlockFlag(contactEl.dataset.blockedViewer);
        }).map(contactEl => ({
            id: String(contactEl.dataset.id || ''),
            displayName: String(contactEl.dataset.displayName || (contactEl.querySelector('.contact-name') ? contactEl.querySelector('.contact-name').textContent : '') || '').trim(),
            username: String(contactEl.dataset.username || '').trim(),
            profilePic: (contactEl.querySelector('.contact-img') ? contactEl.querySelector('.contact-img').src : defaultProfilePic) || defaultProfilePic,
            isOnline: getResolvedContactOnlineState(String(contactEl.dataset.id || ''), contactEl)
        })).filter(contact => contact.id);
    }

    function buildGroupChatSuggestedNameFromContacts(contacts) {
        const names = Array.from(new Set(
            contacts
                .map(contact => String(contact.displayName || contact.username || '').trim())
                .filter(Boolean)
        ));

        if (!names.length) {
            return 'New Group Chat';
        }

        if (names.length <= 3) {
            return names.join(', ');
        }

        return `${names.slice(0, 3).join(', ')} +${names.length - 3}`;
    }

    function getSelectedGroupChatContacts() {
        const selectedIds = new Set(Array.from(groupChatInviteSelection).map(value => String(value)));
        return getAvailableGroupChatContacts().filter(contact => selectedIds.has(contact.id));
    }

    function syncGroupChatNameSuggestion(force = false) {
        const suggestedName = buildGroupChatSuggestedNameFromContacts(getSelectedGroupChatContacts());
        groupChatSuggestedName = suggestedName;

        if (!groupChatNameInput) {
            return;
        }

        if (force || !groupChatNameTouched || !groupChatNameInput.value.trim() || groupChatNameInput.value === groupChatSuggestedName) {
            groupChatNameInput.value = suggestedName;
            groupChatNameTouched = false;
        }
    }

    function updateGroupChatSelectionUi() {
        const count = groupChatInviteSelection.size;

        if (groupChatSelectedCount) {
            groupChatSelectedCount.textContent = `${count} selected`;
        }

        if (groupChatMembersNext) {
            groupChatMembersNext.disabled = count === 0;
        }

        const checkboxes = groupChatMembersList
            ? Array.from(groupChatMembersList.querySelectorAll('input[type="checkbox"][data-group-chat-member-id]'))
            : [];
        const checkedCount = checkboxes.filter(input => input.checked).length;

        if (groupChatSelectAll) {
            groupChatSelectAll.checked = checkboxes.length > 0 && checkedCount === checkboxes.length;
            groupChatSelectAll.indeterminate = checkedCount > 0 && checkedCount < checkboxes.length;
            groupChatSelectAll.disabled = checkboxes.length === 0;
        }

        const isMembersStepVisible = !!(groupChatStepMembers && !groupChatStepMembers.hidden);
        if (groupChatStatus && groupChatStatus.dataset.state !== 'pending') {
            if (count === 0) {
                setGroupChatStatusMessage('Choose at least one contact to continue.');
            } else {
                setGroupChatStatusMessage(
                    isMembersStepVisible
                        ? 'Choose more contacts or continue when you are ready.'
                        : 'Ready to create your group chat.'
                );
            }
        }
    }

    function renderGroupChatMembersList() {
        if (!groupChatMembersList) return;

        const contacts = getAvailableGroupChatContacts();
        groupChatMembersList.innerHTML = '';
        groupChatInviteSelection = new Set(
            Array.from(groupChatInviteSelection)
                .map(value => String(value))
                .filter(value => contacts.some(contact => contact.id === value))
        );

        if (!contacts.length) {
            const empty = document.createElement('div');
            empty.className = 'friend-request-search-empty';
            empty.textContent = 'You need at least one unblocked contact before you can create a group chat.';
            groupChatMembersList.appendChild(empty);
            updateGroupChatSelectionUi();
            return;
        }

        contacts.forEach(contact => {
            const card = document.createElement('label');
            card.className = 'group-chat-member-card';

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.dataset.groupChatMemberId = contact.id;
            checkbox.checked = groupChatInviteSelection.has(contact.id);
            checkbox.addEventListener('change', () => {
                if (checkbox.checked) {
                    groupChatInviteSelection.add(contact.id);
                } else {
                    groupChatInviteSelection.delete(contact.id);
                }
                updateGroupChatSelectionUi();
                syncGroupChatNameSuggestion();
            });

            const image = document.createElement('img');
            image.src = contact.profilePic || defaultProfilePic;
            image.alt = contact.displayName || contact.username || 'Contact';

            const copy = document.createElement('div');
            copy.className = 'group-chat-member-copy';

            const name = document.createElement('div');
            name.className = 'group-chat-member-name';
            const memberDisplayName = getDisplayNameForUser(String(contact.id), {
                displayName: contact.displayName,
                username: contact.username,
                isGroup: false
            });
            name.textContent = memberDisplayName;

            const meta = document.createElement('div');
            meta.className = 'group-chat-member-meta';
            meta.textContent = contact.username ? `@${contact.username}` : 'Contact';

            copy.appendChild(name);
            copy.appendChild(meta);

            const status = document.createElement('div');
            status.className = `group-chat-member-status${contact.isOnline ? ' online' : ''}`;
            status.textContent = contact.isOnline ? 'Online' : 'Offline';

            card.appendChild(checkbox);
            card.appendChild(image);
            card.appendChild(copy);
            card.appendChild(status);
            groupChatMembersList.appendChild(card);
        });

        updateGroupChatSelectionUi();
    }

    function setGroupChatStep(step) {
        if (isGroupChatSingleFlowMode()) {
            if (groupChatStepMembers) {
                groupChatStepMembers.classList.add('active');
                groupChatStepMembers.hidden = false;
            }

            if (groupChatStepDetails) {
                groupChatStepDetails.classList.add('active');
                groupChatStepDetails.hidden = false;
            }

            if (groupChatModalTitle) {
                groupChatModalTitle.textContent = 'Create Group Chat';
            }

            if (groupChatModalSubtitle) {
                groupChatModalSubtitle.textContent = 'Choose who you want to invite, then customize your group chat.';
            }
            return;
        }

        const showMembers = step !== 'details';

        if (groupChatStepMembers) {
            groupChatStepMembers.classList.toggle('active', showMembers);
            groupChatStepMembers.hidden = !showMembers;
        }

        if (groupChatStepDetails) {
            groupChatStepDetails.classList.toggle('active', !showMembers);
            groupChatStepDetails.hidden = showMembers;
        }

        if (groupChatModalTitle) {
            groupChatModalTitle.textContent = showMembers ? 'Group Chat' : 'Customize Group Chat';
        }

        if (groupChatModalSubtitle) {
            groupChatModalSubtitle.textContent = showMembers
                ? 'Choose who you want to invite to this group chat.'
                : 'Give your group chat a name, description, and icon.';
        }
    }

    function resetGroupChatIconPreview() {
        if (groupChatIconObjectUrl) {
            URL.revokeObjectURL(groupChatIconObjectUrl);
            groupChatIconObjectUrl = '';
        }

        groupChatSelectedIconFile = null;
        if (groupChatIconInput) {
            groupChatIconInput.value = '';
        }
        if (groupChatIconPreview) {
            groupChatIconPreview.src = DEFAULT_GROUP_CHAT_ICON;
        }
    }

    function resetGroupChatModalState() {
        groupChatInviteSelection = new Set();
        groupChatNameTouched = false;
        groupChatSuggestedName = '';
        renderGroupChatMembersList();
        updateGroupChatSelectionUi();
        setGroupChatStep('members');
        resetGroupChatIconPreview();

        if (groupChatDescriptionInput) {
            groupChatDescriptionInput.value = '';
        }

        if (groupChatNameInput) {
            groupChatNameInput.value = '';
        }

        syncGroupChatNameSuggestion(true);
        setGroupChatStatusMessage('Choose at least one contact to continue.');
    }

    function openGroupChatModal() {
        if (!groupChatModal) return;
        closeAnyOpenDropdownMenus();
        resetGroupChatModalState();
        groupChatModal.classList.add('open');
        groupChatModal.setAttribute('aria-hidden', 'false');
    }

    function closeGroupChatModal() {
        if (!groupChatModal) return;
        groupChatModal.classList.remove('open');
        groupChatModal.setAttribute('aria-hidden', 'true');
        resetGroupChatIconPreview();
    }

    function createFriendRequestResult(user) {
        const displayName = user.display_name && user.display_name.trim()
            ? user.display_name.trim()
            : user.username;
        const avatar = user.profile_pic && String(user.profile_pic).trim()
            ? String(user.profile_pic)
            : defaultProfilePic;
        const isOnline = Number(user.online) === 1;

        const row = document.createElement('div');
        row.className = 'friend-request-result';

        const avatarWrap = document.createElement('div');
        avatarWrap.className = 'friend-request-result-avatar-wrap';

        const image = document.createElement('img');
        image.className = 'friend-request-result-avatar';
        image.src = avatar;
        image.alt = displayName;
        image.addEventListener('error', () => {
            image.src = defaultProfilePic;
        }, { once: true });
        avatarWrap.appendChild(image);

        const status = document.createElement('span');
        status.className = `friend-request-result-status${isOnline ? ' online' : ''}`;
        status.setAttribute('aria-hidden', 'true');
        avatarWrap.appendChild(status);

        row.appendChild(avatarWrap);

        const body = document.createElement('div');
        body.className = 'friend-request-result-body';

        const name = document.createElement('p');
        name.className = 'friend-request-result-name';
        name.textContent = displayName;
        body.appendChild(name);

        const username = document.createElement('p');
        username.className = 'friend-request-result-username';
        username.textContent = `@${user.username}`;
        body.appendChild(username);

        row.appendChild(body);

        const action = document.createElement('button');
        action.type = 'button';
        action.className = 'friend-request-result-action';
        action.textContent = 'Send Request';
        action.addEventListener('click', async () => {
            const originalLabel = action.textContent;
            action.disabled = true;
            action.textContent = 'Sending...';

            try {
                const fd = new FormData();
                fd.append('token', token);
                fd.append('receiver_id', user.id);
                const sendRes = await fetch('send_friend_request.php', { method: 'POST', body: fd });
                const json = await sendRes.json();
                if (json.success) {
                    action.textContent = 'Sent';
                    setFriendRequestSearchStatus(`Friend request sent to ${displayName}.`, 'success');
                    return;
                }

                action.disabled = false;
                action.textContent = originalLabel;
                setFriendRequestSearchStatus(json.error || 'Failed to send friend request.', 'error');
            } catch (error) {
                action.disabled = false;
                action.textContent = originalLabel;
                setFriendRequestSearchStatus('Network error while sending the friend request.', 'error');
            }
        });
        row.appendChild(action);

        return row;
    }

    function renderFriendRequestSearchResults(users, query) {
        if (!friendRequestSearchResults) return;

        const filteredUsers = users.filter(user => String(user.id) !== String(currentUserId));
        friendRequestSearchResults.innerHTML = '';

        if (!filteredUsers.length) {
            setFriendRequestSearchStatus(`No people matched "${query}".`);
            renderFriendRequestSearchEmpty('No matching people found yet. Try another username or display name.');
            return;
        }

        setFriendRequestSearchStatus(`${filteredUsers.length} result${filteredUsers.length === 1 ? '' : 's'} found.`);
        filteredUsers.forEach(user => {
            friendRequestSearchResults.appendChild(createFriendRequestResult(user));
        });
    }

    async function performFriendRequestSearch(query) {
        const requestId = ++friendRequestSearchSequence;

        try {
            const res = await fetch(`search_users.php?token=${token}&query=${encodeURIComponent(query)}`);
            if (!res.ok) {
                throw new Error('Network error');
            }

            const users = await res.json();
            if (requestId !== friendRequestSearchSequence) {
                return;
            }

            renderFriendRequestSearchResults(Array.isArray(users) ? users : [], query);
        } catch (error) {
            if (requestId !== friendRequestSearchSequence) {
                return;
            }
            setFriendRequestSearchStatus('Could not search right now. Please try again.', 'error');
            renderFriendRequestSearchEmpty('Search is temporarily unavailable.');
        }
    }

    if (friendRequestSearchInput) {
        friendRequestSearchInput.addEventListener('input', () => {
            clearTimeout(friendRequestSearchDebounceId);
            const query = friendRequestSearchInput.value.trim();

            if (!query) {
                friendRequestSearchSequence += 1;
                setFriendRequestSearchStatus('Start typing to find someone.');
                renderFriendRequestSearchEmpty('Search results will appear here as you type.');
                return;
            }

            friendRequestSearchDebounceId = setTimeout(() => {
                performFriendRequestSearch(query);
            }, 180);
        });
    }

    friendRequestModalOpeners.forEach(opener => {
        opener.addEventListener('click', event => {
            event.preventDefault();
            openFriendRequestModal();
        });
    });

    if (friendRequestModalClose) {
        friendRequestModalClose.addEventListener('click', () => {
            closeFriendRequestModal();
        });
    }

    groupChatModalOpeners.forEach(opener => {
        opener.addEventListener('click', event => {
            event.preventDefault();
            openGroupChatModal();
        });
    });

    // ─── AI Chat Modal ────────────────────────────────────────────────────────
    let aiChatIconFile = null;
    
    function openAiChatModal() {
        if (!aiChatModal) return;
        
        // Reset form
        if (aiChatNameInput) aiChatNameInput.value = '';
        if (aiChatBioInput) aiChatBioInput.value = '';
        if (aiChatNotesInput) aiChatNotesInput.value = '';
        if (aiChatIconPreview) aiChatIconPreview.src = DEFAULT_AI_PROFILE_PIC;
        aiChatIconFile = null;
        if (aiChatStatus) aiChatStatus.textContent = 'Ready to create your AI chat.';
        
        bringOverlayToFront(aiChatModal, 3);
        aiChatModal.classList.add('open');
        aiChatModal.setAttribute('aria-hidden', 'false');
        closeAnyOpenDropdownMenus();
    }
    
    function closeAiChatModal() {
        if (!aiChatModal) return;
        aiChatModal.classList.remove('open');
        aiChatModal.setAttribute('aria-hidden', 'true');
        resetOverlayZIndex(aiChatModal);
    }
    
    aiChatModalOpeners.forEach(opener => {
        opener.addEventListener('click', event => {
            event.preventDefault();
            openAiChatModal();
        });
    });
    
    if (aiChatModalClose) {
        aiChatModalClose.addEventListener('click', () => {
            closeAiChatModal();
        });
    }
    
    if (aiChatCancelBtn) {
        aiChatCancelBtn.addEventListener('click', () => {
            closeAiChatModal();
        });
    }
    
    if (aiChatIconTrigger && aiChatIconInput) {
        aiChatIconTrigger.addEventListener('click', () => {
            aiChatIconInput.click();
        });
        
        aiChatIconInput.addEventListener('change', () => {
            const file = aiChatIconInput.files && aiChatIconInput.files[0];
            if (!file) return;
            
            aiChatIconFile = file;
            const reader = new FileReader();
            reader.onload = (e) => {
                if (aiChatIconPreview) {
                    aiChatIconPreview.src = e.target.result;
                }
                if (aiChatStatus) {
                    aiChatStatus.textContent = 'AI icon ready to save.';
                }
            };
            reader.readAsDataURL(file);
        });
    }
    
    if (aiChatCreateBtn) {
        aiChatCreateBtn.addEventListener('click', async () => {
            const displayName = (aiChatNameInput ? aiChatNameInput.value.trim() : '') || 'QuillTalk AI';
            const bio = aiChatBioInput ? aiChatBioInput.value.trim() : '';
            const notes = aiChatNotesInput ? aiChatNotesInput.value.trim() : '';
            
            if (aiChatStatus) aiChatStatus.textContent = 'Creating AI chat...';
            if (aiChatCreateBtn) aiChatCreateBtn.disabled = true;
            
            try {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('display_name', displayName);
                formData.append('bio', bio);
                formData.append('notes', notes);
                
                if (aiChatIconFile) {
                    formData.append('profile_pic', aiChatIconFile);
                }
                
                const response = await fetch('create_ai_chat.php', {
                    method: 'POST',
                    body: formData
                });
                
                const data = await response.json();
                
                if (data.success) {
                    if (aiChatStatus) aiChatStatus.textContent = 'AI chat created successfully!';
                    console.log('AI chat created:', data);
                    
                    // Add to contacts and open chat
                    const aiChatKey = `ai:${data.ai_chat_id}`;
                    
                    // Store AI chat data
                    if (!window.aiChatsMap) window.aiChatsMap = {};
                    window.aiChatsMap[aiChatKey] = {
                        id: data.ai_chat_id,
                        displayName: displayName,
                        bio: bio,
                        notes: notes,
                        profilePic: data.profile_pic || DEFAULT_AI_PROFILE_PIC
                    };
                    
                    // Add to contacts list
                    if (typeof addContact === 'function') {
                        addContact(
                            aiChatKey,
                            displayName,
                            '',
                            data.profile_pic || DEFAULT_AI_PROFILE_PIC,
                            0,
                            bio
                        );
                    } else {
                        console.error('addContact function not available');
                    }
                    
                    closeAiChatModal();
                    
                    // Open the AI chat and send initial greeting
                    setTimeout(async () => {
                        // Find the contact element and open conversation
                        const contactEl = contactsList.querySelector(`.contact[data-id="${aiChatKey}"]`);
                        if (contactEl && typeof openConversation === 'function') {
                            await openConversation(contactEl);
                        } else {
                            console.error('Contact element not found or openConversation not available');
                        }
                        
                        // Send initial greeting message
                        try {
                            const greetingMsg = `Hi! I'm ${displayName}. How can I help you today?`;
                            const formData = new FormData();
                            formData.append('token', token);
                            formData.append('ai_chat_key', aiChatKey);
                            formData.append('message', greetingMsg);
                            formData.append('sender_type', 'ai');
                            
                            const res = await fetch('send_ai_message.php', {
                                method: 'POST',
                                body: formData
                            });
                            
                            if (res.ok) {
                                const msgData = await res.json();
                                if (msgData.success) {
                                    console.log('AI greeting sent');
                                    // Add the greeting message to the chat if it's currently open
                                    if (msgData.message && selectedUser === aiChatKey) {
                                        appendMessage(msgData.message);
                                    }
                                } else {
                                    console.error('AI greeting failed:', msgData.error);
                                }
                            } else {
                                console.error('AI greeting HTTP error:', res.status);
                            }
                        } catch (e) {
                            console.error('Failed to send AI greeting:', e);
                        }
                    }, 100);
                } else {
                    if (aiChatStatus) aiChatStatus.textContent = data.error || 'Failed to create AI chat';
                    console.error('AI chat creation failed:', data);
                }
            } catch (error) {
                console.error('AI chat creation error:', error);
                if (aiChatStatus) aiChatStatus.textContent = 'Network error. Please try again.';
            } finally {
                if (aiChatCreateBtn) aiChatCreateBtn.disabled = false;
            }
        });
    }

    // ─── AI Settings Modal ────────────────────────────────────────────────────
    let aiSettingsIconFile = null;
    let aiSettingsClearIconPending = false;

    function resetAiSettingsIconSelection() {
        aiSettingsIconFile = null;
        aiSettingsClearIconPending = false;
        if (aiSettingsIconInput) {
            aiSettingsIconInput.value = '';
        }
    }
    
    function openAiSettingsModal(chatKey) {
        if (!aiSettingsModal || !chatKey || !chatKey.startsWith('ai:')) return;
        
        currentAiSettingsChatKey = chatKey;
        const aiData = window.aiChatsMap && window.aiChatsMap[chatKey];
        
        if (!aiData) {
            showToast('AI chat not found', 'error');
            return;
        }
        
        // Populate form with current data
        if (aiSettingsNameInput) aiSettingsNameInput.value = aiData.displayName || '';
        if (aiSettingsBioInput) aiSettingsBioInput.value = aiData.bio || '';
        if (aiSettingsNotesInput) {
            const parsedNotes = parseSidequestBotAiChatNotes(aiData.notes || '');
            aiSettingsNotesInput.value = parsedNotes.meta ? parsedNotes.instructions : (aiData.notes || '');
        }
        if (aiSettingsIconPreview) aiSettingsIconPreview.src = aiData.profilePic || DEFAULT_AI_PROFILE_PIC;
        resetAiSettingsIconSelection();
        if (aiSettingsStatus) aiSettingsStatus.textContent = 'Ready to save changes.';
        
        bringOverlayToFront(aiSettingsModal, 3);
        aiSettingsModal.classList.add('open');
        aiSettingsModal.setAttribute('aria-hidden', 'false');
        closeAnyOpenDropdownMenus();
    }
    
    function closeAiSettingsModal() {
        if (!aiSettingsModal) return;
        aiSettingsModal.classList.remove('open');
        aiSettingsModal.setAttribute('aria-hidden', 'true');
        resetOverlayZIndex(aiSettingsModal);
        currentAiSettingsChatKey = null;
        resetAiSettingsIconSelection();
    }
    
    if (aiSettingsModalClose) {
        aiSettingsModalClose.addEventListener('click', () => {
            closeAiSettingsModal();
        });
    }
    
    if (aiSettingsCancelBtn) {
        aiSettingsCancelBtn.addEventListener('click', () => {
            closeAiSettingsModal();
        });
    }
    
    if (aiSettingsIconTrigger && aiSettingsIconInput) {
        aiSettingsIconTrigger.addEventListener('click', () => {
            aiSettingsIconInput.click();
        });
        
        aiSettingsIconInput.addEventListener('change', () => {
            const file = aiSettingsIconInput.files && aiSettingsIconInput.files[0];
            if (!file) return;
            
            aiSettingsIconFile = file;
            aiSettingsClearIconPending = false;
            const reader = new FileReader();
            reader.onload = (e) => {
                if (aiSettingsIconPreview) {
                    aiSettingsIconPreview.src = e.target.result;
                }
                if (aiSettingsStatus) {
                    aiSettingsStatus.textContent = 'AI icon ready to save.';
                }
            };
            reader.readAsDataURL(file);
        });
    }

    if (aiSettingsClearIcon) {
        aiSettingsClearIcon.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            resetAiSettingsIconSelection();
            aiSettingsClearIconPending = true;
            if (aiSettingsIconPreview) {
                aiSettingsIconPreview.src = DEFAULT_AI_PROFILE_PIC;
            }
            if (aiSettingsStatus) {
                aiSettingsStatus.textContent = 'The AI profile picture will be cleared when you save.';
            }
        });
    }
    
    if (aiSettingsSaveBtn) {
        aiSettingsSaveBtn.addEventListener('click', async () => {
            if (!currentAiSettingsChatKey) return;

            const activeAiSettingsChatKey = currentAiSettingsChatKey;
            const shouldClearAiSettingsIcon = aiSettingsClearIconPending;
            const aiData = window.aiChatsMap && window.aiChatsMap[activeAiSettingsChatKey];
            if (!aiData) return;
            
            const displayName = (aiSettingsNameInput ? aiSettingsNameInput.value.trim() : '') || 'QuillTalk AI';
            const bio = aiSettingsBioInput ? aiSettingsBioInput.value.trim() : '';
            let notes = aiSettingsNotesInput ? aiSettingsNotesInput.value.trim() : '';
            const parsedNotes = parseSidequestBotAiChatNotes(aiData.notes || '');
            if (parsedNotes.meta) {
                notes = buildSidequestBotAiChatNotes(parsedNotes.meta, notes);
            }
            
            if (aiSettingsStatus) aiSettingsStatus.textContent = 'Saving changes...';
            if (aiSettingsSaveBtn) aiSettingsSaveBtn.disabled = true;
            
            try {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('ai_chat_id', String(aiData.id));
                formData.append('display_name', displayName);
                formData.append('bio', bio);
                formData.append('notes', notes);
                formData.append('clear_profile_pic', shouldClearAiSettingsIcon ? '1' : '0');
                
                if (aiSettingsIconFile) {
                    formData.append('profile_pic', aiSettingsIconFile);
                }
                
                const response = await fetch('update_ai_chat.php', {
                    method: 'POST',
                    body: formData
                });
                
                const data = await response.json();
                
                if (data.success) {
                    if (aiSettingsStatus) aiSettingsStatus.textContent = 'Changes saved successfully!';

                    const savedProfilePic = shouldClearAiSettingsIcon
                        ? DEFAULT_AI_PROFILE_PIC
                        : (data.profile_pic || DEFAULT_AI_PROFILE_PIC);
                    cacheAiChatRecord(activeAiSettingsChatKey, {
                        id: aiData.id,
                        displayName,
                        bio,
                        notes,
                        profilePic: savedProfilePic
                    });
                    syncAiChatContact(activeAiSettingsChatKey);

                    // Refresh if this chat is currently open
                    if (String(selectedUser) === activeAiSettingsChatKey) {
                        updateHeaderContact(activeAiSettingsChatKey);
                        refreshOpenProfileViews(activeAiSettingsChatKey);
                    }
                    
                    setTimeout(() => {
                        closeAiSettingsModal();
                    }, 1000);
                } else {
                    if (aiSettingsStatus) aiSettingsStatus.textContent = data.error || 'Failed to save changes';
                }
            } catch (error) {
                console.error('AI settings update error:', error);
                if (aiSettingsStatus) aiSettingsStatus.textContent = 'Network error. Please try again.';
            } finally {
                if (aiSettingsSaveBtn) aiSettingsSaveBtn.disabled = false;
            }
        });
    }
    
    // Clear AI Memory functionality
    if (aiClearMemoryBtn) {
        aiClearMemoryBtn.addEventListener('click', () => {
            if (clearAiMemoryModal) {
                bringOverlayToFront(clearAiMemoryModal, 10);
                clearAiMemoryModal.classList.add('open');
                clearAiMemoryModal.setAttribute('aria-hidden', 'false');
                clearAiMemoryModal.style.display = 'flex';
            }
        });
    }
    
    function closeClearAiMemoryModal() {
        if (clearAiMemoryModal) {
            clearAiMemoryModal.classList.remove('open');
            clearAiMemoryModal.setAttribute('aria-hidden', 'true');
            clearAiMemoryModal.style.display = 'none';
        }
        resetOverlayZIndex(clearAiMemoryModal);
    }
    
    if (clearAiMemoryModalClose) {
        clearAiMemoryModalClose.addEventListener('click', () => {
            closeClearAiMemoryModal();
        });
    }
    
    if (clearAiMemoryCancelBtn) {
        clearAiMemoryCancelBtn.addEventListener('click', () => {
            closeClearAiMemoryModal();
        });
    }
    
    if (clearAiMemoryConfirmBtn) {
        clearAiMemoryConfirmBtn.addEventListener('click', async () => {
            if (!currentAiSettingsChatKey) {
                console.error('No current AI chat key');
                return;
            }
            
            const aiData = window.aiChatsMap && window.aiChatsMap[currentAiSettingsChatKey];
            if (!aiData) {
                console.error('No AI data found for key:', currentAiSettingsChatKey);
                return;
            }
            
            console.log('Clearing AI memory for chat:', currentAiSettingsChatKey, 'AI ID:', aiData.id);
            
            clearAiMemoryConfirmBtn.disabled = true;
            clearAiMemoryConfirmBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i><span>Clearing...</span>';
            
            try {
                const formData = new FormData();
                formData.append('token', token);
                formData.append('ai_chat_id', String(aiData.id));
                
                console.log('Sending clear memory request with AI chat ID:', aiData.id);
                
                const response = await fetch('clear_ai_memory.php', {
                    method: 'POST',
                    body: formData
                });
                
                console.log('Clear memory response status:', response.status);
                
                const data = await response.json();
                console.log('Clear memory response data:', data);
                
                if (data.success) {
                    // Close the confirmation modal
                    closeClearAiMemoryModal();
                    
                    // Update status in AI settings modal
                    if (aiSettingsStatus) {
                        aiSettingsStatus.textContent = 'AI memory cleared successfully!';
                        aiSettingsStatus.style.color = 'var(--text-success, #28a745)';
                    }
                    
                    // Reset status color after a delay
                    setTimeout(() => {
                        if (aiSettingsStatus) {
                            aiSettingsStatus.style.color = '';
                            aiSettingsStatus.textContent = 'Ready to save changes.';
                        }
                    }, 3000);
                } else {
                    console.error('Clear memory failed:', data.error);
                    alert(data.error || 'Failed to clear AI memory. Please try again.');
                }
            } catch (error) {
                console.error('Clear AI memory error:', error);
                alert('Network error. Please try again.');
            } finally {
                clearAiMemoryConfirmBtn.disabled = false;
                clearAiMemoryConfirmBtn.innerHTML = '<i class="fa-solid fa-brain" aria-hidden="true"></i><span>Clear Memory</span>';
            }
        });
    }
    
    // Make function globally accessible
    window.openAiSettingsModal = openAiSettingsModal;

    // ─── Add Members Modal ────────────────────────────────────────────────────
    const addMembersModal = document.getElementById('addMembersModal');
    const addMembersModalClose = document.getElementById('addMembersModalClose');
    const addMembersList = document.getElementById('addMembersList');
    const addMembersSelectAll = document.getElementById('addMembersSelectAll');
    const addMembersSelectedCount = document.getElementById('addMembersSelectedCount');
    const addMembersConfirm = document.getElementById('addMembersConfirm');
    const addMembersStatus = document.getElementById('addMembersStatus');
    let addMembersSelection = new Set();
    let addMembersTargetGroupKey = '';

    function updateAddMembersButtonState(userId) {
        const normalizedUserId = userId ? String(userId) : '';
        const meta = normalizedUserId ? getContactMeta(normalizedUserId) : null;
        const isGroup = !!(meta && meta.isGroup);

        [addMembersBtnDesktop, addMembersBtnMobile].forEach(btn => {
            if (!btn) return;
            if (!isGroup) { btn.style.display = 'none'; btn.dataset.forceHidden = '1'; return; }
            btn.style.display = '';
            delete btn.dataset.forceHidden;
            const addPerm = meta.addMembersPermission || GROUP_ADD_PERMISSION_ADMINS;
            const canAdd = addPerm === GROUP_ADD_PERMISSION_ALL || meta.canManageGroup;
            btn.classList.toggle('icon-disabled', !canAdd);
            btn.setAttribute('aria-disabled', canAdd ? 'false' : 'true');
            btn.title = canAdd
                ? 'Add members'
                : 'You do not have the required permissions to add new members. Ask an owner or admin for access.';
        });
    }

    function updateAddMembersSelectionUi() {
        const count = addMembersSelection.size;
        if (addMembersSelectedCount) addMembersSelectedCount.textContent = `${count} selected`;
        if (addMembersConfirm) addMembersConfirm.disabled = count === 0;
        if (addMembersList) {
            const checkboxes = Array.from(addMembersList.querySelectorAll('input[type="checkbox"][data-contact-id]'));
            const checked = checkboxes.filter(c => c.checked).length;
            if (addMembersSelectAll) {
                addMembersSelectAll.checked = checkboxes.length > 0 && checked === checkboxes.length;
                addMembersSelectAll.indeterminate = checked > 0 && checked < checkboxes.length;
                addMembersSelectAll.disabled = checkboxes.length === 0;
            }
        }
    }

    function renderAddMembersList(groupKey) {
        if (!addMembersList) return;
        addMembersList.innerHTML = '';
        addMembersSelection = new Set();

        // Get current group member IDs to exclude them
        const currentMembers = new Set(
            (groupMembersMap[groupKey] || []).map(m => String(m.user_id || m.id || ''))
        );

        const contacts = getAvailableGroupChatContacts().filter(c => !currentMembers.has(c.id));

        if (!contacts.length) {
            const empty = document.createElement('div');
            empty.className = 'friend-request-search-empty';
            empty.textContent = 'All your contacts are already in this group.';
            addMembersList.appendChild(empty);
            updateAddMembersSelectionUi();
            return;
        }

        contacts.forEach(contact => {
            const card = document.createElement('label');
            card.className = 'group-chat-member-card';

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.dataset.contactId = contact.id;
            checkbox.addEventListener('change', () => {
                if (checkbox.checked) addMembersSelection.add(contact.id);
                else addMembersSelection.delete(contact.id);
                updateAddMembersSelectionUi();
            });

            const img = document.createElement('img');
            img.src = contact.profilePic || defaultProfilePic;
            img.alt = contact.displayName || contact.username || 'Contact';

            const copy = document.createElement('div');
            copy.className = 'group-chat-member-copy';

            const name = document.createElement('div');
            name.className = 'group-chat-member-name';
            const memberDisplayName = getDisplayNameForUser(String(contact.id), {
                displayName: contact.displayName,
                username: contact.username,
                isGroup: false
            });
            name.textContent = memberDisplayName;

            const sub = document.createElement('div');
            sub.className = 'group-chat-member-username';
            sub.textContent = contact.username ? `@${contact.username}` : '';

            copy.appendChild(name);
            copy.appendChild(sub);
            card.appendChild(checkbox);
            card.appendChild(img);
            card.appendChild(copy);
            addMembersList.appendChild(card);
        });

        updateAddMembersSelectionUi();
    }

    function openAddMembersModal(groupKey) {
        if (!addMembersModal) return;
        addMembersTargetGroupKey = groupKey;
        if (addMembersStatus) addMembersStatus.textContent = '';
        renderAddMembersList(groupKey);
        addMembersModal.classList.add('open');
        addMembersModal.setAttribute('aria-hidden', 'false');
    }

    function closeAddMembersModal() {
        if (!addMembersModal) return;
        addMembersModal.classList.remove('open');
        addMembersModal.setAttribute('aria-hidden', 'true');
        addMembersTargetGroupKey = '';
        addMembersSelection = new Set();
    }

    if (addMembersModalClose) {
        addMembersModalClose.addEventListener('click', closeAddMembersModal);
    }
    // Disabled backdrop click to close - only X or Cancel buttons should close
    // if (addMembersModal) {
    //     addMembersModal.addEventListener('click', (e) => {
    //         if (e.target === addMembersModal) closeAddMembersModal();
    //     });
    // }

    if (addMembersSelectAll) {
        addMembersSelectAll.addEventListener('change', () => {
            const checkboxes = addMembersList
                ? Array.from(addMembersList.querySelectorAll('input[type="checkbox"][data-contact-id]'))
                : [];
            addMembersSelection = new Set();
            checkboxes.forEach(cb => {
                cb.checked = addMembersSelectAll.checked;
                if (addMembersSelectAll.checked) addMembersSelection.add(cb.dataset.contactId);
            });
            updateAddMembersSelectionUi();
        });
    }

    if (addMembersConfirm) {
        addMembersConfirm.addEventListener('click', async () => {
            if (!addMembersTargetGroupKey || addMembersSelection.size === 0) return;
            const groupId = parseInt(addMembersTargetGroupKey.replace('group:', ''), 10);
            const memberIds = Array.from(addMembersSelection).map(Number);

            addMembersConfirm.disabled = true;
            if (addMembersStatus) addMembersStatus.textContent = 'Adding members...';

            try {
                const res = await fetch('add_group_members.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ token, group_id: groupId, member_ids: memberIds })
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok || !data.success) {
                    if (addMembersStatus) addMembersStatus.textContent = data.error || 'Failed to add members.';
                    addMembersConfirm.disabled = false;
                    return;
                }
                invalidateSidebarHistoryCache({ reloadIfVisible: true });
                await fetchGroupMembersForInfo(addMembersTargetGroupKey, { silent: true });
                closeAddMembersModal();
            } catch {
                if (addMembersStatus) addMembersStatus.textContent = 'Network error. Please try again.';
                addMembersConfirm.disabled = false;
            }
        });
    }

    // ─── Invite Users to Call Modal ───────────────────────────────────────────
    const inviteUsersModal = document.getElementById('inviteUsersModal');
    const inviteUsersModalClose = document.getElementById('inviteUsersModalClose');
    const inviteUsersList = document.getElementById('inviteUsersList');
    const inviteUsersSelectAll = document.getElementById('inviteUsersSelectAll');
    const inviteUsersSelectedCount = document.getElementById('inviteUsersSelectedCount');
    const inviteUsersConfirm = document.getElementById('inviteUsersConfirm');
    const inviteUsersCancel = document.getElementById('inviteUsersCancel');
    let inviteUsersSelection = new Set();
    let pendingCallInvites = new Map(); // Track sent invites

    function updateInviteUsersSelectionUi() {
        const count = inviteUsersSelection.size;
        if (inviteUsersSelectedCount) inviteUsersSelectedCount.textContent = `${count} selected`;
        if (inviteUsersConfirm) {
            inviteUsersConfirm.disabled = count === 0;
            inviteUsersConfirm.innerHTML = `<i class="fa-solid fa-user-plus" aria-hidden="true"></i> Invite ${count} user${count !== 1 ? 's' : ''}`;
        }
        if (inviteUsersList) {
            const checkboxes = Array.from(inviteUsersList.querySelectorAll('input[type="checkbox"][data-contact-id]'));
            const checked = checkboxes.filter(c => c.checked).length;
            if (inviteUsersSelectAll) {
                inviteUsersSelectAll.checked = checkboxes.length > 0 && checked === checkboxes.length;
                inviteUsersSelectAll.indeterminate = checked > 0 && checked < checkboxes.length;
                inviteUsersSelectAll.disabled = checkboxes.length === 0;
            }
        }
    }

    function renderInviteUsersList() {
        if (!inviteUsersList) return;
        inviteUsersList.innerHTML = '';
        inviteUsersSelection = new Set();

        // Get all contacts
        const contacts = getAvailableGroupChatContacts();

        // Exclude users already in the call
        const currentCallParticipants = new Set();
        if (activeGroupCallId) {
            const participants = getCurrentRemoteParticipantIds();
            participants.forEach(id => currentCallParticipants.add(String(id)));
            currentCallParticipants.add(String(currentUserId));
        } else if (currentCall || callConnectedFlag) {
            const directUserId = getDirectCallPeerUserId();
            if (directUserId) currentCallParticipants.add(String(directUserId));
            currentCallParticipants.add(String(currentUserId));
        }

        const availableContacts = contacts.filter(c => !currentCallParticipants.has(c.id));

        if (!availableContacts.length) {
            const empty = document.createElement('div');
            empty.className = 'friend-request-search-empty';
            empty.textContent = 'All your contacts are already in this call.';
            inviteUsersList.appendChild(empty);
            updateInviteUsersSelectionUi();
            return;
        }

        availableContacts.forEach(contact => {
            const card = document.createElement('label');
            card.className = 'group-chat-member-card';

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.dataset.contactId = contact.id;
            checkbox.addEventListener('change', () => {
                if (checkbox.checked) inviteUsersSelection.add(contact.id);
                else inviteUsersSelection.delete(contact.id);
                updateInviteUsersSelectionUi();
            });

            const img = document.createElement('img');
            img.src = contact.profilePic || defaultProfilePic;
            img.alt = contact.displayName || contact.username || 'Contact';

            const copy = document.createElement('div');
            copy.className = 'group-chat-member-copy';

            const name = document.createElement('div');
            name.className = 'group-chat-member-name';
            const memberDisplayName = getDisplayNameForUser(String(contact.id), {
                displayName: contact.displayName,
                username: contact.username,
                isGroup: false
            });
            name.textContent = memberDisplayName;

            const sub = document.createElement('div');
            sub.className = 'group-chat-member-username';
            sub.textContent = contact.username ? `@${contact.username}` : '';

            copy.appendChild(name);
            copy.appendChild(sub);
            card.appendChild(checkbox);
            card.appendChild(img);
            card.appendChild(copy);
            inviteUsersList.appendChild(card);
        });

        updateInviteUsersSelectionUi();
    }

    function openInviteUsersModal() {
        if (!inviteUsersModal) return;
        if (!activeGroupCallId && !currentCall && !callConnectedFlag) {
            showToast('You must be in a call to invite users', 'error');
            return;
        }
        renderInviteUsersList();
        inviteUsersModal.classList.add('open');
        inviteUsersModal.setAttribute('aria-hidden', 'false');
        // Ensure modal appears above call UI and call controls
        inviteUsersModal.style.zIndex = '100003';
    }

    function closeInviteUsersModal() {
        if (!inviteUsersModal) return;
        inviteUsersModal.classList.remove('open');
        inviteUsersModal.setAttribute('aria-hidden', 'true');
        inviteUsersSelection = new Set();
        // Reset z-index after animation completes
        setTimeout(() => {
            if (inviteUsersModal) inviteUsersModal.style.zIndex = '';
        }, 300);
        // Ensure call UI remains visible after closing modal
        if (callUi && (activeGroupCallId || currentCall || callConnectedFlag)) {
            callUi.style.display = 'flex';
        }
    }

    if (inviteUsersModalClose) {
        inviteUsersModalClose.addEventListener('click', closeInviteUsersModal);
    }

    if (inviteUsersCancel) {
        inviteUsersCancel.addEventListener('click', closeInviteUsersModal);
    }

    if (inviteUsersSelectAll) {
        inviteUsersSelectAll.addEventListener('change', () => {
            const checkboxes = inviteUsersList
                ? Array.from(inviteUsersList.querySelectorAll('input[type="checkbox"][data-contact-id]'))
                : [];
            inviteUsersSelection = new Set();
            checkboxes.forEach(cb => {
                cb.checked = inviteUsersSelectAll.checked;
                if (inviteUsersSelectAll.checked) inviteUsersSelection.add(cb.dataset.contactId);
            });
            updateInviteUsersSelectionUi();
        });
    }

    if (inviteUsersConfirm) {
        inviteUsersConfirm.addEventListener('click', async () => {
            if (inviteUsersSelection.size === 0) return;
            
            const invitedUserIds = Array.from(inviteUsersSelection);
            const count = invitedUserIds.length;

            inviteUsersConfirm.disabled = true;
            inviteUsersConfirm.innerHTML = '<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> Inviting...';

            try {
                let callType = 'direct';
                let groupCallId = null;
                const currentParticipants = getCurrentCallInviteParticipants();
                const inviteContext = await ensureGroupInviteContextForCurrentCall(invitedUserIds);
                callType = inviteContext.callType || 'direct';
                groupCallId = inviteContext.groupCallId || null;

                if (callType === 'group' && !groupCallId) {
                    throw new Error('Unable to prepare this call for invites right now.');
                }

                // Send invites
                const res = await fetch('send_call_invites.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        token,
                        invited_user_ids: invitedUserIds.map(Number),
                        call_type: callType,
                        group_call_id: groupCallId,
                        current_participants: currentParticipants
                    })
                });

                const data = await res.json().catch(() => ({}));
                if (!res.ok || !data.success) {
                    showToast(data.error || 'Failed to send invites', 'error');
                    inviteUsersConfirm.disabled = false;
                    inviteUsersConfirm.innerHTML = `<i class="fa-solid fa-user-plus" aria-hidden="true"></i> Invite ${count} user${count !== 1 ? 's' : ''}`;
                    return;
                }

                // Track invites
                invitedUserIds.forEach(userId => {
                    pendingCallInvites.set(String(userId), {
                        invitedAt: Date.now(),
                        displayName: getParticipantDisplayName(userId, false)
                    });
                });

                closeInviteUsersModal();
                showToast(`Invited ${count} member${count !== 1 ? 's' : ''} to the call`, 'success');
                
                // Ensure call UI remains visible after showing toast
                if (callUi && (activeGroupCallId || currentCall || callConnectedFlag)) {
                    callUi.style.display = 'flex';
                }
            } catch (error) {
                console.error('Failed to send call invites:', error);
                showToast('Network error. Please try again.', 'error');
                inviteUsersConfirm.disabled = false;
                inviteUsersConfirm.innerHTML = `<i class="fa-solid fa-user-plus" aria-hidden="true"></i> Invite ${count} user${count !== 1 ? 's' : ''}`;
            }
        });
    }

    [addMembersBtnDesktop, addMembersBtnMobile].forEach(btn => {
        if (!btn) return;
        btn.addEventListener('click', () => {
            if (!selectedUser || !isGroupChatKey(String(selectedUser))) return;
            const meta = getContactMeta(String(selectedUser));
            const addPerm = meta ? (meta.addMembersPermission || GROUP_ADD_PERMISSION_ADMINS) : GROUP_ADD_PERMISSION_ADMINS;
            const canAdd = addPerm === GROUP_ADD_PERMISSION_ALL || (meta && meta.canManageGroup);
            if (!canAdd) return; // button is visually disabled, but guard anyway
            openAddMembersModal(String(selectedUser));
        });
    });

    if (groupChatModalClose) {
        groupChatModalClose.addEventListener('click', () => {
            closeGroupChatModal();
        });
    }

    // ─── Group Call Modal ─────────────────────────────────────────────────────
    const groupCallModal = document.getElementById('groupCallModal');
    const groupCallModalClose = document.getElementById('groupCallModalClose');
    const groupCallContactsList = document.getElementById('groupCallContactsList');
    const groupCallSelectAll = document.getElementById('groupCallSelectAll');
    const groupCallSelectedCount = document.getElementById('groupCallSelectedCount');
    const groupCallStart = document.getElementById('groupCallStart');
    const groupCallStatus = document.getElementById('groupCallStatus');
    let groupCallSelection = new Set();

    function updateGroupCallSelectionUi() {
        const count = groupCallSelection.size;
        if (groupCallSelectedCount) groupCallSelectedCount.textContent = `${count} selected`;
        if (groupCallStart) groupCallStart.disabled = count === 0;
        if (groupCallContactsList) {
            const cbs = Array.from(groupCallContactsList.querySelectorAll('input[type="checkbox"][data-contact-id]'));
            const checked = cbs.filter(c => c.checked).length;
            if (groupCallSelectAll) {
                groupCallSelectAll.checked = cbs.length > 0 && checked === cbs.length;
                groupCallSelectAll.indeterminate = checked > 0 && checked < cbs.length;
                groupCallSelectAll.disabled = cbs.length === 0;
            }
        }
    }

    function renderGroupCallContactsList() {
        if (!groupCallContactsList) return;
        groupCallContactsList.innerHTML = '';
        groupCallSelection = new Set();
        const contacts = getAvailableGroupChatContacts();
        if (!contacts.length) {
            const empty = document.createElement('div');
            empty.className = 'friend-request-search-empty';
            empty.textContent = 'You need at least one contact to start a group call.';
            groupCallContactsList.appendChild(empty);
            updateGroupCallSelectionUi();
            return;
        }
        contacts.forEach(contact => {
            const card = document.createElement('label');
            card.className = 'group-chat-member-card';
            const cb = document.createElement('input');
            cb.type = 'checkbox';
            cb.dataset.contactId = contact.id;
            cb.addEventListener('change', () => {
                if (cb.checked) groupCallSelection.add(contact.id);
                else groupCallSelection.delete(contact.id);
                updateGroupCallSelectionUi();
            });
            const img = document.createElement('img');
            img.src = contact.profilePic || defaultProfilePic;
            img.alt = contact.displayName || contact.username || 'Contact';
            const copy = document.createElement('div');
            copy.className = 'group-chat-member-copy';
            const name = document.createElement('div');
            name.className = 'group-chat-member-name';
            const memberDisplayName = getDisplayNameForUser(String(contact.id), {
                displayName: contact.displayName,
                username: contact.username,
                isGroup: false
            });
            name.textContent = memberDisplayName;
            const sub = document.createElement('div');
            sub.className = 'group-chat-member-username';
            sub.textContent = contact.username ? `@${contact.username}` : '';
            copy.appendChild(name);
            copy.appendChild(sub);
            card.appendChild(cb);
            card.appendChild(img);
            card.appendChild(copy);
            groupCallContactsList.appendChild(card);
        });
        updateGroupCallSelectionUi();
    }

    function openGroupCallModal() {
        if (!groupCallModal) return;
        closeAnyOpenDropdownMenus();
        if (groupCallStatus) groupCallStatus.textContent = '';
        renderGroupCallContactsList();
        groupCallModal.classList.add('open');
        groupCallModal.setAttribute('aria-hidden', 'false');
    }

    function closeGroupCallModal() {
        if (!groupCallModal) return;
        groupCallModal.classList.remove('open');
        groupCallModal.setAttribute('aria-hidden', 'true');
        groupCallSelection = new Set();
    }

    if (groupCallModalClose) groupCallModalClose.addEventListener('click', closeGroupCallModal);
    // Removed backdrop click handler - modal only closes via buttons

    if (groupCallSelectAll) {
        groupCallSelectAll.addEventListener('change', () => {
            const cbs = groupCallContactsList
                ? Array.from(groupCallContactsList.querySelectorAll('input[type="checkbox"][data-contact-id]'))
                : [];
            groupCallSelection = new Set();
            cbs.forEach(cb => {
                cb.checked = groupCallSelectAll.checked;
                if (groupCallSelectAll.checked) groupCallSelection.add(cb.dataset.contactId);
            });
            updateGroupCallSelectionUi();
        });
    }

    function syncGroupContactFromServer(contact) {
        if (!contact || !contact.id) {
            return null;
        }

        return addContact(
            contact.id,
            contact.display_name || 'Group Chat',
            contact.username || '',
            contact.profile_pic || DEFAULT_GROUP_CHAT_ICON,
            contact.online ? 1 : 0,
            contact.bio || '',
            contact.created_at || '',
            contact.last_message_at || contact.created_at || '',
            contact.viewer_has_blocked || 0,
            contact.blocked_viewer || 0,
            {
                chatType: contact.chat_type || 'group',
                entityId: contact.entity_id || getGroupIdFromChatKey(contact.id),
                memberCount: contact.member_count || 0,
                viewerRole: contact.viewer_role || '',
                viewerMutedUntil: contact.viewer_muted_until || '',
                sendPermission: contact.send_permission || '',
                addMembersPermission: contact.add_members_permission || '',
                canManageGroup: !!contact.viewer_can_manage_group,
                canChangeRoles: !!contact.viewer_can_change_roles,
                canDeleteGroup: !!contact.viewer_can_delete_group,
                canSendGroup: !!contact.viewer_can_send
            }
        );
    }

    async function createGroupChatContact(selectedContacts, options = {}) {
        if (!Array.isArray(selectedContacts) || selectedContacts.length === 0) {
            throw new Error('Choose at least one contact to continue.');
        }

        const normalizedDescription = options.callOnly
            ? (options.description || CALL_ONLY_GROUP_DESCRIPTION)
            : (options.description || '');
        const formData = new FormData();
        formData.append('token', token);
        formData.append('member_ids', JSON.stringify(selectedContacts.map(contact => contact.id)));
        formData.append('name', options.name || '');
        formData.append('description', normalizedDescription);
        if (options.iconFile) {
            formData.append('icon', options.iconFile);
        }

        const res = await fetch('create_group.php', {
            method: 'POST',
            body: formData
        });
        const rawText = await res.text();
        let json = {};
        try {
            json = rawText ? JSON.parse(rawText) : {};
        } catch (parseError) {
            throw new Error(rawText.trim() || 'Group chat creation returned an invalid server response.');
        }

        if (!res.ok || !json.success || !json.contact) {
            throw new Error(json.error || 'Unable to create that group chat right now.');
        }

        syncGroupContactFromServer(json.contact);
        return json.contact;
    }

    function getCurrentCallInviteParticipants() {
        const currentParticipants = [];
        if (activeGroupCallId) {
            const participants = getCurrentRemoteParticipantIds();
            participants.forEach(id => {
                const name = getParticipantDisplayName(id, false);
                currentParticipants.push({ user_id: id, display_name: name });
            });
        } else if (currentCall || callConnectedFlag) {
            const directUserId = getDirectCallPeerUserId();
            if (directUserId) {
                const name = getParticipantDisplayName(directUserId, false);
                currentParticipants.push({ user_id: directUserId, display_name: name });
            }
        }
        currentParticipants.push({ user_id: currentUserId, display_name: 'You' });
        return currentParticipants;
    }

    function buildDirectCallPromotionContact(userId) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId || isGroupChatKey(normalizedUserId)) {
            return null;
        }

        const existingContact = getAvailableGroupChatContacts().find(contact => String(contact.id) === normalizedUserId);
        if (existingContact) {
            return existingContact;
        }

        return {
            id: normalizedUserId,
            displayName: getParticipantDisplayName(normalizedUserId, false) || getUsernameById(normalizedUserId) || `User ${normalizedUserId}`,
            username: String(userUsernamesMap[normalizedUserId] || '').trim(),
            profilePic: userProfilePics[normalizedUserId] || defaultProfilePic,
            isOnline: !!userOnlineMap[normalizedUserId]
        };
    }

    function waitForDataConnectionOpen(conn, timeoutMs = 4000) {
        return new Promise((resolve, reject) => {
            if (!conn) {
                reject(new Error('Unable to reach the current call right now.'));
                return;
            }
            if (conn.open) {
                resolve(conn);
                return;
            }

            let settled = false;
            const timeoutId = setTimeout(() => {
                if (settled) return;
                settled = true;
                reject(new Error('Unable to reach the current call right now.'));
            }, timeoutMs);

            conn.on('open', () => {
                if (settled) return;
                settled = true;
                clearTimeout(timeoutId);
                resolve(conn);
            });

            conn.on('error', () => {
                if (settled) return;
                settled = true;
                clearTimeout(timeoutId);
                reject(new Error('Unable to reach the current call right now.'));
            });
        });
    }

    async function ensureDirectCallPromotionConnection() {
        const directPeerId = currentCall && currentCall.peer ? String(currentCall.peer) : '';
        if (!directPeerId || !peer) {
            throw new Error('Unable to reach the current call right now.');
        }

        if (activeDataConnection && activeDataConnection.peer === directPeerId) {
            return waitForDataConnectionOpen(activeDataConnection);
        }

        const conn = peer.connect(directPeerId, { reliable: true });
        activeDataConnection = conn;
        setupDataConnectionHandlers(conn);
        return waitForDataConnectionOpen(conn);
    }

    function waitForDirectCallPromotionAck(timeoutMs = 1800) {
        return new Promise(resolve => {
            let settled = false;
            pendingDirectCallPromotionAckResolve = acknowledged => {
                if (settled) return;
                settled = true;
                pendingDirectCallPromotionAckResolve = null;
                resolve(acknowledged !== false);
            };

            setTimeout(() => {
                if (settled) return;
                settled = true;
                pendingDirectCallPromotionAckResolve = null;
                resolve(false);
            }, timeoutMs);
        });
    }

    function clearDirectCallConnectionForGroupPromotion({
        preserveLocalStream = false,
        preserveEndedUi = false,
        preserveStopwatch = false,
        preserveCallHistory = false,
        preserveGroupCallState = false
    } = {}) {
        clearPendingCallUiDismiss();
        stopAndResetAudio(ringbackAudio);
        stopAndResetAudio(ringtoneAudio);
        if (!preserveStopwatch) {
            stopStopwatch();
        }

        if (callTimeoutId) {
            clearTimeout(callTimeoutId);
            callTimeoutId = null;
        }

        callConnectedFlag = false;
        directCallUiMode = preserveEndedUi ? 'ended' : 'idle';
        activeCallRequestId = null;
        pendingCallTo = null;
        outgoingCallSetupInProgress = false;
        localHangupInitiated = false;
        callerId = null;
        if (!preserveCallHistory) {
            activeCallHistory = null;
        }

        if (currentCall) {
            if (currentCall.peer) {
                rememberResolvedPeerId(getUserIdFromPeerId(currentCall.peer), currentCall.peer);
            }
            try { currentCall.close(); } catch {}
            currentCall = null;
        }

        if (activeDataConnection) {
            if (activeDataConnection.peer) {
                rememberResolvedPeerId(getUserIdFromPeerId(activeDataConnection.peer), activeDataConnection.peer);
            }
            try { activeDataConnection.close(); } catch {}
            activeDataConnection = null;
        }

        if (!preserveGroupCallState) {
            teardownAllGroupCallPeers();
            if (groupCallParticipantsEl) {
                groupCallParticipantsEl.innerHTML = '';
                groupCallParticipantsEl.style.display = 'none';
            }
        }

        if (remoteAudio && remoteAudio.srcObject) {
            remoteAudio.srcObject = null;
        }

        if (!preserveLocalStream && localAudioStream) {
            localAudioStream.getTracks().forEach(track => track.stop());
            localAudioStream = null;
        }

        if (!preserveGroupCallState) {
            resetCallVideoState();
        }
    }

    async function addMembersToGroupCallChat(groupKey, memberIds) {
        const normalizedGroupKey = String(groupKey || '').trim();
        const groupId = getGroupIdFromChatKey(normalizedGroupKey);
        const normalizedMemberIds = Array.from(new Set(
            (Array.isArray(memberIds) ? memberIds : [])
                .map(id => parseInt(id, 10))
                .filter(id => id > 0)
        ));

        if (!groupId || !normalizedMemberIds.length) {
            return;
        }

        const res = await fetch('add_group_members.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                token,
                group_id: groupId,
                member_ids: normalizedMemberIds
            })
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) {
            throw new Error(data.error || 'Unable to prepare this call for invites right now.');
        }

        if (data.group) {
            applyGroupDetailsPayload(normalizedGroupKey, {
                group: data.group,
                members: Array.isArray(data.members) ? data.members : []
            });
        }
        invalidateSidebarHistoryCache({ reloadIfVisible: true });
    }

    async function ensureGroupInviteContextForCurrentCall(invitedUserIds) {
        const normalizedInvitedUserIds = Array.from(new Set(
            (Array.isArray(invitedUserIds) ? invitedUserIds : [])
                .map(id => String(id || '').trim())
                .filter(Boolean)
        ));

        if (activeGroupCallId && activeGroupCallKey && isCallOnlyGroupKey(activeGroupCallKey)) {
            await addMembersToGroupCallChat(activeGroupCallKey, normalizedInvitedUserIds);
            return {
                callType: 'group',
                groupCallId: activeGroupCallId,
                groupKey: activeGroupCallKey
            };
        }

        if (activeGroupCallId) {
            return {
                callType: 'group',
                groupCallId: activeGroupCallId,
                groupKey: activeGroupCallKey
            };
        }

        if (!(currentCall || callConnectedFlag)) {
            return {
                callType: 'direct',
                groupCallId: null,
                groupKey: ''
            };
        }

        const directPeerUserId = getDirectCallPeerUserId();
        const directPeerContact = buildDirectCallPromotionContact(directPeerUserId);
        if (!directPeerUserId || !directPeerContact) {
            throw new Error('Unable to prepare this call for invites right now.');
        }

        const directCallConnection = await ensureDirectCallPromotionConnection();
        const existingStream = localAudioStream || null;
        let promotionContext = null;

        try {
            const started = await initiateAdhocGroupCall([directPeerUserId], {
                existingStream,
                suppressAlerts: true,
                preferredGroupName: 'Group call',
                preferredGroupIcon: DEFAULT_GROUP_CHAT_ICON,
                preserveCallUi: true,
                keepExistingCallUi: true,
                suppressRingback: true
            });

            if (started && activeGroupCallId) {
                const adhocGroupKey = String(
                    started.groupKey || activeGroupCallKey || buildAdhocGroupCallKey(activeGroupCallId)
                ).trim();
                if (adhocGroupKey) {
                    promotionContext = {
                        groupId: 0,
                        groupKey: adhocGroupKey,
                        groupName: started.groupName || 'Group call',
                        groupIcon: started.groupIcon || DEFAULT_GROUP_CHAT_ICON
                    };
                }
            }
        } catch (error) {
            console.warn('Ad-hoc group call promotion failed, falling back to call-only group.', error);
        }

        if (!promotionContext) {
            const hiddenGroupContact = await createGroupChatContact([directPeerContact], { callOnly: true });
            const hiddenGroupKey = String(hiddenGroupContact.id || '').trim();
            if (!hiddenGroupKey) {
                throw new Error('Unable to prepare this call for invites right now.');
            }

            callOnlyGroupIds.add(hiddenGroupKey);
            const started = await initiateGroupCall(hiddenGroupKey, {
                existingStream,
                suppressAlerts: true,
                suppressMessage: true,
                preserveCallUi: true,
                keepExistingCallUi: true,
                suppressRingback: true
            });
            if (!started || !activeGroupCallId) {
                throw new Error('Unable to prepare this call for invites right now.');
            }

            const tempContactEl = getContactElement(hiddenGroupKey);
            if (tempContactEl) {
                tempContactEl.remove();
            }

            await addMembersToGroupCallChat(hiddenGroupKey, normalizedInvitedUserIds);

            promotionContext = {
                groupId: getGroupIdFromChatKey(hiddenGroupKey),
                groupKey: hiddenGroupKey,
                groupName: hiddenGroupContact.display_name || hiddenGroupContact.displayName || 'Group',
                groupIcon: hiddenGroupContact.profile_pic || hiddenGroupContact.profilePic || DEFAULT_GROUP_CHAT_ICON
            };
        }

        capturePromotedDirectCallContext({
            groupCallId: activeGroupCallId,
            groupKey: promotionContext.groupKey,
            otherUserId: directPeerUserId,
            callerId: activeCallHistory && activeCallHistory.callerId ? activeCallHistory.callerId : currentUserId
        });
        applyPromotedDirectCallUi();

        armDirectCallCloseSuppression();
        directCallConnection.send({
            type: 'promote_to_group_call',
            group_call_id: activeGroupCallId,
            group_id: promotionContext.groupId || 0,
            group_key: promotionContext.groupKey,
            group_name: promotionContext.groupName || 'Group call',
            group_icon: promotionContext.groupIcon || DEFAULT_GROUP_CHAT_ICON
        });

        await waitForDirectCallPromotionAck();
        clearDirectCallConnectionForGroupPromotion({
            preserveLocalStream: !!existingStream,
            preserveStopwatch: true,
            preserveCallHistory: true,
            preserveGroupCallState: true
        });

        return {
            callType: 'group',
            groupCallId: activeGroupCallId,
            groupKey: promotionContext.groupKey
        };
    }

    if (groupCallStart) {
        groupCallStart.addEventListener('click', async () => {
            if (groupCallSelection.size === 0) return;
            if (activeGroupCallId) { alert('You are already in a call.'); return; }

            const selectedContacts = getAvailableGroupChatContacts().filter(c => groupCallSelection.has(c.id));

            groupCallStart.disabled = true;
            if (groupCallStatus) groupCallStatus.textContent = 'Starting call...';

            let stream;
            try {
                stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            } catch {
                alert('Microphone permission denied. Cannot start call.');
                groupCallStart.disabled = false;
                if (groupCallStatus) groupCallStatus.textContent = '';
                return;
            }

            try {
                // Create a temporary group for the call session (required by server)
                // but don't navigate to it or show it in the contacts list
                const contact = await createGroupChatContact(selectedContacts, { callOnly: true });
                closeGroupCallModal();
                // Mark this group as call-only so pollContacts won't show it
                callOnlyGroupIds.add(String(contact.id));

                const started = await initiateGroupCall(contact.id, {
                    existingStream: stream,
                    suppressAlerts: true,
                    suppressMessage: true
                });
                if (!started) {
                    throw new Error('Unable to start that group call right now.');
                }
                // Remove from DOM in case it was added before we marked it
                const tempContactEl = getContactElement(contact.id);
                if (tempContactEl) tempContactEl.remove();
            } catch (error) {
                if (stream) {
                    stream.getTracks().forEach(track => track.stop());
                }
                if (localAudioStream === stream) {
                    localAudioStream = null;
                }
                const message = error instanceof Error
                    ? error.message
                    : 'Unable to start that group call right now.';
                if (groupCallStatus) {
                    groupCallStatus.textContent = message;
                }
                if (!groupCallModal || !groupCallModal.classList.contains('open')) {
                    alert(message);
                }
            } finally {
                groupCallStart.disabled = false;
                if (groupCallStatus && groupCallStatus.textContent === 'Starting call...') {
                    groupCallStatus.textContent = '';
                }
            }
        });
    }

    document.getElementById('openGroupCallModalDesktop')?.addEventListener('click', openGroupCallModal);
    document.getElementById('openGroupCallModalMobile')?.addEventListener('click', openGroupCallModal);

    if (groupChatSelectAll) {
        groupChatSelectAll.addEventListener('change', () => {
            const checkboxes = groupChatMembersList
                ? Array.from(groupChatMembersList.querySelectorAll('input[type="checkbox"][data-group-chat-member-id]'))
                : [];

            groupChatInviteSelection = new Set(
                groupChatSelectAll.checked
                    ? checkboxes.map(input => String(input.dataset.groupChatMemberId || '')).filter(Boolean)
                    : []
            );

            checkboxes.forEach(input => {
                input.checked = groupChatInviteSelection.has(String(input.dataset.groupChatMemberId || ''));
            });

            updateGroupChatSelectionUi();
            syncGroupChatNameSuggestion();
        });
    }

    if (groupChatMembersNext) {
        groupChatMembersNext.addEventListener('click', () => {
            if (!groupChatInviteSelection.size) {
                setGroupChatStatusMessage('Choose at least one contact to continue.', 'error');
                return;
            }

            syncGroupChatNameSuggestion(true);
            setGroupChatStep('details');
            setGroupChatStatusMessage('Ready to create your group chat.');

            if (groupChatNameInput) {
                setTimeout(() => groupChatNameInput.focus(), 20);
            }
        });
    }

    if (groupChatDetailsBack) {
        groupChatDetailsBack.addEventListener('click', () => {
            setGroupChatStep('members');
            setGroupChatStatusMessage(
                groupChatInviteSelection.size > 0
                    ? 'Choose more contacts or continue when you are ready.'
                    : 'Choose at least one contact to continue.'
            );
        });
    }

    if (groupChatNameInput) {
        groupChatNameInput.addEventListener('input', () => {
            groupChatNameTouched = true;
        });
    }

    if (groupChatIconTrigger && groupChatIconInput) {
        groupChatIconTrigger.addEventListener('click', () => {
            openFilePickerInput(groupChatIconInput);
        });

        groupChatIconInput.addEventListener('change', () => {
            const file = groupChatIconInput.files && groupChatIconInput.files[0];
            if (!file) {
                resetGroupChatIconPreview();
                return;
            }

            if (groupChatIconObjectUrl) {
                URL.revokeObjectURL(groupChatIconObjectUrl);
                groupChatIconObjectUrl = '';
            }

            groupChatSelectedIconFile = file;
            groupChatIconObjectUrl = URL.createObjectURL(file);
            if (groupChatIconPreview) {
                groupChatIconPreview.src = groupChatIconObjectUrl;
            }
        });
    }

    if (groupChatFinish) {
        groupChatFinish.addEventListener('click', async () => {
            const selectedContacts = getSelectedGroupChatContacts();
            if (!selectedContacts.length) {
                setGroupChatStatusMessage('Choose at least one contact to continue.', 'error');
                setGroupChatStep('members');
                return;
            }

            const groupName = groupChatNameInput ? groupChatNameInput.value.trim() : '';
            const description = groupChatDescriptionInput ? groupChatDescriptionInput.value.trim() : '';
            const originalLabel = groupChatFinish.textContent;
            groupChatFinish.disabled = true;
            if (groupChatDetailsBack) {
                groupChatDetailsBack.disabled = true;
            }
            groupChatFinish.textContent = 'Creating...';
            setGroupChatStatusMessage('Creating your group chat...', 'pending');

            try {
                const contact = await createGroupChatContact(selectedContacts, {
                    name: groupName || groupChatSuggestedName || '',
                    description,
                    iconFile: groupChatSelectedIconFile
                });

                closeGroupChatModal();
                clearLocalTyping(true);
                hideTypingIndicator();
                invalidateSidebarHistoryCache({ reloadIfVisible: true });
                await openConversation(contact.id);
            } catch (error) {
                setGroupChatStatusMessage(error instanceof Error ? error.message : 'Unable to create that group chat right now.', 'error');
            } finally {
                groupChatFinish.disabled = false;
                groupChatFinish.textContent = originalLabel;
                if (groupChatDetailsBack) {
                    groupChatDetailsBack.disabled = false;
                }
            }
        });
    }

    // Disabled backdrop click to close - only X or Cancel buttons should close
    // if (friendRequestModal) {
    //     friendRequestModal.addEventListener('click', event => {
