    //             closeFriendRequestModal();
    //         }
    //     });
    // }

    // if (groupChatModal) {
    //     groupChatModal.addEventListener('click', event => {
    //         if (event.target === groupChatModal) {
    //             closeGroupChatModal();
    //         }
    //     });
    // }

    document.addEventListener('keydown', event => {
        if (event.key === 'Escape' && friendRequestModal && friendRequestModal.classList.contains('open')) {
            closeFriendRequestModal();
        }
        if (event.key === 'Escape' && groupChatModal && groupChatModal.classList.contains('open')) {
            closeGroupChatModal();
        }
    });

    function showFriendRequestPopup(req) {
        if (!getAppSetting('friendRequestPopups')) return;
        if (document.getElementById('friendRequest-' + req.id)) return;
        const popup = document.createElement('div');
        popup.id = 'friendRequest-' + req.id;
        popup.className = 'friend-request-popup';
        const requestLabel = req.display_name && req.display_name !== req.username
            ? `${req.display_name} (@${req.username})`
            : req.username;
        popup.innerHTML = `
            <div><strong>${requestLabel}</strong> has sent you a friend request.</div>
            <button class="accept-btn">Accept</button>
            <button class="reject-btn">Reject</button>`;
        friendRequestPopups.appendChild(popup);
        popup.querySelector('.accept-btn').onclick = async () => {
            await respondFriendRequest(req.id, 'accept', popup);
        };
        popup.querySelector('.reject-btn').onclick = async () => {
            await respondFriendRequest(req.id, 'reject', popup);
        };
    }

    async function pollFriendRequests() {
        try {
            const res = await fetch(`fetch_friend_requests.php?token=${token}`);
            if (!res.ok) throw new Error('Network error');
            const requests = await res.json();
            requests.forEach(showFriendRequestPopup);
        } catch {}
    }
    pollFriendRequests();
    setInterval(pollFriendRequests, 5000);

    async function pollCallRequests() {
        try {
            const res = await fetch(`poll_call_requests.php?token=${token}&t=${Date.now()}`);
            const requests = await res.json();
            if (!Array.isArray(requests)) {
                return;
            }
            const acceptBtn = document.getElementById('accept-call-btn');
            const incomingDirectCallVisible = !!(
                callUi.style.display === "flex"
                && activeCallRequestId
                && !activeGroupCallId
                && acceptBtn
                && acceptBtn.style.display !== 'none'
                && callUsername.innerText.startsWith('Incoming call from ')
            );

            if (incomingDirectCallVisible) {
                const stillPending = requests.some(request => String(request.id) === String(activeCallRequestId));
                if (!stillPending) {
                    activeCallRequestId = null;
                    endPeerCall(false, "none");
                }
                return;
            }

            if (currentCall || activeGroupCallId || (callUi.style.display === "flex" && !incomingDirectCallVisible)) {
                return;
            }

            const req = requests.find(request => !handledIncomingRequestIds.has(String(request.id)));
            if (req) {
                showIncomingCallRequest(req);
            }
        } catch (e) {
            console.error('Error polling call requests:', e);
        }
    }
    pollCallRequests();
    setInterval(pollCallRequests, 3000);

    // ─── Call Invite Polling ──────────────────────────────────────────────────
    let handledCallInviteIds = new Set();
    let lastInviteRejectionCheck = null;
    let pendingIncomingCallInviteId = null;
    let pendingIncomingCallInviteName = '';
    let pendingIncomingCallInviteDirectLike = false;

    function clearPendingIncomingCallInviteState() {
        pendingIncomingCallInviteId = null;
        pendingIncomingCallInviteName = '';
        pendingIncomingCallInviteDirectLike = false;
    }

    async function pollCallInvites() {
        try {
            const res = await fetch(`poll_call_invites.php?token=${token}&t=${Date.now()}`);
            const data = await res.json();
            
            if (!data.success || !Array.isArray(data.invites)) {
                return;
            }

            if (pendingIncomingCallInviteId) {
                const stillPendingInvite = data.invites.some(invite => String(invite.id) === String(pendingIncomingCallInviteId));
                if (!stillPendingInvite && !currentCall && !activeGroupCallId) {
                    const expiredInviteName = pendingIncomingCallInviteName;
                    const wasDirectLikeInvite = pendingIncomingCallInviteDirectLike;
                    clearPendingIncomingCallInviteState();
                    stopAndResetAudio(ringtoneAudio);

                    if (callUi.style.display === 'flex') {
                        if (wasDirectLikeInvite) {
                            showTransientDirectCallState('Call ended', {
                                username: expiredInviteName,
                                durationMs: 2600
                            });
                        } else {
                            closeCallUI();
                        }
                    }
                    return;
                }
            }

            // Don't show invites if already in a call or showing incoming call UI
            if (callUi.style.display === 'flex') {
                return;
            }

            const invite = data.invites.find(inv => !handledCallInviteIds.has(String(inv.id)));
            if (invite) {
                showIncomingCallInvite(invite);
            }
        } catch (e) {
            console.error('Error polling call invites:', e);
        }
    }

    async function pollCallInviteRejections() {
        try {
            const url = lastInviteRejectionCheck
                ? `poll_call_invite_rejections.php?token=${token}&last_check=${encodeURIComponent(lastInviteRejectionCheck)}&t=${Date.now()}`
                : `poll_call_invite_rejections.php?token=${token}&t=${Date.now()}`;
            
            const res = await fetch(url);
            const data = await res.json();
            
            if (!data.success || !Array.isArray(data.rejections)) {
                return;
            }

            data.rejections.forEach(rejection => {
                showToast(`${rejection.rejected_by_display_name} rejected your call invite`, 'error');
                if (
                    activeGroupCallId
                    && activeGroupCallKey
                    && String(activeGroupCallKey).startsWith(ADHOC_GROUP_CALL_KEY_PREFIX)
                    && String(selectedUser || '') === String(rejection.rejected_by_user_id || '')
                    && !getCurrentRemoteParticipantIds().length
                ) {
                    endGroupCall(false, 'declined').catch(() => {});
                }
            });

            if (data.rejections.length > 0) {
                lastInviteRejectionCheck = new Date().toISOString();
            }
        } catch (e) {
            console.error('Error polling call invite rejections:', e);
        }
    }

    function showIncomingCallInvite(invite) {
        handledCallInviteIds.add(String(invite.id));

        const inviteChatKey = String(invite.group_key || invite.inviter_id || '').trim();
        const inviterName = getCallDisplayNameForUser(invite.inviter_id, {
            displayName: invite.inviter_display_name || `User ${invite.inviter_id}`,
            username: invite.inviter_username || '',
            isGroup: false
        }, { chatKey: inviteChatKey });
        const inviterPic = invite.inviter_profile_pic || defaultProfilePic;
        const participants = Array.isArray(invite.current_participants) ? invite.current_participants : [];
        const isDirectLikeInvite = !!(
            invite
            && invite.group_call_id
            && (!invite.group_id || Number(invite.group_id) <= 0)
            && participants.length <= 1
        );
        pendingIncomingCallInviteId = String(invite.id || '');
        pendingIncomingCallInviteName = inviterName;
        pendingIncomingCallInviteDirectLike = isDirectLikeInvite;

        resetCallUI();
        document.getElementById('call-image').src = inviterPic;
        document.getElementById('call-image').style.borderRadius = '50%';
        callUsername.innerText = isDirectLikeInvite
            ? `Incoming call from ${inviterName}...`
            : `${inviterName} has invited you to a call`;

        // Build "Also in the call" subtitle - exclude "You" since the invited user isn't in the call yet
        const otherParticipants = participants.filter(p => String(p.user_id || '') !== String(currentUserId));
        if (isDirectLikeInvite) {
            callStatus.innerText = '';
        } else if (otherParticipants.length > 0) {
            const names = otherParticipants.slice(0, 3).map(p => getCallDisplayNameForUser(p.user_id, {
                displayName: p.display_name || `User ${p.user_id}`,
                username: '',
                isGroup: false
            }, { chatKey: inviteChatKey }));
            const extra = otherParticipants.length > 3 ? ` +${otherParticipants.length - 3}` : '';
            callStatus.innerText = `Also in the call: ${names.join(', ')}${extra}`;
        } else {
            callStatus.innerText = 'Join the call';
        }

        callUi.style.display = 'flex';
        document.getElementById('incoming-actions').style.display = 'flex';
        document.getElementById('accept-call-btn').style.display = 'inline-block';
        endCallBtn.style.display = 'inline-block';
        endCallBtn.style.backgroundColor = 'red';

        if (getAppSetting('callRingtone')) {
            ringtoneAudio.play().catch(() => {});
        }

        document.getElementById('accept-call-btn').onclick = async () => {
            ringtoneAudio.pause();
            ringtoneAudio.currentTime = 0;

            try {
                const res = await fetch('respond_call_invite.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        token,
                        invite_id: invite.id,
                        response: 'accepted'
                    })
                });

                const data = await res.json();
                if (!data.success) {
                    clearPendingIncomingCallInviteState();
                    showToast(data.error || 'Failed to accept invite', 'error');
                    callUi.style.display = 'none';
                    return;
                }
                clearPendingIncomingCallInviteState();

                // Always join as a group call (direct calls are promoted to group when inviting)
                if (invite.group_call_id) {
                    // Join the group call
                    const groupKey = invite.group_key || buildGroupCallUiKey(invite.group_call_id, '', 0);
                    await acceptGroupCall(invite.group_call_id, groupKey, {
                        groupName: isDirectLikeInvite ? inviterName : 'Group call',
                        groupIcon: isDirectLikeInvite ? inviterPic : 'images/default-group.svg',
                        preserveCallUi: false
                    });
                } else {
                    showToast('Unable to join call', 'error');
                    callUi.style.display = 'none';
                }
            } catch (error) {
                console.error('Failed to accept call invite:', error);
                clearPendingIncomingCallInviteState();
                showToast('Network error. Please try again.', 'error');
                callUi.style.display = 'none';
            }
        };

        endCallBtn.onclick = async () => {
            ringtoneAudio.pause();
            ringtoneAudio.currentTime = 0;

            try {
                await fetch('respond_call_invite.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        token,
                        invite_id: invite.id,
                        response: 'rejected'
                    })
                });
            } catch (error) {
                console.error('Failed to reject call invite:', error);
            }

            clearPendingIncomingCallInviteState();
            if (isDirectLikeInvite) {
                showTransientDirectCallState('Call Declined', {
                    username: inviterName,
                    durationMs: 3000
                });
            } else {
                closeCallUI();
            }
        };
    }

    pollCallInvites();
    setInterval(pollCallInvites, 3000);
    setInterval(pollCallInviteRejections, 3000);

    // When app comes to foreground (user opens from push notification),
    // immediately poll for pending calls and reconnect PeerJS
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
            startOnlineStatusHeartbeat();
            // Restore the appropriate pending direct-call UI when returning to foreground.
            if (currentCall && !callConnectedFlag && !localHangupInitiated) {
                callUi.style.display = 'flex';
                if (directCallUiMode === 'incoming') {
                    showPendingDirectCallControls('incoming');
                } else if (directCallUiMode === 'connecting') {
                    showPendingDirectCallControls('connecting');
                } else {
                    showPendingDirectCallControls('outgoing');
                }
            } else {
                // Clean up stale call state
                if (currentCall && !callConnectedFlag) {
                    try { currentCall.close(); } catch {}
                    currentCall = null;
                    callerId = null;
                    if (callUi.style.display === 'flex' && !activeGroupCallId) {
                        callUi.style.display = 'none';
                    }
                }
            }
            // Reconnect PeerJS if disconnected
            if (peer && peer.disconnected && !peer.destroyed) {
                try { peer.reconnect(); } catch {}
            } else if (!peer || peer.destroyed) {
                schedulePeerRecovery({ delayMs: 100 });
            }
            // Immediately check for pending call requests
            pollCallRequests();
            setTimeout(pollCallRequests, 1500);
            setTimeout(pollCallRequests, 3000);
        } else {
            stopOnlineStatusHeartbeat();
            sendOnlineStatusBeacon(0);
        }
    });

    async function respondFriendRequest(requestId, action, popupEl) {
        const fd = new FormData();
        fd.append('token', token);
        fd.append('request_id', requestId);
        fd.append('action', action);
        [...popupEl.querySelectorAll('button')].forEach(b => b.disabled = true);
        try {
            const res = await fetch('handle_request.php', { method: 'POST', body: fd });
            const json = await res.json();
            if (json.success) {
                popupEl.remove();
                if (action === 'accept') {
                    addContact(
                      json.contact.id,
                      json.contact.display_name || json.contact.username,
                      json.contact.username,
                      json.contact.profile_pic,
                      json.contact.online ? 1 : 0,
                      json.contact.bio || '',
                      json.contact.created_at || '',
                      json.contact.last_message_at || ''
                    );

                    clearLocalTyping(true);
                    hideTypingIndicator();
                    await openConversation(json.contact.id);
                    startCallBtnDesktop.style.display = 'block';
                    startCallBtnMobile.style.display = 'block';
                    console.log(`DEBUG: Accepted friend request. Added to map - ID: ${json.contact.id}, Username: ${json.contact.username}`);
                    console.log('DEBUG: Current userNamesMap:', userNamesMap);
                } else if (action === 'reject') {
                    alert('You rejected the friend request.');
                }
            } else {
                alert(json.error || 'Failed to handle friend request.');
                [...popupEl.querySelectorAll('button')].forEach(b => b.disabled = false);
            }
        } catch {
            alert('Network error.');
            [...popupEl.querySelectorAll('button')].forEach(b => b.disabled = false);
        }
    }

    function showIncomingCallRequest(req) {
        const requestId = req && req.id ? String(req.id) : '';
        if (currentCall || !requestId || handledIncomingRequestIds.has(requestId)) return;

        if (req && req.caller_id && isConversationBlocked(req.caller_id)) {
            handledIncomingRequestIds.add(requestId);
            syncCallRequestStatus('rejected', req.id);
            return;
        }

        const rawCallerName = req.display_name || req.username || `User ${req.caller_id}`;
        const callerLabel = getCallDisplayNameForUser(req.caller_id, {
            displayName: rawCallerName,
            username: req.username || '',
            isGroup: false
        }, { chatKey: String(req.caller_id || '') });
        const callerPic = req.profile_pic || 'images/default-profile.png';
        if (req.caller_id) {
            const normalizedCallerId = String(req.caller_id);
            userNamesMap[normalizedCallerId] = rawCallerName;
            if (req.username) {
                userUsernamesMap[normalizedCallerId] = req.username;
            }
            userProfilePics[normalizedCallerId] = callerPic;
        }
        activeCallRequestId = req.id || null;
        document.getElementById('call-image').src = callerPic;
        document.getElementById('call-image').style.borderRadius = '50%';
        callUsername.innerText = `Incoming call from ${callerLabel}...`;
        callStatus.innerText = '';
        callUi.style.display = "flex";
        directCallUiMode = 'incoming';

        // On mobile, the chat container may be hidden (sidebar is showing).
        // Force it visible so the call UI (which lives inside it) is seen.
        if (window.innerWidth <= 768) {
            const chatContainer = document.querySelector('.chat-container');
            if (chatContainer) chatContainer.style.display = 'flex';
            if (sidebar) sidebar.style.display = 'none';
        }
        if(inCallControls) inCallControls.style.display = 'none';
        showPendingDirectCallControls('incoming');

        if (getAppSetting('callRingtone')) {
            ringtoneAudio.play().catch(e => console.error("Ringtone error:", e));
        }

        if (acceptCallBtn) acceptCallBtn.onclick = async () => {
            handledIncomingRequestIds.add(requestId);
            callStatus.innerText = 'Preparing call...';
            acceptCallBtn.style.display = 'none';

            const peerReady = await ensurePeerReadyForIncomingCallAccept();
            if (!peerReady) {
                handledIncomingRequestIds.delete(requestId);
                callStatus.innerText = '';
                directCallUiMode = 'incoming';
                showPendingDirectCallControls('incoming');
                showToast('Call connection is still waking up. Please tap Accept again.', 'error');
                return;
            }

            const accepted = await syncCallRequestStatus('accepted', req.id);
            if (!accepted) {
                handledIncomingRequestIds.delete(requestId);
                ringtoneAudio.pause();
                ringtoneAudio.currentTime = 0;
                callUi.style.display = 'flex';
                callStatus.innerText = '';
                directCallUiMode = 'incoming';
                showPendingDirectCallControls('incoming');
                showToast('Could not accept the call. Please tap Accept again.', 'error');
                return;
            }
            notifyAndroidIncomingCallAnswered();
            ringtoneAudio.pause();
            ringtoneAudio.currentTime = 0;
            // The PeerJS call will arrive via handlePeerCall and be answered there.
            // Just update the UI to show we're waiting for the connection.
            callStatus.innerText = 'Connecting...';
            directCallUiMode = 'connecting';
            showPendingDirectCallControls('connecting');
            clearLocalTyping(true);
            hideTypingIndicator();
            selectedUser = req.caller_id;
            updateHeaderContact(selectedUser);
        };

        endCallBtn.onclick = async () => {
            handledIncomingRequestIds.add(requestId);
            localHangupInitiated = true;
            notifyAndroidIncomingCallRejected();
            await syncCallRequestStatus('rejected', req.id);
            activeCallRequestId = null;
            ringtoneAudio.pause();
            ringtoneAudio.currentTime = 0;
            showTransientDirectCallState('Call Declined', {
                username: callerLabel,
                durationMs: 3000,
                callMessageId: activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null
            });
            clearDirectCallConnectionForGroupPromotion({ preserveEndedUi: true });
        };
    }

    let skipOfflineCheck = false;

    let pendingCallTo = null;
    var outgoingCallSetupInProgress = false;

    // --- PeerJS Calling System Setup ---
    const PEER_BASE_ID = "user_<?= $user_id ?>";
    let savedSuffix = sessionStorage.getItem('peer_id_suffix') || '';
    let finalPeerId = PEER_BASE_ID;
    let peerReconnectTimer = null;
    let pendingPeerRecovery = '';
    const peerConfig = {
        config: {
            iceServers: [
                { urls: 'stun:stun.l.google.com:19302' },
                { urls: 'stun:stun1.l.google.com:19302' },
                // Open Relay — no credentials needed, always fresh
                { urls: 'turn:openrelay.metered.ca:80',      username: 'openrelayproject', credential: 'openrelayproject' },
                { urls: 'turn:openrelay.metered.ca:443',     username: 'openrelayproject', credential: 'openrelayproject' },
                { urls: 'turn:openrelay.metered.ca:443?transport=tcp', username: 'openrelayproject', credential: 'openrelayproject' },
                // Your Metered credentials as backup
                { urls: 'turn:global.relay.metered.ca:80',   username: '4baa73f34291b3f4135f5f77', credential: 'maWtGavK54PqFpeC' },
                { urls: 'turns:global.relay.metered.ca:443?transport=tcp', username: '4baa73f34291b3f4135f5f77', credential: 'maWtGavK54PqFpeC' },
            ],
            iceTransportPolicy: 'all',
        },
        debug: 3
    };

    function computePeerId() {
        finalPeerId = savedSuffix ? `${PEER_BASE_ID}_${savedSuffix}` : PEER_BASE_ID;
        return finalPeerId;
    }

    function attachPeerEventHandlers(targetPeer) {
        if (!targetPeer) {
            return;
        }
        targetPeer.on('open', handlePeerOpen);
        targetPeer.on('error', handlePeerError);
        targetPeer.on('connection', handlePeerConnection);
        targetPeer.on('call', handlePeerCall);
    }

    function rebuildPeerInstance({ forceNewSuffix = false } = {}) {
        if (forceNewSuffix) {
            savedSuffix = String(Math.floor(1000 + Math.random() * 9000));
            sessionStorage.setItem('peer_id_suffix', savedSuffix);
        } else {
            savedSuffix = sessionStorage.getItem('peer_id_suffix') || '';
        }

        const previousPeer = peer;
        const nextPeer = new Peer(computePeerId(), peerConfig);
        peer = nextPeer;
        attachPeerEventHandlers(nextPeer);

        if (previousPeer) {
            try {
                previousPeer.destroy();
            } catch (error) {
                console.warn('Unable to destroy previous PeerJS instance.', error);
            }
        }
    }

    async function syncCurrentPeerIdAlias() {
        if (!peer || peer.destroyed || !peer.id) {
            return false;
        }

        try {
            const response = await fetch('save_peer_id.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    peer_id: String(peer.id)
                })
            });
            const data = await response.json().catch(() => ({}));
            return !!(response.ok && data && data.success);
        } catch (error) {
            console.warn('Unable to sync current peer ID alias.', error);
            return false;
        }
    }

    async function ensurePeerReadyForIncomingCallAccept(timeoutMs = 6000) {
        const hasLivePeer = () => !!(peer && !peer.destroyed && !peer.disconnected && peer.open && peer.id);

        if (hasLivePeer()) {
            await syncCurrentPeerIdAlias();
            return true;
        }

        if (!peer || peer.destroyed) {
            rebuildPeerInstance({ forceNewSuffix: true });
        } else if (peer.disconnected) {
            try {
                peer.reconnect();
            } catch (error) {
                console.warn('PeerJS reconnect failed during call accept, rebuilding peer.', error);
                rebuildPeerInstance({ forceNewSuffix: true });
            }
        }

        const startedAt = Date.now();
        let rebuiltWithSuffix = false;

        while ((Date.now() - startedAt) < timeoutMs) {
            if (hasLivePeer()) {
                await syncCurrentPeerIdAlias();
                return true;
            }

            if (!rebuiltWithSuffix && (!peer || peer.destroyed || peer.disconnected) && (Date.now() - startedAt) > 1200) {
                rebuildPeerInstance({ forceNewSuffix: true });
                rebuiltWithSuffix = true;
            }

            await new Promise(resolve => setTimeout(resolve, 150));
        }

        return hasLivePeer() && await syncCurrentPeerIdAlias();
    }

    function schedulePeerRecovery({ forceNewSuffix = false, delayMs = 900 } = {}) {
        if (currentCall || activeGroupCallId || callConnectedFlag) {
            pendingPeerRecovery = forceNewSuffix ? 'suffix' : (pendingPeerRecovery || 'normal');
            return;
        }

        if (peerReconnectTimer) {
            return;
        }

        peerReconnectTimer = window.setTimeout(() => {
            peerReconnectTimer = null;
            rebuildPeerInstance({ forceNewSuffix });
        }, delayMs);
    }

    function flushPendingPeerRecovery() {
        if (!pendingPeerRecovery) {
            return;
        }
        const forceNewSuffix = pendingPeerRecovery === 'suffix';
        pendingPeerRecovery = '';
        schedulePeerRecovery({ forceNewSuffix, delayMs: 250 });
    }

    let peer = null;
    rebuildPeerInstance();

    window.addEventListener('online', () => {
        schedulePeerRecovery({ delayMs: 250 });
    });

    startOnlineStatusHeartbeat();

    window.addEventListener('beforeunload', () => {
        stopOnlineStatusHeartbeat();
        sendOnlineStatusBeacon(0);
        // Clear peer ID so stale IDs aren't used by callers
        navigator.sendBeacon('save_peer_id.php', JSON.stringify({ token, peer_id: '' }));
        clearLocalTyping(true);
        if (peer) {
            try {
                peer.disconnect();
            } catch (error) {}
            try {
                peer.destroy();
            } catch (error) {}
        }
    });

    window.addEventListener('pagehide', () => {
        stopOnlineStatusHeartbeat();
        sendOnlineStatusBeacon(0);
    });

    function handlePeerOpen(id) {
        console.log("PeerJS: Connected as: " + id);
        // Save our peer ID to the server so others can look it up
        fetch('save_peer_id.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token, peer_id: id })
        }).catch(() => {});
        updateOnlineStatus(1);
    }

    function handlePeerError(err) {
        console.error("PeerJS: Global error:", err);
        const errorType = String(err && err.type ? err.type : '');

        if (errorType === 'unavailable-id') {
            console.warn('PeerJS ID is unavailable. Rebuilding peer with a new suffix.');
            schedulePeerRecovery({ forceNewSuffix: true, delayMs: 300 });
            return;
        }

        if (errorType === 'disconnected') {
            console.log('PeerJS: Connection lost. Attempting reconnect...');
            try {
                if (peer && !peer.destroyed) {
                    peer.reconnect();
                    return;
                }
            } catch (error) {
                console.warn('PeerJS reconnect failed, rebuilding peer.', error);
            }
            schedulePeerRecovery({ delayMs: 600 });
            return;
        }

        if (['network', 'server-error', 'socket-error', 'socket-closed'].includes(errorType)) {
            console.warn(`PeerJS signaling issue (${errorType}). Scheduling peer recovery.`);
            schedulePeerRecovery({ delayMs: 1200 });
            return;
        }

        let errorMessage = 'Call connection error.';
        if (errorType === 'peer-unavailable') {
            // If we're already in an active call, this is a video sub-call failing
            if (callConnectedFlag || activeGroupCallId) {
                console.warn('PeerJS peer-unavailable during active call (video sub-call) — ignoring.');
                const unavailablePeer = err && err.message
                    ? err.message.replace(/.*peer\s+/i, '').replace(/\s+is.*/, '').trim()
                    : '';
                if (unavailablePeer) {
                    const uid = unavailablePeer.replace('user_', '').split('_')[0];
                    if (outgoingVideoCalls[uid]) {
                        closeVideoCallObject(outgoingVideoCalls[uid]);
                        delete outgoingVideoCalls[uid];
                    }
                    removeGroupCallPeer(uid);
                }
                return;
            }
            if (currentCall && !callConnectedFlag && !localHangupInitiated) {
                const failedPeerId = String(currentCall.peer || '').trim();
                const failedMetadata = currentCall.metadata || {};
                retryPendingDirectCallWithFreshPeerId({
                    failedPeerId,
                    metadata: failedMetadata
                }).catch(retryError => {
                    console.warn('Unable to retry direct call after peer-unavailable.', retryError);
                });
            }
            console.warn('PeerJS peer-unavailable before call connected — suppressing popup and waiting for retry/timeout.');
            if (!callConnectedFlag && callUi.style.display === 'flex') {
                callStatus.innerText = 'Ringing...';
                startRingbackAudio();
            }
            return;
        } else if (err && err.message) {
            errorMessage = String(err.message);
        }

        alert(`${errorMessage}${errorType ? ` (Type: ${errorType})` : ''}`);

        if (typeof endPeerCall === "function") {
            endPeerCall(false, "system_error");
        }
    }

    /* NEW: Active call controls globals */
    let audioDevices = [];
    let currentAudioDeviceId = null;
    let isMuted = false;
    const inCallControls = document.getElementById('in-call-controls');
    const audioSelector = document.getElementById('audio-selector');
    const audioIcon = audioSelector ? audioSelector.querySelector('i') : null;
    const audioDropdown = document.getElementById('audio-dropdown');
    const audioDeviceSelect = document.getElementById('audio-device-select');
    const mobileSpeakerOptions = document.getElementById('mobile-speaker-options');
    const speakerPhoneBtn = document.getElementById('speaker-phone-btn');
    const speakerSpeakerBtn = document.getElementById('speaker-speaker-btn');
    const micToggle = document.getElementById('mic-toggle');
    const videoToggle = document.getElementById('video-toggle');
    const screenShareToggle = document.getElementById('screen-share-toggle');
    const endCallActive = document.getElementById('end-call-active');
    
    let currentSpeakerMode = 'phone'; // 'phone' or 'speaker'

    if (inCallControls && inCallControls.parentElement !== document.body) {
        document.body.appendChild(inCallControls);
        inCallControls.style.zIndex = '100002';
    }

    // Click outside to close dropdown
    document.addEventListener('click', (e) => {
        if (audioSelector && audioDropdown && !audioSelector.contains(e.target)) {
            audioDropdown.style.display = 'none';
        }
    });
    /* END NEW */

    /* NEW: Audio helpers */
    async function loadAudioDevices() {
        try {
            // Prompt for permission to populate labels
            await navigator.mediaDevices.getUserMedia({ audio: true });
            audioDevices = await navigator.mediaDevices.enumerateDevices();
            audioDevices = audioDevices.filter(device => device.kind === 'audiooutput');
            console.log('Loaded audio devices:', audioDevices);
        } catch (err) {
            console.error('Error loading audio devices:', err);
        }
    }

    function populateAudioSelector() {
        if (!audioDeviceSelect) return;
        
        // Check if mobile
        const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
        
        if (isMobile && mobileSpeakerOptions) {
            // Show mobile speaker options
            audioDeviceSelect.style.display = 'none';
            mobileSpeakerOptions.style.display = 'block';
            
            // Update active state
            if (speakerPhoneBtn && speakerSpeakerBtn) {
                speakerPhoneBtn.classList.toggle('active', currentSpeakerMode === 'phone');
                speakerSpeakerBtn.classList.toggle('active', currentSpeakerMode === 'speaker');
            }
        } else {
            // Show desktop device selector
            if (mobileSpeakerOptions) mobileSpeakerOptions.style.display = 'none';
            audioDeviceSelect.style.display = 'block';
            
            audioDeviceSelect.innerHTML = '';
            
            // Default option
            const defaultOpt = document.createElement('option');
            defaultOpt.value = '';
            defaultOpt.textContent = 'Auto';
            audioDeviceSelect.appendChild(defaultOpt);

            audioDevices.forEach((device, index) => {
                const opt = document.createElement('option');
                opt.value = device.deviceId;
                opt.textContent = device.label || `Speaker ${index + 1}`;
                audioDeviceSelect.appendChild(opt);
            });

            audioDeviceSelect.onchange = async () => {
                const selectedId = audioDeviceSelect.value;
                if (remoteAudio && selectedId) {
                    try {
                        await remoteAudio.setSinkId(selectedId);
                        currentAudioDeviceId = selectedId;
                        const selectedDevice = audioDevices.find(device => device.deviceId === selectedId);
                        console.log('Switched audio output to:', (selectedDevice && selectedDevice.label) || selectedId);
                    } catch (err) {
                        console.error('Error switching audio device:', err);
                    }
                }
            };
        }
    }
    
    // Mobile speaker mode switching
    async function setSpeakerMode(mode) {
        currentSpeakerMode = mode;
        
        // Update button states
        if (speakerPhoneBtn && speakerSpeakerBtn) {
            speakerPhoneBtn.classList.toggle('active', mode === 'phone');
            speakerSpeakerBtn.classList.toggle('active', mode === 'speaker');
        }
        
        // Update audio icon - use volume-low for phone, volume-up for speaker
        if (audioIcon) {
            if (mode === 'phone') {
                audioIcon.className = 'fas fa-volume-low';
            } else {
                audioIcon.className = 'fas fa-volume-up';
            }
        }
        
        // Switch between internal (earpiece) and external (loudspeaker) audio output
        if (remoteAudio) {
            try {
                // Check if browser supports setSinkId (audio output device selection)
                if (typeof remoteAudio.setSinkId === 'function') {
                    const devices = await navigator.mediaDevices.enumerateDevices();
                    const audioOutputs = devices.filter(d => d.kind === 'audiooutput');
                    
                    console.log('Available audio outputs:', audioOutputs.map(d => ({ id: d.deviceId, label: d.label })));
                    
                    if (mode === 'speaker') {
                        // Try to find external speaker/loudspeaker device
                        const speakerDevice = audioOutputs.find(d => {
                            const label = d.label.toLowerCase();
                            return label.includes('speaker') || 
                                   label.includes('loud') ||
                                   label.includes('external');
                        });
                        
                        if (speakerDevice) {
                            await remoteAudio.setSinkId(speakerDevice.deviceId);
                            console.log('Switched to external speaker:', speakerDevice.label);
                        } else {
                            // Fallback: use default device (usually speaker on mobile)
                            await remoteAudio.setSinkId('');
                            console.log('Switched to default audio output (speaker)');
                        }
                    } else {
                        // Try to find internal earpiece/phone receiver device
                        const phoneDevice = audioOutputs.find(d => {
                            const label = d.label.toLowerCase();
                            return label.includes('earpiece') || 
                                   label.includes('phone') ||
                                   label.includes('receiver') ||
                                   label.includes('internal') ||
                                   label.includes('built-in');
                        });
                        
                        if (phoneDevice) {
                            await remoteAudio.setSinkId(phoneDevice.deviceId);
                            console.log('Switched to internal earpiece:', phoneDevice.label);
                        } else {
                            // Fallback: use first available device (usually earpiece on mobile)
                            if (audioOutputs.length > 0) {
                                await remoteAudio.setSinkId(audioOutputs[0].deviceId);
                                console.log('Switched to first audio output (earpiece):', audioOutputs[0].label);
                            }
                        }
                    }
                } else {
                    console.warn('setSinkId not supported - cannot switch audio output device');
                }
            } catch (err) {
                console.error('Error switching speaker mode:', err);
            }
        }
        
        // Close dropdown
        if (audioDropdown) {
            audioDropdown.style.display = 'none';
        }
    }
    
    // Mobile speaker button event listeners
    if (speakerPhoneBtn) {
        speakerPhoneBtn.addEventListener('click', () => setSpeakerMode('phone'));
    }
    
    if (speakerSpeakerBtn) {
        speakerSpeakerBtn.addEventListener('click', () => setSpeakerMode('speaker'));
    }

    function toggleAudioDropdown() {
        if (!audioDropdown) {
            return;
        }
        audioDropdown.style.display = audioDropdown.style.display === 'block' ? 'none' : 'block';
    }

    function bindMuteToggle(){
        if(!micToggle) return;

        micToggle.onclick = null; // ✅ prevent duplicates

        isMuted = false;

        const track = localAudioStream && localAudioStream.getAudioTracks
            ? localAudioStream.getAudioTracks()[0]
            : null;
        if(track) track.enabled = true;

        const icon = micToggle.querySelector('i');
        icon.className = 'fas fa-microphone';

        micToggle.onclick = () => {
            if(!localAudioStream) return;

            const track = localAudioStream.getAudioTracks()[0];
            if(!track) return;

            const currentlyMuted = !track.enabled;
            const nextMuted = !currentlyMuted;

            track.enabled = !nextMuted;
            isMuted = nextMuted;

            icon.className = isMuted
                ? 'fas fa-microphone-slash'
                : 'fas fa-microphone';

            if(activeDataConnection && activeDataConnection.open){
                activeDataConnection.send({
                    type: 'mute_toggle',
                    muted: isMuted
                });
            }
        };
    }
    // Handle remote mute sync - BIDIRECTIONAL
    function handleMuteSync(data){
        if(data.type !== 'mute_toggle') return;

        console.log(`Remote mic ${data.muted ? 'muted 🔇' : 'unmuted 🎤'}`);

        // ❌ REMOVE THIS BROKEN PART:
        // DO NOT modify localAudioStream or isMuted here
    }

    function sendVisualStateSignal(enabled, mode = 'none') {
        if (activeGroupCallId || !activeDataConnection || !activeDataConnection.open) {
            return;
        }

        try {
            activeDataConnection.send({
                type: 'visual_state',
                enabled: !!enabled,
                mode: enabled ? String(mode || 'camera') : 'none'
            });
        } catch (error) {
            console.warn('Unable to send visual state signal.', error);
        }
    }

    function getUserIdFromPeerId(peerId) {
        const normalized = String(peerId || '').replace(/^user_/, '');
        const [userId] = normalized.split('_');
        return userId || normalized;
    }

    function getDirectCallPeerUserId() {
        if (callerId) {
            return String(callerId);
        }
        if (currentCall && currentCall.peer) {
            return getUserIdFromPeerId(currentCall.peer);
        }
        if (selectedUser && !isGroupChatKey(String(selectedUser || ''))) {
            return String(selectedUser);
        }
        return '';
    }

    function hasLiveLocalVideoTrack() {
        return !!(
            localVideoStream
            && typeof localVideoStream.getVideoTracks === 'function'
            && localVideoStream.getVideoTracks().some(track => track.readyState === 'live')
        );
    }

    function closeOutgoingVisualCalls() {
        Object.keys(outgoingVideoCalls).forEach(userId => {
            const call = outgoingVideoCalls[userId];
            delete outgoingVideoCalls[userId];
            closeVideoCallObject(call);
        });
    }

    function clearLocalVisualStream({ stopTracks = true, closeOutgoingCalls = false } = {}) {
        const previousStream = localVideoStream;
        localVideoStream = null;
        cameraEnabled = false;
        screenShareEnabled = false;
        localVisualMode = 'none';

        sendVisualStateSignal(false, 'none');

        if (stopTracks && previousStream) {
            previousStream.getTracks().forEach(track => track.stop());
        }

        // Keep active video sub-calls alive when the user simply turns their
        // own camera or screen off so the remote stage does not blink away.
        if (closeOutgoingCalls) {
            closeOutgoingVisualCalls();
        }

        updateVideoToggleButtonState();
        updateScreenShareButtonState();
        renderCallVideoLayout();
    }

    function activateLocalVisualStream(stream, mode) {
        if (!stream) {
            return;
        }

        const previousStream = localVideoStream;
        localVideoStream = stream;
        localVisualMode = mode === 'screen' ? 'screen' : 'camera';
        cameraEnabled = localVisualMode === 'camera';
        screenShareEnabled = localVisualMode === 'screen';

        if (previousStream && previousStream !== stream) {
            previousStream.getTracks().forEach(track => track.stop());
        }

        const videoTrack = typeof stream.getVideoTracks === 'function'
            ? stream.getVideoTracks()[0]
            : null;
        if (videoTrack) {
            videoTrack.onended = () => {
                if (localVideoStream === stream) {
                    clearLocalVisualStream({ stopTracks: false });
                }
            };
        }

        closeOutgoingVisualCalls();
        updateVideoToggleButtonState();
        updateScreenShareButtonState();
        renderCallVideoLayout();
        sendVisualStateSignal(true, localVisualMode);
        getActiveVideoTargetUserIds().forEach(userId => ensureOutgoingVideoCall(userId, { forceRefresh: true }));
    }

    function closeVideoCallObject(call) {
        if (!call) {
            return;
        }
        try {
            call.close();
        } catch (error) {
            console.warn('Unable to close video call.', error);
        }
    }

    function updateVideoToggleButtonState() {
        if (!videoToggle) {
            return;
        }

        const icon = videoToggle.querySelector('i');
        const cameraActive = cameraEnabled && localVisualMode === 'camera' && hasLiveLocalVideoTrack();
        if (icon) {
            icon.className = cameraActive ? 'fas fa-video-slash' : 'fas fa-video';
        }
        videoToggle.setAttribute('aria-label', cameraActive ? 'Turn camera off' : 'Turn camera on');
        videoToggle.title = cameraActive ? 'Turn camera off' : 'Turn camera on';
        videoToggle.style.background = cameraActive ? '#2d58f5' : '#303234';
        updateCameraFlipButtonVisibility();
    }

    function updateScreenShareButtonState() {
        // Legacy support - this function is kept for compatibility
        // The actual UI is now in the dropdown menu
        updateScreenShareOptionState();
    }

    function getRemoteVideoFeedEntries() {
        return Object.entries(remoteVideoFeeds)
            .filter(([, entry]) => entry && entry.stream)
            .sort((a, b) => {
                const aName = String(getCallDisplayNameForUser(a[0]) || '').toLowerCase();
                const bName = String(getCallDisplayNameForUser(b[0]) || '').toLowerCase();
                return aName.localeCompare(bName);
            });
    }

    function resolveCallContextChatKey(userId = '', preferredChatKey = '') {
        const normalizedUserId = String(userId || '').trim();
        const normalizedPreferredChatKey = String(preferredChatKey || '').trim();

        if (normalizedPreferredChatKey && !normalizedPreferredChatKey.startsWith('call:')) {
            return normalizedPreferredChatKey;
        }

        if (activeGroupCallKey && isGroupChatKey(String(activeGroupCallKey))) {
            return String(activeGroupCallKey);
        }

        if (selectedUser) {
            const normalizedSelectedUser = String(selectedUser || '').trim();
            if (isGroupChatKey(normalizedSelectedUser)) {
                return normalizedSelectedUser;
            }
            if (!normalizedUserId || normalizedSelectedUser === normalizedUserId) {
                return normalizedSelectedUser;
            }
        }

        if (currentCall && currentCall.peer) {
            const directPeerUserId = String(getUserIdFromPeerId(currentCall.peer) || '').trim();
            if (!normalizedUserId || directPeerUserId === normalizedUserId) {
                return directPeerUserId;
            }
        }

        if (callerId && (!normalizedUserId || String(callerId) === normalizedUserId)) {
            return String(callerId);
        }

        return normalizedUserId;
    }

    function getCallDisplayNameForUser(userId, meta = null, options = {}) {
        const normalizedUserId = String(userId || '').trim();
        if (!normalizedUserId) {
            return 'Unknown';
        }

        if (options.isLocal || normalizedUserId === String(currentUserId)) {
            return 'You';
        }

        const resolvedMeta = meta || getContactMeta(normalizedUserId) || {
            displayName: userNamesMap[normalizedUserId] || getUsernameById(normalizedUserId) || `User ${normalizedUserId}`,
            username: userUsernamesMap[normalizedUserId] || '',
            isGroup: false
        };
        const chatKey = resolveCallContextChatKey(normalizedUserId, options.chatKey || '');

        return getDisplayNameForUser(normalizedUserId, resolvedMeta, chatKey);
    }

    function getCallDisplayNameForChat(chatKey, fallbackDisplayName = '') {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return String(fallbackDisplayName || '').trim() || 'Chat';
        }

        if (normalizedChatKey.startsWith('call:')) {
            return String(fallbackDisplayName || '').trim() || 'Group call';
        }

        if (isGroupChatKey(normalizedChatKey) && isCallOnlyGroupKey(normalizedChatKey)) {
            return String(fallbackDisplayName || '').trim() || 'Group call';
        }

        if (!isGroupChatKey(normalizedChatKey)) {
            return getCallDisplayNameForUser(normalizedChatKey, getContactMeta(normalizedChatKey), {
                chatKey: normalizedChatKey
            });
        }

        const viewerChatNickname = getViewerChatNickname(normalizedChatKey);
        if (viewerChatNickname) {
            return viewerChatNickname;
        }

        const meta = getContactMeta(normalizedChatKey);
        return String((meta && meta.displayName) || fallbackDisplayName || 'Group').trim() || 'Group';
    }

    function getParticipantDisplayName(userId, isLocal = false, chatKey = '') {
        return getCallDisplayNameForUser(userId, null, {
            isLocal,
            chatKey
        });
    }

    function getParticipantProfilePic(userId, isLocal = false) {
        if (isLocal || String(userId) === String(currentUserId)) {
            return currentUserProfilePic || defaultProfilePic;
        }
        return userProfilePics[String(userId)] || defaultProfilePic;
    }

    function getCurrentRemoteParticipantIds() {
        if (activeGroupCallId) {
            if (!groupCallParticipantsEl) {
                return [];
            }
            return Array.from(groupCallParticipantsEl.querySelectorAll('.gc-participant[data-user-id]'))
                .map(el => String(el.dataset.userId || ''))
                .filter(userId => userId && userId !== String(currentUserId));
        }

        const directUserId = getDirectCallPeerUserId();
        return directUserId ? [String(directUserId)] : [];
    }

    function createCallMediaTile(userId, { stream = null, isLocal = false, totalTiles = 1 } = {}) {
        const tile = document.createElement('div');
        tile.className = `call-media-tile ${stream ? 'call-video-tile' : 'call-avatar-tile'}`;
        tile.dataset.userId = String(userId);
        if (isLocal) {
            tile.classList.add('is-local');
            if (localVisualMode === 'camera') {
                tile.classList.add('is-mirrored');
            }
        }
        if (totalTiles === 1) {
            tile.classList.add('single');
        }
        if (speakingParticipantIds.has(String(userId))) {
            tile.classList.add('is-speaking');
        }

        if (stream) {
            const video = document.createElement('video');
            video.autoplay = true;
            video.playsInline = true;
            video.muted = !!isLocal;
            video.srcObject = stream;
            if (!isLocal) {
                video.play().catch(() => {});
            }
            tile.appendChild(video);
        } else {
            const avatarShell = document.createElement('div');
            avatarShell.className = 'call-avatar-shell';

            const avatarImage = document.createElement('img');
            avatarImage.src = getParticipantProfilePic(userId, isLocal);
            avatarImage.alt = getParticipantDisplayName(userId, isLocal);

            avatarShell.appendChild(avatarImage);
            tile.appendChild(avatarShell);
        }

        const identity = document.createElement('div');
        identity.className = 'call-video-identity';

        const avatar = document.createElement('img');
        avatar.className = 'call-video-identity-avatar';
        avatar.src = getParticipantProfilePic(userId, isLocal);
        avatar.alt = getParticipantDisplayName(userId, isLocal);

        const label = document.createElement('span');
        label.textContent = getParticipantDisplayName(userId, isLocal);

        identity.appendChild(avatar);
        identity.appendChild(label);
        tile.appendChild(identity);
        return tile;
    }

    function resetMinimizedCallUiPosition() {
        if (!callUi) {
            return;
        }

        const edgeOffset = window.innerWidth <= 480 ? 10 : 18;
        callUi.style.left = 'auto';
        callUi.style.top = `${edgeOffset}px`;
        callUi.style.right = `${edgeOffset}px`;
        callUi.style.bottom = 'auto';
    }

    function clampMinimizedCallUiPosition(left, top) {
        if (!callUi) {
            return { left, top };
        }

        const margin = window.innerWidth <= 480 ? 8 : 14;
        const cardWidth = callUi.offsetWidth || 280;
        const cardHeight = callUi.offsetHeight || (window.innerWidth <= 480 ? 96 : 128);

        return {
            left: Math.min(Math.max(margin, left), Math.max(margin, window.innerWidth - cardWidth - margin)),
            top: Math.min(Math.max(margin, top), Math.max(margin, window.innerHeight - cardHeight - margin))
        };
    }

    function keepMinimizedCallUiInBounds() {
        if (!callUi || !isCallUiMinimized()) {
            return;
        }

        if (callUi.style.left === '' || callUi.style.left === 'auto') {
            return;
        }

        const currentLeft = parseFloat(callUi.style.left) || 0;
        const currentTop = parseFloat(callUi.style.top) || 0;
        const next = clampMinimizedCallUiPosition(currentLeft, currentTop);
        callUi.style.left = `${next.left}px`;
        callUi.style.top = `${next.top}px`;
        callUi.style.right = 'auto';
        callUi.style.bottom = 'auto';
    }

    function beginMinimizedCallUiDrag(clientX, clientY, pointerId = null) {
        if (!callUi || !isCallUiMinimized()) {
            return;
        }

        const rect = callUi.getBoundingClientRect();
        callUi.style.left = `${rect.left}px`;
        callUi.style.top = `${rect.top}px`;
        callUi.style.right = 'auto';
        callUi.style.bottom = 'auto';

        minimizedCallUiDragState = {
            active: true,
            pointerId,
            startX: clientX,
            startY: clientY,
            originLeft: rect.left,
            originTop: rect.top,
            moved: false
        };
    }

    function updateMinimizedCallUiDrag(clientX, clientY) {
        if (!callUi || !isCallUiMinimized() || !minimizedCallUiDragState.active) {
            return;
        }

        const deltaX = clientX - minimizedCallUiDragState.startX;
        const deltaY = clientY - minimizedCallUiDragState.startY;
        if (Math.abs(deltaX) > 4 || Math.abs(deltaY) > 4) {
            minimizedCallUiDragState.moved = true;
        }

        const next = clampMinimizedCallUiPosition(
            minimizedCallUiDragState.originLeft + deltaX,
            minimizedCallUiDragState.originTop + deltaY
        );

        callUi.style.left = `${next.left}px`;
        callUi.style.top = `${next.top}px`;
        callUi.style.right = 'auto';
        callUi.style.bottom = 'auto';
    }

    function endMinimizedCallUiDrag() {
        const didDrag = minimizedCallUiDragState.moved;
        minimizedCallUiDragState.active = false;
        minimizedCallUiDragState.pointerId = null;
        minimizedCallUiDragState.moved = false;
        return didDrag;
    }

    function syncMinimizedCallUiNavigationState() {
        if (!isMobileViewport()) {
            return;
        }

        if (selectedUser) {
            setMobileConversationVisibility(true);
        } else {
            setMobileConversationVisibility(false);
        }
    }

    function applyCallUiMinimizedState(nextMinimized, { resetPosition = false } = {}) {
        if (!callUi) {
            return;
        }

        const shouldMinimize = !!nextMinimized && canMinimizeCallUi();
        callUi.classList.toggle('is-minimized', shouldMinimize);
        callUi.style.inset = shouldMinimize ? 'auto' : '0';

        if (shouldMinimize) {
            if (resetPosition) {
                resetMinimizedCallUiPosition();
            }
            if (inCallControls && inCallControls.style.display !== 'none') {
                inCallControls.dataset.restoreDisplay = inCallControls.style.display || 'flex';
                inCallControls.style.display = 'none';
            }
            syncMinimizedCallUiNavigationState();
        } else {
            callUi.style.left = '';
            callUi.style.top = '';
            callUi.style.right = '';
            callUi.style.bottom = '';
            if ((activeGroupCallConnected || callConnectedFlag || directCallUiMode === 'connected') && inCallControls) {
                inCallControls.style.display = inCallControls.dataset.restoreDisplay || 'flex';
            } else if (
                directCallUiMode === 'incoming'
                || directCallUiMode === 'outgoing'
                || directCallUiMode === 'connecting'
            ) {
                showPendingDirectCallControls(directCallUiMode);
            }
        }

        minimizedCallUiDragState.active = false;
        minimizedCallUiDragState.pointerId = null;
        renderCallVideoLayout();
        updateCallMessageButtonState();
        updateUnreadAttentionCue();
        if (selectedUser && !shouldDelaySelectedChatRead(selectedUser)) {
            scheduleSelectedChatReadSync(selectedUser);
        }
    }

    function hideInCallControls() {
        if (!inCallControls) {
            return;
        }

        inCallControls.style.display = 'none';
        delete inCallControls.dataset.restoreDisplay;
    }

    function resetLocalVideoPreviewPosition() {
        if (!callVideoLocalPreview) {
            return;
        }

        callVideoLocalPreview.style.left = '';
        callVideoLocalPreview.style.top = '';
        callVideoLocalPreview.style.right = window.innerWidth <= 480 ? '14px' : '24px';
        callVideoLocalPreview.style.bottom = '';
    }

    function clampLocalVideoPreviewPosition(left, top) {
        if (!callVideoLocalPreview) {
            return { left, top };
        }

        const previewWidth = callVideoLocalPreview.offsetWidth || 180;
        const previewHeight = callVideoLocalPreview.offsetHeight || Math.round(previewWidth * 9 / 16);
        const viewportWidth = window.innerWidth;
        const viewportHeight = window.innerHeight;
        const margin = window.innerWidth <= 480 ? 12 : 18;
        const controlsPadding = inCallControls && inCallControls.style.display !== 'none'
            ? (window.innerWidth <= 480 ? 96 : 130)
            : margin;

        return {
            left: Math.min(Math.max(margin, left), Math.max(margin, viewportWidth - previewWidth - margin)),
            top: Math.min(Math.max(margin, top), Math.max(margin, viewportHeight - previewHeight - controlsPadding))
        };
    }

    function keepLocalVideoPreviewInBounds() {
        if (!callVideoLocalPreview || callVideoLocalPreview.hidden || callVideoLocalPreview.style.left === '') {
            return;
        }

        const currentLeft = parseFloat(callVideoLocalPreview.style.left) || 0;
        const currentTop = parseFloat(callVideoLocalPreview.style.top) || 0;
        const next = clampLocalVideoPreviewPosition(currentLeft, currentTop);
        callVideoLocalPreview.style.left = `${next.left}px`;
        callVideoLocalPreview.style.top = `${next.top}px`;
    }

    function beginLocalVideoPreviewDrag(clientX, clientY) {
        if (!callVideoLocalPreview || callVideoLocalPreview.hidden) {
            return;
        }

        const rect = callVideoLocalPreview.getBoundingClientRect();
        if (callVideoLocalPreview.style.left === '') {
            callVideoLocalPreview.style.left = `${rect.left}px`;
            callVideoLocalPreview.style.top = `${rect.top}px`;
            callVideoLocalPreview.style.right = 'auto';
            callVideoLocalPreview.style.bottom = 'auto';
        }

        localVideoPreviewDragState = {
            active: true,
            startX: clientX,
            startY: clientY,
            originLeft: parseFloat(callVideoLocalPreview.style.left) || rect.left,
            originTop: parseFloat(callVideoLocalPreview.style.top) || rect.top
        };
    }

    function updateLocalVideoPreviewDrag(clientX, clientY) {
        if (!localVideoPreviewDragState.active || !callVideoLocalPreview) {
            return;
        }

        const next = clampLocalVideoPreviewPosition(
            localVideoPreviewDragState.originLeft + (clientX - localVideoPreviewDragState.startX),
            localVideoPreviewDragState.originTop + (clientY - localVideoPreviewDragState.startY)
        );
        callVideoLocalPreview.style.left = `${next.left}px`;
        callVideoLocalPreview.style.top = `${next.top}px`;
        callVideoLocalPreview.style.right = 'auto';
        callVideoLocalPreview.style.bottom = 'auto';
    }

    function endLocalVideoPreviewDrag() {
        localVideoPreviewDragState.active = false;
    }

    function renderCallVideoLayout() {
        if (!callUi || !callVideoStage || !callVideoGrid || !callVideoLocalPreview || !callLocalPreviewVideo) {
            return;
        }

        const remoteEntries = getRemoteVideoFeedEntries();
        const remoteParticipantIds = getCurrentRemoteParticipantIds();
        const hasLocalVideo = hasLiveLocalVideoTrack();
        const isMobile = window.innerWidth <= 768;
        const isDirectCall = !activeGroupCallId && !!(currentCall || callConnectedFlag);
        const useMobileDirectLayout = isMobile && isDirectCall;
        const minimizedLayout = isCallUiMinimized();

        let showStage = false;
        let showPreview = false;
        let stageTiles = [];

        if (useMobileDirectLayout) {
            if (remoteParticipantIds.length > 0) {
                const remoteUserId = remoteParticipantIds[0];
                const remoteEntry = remoteVideoFeeds[String(remoteUserId)] || null;
                const hasRemoteVideo = !!(remoteEntry && remoteEntry.stream);
                // Only show stage if there's actual video — not for voice-only calls
                if (hasRemoteVideo || hasLocalVideo) {
                    showStage = true;
                    stageTiles = [{
                        userId: remoteUserId,
                        stream: remoteEntry && remoteEntry.stream ? remoteEntry.stream : null,
                        isLocal: false
                    }];
                    showPreview = hasLocalVideo;
                }
            } else {
                if (hasLocalVideo && localVisualMode === 'screen') {
                    showStage = true;
                    stageTiles = [{
                        userId: String(currentUserId),
                        stream: localVideoStream,
                        isLocal: true
                    }];
                    showPreview = false;
                } else {
                    showStage = false;
                    showPreview = hasLocalVideo;
                }
            }
        } else {
            // Desktop / group: only include participants that have actual video streams
            stageTiles = remoteParticipantIds
                .filter(userId => remoteVideoFeeds[String(userId)] && remoteVideoFeeds[String(userId)].stream)
                .map(userId => ({
                    userId,
                    stream: remoteVideoFeeds[String(userId)].stream,
                    isLocal: false
                }));
            showStage = stageTiles.length > 0;

            if (hasLocalVideo && remoteEntries.length === 0 && localVisualMode === 'screen') {
                stageTiles.push({
                    userId: String(currentUserId),
                    stream: localVideoStream,
                    isLocal: true
                });
                showStage = true;
                showPreview = false;
            } else if (hasLocalVideo && remoteEntries.length === 0) {
                showPreview = true;
            } else if (hasLocalVideo) {
                stageTiles.push({
                    userId: String(currentUserId),
                    stream: localVideoStream,
                    isLocal: true
                });
                showStage = true;
            }
        }

        if (minimizedLayout) {
            if (!showStage && hasLocalVideo && localVideoStream) {
                stageTiles = [{
                    userId: String(currentUserId),
                    stream: localVideoStream,
                    isLocal: true
                }];
                showStage = true;
            }
            showPreview = false;
        }

        callUi.classList.toggle('has-video', showStage || showPreview);
        callVideoStage.hidden = !showStage;
        callVideoLocalPreview.hidden = !showPreview;
        callVideoStage.classList.toggle('is-mobile-direct', showStage && useMobileDirectLayout);
        const callImageEl = document.getElementById('call-image');
        if (callImageEl) {
            callImageEl.style.display = (showStage || showPreview) ? 'none' : '';
        }
        callVideoGrid.innerHTML = '';

        if (showStage) {
            callVideoGrid.classList.toggle('is-mobile-direct', useMobileDirectLayout);
            callVideoGrid.classList.toggle('has-odd', stageTiles.length > 1 && stageTiles.length % 2 === 1);
            stageTiles.forEach(tileMeta => {
                callVideoGrid.appendChild(createCallMediaTile(tileMeta.userId, {
                    stream: tileMeta.stream,
                    isLocal: !!tileMeta.isLocal,
                    totalTiles: stageTiles.length
                }));
            });
        } else {
            callVideoGrid.classList.remove('is-mobile-direct');
            callVideoGrid.classList.remove('has-odd');
            callVideoStage.classList.remove('is-mobile-direct');
        }

        if (showPreview && hasLocalVideo) {
            callLocalPreviewVideo.srcObject = localVideoStream;
            if (callLocalPreviewAvatar) {
                callLocalPreviewAvatar.src = currentUserProfilePic || defaultProfilePic;
            }
            callVideoLocalPreview.classList.toggle('is-mirrored', localVisualMode === 'camera');
            callVideoLocalPreview.classList.toggle('is-speaking', speakingParticipantIds.has(String(currentUserId)));
            keepLocalVideoPreviewInBounds();
        } else {
            callLocalPreviewVideo.srcObject = null;
            callVideoLocalPreview.classList.remove('is-mirrored');
            callVideoLocalPreview.classList.remove('is-speaking');
            if (!hasLocalVideo) {
                resetLocalVideoPreviewPosition();
            }
        }

        if (groupCallParticipantsEl) {
            if (showStage || showPreview) {
                groupCallParticipantsEl.style.display = 'none';
            } else if (groupCallParticipantsEl.children.length) {
                groupCallParticipantsEl.style.display = 'flex';
            }
        }

        updateCallMessageButtonState();
    }

    function removeRemoteVideoFeed(userId, call = null) {
        const normalizedUserId = String(userId || '');
        const existing = remoteVideoFeeds[normalizedUserId];
        if (!existing) {
            return;
        }
        if (call && existing.call && existing.call !== call) {
            return;
        }
        delete remoteVideoFeeds[normalizedUserId];
        renderCallVideoLayout();
    }

    function setRemoteVideoFeed(userId, stream, call) {
        const normalizedUserId = String(userId || '');
        if (!normalizedUserId || !stream) {
            return;
        }

        const videoTrack = typeof stream.getVideoTracks === 'function'
            ? stream.getVideoTracks()[0]
            : null;

        // If the new stream has no video track, the remote user turned off their camera.
        if (!videoTrack) {
            removeRemoteVideoFeed(normalizedUserId, call);
            return;
        }

        remoteVisualStates[normalizedUserId] = true;
        const previous = remoteVideoFeeds[normalizedUserId];
        remoteVideoFeeds[normalizedUserId] = { stream, call };
        if (previous && previous.call && previous.call !== call) {
            closeVideoCallObject(previous.call);
        }

        const handleTrackGone = () => {
            if (remoteVideoFeeds[normalizedUserId] && remoteVideoFeeds[normalizedUserId].stream === stream) {
                remoteVisualStates[normalizedUserId] = false;
                removeRemoteVideoFeed(normalizedUserId, call);
            }
        };

        videoTrack.onended = handleTrackGone;
        let muteTimeoutId = null;
        videoTrack.onmute = () => {
            clearTimeout(muteTimeoutId);
            muteTimeoutId = setTimeout(() => {
                if (!remoteVideoFeeds[normalizedUserId] || remoteVideoFeeds[normalizedUserId].stream !== stream) {
                    return;
                }
                if (videoTrack.readyState !== 'live' || videoTrack.muted) {
                    handleTrackGone();
                }
            }, 700);
        };
        videoTrack.onunmute = () => {
            clearTimeout(muteTimeoutId);
            remoteVisualStates[normalizedUserId] = true;
        };

        // Poll: only remove if track is truly ended (readyState === 'ended')
        const pollId = setInterval(() => {
            if (videoTrack.readyState === 'ended') {
                clearInterval(pollId);
                handleTrackGone();
            }
            // Stop polling if this feed is no longer current
            if (!remoteVideoFeeds[normalizedUserId] || remoteVideoFeeds[normalizedUserId].stream !== stream) {
                clearInterval(pollId);
            }
        }, 1500);

        renderCallVideoLayout();
    }

    function bindVideoCallHandlers(userId, call, direction = 'incoming') {
        if (!call) {
            return;
        }

        const normalizedUserId = String(userId || '');
        call.on('stream', stream => {
            // For outgoing video sub-calls, the answer stream from the remote is
            // audio-only (they answer to keep the connection alive but send their
            // own video via a separate peer.call). Don't treat this as a video feed.
            if (direction === 'outgoing') {
                const hasVideo = stream && typeof stream.getVideoTracks === 'function' && stream.getVideoTracks().length > 0;
                if (!hasVideo) return; // ignore audio-only answer stream
            }
            setRemoteVideoFeed(normalizedUserId, stream, call);
        });

        const cleanup = () => {
            if (direction === 'outgoing' && outgoingVideoCalls[normalizedUserId] === call) {
                delete outgoingVideoCalls[normalizedUserId];
                return;
            }
            removeRemoteVideoFeed(normalizedUserId, call);
        };

        call.on('close', cleanup);
        call.on('error', cleanup);
    }

    function getActiveVideoTargetUserIds() {
        if (activeGroupCallId) {
            if (!groupCallParticipantsEl) {
                return [];
            }
            return Array.from(groupCallParticipantsEl.querySelectorAll('.gc-participant[data-user-id]'))
                .map(el => String(el.dataset.userId || ''))
                .filter(userId => userId && userId !== String(currentUserId));
        }

        const directUserId = getDirectCallPeerUserId();
        return directUserId ? [directUserId] : [];
    }

    function ensureOutgoingVideoCall(userId, { forceRefresh = false } = {}) {
        const normalizedUserId = String(userId || '');
        if (!normalizedUserId || normalizedUserId === String(currentUserId) || !hasLiveLocalVideoTrack()) {
            return;
        }

        if (forceRefresh && outgoingVideoCalls[normalizedUserId]) {
            closeVideoCallObject(outgoingVideoCalls[normalizedUserId]);
            delete outgoingVideoCalls[normalizedUserId];
        }

        if (outgoingVideoCalls[normalizedUserId]) {
            return;
        }

        try {
            const call = peer.call(getGroupCallPeerId(normalizedUserId), localVideoStream, {
                metadata: {
                    mediaKind: 'video',
                    visualMode: localVisualMode || 'camera',
                    callType: activeGroupCallId ? 'group' : 'direct',
                    groupCallId: activeGroupCallId || null
                }
            });
            if (!call) {
                return;
            }

            outgoingVideoCalls[normalizedUserId] = call;
            bindVideoCallHandlers(normalizedUserId, call, 'outgoing');
        } catch (error) {
            console.warn(`Unable to start video for ${normalizedUserId}.`, error);
        }
    }

    async function requestCameraStream(facingMode) {
        const videoConstraints = [];

        if (facingMode) {
            videoConstraints.push({ facingMode: { exact: facingMode } });
            videoConstraints.push({ facingMode });
            videoConstraints.push({ facingMode: { ideal: facingMode } });
        }

        videoConstraints.push(true);

        let lastError = null;
        for (const videoConstraint of videoConstraints) {
            try {
                return await navigator.mediaDevices.getUserMedia({
                    video: videoConstraint,
                    audio: false
                });
            } catch (error) {
                lastError = error;
            }
        }

        throw lastError || new Error('Unable to access camera.');
    }

    async function enableCamera({ forceRestart = false } = {}) {
        if (!forceRestart && hasLiveLocalVideoTrack() && localVisualMode === 'camera') {
            cameraEnabled = true;
            screenShareEnabled = false;
            updateVideoToggleButtonState();
            updateScreenShareButtonState();
            renderCallVideoLayout();
            getActiveVideoTargetUserIds().forEach(userId => ensureOutgoingVideoCall(userId));
            return;
        }

        if (forceRestart && localVideoStream) {
            const previousStream = localVideoStream;
            localVideoStream = null;
            cameraEnabled = false;
            screenShareEnabled = false;
            localVisualMode = 'none';
            previousStream.getTracks().forEach(track => track.stop());
        }

        const stream = await requestCameraStream(currentFacingMode);

        activateLocalVisualStream(stream, 'camera');
    }

    function disableCamera() {
        if (localVisualMode === 'camera' || cameraEnabled) {
            clearLocalVisualStream();
        }
    }

    async function toggleCamera() {
        if (!(activeGroupCallId || callConnectedFlag || currentCall)) {
            return;
        }

        try {
            if (localVisualMode === 'camera' && cameraEnabled) {
                disableCamera();
            } else {
                await enableCamera();
            }
        } catch (error) {
            console.error('Unable to toggle camera.', error);
            alert('Camera permission denied. Cannot start video.');
        }
    }

    async function enableScreenShare() {
        if (hasLiveLocalVideoTrack() && localVisualMode === 'screen') {
            screenShareEnabled = true;
            cameraEnabled = false;
            updateVideoToggleButtonState();
            updateScreenShareButtonState();
            renderCallVideoLayout();
            getActiveVideoTargetUserIds().forEach(userId => ensureOutgoingVideoCall(userId));
            return;
        }

        // On mobile, getDisplayMedia may not be available — try it anyway (modern mobile browsers support it),
        // and only fall back to an error if it truly fails
        if (!navigator.mediaDevices.getDisplayMedia) {
            alert('Screen sharing is not supported on this browser.');
            return;
        }

        const stream = await navigator.mediaDevices.getDisplayMedia({
            video: true,
            audio: false
        });

        activateLocalVisualStream(stream, 'screen');
    }

    function disableScreenShare() {
        if (localVisualMode === 'screen' || screenShareEnabled) {
            clearLocalVisualStream();
        }
    }

    async function toggleScreenShare() {
        if (!(activeGroupCallId || callConnectedFlag || currentCall)) {
            return;
        }

        try {
            if (localVisualMode === 'screen' && screenShareEnabled) {
                disableScreenShare();
            } else {
                await enableScreenShare();
            }
        } catch (error) {
            console.error('Unable to toggle screen share.', error);
            alert('Screen sharing is unavailable right now.');
        }
    }

    function resetCallVideoState() {
        cameraEnabled = false;
        screenShareEnabled = false;
        localVisualMode = 'none';
        speakingDetectionRunId += 1;
        speakingParticipantIds.clear();

        if (localVideoStream) {
            localVideoStream.getTracks().forEach(track => track.stop());
            localVideoStream = null;
        }

        const callsToClose = new Set();
        Object.keys(outgoingVideoCalls).forEach(userId => {
            if (outgoingVideoCalls[userId]) {
                callsToClose.add(outgoingVideoCalls[userId]);
            }
            delete outgoingVideoCalls[userId];
        });
        Object.keys(remoteVideoFeeds).forEach(userId => {
            if (remoteVideoFeeds[userId] && remoteVideoFeeds[userId].call) {
                callsToClose.add(remoteVideoFeeds[userId].call);
            }
            delete remoteVideoFeeds[userId];
        });
        Object.keys(remoteVisualStates).forEach(userId => {
            delete remoteVisualStates[userId];
        });

        callsToClose.forEach(call => closeVideoCallObject(call));

        if (callLocalPreviewVideo) {
            callLocalPreviewVideo.srcObject = null;
        }
        resetLocalVideoPreviewPosition();
        updateVideoToggleButtonState();
        updateScreenShareButtonState();
        renderCallVideoLayout();
    }

    function handleIncomingVideoCall(call, incomingUserId) {
        const normalizedUserId = String(incomingUserId || '');
        const metadata = call && call.metadata && typeof call.metadata === 'object'
            ? call.metadata
            : {};
        const isGroupVideo = metadata.callType === 'group';

        if (isGroupVideo) {
            if (!activeGroupCallId || (metadata.groupCallId && String(metadata.groupCallId) !== String(activeGroupCallId))) {
                closeVideoCallObject(call);
                return;
            }
        } else {
            const directPeerUserId = getDirectCallPeerUserId();
            const directId = getUserIdFromPeerId(directPeerUserId);
            const incomingId = getUserIdFromPeerId(normalizedUserId);
            console.log('CAMERA: handleIncomingVideoCall check — directPeerUserId:', directPeerUserId, 'directId:', directId, 'incomingId:', incomingId);
            if (!directPeerUserId || directId !== incomingId) {
                console.warn('CAMERA: rejected video sub-call — peer mismatch');
                closeVideoCallObject(call);
                return;
            }
        }

        try {
            if (hasLiveLocalVideoTrack()) {
                call.answer(localVideoStream);
            } else if (localAudioStream) {
                // Answer with audio stream to keep the connection alive
                // even if we don't have local video yet
                call.answer(localAudioStream);
            } else {
                call.answer();
            }
        } catch (error) {
            console.warn('Unable to answer incoming video call.', error);
            closeVideoCallObject(call);
            return;
        }

        // Use a direct stream handler instead of bindVideoCallHandlers to avoid
        // the close-cleanup removing the feed when PeerJS cleans up the connection
        call.on('stream', stream => {
            console.log('CAMERA: incoming video stream received from', normalizedUserId);
            // Defer slightly so the video track readyState is 'live'
            setTimeout(() => setRemoteVideoFeed(normalizedUserId, stream, call), 200);
        });
        const cleanupIncomingVideoCall = () => {
            if (remoteVisualStates[normalizedUserId] === false) {
                removeRemoteVideoFeed(normalizedUserId, call);
            }
        };
        call.on('close', cleanupIncomingVideoCall);
        call.on('error', cleanupIncomingVideoCall);
        // Only remove the feed if the main audio call also ends
        // (don't remove on video sub-call close — PeerJS may close it prematurely)
    }

    if (videoToggle) {
        videoToggle.onclick = () => {
            toggleCamera();
        };
    }

    const cameraFlipBtn = document.getElementById('camera-flip');

    async function flipCamera() {
        if (!hasLiveLocalVideoTrack() || localVisualMode !== 'camera' || !cameraEnabled) return;
        const previousFacingMode = currentFacingMode;
        currentFacingMode = currentFacingMode === 'user' ? 'environment' : 'user';
        try {
            await enableCamera({ forceRestart: true });
        } catch (error) {
            currentFacingMode = previousFacingMode;
            try {
                await enableCamera({ forceRestart: true });
            } catch (recoveryError) {
                console.warn('Unable to restore previous camera after flip failure.', recoveryError);
            }
            console.warn('Unable to flip camera immediately.', error);
        }
    }

    function updateCameraFlipButtonVisibility() {
        if (!cameraFlipBtn) return;
        // Never show on desktop
        if (window.innerWidth > 768) { cameraFlipBtn.style.display = 'none'; return; }
        const show = hasLiveLocalVideoTrack() && localVisualMode === 'camera' && cameraEnabled;
        if (show) {
            navigator.mediaDevices.enumerateDevices().then(devices => {
                const videoCams = devices.filter(d => d.kind === 'videoinput');
                cameraFlipBtn.style.display = videoCams.length > 1 ? '' : 'none';
            }).catch(() => { cameraFlipBtn.style.display = 'none'; });
        } else {
            cameraFlipBtn.style.display = 'none';
        }
    }

    if (cameraFlipBtn) {
        cameraFlipBtn.onclick = () => flipCamera();
    }

    // Call more dropdown menu
    const callMoreToggle = document.getElementById('call-more-toggle');
    const callMoreDropdown = document.getElementById('call-more-dropdown');
    const callScreenShareOption = document.getElementById('call-screen-share-option');
    const callInviteUsersOption = document.getElementById('call-invite-users-option');

    if (callMoreToggle && callMoreDropdown) {
        callMoreToggle.onclick = (e) => {
            e.stopPropagation();
            const isVisible = callMoreDropdown.style.display === 'block';
            callMoreDropdown.style.display = isVisible ? 'none' : 'block';
        };

        // Close dropdown when clicking outside
        document.addEventListener('click', (e) => {
            if (callMoreDropdown && !callMoreToggle.contains(e.target) && !callMoreDropdown.contains(e.target)) {
                callMoreDropdown.style.display = 'none';
            }
        });
    }

    if (callScreenShareOption) {
        callScreenShareOption.onclick = () => {
            toggleScreenShare();
            if (callMoreDropdown) callMoreDropdown.style.display = 'none';
        };
    }

    if (callInviteUsersOption) {
        callInviteUsersOption.onclick = () => {
            openInviteUsersModal();
            if (callMoreDropdown) callMoreDropdown.style.display = 'none';
        };
    }

    // Update screen share option visual state
    function updateScreenShareOptionState() {
        if (!callScreenShareOption) return;
        const sharingScreen = screenShareEnabled && localVisualMode === 'screen' && hasLiveLocalVideoTrack();
        if (sharingScreen) {
            callScreenShareOption.classList.add('active');
            callScreenShareOption.querySelector('i').className = 'fas fa-stop';
            callScreenShareOption.querySelector('span').textContent = 'Stop sharing';
        } else {
            callScreenShareOption.classList.remove('active');
            callScreenShareOption.querySelector('i').className = 'fas fa-desktop';
            callScreenShareOption.querySelector('span').textContent = 'Screen share';
        }
    }

    if (callVideoLocalPreview) {
        callVideoLocalPreview.addEventListener('mousedown', event => {
            event.preventDefault();
            beginLocalVideoPreviewDrag(event.clientX, event.clientY);
        });
        callVideoLocalPreview.addEventListener('touchstart', event => {
            const touch = event.touches && event.touches[0];
            if (!touch) {
                return;
            }
            beginLocalVideoPreviewDrag(touch.clientX, touch.clientY);
        }, { passive: true });
    }

    if (callMessageBtn) {
        callMessageBtn.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            applyCallUiMinimizedState(true, { resetPosition: true });
        });
    }

    if (callUi) {
        callUi.addEventListener('pointerdown', event => {
            if (!isCallUiMinimized()) {
                return;
            }
            if (typeof event.button === 'number' && event.button !== 0) {
                return;
            }

            event.preventDefault();
            beginMinimizedCallUiDrag(event.clientX, event.clientY, event.pointerId);
            try {
                callUi.setPointerCapture(event.pointerId);
            } catch (error) {}
        });
    }

    window.addEventListener('mousemove', event => {
        updateLocalVideoPreviewDrag(event.clientX, event.clientY);
    });
    window.addEventListener('touchmove', event => {
        const touch = event.touches && event.touches[0];
        if (!touch) {
            return;
        }
        updateLocalVideoPreviewDrag(touch.clientX, touch.clientY);
    }, { passive: true });
    window.addEventListener('mouseup', endLocalVideoPreviewDrag);
    window.addEventListener('touchend', endLocalVideoPreviewDrag, { passive: true });
    window.addEventListener('pointermove', event => {
        if (!minimizedCallUiDragState.active || minimizedCallUiDragState.pointerId !== event.pointerId) {
            return;
        }
        updateMinimizedCallUiDrag(event.clientX, event.clientY);
    });
    window.addEventListener('pointerup', event => {
        if (!callUi || !minimizedCallUiDragState.active || minimizedCallUiDragState.pointerId !== event.pointerId) {
            return;
        }

        const didDrag = endMinimizedCallUiDrag();
        try {
            callUi.releasePointerCapture(event.pointerId);
        } catch (error) {}

        if (!didDrag && isCallUiMinimized()) {
            applyCallUiMinimizedState(false);
        }
    });
    window.addEventListener('pointercancel', event => {
        if (!callUi || !minimizedCallUiDragState.active || minimizedCallUiDragState.pointerId !== event.pointerId) {
            return;
        }

        endMinimizedCallUiDrag();
        try {
            callUi.releasePointerCapture(event.pointerId);
        } catch (error) {}
    });
    window.addEventListener('resize', () => {
        keepLocalVideoPreviewInBounds();
        keepMinimizedCallUiInBounds();
        renderCallVideoLayout();
    });
    updateVideoToggleButtonState();
    updateScreenShareButtonState();

    // Function to send the 'call_end' signal reliably
    function sendCallEndSignal(peerId, retries = 3, delay = 100) {
        if (!activeDataConnection || activeDataConnection.peer !== peerId || !activeDataConnection.open) {
            console.warn(`SEND_SIGNAL: DataChannel not open for ${peerId}. Current state: ${activeDataConnection ? activeDataConnection.open : 'null'}. Retrying in ${delay}ms... (Retries left: ${retries})`);
            if (retries > 0) {
                setTimeout(() => sendCallEndSignal(peerId, retries - 1, delay * 2), delay);
            } else {
                console.error(`SEND_SIGNAL: Failed to send 'call_end' signal to ${peerId}. DataChannel not open after multiple retries.`);
            }
            return;
        }
        try {
            activeDataConnection.send({ type: 'call_end' });
            console.log(`SEND_SIGNAL: Successfully sent 'call_end' signal to ${peerId}.`);
        } catch (e) {
            console.error(`SEND_SIGNAL: Error sending 'call_end' signal to ${peerId}:`, e);
        }
    }

    async function syncCallRequestStatus(status, requestId = activeCallRequestId) {
        const normalizedId = parseInt(requestId, 10);
        if (!normalizedId || !['accepted', 'rejected'].includes(status)) {
            return false;
        }

        try {
            const res = await fetch('update_call_request.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token,
                    id: normalizedId,
                    status
                })
            });

            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                console.warn(`CALL_REQUEST: Failed to mark request ${normalizedId} as ${status}.`, data);
                return false;
            }

            if (status === 'rejected' || status === 'accepted') {
                handledIncomingRequestIds.add(String(normalizedId));
            }

            return true;
        } catch (e) {
            console.error(`CALL_REQUEST: Failed to sync status ${status} for request ${normalizedId}.`, e);
            return false;
        }
    }

    async function fetchCallRequestStatus(requestId) {
        const normalizedId = parseInt(requestId, 10);
        if (!normalizedId) {
            return null;
        }

        try {
            const res = await fetch(`get_call_request_status.php?token=${encodeURIComponent(token)}&id=${encodeURIComponent(normalizedId)}&t=${Date.now()}`);
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.success) {
                return null;
            }
            return typeof data.status === 'string' ? data.status : null;
        } catch (e) {
            return null;
        }
    }

    async function waitForAcceptedCallRequest(requestId, timeoutMs = RINGING_DURATION, pollIntervalMs = 750) {
        const startedAt = Date.now();
        while (!localHangupInitiated && (Date.now() - startedAt) < timeoutMs) {
            const status = await fetchCallRequestStatus(requestId);
            if (status === 'accepted' || status === 'rejected') {
                return status;
            }
            await new Promise(resolve => setTimeout(resolve, pollIntervalMs));
        }

        return localHangupInitiated ? 'cancelled' : 'timeout';
    }

    // Function to stop local stream and clear call
    function restoreMobileContactsView({ clearSelection = true } = {}) {
        console.log('DEBUG: local restoreMobileContactsView called', { isMobile: isMobileViewport(), mobileBackInlineDisplay: (mobileBackBtn ? mobileBackBtn.style.display : null) });
        const backButtonVisible = !!(mobileBackBtn && mobileBackBtn.style.display !== 'none');
        if (!isMobileViewport() && !backButtonVisible) {
            console.log('DEBUG: restoreMobileContactsView aborted: not mobile and back button not visible');
            return;
        }

        setMobileConversationVisibility(false);
        try {
            activeConversationLoadToken += 1;
        } catch (error) {}

        clearLocalTyping(true);
        hideTypingIndicator();
        hideEmojiPicker();
        clearPendingAttachment(true);
        hideContactInfoPanel();
        closeRightSidebar();

        if (clearSelection) {
            document.querySelectorAll('#contactsList .contact.active').forEach(contactEl => {
                contactEl.classList.remove('active');
            });
            selectedUser = null;
            updateHeaderContact(null);
        }

        requestAnimationFrame(updateMobileContactsStripScrollbar);
        updateMobileBackButtonState();
    }

    window.restoreMobileContactsView = restoreMobileContactsView;

    if (mobileBackBtn) {
        try {
            addTapAndClickListener(mobileBackBtn, handleMobileBackAction);
            mobileBackBtn.addEventListener('keydown', event => {
                if (event.key === 'Enter' || event.key === ' ') {
                    handleMobileBackAction(event);
                }
            });
            console.log('DEBUG: attached mobileBackBtn handlers');
        } catch (e) {
            console.warn('DEBUG: failed to attach mobileBackBtn handlers', e);
        }
    }

    function endPeerCall(notifyPeer = true, reason = "local_hangup") {
        console.log(`END_CALL_FLOW: Initiating endPeerCall. Reason: ${reason}. Notify peer: ${notifyPeer}. localHangupInitiated: ${localHangupInitiated}. callConnectedFlag: ${callConnectedFlag}`);
        const isCallerForHistory = !!(activeCallHistory && String(activeCallHistory.callerId) === String(currentUserId));
        const shouldLogEndedCall = !!(callConnectedFlag && activeCallHistory && isCallerForHistory && ['local_hangup', 'remote_hangup'].includes(reason));
        const shouldLogMissedCall = !!(reason === 'timeout' && activeCallHistory && isCallerForHistory);
        const preservedCallUsername = String(callUsername && callUsername.innerText ? callUsername.innerText : '').trim()
            .replace(/^Calling\s+/i, '')
            .replace(/^Incoming(?:\s+video)?\s+call\s+from\s+/i, '')
            .replace(/\.\.\.$/, '')
            || getUsernameById(callerId || selectedUser || '');

        // NEW: Hide active controls
        hideInCallControls();
        clearActiveGroupCallState();
        if (audioDropdown) audioDropdown.style.display = 'none';
        if (incomingActions) incomingActions.style.display = 'none';
        if (acceptCallBtn) acceptCallBtn.style.display = 'none';
        if (endCallBtn) endCallBtn.style.display = 'none';
        clearPendingCallUiDismiss();
        if (['local_hangup', 'remote_hangup', 'timeout'].includes(String(reason || ''))) {
            freezeStopwatch();
        } else {
            stopStopwatch();
        }
        // END NEW

        // Stop all call audio (ringback and ringtone)
        stopAndResetAudio(ringbackAudio);
        stopAndResetAudio(ringtoneAudio);
        notifyAndroidCallEnded(reason);

        // Only notify peer if a currentCall object exists
        if (notifyPeer && currentCall && currentCall.peer && activeDataConnection &&
            (callConnectedFlag || reason === "local_hangup" || reason === "timeout")) {
            console.log(`END_CALL_FLOW: Attempting to send 'call_end' signal via sendCallEndSignal for peer: ${currentCall.peer} (Reason: ${reason})`);
            sendCallEndSignal(currentCall.peer);
        } else if (notifyPeer) {
            console.warn("END_CALL_FLOW: Not sending 'call_end' signal. Conditions not met for notification.");
        }

        if (activeCallRequestId && !callConnectedFlag && ['local_hangup', 'timeout', 'microphone_error'].includes(reason)) {
            syncCallRequestStatus('rejected');
        }

        if (shouldLogEndedCall) {
            logCallHistoryEntry('ended');
        } else if (shouldLogMissedCall) {
            logCallHistoryEntry('missed');
        } else {
            activeCallHistory = null;
        }

        // --- Cleanup Resources ---
        if (localAudioStream) {
            console.log("END_CALL_FLOW: Stopping local audio tracks.");
            localAudioStream.getTracks().forEach(track => track.stop());
            localAudioStream = null;
        }
        callConnectedFlag = false;
        resetCallVideoState();

        if (currentCall) {
            console.log("END_CALL_FLOW: Closing PeerJS media call object.");
            currentCall.close();
            currentCall = null;
        }

        if (remoteAudio.srcObject) {
            console.log("END_CALL_FLOW: Clearing remote audio source.");
            remoteAudio.srcObject = null;
        }

        if (callTimeoutId) {
            console.log("END_CALL_FLOW: Clearing ringing timeout.");
            clearTimeout(callTimeoutId);
            callTimeoutId = null;
        }

        if(activeDataConnection){
            const conn = activeDataConnection;

            // wait a moment so any signals finish sending
            setTimeout(()=>{
                try{
                    conn.close();
                }catch(e){}
            },800);

            activeDataConnection = null;
        }

        // --- Update UI ---
        applyCallUiMinimizedState(false);
        endCallBtn.style.backgroundColor = 'red';
        directCallUiMode = 'idle';

        // --- Display Alerts based on reason ---
        if (reason === "local_hangup") {
            console.log("END_CALL_FLOW: Call ended by local user. Showing inline ended state.");
            const callMessageId = activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null;
            showTransientDirectCallState("Call ended", {
                username: preservedCallUsername,
                durationMs: 2600,
                callMessageId
            });
        } else if (reason === "remote_hangup") {
            console.log("END_CALL_FLOW: Call ended by remote user. Showing inline ended state.");
            const callMessageId = activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null;
            showTransientDirectCallState("Call ended", {
                username: preservedCallUsername,
                durationMs: 2600,
                callMessageId: callMessageId
            });
        } else if (reason === "timeout") {
            console.log("END_CALL_FLOW: Outgoing call timed out. Displaying message.");
            const callMessageId = activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null;
            showTransientDirectCallState("Didn't answer.", {
                username: getUsernameById(selectedUser) || preservedCallUsername,
                durationMs: 3000,
                callMessageId: callMessageId
            });
        } else if (reason === "microphone_error") {
            console.log("END_CALL_FLOW: Call ended due to microphone error.");
            callUi.style.display = "none";
            callStatus.innerText = "";
            callUsername.innerText = "";
            updateCallMessageButtonState();
            alert(`Microphone access failed for this call. Cannot continue.`);
        } else {
            callUi.style.display = "none";
            callStatus.innerText = "";
            callUsername.innerText = "";
            updateCallMessageButtonState();
        }

        // Reset mute state
        isMuted = false;
        
        // Reset flags
        localHangupInitiated = false;
        activeCallRequestId = null;
        callerId = null;
        pendingCallTo = null;
        outgoingCallSetupInProgress = false;
        clearPromotedDirectCallContext();
        // Clear participant strip
        if (groupCallParticipantsEl) { groupCallParticipantsEl.innerHTML = ''; groupCallParticipantsEl.style.display = 'none'; }
        teardownAllGroupCallPeers();
        flushPendingPeerRecovery();

        restoreMobileContactsView();
        console.log("END_CALL_FLOW: endPeerCall finished.");
    }

    // Initial binding for the End Call button
    bindDefaultEndCallButton();

    // Centralized function to set up call event handlers for the media call
    function setupCallHandlers(call) {
        console.log(`CALL_HANDLER: Setting up media call handlers for peer: ${call.peer}`);

        // Attach ontrack to the RTCPeerConnection to receive video added via renegotiation.
        // peerConnection may not exist yet — retry until it does (max 5s).
        let _attachAttempts = 0;
        function attachOnTrack() {
            const pc = call.peerConnection;
            if (!pc) {
                if (++_attachAttempts < 50) setTimeout(attachOnTrack, 100);
                return;
            }
            pc.addEventListener('track', (evt) => {
                if (evt.track && evt.track.kind === 'video') {
                    const remoteUserId = getUserIdFromPeerId(call.peer);
                    if (remoteUserId) {
                        const videoStream = (evt.streams && evt.streams[0])
                            ? evt.streams[0]
                            : new MediaStream([evt.track]);
                        setRemoteVideoFeed(remoteUserId, videoStream, call);
                    }
                }
            });
        }
        attachOnTrack();

        call.on('stream', async (remoteStream) => {
            if (groupCallTeardownInProgress) {
                return;
            }
            console.log("CALL_HANDLER: Stream received! Call connected.");
            remoteAudio.srcObject = remoteStream;
            remoteAudio.play().catch(() => {});
            // Strip the "Calling " / "Incoming call from " prefix now that we're connected
            if (callUsername.innerText.startsWith('Calling ')) {
                callUsername.innerText = callUsername.innerText.replace(/^Calling\s+/, '').replace(/\.\.\.$/, '');
            } else if (callUsername.innerText.startsWith('Incoming call from ')) {
                callUsername.innerText = callUsername.innerText.replace(/^Incoming call from\s+/, '').replace(/\.\.\.$/, '');
            }
            callStatus.innerText = "Connected"; startStopwatch();
            callConnectedFlag = true;

            // Auto-enable camera if this was a video call (outgoing) or incoming video with checkbox ticked
            const wasVideoCall = pendingVideoCall; // outgoing video call flag
            pendingVideoCall = false;
            const incomingVideoAccepted = pendingIncomingVideoCall
                && !!(incomingCameraToggle && incomingCameraToggle.checked);
            pendingIncomingVideoCall = false;
            if (wasVideoCall || incomingVideoAccepted) {
                const exactPeerId = call.peer;
                const exactUserId = getUserIdFromPeerId(exactPeerId);

                (async () => {
                    let camStream;
                    try {
                        camStream = await requestCameraStream(currentFacingMode);
                    } catch (e) {
                        console.warn('CAMERA: permission denied:', e);
                        return;
                    }
                    // Show local preview — wait a tick so the track readyState is 'live'
                    localVideoStream = camStream;
                    localVisualMode = 'camera';
                    cameraEnabled = true;
                    screenShareEnabled = false;
                    updateVideoToggleButtonState();
                    updateScreenShareButtonState();
                    // Defer renderCallVideoLayout so the video track is live
                    setTimeout(() => renderCallVideoLayout(), 200);

                    // Send video via a dedicated PeerJS video sub-call
                    if (exactUserId && exactPeerId) {
                        if (outgoingVideoCalls[exactUserId]) {
                            closeVideoCallObject(outgoingVideoCalls[exactUserId]);
                            delete outgoingVideoCalls[exactUserId];
                        }
                        try {
                            const vc = peer.call(exactPeerId, camStream, {
                                metadata: { mediaKind: 'video', callType: 'direct' }
                            });
                            if (vc) {
                                outgoingVideoCalls[exactUserId] = vc;
                                bindVideoCallHandlers(exactUserId, vc, 'outgoing');
                                console.log('CAMERA: video sub-call placed to', exactPeerId);
                            }
                        } catch (e) {
                            console.warn('CAMERA: peer.call failed:', e);
                        }
                    }
                })();
            }
            if (incomingCameraToggleWrap) incomingCameraToggleWrap.style.display = 'none';
            // Show participant strip for direct calls (caller + callee)
            const otherUserId = callerId || (call.peer ? getUserIdFromPeerId(call.peer) : null);
            if (otherUserId) {
                renderAdhocCallParticipants([String(otherUserId)]);
                // Speaking detection for the remote stream
                addGroupCallPeerAudio(otherUserId, remoteStream, { attachAudio: false });
                // Override remoteAudio since addGroupCallPeerAudio creates its own element
                // Keep remoteAudio.srcObject for compatibility
            }

            if (activeCallRequestId) {
                syncCallRequestStatus('accepted');
            }

            if (callTimeoutId) {
                console.log("CALL_HANDLER: Call connected, clearing ringing timeout.");
                clearTimeout(callTimeoutId);
                callTimeoutId = null;
            }
            if (localAudioStream) {
                startCallSpeakingDetection(localAudioStream, currentUserId);
            }
            stopAndResetAudio(ringbackAudio);

            // FIXED UI FLOW: Hide accept/reject → show ONLY active controls on connected
            showConnectedDirectCallControls();

            // Init audio devices if needed
            if (audioDevices.length === 0) {
                await loadAudioDevices();
                populateAudioSelector();
            }
            
            // Initialize to phone mode by default
            await setSpeakerMode('phone');
            
            // Bind controls (idempotent - safe to call multiple times)
            if (audioIcon) audioIcon.onclick = toggleAudioDropdown;
            bindMuteToggle();
            updateVideoToggleButtonState();
            
            if (endCallActive) {
                endCallActive.onclick = () => {
                    localHangupInitiated = true;
                    endPeerCall(true, "local_hangup");
                };
            }
            // END FIXED
        });

        call.on('close', () => {
            console.log("CALL_HANDLER: Media call 'close' event fired for peer:", call.peer);
            if (suppressDirectCallCloseDuringPromotion) {
                console.log("CALL_HANDLER: Suppressing direct call close during group call promotion.");
                return;
            }
            if (!localHangupInitiated && callConnectedFlag) {
                endPeerCall(false, "remote_hangup");
            }
        });

        call.on('error', err => {
            console.error("CALL_HANDLER: Media call error:", err);
            if (String(err && err.type ? err.type : '') === 'peer-unavailable') {
                console.warn("CALL_HANDLER: Suppressing peer-unavailable during outgoing call setup.");
                if (!callConnectedFlag && callUi.style.display === 'flex') {
                    callStatus.innerText = 'Ringing...';
                    startRingbackAudio();
                }
                return;
            }
            alert("Call encountered an error: " + (err.type || err.message));
            endPeerCall(false, "system_error");
        });
    }

    // Handle incoming DataConnections (for signaling)
    function handlePeerConnection(conn) {
        console.log("DATA_CONN: Incoming DataConnection from:", conn.peer);
        if (activeDataConnection === null) {
            activeDataConnection = conn;
            setupDataConnectionHandlers(activeDataConnection);
        } else if (activeDataConnection.peer === conn.peer) {
            conn.close();
        } else {
            conn.close();
        }
    }

    // Centralized function to set up data connection event handlers
    function setupDataConnectionHandlers(conn) {
        conn.on('open', () => {
            console.log(`DATA_CONN_HANDLER: Data connection opened with: ${conn.peer}`);
        });

        conn.on('data', data => {
            if (data.type === 'call_end') {
                endPeerCall(false, "remote_hangup");
            } 
            else if (data.type === 'call_rejected') {
                console.log("DATA_CONN: Call was explicitly rejected by the user.");
                stopAndResetAudio(ringbackAudio);
                syncCallRequestStatus('rejected');

                // Show Call Declined screen with call ended controls
                const callMessageId = activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null;
                showTransientDirectCallState("Call Declined", {
                    username: getUsernameById(selectedUser) || callUsername.innerText,
                    durationMs: 3000,
                    callMessageId: callMessageId
                });
                clearDirectCallConnectionForGroupPromotion({ preserveEndedUi: true });
            }
            else if (data.type === 'group_call_promotion_ack') {
                if (typeof pendingDirectCallPromotionAckResolve === 'function') {
                    const resolvePromotionAck = pendingDirectCallPromotionAckResolve;
                    pendingDirectCallPromotionAckResolve = null;
                    resolvePromotionAck(true);
                }
            }
            else if (data.type === 'promote_to_group_call') {
                if (conn && conn.open) {
                    try {
                        conn.send({ type: 'group_call_promotion_ack' });
                    } catch {}
                }

                armDirectCallCloseSuppression();
                const promotedGroupKey = buildGroupCallUiKey(data.group_call_id, data.group_key, data.group_id);
                if (promotedGroupKey && parseInt(data.group_id, 10) > 0) {
                    callOnlyGroupIds.add(promotedGroupKey);
                }

                const directPeerUserId = getUserIdFromPeerId(conn.peer);
                capturePromotedDirectCallContext({
                    groupCallId: data.group_call_id,
                    groupKey: promotedGroupKey,
                    otherUserId: directPeerUserId,
                    callerId: activeCallHistory && activeCallHistory.callerId ? activeCallHistory.callerId : directPeerUserId
                });

                const retainedStream = localAudioStream || null;
                clearDirectCallConnectionForGroupPromotion({
                    preserveLocalStream: !!retainedStream,
                    preserveStopwatch: true,
                    preserveCallHistory: true
                });
                acceptGroupCall(data.group_call_id, promotedGroupKey, {
                    existingStream: retainedStream,
                    suppressAlerts: true,
                    groupName: data.group_name || '',
                    groupIcon: data.group_icon || '',
                    preserveCallUi: true,
                    keepExistingCallUi: true
                }).catch(error => {
                    clearPromotedDirectCallContext(data.group_call_id);
                    console.error('Failed to join promoted group call:', error);
                    showToast('Unable to join the updated call right now.', 'error');
                });
            }
            else if (data.type === 'visual_state') {
                const remoteUserId = getUserIdFromPeerId(conn.peer);
                if (remoteUserId) {
                    remoteVisualStates[remoteUserId] = !!data.enabled;
                }
                if (!data.enabled && remoteUserId) {
                    removeRemoteVideoFeed(remoteUserId);
                }
            }
            else {
                handleMuteSync(data);
            }
        });

        conn.on('close', () => {
            if (activeDataConnection === conn) {
                activeDataConnection = null;
            }
        });
    }
        
    // --- Receiver's side: Listen for incoming calls ---
    async function handlePeerCall(call) {
        const incomingCallerId = getUserIdFromPeerId(call.peer);
        const callMetadata = call && call.metadata && typeof call.metadata === 'object'
            ? call.metadata
            : {};

        const callReqIdFromMeta = callMetadata && (callMetadata.call_request_id || callMetadata.callRequestId)
            ? String(callMetadata.call_request_id || callMetadata.callRequestId)
            : null;

        if (callMetadata.mediaKind === 'video') {
            // Only handle as video sub-call if we're already in an active call
            // If not in a call yet, treat as a regular incoming call (video flag just shows checkbox)
            if (callConnectedFlag || activeGroupCallId) {
                handleIncomingVideoCall(call, incomingCallerId);
                return;
            }
            // Fall through to normal incoming call handling — checkbox will be shown
        }

        // If we're in an active group call, auto-answer and add audio
        if (activeGroupCallId) {
            if (groupCallTeardownInProgress) {
                try { call.close(); } catch {}
                return;
            }
            let answerStream = null;
            try {
                const ensuredAudio = await ensureLiveLocalAudioStream(localAudioStream);
                answerStream = ensuredAudio.stream;
            } catch {
                call.close();
                return;
            }
            call.answer(answerStream);
            if (cameraEnabled) {
                ensureOutgoingVideoCall(incomingCallerId);
            }
            call.on('stream', (remoteStream) => {
                if (groupCallTeardownInProgress || !activeGroupCallId) {
                    return;
                }
                addGroupCallPeerAudio(incomingCallerId, remoteStream);
                // Add this caller to the participant strip if not already there
                if (!groupCallParticipantsEl) return;
                if (!groupCallParticipantsEl.querySelector(`.gc-participant[data-user-id="${incomingCallerId}"]`)) {
                    const existingIds = Array.from(groupCallParticipantsEl.querySelectorAll('.gc-participant'))
                        .map(el => el.dataset.userId).filter(Boolean);
                    const nextRemoteIds = [...existingIds.filter(id => id && id !== String(currentUserId)), incomingCallerId];
                    if (getPromotedDirectCallContext(activeGroupCallId) && nextRemoteIds.length > 1) {
                        activatePromotedGroupUi();
                    }
                    renderAdhocCallParticipants(nextRemoteIds);
                }
            });
            call.on('close', () => removeGroupCallPeer(incomingCallerId));
            call.on('error', () => removeGroupCallPeer(incomingCallerId));
            return;
        }

        const shouldAutoAnswerAcceptedDirectCall = !!(
            // Only auto-answer if the local UI was put into 'connecting' by the
            // local user's explicit Accept action and the metadata matches the
            // same call_request_id. This avoids auto-answering merely because
            // the server has an 'accepted' status for the request.
            directCallUiMode === 'connecting'
            && activeCallRequestId
            && callReqIdFromMeta
            && String(activeCallRequestId) === String(callReqIdFromMeta)
            && (!selectedUser || String(selectedUser) === String(incomingCallerId))
        );

        const activeCurrentCallPeerUserId = currentCall && currentCall.peer
            ? String(getUserIdFromPeerId(currentCall.peer) || '').trim()
            : '';
        const shouldReplaceStalePendingDirectCall = !!(
            currentCall
            && !callConnectedFlag
            && !activeGroupCallId
            && directCallUiMode === 'connecting'
            && activeCurrentCallPeerUserId
            && activeCurrentCallPeerUserId === String(incomingCallerId || '').trim()
        );

        console.log('Incoming call received from:', call.peer);
        if (shouldReplaceStalePendingDirectCall) {
            console.warn('Replacing stale pending direct call with a fresh incoming call attempt.');
            try { currentCall.close(); } catch (error) {}
            currentCall = null;
            if (activeDataConnection && activeDataConnection.peer === call.peer) {
                try { activeDataConnection.close(); } catch (error) {}
                activeDataConnection = null;
            }
        }
        if (currentCall) {
            call.answer(); 
            setTimeout(() => call.close(), 500);
            return;
        }

        currentCall = call;
        callerId = getUserIdFromPeerId(incomingCallerId);
        
        // SECURITY: Check if caller is blocked
        if (isConversationBlocked(callerId)) {
            console.warn('Rejected call from blocked user:', callerId);
            try { call.close(); } catch (e) {}
            currentCall = null;
            callerId = null;
            return;
        }

        // SECURITY: Validate friendship before accepting call
        try {
            const friendCheckRes = await fetch('check_friendship.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ 
                    token: token, 
                    user_id: callerId 
                })
            });
            const friendCheckData = await friendCheckRes.json();
            
            if (!friendCheckData.are_friends) {
                console.warn('Rejected call from non-friend:', callerId);
                try { call.close(); } catch (e) {}
                currentCall = null;
                callerId = null;
                return;
            }
        } catch (e) {
            console.error('Failed to verify friendship, rejecting call:', e);
            try { call.close(); } catch (err) {}
            currentCall = null;
            callerId = null;
            return;
        }

        beginCallHistory(callerId, callerId);

        // If the callee already accepted via the call request UI, auto-answer
        if (shouldAutoAnswerAcceptedDirectCall) {
            const callerPic = userProfilePics[callerId] || 'images/default-profile.png';
            document.getElementById('call-image').src = callerPic;
            document.getElementById('call-image').style.borderRadius = '50%';
            const isVideoCall = !!(call.metadata && call.metadata.mediaKind === 'video');
            const callerLabel = getCallDisplayNameForUser(callerId, getContactMeta(callerId), {
                chatKey: String(callerId || '')
            });
            callUsername.innerText = isVideoCall
                ? `Incoming video call from ${callerLabel}...`
                : `Incoming call from ${callerLabel}...`;
            callUi.style.display = 'flex';
            callStatus.innerText = 'Connecting...';
            directCallUiMode = 'connecting';
            showPendingDirectCallControls('connecting');
            if (window.innerWidth <= 768) {
                const chatContainer = document.querySelector('.chat-container');
                if (chatContainer) chatContainer.style.display = 'flex';
                if (sidebar) sidebar.style.display = 'none';
            }
            if (incomingCameraToggleWrap) {
                incomingCameraToggleWrap.style.display = 'none';
                incomingCameraToggleWrap.dataset.isVideoCall = isVideoCall ? '1' : '0';
            }
            pendingIncomingVideoCall = isVideoCall;
            call.on('close', () => {
                if (currentCall === call && !callConnectedFlag && !localHangupInitiated) {
                    currentCall = null;
                    if (
                        directCallUiMode === 'connecting'
                        && activeCallRequestId
                        && callReqIdFromMeta
                        && String(activeCallRequestId) === String(callReqIdFromMeta)
                    ) {
                        console.warn('Accepted direct call attempt closed before connecting; waiting for retry.');
                        callUi.style.display = 'flex';
                        callStatus.innerText = 'Connecting...';
                        showPendingDirectCallControls('connecting');
                        return;
                    }
                    activeCallRequestId = null;
                    endPeerCall(false, 'none');
                }
            });
            try {
                // Ensure a data connection exists for signaling
                try {
                    if (!activeDataConnection || activeDataConnection.peer !== call.peer) {
                        activeDataConnection = peer.connect(call.peer, { reliable: true });
                        setupDataConnectionHandlers(activeDataConnection);
                    }
                } catch (e) {
                    console.warn('Auto-answer: failed to establish data connection', e);
                }

                const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                localAudioStream = stream;
                call.answer(stream);
                setupCallHandlers(call);
            } catch (e) {
                endPeerCall(true, 'microphone_error');
            }
            return;
        }

        resetCallUI();

        // UI Setup
        const callerPic = userProfilePics[callerId] || 'images/default-profile.png';
        document.getElementById('call-image').src = callerPic;
        document.getElementById('call-image').style.borderRadius = '50%';

        // Check if this is a video call (caller has video metadata)
        const isVideoCall = !!(call.metadata && call.metadata.mediaKind === 'video');
        const callerLabel = getCallDisplayNameForUser(callerId, getContactMeta(callerId), {
            chatKey: String(callerId || '')
        });
        callUsername.innerText = isVideoCall
            ? `Incoming video call from ${callerLabel}...`
            : `Incoming call from ${callerLabel}...`;
        callStatus.innerText = '';
        callUi.style.display = "flex";
        directCallUiMode = 'incoming';

        // On mobile, force chat container visible so call UI shows even without a selected contact
        if (window.innerWidth <= 768) {
            const chatContainer = document.querySelector('.chat-container');
            if (chatContainer) chatContainer.style.display = 'flex';
            if (sidebar) sidebar.style.display = 'none';
        }

        // Show camera toggle ONLY for video calls
        if (incomingCameraToggleWrap) {
            incomingCameraToggleWrap.style.display = isVideoCall ? 'flex' : 'none';
            incomingCameraToggleWrap.dataset.isVideoCall = isVideoCall ? '1' : '0';
        }
        if (incomingCameraToggle) {
            incomingCameraToggle.checked = isVideoCall; // ticked by default for video calls
        }
        // Store flag so stream handler knows this was a video call
        pendingIncomingVideoCall = isVideoCall;

        const rejectBtn = document.getElementById('end-call-btn'); // This is the same as endCallBtn
        showPendingDirectCallControls('incoming');

        if (getAppSetting('callRingtone')) {
            ringtoneAudio.play().catch(e => console.warn("Audio blocked"));
        }

        call.on('close', () => {
            if (currentCall === call && !callConnectedFlag && !localHangupInitiated) {
                activeCallRequestId = null;
                endPeerCall(false, "none");
            }
        });

        // Force Data Connection
        if (!activeDataConnection || activeDataConnection.peer !== call.peer) {
            activeDataConnection = peer.connect(call.peer, { reliable: true });
            setupDataConnectionHandlers(activeDataConnection);
        }

        // REJECT LOGIC (Inside the call event)
        rejectBtn.onclick = () => {
            localHangupInitiated = true;
            notifyAndroidIncomingCallRejected();
            stopAndResetAudio(ringtoneAudio);
            syncCallRequestStatus('rejected', callReqIdFromMeta || activeCallRequestId);

            const attemptRejectSignal = (attempts) => {
                if (activeDataConnection && activeDataConnection.open) {
                    setTimeout(()=>{
                        activeDataConnection.send({type:'call_rejected'});
                    },50);
                    // Clean up call and show Call Declined screen
                    setTimeout(() => {
                        if (currentCall === call) {
                            try { call.close(); } catch {}
                            currentCall = null;
                        }
                        if (activeDataConnection) {
                            try { activeDataConnection.close(); } catch {}
                            activeDataConnection = null;
                        }
                        activeCallRequestId = null;
                        callerId = null;
                        
                        const callMessageId = activeCallHistory && activeCallHistory.messageId ? activeCallHistory.messageId : null;
                        showTransientDirectCallState("Call Declined", {
                            username: getUsernameById(selectedUser) || callUsername.innerText,
                            durationMs: 3000,
                            callMessageId: callMessageId
                        });
                    }, 300);
                } else if (attempts > 0) {
                    setTimeout(() => attemptRejectSignal(attempts - 1), 250);
                } else {
                    // Clean up and show Call Declined screen even if signal failed
                    if (currentCall === call) {
                        try { call.close(); } catch {}
                        currentCall = null;
                    }
