            if (event.stopPropagation) event.stopPropagation();
        }
        if (!selectedUser) return alert('Please select a contact to call.');
        if (getChatTypeFromKey(selectedUser) === 'group') {
            initiateGroupCall(selectedUser);
        } else {
            initiateCall();
        }
    }

    function bindCallButton(button, handler) {
        if (!button) return;
        button.onclick = null;
        button.addEventListener('click', handler, { passive: false });
    }

    async function handleVideoCallButtonClick(event) {
