    function urlBase64ToUint8Array(base64String) {
        const padding = '='.repeat((4 - base64String.length % 4) % 4);
        const base64 = (base64String + padding)
            .replace(/-/g, '+')
            .replace(/_/g, '/');

        const rawData = atob(base64);
        const outputArray = new Uint8Array(rawData.length);

        for (let i = 0; i < rawData.length; ++i) {
            outputArray[i] = rawData.charCodeAt(i);
        }
        return outputArray;
    }


    async function legacyInitPush() {
        if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;

        // 1. Register with explicit scope
        const reg = await navigator.serviceWorker.register('/push-sw.js', { scope: '/' });

        // 2. WAIT for the Service Worker to be active
        // This is the #1 reason notifications fail when the app is closed
        await navigator.serviceWorker.ready;

        let sub = await reg.pushManager.getSubscription();

        // 3. Force re-subscribe if it's broken or missing
        if (sub) {
            await sub.unsubscribe(); 
        }

        sub = await reg.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
        });

        // 4. Send to server
        await fetch('/save_subscription.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token: token, subscription: sub })
        });

        console.log('Push active even when closed 🔔');
    }



    async function initPush() {
        if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) return;

        try {
            if (Notification.permission !== 'granted') {
                const permission = await Notification.requestPermission();
                if (permission !== 'granted') {
                    return;
                }
            }

            const reg = await navigator.serviceWorker.register('/push-sw.js', { scope: '/' });
            await navigator.serviceWorker.ready;

            let sub = await reg.pushManager.getSubscription();
            if (sub) {
                await sub.unsubscribe();
            }

            sub = await reg.pushManager.subscribe({
                userVisibleOnly: true,
                applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
            });

            await fetch('/save_subscription.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ token: token, subscription: sub })
            });

            console.log('Push active even when closed.');
        } catch (error) {
            console.error('Unable to initialize push notifications.', error);
        }
    }

