    async function refreshUnreadBadges() {
        try {
            const res = await fetch(`get_unread_counts.php?token=${token}`);
            const data = await res.json().catch(() => ({}));
            const rows = Array.isArray(data) ? data : (Array.isArray(data.rows) ? data.rows : []);
            const senders = !Array.isArray(data) && Array.isArray(data.senders) ? data.senders : [];

            unreadOverlayState.rows = rows;
            unreadOverlayState.senders = senders;

            document.querySelectorAll('.contact').forEach(c => {
                c.classList.remove('unread');
                const old = c.querySelector('.unread-badge');
                if (old) old.remove();
            });

            const unreadCountByChat = new Map();

            rows.forEach(row => {
                const chatKey = String(row.chat_key || row.sender_id || '');
                if (!chatKey) {
                    return;
                }

                if (
                    String(selectedUser || '') === chatKey
                    && !shouldDelaySelectedChatRead(chatKey)
                    && !isManuallyUnreadChatId(chatKey)
                ) {
                    delete mentionUnreadCounts[chatKey];
                    return;
                }

                const effectiveCount = getUnreadEffectiveCount(row);
                if (effectiveCount <= 0) {
                    return;
                }

                unreadCountByChat.set(
                    chatKey,
                    Math.max(unreadCountByChat.get(chatKey) || 0, effectiveCount)
                );
            });

            manualUnreadChatIds.forEach(chatKey => {
                const normalizedChatKey = String(chatKey || '').trim();
                if (!normalizedChatKey) {
                    return;
                }

                unreadCountByChat.set(
                    normalizedChatKey,
                    Math.max(unreadCountByChat.get(normalizedChatKey) || 0, 1)
                );
            });

            let totalUnread = 0;
            unreadCountByChat.forEach((effectiveCount, chatKey) => {
                if (!(effectiveCount > 0)) {
                    return;
                }

                const contact = document.querySelector(`.contact[data-id="${chatKey}"]`);
                if (!contact) {
                    totalUnread += effectiveCount;
                    return;
                }

                contact.classList.add('unread');
                const badge = document.createElement('div');
                badge.className = 'unread-badge';
                badge.textContent = String(effectiveCount);
                contact.appendChild(badge);
                totalUnread += effectiveCount;
            });

            unreadOverlayState.total = totalUnread;
            updatePageTitle(totalUnread);
            updateUnreadAttentionCue();
            sortContactsList();
        } catch (error) {
            console.error('Unable to refresh unread badges.', error);
        }
    }
    
    function updatePageTitle(unreadCount) {
        const baseTitle = 'QuillTalk';
        
        if (unreadCount > 0) {
            const displayCount = unreadCount > 20 ? '20+' : String(unreadCount);
            document.title = `(${displayCount}) ${baseTitle}`;
        } else {
            document.title = baseTitle;
        }
    }
    
    function formatUnreadDividerTime(ts) {
        const parsedTimestamp = parseServerDateTimeMs(ts);
        if (!parsedTimestamp) {
            return 'unknown time';
        }

        return new Date(parsedTimestamp).toLocaleTimeString([], {
            hour: 'numeric',
            minute: '2-digit'
        });
    }

    function isUnreadDividerCandidateMessage(messageEl) {
        if (!messageEl) {
            return false;
        }

        const messageId = getMessageServerId(messageEl);
        const lastSeen = parseInt(window.chatLastSeen, 10) || 0;
        const isUnread = Number.isFinite(messageId) && messageId > lastSeen;
        const isFromMe = messageEl.classList.contains('self');
        const isCallEvent = messageEl.classList.contains('call-event');
        const isMissedCall = isCallEvent && messageEl.dataset.unreadCallEvent === '1';

        return isUnread && !isFromMe && (!isCallEvent || isMissedCall);
    }

    function resolveUnreadDividerAnchor(messageEl) {
        let anchor = messageEl || null;
        while (anchor && anchor.parentElement !== chatBox) {
            anchor = anchor.parentElement;
        }
        return anchor && anchor.parentElement === chatBox ? anchor : null;
    }

    function getUnreadDividerSenderLabel(messageEl, messageRecord) {
        const senderLabelEl = messageEl
            ? messageEl.querySelector('.group-message-sender, .username')
            : null;
        const senderLabelText = senderLabelEl ? String(senderLabelEl.textContent || '').trim() : '';
        const senderId = String(
            (messageRecord && messageRecord.sender_id)
            || (messageEl && messageEl.dataset ? messageEl.dataset.senderId : '')
            || ''
        ).trim();

        if (messageEl && messageEl.classList.contains('group-news-message')) {
            return 'Group update';
        }

        if (
            messageRecord
            && (
                messageRecord.self === true
                || messageRecord.self === 1
                || messageRecord.self === '1'
                || senderId === String(currentUserId)
            )
        ) {
            return 'You';
        }

        if (messageRecord && messageRecord.sender_display_name) {
            return String(messageRecord.sender_display_name).trim();
        }

        if (senderLabelText) {
            return senderLabelText;
        }

        if (senderId) {
            return getDisplayNameForUser(senderId, {
                displayName: getUsernameById(senderId),
                username: getUsernameById(senderId)
            }, messageRecord ? getMessageChatKey(messageRecord) : String(selectedUser || '')) || 'Someone';
        }

        return 'Someone';
    }

    function getUnreadDividerMessageBody(messageRecord, messageEl) {
        const rawMessage = String((messageRecord && messageRecord.message) || '');
        if (!rawMessage) {
            const textEl = messageEl
                ? messageEl.querySelector('.message-text-content, .text, .group-news-card, .call-event-card')
                : null;
            return String(textEl && textEl.textContent ? textEl.textContent : 'Message').trim() || 'Message';
        }

        const attachment = parseAttachmentMessage(rawMessage);
        if (attachment) {
            if (attachment.kind === 'image') {
                return attachment.caption ? `Photo: ${attachment.caption}` : 'Photo';
            }
            if (attachment.kind === 'video') {
                return attachment.caption ? `Video: ${attachment.caption}` : 'Video';
            }
            if (attachment.kind === 'audio') {
                return attachment.caption ? `Voice message: ${attachment.caption}` : 'Voice message';
            }
            return attachment.name || 'Attachment';
        }

        const tableMessage = parseTableMessage(rawMessage);
        if (tableMessage) {
            return getTableMessageSummary(tableMessage);
        }

        if (parsePollMessage(rawMessage)) {
            return 'Started a poll';
        }

        if (parseGroupCallMessage(rawMessage)) {
            return 'Group call';
        }

        const callEvent = parseCallEventMessage(rawMessage);
        if (callEvent) {
            return getCallEventPreviewText(rawMessage);
        }

        const groupNews = parseGroupNewsMessage(rawMessage);
        if (groupNews) {
            return getGroupNewsSentence(groupNews);
        }

        return getMessageSnippetForReply(rawMessage) || 'Message';
    }

    function getUnreadDividerChatLabel(chatKey) {
        const normalizedChatKey = String(chatKey || '').trim();
        if (!normalizedChatKey) {
            return 'Chat';
        }

        if (isGroupChatKey(normalizedChatKey)) {
            return groupNamesMap[normalizedChatKey] || 'Group Chat';
        }

        return getDisplayNameForUser(normalizedChatKey) || 'Chat';
    }

    function collectUnreadDividerState() {
        if (!chatBox) {
            return null;
        }

        const unreadEntries = [];
        const messageElements = Array.from(chatBox.querySelectorAll('.message'));
        for (const messageEl of messageElements) {
            if (!isUnreadDividerCandidateMessage(messageEl)) {
                continue;
            }

            const messageRecord = messageEl._qtMessageRecord || null;
            const timestamp = String(
                (messageRecord && messageRecord.created_at)
                || (messageEl.dataset && messageEl.dataset.timestamp)
                || ''
            );

            unreadEntries.push({
                messageEl,
                messageId: getMessageServerId(messageEl),
                messageRecord,
                rawMessage: String((messageRecord && messageRecord.message) || ''),
                timestamp,
                senderLabel: getUnreadDividerSenderLabel(messageEl, messageRecord),
                bodyText: normalizeUnreadDividerSummaryText(getUnreadDividerMessageBody(messageRecord, messageEl))
            });
        }

        if (!unreadEntries.length) {
            return null;
        }

        const firstUnread = unreadEntries[0];
        const dividerAnchor = resolveUnreadDividerAnchor(firstUnread.messageEl);
        if (!dividerAnchor) {
            return null;
        }

        const contextLines = unreadEntries.map((entry, index) => {
            const timeLabel = formatUnreadDividerTime(entry.timestamp);
            return `${index + 1}. ${timeLabel} - ${entry.senderLabel}: ${entry.bodyText}`;
        });

        return {
            dividerAnchor,
            unreadEntries,
            unreadCount: unreadEntries.length,
            firstUnreadTimeLabel: formatUnreadDividerTime(firstUnread.timestamp),
            signature: unreadEntries.map(entry => entry.messageId).filter(Boolean).join(':'),
            contextLines
        };
    }

    async function buildUnreadDividerSummaryState(unreadState) {
        if (!unreadState || !Array.isArray(unreadState.unreadEntries) || !unreadState.unreadEntries.length) {
            return null;
        }

        const summaryEntries = await Promise.all(unreadState.unreadEntries.map(entry => {
            return buildSummaryContextEntry({
                messageEl: entry && entry.messageEl ? entry.messageEl : null,
                messageRecord: entry && entry.messageRecord ? entry.messageRecord : null,
                rawMessage: entry && entry.rawMessage ? entry.rawMessage : '',
                senderLabel: entry && entry.senderLabel ? entry.senderLabel : '',
                timestamp: entry && entry.timestamp ? entry.timestamp : ''
            }, {
                maxChars: 680
            });
        }));

        const usableEntries = summaryEntries.filter(entry => entry && entry.bodyText);
        if (!usableEntries.length) {
            return null;
        }

        return {
            ...unreadState,
            voiceMessageCount: usableEntries.filter(entry => entry.wasVoiceMessage).length,
            transcribedVoiceCount: usableEntries.filter(entry => entry.usedVoiceTranscription).length,
            voiceFallbackCount: usableEntries.filter(entry => entry.usedVoiceFallback).length,
            contextLines: usableEntries.map((entry, index) => {
                const timeLabel = formatUnreadDividerTime(entry.timestamp);
                return `${index + 1}. ${timeLabel} - ${entry.senderLabel}: ${entry.bodyText}`;
            })
        };
    }

    function buildUnreadDividerLabel(unreadCount, firstUnreadTimeLabel) {
        const noun = unreadCount === 1 ? 'unread message' : 'unread messages';
        return `(${unreadCount}) ${noun} since ${firstUnreadTimeLabel}`;
    }

    function normalizeUnreadDividerSummaryText(text) {
        const normalized = String(text || '')
            .replace(/\s+/g, ' ')
            .trim();
        if (normalized.length <= 220) {
            return normalized;
        }
        return normalized.slice(0, 217) + '...';
    }

    function createUnreadDividerLoadingNode() {
        const loadingWrap = document.createElement('div');
        loadingWrap.className = 'transcribe-loading-container';
        for (let index = 0; index < 5; index += 1) {
            const line = document.createElement('div');
            line.className = 'transcribe-loading-line';
            loadingWrap.appendChild(line);
        }
        return loadingWrap;
    }

    function setUnreadDividerBodyState(divider, mode, text = '') {
        if (!divider) {
            return;
        }

        divider.classList.remove('is-loading', 'is-summarized', 'has-error');
        const body = divider.querySelector('.unread-divider-body');
        if (!body) {
            return;
        }

        stopSummarySpeechPlaybackIfWithin(body);
        body.innerHTML = '';
        if (mode === 'loading') {
            divider.classList.add('is-loading');
            body.appendChild(createUnreadDividerLoadingNode());
            return;
        }

        if (mode === 'summary') {
            divider.classList.add('is-summarized');
            renderSummarySpeechContent(body, text, {
                textClassName: 'unread-divider-summary-text',
                idleLabel: 'Read unread summary aloud',
                activeLabel: 'Stop reading unread summary aloud'
            });
            return;
        }

        if (mode === 'error') {
            divider.classList.add('has-error');
            const errorText = document.createElement('p');
            errorText.className = 'unread-divider-error-text';
            errorText.textContent = text;
            body.appendChild(errorText);
        }
    }

    async function summarizeUnreadDivider(divider, unreadState) {
        const normalizedChatKey = String(selectedUser || '').trim();
        if (!divider || !divider.isConnected || !normalizedChatKey || !unreadState || !unreadState.unreadEntries || !unreadState.unreadEntries.length) {
            return;
        }

        const summaryButton = divider.querySelector('.unread-divider-summary-btn');
        if (summaryButton && summaryButton.disabled) {
            return;
        }

        if (summaryButton) {
            summaryButton.disabled = true;
            summaryButton.setAttribute('aria-busy', 'true');
        }

        setUnreadDividerBodyState(divider, 'loading');

        try {
            const summaryState = await buildUnreadDividerSummaryState(unreadState);
            if (!summaryState || !summaryState.contextLines.length) {
                throw new Error('No unread messages could be summarized.');
            }

            const summaryText = await requestContextOnlyAiSummary({
                prompt: `There are ${summaryState.unreadCount} unread messages starting at ${summaryState.firstUnreadTimeLabel}. Summarize only that unread message batch from the supplemental local-only context. Treat any line labeled "Voice message transcription" as the full content of that voice message. The only allowed evidence is the supplemental local-only context, so do not use any earlier conversation history or outside details. Keep it concise and stylish in 2 to 4 short sentences. Focus on what happened, open questions, requests, and anything urgent. Do not mention that you are summarizing unread messages.`,
                chatKey: normalizedChatKey,
                chatLabel: getUnreadDividerChatLabel(normalizedChatKey),
                contextLines: summaryState.contextLines
            });

            if (
                !divider.isConnected
                || String(selectedUser || '').trim() !== normalizedChatKey
                || String(divider.dataset.unreadSignature || '') !== String(unreadState.signature || '')
            ) {
                return;
            }

            setUnreadDividerBodyState(divider, 'summary', summaryText);
        } catch (error) {
            if (
                divider.isConnected
                && String(selectedUser || '').trim() === normalizedChatKey
                && String(divider.dataset.unreadSignature || '') === String(unreadState.signature || '')
            ) {
                setUnreadDividerBodyState(
                    divider,
                    'error',
                    'Could not summarize those unread messages right now. Try the star again in a moment.'
                );
            }
        } finally {
            if (summaryButton) {
                summaryButton.disabled = false;
                summaryButton.setAttribute('aria-busy', 'false');
            }
        }
    }

    function placeUnreadDivider() {
        if (!chatBox) {
            return;
        }

        if ((selectedUser && String(selectedUser).startsWith('ai:')) || isChessConversationDockMounted()) {
            const oldAiDivider = chatBox.querySelector('.unread-divider');
            if (oldAiDivider) {
                stopSummarySpeechPlaybackIfWithin(oldAiDivider);
                oldAiDivider.remove();
            }
            return;
        }

        const oldDivider = chatBox.querySelector('.unread-divider');
        if (oldDivider) {
            stopSummarySpeechPlaybackIfWithin(oldDivider);
            oldDivider.remove();
        }

        if (window.chatLastSeen === undefined || window.chatLastSeen === null) {
            return;
        }

        const unreadState = collectUnreadDividerState();
        if (!unreadState) {
            chatBox.scrollTop = chatBox.scrollHeight;
            return;
        }

        const divider = document.createElement('div');
        divider.className = 'unread-divider';
        divider.dataset.unreadSignature = unreadState.signature;

        const shell = document.createElement('div');
        shell.className = 'unread-divider-shell';

        const header = document.createElement('div');
        header.className = 'unread-divider-header';

        const label = document.createElement('div');
        label.className = 'unread-divider-label';
        label.textContent = buildUnreadDividerLabel(unreadState.unreadCount, unreadState.firstUnreadTimeLabel);

        const summaryButton = document.createElement('button');
        summaryButton.type = 'button';
        summaryButton.className = 'unread-divider-summary-btn';
        summaryButton.textContent = '✦';
        summaryButton.setAttribute('aria-label', 'Summarize unread messages');
        summaryButton.setAttribute('title', 'Summarize unread messages');
        summaryButton.addEventListener('click', () => {
            summarizeUnreadDivider(divider, unreadState).catch(() => {});
        });

        const body = document.createElement('div');
        body.className = 'unread-divider-body';

        header.appendChild(label);
        header.appendChild(summaryButton);
        shell.appendChild(header);
        shell.appendChild(body);
        divider.appendChild(shell);

        chatBox.insertBefore(divider, unreadState.dividerAnchor);

        // Don't add individual animations during initial load - the centralized system will handle it
        // Individual animations are only for when dividers are added after initial load
        if (!isInitialConversationLoad) {
            // Add animation for dynamically added unread dividers (not during initial load)
            divider.style.animation = 'slideInFromLeft 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        window.setTimeout(() => {
            divider.scrollIntoView({ block: 'center', behavior: 'smooth' });
        }, 50);
    }

    initializeAppStartup();

    window.updateHeaderContact = updateHeaderContact;
    window.hideEmojiPicker = hideEmojiPicker;
    window.clearPendingAttachment = clearPendingAttachment;
    window.clearComposerAfterSend = clearComposerAfterSend;
    window.invalidateSidebarHistoryCache = invalidateSidebarHistoryCache;
    window.parseComposerAiCommand = parseComposerAiCommand;
    window.pollMessages = pollMessages;
    window.bindMobileMessageGestures = bindMobileMessageGestures;
    window.getPendingTableDraft = getPendingTableDraftSnapshot;
    window.queuePendingGifAttachments = queuePendingGifAttachments;
    window.queuePendingTableDraft = queuePendingTableDraft;
    window.hideContactInfoPanel = hideContactInfoPanel;
    window.closeRightSidebar = closeRightSidebar;
    window.closeVoiceActionMenu = closeVoiceActionMenu;
    window.openChatActionModal = openChatActionModal;
    window.normalizeProfilePic = normalizeProfilePic;
    window.isGroupChatKey = isGroupChatKey;
    window.getContactMeta = getContactMeta;
    window.getDisplayNameForUser = getDisplayNameForUser;
    window.__QT_GET_SELECTED_CHAT_KEY = function getSelectedChatKeyGlobal() {
        return String(selectedUser || '');
    };
    window.__QT_CURRENT_USER_ID = currentUserId;
    window.__QT_DEFAULT_PROFILE_PIC = defaultProfilePic;
    window.restoreMobileContactsView = function restoreMobileContactsViewGlobal(options) {
        console.log('DEBUG: restoreMobileContactsViewGlobal invoked', options);
        const chatContainer = document.querySelector('.chat-container');
        const sidebarEl = document.getElementById('sidebar');
        const backBtnEl = document.getElementById('mobileBackBtn');
        if (chatContainer) {
            chatContainer.style.display = chatContainer.classList.contains('is-docked-in-chess-modal') ? 'flex' : 'none';
        }
        if (sidebarEl) {
            sidebarEl.style.display = 'flex';
        }
        if (backBtnEl) {
            backBtnEl.style.display = 'none';
        }
        try {
            restoreMobileContactsView(options || {});
            console.log('DEBUG: restoreMobileContactsViewGlobal finished');
        } catch (err) {
            console.error('DEBUG: restoreMobileContactsViewLocal threw inside global wrapper', err);
        }
    };
})();

