function normalizeGifFavoriteItemRecord(item) {
    if (!item || !item.sendUrl || !item.previewUrl) {
        return null;
    }

    const key = String(item.id || item.sendUrl || item.previewUrl || '').trim();
    if (!key) {
        return null;
    }

    return {
        id: key,
        title: String(item.title || 'GIF'),
        previewUrl: String(item.previewUrl),
        sendUrl: String(item.sendUrl),
        fileName: String(item.fileName || buildGifFileName(item.title || 'GIF')),
        useCount: Math.max(1, Number(item.useCount || item.count || 1) || 1),
        lastUsed: Math.max(0, Number(item.lastUsed || Date.now()) || Date.now())
    };
}

function loadGifFavoriteItems() {
    try {
        const stored = localStorage.getItem(GIF_FAVORITES_STORAGE_KEY);
        const parsed = stored ? JSON.parse(stored) : [];
        gifFavoriteItems = Array.isArray(parsed)
            ? parsed.map(normalizeGifFavoriteItemRecord).filter(Boolean)
            : [];
    } catch (error) {
        gifFavoriteItems = [];
    }
}

function persistGifFavoriteItems() {
    try {
        localStorage.setItem(GIF_FAVORITES_STORAGE_KEY, JSON.stringify(gifFavoriteItems));
    } catch (error) {
        console.error('Failed to save GIF favorites:', error);
    }
}

function recordGifUsage(items) {
    const normalizedItems = Array.isArray(items)
        ? items.map(normalizeGifFavoriteItemRecord).filter(Boolean)
        : [];
    if (!normalizedItems.length) {
        return;
    }

    const usageMap = new Map(gifFavoriteItems.map(item => [getGifSelectionKey(item), item]));
    normalizedItems.forEach(item => {
        const key = getGifSelectionKey(item);
        const existing = usageMap.get(key);
        if (existing) {
            existing.title = item.title;
            existing.previewUrl = item.previewUrl;
            existing.sendUrl = item.sendUrl;
            existing.fileName = item.fileName;
            existing.useCount = Math.max(1, Number(existing.useCount || 0)) + 1;
            existing.lastUsed = Date.now();
            return;
        }

        usageMap.set(key, {
            ...item,
            useCount: 1,
            lastUsed: Date.now()
        });
    });

    gifFavoriteItems = Array.from(usageMap.values())
        .map(normalizeGifFavoriteItemRecord)
        .filter(Boolean)
        .sort((a, b) => b.lastUsed - a.lastUsed || b.useCount - a.useCount)
        .slice(0, 40);
    persistGifFavoriteItems();
}

function getGifModalCategory(categoryKey) {
    return GIF_MODAL_CATEGORIES.find(category => category.key === categoryKey) || null;
}

function getFavoriteGifItems(query = '') {
    const normalizedQuery = String(query || '').trim().toLowerCase();
    const items = gifFavoriteItems
        .slice()
        .sort((a, b) => b.lastUsed - a.lastUsed || b.useCount - a.useCount);

    if (!normalizedQuery) {
        return items;
    }

    return items.filter(item => {
        const title = String(item.title || '').toLowerCase();
        const fileName = String(item.fileName || '').toLowerCase();
        return title.includes(normalizedQuery) || fileName.includes(normalizedQuery);
    });
}

loadGifFavoriteItems();

function getTopOpenOverlayZIndex() {
    let highestZIndex = 12000;
    document.querySelectorAll('.friend-request-modal, .chat-action-modal').forEach(overlay => {
        const computedStyle = window.getComputedStyle(overlay);
        const isOpen = overlay.classList.contains('open')
            || overlay.getAttribute('aria-hidden') === 'false'
            || computedStyle.display !== 'none';
        if (!isOpen) {
            return;
        }

        const inlineZIndex = parseInt(String(overlay.style.zIndex || ''), 10);
        const computedZIndex = parseInt(String(computedStyle.zIndex || ''), 10);
        if (Number.isFinite(inlineZIndex)) {
            highestZIndex = Math.max(highestZIndex, inlineZIndex);
        }
        if (Number.isFinite(computedZIndex)) {
            highestZIndex = Math.max(highestZIndex, computedZIndex);
        }
    });
    return highestZIndex;
}

function getVisibleElementZIndex(element) {
    if (!element) {
        return null;
    }

    const computedStyle = window.getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    const isVisible = computedStyle.display !== 'none'
        && computedStyle.visibility !== 'hidden'
        && rect.width > 0
        && rect.height > 0;
    if (!isVisible) {
        return null;
    }

    const inlineZIndex = parseInt(String(element.style.zIndex || ''), 10);
    const computedZIndex = parseInt(String(computedStyle.zIndex || ''), 10);
    return Math.max(
        Number.isFinite(inlineZIndex) ? inlineZIndex : 0,
        Number.isFinite(computedZIndex) ? computedZIndex : 0
    );
}

function getTopUiLayerZIndex() {
    let highestZIndex = getTopOpenOverlayZIndex();
    [document.getElementById('call-ui'), document.getElementById('in-call-controls')].forEach(element => {
        const zIndex = getVisibleElementZIndex(element);
        if (Number.isFinite(zIndex)) {
            highestZIndex = Math.max(highestZIndex, zIndex);
        }
    });
    return highestZIndex;
}

function getToastBottomOffset() {
    let bottomOffset = 20;
    const callControls = document.getElementById('in-call-controls');
    const controlsZIndex = getVisibleElementZIndex(callControls);
    if (Number.isFinite(controlsZIndex) && callControls) {
        const rect = callControls.getBoundingClientRect();
        if (rect.height > 0) {
            bottomOffset = Math.max(bottomOffset, Math.ceil(window.innerHeight - rect.top + 20));
        }
    }
    return bottomOffset;
}

function bringOverlayToFront(overlay, step = 10) {
    if (!overlay) {
        return getTopOpenOverlayZIndex();
    }

    const nextZIndex = getTopOpenOverlayZIndex() + Math.max(1, Number(step) || 1);
    overlay.style.zIndex = String(nextZIndex);
    return nextZIndex;
}

function resetOverlayZIndex(overlay) {
    if (overlay) {
        overlay.style.zIndex = '';
    }
}

// Toast notification helper
function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    const toastZIndex = getTopUiLayerZIndex() + 20;
    const bottomOffset = getToastBottomOffset();
    toast.style.cssText = `
        position: fixed;
        bottom: ${bottomOffset}px;
        left: 50%;
        transform: translateX(-50%);
        padding: 12px 24px;
        background: ${type === 'error' ? '#dc2626' : type === 'success' ? '#16a34a' : '#2d58f5'};
        color: white;
        border-radius: 8px;
        font-size: 0.92rem;
        font-weight: 500;
        box-shadow: 0 10px 25px rgba(0,0,0,0.2);
        z-index: ${toastZIndex};
        animation: slideUp 0.3s ease;
    `;
    toast.textContent = message;
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.style.animation = 'slideDown 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

