function getSidequestType(gameData = activeChessGameData) {
    return String(gameData && gameData.game && gameData.game.type || '').trim().toLowerCase();
}

function isChessSidequest(gameData = activeChessGameData) {
    return getSidequestType(gameData) === SIDEQUEST_GAME_CHESS;
}

function isCheckersSidequest(gameData = activeChessGameData) {
    return getSidequestType(gameData) === SIDEQUEST_GAME_CHECKERS;
}

function isConnectFourSidequest(gameData = activeChessGameData) {
    return getSidequestType(gameData) === SIDEQUEST_GAME_CONNECT_FOUR;
}

function isSketchoffSidequest(gameData = activeChessGameData) {
    return getSidequestType(gameData) === SIDEQUEST_GAME_SKETCHOFF;
}

function getSidequestLabel(gameData = activeChessGameData) {
    const label = String(gameData && gameData.game && gameData.game.label || '').trim();
    if (label) {
        return label;
    }
    if (isCheckersSidequest(gameData)) {
        return 'Checkers';
    }
    if (isConnectFourSidequest(gameData)) {
        return 'Connect Four';
    }
    if (isSketchoffSidequest(gameData)) {
        return 'Sketchoff';
    }
    return 'Chess';
}

function getSidequestEngine(gameData = activeChessGameData) {
    if (isCheckersSidequest(gameData)) {
        return window.QuillTalkCheckers;
    }
    if (isConnectFourSidequest(gameData)) {
        return window.QuillTalkConnectFour;
    }
    if (isSketchoffSidequest(gameData)) {
        return window.QuillTalkSketchoff;
    }
    return window.QuillTalkChess;
}

function getNormalizedSidequestState(gameData = activeChessGameData) {
    if (!gameData || typeof gameData !== 'object' || !Object.prototype.hasOwnProperty.call(gameData, 'state')) {
        return null;
    }
    const engine = getSidequestEngine(gameData);
    if (!engine || typeof engine.normalizeState !== 'function') {
        return null;
    }
    return engine.normalizeState(gameData.state);
}

function getSidequestIconMarkup(gameData = activeChessGameData) {
    if (isCheckersSidequest(gameData)) {
        return '<i class="fa-solid fa-circle-dot" aria-hidden="true"></i>';
    }
    if (isConnectFourSidequest(gameData)) {
        return '<i class="fa-solid fa-table-cells-large" aria-hidden="true"></i>';
    }
    if (isSketchoffSidequest(gameData)) {
        return '<i class="fa-solid fa-pencil" aria-hidden="true"></i>';
    }
    return '<i class="fa-solid fa-chess-knight" aria-hidden="true"></i>';
}

function getChessSelectedChatKey() {
    if (typeof window.__QT_GET_SELECTED_CHAT_KEY === 'function') {
        return String(window.__QT_GET_SELECTED_CHAT_KEY() || '').trim();
