function normalizeSidequestBotAiInstructions(text) {
    return String(text || '')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .trim();
}

function normalizeSidequestBotAiChatMeta(value) {
    if (!value || typeof value !== 'object') {
        return null;
    }

    const gameId = Math.max(0, Number(value.gameId || value.game_id || 0) || 0);
    const gameType = String(value.gameType || value.game_type || '').trim().toLowerCase();
    if (!gameId || ![SIDEQUEST_GAME_CHESS, SIDEQUEST_GAME_CHECKERS, SIDEQUEST_GAME_CONNECT_FOUR].includes(gameType)) {
        return null;
    }

    const botColor = value.botColor === 'b' || value.botColor === 'w'
        ? value.botColor
        : (value.bot_color === 'b' || value.bot_color === 'w' ? value.bot_color : null);

    return {
        kind: 'sidequest_bot',
        version: 1,
        gameId,
        gameType,
        botColor,
        lastFinalSignature: String(value.lastFinalSignature || value.last_final_signature || '').trim(),
        temporary: true
    };
}

function isTemporarySidequestBotAiMeta(meta) {
    return !!(meta && meta.kind === 'sidequest_bot' && meta.temporary !== false);
}

function isTemporaryAiChatKey(chatKey) {
    return isTemporarySidequestBotAiMeta(getSidequestBotAiChatMeta(chatKey));
}

function removeAiChatContact(chatKey) {
    const contactEl = getContactElement(chatKey);
    if (!contactEl) {
        return;
    }
    if (selectedUser && String(selectedUser) === String(chatKey)) {
        contactEl.classList.remove('active');
    }
    contactEl.remove();
}

function parseSidequestBotAiChatNotes(notes) {
    const normalizedNotes = normalizeSidequestBotAiInstructions(notes);
    if (!normalizedNotes) {
        return {
            meta: null,
            instructions: ''
        };
    }

    const firstNewlineIndex = normalizedNotes.indexOf('\n');
    const firstLine = firstNewlineIndex === -1
        ? normalizedNotes
        : normalizedNotes.slice(0, firstNewlineIndex);
    const remaining = firstNewlineIndex === -1
        ? ''
        : normalizeSidequestBotAiInstructions(normalizedNotes.slice(firstNewlineIndex + 1));

    if (!firstLine.startsWith(SIDEQUEST_BOT_AI_CHAT_NOTES_PREFIX)) {
        return {
            meta: null,
            instructions: normalizedNotes
        };
    }

    let decodedMeta = null;
    try {
        decodedMeta = JSON.parse(firstLine.slice(SIDEQUEST_BOT_AI_CHAT_NOTES_PREFIX.length));
    } catch (error) {
        decodedMeta = null;
    }

    return {
        meta: normalizeSidequestBotAiChatMeta(decodedMeta),
        instructions: remaining
    };
}

function buildSidequestBotAiChatNotes(meta, instructions = '') {
    const normalizedMeta = normalizeSidequestBotAiChatMeta(meta);
    const normalizedInstructions = normalizeSidequestBotAiInstructions(instructions);
    if (!normalizedMeta) {
        return normalizedInstructions;
    }

    const lines = [
        `${SIDEQUEST_BOT_AI_CHAT_NOTES_PREFIX}${JSON.stringify(normalizedMeta)}`
    ];
    if (normalizedInstructions) {
        lines.push('', normalizedInstructions);
    }
    return lines.join('\n');
}

function getAiChatRecord(chatKey) {
    const normalizedChatKey = String(chatKey || '').trim();
    if (!normalizedChatKey || !window.aiChatsMap || typeof window.aiChatsMap !== 'object') {
        return null;
    }
    const aiData = window.aiChatsMap[normalizedChatKey];
    return aiData && typeof aiData === 'object' ? aiData : null;
}

function cacheAiChatRecord(chatKey, aiData) {
    const normalizedChatKey = String(chatKey || '').trim();
    if (!normalizedChatKey || !aiData || typeof aiData !== 'object') {
        return null;
    }

    if (!window.aiChatsMap || typeof window.aiChatsMap !== 'object') {
        window.aiChatsMap = {};
    }

    const existing = getAiChatRecord(normalizedChatKey) || {};
    const nextRecord = {
        ...existing,
        ...aiData,
        id: Math.max(0, Number(aiData.id || existing.id || 0) || 0),
        displayName: String(aiData.displayName !== undefined ? aiData.displayName : (existing.displayName || 'QuillTalk AI')).trim() || 'QuillTalk AI',
        bio: String(aiData.bio !== undefined ? aiData.bio : (existing.bio || '')).trim(),
        notes: typeof aiData.notes === 'string' ? aiData.notes : String(existing.notes || ''),
        profilePic: String(aiData.profilePic !== undefined ? aiData.profilePic : (existing.profilePic || DEFAULT_AI_PROFILE_PIC)).trim() || DEFAULT_AI_PROFILE_PIC
    };

    window.aiChatsMap[normalizedChatKey] = nextRecord;
    return nextRecord;
}

function syncAiChatContact(chatKey) {
    const normalizedChatKey = String(chatKey || '').trim();
    const aiData = getAiChatRecord(normalizedChatKey);
    if (!normalizedChatKey || !aiData || typeof addContact !== 'function') {
        return;
    }

    if (isTemporaryAiChatKey(normalizedChatKey)) {
        removeAiChatContact(normalizedChatKey);
        return;
    }

    addContact(
        normalizedChatKey,
        aiData.displayName || 'QuillTalk AI',
        '',
        aiData.profilePic || DEFAULT_AI_PROFILE_PIC,
        0,
        aiData.bio || ''
    );
}

function buildSidequestBotAiChatDisplayName(gameData) {
    const label = getSidequestLabel(gameData);
    return `QuillTalk ${label} Bot`;
}

function buildSidequestBotAiChatBio(gameData) {
    const label = getSidequestLabel(gameData);
    return `Private bot chat for your ${label.toLowerCase()} sidequest.`;
}

function buildSidequestBotAiDefaultInstructions(gameData) {
    const label = getSidequestLabel(gameData);
    return [
        `You are the QuillTalk ${label} Bot for this one private Sidequest match.`,
        'Use the supplemental local-only context as the source of truth for the live board, move history, current turn, and final result.',
        'When the user asks about moves, answer directly and mention which side played them when useful.',
        'Keep replies brief, friendly, and lightly competitive without being rude.',
        'If the game is over, stay sportsmanlike.'
    ].join(' ');
}

function getSidequestBotAiChatMeta(chatKey) {
    const aiData = getAiChatRecord(chatKey);
    if (!aiData) {
        return null;
    }
    return parseSidequestBotAiChatNotes(aiData.notes || '').meta;
}

function getSidequestStateSignature(state) {
    if (!state || typeof state !== 'object') {
        return '';
    }

    return JSON.stringify({
        board: Array.isArray(state.board) ? state.board : [],
        turn: state.turn === 'b' ? 'b' : 'w',
        lastMove: state.lastMove || null,
        winnerColor: state.winnerColor || null,
        resultCode: state.resultCode || null,
        resultLabel: state.resultLabel || null,
        moveCount: Number(state.moveCount || 0) || 0,
        fullmoveNumber: Number(state.fullmoveNumber || 0) || 0,
        halfmoveClock: Number(state.halfmoveClock || 0) || 0
    });
}

function buildSidequestBotFinalDeliveryKey(gameData, finalSignature = '') {
    const gameId = Math.max(0, Number(gameData && gameData.game && gameData.game.id || 0) || 0);
    const normalizedFinalSignature = String(finalSignature || '').trim();
    if (!gameId || !normalizedFinalSignature) {
        return '';
    }
    return `${gameId}:${normalizedFinalSignature}`;
}

function loadStoredSidequestBotFinalDeliveries() {
    try {
        const raw = window.localStorage ? window.localStorage.getItem(SIDEQUEST_BOT_FINAL_DELIVERY_STORAGE_KEY) : '';
        if (!raw) {
            return {};
        }
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === 'object' ? parsed : {};
    } catch (error) {
        return {};
    }
}

function hasStoredSidequestBotFinalDelivery(deliveryKey) {
    const normalizedDeliveryKey = String(deliveryKey || '').trim();
    if (!normalizedDeliveryKey) {
        return false;
    }
    const deliveries = loadStoredSidequestBotFinalDeliveries();
    return !!deliveries[normalizedDeliveryKey];
}

function rememberStoredSidequestBotFinalDelivery(deliveryKey) {
    const normalizedDeliveryKey = String(deliveryKey || '').trim();
    if (!normalizedDeliveryKey || !window.localStorage) {
        return;
    }

    const deliveries = loadStoredSidequestBotFinalDeliveries();
    deliveries[normalizedDeliveryKey] = Date.now();

    const trimmedEntries = Object.entries(deliveries)
        .sort((left, right) => Number(right[1] || 0) - Number(left[1] || 0))
        .slice(0, 200);

    try {
        window.localStorage.setItem(
            SIDEQUEST_BOT_FINAL_DELIVERY_STORAGE_KEY,
            JSON.stringify(Object.fromEntries(trimmedEntries))
        );
    } catch (error) {}
}

function rememberSidequestBotFinalSignatureLocally(chatKey, gameData, finalSignature) {
    const normalizedChatKey = String(chatKey || '').trim();
    const normalizedFinalSignature = String(finalSignature || '').trim();
    const aiData = getAiChatRecord(normalizedChatKey);
    if (!normalizedChatKey || !normalizedFinalSignature || !aiData) {
        return;
    }

    const parsed = parseSidequestBotAiChatNotes(aiData.notes || '');
    const fallbackMeta = normalizeSidequestBotAiChatMeta({
        gameId: gameData && gameData.game ? gameData.game.id : 0,
        gameType: getSidequestType(gameData),
        botColor: getSidequestBotColor(gameData)
    });
    const nextMeta = normalizeSidequestBotAiChatMeta({
        ...(parsed.meta || fallbackMeta || {}),
        lastFinalSignature: normalizedFinalSignature
    });
    if (!nextMeta) {
        return;
    }

    const nextNotes = buildSidequestBotAiChatNotes(
        nextMeta,
        parsed.instructions || buildSidequestBotAiDefaultInstructions(gameData)
    );
    cacheAiChatRecord(normalizedChatKey, {
        id: aiData.id,
        displayName: aiData.displayName,
        bio: aiData.bio,
        notes: nextNotes,
        profilePic: aiData.profilePic || DEFAULT_AI_PROFILE_PIC
    });
}

function resolveSidequestHostChatKey(gameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    const viewer = gameData && gameData.viewer ? gameData.viewer : {};
    const groupId = Math.max(0, Number(game.group_id || 0) || 0);
    if (groupId > 0) {
        return `group:${groupId}`;
    }

    const viewerUserId = Math.max(0, Number(viewer.user_id || 0) || 0);
    const creatorUserId = Math.max(0, Number(game.creator_user_id || 0) || 0);
    const recipientId = Math.max(0, Number(game.recipient_id || 0) || 0);

    if (recipientId > 0) {
        if (viewerUserId > 0 && recipientId === viewerUserId && creatorUserId > 0) {
            return String(creatorUserId);
        }
        return String(recipientId);
    }
    if (creatorUserId > 0 && creatorUserId !== viewerUserId) {
        return String(creatorUserId);
    }

    return '';
}

function isChessConversationDockMounted() {
    const chatContainer = getChessConversationContainer();
    return !!(chatContainer && chatContainer.classList.contains('is-docked-in-chess-modal'));
}

function getSidequestBotColor(gameData) {
    const botColor = String(gameData && gameData.game && gameData.game.bot_color || '').trim().toLowerCase();
    return botColor === 'b' ? 'b' : (botColor === 'w' ? 'w' : null);
}

function getSidequestColorLabel(color) {
    return color === 'b' ? 'Black' : 'White';
}

function getSidequestSeatUserId(gameData, seatColor) {
    const seat = getSidequestSeatCard(gameData, seatColor);
    return Math.max(0, Number(seat && seat.user_id || 0) || 0);
}

function getSidequestSeatDisplayName(gameData, seatColor, options = {}) {
    const normalizedOptions = options && typeof options === 'object' ? options : {};
    const preferYou = normalizedOptions.preferYou !== false;
    const fallbackToColor = normalizedOptions.fallbackToColor !== false;
    const seat = getSidequestSeatCard(gameData, seatColor);
    const seatUserId = getSidequestSeatUserId(gameData, seatColor);
    const seatName = seat && seat.display_name ? String(seat.display_name) : '';
    if (preferYou && seatUserId > 0 && String(seatUserId) === String(currentUserId)) {
        return 'You';
    }
    if (seatName) {
        return seatName;
    }
    return fallbackToColor ? getSidequestColorLabel(seatColor) : '';
}

function getLocalizedSidequestStarterName(gameData, fallbackName = 'Someone') {
    const creatorUserId = Math.max(0, Number(gameData && gameData.game && gameData.game.creator_user_id || 0) || 0);
    if (creatorUserId > 0 && String(creatorUserId) === String(currentUserId)) {
        return 'You';
    }
    const normalizedFallbackName = String(fallbackName || '').trim();
    return normalizedFallbackName || 'Someone';
}

function getLocalizedSidequestResultSummary(gameData, fallbackLabel = '') {
    const fallbackSummary = String(
        fallbackLabel
        || (gameData && gameData.game && (gameData.game.result_summary_label || gameData.game.result_label) || '')
    ).trim();
    const state = getNormalizedSidequestState(gameData);
    const winnerColor = state && (state.winnerColor === 'w' || state.winnerColor === 'b')
        ? state.winnerColor
        : '';
    if (!winnerColor) {
        return fallbackSummary || 'Draw';
    }

    const winnerName = getSidequestSeatDisplayName(gameData, winnerColor, {
        preferYou: true,
        fallbackToColor: !isSketchoffSidequest(gameData)
    });
    if (isSketchoffSidequest(gameData)) {
        return winnerName ? `Best match: ${winnerName}` : (fallbackSummary || 'Best match decided');
    }

    const colorLabel = getSidequestColorLabel(winnerColor);
    return winnerName ? `${colorLabel} wins (${winnerName})` : `${colorLabel} wins`;
}

function getLocalizedSidequestResultDetail(gameData, fallbackLabel = '') {
    const fallbackDetail = String(
        fallbackLabel
        || (gameData && gameData.game && (gameData.game.result_reason_label || gameData.game.result_label) || '')
    ).trim();
    if (!fallbackDetail) {
        return '';
    }
    if (!isSketchoffSidequest(gameData)) {
        return fallbackDetail;
    }

    const whiteName = getSidequestSeatDisplayName(gameData, 'w', {
        preferYou: true,
        fallbackToColor: false
    }) || 'Player 1';
    const blackName = getSidequestSeatDisplayName(gameData, 'b', {
        preferYou: true,
        fallbackToColor: false
    }) || 'Player 2';
    const scoreMatch = fallbackDetail.match(/^White\s+(\d{1,3})%\s+vs\s+Black\s+(\d{1,3})%$/i);
    if (scoreMatch) {
        return `${whiteName} ${scoreMatch[1]}% · ${blackName} ${scoreMatch[2]}%`;
    }

    return fallbackDetail
        .replace(/\bWhite\b/g, '__QT_SIDEQUEST_WHITE__')
        .replace(/\bBlack\b/g, '__QT_SIDEQUEST_BLACK__')
        .replace(/__QT_SIDEQUEST_WHITE__/g, whiteName)
        .replace(/__QT_SIDEQUEST_BLACK__/g, blackName);
}

function getSidequestOpponentColor(color) {
    return color === 'b' ? 'w' : 'b';
}

function getSidequestSeatCard(gameData, seatColor) {
    const players = gameData && gameData.players ? gameData.players : {};
    return seatColor === 'b' ? players.black : players.white;
}

function getSidequestSeatName(gameData, seatColor) {
    const seat = getSidequestSeatCard(gameData, seatColor);
    if (seat && seat.display_name) {
        return String(seat.display_name);
    }
    return seatColor === 'b' ? 'Black' : 'White';
}

function resolveSidequestMoveActorName(gameData, move) {
    const normalizedMove = move && typeof move === 'object' ? move : {};
    const moveUserId = Math.max(0, Number(normalizedMove.user_id || 0) || 0);
    const botColor = getSidequestBotColor(gameData);
    const whiteSeat = getSidequestSeatCard(gameData, 'w');
    const blackSeat = getSidequestSeatCard(gameData, 'b');
    const whiteUserId = Math.max(0, Number(whiteSeat && whiteSeat.user_id || 0) || 0);
    const blackUserId = Math.max(0, Number(blackSeat && blackSeat.user_id || 0) || 0);

    if (moveUserId > 0) {
        if (moveUserId === whiteUserId) {
            return `${getSidequestSeatName(gameData, 'w')} (White)`;
        }
        if (moveUserId === blackUserId) {
            return `${getSidequestSeatName(gameData, 'b')} (Black)`;
        }
    }

    if (moveUserId === 0 && botColor) {
        return `${getSidequestSeatName(gameData, botColor)} (${getSidequestColorLabel(botColor)})`;
    }

    const plyNumber = Math.max(1, Number(normalizedMove.ply_number || 1) || 1);
    const inferredColor = plyNumber % 2 === 0 ? 'b' : 'w';
    return `${getSidequestSeatName(gameData, inferredColor)} (${getSidequestColorLabel(inferredColor)})`;
}

function buildSidequestBoardContextLines(gameData) {
    const state = getNormalizedSidequestState(gameData);
    if (!state || !Array.isArray(state.board)) {
        return [];
    }

    const engine = getSidequestEngine(gameData);
    const boardDimensions = engine && typeof engine.getBoardDimensions === 'function'
        ? engine.getBoardDimensions()
        : { rows: Array.isArray(state.board) ? state.board.length : 8, cols: Array.isArray(state.board[0]) ? state.board[0].length : 8 };
    const rowCount = Math.max(1, Number(boardDimensions && boardDimensions.rows ? boardDimensions.rows : state.board.length) || state.board.length || 8);
    const colCount = Math.max(1, Number(boardDimensions && boardDimensions.cols ? boardDimensions.cols : (Array.isArray(state.board[0]) ? state.board[0].length : 8)) || 8);
    const fileLabels = Array.from({ length: colCount }, (_, index) => String.fromCharCode(97 + index)).join('  ');
    const lines = ['Board snapshot:'];
    state.board.slice(0, rowCount).forEach((row, rowIndex) => {
        const cells = Array.isArray(row) ? row : [];
        lines.push(`${rowCount - rowIndex} ${cells.slice(0, colCount).map(cell => cell || '__').join(' ')}`);
    });
    lines.push(`  ${fileLabels}`);
    return lines;
}

function buildSidequestRecentMoveContextLines(gameData, maxMoves = 18) {
    const moves = Array.isArray(gameData && gameData.moves) ? gameData.moves : [];
    if (!moves.length) {
        return ['Moves so far: none yet.'];
    }

    const lines = ['Recent moves:'];
    moves.slice(-1 * Math.max(1, maxMoves)).forEach(move => {
        const plyNumber = Math.max(1, Number(move && move.ply_number || 0) || 1);
        const moveLabel = String(move && (move.notation || move.uci) || '').trim() || 'unknown move';
        lines.push(`Ply ${plyNumber}: ${resolveSidequestMoveActorName(gameData, move)} played ${moveLabel}.`);
    });
    return lines;
}

function buildSidequestBotAiContextLines(gameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    const state = getNormalizedSidequestState(gameData);
    const label = getSidequestLabel(gameData);
    const botColor = getSidequestBotColor(gameData);
    const humanColor = botColor ? getSidequestOpponentColor(botColor) : null;
    const botName = buildSidequestBotAiChatDisplayName(gameData);
    const humanName = humanColor ? getSidequestSeatName(gameData, humanColor) : 'The human player';
    const viewerColor = getChessViewerColor(gameData);
    const viewerName = viewerColor ? getSidequestSeatName(gameData, viewerColor) : (currentUserDisplayName || 'The user');
    const status = String(game.status || '').trim() || 'waiting';
    const currentTurnColor = state && state.turn === 'b' ? 'b' : 'w';
    const currentTurnName = getSidequestSeatName(gameData, currentTurnColor);
    const lines = [
        `This private AI chat is linked to Sidequest ${label} game #${Math.max(0, Number(game.id || 0) || 0)}.`,
        `You are ${botName}, the bot opponent, and you are playing ${botColor ? getSidequestColorLabel(botColor) : 'one side of the board'}.`,
        `${humanName} is the human player.`,
        `The user speaking in this chat is ${viewerName}${viewerColor ? `, playing ${getSidequestColorLabel(viewerColor)}` : ''}.`,
        `Game status: ${status}.`,
        `Current turn: ${getSidequestColorLabel(currentTurnColor)} (${currentTurnName}).`
    ];

    if (state && state.lastMove) {
        const lastMoveLabel = String(state.lastMove.notation || state.lastMove.uci || `${state.lastMove.from}-${state.lastMove.to}`).trim();
        const lastMoveColor = state.lastMove.playerColor === 'b' ? 'b' : 'w';
        lines.push(`Last move played: ${lastMoveLabel} by ${getSidequestSeatName(gameData, lastMoveColor)} (${getSidequestColorLabel(lastMoveColor)}).`);
    } else {
        lines.push('Last move played: none yet.');
    }

    if (status === 'completed') {
        const summary = String(game.result_summary_label || 'Game over').trim();
        const reason = String(game.result_reason_label || game.result_label || '').trim();
        lines.push(`Final result: ${summary}${reason ? ` by ${reason}` : ''}.`);
    } else {
        lines.push('Final result: the game is still in progress.');
    }

    return lines
        .concat(buildSidequestRecentMoveContextLines(gameData))
        .concat(buildSidequestBoardContextLines(gameData));
}

function findSidequestBotAiChatKeyForGame(gameData) {
    const gameId = Math.max(0, Number(gameData && gameData.game && gameData.game.id || 0) || 0);
    if (!gameId || !window.aiChatsMap || typeof window.aiChatsMap !== 'object') {
        return '';
    }

    for (const [chatKey, aiData] of Object.entries(window.aiChatsMap)) {
        const parsed = parseSidequestBotAiChatNotes(aiData && aiData.notes ? aiData.notes : '');
        if (parsed.meta && Number(parsed.meta.gameId || 0) === gameId) {
            return chatKey;
        }
    }

    return '';
}

async function saveAiChatRecord(chatKey, updates = {}) {
    const normalizedChatKey = String(chatKey || '').trim();
    const aiData = getAiChatRecord(normalizedChatKey);
    if (!normalizedChatKey || !aiData || !(aiData.id > 0)) {
        throw new Error('AI chat not found.');
    }

    const displayName = String(updates.displayName !== undefined ? updates.displayName : aiData.displayName || 'QuillTalk AI').trim() || 'QuillTalk AI';
    const bio = String(updates.bio !== undefined ? updates.bio : aiData.bio || '').trim();
    const notes = typeof updates.notes === 'string' ? updates.notes : String(aiData.notes || '');

    const formData = new FormData();
    formData.append('token', token);
    formData.append('ai_chat_id', String(aiData.id));
    formData.append('display_name', displayName);
    formData.append('bio', bio);
    formData.append('notes', notes);

    const response = await fetch('update_ai_chat.php', {
        method: 'POST',
        body: formData
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.success) {
        throw new Error(data.error || 'Could not update the AI chat.');
    }

    const nextRecord = cacheAiChatRecord(normalizedChatKey, {
        id: aiData.id,
        displayName,
        bio,
        notes,
        profilePic: data.profile_pic || aiData.profilePic || DEFAULT_AI_PROFILE_PIC
    });
    syncAiChatContact(normalizedChatKey);
    return nextRecord;
}

async function syncSidequestBotAiChatRecord(chatKey, gameData, metaUpdates = {}, options = {}) {
    const normalizedChatKey = String(chatKey || '').trim();
    const aiData = getAiChatRecord(normalizedChatKey);
    if (!normalizedChatKey || !aiData) {
        return null;
    }

    const parsed = parseSidequestBotAiChatNotes(aiData.notes || '');
    const fallbackMeta = normalizeSidequestBotAiChatMeta({
        gameId: gameData && gameData.game ? gameData.game.id : 0,
        gameType: getSidequestType(gameData),
        botColor: getSidequestBotColor(gameData)
    });
    const nextMeta = normalizeSidequestBotAiChatMeta({
        ...(parsed.meta || fallbackMeta || {}),
        ...metaUpdates
    });
    if (!nextMeta) {
        return aiData;
    }

    const instructions = options.instructions !== undefined
        ? String(options.instructions)
        : (parsed.instructions || buildSidequestBotAiDefaultInstructions(gameData));
    const displayName = String(options.displayName || aiData.displayName || buildSidequestBotAiChatDisplayName(gameData)).trim() || buildSidequestBotAiChatDisplayName(gameData);
    const bio = String(options.bio || aiData.bio || buildSidequestBotAiChatBio(gameData)).trim();
    const nextNotes = buildSidequestBotAiChatNotes(nextMeta, instructions);

    if (
        displayName === String(aiData.displayName || '')
        && bio === String(aiData.bio || '')
        && nextNotes === String(aiData.notes || '')
    ) {
        syncAiChatContact(normalizedChatKey);
        return aiData;
    }

    return saveAiChatRecord(normalizedChatKey, {
        displayName,
        bio,
        notes: nextNotes
    });
}

async function createSidequestBotAiChat(gameData) {
    const displayName = buildSidequestBotAiChatDisplayName(gameData);
    const bio = buildSidequestBotAiChatBio(gameData);
    const notes = buildSidequestBotAiChatNotes({
        gameId: gameData && gameData.game ? gameData.game.id : 0,
        gameType: getSidequestType(gameData),
        botColor: getSidequestBotColor(gameData)
    }, buildSidequestBotAiDefaultInstructions(gameData));

    const formData = new FormData();
    formData.append('token', token);
    formData.append('display_name', displayName);
    formData.append('bio', bio);
    formData.append('notes', notes);

    const response = await fetch('create_ai_chat.php', {
        method: 'POST',
        body: formData
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.success || !data.ai_chat_id) {
        throw new Error(data.error || 'Could not create the bot chat.');
    }

    const chatKey = `ai:${Math.max(0, Number(data.ai_chat_id || 0) || 0)}`;
    cacheAiChatRecord(chatKey, {
        id: Math.max(0, Number(data.ai_chat_id || 0) || 0),
        displayName,
        bio,
        notes,
        profilePic: data.profile_pic || DEFAULT_AI_PROFILE_PIC
    });
    syncAiChatContact(chatKey);
    return chatKey;
}

async function ensureSidequestBotAiChat(gameData) {
    if (!gameData || !gameData.game || !gameData.game.bot_enabled) {
        return '';
    }

    if ((!window.aiChatsMap || typeof window.aiChatsMap !== 'object' || !Object.keys(window.aiChatsMap).length) && typeof loadAiChatsFromDatabase === 'function') {
        try {
            await loadAiChatsFromDatabase();
        } catch (error) {
            console.warn('Unable to refresh AI chats before opening the bot conversation.', error);
        }
    }

    let chatKey = findSidequestBotAiChatKeyForGame(gameData);
    if (!chatKey && typeof loadAiChatsFromDatabase === 'function') {
        try {
            await loadAiChatsFromDatabase();
            chatKey = findSidequestBotAiChatKeyForGame(gameData);
        } catch (error) {
            console.warn('Unable to re-check AI chats before creating the bot conversation.', error);
        }
    }
    if (!chatKey) {
        chatKey = await createSidequestBotAiChat(gameData);
    } else {
        await syncSidequestBotAiChatRecord(chatKey, gameData);
    }

    syncAiChatContact(chatKey);
    return chatKey;
}

async function resolveAiChatSupplementalContext(chatKey) {
    const normalizedChatKey = String(chatKey || '').trim();
    const meta = getSidequestBotAiChatMeta(normalizedChatKey);
    if (!normalizedChatKey || !meta) {
        return null;
    }

    let gameData = null;
    if (activeChessGameData && activeChessGameData.game && Number(activeChessGameData.game.id || 0) === Number(meta.gameId || 0)) {
        gameData = activeChessGameData;
    } else {
        try {
            gameData = await fetchGameData(meta.gameId, { silent: true, allowBackground: true });
        } catch (error) {
            gameData = null;
        }
    }

    if (!gameData || !gameData.game) {
        return {
            chatLabel: buildSidequestBotAiChatDisplayName({ game: { type: meta.gameType } }),
            contextLines: [
                `This AI chat is linked to Sidequest game #${meta.gameId}.`,
                'The live game snapshot could not be refreshed just now, so say that you could not pull the latest board state.'
            ]
        };
    }

    return {
        chatLabel: buildSidequestBotAiChatDisplayName(gameData),
        contextLines: buildSidequestBotAiContextLines(gameData)
    };
}

function buildSidequestBotFinalMessage(gameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    const state = getNormalizedSidequestState(gameData);
    const botColor = getSidequestBotColor(gameData);
    const winnerColor = state && (state.winnerColor === 'b' || state.winnerColor === 'w')
        ? state.winnerColor
        : null;
    const reason = getLocalizedSidequestResultDetail(gameData, game.result_reason_label || game.result_label || '');

    const drawMessages = [
        'Good game. A draw feels fair after that one.',
        'GG. That was a balanced fight all the way through.',
        'Good game. We pushed that one to an even finish.',
        'GG. Hard to complain about a draw there.'
    ];
    const botWinMessages = [
        'Good game. I finally managed to convert that one.',
        'GG. That was tense right up to the end.',
        'Good game. I had to work for that finish.',
        'GG. That one stayed sharp the whole way.'
    ];
    const humanWinMessages = [
        'Good game. You closed that out nicely.',
        'GG. You earned that finish.',
        'Good game. You handled the ending better than I did.',
        'GG. You found the cleaner route at the end.'
    ];

    let pool = drawMessages;
    if (winnerColor && botColor && winnerColor === botColor) {
        pool = botWinMessages;
    } else if (winnerColor) {
        pool = humanWinMessages;
    }

    const chosen = pool[Math.floor(Math.random() * pool.length)] || 'Good game.';
    return reason ? `${chosen} ${reason}.` : chosen;
}

async function deliverSidequestBotFinalMessage(chatKey, gameData, finalSignature, deliveryKey = '') {
    const normalizedChatKey = String(chatKey || '').trim();
    if (!normalizedChatKey || !gameData || !gameData.game) {
        return;
    }

    const message = buildSidequestBotFinalMessage(gameData);
    if (!message) {
        return;
    }

    const formData = new FormData();
    formData.append('token', token);
    formData.append('ai_chat_key', normalizedChatKey);
    formData.append('message', message);
    formData.append('sender_type', 'ai');

    const response = await fetch('send_ai_message.php', {
        method: 'POST',
        body: formData
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.success || !data.message) {
        throw new Error(data.error || 'Could not send the final bot message.');
    }

    if (deliveryKey) {
        rememberStoredSidequestBotFinalDelivery(deliveryKey);
    }
    rememberSidequestBotFinalSignatureLocally(normalizedChatKey, gameData, finalSignature);

    if (selectedUser === normalizedChatKey) {
        try {
            appendMessage(data.message);
            lastId = Math.max(Number(lastId || 0), Number(data.message.id || data.message.message_id || 0));
            scrollChatToBottomAfterSend();
        } catch (error) {
            console.warn('Could not append the final bot message to the open conversation.', error);
        }
    }
    if (typeof updateContactPreview === 'function') {
        try {
            updateContactPreview(normalizedChatKey, data.message, selectedUser === normalizedChatKey);
        } catch (error) {
            console.warn('Could not refresh the sidequest bot preview after the final message.', error);
        }
    }

    try {
        await syncSidequestBotAiChatRecord(normalizedChatKey, gameData, {
            lastFinalSignature: finalSignature
        });
    } catch (error) {
        console.warn('Could not persist the sidequest bot final signature after sending the message.', error);
    }
}

async function maybeSendSidequestBotFinalMessage(gameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    if (!game.bot_enabled || game.status !== 'completed') {
        return;
    }

    const finalSignature = [
        game.id || 0,
        game.result_code || '',
        game.result_summary_label || '',
        game.result_reason_label || '',
        game.completed_at || ''
    ].join(':');
    if (!finalSignature) {
        return;
    }

    const requestKey = `${game.id || 0}:${finalSignature}`;
    const deliveryKey = buildSidequestBotFinalDeliveryKey(gameData, finalSignature);
    if (activeSidequestBotDeliveredFinalSignatures.has(requestKey)) {
        return;
    }
    if (activeSidequestBotFinalMessageRequests.has(requestKey)) {
        return;
    }
    if (deliveryKey && hasStoredSidequestBotFinalDelivery(deliveryKey)) {
        activeSidequestBotDeliveredFinalSignatures.add(requestKey);
        return;
    }

    activeSidequestBotFinalMessageRequests.add(requestKey);
    try {
        const chatKey = await ensureSidequestBotAiChat(gameData);
        const existingMeta = getSidequestBotAiChatMeta(chatKey);
        if (existingMeta && existingMeta.lastFinalSignature === finalSignature) {
            if (deliveryKey) {
                rememberStoredSidequestBotFinalDelivery(deliveryKey);
            }
            activeSidequestBotDeliveredFinalSignatures.add(requestKey);
            return;
        }
        activeSidequestBotDeliveredFinalSignatures.add(requestKey);
        await deliverSidequestBotFinalMessage(chatKey, gameData, finalSignature, deliveryKey);
    } catch (error) {
        activeSidequestBotDeliveredFinalSignatures.delete(requestKey);
        throw error;
    } finally {
        activeSidequestBotFinalMessageRequests.delete(requestKey);
    }
}

function syncChessConversationDockState() {
    const elements = getChessModalElements();
    const chatContainer = getChessConversationContainer();
    const isChatMounted = !!(chatContainer && elements.conversationDock && chatContainer.parentElement === elements.conversationDock);
    if (elements.conversationColumn) {
        elements.conversationColumn.hidden = !isChatMounted;
    }
}

function mountChessConversationDock() {
    const elements = getChessModalElements();
    const chatContainer = getChessConversationContainer();
    if (!chatContainer || !elements.conversationDock) {
        syncChessConversationDockState();
        return false;
    }

    if (chatContainer.parentElement === elements.conversationDock) {
        chatContainer.classList.add('is-docked-in-chess-modal');
        syncChessConversationDockState();
        return true;
    }

    if (typeof window.setChatActionsDropdownOpen === 'function') {
        window.setChatActionsDropdownOpen(false);
    }
    if (typeof window.closeVoiceActionMenu === 'function') {
        window.closeVoiceActionMenu();
    }
    if (typeof window.hideContactInfoPanel === 'function') {
        window.hideContactInfoPanel();
    }
    if (isMobileViewport() && typeof window.closeRightSidebar === 'function') {
        window.closeRightSidebar();
    }

    activeChessConversationOriginalParent = chatContainer.parentElement;
    activeChessConversationPlaceholder = document.createElement('div');
    activeChessConversationPlaceholder.className = 'chess-chat-container-placeholder';
    activeChessConversationPlaceholder.setAttribute('aria-hidden', 'true');

    if (chatContainer.parentNode) {
        chatContainer.parentNode.insertBefore(activeChessConversationPlaceholder, chatContainer);
    }

    elements.conversationDock.appendChild(chatContainer);
    chatContainer.classList.add('is-docked-in-chess-modal');
    syncChessConversationDockState();
    return true;
}

function restoreChessConversationDock() {
    const elements = getChessModalElements();
    const chatContainer = getChessConversationContainer();

    if (chatContainer && chatContainer.classList.contains('is-docked-in-chess-modal')) {
        if (activeChessConversationPlaceholder && activeChessConversationPlaceholder.parentNode) {
            activeChessConversationPlaceholder.parentNode.insertBefore(chatContainer, activeChessConversationPlaceholder);
            activeChessConversationPlaceholder.remove();
        } else if (activeChessConversationOriginalParent) {
            activeChessConversationOriginalParent.appendChild(chatContainer);
        }
    }

    if (chatContainer) {
        chatContainer.classList.remove('is-docked-in-chess-modal');
    }

    if (activeChessConversationPlaceholder && activeChessConversationPlaceholder.parentNode) {
        activeChessConversationPlaceholder.remove();
    }

    activeChessConversationPlaceholder = null;
    activeChessConversationOriginalParent = null;
    syncChessConversationDockState();
}

function resolveChessConversationKey(gameData = activeChessGameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    if (game.bot_enabled) {
        return ensureSidequestBotAiChat(gameData);
    }

    const viewer = gameData && gameData.viewer ? gameData.viewer : {};
    const players = gameData && gameData.players ? gameData.players : {};
    const groupId = Math.max(0, Number(game.group_id || 0) || 0);
    if (groupId > 0) {
        return `group:${groupId}`;
    }

    const viewerUserId = Math.max(0, Number(viewer.user_id || 0) || 0);
    const creatorUserId = Math.max(0, Number(game.creator_user_id || 0) || 0);
    const recipientId = Math.max(0, Number(game.recipient_id || 0) || 0);
    const playerIds = [players.white, players.black]
        .map(player => Math.max(0, Number(player && player.user_id || 0) || 0))
        .filter(playerId => playerId > 0);
    const otherPlayerId = playerIds.find(playerId => playerId !== viewerUserId);

    if (otherPlayerId) {
        return String(otherPlayerId);
    }
    if (recipientId > 0) {
        if (viewerUserId > 0 && recipientId === viewerUserId && creatorUserId > 0) {
            return String(creatorUserId);
        }
        return String(recipientId);
    }
    if (creatorUserId > 0 && creatorUserId !== viewerUserId) {
        return String(creatorUserId);
    }

    return '';
}

async function prepareChessConversationDock(gameData = activeChessGameData) {
    const targetChatKey = String(await resolveChessConversationKey(gameData) || '').trim();
    const previousChatKey = String(selectedUser || '').trim();
    activeChessSidebarWasOpen = !!(rightSidebar && rightSidebar.classList.contains('is-open') && !isMobileViewport());
    activeChessSidebarRestoreUser = activeChessSidebarWasOpen
        ? String((rightSidebar && rightSidebar.dataset && rightSidebar.dataset.activeUser) || previousChatKey || targetChatKey || '').trim()
        : '';
    if (targetChatKey && isTemporaryAiChatKey(targetChatKey) && previousChatKey && previousChatKey !== targetChatKey) {
        activeChessConversationReturnChatKey = previousChatKey;
    }
    activeChessDockedConversationChatKey = targetChatKey;
    if (targetChatKey && typeof window.openConversation === 'function') {
        await window.openConversation(targetChatKey, { scrollToBottomOnInitialLoad: true });
    }

    const mounted = mountChessConversationDock();
    if (!mounted) {
        syncChessConversationDockState();
    } else if (isChessConversationDockMounted()) {
        scrollChatToBottomAfterSend();
    }
    return mounted;
}

function formatChessTimeControlLabel(seconds) {
    const normalizedSeconds = Math.max(0, Number(seconds || 0) || 0);
    if (!normalizedSeconds) {
        return 'Custom';
    }
    const minutes = Math.round(normalizedSeconds / 60);
    return `${minutes} min`;
}

function getSelectedChessHumanOpponentLabel() {
    const chatKey = getChessSelectedChatKey();
    if (!chatKey) {
        return 'your contact';
    }

    if (typeof window.isGroupChatKey === 'function' && window.isGroupChatKey(chatKey)) {
        return 'someone in this chat';
    }

    const meta = typeof window.getContactMeta === 'function'
        ? window.getContactMeta(chatKey)
        : null;
    return typeof window.getDisplayNameForUser === 'function'
        ? (window.getDisplayNameForUser(chatKey, meta, chatKey) || 'your contact')
        : 'your contact';
}

function getActiveChessSetupGameType() {
    if (activeChessSetupGameType === SIDEQUEST_GAME_CHECKERS) {
        return SIDEQUEST_GAME_CHECKERS;
    }
    if (activeChessSetupGameType === SIDEQUEST_GAME_CONNECT_FOUR) {
        return SIDEQUEST_GAME_CONNECT_FOUR;
    }
    return SIDEQUEST_GAME_CHESS;
}

function syncChessSetupSelectionUi() {
    const elements = getChessSetupModalElements();
    if (!elements.modal) {
        return;
    }

    const setupGameType = getActiveChessSetupGameType();
    const setupGameLabel = setupGameType === SIDEQUEST_GAME_CHECKERS
        ? 'Checkers'
        : (setupGameType === SIDEQUEST_GAME_CONNECT_FOUR ? 'Connect Four' : 'Chess');
    const humanLabel = getSelectedChessHumanOpponentLabel();
    if (elements.title) {
        elements.title.textContent = `Start ${setupGameLabel}`;
    }
    if (elements.subtitle) {
        elements.subtitle.textContent = setupGameType === SIDEQUEST_GAME_CHECKERS
            ? 'Choose your opponent and match settings before the checkers invite lands in chat.'
            : (setupGameType === SIDEQUEST_GAME_CONNECT_FOUR
                ? 'Choose your opponent and match settings before the connect four invite lands in chat.'
                : 'Choose your opponent and match settings before the invite lands in chat.');
    }
    if (elements.humanTitle) {
        elements.humanTitle.textContent = `Play ${setupGameLabel} with ${humanLabel}`;
    }
    if (elements.humanCopy) {
        elements.humanCopy.textContent = (typeof window.isGroupChatKey === 'function' && window.isGroupChatKey(getChessSelectedChatKey()))
            ? `Send a ${setupGameLabel.toLowerCase()} invite into this group so another player can join that seat.`
            : `${humanLabel} will get the ${setupGameLabel.toLowerCase()} invite in this chat and join from their side.`;
    }

    const opponentCards = [elements.humanBtn, elements.botBtn];
    opponentCards.forEach(card => {
        if (!card) {
            return;
        }
        const mode = String(card.dataset.opponentMode || '').trim().toLowerCase();
        const isSelected = activeChessSetupOpponentMode === mode;
        card.classList.toggle('is-selected', isSelected);
        card.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });

    if (elements.options) {
        elements.options.hidden = !activeChessSetupOpponentMode;
    }

    document.querySelectorAll('[data-chess-color-choice]').forEach(button => {
        const isSelected = String(button.getAttribute('data-chess-color-choice') || '').trim().toLowerCase() === activeChessSetupColorChoice;
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
    document.querySelectorAll('[data-chess-time-control]').forEach(button => {
        const isSelected = Number(button.getAttribute('data-chess-time-control') || 0) === activeChessSetupTimeControlSeconds;
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });

    if (elements.startBtn) {
        const isReady = !!activeChessSetupOpponentMode && !activeChessSetupSubmitting;
        elements.startBtn.disabled = !isReady;
        elements.startBtn.textContent = activeChessSetupSubmitting ? `Starting ${setupGameLabel}...` : `Start ${setupGameLabel}`;
    }
    if (elements.cancelBtn) {
        elements.cancelBtn.disabled = activeChessSetupSubmitting;
    }
    if (elements.humanBtn) {
        elements.humanBtn.disabled = activeChessSetupSubmitting;
    }
    if (elements.botBtn) {
        elements.botBtn.disabled = activeChessSetupSubmitting;
    }
}

function setChessSetupStatus(message = '', isError = false) {
