    activeChessSetupGameType = normalizedGameType === SIDEQUEST_GAME_CHECKERS
        ? SIDEQUEST_GAME_CHECKERS
        : (normalizedGameType === SIDEQUEST_GAME_CONNECT_FOUR ? SIDEQUEST_GAME_CONNECT_FOUR : SIDEQUEST_GAME_CHESS);
    activeChessSetupOpponentMode = '';
    activeChessSetupColorChoice = 'random';
    activeChessSetupTimeControlSeconds = 300;
    activeChessSetupSubmitting = false;
    setChessSetupStatus('');
    syncChessSetupSelectionUi();

    bringOverlayToFront(elements.modal, 6);
