function showChessResultPopup(summary, reason) {
    const elements = getChessModalElements();
    if (!elements.resultPopup || !elements.resultPopupSummary || !elements.resultPopupReason) {
        return;
    }

    elements.resultPopupSummary.textContent = summary || 'Game finished';
    elements.resultPopupReason.textContent = reason || '';
    elements.resultPopupReason.hidden = !reason;
    elements.resultPopup.hidden = false;
    requestAnimationFrame(() => {
        if (elements.resultPopupCloseBtn) {
            elements.resultPopupCloseBtn.focus();
        }
    });
}

function getChessLiveClocks(gameData = activeChessGameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    const clocks = gameData && gameData.clocks ? gameData.clocks : {};
    let whiteMs = Math.max(0, Number(clocks.white_ms || 0) || 0);
    let blackMs = Math.max(0, Number(clocks.black_ms || 0) || 0);

    if (game.status === 'active' && activeChessBoardState) {
        const fetchedAt = Math.max(0, Number(gameData.__clientFetchedAtMs || 0) || 0);
        const elapsedSinceFetch = fetchedAt ? Math.max(0, Date.now() - fetchedAt) : 0;
        const activeTurnColor = activeChessBoardState.turn === 'b' ? 'b' : 'w';
        if (activeTurnColor === 'w') {
            whiteMs = Math.max(0, whiteMs - elapsedSinceFetch);
        } else {
            blackMs = Math.max(0, blackMs - elapsedSinceFetch);
        }
    }

    return { whiteMs, blackMs };
}

function formatChessClock(ms) {
    const totalSeconds = Math.max(0, Math.ceil((Number(ms || 0) || 0) / 1000));
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    if (hours > 0) {
        return `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function maybeShowChessResultPopup(gameData = activeChessGameData) {
    if (!gameData || !gameData.game || gameData.game.status !== 'completed') {
        return;
    }

    const signature = [
        gameData.game.id || 0,
        gameData.game.result_code || '',
        gameData.game.result_summary_label || '',
        gameData.game.result_reason_label || ''
    ].join(':');
    if (!signature || signature === activeChessLastResultSignature) {
        return;
    }

    activeChessLastResultSignature = signature;
    showChessResultPopup(
        getLocalizedSidequestResultSummary(gameData, gameData.game.result_summary_label || 'Game finished'),
        getLocalizedSidequestResultDetail(gameData, gameData.game.result_reason_label || gameData.game.result_label || '')
    );
}

function refreshChessLiveClockUi() {
    const elements = getChessModalElements();
    if (!elements.modal || elements.modal.getAttribute('aria-hidden') !== 'false' || !activeChessGameData) {
        return;
    }

    if (isSketchoffSidequest(activeChessGameData)) {
        renderChessPlayerStrip(elements.whitePlayer, activeChessGameData, 'w');
        renderChessPlayerStrip(elements.blackPlayer, activeChessGameData, 'b');
        refreshSketchoffLiveUi();
        return;
    }

    renderChessPlayerStrip(elements.whitePlayer, activeChessGameData, 'w');
    renderChessPlayerStrip(elements.blackPlayer, activeChessGameData, 'b');

    const game = activeChessGameData.game || {};
    if (game.status !== 'active') {
        return;
    }

    const liveClocks = getChessLiveClocks(activeChessGameData);
    const activeTurnClockMs = activeChessBoardState && activeChessBoardState.turn === 'b'
        ? liveClocks.blackMs
        : liveClocks.whiteMs;
    if (activeTurnClockMs <= 0 && activeChessGameId && !activeChessIsSubmittingMove && !activeChessIsProcessingBotTurn) {
        clearChessClockTimer();
        loadChessGame(activeChessGameId, { silent: true }).catch(() => {});
    }
}

function scheduleChessClockTimer() {
    clearChessClockTimer();
    if (!activeChessGameData || !activeChessGameData.game || activeChessGameData.game.status !== 'active') {
        return;
    }
    activeChessClockTimer = window.setInterval(() => {
        refreshChessLiveClockUi();
    }, 1000);
}

function clearChessModalPolling() {
    if (activeChessPollTimer) {
        clearInterval(activeChessPollTimer);
        activeChessPollTimer = 0;
    }
}

function scheduleChessModalPolling() {
    clearChessModalPolling();
    if (!activeChessGameId) {
        return;
    }
    activeChessPollTimer = window.setInterval(() => {
        const elements = getChessModalElements();
        if (
            !elements.modal
            || elements.modal.getAttribute('aria-hidden') !== 'false'
            || activeChessIsSubmittingMove
            || activeChessIsProcessingBotTurn
            || activeSketchoffIsDrawing
            || activeSketchoffColorPickerOpen
        ) {
            return;
        }
        loadChessGame(activeChessGameId, { silent: true }).catch(() => {});
    }, GAME_MODAL_REFRESH_MS);
}

function closeChessGameModal() {
    const elements = getChessModalElements();
    const returnChatKey = String(activeChessConversationReturnChatKey || '').trim();
    const dockedChatKey = String(activeChessDockedConversationChatKey || '').trim();
    const restoreSidebar = activeChessSidebarWasOpen && !isMobileViewport();
    const restoreSidebarUser = String(activeChessSidebarRestoreUser || selectedUser || returnChatKey || dockedChatKey || '').trim();
    const dockedChatScrollTop = chatBox ? chatBox.scrollTop : null;
    clearChessModalPolling();
    clearChessClockTimer();
    clearChessBotTurnTimer();
    activeChessBotTurnRequestToken = 0;
    closeChessResultPopup();
    closeChessPromotionPrompt();
    activeChessGameId = 0;
    activeChessGameData = null;
    activeChessBoardState = null;
    activeChessSelectedSquare = '';
    activeChessLegalMoves = [];
    activeChessIsSubmittingMove = false;
    activeChessIsProcessingBotTurn = false;
    activeChessChatSubmitting = false;
    activeChessLastResultSignature = '';
    activeChessLastChatMessageCount = 0;
    activeSketchoffIsDrawing = false;
    activeSketchoffColorPickerOpen = false;
    activeSketchoffBrushColor = '#111827';
    activeSketchoffBrushSize = 6;

    if (elements.chatInput) {
        elements.chatInput.value = '';
    }
    restoreChessConversationDock();
    if (dockedChatKey && isTemporaryAiChatKey(dockedChatKey)) {
        removeAiChatContact(dockedChatKey);
    }
    activeChessConversationReturnChatKey = '';
    activeChessDockedConversationChatKey = '';
    activeChessSidebarWasOpen = false;
    activeChessSidebarRestoreUser = '';
    if (!elements.modal) {
        return;
    }

    elements.modal.setAttribute('aria-hidden', 'true');
    elements.modal.style.display = 'none';
    resetOverlayZIndex(elements.modal);

    const restoreConversationPromise = (
        returnChatKey
        && dockedChatKey
        && String(selectedUser || '').trim() === dockedChatKey
        && isTemporaryAiChatKey(dockedChatKey)
        && typeof window.openConversation === 'function'
    )
        ? window.openConversation(returnChatKey).catch(error => {
            console.warn('Could not restore the previous conversation after closing the sidequest.', error);
        })
        : Promise.resolve();

    window.setTimeout(() => {
        Promise.resolve(restoreConversationPromise).finally(() => {
            const restoreUiState = () => {
                if (chatBox && dockedChatScrollTop !== null) {
                    chatBox.scrollTop = dockedChatScrollTop;
                }
                if (restoreSidebar && restoreSidebarUser) {
                    requestRightSidebarRestore(restoreSidebarUser);
                } else {
                    clearPendingRightSidebarRestore();
                }
            };

            if (typeof window.requestAnimationFrame === 'function') {
                window.requestAnimationFrame(() => {
                    window.requestAnimationFrame(restoreUiState);
                });
                return;
            }

            restoreUiState();
        });
    }, 0);
}

async function fetchGameData(gameId, options = {}) {
    const normalizedGameId = Math.max(0, Number(gameId || 0) || 0);
    if (!normalizedGameId) {
        throw new Error('Missing game id');
    }

    const response = await fetch(`get_game_data.php?token=${encodeURIComponent(getChessSessionToken())}&game_id=${normalizedGameId}&_=${Date.now()}`);
    const rawResponseText = await response.text();
    let data = {};
    if (rawResponseText) {
        try {
            data = JSON.parse(rawResponseText);
        } catch (error) {
            data = {};
        }
    }
    if (!response.ok || !data.success || !data.data) {
        const rawFallbackMessage = rawResponseText
            ? rawResponseText.trim().replace(/\s+/g, ' ').slice(0, 220)
            : '';
        const emptyServerFailureMessage = !rawFallbackMessage && response.status >= 500
            ? `The game endpoint returned an empty HTTP ${response.status} response while loading the board.`
            : '';
        const errorMessage = (typeof data.error === 'string' && data.error)
            || emptyServerFailureMessage
            || rawFallbackMessage
            || `Failed to load the game (HTTP ${response.status}).`;
        if (!options.silent) {
            showToast(errorMessage, 'error');
        }
        throw new Error(errorMessage);
    }

    return data.data;
}

function setActiveChessGameData(gameData, options = {}) {
    const previousGameData = activeChessGameData;
    const previousBoardState = activeChessBoardState;
    const previousSelectedSquare = activeChessSelectedSquare;
    const previousLegalMoves = Array.isArray(activeChessLegalMoves)
        ? activeChessLegalMoves
            .filter(move => move && typeof move === 'object')
            .map(move => ({ ...move }))
        : [];
    const engine = getSidequestEngine(gameData);
    const preserveSelection = !!(options && options.preserveSelection);
    const nextGameData = gameData && typeof gameData === 'object'
        ? { ...gameData, __clientFetchedAtMs: Date.now() }
        : gameData;
    activeChessGameData = nextGameData;
    activeChessBoardState = engine && typeof engine.normalizeState === 'function'
        ? engine.normalizeState(gameData && gameData.state ? gameData.state : null)
        : null;
    activeChessSelectedSquare = '';
    activeChessLegalMoves = [];

    if (
        preserveSelection
        && previousSelectedSquare
        && engine
        && activeChessBoardState
        && previousBoardState
        && previousGameData
        && previousGameData.game
        && nextGameData
        && nextGameData.game
        && Number(previousGameData.game.id || 0) === Number(nextGameData.game.id || 0)
        && getSidequestStateSignature(previousBoardState) === getSidequestStateSignature(activeChessBoardState)
    ) {
        const viewerColor = getChessViewerColor(nextGameData);
        const selectedCoords = typeof engine.squareToCoords === 'function'
            ? engine.squareToCoords(previousSelectedSquare)
            : null;
        const selectedPiece = selectedCoords && activeChessBoardState.board && activeChessBoardState.board[selectedCoords.row]
            ? activeChessBoardState.board[selectedCoords.row][selectedCoords.col]
            : null;
        const recomputedMoves = typeof engine.getLegalMovesForSquare === 'function'
            ? engine.getLegalMovesForSquare(activeChessBoardState, previousSelectedSquare)
            : [];
        const preservedMoves = Array.isArray(recomputedMoves) && recomputedMoves.length
            ? recomputedMoves
            : previousLegalMoves;

        if (
            nextGameData.game.status === 'active'
            && viewerColor
            && activeChessBoardState.turn === viewerColor
            && selectedPiece
            && String(selectedPiece).charAt(0) === viewerColor
        ) {
            activeChessSelectedSquare = previousSelectedSquare;
            activeChessLegalMoves = Array.isArray(preservedMoves) ? preservedMoves : [];
        }
    }

    if (isSketchoffSidequest(nextGameData)) {
        const viewerColor = getChessViewerColor(nextGameData);
        if ((viewerColor === 'w' || viewerColor === 'b') && getSketchoffSubmissionForColor(nextGameData, viewerColor)) {
            clearStoredSketchoffDraft(nextGameData, viewerColor);
        }
    }

    closeChessPromotionPrompt();
    scheduleChessClockTimer();
    maybeShowChessResultPopup(nextGameData);
    if (nextGameData && nextGameData.game && nextGameData.game.bot_enabled) {
        maybeSendSidequestBotFinalMessage(nextGameData).catch(error => {
            console.warn('Could not send the sidequest bot final message.', error);
        });
    }
}

function getChessViewerColor(gameData = activeChessGameData) {
    return gameData && gameData.viewer && (gameData.viewer.color === 'w' || gameData.viewer.color === 'b')
        ? gameData.viewer.color
        : '';
}

function getChessPerspectiveColor(gameData = activeChessGameData) {
    if (isConnectFourSidequest(gameData)) {
        return 'w';
    }

    const viewerColor = getChessViewerColor(gameData);
    if (viewerColor === 'w' || viewerColor === 'b') {
        return viewerColor;
    }

    const game = gameData && gameData.game ? gameData.game : {};
    const viewer = gameData && gameData.viewer ? gameData.viewer : {};
    const viewerUserId = Math.max(0, Number(viewer.user_id || 0) || 0);
    if (!viewerUserId) {
        return '';
    }

    if (viewerUserId === Math.max(0, Number(game.creator_user_id || 0) || 0)) {
        return 'w';
    }

    if (!game.group_id && viewerUserId === Math.max(0, Number(game.recipient_id || 0) || 0)) {
        return 'b';
    }

    return '';
}

function getChessPlayerSeatInfo(gameData, seatColor) {
    const players = gameData && gameData.players ? gameData.players : {};
    const player = seatColor === 'w' ? players.white : players.black;
    const game = gameData && gameData.game ? gameData.game : {};
    const viewerColor = getChessViewerColor(gameData);
    const roleLabel = seatColor === 'w' ? 'White pieces' : 'Black pieces';
    const directRecipientId = Math.max(0, Number(game.recipient_id || 0) || 0);
    const reservedRecipientSeat = directRecipientId > 0
        ? [players.white, players.black].find(candidate => Math.max(0, Number(candidate && candidate.user_id || 0) || 0) === directRecipientId)
        : null;

    if (player && player.display_name) {
        const isReservedDirectSeat = !game.group_id
            && game.status === 'waiting'
            && reservedRecipientSeat
            && Math.max(0, Number(player.user_id || 0) || 0) === Math.max(0, Number(reservedRecipientSeat.user_id || 0) || 0);
        const statusText = isReservedDirectSeat
            ? `${roleLabel} · Ready to join`
            : viewerColor === seatColor
                ? `${roleLabel} · You`
                : roleLabel;
        return {
            name: String(player.display_name),
            profilePic: String(player.profile_pic || getChessDefaultProfilePic()),
            statusText
        };
    }

    return {
        name: seatColor === 'b' ? 'Open seat' : 'Waiting',
        profilePic: '',
        statusText: seatColor === 'b' ? `${roleLabel} · Join from chat` : roleLabel
    };
}

function renderChessPlayerStrip(target, gameData, seatColor) {
    if (!target) {
        return;
    }

    const seat = getChessPlayerSeatInfo(gameData, seatColor);
    const viewerTurnColor = activeChessBoardState && activeChessBoardState.turn ? activeChessBoardState.turn : 'w';
    const isTurn = !!(
        gameData
        && gameData.game
        && gameData.game.status === 'active'
        && !isSketchoffSidequest(gameData)
        && viewerTurnColor === seatColor
    );
    const liveClocks = getChessLiveClocks(gameData);
    const remainingMs = isSketchoffSidequest(gameData)
        ? getSketchoffTimeRemainingMs(gameData)
        : (seatColor === 'b' ? liveClocks.blackMs : liveClocks.whiteMs);
    const isLowClock = gameData && gameData.game && gameData.game.status === 'active' && remainingMs <= 10000;
    target.classList.toggle('is-turn', !!isTurn);
    target.innerHTML = '';

    let avatarNode;
    if (seat.profilePic) {
        avatarNode = document.createElement('img');
        avatarNode.className = 'chess-player-avatar';
        avatarNode.src = normalizeChessProfilePic(seat.profilePic, 'direct');
        avatarNode.alt = seat.name;
    } else {
        avatarNode = document.createElement('div');
        avatarNode.className = 'chess-player-avatar placeholder';
        avatarNode.textContent = seatColor === 'w' ? 'W' : 'B';
    }

    const meta = document.createElement('div');
    meta.className = 'chess-player-meta';

    const topRow = document.createElement('div');
    topRow.className = 'chess-player-top';

    const name = document.createElement('div');
    name.className = 'chess-player-name';
    name.textContent = seat.name;

    const clock = document.createElement('div');
    clock.className = 'chess-player-clock';
    if (isTurn) {
        clock.classList.add('is-running');
    }
    if (isLowClock) {
        clock.classList.add('is-low');
    }
    clock.textContent = formatChessClock(remainingMs);

    const role = document.createElement('div');
    role.className = 'chess-player-role';
    if (isSketchoffSidequest(gameData)) {
        const submission = getSketchoffSubmissionForColor(gameData, seatColor);
        const score = getSketchoffScoreForColor(gameData, seatColor);
        role.textContent = gameData && gameData.game && gameData.game.status === 'waiting'
            ? (seat.profilePic ? 'Ready when the round starts' : 'Waiting for a player')
            : gameData && gameData.game && gameData.game.status === 'completed'
            ? (submission ? `Sketch submitted${score !== null ? ` · ${Math.round(score)}% match` : ''}` : 'No sketch submitted')
            : (submission ? 'Sketch submitted' : 'Drawing in progress');
        clock.textContent = gameData && gameData.game && gameData.game.status === 'waiting'
            ? '--:--'
            : gameData && gameData.game && gameData.game.status === 'completed'
            ? `${Math.round(score !== null ? score : 0)}%`
            : formatSketchoffCountdown(remainingMs);
    } else {
        role.textContent = seat.statusText;
    }

    topRow.appendChild(name);
    topRow.appendChild(clock);
    meta.appendChild(topRow);
    meta.appendChild(role);
    target.appendChild(avatarNode);
    target.appendChild(meta);
}

function buildChessInviteSubtitle(gameData) {
    const game = gameData && gameData.game ? gameData.game : {};
    const players = gameData && gameData.players ? gameData.players : {};
    const state = getNormalizedSidequestState(gameData);
    const label = getSidequestLabel(gameData);

    if (game.status === 'waiting') {
        if (!game.group_id && game.recipient_id) {
            const waitingPlayer = [players.white, players.black].find(player => Math.max(0, Number(player && player.user_id || 0) || 0) === Math.max(0, Number(game.recipient_id || 0) || 0));
            if (waitingPlayer && waitingPlayer.display_name) {
                return `Waiting for ${waitingPlayer.display_name} to join the ${label} game.`;
            }
        }
        return `Waiting for someone to join the ${label} game.`;
    }

    if (isSketchoffSidequest(gameData) && game.status === 'active') {
        return `Prompt "${getSketchoffPrompt(gameData)}" is live. ${formatSketchoffCountdown(getSketchoffTimeRemainingMs(gameData))} left to sketch.`;
    }

    if (game.status === 'completed') {
        const localizedSummary = getLocalizedSidequestResultSummary(gameData);
        const localizedDetail = getLocalizedSidequestResultDetail(gameData, game.result_reason_label || game.result_label || '');
        if (game.result_summary_label && localizedDetail) {
            return `${localizedSummary}. ${localizedDetail}.`;
        }
        return localizedSummary || game.result_label || `${label} finished.`;
    }

    if (!state) {
        return `${label} is live.`;
    }

    const turnColor = state.turn === 'b' ? 'b' : 'w';
    const turnPlayer = turnColor === 'w' ? players.white : players.black;
    const turnName = turnPlayer && turnPlayer.display_name ? turnPlayer.display_name : (turnColor === 'w' ? 'White' : 'Black');
    const suffix = isChessSidequest(gameData) && state.checkColor === turnColor ? ' Check.' : '';
    return `${turnName} to move.${suffix}`;
}

function renderGameInviteCard(gameData, options = {}) {
    const senderDisplayName = String(options.senderDisplayName || 'Someone');
    const isSketchGame = isSketchoffSidequest(gameData);
    const canJoinGame = !!(gameData && gameData.viewer && gameData.viewer.can_join);
    const useJoinAsPrimaryAction = isSketchGame && canJoinGame && gameData && gameData.game && gameData.game.status !== 'completed';
    const card = document.createElement('div');
    card.className = 'game-invite-card';
    card.dataset.gameId = String(gameData && gameData.game ? gameData.game.id : '');
    card.dataset.senderDisplayName = senderDisplayName;

    const top = document.createElement('div');
    top.className = 'game-invite-top';

    const icon = document.createElement('div');
    icon.className = 'game-invite-icon';
    icon.innerHTML = getSidequestIconMarkup(gameData);

    const copy = document.createElement('div');
    copy.className = 'game-invite-copy';

    const title = document.createElement('div');
    title.className = 'game-invite-title';
    title.textContent = `${getLocalizedSidequestStarterName(gameData, senderDisplayName)} started the ${gameData.game.label} game`;

    const subtitle = document.createElement('div');
    subtitle.className = 'game-invite-subtitle';
    subtitle.textContent = buildChessInviteSubtitle(gameData);

    copy.appendChild(title);
    copy.appendChild(subtitle);
    top.appendChild(icon);
    top.appendChild(copy);
    card.appendChild(top);

    const actions = document.createElement('div');
    actions.className = 'game-invite-actions';

    const openButton = document.createElement('button');
    openButton.type = 'button';
    openButton.className = `game-invite-action ${useJoinAsPrimaryAction ? 'primary' : 'secondary'}`;
    openButton.textContent = useJoinAsPrimaryAction
        ? 'Join round'
        : isSketchGame
        ? (gameData.game.status === 'completed' ? 'View reveal' : 'Open round')
        : (gameData.game.status === 'completed' ? 'View board' : 'Open board');
    addTapAndClickListener(openButton, () => {
        openChessGameModal(gameData.game.id, {
            join: useJoinAsPrimaryAction,
            gameType: gameData.game.type
        });
    });
    actions.appendChild(openButton);

    if (canJoinGame && !useJoinAsPrimaryAction) {
        const joinButton = document.createElement('button');
        joinButton.type = 'button';
        joinButton.className = 'game-invite-action primary';
        joinButton.textContent = isSketchGame ? 'Join round' : 'Join';
        addTapAndClickListener(joinButton, () => {
            openChessGameModal(gameData.game.id, { join: true, gameType: gameData.game.type });
        });
        actions.appendChild(joinButton);
    }

    card.appendChild(actions);
    return card;
}

async function buildGameMessageElement(gameMessage, options = {}) {
    const normalized = normalizeGameMessagePayload(gameMessage);
    if (!normalized) {
        return createTextElement('Game unavailable');
    }

    const gameData = await fetchGameData(normalized.gameId, { silent: true });
    return renderGameInviteCard(gameData, options);
}

async function refreshVisibleGameCards(gameId, providedData = null) {
    const normalizedGameId = Math.max(0, Number(gameId || 0) || 0);
    if (!normalizedGameId) {
        return;
    }

    const existingCards = Array.from(document.querySelectorAll(`.game-invite-card[data-game-id="${normalizedGameId}"]`));
    if (!existingCards.length) {
        return;
    }

    let nextData = providedData;
    if (!nextData) {
        try {
            nextData = await fetchGameData(normalizedGameId, { silent: true });
        } catch (error) {
            return;
        }
    }

    existingCards.forEach(card => {
        const replacement = renderGameInviteCard(nextData, {
            senderDisplayName: card.dataset.senderDisplayName || 'Someone'
        });
        card.replaceWith(replacement);
    });
}

function getChessBoardOrientationColor(gameData = activeChessGameData) {
    const perspectiveColor = getChessPerspectiveColor(gameData);
    return perspectiveColor === 'b' ? 'b' : 'w';
}

function syncChessPlayerStripOrder(gameData = activeChessGameData) {
    const elements = getChessModalElements();
    const perspectiveColor = getChessPerspectiveColor(gameData);
    const boardShell = elements.board ? elements.board.closest('.chess-board-shell') : null;
    if (boardShell) {
        boardShell.style.order = '1';
    }
    if (elements.whitePlayer) {
        elements.whitePlayer.style.order = perspectiveColor === 'w' ? '2' : '0';
    }
    if (elements.blackPlayer) {
        elements.blackPlayer.style.order = perspectiveColor === 'w' ? '0' : '2';
    }
}

function getSketchoffState(gameData = activeChessGameData) {
    return isSketchoffSidequest(gameData) ? getNormalizedSidequestState(gameData) : null;
}

function getSketchoffPrompt(gameData = activeChessGameData) {
    const state = getSketchoffState(gameData);
    return state && state.prompt ? String(state.prompt) : '';
}

function getSketchoffSubmissionForColor(gameData, seatColor) {
    const state = getSketchoffState(gameData);
    if (!state) {
        return null;
    }
    return seatColor === 'b' ? state.blackSubmission : state.whiteSubmission;
}

function getSketchoffScoreForColor(gameData, seatColor) {
    const state = getSketchoffState(gameData);
    if (!state) {
        return null;
    }
    const score = seatColor === 'b' ? state.blackScore : state.whiteScore;
    return score === null || score === undefined || score === '' ? null : Math.max(0, Math.min(100, Number(score) || 0));
}

function getSketchoffTimeRemainingMs(gameData = activeChessGameData) {
    const state = getSketchoffState(gameData);
    if (!state) {
        return 0;
    }

    const fallbackMs = Math.max(15, Number(state.roundSeconds || 180) || 180) * 1000;
    const endTimestamp = parseServerDateTimeMs(state.promptEndsAt || '');
    if (!endTimestamp) {
        return fallbackMs;
    }

    const fetchedAt = Math.max(0, Number(gameData && gameData.__clientFetchedAtMs || 0) || 0);
    const elapsedSinceFetch = fetchedAt ? Math.max(0, Date.now() - fetchedAt) : 0;
    const baseRemaining = Math.max(0, Number(gameData && gameData.clocks && gameData.clocks.prompt_remaining_ms || 0) || 0);
    if (baseRemaining > 0) {
        return Math.max(0, baseRemaining - elapsedSinceFetch);
    }
    return Math.max(0, endTimestamp - Date.now());
}

function formatSketchoffCountdown(ms) {
    const totalSeconds = Math.max(0, Math.ceil((Number(ms || 0) || 0) / 1000));
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function getSketchoffDraftKey(gameData = activeChessGameData, seatColor = '') {
    const gameId = Math.max(0, Number(gameData && gameData.game && gameData.game.id || 0) || 0);
    const color = String(seatColor || '').trim().toLowerCase();
    if (!gameId || (color !== 'w' && color !== 'b')) {
        return '';
    }
    return `${gameId}:${color}`;
}

function getStoredSketchoffDraft(gameData = activeChessGameData, seatColor = '') {
    const key = getSketchoffDraftKey(gameData, seatColor);
    return key ? String(activeSketchoffDrafts[key] || '') : '';
}

function rememberSketchoffDraft(gameData = activeChessGameData, seatColor = '', dataUrl = '') {
    const key = getSketchoffDraftKey(gameData, seatColor);
    if (!key) {
        return;
    }
    const normalizedDataUrl = String(dataUrl || '').trim();
    if (!normalizedDataUrl) {
        delete activeSketchoffDrafts[key];
        return;
    }
    activeSketchoffDrafts[key] = normalizedDataUrl;
}

function clearStoredSketchoffDraft(gameData = activeChessGameData, seatColor = '') {
    rememberSketchoffDraft(gameData, seatColor, '');
}

function canvasHasVisibleInk(canvas) {
    if (!canvas) {
        return false;
    }
    const context = canvas.getContext('2d', { willReadFrequently: true });
    if (!context) {
        return false;
    }
    const sample = context.getImageData(0, 0, canvas.width, canvas.height).data;
    for (let index = 0; index < sample.length; index += 16) {
        const alpha = sample[index + 3];
        if (!alpha) {
            continue;
        }
        const luma = ((sample[index] * 299) + (sample[index + 1] * 587) + (sample[index + 2] * 114)) / 1000;
        if (luma < 245) {
            return true;
        }
    }
    return false;
}

function drawSketchoffDraftImage(canvas, dataUrl) {
    if (!canvas || !dataUrl) {
        return;
    }
    const context = canvas.getContext('2d');
    if (!context) {
        return;
    }
    const image = new Image();
    image.onload = () => {
        context.clearRect(0, 0, canvas.width, canvas.height);
        context.fillStyle = '#ffffff';
        context.fillRect(0, 0, canvas.width, canvas.height);
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
    };
    image.src = dataUrl;
}

async function submitSketchoffDrawing(dataUrl) {
    if (!activeChessGameId || !activeChessGameData || !isSketchoffSidequest(activeChessGameData) || activeChessIsSubmittingMove) {
        return;
    }

    const viewerColor = getChessViewerColor(activeChessGameData);
    if (viewerColor !== 'w' && viewerColor !== 'b') {
        showToast('Only players can submit a sketch.', 'error');
        return;
    }

    const normalizedDataUrl = String(dataUrl || '').trim();
    if (!normalizedDataUrl) {
        showToast('Draw something first before you submit.', 'error');
        return;
    }

    activeChessIsSubmittingMove = true;
    activeSketchoffIsDrawing = false;
    renderChessGameModal();

    try {
        const response = await fetch('submit_sketchoff_drawing.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_id: activeChessGameId,
                token: getChessSessionToken(),
                image_data: normalizedDataUrl
            })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.success || !data.data) {
            throw new Error(data.error || 'Could not submit the sketch.');
        }

        clearStoredSketchoffDraft(activeChessGameData, viewerColor);
        setActiveChessGameData(data.data);
        renderChessGameModal(data.data);
        await refreshVisibleGameCards(data.data.game.id, data.data);
    } catch (error) {
        showToast(error.message || 'Could not submit the sketch.', 'error');
    } finally {
        activeChessIsSubmittingMove = false;
        renderChessGameModal();
    }
}

function refreshSketchoffLiveUi() {
    const elements = getChessModalElements();
    if (!activeChessGameData || !isSketchoffSidequest(activeChessGameData)) {
        return;
    }

    const remainingMs = getSketchoffTimeRemainingMs(activeChessGameData);
    document.querySelectorAll('[data-sketchoff-countdown]').forEach(node => {
        node.textContent = formatSketchoffCountdown(remainingMs);
        const countdownChip = node.closest('.sketchoff-countdown');
        if (countdownChip) {
            countdownChip.classList.toggle('is-low', remainingMs > 0 && remainingMs <= 30000);
        }
    });

    if (elements.status) {
        elements.status.textContent = buildChessInviteSubtitle(activeChessGameData);
    }
    if (elements.turnLabel) {
        elements.turnLabel.textContent = buildChessTurnLabel(activeChessGameData);
    }
    if (elements.result) {
        elements.result.textContent = activeChessGameData.game.status === 'completed'
            ? [
                getLocalizedSidequestResultSummary(activeChessGameData, activeChessGameData.game.result_summary_label || 'Round finished.'),
                getLocalizedSidequestResultDetail(activeChessGameData, activeChessGameData.game.result_reason_label || '')
            ]
                .filter(Boolean)
                .join(' · ')
            : `Prompt reveal in ${formatSketchoffCountdown(remainingMs)}.`;
    }

    if (remainingMs <= 0 && activeChessGameId && !activeChessIsSubmittingMove && !activeSketchoffIsDrawing && !activeSketchoffColorPickerOpen) {
        loadChessGame(activeChessGameId, { silent: true }).catch(() => {});
    }
}

function renderSketchoffMoveLog(gameData) {
    const elements = getChessModalElements();
    if (!elements.moveLog) {
        return;
    }

    const titleNode = document.querySelector('.chess-move-log-title');
    if (titleNode) {
        titleNode.textContent = 'Round';
    }

    const state = getSketchoffState(gameData);
    const game = gameData && gameData.game ? gameData.game : {};
    const prompt = getSketchoffPrompt(gameData) || 'mystery prompt';
    const remainingMs = getSketchoffTimeRemainingMs(gameData);
    const whiteSubmission = getSketchoffSubmissionForColor(gameData, 'w');
    const blackSubmission = getSketchoffSubmissionForColor(gameData, 'b');
    const whiteLabel = getSidequestSeatDisplayName(gameData, 'w', { preferYou: true, fallbackToColor: false }) || 'Player 1';
    const blackLabel = getSidequestSeatDisplayName(gameData, 'b', { preferYou: true, fallbackToColor: false }) || 'Player 2';

    elements.moveLog.innerHTML = '';

    const rows = [
        { label: 'Prompt', value: game.status === 'waiting' ? 'Locks in when the round starts' : prompt },
        { label: 'Timer', value: game.status === 'waiting' ? 'Starts on join' : (game.status === 'completed' ? 'Round closed' : formatSketchoffCountdown(remainingMs) + ' left') },
        { label: whiteLabel, value: game.status === 'completed'
            ? `${whiteSubmission ? 'Submitted' : 'No sketch'}${getSketchoffScoreForColor(gameData, 'w') !== null ? ` · ${getSketchoffScoreForColor(gameData, 'w')}%` : ''}`
            : (whiteSubmission ? 'Sketch submitted' : 'Still drawing') },
        { label: blackLabel, value: game.status === 'completed'
            ? `${blackSubmission ? 'Submitted' : 'No sketch'}${getSketchoffScoreForColor(gameData, 'b') !== null ? ` · ${getSketchoffScoreForColor(gameData, 'b')}%` : ''}`
            : (blackSubmission ? 'Sketch submitted' : 'Still drawing') }
    ];

    rows.forEach(entry => {
        const row = document.createElement('div');
        row.className = 'chess-move-row';
        const label = document.createElement('div');
        label.className = 'chess-move-number';
        label.textContent = entry.label;
        const value = document.createElement('div');
        value.className = 'chess-move-cell';
        value.style.gridColumn = 'span 2';
        value.textContent = entry.value;
        row.appendChild(label);
        row.appendChild(value);
        elements.moveLog.appendChild(row);
    });

    if (game.status === 'completed' && state && state.referenceImage && state.referenceImage.url) {
        const downloadRow = document.createElement('div');
        downloadRow.className = 'chess-move-row';
        const label = document.createElement('div');
        label.className = 'chess-move-number';
        label.textContent = 'AI';
        const value = document.createElement('a');
        value.className = 'chess-move-cell is-latest';
        value.style.gridColumn = 'span 2';
        value.href = state.referenceImage.url;
        value.target = '_blank';
        value.rel = 'noopener';
        value.textContent = 'Open reference sketch';
        downloadRow.appendChild(label);
        downloadRow.appendChild(value);
        elements.moveLog.appendChild(downloadRow);
    }
}

function renderSketchoffBoard(gameData = activeChessGameData) {
    const elements = getChessModalElements();
    if (!elements.board) {
        return;
    }

    const game = gameData && gameData.game ? gameData.game : {};
    const state = getSketchoffState(gameData);
    const viewerColor = getChessViewerColor(gameData);
    const viewerSubmission = getSketchoffSubmissionForColor(gameData, viewerColor);
    const canSubmitDrawing = !!(gameData && gameData.viewer && gameData.viewer.can_submit_drawing);
    const remainingMs = getSketchoffTimeRemainingMs(gameData);
    const prompt = getSketchoffPrompt(gameData) || 'mystery prompt';
    const brushColorValue = /^#[0-9a-f]{6}$/i.test(String(activeSketchoffBrushColor || '').trim())
        ? String(activeSketchoffBrushColor).trim()
        : '#111827';
    const brushSizeValue = Math.max(2, Math.min(22, Number(activeSketchoffBrushSize || 6) || 6));

    elements.board.style.gridTemplateColumns = 'minmax(0, 1fr)';
    elements.board.style.gridTemplateRows = 'auto';
    elements.board.style.aspectRatio = 'auto';
    elements.board.innerHTML = '';

    const shell = document.createElement('div');
    shell.className = 'sketchoff-shell';

    const hero = document.createElement('section');
    hero.className = 'sketchoff-hero';
    hero.innerHTML = `
        <p class="sketchoff-kicker">Sketchoff Prompt</p>
        <h3 class="sketchoff-prompt">${game.status === 'waiting' ? 'Prompt locks when the round starts' : prompt}</h3>
        <p class="sketchoff-subcopy">${game.status === 'completed'
            ? 'The round is over. Compare both sketches to the AI reference below.'
            : 'You both get the same prompt and three minutes to sketch it before the AI comparison reveal.'}</p>
    `;
    shell.appendChild(hero);

    if (game.status === 'waiting') {
        const waitingCard = document.createElement('section');
        waitingCard.className = 'sketchoff-status-card';
        waitingCard.innerHTML = `
            <p class="sketchoff-status-title">Waiting for the second player</p>
            <p class="sketchoff-status-copy">Once both seats are filled, QuillTalk will lock a prompt and start the three-minute sketch timer for everyone at the same time.</p>
        `;
        shell.appendChild(waitingCard);
        elements.board.appendChild(shell);
        return;
    }

    if (game.status === 'completed') {
        const results = document.createElement('section');
        results.className = 'sketchoff-results-grid';

        const viewerResultSeat = viewerColor === 'w' || viewerColor === 'b' ? viewerColor : 'w';
        const otherResultSeat = viewerResultSeat === 'b' ? 'w' : 'b';
        const viewerSeatName = getSidequestSeatDisplayName(gameData, viewerResultSeat, { preferYou: true, fallbackToColor: false }) || 'Player 1';
        const otherSeatName = getSidequestSeatDisplayName(gameData, otherResultSeat, { preferYou: true, fallbackToColor: false }) || 'Player 2';
        const cards = viewerColor === 'w' || viewerColor === 'b'
            ? [
                {
                    seatColor: viewerResultSeat,
                    title: viewerSeatName,
                    score: getSketchoffScoreForColor(gameData, viewerResultSeat),
                    image: getSketchoffSubmissionForColor(gameData, viewerResultSeat),
                    winner: state && state.winnerColor === viewerResultSeat,
                    metaText: state && state.winnerColor === viewerResultSeat
                        ? 'Best match for this round.'
                        : (viewerSeatName === 'You' ? 'Your final sketch for this round.' : `${viewerSeatName}'s final sketch for this round.`)
                },
                {
                    seatColor: 'ref',
                    title: 'AI drawing',
                    score: null,
                    image: state ? state.referenceImage : null,
                    winner: false,
                    isReference: true,
                    metaText: 'The AI reference sketch used for the final match score.'
                },
                {
                    seatColor: otherResultSeat,
                    title: otherSeatName,
                    score: getSketchoffScoreForColor(gameData, otherResultSeat),
                    image: getSketchoffSubmissionForColor(gameData, otherResultSeat),
                    winner: state && state.winnerColor === otherResultSeat,
                    metaText: state && state.winnerColor === otherResultSeat
                        ? 'Best match for this round.'
                        : `${otherSeatName}'s final sketch for this round.`
                }
            ]
            : [
                {
                    seatColor: 'w',
                    title: getSidequestSeatDisplayName(gameData, 'w', { preferYou: true, fallbackToColor: false }) || 'Player 1',
                    score: getSketchoffScoreForColor(gameData, 'w'),
                    image: getSketchoffSubmissionForColor(gameData, 'w'),
                    winner: state && state.winnerColor === 'w',
                    metaText: state && state.winnerColor === 'w'
                        ? 'Best match for this round.'
                        : 'Final sketch for this round.'
                },
                {
                    seatColor: 'ref',
                    title: 'AI drawing',
                    score: null,
                    image: state ? state.referenceImage : null,
                    winner: false,
                    isReference: true,
                    metaText: 'The AI reference sketch used for the final match score.'
                },
                {
                    seatColor: 'b',
                    title: getSidequestSeatDisplayName(gameData, 'b', { preferYou: true, fallbackToColor: false }) || 'Player 2',
                    score: getSketchoffScoreForColor(gameData, 'b'),
                    image: getSketchoffSubmissionForColor(gameData, 'b'),
                    winner: state && state.winnerColor === 'b',
                    metaText: state && state.winnerColor === 'b'
                        ? 'Best match for this round.'
                        : 'Final sketch for this round.'
                }
            ];

        cards.forEach(cardMeta => {
            const card = document.createElement('article');
            card.className = `sketchoff-result-card${cardMeta.isReference ? ' is-reference' : ''}${cardMeta.winner ? ' is-winner' : ''}`;

            const top = document.createElement('div');
            top.className = 'sketchoff-result-top';
            const name = document.createElement('div');
            name.className = 'sketchoff-result-name';
            name.textContent = cardMeta.title;
            const badge = document.createElement('div');
            badge.className = 'sketchoff-result-badge';
            badge.textContent = cardMeta.isReference
                ? 'Reference'
                : (cardMeta.score !== null ? `${Math.round(cardMeta.score)}%` : 'No score');
            top.appendChild(name);
            top.appendChild(badge);
            card.appendChild(top);

            if (cardMeta.image && cardMeta.image.url) {
                const link = document.createElement('a');
                link.href = cardMeta.image.url;
                link.target = '_blank';
                link.rel = 'noopener';
                const image = document.createElement('img');
                image.className = 'sketchoff-result-preview';
                image.src = cardMeta.image.url;
                image.alt = cardMeta.title;
                link.appendChild(image);
                card.appendChild(link);
            } else {
                const empty = document.createElement('div');
                empty.className = 'sketchoff-result-preview';
                empty.style.display = 'flex';
                empty.style.alignItems = 'center';
                empty.style.justifyContent = 'center';
                empty.style.color = 'var(--text-secondary)';
                empty.textContent = cardMeta.isReference ? 'Missing reference' : 'No sketch submitted';
                card.appendChild(empty);
            }

            const meta = document.createElement('div');
            meta.className = 'sketchoff-result-meta';
            meta.textContent = cardMeta.metaText || (cardMeta.isReference
                ? 'The AI reference sketch used for the final match score.'
                : (cardMeta.winner ? 'Best match for this round.' : 'Compared against the same AI sketch prompt.'));
            card.appendChild(meta);
            results.appendChild(card);
        });

        shell.appendChild(results);
        elements.board.appendChild(shell);
        return;
    }

    if (canSubmitDrawing && (viewerColor === 'w' || viewerColor === 'b') && !viewerSubmission) {
        const canvasCard = document.createElement('section');
        canvasCard.className = 'sketchoff-canvas-card';
        canvasCard.innerHTML = `
            <div class="sketchoff-toolbar">
                <div class="sketchoff-toolbar-left">
                    <div class="sketchoff-countdown${remainingMs > 0 && remainingMs <= 30000 ? ' is-low' : ''}">
                        <i class="fa-regular fa-clock" aria-hidden="true"></i>
                        <span data-sketchoff-countdown>${formatSketchoffCountdown(remainingMs)}</span>
                    </div>
                </div>
                <div class="sketchoff-toolbar-right">
                    <label class="sketchoff-color-control">
                        <span class="sr-only">Brush color</span>
                        <input type="color" class="sketchoff-color" value="${brushColorValue}" aria-label="Brush color" />
                    </label>
                    <label>
                        <span class="sr-only">Brush size</span>
                        <input type="range" class="sketchoff-brush" min="2" max="22" value="${brushSizeValue}" step="1" />
                    </label>
                    <button type="button" class="settings-action-btn secondary" data-sketchoff-clear>Clear</button>
                    <button type="button" class="settings-action-btn" data-sketchoff-submit>${activeChessIsSubmittingMove ? 'Submitting...' : 'Submit sketch'}</button>
                </div>
            </div>
            <div class="sketchoff-canvas-frame">
                <canvas class="sketchoff-canvas" width="1024" height="1024" aria-label="Sketchoff drawing surface"></canvas>
            </div>
            <p class="sketchoff-submission-note">Draw with any color you want. Once you submit, your sketch locks in for the round.</p>
        `;
        shell.appendChild(canvasCard);
        elements.board.appendChild(shell);

        const canvas = canvasCard.querySelector('canvas');
        const brush = canvasCard.querySelector('.sketchoff-brush');
        const colorInput = canvasCard.querySelector('.sketchoff-color');
        const clearBtn = canvasCard.querySelector('[data-sketchoff-clear]');
        const submitBtn = canvasCard.querySelector('[data-sketchoff-submit]');
        if (!canvas || !brush || !colorInput || !clearBtn || !submitBtn) {
            return;
        }

        const context = canvas.getContext('2d');
        if (!context) {
            return;
        }

        context.fillStyle = '#ffffff';
        context.fillRect(0, 0, canvas.width, canvas.height);
        context.lineCap = 'round';
        context.lineJoin = 'round';
        context.strokeStyle = brushColorValue;
        context.lineWidth = brushSizeValue;

        const savedDraft = getStoredSketchoffDraft(gameData, viewerColor);
        if (savedDraft) {
            drawSketchoffDraftImage(canvas, savedDraft);
        }

        let pointerActive = false;
        let lastPoint = null;

        const getCanvasPoint = event => {
            const rect = canvas.getBoundingClientRect();
            const ratioX = canvas.width / Math.max(rect.width, 1);
            const ratioY = canvas.height / Math.max(rect.height, 1);
            return {
                x: (event.clientX - rect.left) * ratioX,
                y: (event.clientY - rect.top) * ratioY
            };
        };

        const persistDraft = () => {
            rememberSketchoffDraft(gameData, viewerColor, canvas.toDataURL('image/png'));
        };

        const stopDrawing = () => {
            if (!pointerActive) {
                return;
            }
            pointerActive = false;
            activeSketchoffIsDrawing = false;
            lastPoint = null;
            persistDraft();
        };

        const beginPathAt = point => {
            context.beginPath();
            context.moveTo(point.x, point.y);
            context.lineTo(point.x + 0.01, point.y + 0.01);
            context.stroke();
        };

        canvas.addEventListener('pointerdown', event => {
            if (activeChessIsSubmittingMove) {
                return;
            }
            event.preventDefault();
            pointerActive = true;
            activeSketchoffIsDrawing = true;
            canvas.setPointerCapture(event.pointerId);
            lastPoint = getCanvasPoint(event);
            beginPathAt(lastPoint);
        });

        canvas.addEventListener('pointermove', event => {
            if (!pointerActive || !lastPoint) {
                return;
            }
            event.preventDefault();
            const nextPoint = getCanvasPoint(event);
            context.beginPath();
            context.moveTo(lastPoint.x, lastPoint.y);
            context.lineTo(nextPoint.x, nextPoint.y);
            context.stroke();
            lastPoint = nextPoint;
        });

        ['pointerup', 'pointercancel', 'pointerleave'].forEach(eventName => {
            canvas.addEventListener(eventName, stopDrawing);
        });

        brush.addEventListener('input', () => {
            activeSketchoffBrushSize = Math.max(2, Number(brush.value || 6) || 6);
            context.lineWidth = activeSketchoffBrushSize;
        });

        const markColorPickerOpen = () => {
            activeSketchoffColorPickerOpen = true;
        };
        const markColorPickerClosed = () => {
            activeSketchoffColorPickerOpen = false;
        };
        ['focus', 'click', 'pointerdown'].forEach(eventName => {
            colorInput.addEventListener(eventName, markColorPickerOpen);
        });
        colorInput.addEventListener('input', () => {
            activeSketchoffBrushColor = String(colorInput.value || '#111827');
            context.strokeStyle = activeSketchoffBrushColor;
            activeSketchoffColorPickerOpen = true;
        });
        colorInput.addEventListener('change', () => {
            activeSketchoffBrushColor = String(colorInput.value || '#111827');
            context.strokeStyle = activeSketchoffBrushColor;
            window.setTimeout(markColorPickerClosed, 0);
        });
        colorInput.addEventListener('blur', markColorPickerClosed);

        clearBtn.addEventListener('click', () => {
            context.clearRect(0, 0, canvas.width, canvas.height);
            context.fillStyle = '#ffffff';
            context.fillRect(0, 0, canvas.width, canvas.height);
            clearStoredSketchoffDraft(gameData, viewerColor);
        });

        submitBtn.addEventListener('click', async () => {
            stopDrawing();
            if (!canvasHasVisibleInk(canvas)) {
                showToast('Add a sketch before you submit it.', 'error');
                return;
            }
            await submitSketchoffDrawing(canvas.toDataURL('image/png'));
        });
        return;
    }

    const statusCard = document.createElement('section');
    statusCard.className = 'sketchoff-status-card';
    statusCard.innerHTML = `
        <p class="sketchoff-status-title">${viewerSubmission ? 'Sketch submitted' : 'Round in progress'}</p>
        <p class="sketchoff-status-copy">${viewerSubmission
            ? `Your sketch is locked in. Waiting for the other side while the timer runs down. ${formatSketchoffCountdown(remainingMs)} left.`
            : `You can watch this round live. The shared reveal happens once both drawings are in or the timer reaches zero.`}</p>
    `;
    shell.appendChild(statusCard);
    elements.board.appendChild(shell);
}

function renderChessMoveLog(gameData) {
    if (isSketchoffSidequest(gameData)) {
        renderSketchoffMoveLog(gameData);
        return;
    }

    const elements = getChessModalElements();
    if (!elements.moveLog) {
        return;
    }

    const titleNode = document.querySelector('.chess-move-log-title');
    if (titleNode) {
        titleNode.textContent = 'Moves';
    }

    elements.moveLog.innerHTML = '';
    const moves = Array.isArray(gameData && gameData.moves) ? gameData.moves : [];
    if (!moves.length) {
        const empty = document.createElement('div');
        empty.className = 'chess-move-log-empty';
        empty.textContent = 'No moves yet. White opens the game.';
        elements.moveLog.appendChild(empty);
        return;
    }

    for (let index = 0; index < moves.length; index += 2) {
        const row = document.createElement('div');
        row.className = 'chess-move-row';

        const number = document.createElement('div');
        number.className = 'chess-move-number';
        number.textContent = `${Math.floor(index / 2) + 1}.`;

        const whiteMove = moves[index];
        const blackMove = moves[index + 1];
        const whiteCell = document.createElement('div');
        whiteCell.className = 'chess-move-cell';
        whiteCell.textContent = whiteMove && (whiteMove.notation || whiteMove.uci) ? (whiteMove.notation || whiteMove.uci) : '-';
        if (index === moves.length - 1) {
            whiteCell.classList.add('is-latest');
        }

        const blackCell = document.createElement('div');
        blackCell.className = 'chess-move-cell';
        blackCell.textContent = blackMove && (blackMove.notation || blackMove.uci) ? (blackMove.notation || blackMove.uci) : '-';
        if (index + 1 === moves.length - 1) {
            blackCell.classList.add('is-latest');
        }

        row.appendChild(number);
        row.appendChild(whiteCell);
        row.appendChild(blackCell);
        elements.moveLog.appendChild(row);
    }
}

function renderChessChatLog(gameData) {
    const elements = getChessModalElements();
    if (!elements.chatLog) {
        return;
    }

    const messages = Array.isArray(gameData && gameData.chat_messages) ? gameData.chat_messages : [];
    const shouldScrollToBottom = messages.length !== activeChessLastChatMessageCount;
    activeChessLastChatMessageCount = messages.length;
    elements.chatLog.innerHTML = '';

    if (!messages.length) {
        const empty = document.createElement('div');
        empty.className = 'chess-chat-empty';
        empty.textContent = 'No table talk yet. Send a quick message to your opponent here.';
        elements.chatLog.appendChild(empty);
        return;
    }

    messages.forEach(message => {
        const isBot = !!message.is_bot;
        const isSelf = !isBot && Math.max(0, Number(message.user_id || 0) || 0) === getChessCurrentUserId();
        const row = document.createElement('div');
        row.className = `chess-chat-message${isSelf ? ' self' : ''}${isBot ? ' bot' : ''}`;

        if (!isSelf) {
            const avatar = document.createElement('img');
            avatar.className = 'chess-chat-avatar';
            avatar.src = normalizeChessProfilePic(String(message.profile_pic || getChessDefaultProfilePic()), 'direct');
            avatar.alt = String(message.display_name || (isBot ? 'QuillTalk AI' : 'Player'));
            row.appendChild(avatar);
        }

        const bubble = document.createElement('div');
        bubble.className = 'chess-chat-bubble';

        const author = document.createElement('div');
        author.className = 'chess-chat-author';
        author.textContent = isSelf ? 'You' : String(message.display_name || (isBot ? 'QuillTalk AI' : 'Player'));

        const text = document.createElement('div');
        text.className = 'chess-chat-text';
        text.textContent = String(message.message || '');

        bubble.appendChild(author);
        bubble.appendChild(text);
        row.appendChild(bubble);
        elements.chatLog.appendChild(row);
    });

    if (shouldScrollToBottom) {
        elements.chatLog.scrollTop = elements.chatLog.scrollHeight;
    }
}

function buildChessTurnLabel(gameData) {
    const state = getNormalizedSidequestState(gameData);
    if (!state || !gameData || !gameData.game) {
        return 'Loading board...';
    }

    if (gameData.game.status === 'waiting') {
        return 'Waiting for the second player to join.';
    }

    if (gameData.game.status === 'completed') {
        return getLocalizedSidequestResultSummary(gameData, gameData.game.result_summary_label || gameData.game.result_label || 'Game finished.');
    }

    if (isSketchoffSidequest(gameData)) {
        const viewerColor = getChessViewerColor(gameData);
        const viewerSubmission = getSketchoffSubmissionForColor(gameData, viewerColor);
        if (viewerColor !== 'w' && viewerColor !== 'b') {
            return `Both players are sketching "${getSketchoffPrompt(gameData) || 'the prompt'}" right now.`;
        }
        return viewerSubmission
            ? `Your sketch is in. Waiting for the reveal with ${formatSketchoffCountdown(getSketchoffTimeRemainingMs(gameData))} left.`
            : `Sketch "${getSketchoffPrompt(gameData)}" before the timer runs out.`;
    }

    const turnColor = state.turn === 'b' ? 'b' : 'w';
    const turnPlayer = turnColor === 'w' ? gameData.players.white : gameData.players.black;
    const turnName = turnPlayer && turnPlayer.display_name
        ? turnPlayer.display_name
        : (turnColor === 'w' ? 'White' : 'Black');
    const prefix = `${turnName} to move.`;
    return isChessSidequest(gameData) && state.checkColor === turnColor ? `${prefix} Check.` : prefix;
}

function renderChessBoard(gameData = activeChessGameData) {
    const elements = getChessModalElements();
    const engine = getSidequestEngine(gameData);
    if (!elements.board || !engine || !activeChessBoardState) {
        return;
    }

    if (isSketchoffSidequest(gameData)) {
        renderSketchoffBoard(gameData);
        return;
    }

    const viewerColor = getChessViewerColor(gameData);
    const orientationColor = getChessBoardOrientationColor(gameData);
    const boardDimensions = engine && typeof engine.getBoardDimensions === 'function'
        ? engine.getBoardDimensions()
        : { rows: 8, cols: 8 };
    const boardRows = Math.max(1, Number(boardDimensions && boardDimensions.rows ? boardDimensions.rows : 8) || 8);
    const boardCols = Math.max(1, Number(boardDimensions && boardDimensions.cols ? boardDimensions.cols : 8) || 8);
    const rowIndexes = Array.from({ length: boardRows }, (_, index) => index);
    const colIndexes = Array.from({ length: boardCols }, (_, index) => index);
    const rowOrder = orientationColor === 'b' ? rowIndexes.slice().reverse() : rowIndexes;
    const colOrder = orientationColor === 'b' ? colIndexes.slice().reverse() : colIndexes;
    const isInteractiveTurn = gameData
        && gameData.game
        && gameData.game.status === 'active'
        && viewerColor
        && activeChessBoardState.turn === viewerColor
        && !activeChessIsSubmittingMove
        && !activeChessIsProcessingBotTurn;
    const lastMove = activeChessBoardState.lastMove || null;

    elements.board.setAttribute('aria-label', `${getSidequestLabel(gameData)} board`);
    elements.board.style.gridTemplateColumns = `repeat(${boardCols}, minmax(0, 1fr))`;
    elements.board.style.gridTemplateRows = `repeat(${boardRows}, minmax(0, 1fr))`;
    elements.board.style.aspectRatio = `${boardCols} / ${boardRows}`;
    elements.board.innerHTML = '';

    rowOrder.forEach((row, renderedRowIndex) => {
        colOrder.forEach((col, renderedColIndex) => {
            const square = engine.coordsToSquare(row, col);
            const piece = activeChessBoardState.board[row][col];
            const button = document.createElement('button');
            button.type = 'button';
            button.className = `chess-square ${((row + col) % 2 === 0) ? 'light' : 'dark'}`;
            button.dataset.square = square;
            button.disabled = !isInteractiveTurn;
            button.setAttribute('aria-label', `${getSidequestLabel(gameData)} square ${square}`);

            if (lastMove && (lastMove.from === square || lastMove.to === square)) {
                button.classList.add('is-last-move');
            }
            if (activeChessSelectedSquare === square) {
                button.classList.add('is-selected');
            }
            const passiveLegalMove = !activeChessSelectedSquare
                && isConnectFourSidequest(gameData)
                && typeof engine.getLegalMovesForSquare === 'function'
                ? (engine.getLegalMovesForSquare(activeChessBoardState, square) || [])[0]
                : null;
            const legalMove = activeChessLegalMoves.find(move => move.to === square) || passiveLegalMove;
            if (legalMove) {
                button.classList.add('is-legal');
                if (legalMove.capture) {
                    button.classList.add('is-capture');
                }
            }

            if (piece) {
                const pieceEl = document.createElement('span');
                pieceEl.className = `chess-piece ${piece.charAt(0) === 'w' ? 'white' : 'black'}${piece.charAt(1) === 'k' ? ' is-king' : ''}`;
                pieceEl.textContent = engine.getPieceGlyph(piece);
                button.appendChild(pieceEl);
            }

            if (renderedRowIndex === rowOrder.length - 1) {
                const fileLabel = document.createElement('span');
                fileLabel.className = 'chess-square-label';
                fileLabel.textContent = square.charAt(0);
                button.appendChild(fileLabel);
            }

            if (renderedColIndex === 0) {
                const rankLabel = document.createElement('span');
                rankLabel.className = 'chess-square-rank';
                rankLabel.textContent = square.charAt(1);
                button.appendChild(rankLabel);
            }

            button.addEventListener('click', () => {
                handleChessSquareSelection(square);
            });
            elements.board.appendChild(button);
        });
    });
}

function renderChessGameModal(gameData = activeChessGameData) {
    const elements = getChessModalElements();
    if (!elements.modal || !gameData) {
        return;
    }

    const gameLabel = getSidequestLabel(gameData);
    const isChessGame = isChessSidequest(gameData);
    const isSketchGame = isSketchoffSidequest(gameData);
    const boardColumn = elements.board ? elements.board.closest('.chess-game-board-column') : null;
    const boardShell = elements.board ? elements.board.closest('.chess-board-shell') : null;

    elements.modal.classList.toggle('is-sketchoff-layout', isSketchGame);
    if (elements.body) {
        elements.body.classList.toggle('is-sketchoff-layout', isSketchGame);
    }
    if (elements.layout) {
        elements.layout.classList.toggle('is-sketchoff-layout', isSketchGame);
    }
    if (boardColumn) {
        boardColumn.classList.toggle('is-sketchoff-layout', isSketchGame);
    }
    if (boardShell) {
        boardShell.classList.toggle('is-sketchoff-shell', isSketchGame);
    }
    if (elements.board) {
        elements.board.classList.toggle('is-sketchoff-board', isSketchGame);
    }
    if (elements.conversationColumn) {
        elements.conversationColumn.classList.toggle('is-sketchoff-layout', isSketchGame);
    }

    if (elements.title) {
        elements.title.textContent = gameLabel;
    }
    if (elements.subtitle) {
        elements.subtitle.textContent = isSketchGame
            ? 'Sketch the same prompt at the same time, then compare both drawings against a free AI reference reveal.'
            : isChessGame
            ? 'Take turns on an in-chat board that keeps the full flow of play together.'
            : (isConnectFourSidequest(gameData)
                ? 'Stack discs, trap columns, and race to four in a row without leaving the QuillTalk conversation.'
                : 'Jump, capture, and crown kings without leaving the QuillTalk conversation.');
    }

    if (elements.status) {
        elements.status.textContent = buildChessInviteSubtitle(gameData);
    }
    if (elements.turnLabel) {
        elements.turnLabel.textContent = buildChessTurnLabel(gameData);
    }
    if (elements.result) {
        elements.result.textContent = gameData.game.status === 'completed'
            ? [
                getLocalizedSidequestResultSummary(gameData, gameData.game.result_summary_label || 'Game finished.'),
                getLocalizedSidequestResultDetail(gameData, gameData.game.result_reason_label || gameData.game.result_label || '')
            ]
                .filter(Boolean)
                .join(' · ')
            : (isSketchGame
                ? (gameData.game.status === 'waiting'
                    ? 'Prompt locks in when the second player joins.'
                    : `Prompt reveal in ${formatSketchoffCountdown(getSketchoffTimeRemainingMs(gameData))}.`)
                : `Playing ${gameData.game.label} in ${gameData.game.family_label}. ${formatChessTimeControlLabel(gameData.game.time_control_seconds)} per player.`);
    }
    if (elements.promotionPrompt && !isChessGame) {
        elements.promotionPrompt.hidden = true;
    }

    syncChessPlayerStripOrder(gameData);
    renderChessPlayerStrip(elements.whitePlayer, gameData, 'w');
    renderChessPlayerStrip(elements.blackPlayer, gameData, 'b');
    renderChessBoard(gameData);
    renderChessMoveLog(gameData);
    renderChessChatLog(gameData);

    if (elements.primaryBtn) {
        elements.primaryBtn.hidden = !(gameData.viewer && gameData.viewer.can_join);
        elements.primaryBtn.disabled = activeChessIsSubmittingMove || activeChessIsProcessingBotTurn;
        elements.primaryBtn.textContent = activeChessIsSubmittingMove
            ? 'Joining...'
            : (isSketchGame ? 'Join round' : `Join ${gameLabel}`);
    }
    if (elements.secondaryBtn) {
        elements.secondaryBtn.disabled = activeChessIsSubmittingMove;
        elements.secondaryBtn.textContent = activeChessIsSubmittingMove ? 'Working...' : 'Close';
    }
    if (elements.resignBtn) {
        const canResign = !!(gameData.viewer && gameData.viewer.can_resign);
        elements.resignBtn.hidden = !canResign;
        elements.resignBtn.disabled = !canResign || activeChessIsSubmittingMove;
    }
    if (elements.chatInput) {
        const canChat = !!(gameData.viewer && gameData.viewer.can_chat);
        elements.chatInput.disabled = !canChat || activeChessChatSubmitting || activeChessIsProcessingBotTurn;
        elements.chatInput.placeholder = canChat ? 'Message your opponent' : 'Only players can chat here';
    }
    if (elements.chatSendBtn) {
        const canChat = !!(gameData.viewer && gameData.viewer.can_chat);
        elements.chatSendBtn.disabled = !canChat || activeChessChatSubmitting || activeChessIsProcessingBotTurn;
        elements.chatSendBtn.textContent = activeChessChatSubmitting ? 'Sending...' : 'Send';
    }
}

function selectChessSquare(square) {
    const engine = getSidequestEngine(activeChessGameData);
    if (!engine || !activeChessBoardState) {
        return;
    }
    activeChessSelectedSquare = square;
    activeChessLegalMoves = engine.getLegalMovesForSquare(activeChessBoardState, square);
    renderChessBoard();
}

function clearChessSelection() {
    activeChessSelectedSquare = '';
    activeChessLegalMoves = [];
    renderChessBoard();
}

function handleChessSquareSelection(square) {
    const engine = getSidequestEngine(activeChessGameData);
    if (!engine || !activeChessBoardState || !activeChessGameData || activeChessIsSubmittingMove || activeChessIsProcessingBotTurn) {
        return;
    }

    if (!activeChessGameData.game || activeChessGameData.game.status !== 'active') {
        return;
    }

    const viewerColor = getChessViewerColor(activeChessGameData);
    if (!viewerColor || activeChessBoardState.turn !== viewerColor) {
        return;
    }

    const coords = engine.squareToCoords(square);
    if (!coords) {
        return;
    }

    if (isConnectFourSidequest(activeChessGameData)) {
        const connectFourMove = typeof engine.getLegalMovesForSquare === 'function'
            ? (engine.getLegalMovesForSquare(activeChessBoardState, square) || [])[0]
            : null;
        if (connectFourMove) {
            submitChessMove(connectFourMove.from, connectFourMove.to, '');
        }
        return;
    }

    const piece = activeChessBoardState.board[coords.row][coords.col];

    if (activeChessSelectedSquare) {
        const legalMove = activeChessLegalMoves.find(move => move.to === square);
        if (legalMove) {
            submitChessMove(activeChessSelectedSquare, square, legalMove.promotion || '');
            return;
        }

        if (piece && String(piece).charAt(0) === viewerColor) {
            selectChessSquare(square);
            return;
        }

        clearChessSelection();
        return;
    }

    if (piece && String(piece).charAt(0) === viewerColor) {
        selectChessSquare(square);
    }
}

async function loadChessGame(gameId, options = {}) {
    const gameData = await fetchGameData(gameId, options);
    if (Number(gameId || 0) !== Number(activeChessGameId || 0) && !options.allowBackground) {
        return gameData;
    }
    setActiveChessGameData(gameData, {
        preserveSelection: !!options.silent
    });
    renderChessGameModal(gameData);
    await refreshVisibleGameCards(gameData.game.id, gameData);
    maybeTriggerBotChessTurn(gameData);
    return gameData;
}

function setSidequestCatalogSubmitting(gameType = '') {
    activeSidequestCreateType = String(gameType || '').trim().toLowerCase();
    document.querySelectorAll('[data-game-start]').forEach(card => {
        const button = card;
        const buttonGameType = String(button.dataset.gameStart || '').trim().toLowerCase();
        const isSubmitting = !!activeSidequestCreateType;
        const isActiveType = isSubmitting && buttonGameType === activeSidequestCreateType;
        const badge = button.querySelector('.game-catalog-badge');

        button.disabled = isSubmitting;
        button.classList.toggle('is-loading', isActiveType);
        button.setAttribute('aria-busy', isActiveType ? 'true' : 'false');

        if (badge) {
            badge.textContent = isActiveType ? 'Starting' : 'Live';
        }
    });
}

function getSelectedSidequestChatTarget() {
    const chatTarget = getChessSelectedChatKey();
    if (!chatTarget) {
        throw new Error('Please select a chat first.');
    }
    if (chatTarget.startsWith('ai:')) {
        throw new Error('Sidequests are only available in direct and group chats.');
    }
    return chatTarget;
}

async function createSidequestGame(gameType, options = {}) {
    const normalizedGameType = String(gameType || '').trim().toLowerCase();
    const chatTarget = getSelectedSidequestChatTarget();
    const sessionToken = getChessSessionToken();
    const payloadOptions = {};
    if (
        normalizedGameType === SIDEQUEST_GAME_CHESS
        || normalizedGameType === SIDEQUEST_GAME_CHECKERS
        || normalizedGameType === SIDEQUEST_GAME_CONNECT_FOUR
    ) {
        payloadOptions.opponent_mode = options.opponentMode === 'bot' ? 'bot' : 'human';
        payloadOptions.color_choice = ['white', 'black', 'random'].includes(String(options.colorChoice || '').trim().toLowerCase())
            ? String(options.colorChoice).trim().toLowerCase()
            : 'random';
        payloadOptions.time_control_seconds = [60, 180, 300, 600, 900, 1800].includes(Number(options.timeControlSeconds || 0))
            ? Number(options.timeControlSeconds)
            : 300;
    }
    const response = await fetch(`create_game.php?token=${encodeURIComponent(sessionToken)}&_=${Date.now()}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            chat_with: chatTarget,
            game_type: normalizedGameType,
            options: payloadOptions
        })
    });
    const rawResponseText = await response.text();
    let data = {};
    if (rawResponseText) {
        try {
            data = JSON.parse(rawResponseText);
        } catch (error) {
            data = {};
        }
    }
    if (!response.ok || !data.success || !data.game_id) {
        const rawFallbackMessage = rawResponseText
            ? rawResponseText.trim().replace(/\s+/g, ' ').slice(0, 220)
            : '';
        const emptyServerFailureMessage = !rawFallbackMessage && response.status >= 500
            ? `The sidequest endpoint returned an empty HTTP ${response.status} response while creating the game.`
            : '';
        throw new Error(
            (typeof data.error === 'string' && data.error)
            || emptyServerFailureMessage
            || rawFallbackMessage
            || `Failed to start the game (HTTP ${response.status}).`
        );
    }
    return {
        chatTarget,
        gameId: Math.max(0, Number(data.game_id || 0) || 0)
    };
}

async function startSidequestGame(gameType, options = {}) {
    const normalizedGameType = String(gameType || '').trim().toLowerCase();
    if (!normalizedGameType || activeSidequestCreateType) {
        return;
    }

    setSidequestCatalogSubmitting(normalizedGameType);
    try {
        const createdGame = await createSidequestGame(normalizedGameType, options);
        if (typeof window.invalidateSidebarHistoryCache === 'function') {
            window.invalidateSidebarHistoryCache({ reloadIfVisible: true });
        }
        if (typeof window.pollMessages === 'function' && getChessSelectedChatKey() === createdGame.chatTarget) {
            try {
                await window.pollMessages(false, createdGame.chatTarget);
            } catch (error) {
                console.warn('Failed to refresh chat after starting the game.', error);
            }
        }

        if (
            normalizedGameType === SIDEQUEST_GAME_CHESS
            || normalizedGameType === SIDEQUEST_GAME_CHECKERS
            || normalizedGameType === SIDEQUEST_GAME_CONNECT_FOUR
            || normalizedGameType === SIDEQUEST_GAME_SKETCHOFF
        ) {
            const startedLabel = normalizedGameType === SIDEQUEST_GAME_CHECKERS
                ? 'Checkers'
                : (normalizedGameType === SIDEQUEST_GAME_CONNECT_FOUR
                    ? 'Connect Four'
                    : (normalizedGameType === SIDEQUEST_GAME_SKETCHOFF ? 'Sketchoff' : 'Chess'));
            await openChessGameModal(createdGame.gameId, {
                gameType: normalizedGameType,
                deferDisplayUntilReady: true,
                suppressErrorToast: true,
                rethrowOnError: true
            });
            closeChessSetupModal(true);
            closeGamesModal();
            showToast(`${startedLabel} game started.`, 'success');
            return;
        }

        closeChessSetupModal(true);
        closeGamesModal();
        showToast('Game started.', 'success');
    } finally {
        setSidequestCatalogSubmitting('');
    }
}

async function joinChessGame(gameId) {
    const sessionToken = getChessSessionToken();
    const response = await fetch('join_game.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            game_id: gameId,
            token: sessionToken
        })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.success || !data.data) {
        throw new Error(data.error || 'Failed to join the game.');
    }
    return data.data;
}

async function openChessGameModal(gameId, options = {}) {
    const elements = getChessModalElements();
    if (!elements.modal) {
        return null;
    }

    const hintedGameType = String(options.gameType || '').trim().toLowerCase();
    const hintedLabel = hintedGameType === SIDEQUEST_GAME_CHECKERS
        ? 'Checkers'
        : (hintedGameType === SIDEQUEST_GAME_CONNECT_FOUR
            ? 'Connect Four'
            : (hintedGameType === SIDEQUEST_GAME_SKETCHOFF ? 'Sketchoff' : 'Chess'));
    const deferDisplayUntilReady = !!options.deferDisplayUntilReady;

    const showLoadingState = () => {
        bringOverlayToFront(elements.modal, 6);
        elements.modal.setAttribute('aria-hidden', 'false');
        elements.modal.style.display = 'flex';
        if (elements.title) {
            elements.title.textContent = hintedLabel;
        }
        if (elements.subtitle) {
            elements.subtitle.textContent = hintedGameType === SIDEQUEST_GAME_CHECKERS
                ? 'Jump, capture, and crown kings without leaving the QuillTalk conversation.'
                : (hintedGameType === SIDEQUEST_GAME_CONNECT_FOUR
                    ? 'Drop discs, stack threats, and connect four right inside the QuillTalk conversation.'
                    : (hintedGameType === SIDEQUEST_GAME_SKETCHOFF
                        ? 'Sketch the same prompt at the same time, then compare both drawings against the free AI reference.'
                        : 'Take turns on an in-chat board that keeps the full flow of play together.'));
        }
        if (elements.status) {
            elements.status.textContent = options.join ? 'Joining game...' : 'Loading board...';
        }
    };

    activeChessGameId = Math.max(0, Number(gameId || 0) || 0);
    activeChessGameData = null;
    activeChessBoardState = null;
    activeChessSelectedSquare = '';
    activeChessLegalMoves = [];
    activeChessIsSubmittingMove = false;
    activeChessIsProcessingBotTurn = false;
    activeChessChatSubmitting = false;
    activeChessBotTurnRequestToken = 0;
    activeChessLastResultSignature = '';
    activeChessLastChatMessageCount = 0;
    clearChessBotTurnTimer();
    closeChessResultPopup();
    closeChessPromotionPrompt();

    if (!deferDisplayUntilReady) {
        showLoadingState();
    }

    try {
        const gameData = options.join
            ? await joinChessGame(activeChessGameId)
            : await fetchGameData(activeChessGameId, { silent: true });
        await prepareChessConversationDock(gameData);
        if (deferDisplayUntilReady) {
            showLoadingState();
        }
        setActiveChessGameData(gameData);
        renderChessGameModal(gameData);
        if (isSketchoffSidequest(gameData)) {
            const boardColumn = elements.board ? elements.board.closest('.chess-game-board-column') : null;
            if (elements.body) {
                elements.body.scrollTop = 0;
            }
            if (boardColumn) {
                boardColumn.scrollTop = 0;
            }
        }
        await refreshVisibleGameCards(gameData.game.id, gameData);
        scheduleChessModalPolling();
        maybeTriggerBotChessTurn(gameData);
        return gameData;
    } catch (error) {
        closeChessGameModal();
        if (!options.suppressErrorToast) {
            showToast(error.message || 'Failed to open the game.', 'error');
        }
        if (options.rethrowOnError) {
            throw error;
        }
        return null;
    }
}

async function persistChessMoveAttempt(attempt, actorRole = 'user') {
    if (!attempt || !attempt.ok || !attempt.move || !activeChessGameId) {
        return null;
    }

    const normalizedActorRole = actorRole === 'bot' ? 'bot' : 'user';
    const gameId = activeChessGameId;
    activeChessIsSubmittingMove = true;
    closeChessPromotionPrompt();
    renderChessGameModal();

    try {
        const response = await fetch('make_game_move.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_id: gameId,
                token: getChessSessionToken(),
                actor_role: normalizedActorRole,
                move: {
                    from: attempt.move.from,
                    to: attempt.move.to,
                    promotion: attempt.move.promotion || null,
                    notation: attempt.move.notation || '',
                    uci: attempt.move.uci || ''
                },
                state: attempt.state
            })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.success || !data.data) {
            throw new Error(data.error || 'Failed to save the move.');
        }

        if (gameId !== activeChessGameId) {
            return data.data;
        }
        setActiveChessGameData(data.data);
        renderChessGameModal(data.data);
        await refreshVisibleGameCards(data.data.game.id, data.data);
        maybeTriggerBotChessTurn(data.data);
        return data.data;
    } catch (error) {
        showToast(error.message || 'Failed to save the move.', 'error');
        if (gameId === activeChessGameId) {
            await loadChessGame(gameId, { silent: true }).catch(() => {});
        }
        return null;
    } finally {
        activeChessIsSubmittingMove = false;
        renderChessGameModal();
    }
}

async function submitChessMove(from, to, promotion) {
    const engine = getSidequestEngine(activeChessGameData);
    if (!engine || !activeChessBoardState || !activeChessGameId || activeChessIsSubmittingMove || activeChessIsProcessingBotTurn) {
        return;
    }

    const attempt = engine.attemptMove(activeChessBoardState, from, to, promotion);
    if (!attempt.ok) {
        if (attempt.needsPromotion) {
            pendingChessPromotionContext = { from, to };
            const elements = getChessModalElements();
            if (elements.promotionPrompt) {
                elements.promotionPrompt.hidden = false;
            }
            return;
        }
        showToast(attempt.reason || 'That move is not legal.', 'error');
        return;
    }

    await persistChessMoveAttempt(attempt, 'user');
}

async function getChessBotMoveChoice(gameId, legalMoves) {
    const response = await fetch('get_game_bot_move.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            game_id: gameId,
            token: getChessSessionToken(),
            legal_moves: legalMoves
        })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.success || !data.move) {
        throw new Error(data.error || 'QuillTalk AI could not choose a move.');
    }
    return data.move;
}

function maybeTriggerBotChessTurn(gameData = activeChessGameData) {
    clearChessBotTurnTimer();
    const elements = getChessModalElements();
    if (!elements.modal || elements.modal.getAttribute('aria-hidden') !== 'false') {
        return;
    }
    if (!gameData || !gameData.game || !gameData.viewer || !gameData.viewer.is_bot_turn || !gameData.game.bot_enabled || !getChessViewerColor(gameData)) {
        return;
    }
    if (activeChessIsSubmittingMove || activeChessIsProcessingBotTurn) {
        return;
    }

    activeChessBotTurnTimer = window.setTimeout(() => {
        requestChessBotTurn().catch(error => {
            showToast(error.message || 'QuillTalk AI could not make its move.', 'error');
        });
    }, 700);
}

async function requestChessBotTurn() {
    const engine = getSidequestEngine(activeChessGameData);
    const gameData = activeChessGameData;
    if (!engine || !gameData || !gameData.game || !gameData.viewer || !gameData.viewer.is_bot_turn || !getChessViewerColor(gameData) || activeChessIsSubmittingMove || activeChessIsProcessingBotTurn || !activeChessBoardState) {
        return;
    }

    const botColor = gameData.game.bot_color === 'b' ? 'b' : 'w';
    const legalMoves = engine.getLegalMovesForColor(activeChessBoardState, botColor);
    if (!Array.isArray(legalMoves) || !legalMoves.length) {
        return;
    }

    const gameId = activeChessGameId;
    const requestToken = activeChessBotTurnRequestToken + 1;
    activeChessBotTurnRequestToken = requestToken;
    activeChessIsProcessingBotTurn = true;
    clearChessSelection();
    renderChessGameModal();

    try {
        const chosenMove = await getChessBotMoveChoice(gameId, legalMoves);
        if (
            requestToken !== activeChessBotTurnRequestToken
            || gameId !== activeChessGameId
            || !activeChessBoardState
            || !activeChessGameData
            || !activeChessGameData.game
            || activeChessGameData.game.status !== 'active'
        ) {
            return;
        }

        const attempt = engine.attemptMove(
            activeChessBoardState,
            String(chosenMove.from || ''),
            String(chosenMove.to || ''),
            String(chosenMove.promotion || '')
        );
        if (!attempt.ok) {
            throw new Error(attempt.reason || 'The bot move was invalid.');
        }

        await persistChessMoveAttempt(attempt, 'bot');
    } catch (error) {
        if (
            requestToken === activeChessBotTurnRequestToken
            && gameId === activeChessGameId
            && activeChessGameData
            && activeChessGameData.game
            && activeChessGameData.game.status === 'active'
        ) {
            showToast(error.message || 'QuillTalk AI could not make its move.', 'error');
            await loadChessGame(gameId, { silent: true }).catch(() => {});
        }
    } finally {
        if (requestToken === activeChessBotTurnRequestToken) {
            activeChessIsProcessingBotTurn = false;
            renderChessGameModal();
        }
    }
}

async function sendChessChatMessage() {
    const elements = getChessModalElements();
    const gameData = activeChessGameData;
    if (!elements.chatInput || !gameData || !gameData.game || !gameData.viewer || !gameData.viewer.can_chat || activeChessChatSubmitting) {
        return;
    }

    const message = String(elements.chatInput.value || '').trim();
    if (!message) {
        return;
    }

    activeChessChatSubmitting = true;
    renderChessGameModal();

    try {
        const response = await fetch('send_game_chat.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_id: activeChessGameId,
                token: getChessSessionToken(),
                message
            })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.success || !data.data) {
            throw new Error(data.error || 'Failed to send the chat message.');
        }

        elements.chatInput.value = '';
        setActiveChessGameData(data.data);
        renderChessGameModal(data.data);
        maybeTriggerBotChessTurn(data.data);
    } catch (error) {
        showToast(error.message || 'Failed to send the chat message.', 'error');
    } finally {
        activeChessChatSubmitting = false;
        renderChessGameModal();
        if (elements.chatInput && activeChessGameData && activeChessGameData.viewer && activeChessGameData.viewer.can_chat) {
            elements.chatInput.focus();
        }
    }
}

async function resignChessGame() {
    if (!activeChessGameId || !activeChessGameData || !activeChessGameData.viewer || !activeChessGameData.viewer.can_resign || activeChessIsSubmittingMove) {
        return;
    }

    const gameId = activeChessGameId;
    clearChessBotTurnTimer();
    activeChessBotTurnRequestToken += 1;
    activeChessIsProcessingBotTurn = false;
    activeChessIsSubmittingMove = true;
    renderChessGameModal();

    try {
        const response = await fetch('resign_game.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_id: gameId,
                token: getChessSessionToken()
            })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.success || !data.data) {
            throw new Error(data.error || 'Failed to resign from the game.');
        }

        setActiveChessGameData(data.data);
        renderChessGameModal(data.data);
        await refreshVisibleGameCards(data.data.game.id, data.data);
    } catch (error) {
        showToast(error.message || 'Failed to resign from the game.', 'error');
        if (gameId === activeChessGameId) {
            await loadChessGame(gameId, { silent: true }).catch(() => {});
        }
    } finally {
        activeChessIsSubmittingMove = false;
        renderChessGameModal();
    }
}

// Poll Modal Management
function openPollModal() {
    const modal = document.getElementById('pollModal');
    if (!modal) return;
    
