    document.getElementById('pollEndResponses').value = '';
    document.getElementById('pollDatePickerContainer').style.display = 'none';
    document.getElementById('pollResponsesPickerContainer').style.display = 'none';
    
    // Add default 2 options
    pollOptionCounter = 2;
