    if (!modal) return;
    modal.setAttribute('aria-hidden', 'true');
    modal.style.display = 'none';
    resetOverlayZIndex(modal);
}

function buildGifFileName(title = '') {
    const normalized = String(title || '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .slice(0, 48);
    return `${normalized || 'tenor-gif'}.gif`;
}

function getTenorLocale() {
    const language = String((navigator.language || 'en-US')).replace('-', '_');
    return /^[a-z]{2}(?:_[A-Z]{2})?$/.test(language) ? language : 'en_US';
}

function getTenorMediaUrl(result, preferredFormats) {
    const formats = Array.isArray(preferredFormats) ? preferredFormats : [preferredFormats];
    for (const formatName of formats) {
        if (result && result.media_formats && result.media_formats[formatName] && result.media_formats[formatName].url) {
            return String(result.media_formats[formatName].url);
        }
        if (result && Array.isArray(result.media) && result.media[0] && result.media[0][formatName] && result.media[0][formatName].url) {
            return String(result.media[0][formatName].url);
        }
    }
    return '';
}

function normalizeTenorGifResult(result, index = 0) {
    const title = String(
        result && (
            result.content_description
            || result.title
            || result.h1_title
            || (Array.isArray(result.tags) ? result.tags[0] : '')
        )
        || `GIF ${index + 1}`
    ).trim();

    const previewUrl = getTenorMediaUrl(result, ['tinygif', 'nanogif', 'mediumgif', 'gif']);
    const sendUrl = getTenorMediaUrl(result, ['gif', 'mediumgif', 'tinygif', 'nanogif']);

    if (!previewUrl || !sendUrl) {
        return null;
    }

    return {
        id: String(result && result.id ? result.id : `${Date.now()}-${index}`),
        title,
        previewUrl,
        sendUrl,
        fileName: buildGifFileName(title)
    };
}

function getGifSelectionKey(item) {
    if (!item || typeof item !== 'object') {
        return '';
    }
    return String(item.id || item.sendUrl || item.previewUrl || '');
}

function mergeGifSelectionItems(existingItems, newItems) {
    const seenKeys = new Set();
    const mergedItems = [];

    [...(Array.isArray(existingItems) ? existingItems : []), ...(Array.isArray(newItems) ? newItems : [])].forEach(item => {
        const key = getGifSelectionKey(item);
        if (!key || seenKeys.has(key)) {
            return;
        }
        seenKeys.add(key);
        mergedItems.push(item);
    });

    return mergedItems;
}

function buildGifPickerItemFromCard(card) {
    if (!card) {
        return null;
    }

    const sendUrl = String(card.dataset.gifSendUrl || '');
    const previewUrl = String(card.dataset.gifPreviewUrl || '');
    if (!sendUrl || !previewUrl) {
        return null;
    }

    return {
        id: String(card.dataset.gifId || sendUrl),
        title: String(card.dataset.gifTitle || 'GIF'),
        previewUrl,
        sendUrl,
        fileName: String(card.dataset.gifFileName || buildGifFileName(card.dataset.gifTitle || 'GIF'))
    };
}

function isGifModalItemSelected(item) {
    const key = getGifSelectionKey(item);
    return !!key && gifModalSelectedItems.some(selectedItem => getGifSelectionKey(selectedItem) === key);
}

function syncGifCardSelectionState(card) {
    if (!card) {
        return;
    }

    const item = buildGifPickerItemFromCard(card);
    const selected = isGifModalItemSelected(item);
    const badge = card.querySelector('.gif-search-card-badge');
    const selectedIndex = selected
        ? gifModalSelectedItems.findIndex(selectedItem => getGifSelectionKey(selectedItem) === getGifSelectionKey(item))
        : -1;

    card.classList.toggle('is-selected', selected);
    card.setAttribute('aria-pressed', selected ? 'true' : 'false');
    if (badge) {
        badge.textContent = selected && selectedIndex >= 0 ? String(selectedIndex + 1) : '';
    }
}

function syncVisibleGifCardSelectionStates() {
    document.querySelectorAll('#gifSearchResults .gif-search-card').forEach(syncGifCardSelectionState);
}

function renderGifSelectionBar() {
    const selectionBar = document.getElementById('gifSelectionBar');
    const selectionStrip = document.getElementById('gifSelectionStrip');
    const selectionCount = document.getElementById('gifSelectionCount');
    const doneBtn = document.getElementById('gifSelectionDone');
    if (!selectionBar || !selectionStrip || !selectionCount || !doneBtn) {
        return;
    }

    const hasSelection = gifModalSelectedItems.length > 0;
    selectionBar.hidden = !hasSelection;
    selectionBar.style.display = hasSelection ? 'flex' : 'none';
    selectionCount.textContent = String(gifModalSelectedItems.length);
    doneBtn.disabled = !hasSelection;
    selectionStrip.innerHTML = '';

    if (!hasSelection) {
        return;
    }

    gifModalSelectedItems.forEach((item, index) => {
        const chip = document.createElement('div');
        chip.className = 'gif-selection-chip';
        if (index === 0) {
            chip.classList.add('is-first');
        }

        const image = document.createElement('img');
        image.src = item.previewUrl;
        image.alt = item.title || `Selected GIF ${index + 1}`;
        image.loading = 'lazy';

        chip.appendChild(image);
        selectionStrip.appendChild(chip);
    });
}

function clearGifModalSelection() {
    gifModalSelectedItems = [];
    renderGifSelectionBar();
    syncVisibleGifCardSelectionStates();
}

function toggleGifModalSelection(item) {
    const key = getGifSelectionKey(item);
    if (!key) {
        return;
    }

    const existingIndex = gifModalSelectedItems.findIndex(selectedItem => getGifSelectionKey(selectedItem) === key);
    if (existingIndex >= 0) {
        gifModalSelectedItems.splice(existingIndex, 1);
    } else {
        gifModalSelectedItems.push(item);
    }

    renderGifSelectionBar();
    syncVisibleGifCardSelectionStates();
}

function cancelGifModalSearchQueue() {
    gifSearchSequence += 1;
    clearTimeout(gifSearchDebounceId);
    gifSearchDebounceId = 0;
}

function setGifModalSectionVisibility(element, shouldShow) {
    if (!element) {
        return;
    }

    element.hidden = !shouldShow;
    if (shouldShow) {
        element.style.removeProperty('display');
        return;
    }

    element.style.display = 'none';
}

function renderGifCategoryList() {
    const categoryList = document.getElementById('gifCategoryList');
    if (!categoryList) {
        return;
    }

    categoryList.innerHTML = '';
    GIF_MODAL_CATEGORIES.forEach(category => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'gif-category-card';
        const icon = document.createElement('i');
        icon.className = category.icon;
        icon.setAttribute('aria-hidden', 'true');

        const title = document.createElement('span');
        title.className = 'gif-category-card-title';
        title.textContent = category.label;

        const note = document.createElement('span');
        note.className = 'gif-category-card-note';
        note.textContent = category.note || '';

        button.appendChild(icon);
        button.appendChild(title);
        button.appendChild(note);
        button.addEventListener('click', () => {
            openGifCategoryResults(category.key);
        });
        categoryList.appendChild(button);
    });
}

function renderGifFavoritesResults(query = '') {
    const filteredItems = getFavoriteGifItems(query);
    if (!filteredItems.length) {
        const results = document.getElementById('gifSearchResults');
        if (!results) {
            return;
        }

        results.innerHTML = '';
        const empty = document.createElement('div');
        empty.className = 'friend-request-search-empty';
        empty.textContent = query
            ? `No favorite GIFs matched "${query}" yet.`
            : 'Use a GIF once and it will show up here.';
        results.appendChild(empty);
        return;
    }

    renderGifSearchResults(filteredItems, query || 'Favorites');
}

function showGifSearchResultsView(query = '', options = {}) {
    const trimmedQuery = String(query || '').trim();
    const toolbar = document.getElementById('gifCategoryToolbar');
    const backButton = document.getElementById('gifCategoryBack');
    const title = document.getElementById('gifCategoryTitle');
    const subtitle = document.getElementById('gifModalSubtitle');
    const categoryList = document.getElementById('gifCategoryList');
    const searchShell = document.getElementById('gifSearchShell');
    const searchInput = document.getElementById('gifSearchInput');
    const results = document.getElementById('gifSearchResults');
    const shouldLoadResults = options.loadResults !== false;

    if (!trimmedQuery || !results) {
        showGifCategoryPicker();
        return;
    }

    activeGifModalMode = 'search';
    activeGifModalCategoryKey = '';

    setGifModalSectionVisibility(toolbar, true);
    setGifModalSectionVisibility(backButton, true);
    setGifModalSectionVisibility(categoryList, false);
    setGifModalSectionVisibility(searchShell, true);
    setGifModalSectionVisibility(results, true);
    if (title) title.textContent = 'Search Results';
    if (subtitle) subtitle.textContent = `Showing results for "${trimmedQuery}"`;
    if (searchInput) searchInput.placeholder = 'Search GIFs';

    if (shouldLoadResults) {
        loadGifSearchResults(trimmedQuery);
        return;
    }

    renderGifSearchLoading(`Searching "${trimmedQuery}"...`);
}

function showGifCategoryPicker() {
    const toolbar = document.getElementById('gifCategoryToolbar');
    const backButton = document.getElementById('gifCategoryBack');
    const subtitle = document.getElementById('gifModalSubtitle');
    const categoryList = document.getElementById('gifCategoryList');
    const searchShell = document.getElementById('gifSearchShell');
    const searchInput = document.getElementById('gifSearchInput');
    const results = document.getElementById('gifSearchResults');

    cancelGifModalSearchQueue();
    activeGifModalMode = 'categories';
    activeGifModalCategoryKey = '';

    setGifModalSectionVisibility(toolbar, false);
    setGifModalSectionVisibility(backButton, false);
    if (categoryList) {
        setGifModalSectionVisibility(categoryList, true);
        renderGifCategoryList();
    }
    setGifModalSectionVisibility(searchShell, true);
    setGifModalSectionVisibility(results, false);
    if (subtitle) subtitle.textContent = 'Pick a category to explore GIFs';
    if (searchInput) {
        searchInput.value = '';
        searchInput.placeholder = 'Search GIFs';
    }
    if (results) {
        results.innerHTML = '';
    }
}

function openGifCategoryResults(categoryKey) {
    const category = getGifModalCategory(categoryKey);
    const toolbar = document.getElementById('gifCategoryToolbar');
    const backButton = document.getElementById('gifCategoryBack');
    const title = document.getElementById('gifCategoryTitle');
    const subtitle = document.getElementById('gifModalSubtitle');
    const categoryList = document.getElementById('gifCategoryList');
    const searchShell = document.getElementById('gifSearchShell');
    const searchInput = document.getElementById('gifSearchInput');
    const results = document.getElementById('gifSearchResults');

    if (!category || !searchInput || !results) {
        return;
    }

    cancelGifModalSearchQueue();
    activeGifModalMode = 'results';
    activeGifModalCategoryKey = category.key;

    setGifModalSectionVisibility(toolbar, true);
    setGifModalSectionVisibility(backButton, true);
    setGifModalSectionVisibility(categoryList, false);
    setGifModalSectionVisibility(searchShell, true);
    setGifModalSectionVisibility(results, true);
    if (title) title.textContent = category.label;
    if (subtitle) {
        subtitle.textContent = category.key === 'favorites'
            ? 'Favorites'
            : `Showing ${category.label} GIFs`;
    }

    if (category.key === 'favorites') {
        searchInput.value = '';
        searchInput.placeholder = 'Search favorites';
        renderGifFavoritesResults('');
    } else {
        searchInput.value = '';
        searchInput.placeholder = `Search ${category.label} GIFs`;
        loadGifSearchResults(category.label);
    }

    window.setTimeout(() => {
        if (searchInput && typeof searchInput.focus === 'function') {
            searchInput.focus();
            searchInput.setSelectionRange(searchInput.value.length, searchInput.value.length);
        }
    }, 30);
}

function renderGifSearchLoading(message = 'Loading GIFs...') {
    const results = document.getElementById('gifSearchResults');
    if (!results) return;

    results.innerHTML = '';
    const loading = document.createElement('div');
    loading.className = 'gif-search-loading';
    loading.textContent = message;
    results.appendChild(loading);
}

function renderGifSearchPlaceholder(query = '') {
    const results = document.getElementById('gifSearchResults');
    if (!results) return;

    results.innerHTML = '';
    const empty = document.createElement('div');
    empty.className = 'friend-request-search-empty';
    empty.textContent = query
        ? `No GIFs matched "${query}" yet.`
        : 'Search results will appear here as you type.';
    results.appendChild(empty);
}

function renderGifSearchResults(items, query = '') {
    const results = document.getElementById('gifSearchResults');
    if (!results) return;

    results.innerHTML = '';
    if (!Array.isArray(items) || !items.length) {
        renderGifSearchPlaceholder(query);
        return;
    }

    const grid = document.createElement('div');
    grid.className = 'gif-search-grid';

    items.forEach((item, index) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'gif-search-card';
        button.dataset.gifId = item.id || String(index);
        button.dataset.gifTitle = item.title || 'GIF';
        button.dataset.gifPreviewUrl = item.previewUrl;
        button.dataset.gifSendUrl = item.sendUrl;
        button.dataset.gifFileName = item.fileName || buildGifFileName(item.title);
        button.setAttribute('aria-label', `Select GIF: ${item.title || 'GIF'}`);
        button.setAttribute('aria-pressed', 'false');

        const image = document.createElement('img');
        image.src = item.sendUrl || item.previewUrl;
        image.alt = item.title || 'GIF result';
        image.loading = 'lazy';

        const badge = document.createElement('div');
        badge.className = 'gif-search-card-badge';

        button.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();

            if (!selectedUser) {
                showToast('Please select a chat first', 'error');
                closeGifModal();
                return;
            }

            toggleGifModalSelection(item);
        });

        button.appendChild(image);
        button.appendChild(badge);
        syncGifCardSelectionState(button);
        grid.appendChild(button);
    });

    results.appendChild(grid);
}

async function loadGifSearchResults(query = '') {
    const trimmedQuery = String(query || '').trim();
    const requestId = ++gifSearchSequence;
    renderGifSearchLoading(trimmedQuery ? `Searching "${trimmedQuery}"...` : 'Loading trending GIFs...');

    const params = new URLSearchParams({
        token,
        limit: String(TENOR_GIF_LIMIT),
        locale: getTenorLocale()
    });

    if (trimmedQuery) {
        params.set('q', trimmedQuery);
    }

    try {
        const response = await fetch(`search_gifs.php?${params.toString()}`, {
            cache: 'no-store',
            credentials: 'same-origin'
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) {
            throw new Error(data.error || `GIF search failed with status ${response.status}`);
        }

        if (requestId !== gifSearchSequence) {
            return;
        }

        if (data && data.success === false) {
            throw new Error(data.error || 'Unable to load GIFs right now.');
        }

        const items = (Array.isArray(data && data.results) ? data.results : [])
            .map((item, index) => normalizeTenorGifResult(item, index))
            .filter(Boolean);

        renderGifSearchResults(items, trimmedQuery);
    } catch (error) {
        console.error('GIF search failed:', error);
        if (requestId !== gifSearchSequence) {
            return;
        }
        renderGifSearchPlaceholder(trimmedQuery);
        showToast('Could not load GIFs right now.', 'error');
    }
}

function openGifModal() {
    const modal = document.getElementById('gifModal');
    if (!modal) return;

    clearGifModalSelection();
    bringOverlayToFront(modal, 6);
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
    showGifCategoryPicker();
    window.setTimeout(() => {
        const firstCategoryBtn = document.querySelector('#gifCategoryList .gif-category-card');
        if (firstCategoryBtn && typeof firstCategoryBtn.focus === 'function') {
            firstCategoryBtn.focus();
        }
    }, 30);
    updateUnreadAttentionCue();
}

function closeGifModal() {
    const modal = document.getElementById('gifModal');
    const input = document.getElementById('gifSearchInput');
    if (!modal) return;
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
    clearGifModalSelection();
    resetOverlayZIndex(modal);
    cancelGifModalSearchQueue();
    activeGifModalMode = 'categories';
    activeGifModalCategoryKey = '';
    if (input) {
        input.value = '';
        input.placeholder = 'Search GIFs';
    }
    showGifCategoryPicker();
    updateUnreadAttentionCue();
    if (selectedUser && !shouldDelaySelectedChatRead(selectedUser)) {
        scheduleSelectedChatReadSync(selectedUser);
    }
}

function openComposerAttachmentPicker(acceptValue = '') {
    const attachmentInputEl = document.getElementById('attachmentInput');
    const voiceRecordBtnEl = document.getElementById('voiceRecordBtn');
    if (!attachmentInputEl) return;

    if (!selectedUser) {
        showToast('Please select a chat first', 'error');
        return;
    }

    if (voiceRecordBtnEl && voiceRecordBtnEl.classList.contains('recording')) {
        showToast('Finish recording the voice message first.', 'error');
        return;
    }

    try {
        attachmentInputEl.value = '';
    } catch (error) {
        console.warn('Unable to reset attachment input before opening picker.', error);
    }

    attachmentInputEl.accept = acceptValue || '';
    window.addEventListener('focus', () => {
        attachmentInputEl.accept = '';
    }, { once: true });
    attachmentInputEl.click();
}

function getTableComposerDimensions() {
    return {
        rows: clampTableMessageDimension(tableComposerRowsInput ? tableComposerRowsInput.value : 3, 3),
        cols: clampTableMessageDimension(tableComposerColsInput ? tableComposerColsInput.value : 3, 3)
    };
}

function applyTableComposerGridHighlight(rows, cols) {
    if (!tableComposerGrid) {
        return;
    }

    Array.from(tableComposerGrid.children).forEach(cell => {
        const cellRows = Number(cell.dataset.tableRows || 0);
        const cellCols = Number(cell.dataset.tableCols || 0);
        cell.classList.toggle('is-active', cellRows <= rows && cellCols <= cols);
    });

    if (tableComposerGridStatus) {
        tableComposerGridStatus.textContent = `${rows} x ${cols} table`;
    }
}

function renderTableComposerGrid(rows, cols) {
    if (!tableComposerGrid) {
        return;
    }

    const renderRows = Math.min(TABLE_MESSAGE_MAX_DIMENSION, Math.max(rows, 8));
    const renderCols = Math.min(TABLE_MESSAGE_MAX_DIMENSION, Math.max(cols, 8));

    tableComposerGrid.style.setProperty('--table-picker-cols', String(renderCols));
    tableComposerGrid.innerHTML = '';

    for (let rowIndex = 1; rowIndex <= renderRows; rowIndex += 1) {
        for (let colIndex = 1; colIndex <= renderCols; colIndex += 1) {
            const cell = document.createElement('button');
            cell.type = 'button';
            cell.className = 'table-picker-cell';
            cell.dataset.tableRows = String(rowIndex);
            cell.dataset.tableCols = String(colIndex);
            cell.setAttribute('aria-label', `${rowIndex} rows by ${colIndex} columns`);
            cell.addEventListener('mouseenter', () => {
                if (tableComposerRowsInput) tableComposerRowsInput.value = String(rowIndex);
                if (tableComposerColsInput) tableComposerColsInput.value = String(colIndex);
                applyTableComposerGridHighlight(rowIndex, colIndex);
            });
            cell.addEventListener('click', () => {
                if (tableComposerRowsInput) tableComposerRowsInput.value = String(rowIndex);
                if (tableComposerColsInput) tableComposerColsInput.value = String(colIndex);
                applyTableComposerGridHighlight(rowIndex, colIndex);
            });
            tableComposerGrid.appendChild(cell);
        }
    }

    applyTableComposerGridHighlight(rows, cols);
}

function syncTableComposerDimensions(shouldRerenderGrid = true) {
    const { rows, cols } = getTableComposerDimensions();
    if (tableComposerRowsInput) tableComposerRowsInput.value = String(rows);
    if (tableComposerColsInput) tableComposerColsInput.value = String(cols);

    if (shouldRerenderGrid) {
        renderTableComposerGrid(rows, cols);
        return;
    }

    applyTableComposerGridHighlight(rows, cols);
}

function getComposerPendingTableDraft() {
    if (typeof window.getPendingTableDraft === 'function') {
        return window.getPendingTableDraft();
    }

    return null;
}

function openTableComposerModal() {
    if (!tableComposerModal) {
        return;
    }

    const pendingTableDraft = getComposerPendingTableDraft();
    const initialRows = pendingTableDraft ? pendingTableDraft.rows : 3;
    const initialCols = pendingTableDraft ? pendingTableDraft.cols : 3;
    if (tableComposerRowsInput) tableComposerRowsInput.value = String(initialRows);
    if (tableComposerColsInput) tableComposerColsInput.value = String(initialCols);
    syncTableComposerDimensions(true);

    bringOverlayToFront(tableComposerModal, 6);
    tableComposerModal.classList.add('open');
    tableComposerModal.setAttribute('aria-hidden', 'false');

    window.setTimeout(() => {
        if (tableComposerRowsInput && typeof tableComposerRowsInput.focus === 'function') {
            tableComposerRowsInput.focus();
            tableComposerRowsInput.select();
        }
    }, 30);
}

function closeTableComposerModal() {
    if (!tableComposerModal) {
        return;
    }

    tableComposerModal.classList.remove('open');
    tableComposerModal.setAttribute('aria-hidden', 'true');
    resetOverlayZIndex(tableComposerModal);
}

function addPollOption(optionNumber) {
    const container = document.getElementById('pollOptionsContainer');
    if (!container) return;
    
    const optionDiv = document.createElement('div');
    optionDiv.className = 'poll-option-item';
    optionDiv.dataset.optionNumber = optionNumber;
    
    optionDiv.innerHTML = `
        <div class="poll-option-header">
            <span class="poll-option-number">Option ${optionNumber}</span>
            ${optionNumber > 2 ? '<button type="button" class="poll-option-remove" onclick="removePollOption(this)"><i class="fa-solid fa-trash"></i> Remove</button>' : ''}
        </div>
        <div class="poll-option-image-upload">
            <label class="poll-option-image-label">Option ${optionNumber} image (optional)</label>
            <input type="file" class="poll-option-image-input" accept="image/*" />
        </div>
        <input type="text" class="poll-form-input poll-option-text-input" placeholder="Option ${optionNumber} text" maxlength="500" />
    `;
    
    container.appendChild(optionDiv);
}

function removePollOption(btn) {
    const optionItem = btn.closest('.poll-option-item');
    if (optionItem) {
        optionItem.remove();
        // Renumber remaining options
        const options = document.querySelectorAll('.poll-option-item');
        options.forEach((opt, index) => {
            const num = index + 1;
            opt.dataset.optionNumber = num;
            opt.querySelector('.poll-option-number').textContent = `Option ${num}`;
            opt.querySelector('.poll-option-image-label').textContent = `Option ${num} image (optional)`;
            opt.querySelector('.poll-option-text-input').placeholder = `Option ${num} text`;
        });
        pollOptionCounter = options.length;
    }
}

async function createPoll() {
    const title = document.getElementById('pollTitleInput').value.trim();
    if (!title) {
        showToast('Please enter a poll title', 'error');
        return;
    }
    
    const optionItems = document.querySelectorAll('.poll-option-item');
    const options = [];
    
    for (let i = 0; i < optionItems.length; i++) {
        const item = optionItems[i];
        const text = item.querySelector('.poll-option-text-input').value.trim();
        const imageInput = item.querySelector('.poll-option-image-input');
        
        if (!text) {
            showToast(`Please enter text for Option ${i + 1}`, 'error');
            return;
        }
        
        let imageUrl = null;
        if (imageInput.files && imageInput.files[0]) {
            // Upload image
            const formData = new FormData();
            formData.append('file', imageInput.files[0]);
            
            try {
                const res = await fetch('upload_poll_image.php?token=' + encodeURIComponent(token), {
                    method: 'POST',
                    body: formData
                });
                const data = await res.json();
                if (data.success) {
                    imageUrl = data.url;
                }
            } catch (e) {
                console.error('Failed to upload poll option image:', e);
            }
        }
        
        options.push({
            text: text,
            image: imageUrl
        });
    }
    
    if (options.length < 2) {
        showToast('Poll must have at least 2 options', 'error');
        return;
    }
    
    const endByDate = document.getElementById('pollEndByDate').checked;
    const endByResponses = document.getElementById('pollEndByResponses').checked;
    
    let endDate = null;
    let endResponses = null;
    
    if (endByDate) {
        const endDateInputValue = document.getElementById('pollEndDate').value;
        if (!endDateInputValue) {
            showToast('Please select an end date', 'error');
            return;
        }

        const parsedEndDate = new Date(endDateInputValue);
        if (Number.isNaN(parsedEndDate.getTime())) {
            showToast('Please select a valid end date', 'error');
            return;
        }

        endDate = parsedEndDate.toISOString();
    }
    
    if (endByResponses) {
        endResponses = parseInt(document.getElementById('pollEndResponses').value);
        if (!endResponses || endResponses < 1) {
            showToast('Please enter a valid number of responses', 'error');
            return;
        }
    }
    
    // End conditions are optional - poll can run indefinitely
    
    try {
        const res = await fetch('create_poll.php?token=' + encodeURIComponent(token) + '&_=' + Date.now(), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                chat_with: selectedUser,
                title: title,
                options: options,
                end_date: endDate,
                end_responses: endResponses
            })
        });
        
        const data = await res.json();
        console.log('Create poll response:', data);
        
        if (data.success) {
            closePollModal();
            showToast('Poll created successfully', 'success');
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
            // The message will appear via WebSocket or polling
        } else {
            console.error('Create poll error:', data);
            showToast(data.error || 'Failed to create poll', 'error');
            if (data.debug) {
                console.error('Debug info:', data.debug);
            }
        }
    } catch (e) {
        console.error('Create poll exception:', e);
        showToast('Failed to create poll', 'error');
    }
}

// Parse poll message
function parsePollMessage(message) {
    if (typeof message !== 'string' || !message.startsWith(POLL_MESSAGE_PREFIX)) {
        return null;
    }
    try {
        return JSON.parse(message.slice(POLL_MESSAGE_PREFIX.length));
    } catch (e) {
        return null;
    }
}

// Build poll message element
async function buildPollMessageElement(pollData, messageId, senderId) {
    const pollId = pollData.poll_id;
    
    // Fetch poll data
    let pollInfo;
    try {
        const res = await fetch(`get_poll_data.php?token=${encodeURIComponent(token)}&poll_id=${pollId}`);
        pollInfo = await res.json();
        if (!pollInfo.success) {
            return createTextElement('Poll not found');
        }
    } catch (e) {
        console.error('Failed to fetch poll data:', e);
        return createTextElement('Failed to load poll');
    }
    
    const poll = pollInfo.poll;
    const options = pollInfo.options;
    const totalVotes = pollInfo.total_votes;
    const userVote = pollInfo.user_vote;
    const isCreator = poll.creator_id == currentUserId;
    const isEnded = !!(poll.is_ended || poll.ended_at);
    
    const container = document.createElement('div');
    container.className = 'poll-container';
    container.dataset.pollId = pollId;
    
    // Title
    const titleDiv = document.createElement('div');
    titleDiv.className = 'poll-title';
    titleDiv.textContent = poll.title;
    container.appendChild(titleDiv);
    
    // Options
    const optionsList = document.createElement('div');
    optionsList.className = 'poll-options-list';
    
    options.forEach(option => {
        const optionDiv = document.createElement('div');
        optionDiv.className = 'poll-option';
        optionDiv.dataset.optionId = option.id;
        
        if (userVote == option.id) {
            optionDiv.classList.add('selected');
        }
        
        if (isEnded) {
            optionDiv.classList.add('disabled');
        }
        
        // Progress bar
        const percentage = totalVotes > 0 ? Math.round((option.vote_count / totalVotes) * 100) : 0;
        const barDiv = document.createElement('div');
        barDiv.className = 'poll-option-bar';
        barDiv.style.width = percentage + '%';
        optionDiv.appendChild(barDiv);
        
        // Image if exists
        if (option.option_image) {
            const img = document.createElement('img');
            img.className = 'poll-option-image';
            img.src = option.option_image;
            img.alt = '';
            optionDiv.appendChild(img);
        }
        
        // Content
        const contentDiv = document.createElement('div');
        contentDiv.className = 'poll-option-content';
        
        const textDiv = document.createElement('div');
        textDiv.className = 'poll-option-text';
        textDiv.textContent = option.option_text;
        contentDiv.appendChild(textDiv);
        
        // Stats (show if user voted or poll ended)
        if (userVote || isEnded) {
            const statsDiv = document.createElement('div');
            statsDiv.className = 'poll-option-stats';
            
            const percentageSpan = document.createElement('span');
            percentageSpan.className = 'poll-option-percentage';
            percentageSpan.textContent = percentage + '%';
            statsDiv.appendChild(percentageSpan);
            
            if (option.vote_count > 0) {
                const countSpan = document.createElement('span');
                countSpan.className = 'poll-option-count';
                countSpan.textContent = `${option.vote_count} chose this response`;
                countSpan.onclick = (e) => {
                    e.stopPropagation();
                    showPollOptionVoters(option.id);
                };
                statsDiv.appendChild(countSpan);
            }
            
            contentDiv.appendChild(statsDiv);
        }
        
        optionDiv.appendChild(contentDiv);
        
        // Click handler
        if (!isEnded) {
            optionDiv.onclick = () => votePoll(pollId, option.id, messageId);
        } else {
            optionDiv.onclick = () => {
                showToast('This poll is no longer accepting responses', 'error');
            };
        }
        
        optionsList.appendChild(optionDiv);
    });
    
    container.appendChild(optionsList);
    
    // Poll info
    const infoDiv = document.createElement('div');
    infoDiv.className = 'poll-info';
    
    if (isEnded) {
        const endedRow = document.createElement('div');
        endedRow.className = 'poll-info-row';
        endedRow.innerHTML = '<span class="poll-ended-badge"><i class="fa-solid fa-circle-check"></i> Poll ended</span>';
        infoDiv.appendChild(endedRow);
    } else {
        if (poll.end_date) {
            const endDate = new Date(poll.end_date);
            if (!Number.isNaN(endDate.getTime())) {
            const dateRow = document.createElement('div');
            dateRow.className = 'poll-info-row';
            dateRow.innerHTML = `<i class="fa-regular fa-calendar"></i> Poll ending: ${endDate.toLocaleString()}`;
            infoDiv.appendChild(dateRow);
            
            const timeLeft = endDate - new Date();
            if (timeLeft > 0) {
                const timeRow = document.createElement('div');
                timeRow.className = 'poll-info-row';
                timeRow.innerHTML = `<i class="fa-regular fa-clock"></i> Time left: ${formatTimeLeft(timeLeft)}`;
                infoDiv.appendChild(timeRow);
            }
            }
        }
        
        if (poll.end_responses) {
            const responsesRow = document.createElement('div');
            responsesRow.className = 'poll-info-row';
            responsesRow.innerHTML = `<i class="fa-solid fa-users"></i> Poll will end at ${poll.end_responses} responses`;
            infoDiv.appendChild(responsesRow);
        }
    }
    
    const totalRow = document.createElement('div');
    totalRow.className = 'poll-info-row';
    totalRow.innerHTML = `<span class="poll-total-responses">${totalVotes} ${totalVotes === 1 ? 'response' : 'responses'}</span>`;
    infoDiv.appendChild(totalRow);
    
    container.appendChild(infoDiv);
    
    // Actions
    if (userVote || isCreator) {
        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'poll-actions';
        
        if (userVote && !isEnded) {
            const clearBtn = document.createElement('button');
            clearBtn.className = 'poll-action-btn danger';
            clearBtn.innerHTML = '<i class="fa-solid fa-trash"></i> Clear response';
            clearBtn.onclick = () => clearPollVote(pollId, messageId);
            actionsDiv.appendChild(clearBtn);
        }
        
        if (isCreator && !isEnded) {
            const endBtn = document.createElement('button');
            endBtn.className = 'poll-action-btn danger';
            endBtn.innerHTML = '<i class="fa-solid fa-stop"></i> End poll';
            endBtn.onclick = () => endPoll(pollId, messageId);
            actionsDiv.appendChild(endBtn);
        }
        
        container.appendChild(actionsDiv);
    }
    
    return container;
}

function formatTimeLeft(ms) {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);
    
    if (days > 0) return `${days}d ${hours % 24}h`;
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m`;
    return `${seconds}s`;
}

async function votePoll(pollId, optionId, messageId) {
    try {
        const res = await fetch('vote_poll.php?token=' + encodeURIComponent(token), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ poll_id: pollId, option_id: optionId })
        });
        
        const data = await res.json();
        if (data.success) {
            // Refresh the poll message
            await refreshPollMessage(messageId);
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
        } else {
            showToast(data.error || 'Failed to vote', 'error');
        }
    } catch (e) {
        console.error('Vote poll error:', e);
        showToast('Failed to vote', 'error');
    }
}

async function clearPollVote(pollId, messageId) {
    if (!confirm('Are you sure you want to clear your response?')) return;
    
    try {
        const res = await fetch('clear_poll_vote.php?token=' + encodeURIComponent(token), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ poll_id: pollId })
        });
        
        const data = await res.json();
        if (data.success) {
            await refreshPollMessage(messageId);
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
            showToast('Response cleared', 'success');
        } else {
            showToast(data.error || 'Failed to clear response', 'error');
        }
    } catch (e) {
        console.error('Clear poll vote error:', e);
        showToast('Failed to clear response', 'error');
    }
}

async function endPoll(pollId, messageId) {
    if (!confirm('Are you sure you want to end this poll? This cannot be undone.')) return;
    
    try {
        const res = await fetch('end_poll.php?token=' + encodeURIComponent(token), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ poll_id: pollId })
        });
        
        const data = await res.json();
        if (data.success) {
            await refreshPollMessage(messageId);
            invalidateSidebarHistoryCache({ reloadIfVisible: true });
            showToast('Poll ended', 'success');
        } else {
            showToast(data.error || 'Failed to end poll', 'error');
        }
    } catch (e) {
        console.error('End poll error:', e);
        showToast('Failed to end poll', 'error');
    }
}

async function refreshPollMessage(messageId) {
    const messageEl = chatBox.querySelector(`.message[data-id="${messageId}"]`);
    if (!messageEl) return;
    
    const bubbleEl = messageEl.querySelector('.message-bubble');
    if (!bubbleEl) return;
    
    const pollContainer = bubbleEl.querySelector('.poll-container');
    if (!pollContainer) return;
    
    const pollId = pollContainer.dataset.pollId;
    const pollData = { poll_id: pollId };
    const senderId = messageEl.dataset.senderId;
    
    const newPollEl = await buildPollMessageElement(pollData, messageId, senderId);
    pollContainer.replaceWith(newPollEl);
}

async function showPollOptionVoters(optionId) {
    try {
        const res = await fetch(`get_poll_option_voters.php?token=${encodeURIComponent(token)}&option_id=${optionId}`);
        const raw = await res.text();
        const data = raw ? JSON.parse(raw) : {};
        
        if (!res.ok || !data.success) {
            showToast(data.error || 'Failed to load voters', 'error');
            return;
        }
        
        const modal = document.getElementById('pollResponsesModal');
        const list = document.getElementById('pollResponsesList');
        
        if (!modal || !list) return;
        
        list.innerHTML = '';
        
        if (data.voters.length === 0) {
            list.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-secondary);">No responses yet</div>';
        } else {
            data.voters.forEach(voter => {
                const item = document.createElement('div');
                item.className = 'poll-response-item';
                
                const avatarWrap = document.createElement('div');
                avatarWrap.className = 'poll-response-avatar-wrap';
                
                const avatar = document.createElement('img');
                avatar.className = 'poll-response-avatar';
                avatar.src = voter.profile_pic || 'images/default-profile.png';
                avatar.alt = '';
                avatarWrap.appendChild(avatar);
                
                const status = document.createElement('span');
                status.className = 'poll-response-status';
                if (voter.online_status === 'online') {
                    status.classList.add('online');
                }
                avatarWrap.appendChild(status);
                
                item.appendChild(avatarWrap);
                
                const info = document.createElement('div');
                info.className = 'poll-response-info';
                
                const name = document.createElement('div');
                name.className = 'poll-response-name';
                name.textContent = voter.display_name;
                info.appendChild(name);
                
                const username = document.createElement('div');
                username.className = 'poll-response-username';
                username.textContent = '@' + voter.username;
                info.appendChild(username);
                
                item.appendChild(info);
                list.appendChild(item);
            });
        }
        
        bringOverlayToFront(modal, 6);
        modal.setAttribute('aria-hidden', 'false');
        modal.style.display = 'flex';
    } catch (e) {
        console.error('Show poll voters error:', e);
        showToast('Failed to load voters', 'error');
    }
}

function closePollResponsesModal() {
    const modal = document.getElementById('pollResponsesModal');
    if (!modal) return;
    modal.setAttribute('aria-hidden', 'true');
    modal.style.display = 'none';
    resetOverlayZIndex(modal);
}

</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
  console.log("JS loaded 🔥");
  const addTapAndClickListener = typeof window.addTapAndClickListener === 'function'
    ? window.addTapAndClickListener.bind(window)
    : ((element, handler) => {
        if (!element || typeof handler !== 'function') {
            return;
        }
        element.addEventListener('click', handler);
      });

    // Load nicknames from database (non-blocking)
    loadNicknamesFromDatabase().then(() => {
        console.log('Nicknames loaded from database');
        // Apply nicknames after loading
        try {
            applyNicknamesOnPageLoad();
            // Retry a few times to catch any late-rendered elements
            setTimeout(applyNicknamesOnPageLoad, 100);
            setTimeout(applyNicknamesOnPageLoad, 300);
            setTimeout(applyNicknamesOnPageLoad, 600);
        } catch (e) {
            console.error('Error applying nicknames:', e);
        }
    }).catch(err => {
        console.error('Failed to load nicknames:', err);
    });

    // Ensure a fallback global restore exists in case the main script didn't set it
    try {
        if (typeof window.restoreMobileContactsView !== 'function') {
            window.restoreMobileContactsView = function restoreMobileContactsViewFallback(options) {
                console.log('DEBUG_FALLBACK: restoreMobileContactsView fallback invoked', options);
                try {
                    const chatContainer = document.querySelector('.chat-container');
                    const sidebarEl = document.getElementById('sidebar');
                    const backBtnEl = document.getElementById('mobileBackBtn');
                    if (chatContainer) chatContainer.style.display = 'none';
                    if (sidebarEl) sidebarEl.style.display = 'flex';
                    if (backBtnEl) backBtnEl.style.display = 'none';
                    // Clear active selection
                    document.querySelectorAll('#contactsList .contact.active').forEach(c => c.classList.remove('active'));
                    if (typeof window.updateHeaderContact === 'function') {
                        try { window.updateHeaderContact(null); } catch (e) {}
                    }
                    requestAnimationFrame(() => {
                        try { const strip = document.getElementById('mobileContactsStrip'); if (strip) strip.scrollLeft = 0; } catch (e) {}
                    });
                } catch (err) {
                    console.error('DEBUG_FALLBACK: restoreMobileContactsView failed', err);
                }
            };
            console.log('DEBUG_FALLBACK: installed fallback window.restoreMobileContactsView');
        }
    } catch (e) { console.warn('DEBUG_FALLBACK: could not install fallback', e); }

  /* ======================================
     PROFILE DROPDOWN + ACCOUNT MENU
  ====================================== */
  const accountMenu = document.getElementById('accountMenu');
  const settingsNavItems = Array.from(document.querySelectorAll('.settings-nav-item[data-settings-target]'));
  const settingsPanels = Array.from(document.querySelectorAll('.settings-panel[data-settings-panel]'));
  const settingsNavList = document.querySelector('.settings-nav-list');
  const settingsNavScrollbar = document.querySelector('.settings-sidebar .settings-nav-scrollbar');
  // token is already declared earlier in the script
  const profileDropdownToggles = Array.from(document.querySelectorAll('[data-dropdown-toggle]'));
  const openNativeFilePicker = typeof window.qtOpenFilePicker === 'function'
    ? window.qtOpenFilePicker
    : (inputEl => {
        if (!inputEl) return;
        inputEl.click();
      });

  function updateSettingsNavScrollbar() {
    if (!settingsNavList || !settingsNavScrollbar) {
      return;
    }

    const maxScroll = Math.max(0, settingsNavList.scrollWidth - settingsNavList.clientWidth);
    settingsNavScrollbar.min = '0';
    settingsNavScrollbar.max = String(Math.max(0, Math.ceil(maxScroll)));
    settingsNavScrollbar.disabled = maxScroll <= 0;
    settingsNavScrollbar.style.visibility = maxScroll > 0 ? 'visible' : 'hidden';
    settingsNavScrollbar.style.pointerEvents = maxScroll > 0 ? 'auto' : 'none';
    settingsNavScrollbar.value = String(Math.round(Math.min(maxScroll, Math.max(0, settingsNavList.scrollLeft))));
  }

  function setActiveSettingsPanel(panelKey = 'profile') {
    settingsNavItems.forEach(item => {
      item.classList.toggle('active', item.dataset.settingsTarget === panelKey);
    });

    settingsPanels.forEach(panel => {
      panel.classList.toggle('active', panel.dataset.settingsPanel === panelKey);
    });

    requestAnimationFrame(updateSettingsNavScrollbar);
  }

  function closeProfileDropdowns() {
        document.querySelectorAll('.dropdown-menu.show').forEach(menu => {
            menu.classList.remove('show');
            // clear any inline positioning we may have applied for mobile
            menu.style.top = '';
            menu.style.left = '';
            menu.style.right = '';
            menu.style.position = '';
            menu.style.maxWidth = '';
            menu.style.zIndex = '';
        });
    profileDropdownToggles.forEach(toggle => {
      toggle.setAttribute('aria-expanded', 'false');
      toggle.blur();
    });
  }

  function positionMobileToolbarDropdown(toggle, menu) {
        if (!toggle || !menu || window.innerWidth > 768) return;

        // Place the mobile toolbar dropdown using fixed positioning so it always
        // appears below the toggle and stays within the viewport.
        try {
            menu.style.position = 'fixed';
            menu.style.zIndex = '2000';
            // Ensure max width fits viewport
            const maxW = Math.min(280, Math.max(220, window.innerWidth - 32));
            menu.style.maxWidth = `${maxW}px`;

            const tRect = toggle.getBoundingClientRect();
            const menuW = Math.min(menu.offsetWidth || 220, maxW);
            let left = Math.round(tRect.left);
            if (left + menuW > window.innerWidth - 8) left = Math.max(8, window.innerWidth - menuW - 8);
            if (left < 8) left = 8;

            menu.style.left = `${left}px`;
            menu.style.top = `${Math.round(tRect.bottom + 8)}px`;
            menu.style.right = 'auto';
        } catch (err) {
            // fallback to relative placement
            menu.style.position = '';
            menu.style.top = 'calc(100% + 8px)';
            menu.style.left = '0';
            menu.style.right = 'auto';
            menu.style.maxWidth = '';
            menu.style.zIndex = '';
        }
  }

  profileDropdownToggles.forEach(toggle => {
    const menuId = toggle.getAttribute('data-dropdown-toggle');
    const menu = menuId ? document.getElementById(menuId) : null;
    if (!menu) {
      return;
    }

        // Prevent touches inside the menu from bubbling out and triggering
        // the global close handler (helps on mobile when tapping options).
        menu.addEventListener('pointerdown', event => { event.stopPropagation(); });
        menu.addEventListener('pointerup', event => { event.stopPropagation(); });
        menu.addEventListener('touchstart', event => { event.stopPropagation(); }, { passive: true });
        menu.addEventListener('click', event => { event.stopPropagation(); });

        toggle.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            const shouldOpen = !menu.classList.contains('show');
            closeProfileDropdowns();
            if (shouldOpen) {
                // Show first so we can measure and position correctly on mobile
                menu.classList.add('show');
                toggle.setAttribute('aria-expanded', 'true');
                positionMobileToolbarDropdown(toggle, menu);
            }
        });

        // If this device supports hover with a fine pointer (mouse), emulate
        // desktop-like hover behavior using pointerenter/pointerleave so that
        // moving the mouse from the toggle into the menu does not close it.
        try {
            const hoverSupported = window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches;
            if (hoverSupported) {
                let hoverCloseTimeout = null;
                toggle.addEventListener('pointerenter', () => {
                    clearTimeout(hoverCloseTimeout);
                    closeProfileDropdowns();
                    menu.classList.add('show');
                    toggle.setAttribute('aria-expanded', 'true');
                    positionMobileToolbarDropdown(toggle, menu);
                });
                toggle.addEventListener('pointerleave', () => {
                    hoverCloseTimeout = setTimeout(() => closeProfileDropdowns(), 160);
                });
                menu.addEventListener('pointerenter', () => { clearTimeout(hoverCloseTimeout); });
                menu.addEventListener('pointerleave', () => { hoverCloseTimeout = setTimeout(() => closeProfileDropdowns(), 160); });
            }
        } catch (e) {}
  });

  document.addEventListener('click', () => {
    closeProfileDropdowns();
  });

  window.addEventListener('resize', () => {
    profileDropdownToggles.forEach(toggle => {
      const menuId = toggle.getAttribute('data-dropdown-toggle');
      const menu = menuId ? document.getElementById(menuId) : null;
      if (menu && menu.classList.contains('show')) {
        positionMobileToolbarDropdown(toggle, menu);
      }
    });
  });

  if (settingsNavList && settingsNavScrollbar) {
    const syncNavFromSlider = () => {
      settingsNavList.scrollLeft = Number(settingsNavScrollbar.value || 0);
    };

    settingsNavScrollbar.addEventListener('input', syncNavFromSlider);
    settingsNavScrollbar.addEventListener('change', syncNavFromSlider);
    settingsNavList.addEventListener('scroll', updateSettingsNavScrollbar, { passive: true });
    window.addEventListener('resize', updateSettingsNavScrollbar);
    window.addEventListener('load', updateSettingsNavScrollbar);
    setTimeout(updateSettingsNavScrollbar, 0);
  }

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      closeProfileDropdowns();
      window.closeAccountMenu();
    }
  });

  // Expose globally
  window.openAccountMenu = (panelKey = 'profile') => {
    closeProfileDropdowns();
    document.body.classList.add('account-menu-open');
    if (typeof hideContactInfoPanel === 'function') {
      hideContactInfoPanel();
    }
    if (typeof closeRightSidebar === 'function') {
      closeRightSidebar();
    }
    if (headerOverflowMenu) {
      headerOverflowMenu.style.display = 'none';
    }
    accountMenu.style.display = 'block';
    setActiveSettingsPanel(panelKey);
    requestAnimationFrame(updateSettingsNavScrollbar);
    setTimeout(updateSettingsNavScrollbar, 80);
    setTimeout(updateSettingsNavScrollbar, 180);
    updateUnreadAttentionCue();
  };

  window.closeAccountMenu = () => {
    document.body.classList.remove('account-menu-open');
    accountMenu.style.display = 'none';
    updateUnreadAttentionCue();
    if (selectedUser && !shouldDelaySelectedChatRead(selectedUser)) {
      scheduleSelectedChatReadSync(selectedUser);
    }
  };

  settingsNavItems.forEach(item => {
    item.addEventListener('click', () => {
      setActiveSettingsPanel(item.dataset.settingsTarget || 'profile');
    });
  });
  setActiveSettingsPanel('profile');

  /* ======================================
     USERNAME EDIT UI
  ====================================== */
  const editLink         = document.getElementById('editUsernameLink');
  const displayUsername  = document.getElementById('displayUsername');
  const accountHeroDisplayName = document.getElementById('accountHeroDisplayName');
  const accountUsernameValue = document.getElementById('accountUsernameValue');
  const accountCurrentBioValue = document.getElementById('accountCurrentBioValue');
  const editForm         = document.getElementById('editUsernameForm');
  const saveBtn          = document.getElementById('saveUsernameBtn');
  const newUsernameInput = document.getElementById('newUsername');
  const bioInput         = document.getElementById('bioInput');
  const saveBioBtn       = document.getElementById('saveBioBtn');
  const bioStatusMsg     = document.getElementById('bioStatusMsg');

  if (!editLink) {
    console.warn("⚠️ editUsernameLink not found in DOM");
    return;
  }

  editLink.innerHTML = '<i class="fa-solid fa-pen-to-square" aria-hidden="true"></i><span>Edit Display Name</span>';

  // Toggle edit mode
  editLink.addEventListener('click', e => {
    e.preventDefault();
    console.log('Edit clicked 🔥');

    editLink.style.display = 'none';
    editForm.style.display = 'block';

    setTimeout(() => newUsernameInput.focus(), 50);
  });

  // Save updated display name
  saveBtn.addEventListener('click', () => {
    const newUsername = newUsernameInput.value.trim();
    if (!newUsername) return alert("Display name can't be empty");

    fetch('/update-username.php', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ newUsername, token: token || '' })
    })
    .then(res => res.text())
    .then(text => {
      console.log("RAW:", text);  // debug
      return JSON.parse(text);
    })

    .then(data => {
      console.log(data);
      if (data.success) {
        const nextDisplayName = data.display_name || newUsername;
        displayUsername.textContent = nextDisplayName;
        if (accountHeroDisplayName) {
          accountHeroDisplayName.textContent = nextDisplayName;
        }
        editLink.style.display = 'inline';
        editForm.style.display = 'none';
        currentUserDisplayName = nextDisplayName;
        if (accountUsernameValue) {
          accountUsernameValue.textContent = `Username: ${currentUsername}`;
        }
        return alert('Display name updated successfully.');
        alert('Username updated ✔️');
      } else {
        alert(data.error || 'Failed to update display name.');
      }
    })
    .catch(err => {
      console.error(err);
      alert('Server error updating display name.');
    });
  });

  if (saveBioBtn && bioInput && bioStatusMsg) {
    saveBioBtn.addEventListener('click', async () => {
      const bio = bioInput.value.trim();
      bioStatusMsg.textContent = '';

      try {
        const res = await fetch('/update-bio.php', {
          method: 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({ bio, token: token || '' })
        });

        const data = await res.json();
        if (data.success) {
          currentUserBio = data.bio || '';
          if (accountCurrentBioValue) {
            accountCurrentBioValue.textContent = currentUserBio || 'No bio yet.';
          }
          bioStatusMsg.textContent = 'Bio saved.';
        } else {
          bioStatusMsg.textContent = data.error || 'Failed to save bio.';
        }
      } catch (err) {
        console.error(err);
        bioStatusMsg.textContent = 'Server error saving bio.';
      }
    });
  }

  /* ======================================
     SETTINGS PREFERENCES
  ====================================== */
  const settingsStore = window.QuillTalkSettings || null;
  const settingsInputs = {
    typingIndicators: document.getElementById('settingTypingIndicators'),
    enterToSend: document.getElementById('settingEnterToSend'),
    messagePositionMode: document.getElementById('settingMessagePositionMode'),
    messageSplitSelfSide: document.getElementById('settingMessageSplitSelfSide'),
    messageSingleSide: document.getElementById('settingMessageSingleSide'),
    confirmMediaSends: document.getElementById('settingConfirmMediaSends'),
    confirmVoiceSends: document.getElementById('settingConfirmVoiceSends'),
    voicePlaybackSpeed: document.getElementById('settingVoicePlaybackSpeed'),
    callRingtone: document.getElementById('settingCallRingtone'),
    callRingback: document.getElementById('settingCallRingback'),
    messageSounds: document.getElementById('settingMessageSounds'),
    friendRequestPopups: document.getElementById('settingFriendRequestPopups'),
    themeMode: document.getElementById('settingThemeMode'),
    accentColor: document.getElementById('settingAccentColor')
  };
  const settingsAccentColorTrigger = document.getElementById('settingAccentColorTrigger');
  const settingsAccentColorValue = document.getElementById('settingAccentColorValue');
  const settingsAccentColorPreview = document.getElementById('settingAccentColorPreview');
  const settingsMessageSplitSelfSideRow = document.getElementById('settingMessageSplitSelfSideRow');
  const settingsMessageSingleSideRow = document.getElementById('settingMessageSingleSideRow');
  const resetAppSettingsBtn = document.getElementById('resetAppSettingsBtn');
  const resetAppSettingsMsg = document.getElementById('resetAppSettingsMsg');
  const settingsDefaults = typeof window.__qtGetDefaultAppSettings === 'function'
    ? window.__qtGetDefaultAppSettings()
    : (settingsStore && typeof settingsStore.defaults === 'function'
        ? settingsStore.defaults()
        : {
            messagePositionMode: 'split',
            messageSplitSelfSide: 'right',
            messageSingleSide: 'left',
            themeMode: 'system'
          });
  const normalizeSettingsThemeMode = (value) => (
    typeof window.__qtNormalizeThemeModePreference === 'function'
      ? window.__qtNormalizeThemeModePreference(value, settingsDefaults.themeMode)
      : (() => {
          const normalized = String(value || '').trim().toLowerCase();
          if (normalized === 'dark' || normalized === 'light' || normalized === 'system') {
            return normalized;
          }
          return settingsDefaults.themeMode;
        })()
  );
  const normalizeSettingsMessagePositionMode = (value) => (
    typeof window.__qtNormalizeMessagePositionMode === 'function'
      ? window.__qtNormalizeMessagePositionMode(value, settingsDefaults.messagePositionMode)
      : (() => {
          const normalized = String(value || '').trim().toLowerCase();
          if (normalized === 'split' || normalized === 'single') {
            return normalized;
          }
          return settingsDefaults.messagePositionMode;
        })()
  );
  const normalizeSettingsMessagePositionSide = (value, fallback = settingsDefaults.messageSplitSelfSide) => (
    typeof window.__qtNormalizeMessagePositionSide === 'function'
      ? window.__qtNormalizeMessagePositionSide(value, fallback)
      : (() => {
          const normalized = String(value || '').trim().toLowerCase();
          if (normalized === 'left' || normalized === 'right') {
            return normalized;
          }
          return fallback;
        })()
  );
  const settingsValueParsers = {
    messagePositionMode: value => normalizeSettingsMessagePositionMode(value),
    messageSplitSelfSide: value => normalizeSettingsMessagePositionSide(value, settingsDefaults.messageSplitSelfSide),
    messageSingleSide: value => normalizeSettingsMessagePositionSide(value, settingsDefaults.messageSingleSide),
    voicePlaybackSpeed: value => Number(value),
    themeMode: value => normalizeSettingsThemeMode(value),
    accentColor: value => String(value || '').toLowerCase()
  };

  function updateAccentColorPreview(colorValue) {
    const safeColor = String(colorValue || '#2d58f5').toLowerCase();
    if (settingsAccentColorValue) {
      settingsAccentColorValue.textContent = safeColor;
    }
    if (settingsAccentColorPreview) {
      settingsAccentColorPreview.style.setProperty('--accent-color', safeColor);
    }
  }

  function setSettingsRowVisibility(rowElement, shouldShow) {
    if (!rowElement) {
      return;
    }

    rowElement.hidden = !shouldShow;
    rowElement.style.display = shouldShow ? '' : 'none';
    rowElement.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');

    const selectElement = rowElement.querySelector('select');
    if (selectElement) {
      selectElement.disabled = !shouldShow;
    }
  }

  function syncMessagePositionSettingsRows(values) {
    const mode = normalizeSettingsMessagePositionMode(values && values.messagePositionMode);
    setSettingsRowVisibility(settingsMessageSplitSelfSideRow, mode === 'split');
    setSettingsRowVisibility(settingsMessageSingleSideRow, mode === 'single');
  }

  function syncSettingsInputs() {
    if (!settingsStore) {
      return;
    }

    const values = settingsStore.all();
    Object.entries(settingsInputs).forEach(([key, element]) => {
      if (!element) {
        return;
      }

      if (element.type === 'checkbox') {
        element.checked = !!values[key];
      } else {
        element.value = String(values[key]);
      }
    });

    syncMessagePositionSettingsRows(values);
    updateAccentColorPreview(values.accentColor);
  }

  Object.entries(settingsInputs).forEach(([key, element]) => {
    if (!element || !settingsStore) {
      return;
    }

    const applySettingValue = () => {
      if (resetAppSettingsMsg) {
        resetAppSettingsMsg.textContent = '';
      }
      const nextValue = element.type === 'checkbox'
        ? !!element.checked
        : (settingsValueParsers[key] ? settingsValueParsers[key](element.value) : element.value);
      if (key === 'messagePositionMode') {
        syncMessagePositionSettingsRows({
          ...(settingsStore.all ? settingsStore.all() : {}),
          messagePositionMode: nextValue
        });
      }
      settingsStore.set(key, nextValue);
      syncSettingsInputs();
    };

    element.addEventListener('change', applySettingValue);
    if (element.tagName === 'SELECT') {
      element.addEventListener('input', applySettingValue);
    }
  });

  if (settingsAccentColorTrigger && settingsInputs.accentColor) {
    settingsAccentColorTrigger.addEventListener('click', () => {
      settingsInputs.accentColor.click();
    });
  }

  if (resetAppSettingsBtn && settingsStore) {
    resetAppSettingsBtn.addEventListener('click', () => {
      const confirmed = window.confirm('Reset QuillTalk settings to their default values for this browser?');
      if (!confirmed) {
        return;
      }

      if (typeof settingsStore.reset === 'function') {
        settingsStore.reset();
      }
      syncSettingsInputs();

      if (resetAppSettingsMsg) {
        resetAppSettingsMsg.textContent = 'QuillTalk settings were reset to default.';
      }
    });
  }

  syncSettingsInputs();
  
  // ---- Profile Pic Upload with Crop ----
    const profilePicForm = document.getElementById("profilePicForm");
    const profilePicMsg = document.getElementById("profilePicMsg");
    const profileBtnImgs = document.querySelectorAll(".profile-btn");
    const accountMenuProfileImg = document.getElementById("accountMenuProfileImg");
    const profilePicFileInput = document.getElementById("profilePicFileInput");
    const profilePicUploadBtn = document.getElementById("profilePicUploadBtn");
    const profilePicResetBtn = document.getElementById("profilePicResetBtn");

    // Note: setProfileImage is defined in a different scope, so we skip it here
    // The profile images will be set by the earlier DOMContentLoaded block

    // Crop modal elements
    const pfpCropModal = document.getElementById("pfpCropModal");
    const pfpCropCanvas = document.getElementById("pfpCropCanvas");
    const pfpCropWrap = document.getElementById("pfpCropWrap");
    const pfpCropZoom = document.getElementById("pfpCropZoom");
    const pfpCropCancel = document.getElementById("pfpCropCancel");
    const pfpCropApply = document.getElementById("pfpCropApply");

    const CROP_SIZE = 280;
    let cropImg = null, cropScale = 1, cropOffsetX = 0, cropOffsetY = 0;
    let cropDragging = false, cropDragStartX = 0, cropDragStartY = 0, cropDragOriginX = 0, cropDragOriginY = 0;

    function drawCrop() {
        if (!cropImg || !pfpCropCanvas) return;
        const ctx = pfpCropCanvas.getContext('2d');
        pfpCropCanvas.width = CROP_SIZE;
        pfpCropCanvas.height = CROP_SIZE;
        ctx.clearRect(0, 0, CROP_SIZE, CROP_SIZE);
        const w = cropImg.naturalWidth * cropScale;
        const h = cropImg.naturalHeight * cropScale;
        ctx.drawImage(cropImg, cropOffsetX, cropOffsetY, w, h);
    }

    function clampCropOffset() {
        const w = cropImg.naturalWidth * cropScale;
        const h = cropImg.naturalHeight * cropScale;
        cropOffsetX = Math.min(0, Math.max(CROP_SIZE - w, cropOffsetX));
        cropOffsetY = Math.min(0, Math.max(CROP_SIZE - h, cropOffsetY));
    }

    function openCropModal(file) {
        console.log('=== openCropModal CALLED ===');
        console.log('File:', file.name, 'Size:', file.size, 'Type:', file.type);
        console.log('pfpCropModal:', pfpCropModal);
        console.log('pfpCropModal classList before:', pfpCropModal ? pfpCropModal.classList.toString() : 'NULL');
        
        const reader = new FileReader();
        reader.onload = (e) => {
            console.log('=== FileReader onload fired ===');
            console.log('Data URL length:', e.target.result.length);
            const img = new Image();
            img.onload = () => {
                console.log('=== Image loaded ===');
                console.log('Image naturalWidth:', img.naturalWidth, 'naturalHeight:', img.naturalHeight);
                cropImg = img;
                // Fit image to fill the crop area initially
                const fitScale = Math.max(CROP_SIZE / img.naturalWidth, CROP_SIZE / img.naturalHeight);
                cropScale = fitScale;
                cropOffsetX = (CROP_SIZE - img.naturalWidth * cropScale) / 2;
                cropOffsetY = (CROP_SIZE - img.naturalHeight * cropScale) / 2;
                pfpCropZoom.min = fitScale;
                pfpCropZoom.max = fitScale * 4;
                pfpCropZoom.step = fitScale * 0.01;
                pfpCropZoom.value = fitScale;
                drawCrop();
                console.log('=== Adding is-open class to pfpCropModal ===');
                pfpCropModal.classList.add('is-open');
                console.log('pfpCropModal classList after:', pfpCropModal.classList.toString());
                console.log('pfpCropModal computed display:', window.getComputedStyle(pfpCropModal).display);
            };
            img.onerror = () => {
                console.log('=== Image onerror - unsupported format ===');
                profilePicMsg.innerText = 'This photo format is not supported on this device. Try a JPG, PNG, or WebP image.';
                profilePicFileInput.value = '';
            };
            console.log('Setting img.src...');
            img.src = e.target.result;
        };
        reader.onerror = () => {
            console.log('=== FileReader onerror - could not read file ===');
            profilePicMsg.innerText = 'Could not open that photo. Please try another image.';
            profilePicFileInput.value = '';
        };
        console.log('Starting FileReader.readAsDataURL...');
        reader.readAsDataURL(file);
    }

    // Drag to pan
    pfpCropWrap.addEventListener('mousedown', (e) => {
        cropDragging = true;
        cropDragStartX = e.clientX; cropDragStartY = e.clientY;
        cropDragOriginX = cropOffsetX; cropDragOriginY = cropOffsetY;
        e.preventDefault();
    });
    window.addEventListener('mousemove', (e) => {
        if (!cropDragging || !cropImg) return;
        cropOffsetX = cropDragOriginX + (e.clientX - cropDragStartX);
        cropOffsetY = cropDragOriginY + (e.clientY - cropDragStartY);
        clampCropOffset();
        drawCrop();
    });
    window.addEventListener('mouseup', () => { cropDragging = false; });

    // Touch drag
    pfpCropWrap.addEventListener('touchstart', (e) => {
        const t = e.touches[0];
        cropDragging = true;
        cropDragStartX = t.clientX; cropDragStartY = t.clientY;
        cropDragOriginX = cropOffsetX; cropDragOriginY = cropOffsetY;
    }, { passive: true });
    window.addEventListener('touchmove', (e) => {
        if (!cropDragging || !cropImg) return;
        const t = e.touches[0];
        cropOffsetX = cropDragOriginX + (t.clientX - cropDragStartX);
        cropOffsetY = cropDragOriginY + (t.clientY - cropDragStartY);
        clampCropOffset();
        drawCrop();
    }, { passive: true });
    window.addEventListener('touchend', () => { cropDragging = false; });

    // Scroll to zoom
    pfpCropWrap.addEventListener('wheel', (e) => {
        if (!cropImg) return;
        e.preventDefault();
        const delta = e.deltaY > 0 ? -0.05 : 0.05;
        const minScale = parseFloat(pfpCropZoom.min);
        const newScale = Math.max(minScale, Math.min(parseFloat(pfpCropZoom.max), cropScale + delta * cropScale));
        // Zoom toward center
        const cx = CROP_SIZE / 2, cy = CROP_SIZE / 2;
        cropOffsetX = cx - (cx - cropOffsetX) * (newScale / cropScale);
        cropOffsetY = cy - (cy - cropOffsetY) * (newScale / cropScale);
        cropScale = newScale;
        pfpCropZoom.value = cropScale;
        clampCropOffset();
        drawCrop();
    }, { passive: false });

    pfpCropZoom.addEventListener('input', () => {
        if (!cropImg) return;
        const newScale = parseFloat(pfpCropZoom.value);
        const cx = CROP_SIZE / 2, cy = CROP_SIZE / 2;
        cropOffsetX = cx - (cx - cropOffsetX) * (newScale / cropScale);
        cropOffsetY = cy - (cy - cropOffsetY) * (newScale / cropScale);
        cropScale = newScale;
        clampCropOffset();
        drawCrop();
    });

    pfpCropCancel.addEventListener('click', () => {
        pfpCropModal.classList.remove('is-open');
        profilePicFileInput.value = '';
    });

    pfpCropApply.addEventListener('click', async () => {
        if (!cropImg) return;
        // Render the circular crop to a 400x400 canvas
        const out = document.createElement('canvas');
        out.width = 400; out.height = 400;
        const ctx = out.getContext('2d');
        // Scale from CROP_SIZE to 400
        const ratio = 400 / CROP_SIZE;
        ctx.drawImage(pfpCropCanvas, 0, 0, CROP_SIZE, CROP_SIZE, 0, 0, 400, 400);

        pfpCropModal.classList.remove('is-open');
        pfpCropApply.disabled = true;
        profilePicMsg.innerText = 'Uploading...';

        out.toBlob(async (blob) => {
            if (!blob) {
                profilePicMsg.innerText = 'Could not prepare that photo. Please try another image.';
                pfpCropApply.disabled = false;
                profilePicFileInput.value = '';
                return;
            }

            const formData = new FormData();
            formData.append('token', token);
            formData.append('profile_pic', blob, 'profile.jpg');

            try {
                const res = await fetch('upload_profile_pic.php', { method: 'POST', body: formData });
                const txt = await res.text();
                if (txt.trim() === 'success') {
                    profilePicMsg.innerText = 'Profile updated ✔️';
                    setTimeout(() => location.reload(), 500);
                } else {
                    profilePicMsg.innerText = 'Error: ' + txt;
                }
            } catch {
                profilePicMsg.innerText = 'Upload failed. Please try again.';
            }
            pfpCropApply.disabled = false;
            profilePicFileInput.value = '';
        }, 'image/jpeg', 0.92);
    });

    console.log('=== PROFILE PIC SETUP START ===');
    console.log('profilePicFileInput element:', profilePicFileInput);
    console.log('profilePicUploadBtn element:', profilePicUploadBtn);
    console.log('pfpCropModal element:', pfpCropModal);

    if (profilePicFileInput) {
        // Store a reference to check files periodically after click
        let checkFilesInterval = null;
        
        const handleFileSelection = function(event) {
            console.log('=== FILE SELECTION EVENT FIRED ===', event.type);
            console.log('this.files:', this.files);
            
            if (checkFilesInterval) {
                clearInterval(checkFilesInterval);
                checkFilesInterval = null;
            }
            
            const files = this.files;
            if (!files || files.length === 0) {
                console.log('No files found in event handler');
                return;
            }
            
            const file = files[0];
            console.log('File captured:', file.name, file.size, file.type);
            console.log('Calling openCropModal...');
            openCropModal(file);
        };
        
        // Add multiple event listeners
        profilePicFileInput.addEventListener('change', handleFileSelection, false);
        profilePicFileInput.addEventListener('input', handleFileSelection, false);
        
        // Also monitor clicks on the file input itself
        profilePicFileInput.addEventListener('click', function(e) {
            console.log('=== FILE INPUT CLICKED ===');
            console.log('Files before picker:', this.files.length);
            
            // Clear any existing interval
            if (checkFilesInterval) {
                clearInterval(checkFilesInterval);
            }
            
            // Poll for files after the picker closes
            let attempts = 0;
            checkFilesInterval = setInterval(() => {
                attempts++;
                console.log(`Checking for files (attempt ${attempts}):`, this.files.length);
                
                if (this.files.length > 0) {
                    console.log('Files detected via polling!');
                    clearInterval(checkFilesInterval);
                    checkFilesInterval = null;
                    const file = this.files[0];
                    console.log('File from polling:', file.name, file.size, file.type);
                    openCropModal(file);
                } else if (attempts > 50) {
                    // Stop after 5 seconds (50 * 100ms)
                    console.log('Polling timeout - no files detected');
                    clearInterval(checkFilesInterval);
                    checkFilesInterval = null;
                }
            }, 100);
        }, false);
        
        console.log('File selection handlers added (change + input + polling)');
    } else {
        console.log('ERROR: profilePicFileInput not found');
    }
    
    console.log('=== PROFILE PIC SETUP END ===');

    // ═══════════════════════════════════════════════════════════════════════════
    // POLL EVENT LISTENERS
    // ═══════════════════════════════════════════════════════════════════════════
    
    // Chat actions dropdown toggle
    const chatActionsBtn = document.getElementById('chatActionsBtn');
    const chatActionsDropdown = document.getElementById('chatActionsDropdown');

    if (chatActionsBtn && chatActionsDropdown) {
        chatActionsBtn.addEventListener('mousedown', event => {
            if (!isMobileViewport() || !messageInput || !isMessageInputFocused()) {
                return;
            }
            event.preventDefault();
            rememberMessageSelection();
        });
        addTapAndClickListener(chatActionsBtn, (e) => {
            e.preventDefault();
            e.stopPropagation();
            const shouldOpen = !chatActionsDropdown.classList.contains('show');
            window.setChatActionsDropdownOpen(shouldOpen);
            if (shouldOpen) {
                if (typeof window.activateComposerKeyboard === 'function') {
                    window.activateComposerKeyboard({ collapseActions: false });
                }
                if (typeof window.focusMessageInputPreservingSelection === 'function') {
                    window.focusMessageInputPreservingSelection();
                }
            }
        });
        
        // Close dropdown when clicking outside
        document.addEventListener('click', () => {
            window.setChatActionsDropdownOpen(false);
        });
    }

    const gifActionBtn = document.querySelector('[data-action="gif"]');
    if (gifActionBtn) {
        addTapAndClickListener(gifActionBtn, () => {
            if (!selectedUser) {
                showToast('Please select a chat first', 'error');
                return;
            }
            if (voiceRecordBtn && voiceRecordBtn.classList.contains('recording')) {
                showToast('Finish recording the voice message first.', 'error');
                return;
            }
            window.setChatActionsDropdownOpen(false);
            openGifModal();
        });
    }

    // Poll action button
    const pollActionBtn = document.querySelector('[data-action="poll"]');
    if (pollActionBtn) {
        addTapAndClickListener(pollActionBtn, () => {
            if (!selectedUser) {
                showToast('Please select a chat first', 'error');
                return;
            }
            window.setChatActionsDropdownOpen(false);
            openPollModal();
        });
    }

    const tableActionBtn = document.querySelector('[data-action="table"]');
    if (tableActionBtn) {
        addTapAndClickListener(tableActionBtn, () => {
            if (!selectedUser) {
                showToast('Please select a chat first', 'error');
                return;
            }
            if (voiceRecordBtn && voiceRecordBtn.classList.contains('recording')) {
                showToast('Finish recording the voice message first.', 'error');
                return;
            }
