                showGifSearchResultsView(query, { loadResults: false });
                gifSearchDebounceId = window.setTimeout(() => {
                    loadGifSearchResults(query);
                }, 550);
                return;
            }

            if (activeGifModalMode !== 'results') {
                return;
            }

            if (activeGifModalCategoryKey === 'favorites') {
                renderGifFavoritesResults(query);
                return;
            }

            gifSearchDebounceId = window.setTimeout(() => {
                const activeCategory = getGifModalCategory(activeGifModalCategoryKey);
                loadGifSearchResults(query || (activeCategory ? activeCategory.label : ''));
            }, query ? 550 : 0);
