            profilePicResetBtn.disabled = true;
            profilePicMsg.innerText = 'Resetting...';
            try {
                const res = await fetch('reset_profile_pic.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ token })
                });
                const rawText = await res.text();
                let data = {};
                try {
                    data = rawText ? JSON.parse(rawText) : {};
                } catch {
                    data = { error: rawText.trim() || 'Unknown error' };
                }
                if (data.success) {
                    profilePicMsg.innerText = 'Profile picture reset ✔️';
                    setTimeout(() => location.reload(), 500);
                } else {
                    profilePicMsg.innerText = 'Error: ' + (data.error || 'Unknown error');
