            } catch {
                profilePicMsg.innerText = 'Network error. Please try again.';
            }
            profilePicResetBtn.disabled = false;
        });
    }

    // ===== AI CHATS LOADED SYNCHRONOUSLY =====
    // AI chats are now loaded synchronously in pollContacts() before auto-selection
    
    // ===== FOCUS STATE TRACKING FOR NOTIFICATIONS =====
    let lastFocusState = document.hasFocus();
    let focusUpdateTimeout = null;
    
    function updateFocusState(isFocused) {
        console.log('[FOCUS] Updating focus state:', isFocused);
        
        if (focusUpdateTimeout) {
            clearTimeout(focusUpdateTimeout);
        }
        
        focusUpdateTimeout = setTimeout(() => {
            if (token) {
                console.log('[FOCUS] Sending focus update to server:', isFocused);
                fetch('update_focus_state.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        token: token,
                        is_focused: isFocused
                    })
                }).then(response => response.json())
                .then(data => {
                    console.log('[FOCUS] Server response:', data);
                })
                .catch(err => {
                    console.error('[FOCUS] Failed to update focus state:', err);
                });
            } else {
                console.log('[FOCUS] No token available, skipping focus update');
            }
        }, 500); // Reduced debounce time
    }
    
    // Track focus/blur events
    window.addEventListener('focus', () => {
        console.log('[FOCUS] Window focus event fired');
        if (!lastFocusState) {
            lastFocusState = true;
            updateFocusState(true);
            console.log('[FOCUS] Window focused - notifications should be suppressed');
        }
    });
    
    window.addEventListener('blur', () => {
        console.log('[FOCUS] Window blur event fired');
        if (lastFocusState) {
            lastFocusState = false;
            updateFocusState(false);
            console.log('[FOCUS] Window blurred - notifications should be shown');
        }
    });
    
    // Track visibility changes (tab switching)
    document.addEventListener('visibilitychange', () => {
        const isFocused = !document.hidden && document.hasFocus();
        console.log('[FOCUS] Visibility change - hidden:', document.hidden, 'focused:', document.hasFocus(), 'combined:', isFocused);
        if (isFocused !== lastFocusState) {
            lastFocusState = isFocused;
            updateFocusState(isFocused);
            console.log('[FOCUS] Visibility changed - focused:', isFocused);
        }
    });
    
    // Update focus state more frequently
    setInterval(() => {
        const currentFocus = !document.hidden && document.hasFocus();
        if (currentFocus !== lastFocusState) {
            console.log('[FOCUS] Periodic check detected focus change:', lastFocusState, '->', currentFocus);
            lastFocusState = currentFocus;
            updateFocusState(currentFocus);
        }
    }, 5000); // Check every 5 seconds
    
    // Initial focus state
    console.log('[FOCUS] Initial focus state:', document.hasFocus(), 'hidden:', document.hidden);
    if (token) {
        updateFocusState(document.hasFocus() && !document.hidden);
    }
    
    // Manual trigger for AI chat loading (for testing)
    window.manualLoadAiChats = function() {
        console.log('[MANUAL] Attempting to load AI chats...');
        if (typeof loadAiChatsFromDatabase === 'function' && typeof addContact === 'function') {
            loadAiChatsFromDatabase().then(() => {
                console.log('[MANUAL] AI chats loaded successfully');
            }).catch(err => {
                console.error('[MANUAL] Failed to load AI chats:', err);
            });
        } else {
            console.error('[MANUAL] Required functions not available:', {
                loadAiChatsFromDatabase: typeof loadAiChatsFromDatabase,
                addContact: typeof addContact
            });
        }
    };
    
    // Function to check what functions are available
    window.checkAiFunctions = function() {
        console.log('Function availability check:', {
            loadAiChatsFromDatabase: typeof loadAiChatsFromDatabase,
            addContact: typeof addContact,
            openConversation: typeof openConversation,
            contactsList: !!document.getElementById('contactsList'),
            token: !!token
        });
    };

});

// ===== SCHEDULED MESSAGES =====
(function() {
    const chatActionsDropdown = document.getElementById('chatActionsDropdown');
    const scheduleBar = document.getElementById('scheduleBar');
    const scheduleTimeInput = document.getElementById('scheduleTimeInput');
    const scheduleBarCancel = document.getElementById('scheduleBarCancel');
    const chatForm = document.getElementById('chatForm');
    const messageInput = document.getElementById('messageInput');
    
    let isScheduleMode = false;
    
    // Make these globally accessible for delete handler
    if (!window.scheduledMessagesMap) {
        window.scheduledMessagesMap = new Map(); // scheduled_id -> {recipient_id, message, scheduled_time}
    }
    if (!window.hiddenScheduledMessages) {
        window.hiddenScheduledMessages = new Set();
    }
    const scheduledMessagesMap = window.scheduledMessagesMap;
    const hiddenScheduledMessages = window.hiddenScheduledMessages;
    
    // Handle schedule action from + menu
    if (chatActionsDropdown) {
        chatActionsDropdown.addEventListener('click', (e) => {
            const item = e.target.closest('[data-action="schedule"]');
            if (!item) return;
            
            openScheduleMode();
        });
    }
    
    function openScheduleMode() {
        if (!scheduleBar || !scheduleTimeInput) return;
        
        isScheduleMode = true;
        if (typeof window.setChatActionsDropdownOpen === 'function') {
            window.setChatActionsDropdownOpen(false);
        }
        scheduleBar.style.display = 'flex';
        scheduleBar.classList.add('is-open');
        
        // Set minimum time to current time
        const now = new Date();
        // Format for datetime-local: YYYY-MM-DDTHH:MM
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const day = String(now.getDate()).padStart(2, '0');
        const hours = String(now.getHours()).padStart(2, '0');
        const minutes = String(now.getMinutes()).padStart(2, '0');
        const currentTime = `${year}-${month}-${day}T${hours}:${minutes}`;
        
        scheduleTimeInput.min = currentTime;
        
        // Set default to 1 hour from now
        const defaultTime = new Date(now.getTime() + 60 * 60 * 1000);
        const defaultYear = defaultTime.getFullYear();
        const defaultMonth = String(defaultTime.getMonth() + 1).padStart(2, '0');
        const defaultDay = String(defaultTime.getDate()).padStart(2, '0');
        const defaultHours = String(defaultTime.getHours()).padStart(2, '0');
        const defaultMinutes = String(defaultTime.getMinutes()).padStart(2, '0');
        scheduleTimeInput.value = `${defaultYear}-${defaultMonth}-${defaultDay}T${defaultHours}:${defaultMinutes}`;
        
        messageInput.focus();
    }
    
    function closeScheduleMode() {
        if (!scheduleBar) return;
        
        isScheduleMode = false;
        scheduleBar.style.display = 'none';
        scheduleBar.classList.remove('is-open');
        scheduleTimeInput.value = '';
    }

    window.openScheduleMode = openScheduleMode;
    window.closeScheduleMode = closeScheduleMode;
    
    if (scheduleBarCancel) {
        scheduleBarCancel.addEventListener('click', closeScheduleMode);
    }
    
    function shouldHandleScheduledComposerSubmit() {
        if (!isScheduleMode || !scheduleTimeInput || !scheduleTimeInput.value) {
            return false;
        }

        const rawText = messageInput ? String(messageInput.value || '') : '';
        const parseAiCommand = typeof window.parseComposerAiCommand === 'function'
            ? window.parseComposerAiCommand
            : null;

        return !(parseAiCommand && parseAiCommand(rawText));
    }

    let isSchedulingSubmit = false;

    // Capture this before the normal composer submit handler so the browser never navigates.
    if (chatForm) {
        chatForm.addEventListener('submit', async (e) => {
            if (!shouldHandleScheduledComposerSubmit()) {
                return;
            }

            e.preventDefault();
            e.stopPropagation();
            if (typeof e.stopImmediatePropagation === 'function') {
                e.stopImmediatePropagation();
            }

            if (isSchedulingSubmit) {
                return;
            }

            isSchedulingSubmit = true;
            try {
                await handleScheduledMessageSend();
            } finally {
                isSchedulingSubmit = false;
            }
        }, true);
    }
    
    async function handleScheduledMessageSend() {
        if (!selectedUser || !messageInput) return;

        const sessionToken = getSessionTokenValue();
        if (!sessionToken) {
            showToast('Missing session token. Please refresh and sign in again.', 'error');
            return;
        }
        
        const message = messageInput.value.trim();
        if (!message) {
            showToast('Please enter a message', 'error');
            return;
        }
        
        const scheduledTime = scheduleTimeInput.value;
        if (!scheduledTime) {
            showToast('Please select a time', 'error');
            return;
        }
        
        // Convert local datetime to ISO string for server
        const selectedDate = new Date(scheduledTime);
        const isoTime = selectedDate.toISOString();
        
        // Validate time is in the future
        const selectedTimestamp = selectedDate.getTime();
        const now = Date.now();
        if (selectedTimestamp <= now) {
            showToast('Please select a time in the future', 'error');
            return;
        }
        
        console.log('Scheduling message for:', {
            localTime: scheduledTime,
            isoTime: isoTime,
            timestamp: selectedTimestamp,
            now: now,
            diff: selectedTimestamp - now
        });
        
        try {
            const res = await fetch(`send_scheduled_message.php?token=${encodeURIComponent(sessionToken)}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    token: sessionToken,
                    recipient_id: selectedUser,
                    message: message,
                    scheduled_time: isoTime
                })
            });
            
            const data = await res.json();
            
            if (data.success) {
                // Store scheduled message info
                scheduledMessagesMap.set(data.scheduled_id, {
                    recipient_id: selectedUser,
                    message: message,
                    scheduled_time: data.scheduled_time,
                    scheduled_id: data.scheduled_id
                });
                
                // Display scheduled message in chat
                displayScheduledMessage(data.scheduled_id, message, data.scheduled_time);
                
                // Clear input and close schedule mode
                if (typeof window.clearComposerAfterSend === 'function') {
                    window.clearComposerAfterSend(selectedUser, true);
                } else if (messageInput) {
                    messageInput.value = '';
                }
                closeScheduleMode();
                if (typeof window.invalidateSidebarHistoryCache === 'function') {
                    window.invalidateSidebarHistoryCache({ reloadIfVisible: true });
                }
                showToast('Message scheduled', 'success');
            } else {
                console.error('Schedule failed:', data);
                showToast(data.error || 'Failed to schedule message', 'error');
            }
        } catch (error) {
            console.error('Failed to schedule message:', error);
            showToast('Network error: ' + (error.message || 'Failed to schedule message'), 'error');
        }
    }
    
    function displayScheduledMessage(scheduledId, message, scheduledTime) {
        const chatBox = document.getElementById('chatBox');
        if (!chatBox) return;
        
        // Check if already displayed to prevent duplicates
        const existing = chatBox.querySelector(`[data-scheduled-id="${scheduledId}"]`);
        if (existing) {
            console.log('Scheduled message already displayed:', scheduledId);
            return;
        }
        
        const messageDiv = document.createElement('div');
        messageDiv.className = 'message self scheduled';
        messageDiv.dataset.scheduledId = scheduledId;
        messageDiv.dataset.id = 'scheduled-' + scheduledId; // Fake message ID for actions menu
        
        // Parse the server time - it's in server's timezone (likely UTC or server local)
        // Remove the 'Z' and just parse as-is, then display in user's local time
        let scheduledDate;
        if (scheduledTime.includes('T')) {
            // ISO format
            scheduledDate = new Date(scheduledTime);
        } else {
            // MySQL datetime format "YYYY-MM-DD HH:MM:SS"
            // Assume it's in UTC from server
            scheduledDate = new Date(scheduledTime.replace(' ', 'T') + 'Z');
        }
        
        const formattedTime = scheduledDate.toLocaleString(undefined, {
            month: 'short',
            day: 'numeric',
            hour: 'numeric',
            minute: '2-digit',
            hour12: true
        });
        
        console.log('Displaying scheduled message:', {
            scheduledId,
            scheduledTime,
            parsedDate: scheduledDate,
            formattedTime
        });
        
        // Create message structure matching regular messages
        const messageContent = document.createElement('div');
        messageContent.className = 'message-content';
        
        // Create bubble row (needed for actions menu positioning)
        const bubbleRow = document.createElement('div');
        bubbleRow.className = 'message-bubble-row';
        
        const scheduledIndicator = document.createElement('div');
        scheduledIndicator.className = 'message-scheduled-indicator';
        scheduledIndicator.innerHTML = `
            <i class="fa-regular fa-clock"></i>
            <span>Scheduled for ${formattedTime}</span>
        `;
        
        const messageBubble = document.createElement('div');
        messageBubble.className = 'message-bubble';
        
        const messageText = document.createElement('div');
        messageText.className = 'message-text';
        messageText.textContent = message;
        decorateInlineEmojiText(messageText);
        if (isEmojiOnlyMessageText(message)) {
            messageDiv.classList.add('emoji-only-message');
        }
        
        messageBubble.appendChild(messageText);
        bubbleRow.appendChild(messageBubble);
        
        // Add actions menu (three dots)
        const actionsWrap = document.createElement('div');
        actionsWrap.className = 'message-actions-wrap';
        
        const menuBtn = document.createElement('button');
        menuBtn.type = 'button';
        menuBtn.className = 'message-actions-btn';
        menuBtn.innerHTML = '<i class="fa-solid fa-ellipsis-vertical"></i>';
        menuBtn.setAttribute('aria-label', 'Message actions');
        
        console.log('[SCHEDULED] Creating menu button for message:', scheduledId);
        
        const menu = document.createElement('div');
        menu.className = 'message-actions-menu';
        menu.innerHTML = `
            <button type="button" class="message-actions-item" data-act="edit-scheduled"><i class="fa-solid fa-pen-to-square"></i> Edit</button>
            <button type="button" class="message-actions-item" data-act="send-now"><i class="fa-solid fa-paper-plane"></i> Send now</button>
            <button type="button" class="message-actions-item" data-act="delete"><i class="fa-solid fa-trash"></i> Delete</button>
        `;
        
        console.log('[SCHEDULED] Menu initial state:', {
            hasIsOpen: menu.classList.contains('is-open'),
            classList: Array.from(menu.classList)
        });
        
        // Add click listeners directly to menu items for debugging
        menu.addEventListener('click', (ev) => {
            console.log('[SCHEDULED] Menu clicked:', {
                target: ev.target,
                closest: ev.target.closest('[data-act]'),
                dataAct: ev.target.closest('[data-act]')?.dataset?.act
            });
        });
        
        // Add event listeners to menu button
        const stopProp = (ev) => { 
            try { ev.stopPropagation(); } catch(e) {}
        };
        
        menuBtn.addEventListener('mousedown', (ev) => {
            console.log('[SCHEDULED] Menu button mousedown');
            stopProp(ev);
        });
        menuBtn.addEventListener('pointerdown', (ev) => {
            console.log('[SCHEDULED] Menu button pointerdown');
            stopProp(ev);
        });
        menuBtn.addEventListener('pointerup', (ev) => {
            console.log('[SCHEDULED] Menu button pointerup');
            stopProp(ev);
        });
        menuBtn.addEventListener('touchstart', (ev) => {
            console.log('[SCHEDULED] Menu button touchstart');
            stopProp(ev);
        }, { passive: true });
        
        menu.addEventListener('mousedown', stopProp);
        menu.addEventListener('pointerdown', stopProp);
        menu.addEventListener('pointerup', stopProp);
        menu.addEventListener('touchstart', stopProp, { passive: true });
        
        // Toggle menu on click/tap
        const toggleMenu = (ev) => {
            const menuIsOpen = menu.classList.contains('is-open');
            const wrapIsOpen = actionsWrap.classList.contains('is-open');
            
            console.log('[SCHEDULED] Toggle menu clicked!', {
                menuIsOpen: menuIsOpen,
                wrapIsOpen: wrapIsOpen,
                eventType: ev.type,
                menuClasses: Array.from(menu.classList),
                wrapClasses: Array.from(actionsWrap.classList)
            });
            
            try { ev.preventDefault(); } catch(e) {}
            try { ev.stopPropagation(); } catch(e) {}
            
            if (menuIsOpen) {
                console.log('[SCHEDULED] Closing menu');
                menu.classList.remove('is-open');
                actionsWrap.classList.remove('is-open');
            } else {
                console.log('[SCHEDULED] Opening menu');
                menu.classList.add('is-open');
                actionsWrap.classList.add('is-open');
                
                // Position the menu relative to the button
                const r = menuBtn.getBoundingClientRect();
                const mw = 170;
                const mh = menu.scrollHeight || 200;
                
                let left = r.right + 6;
                if (left + mw > window.innerWidth - 8) {
                    left = r.left - mw - 6;
                }
                
                let top = r.bottom + 6;
                const spaceBelow = window.innerHeight - r.bottom;
                const spaceAbove = r.top;
                
                if (top + mh > window.innerHeight - 8 && spaceAbove > spaceBelow) {
                    top = r.top - mh - 6;
                }
                
                top = Math.max(8, Math.min(top, window.innerHeight - mh - 8));
                
                menu.style.left = `${Math.max(8, left)}px`;
                menu.style.top = `${top}px`;
                
                console.log('[SCHEDULED] Menu positioned at:', { left: menu.style.left, top: menu.style.top });
            }
            
            console.log('[SCHEDULED] After toggle:', {
                menuIsOpen: menu.classList.contains('is-open'),
                wrapIsOpen: actionsWrap.classList.contains('is-open')
            });
        };
        
        menuBtn.addEventListener('click', toggleMenu);
        menuBtn.addEventListener('touchend', toggleMenu, { passive: false });
        
        console.log('[SCHEDULED] Menu button event listeners attached');
        
        actionsWrap.appendChild(menuBtn);
        actionsWrap.appendChild(menu);
        
        // Close menu when clicking outside
        const closeMenuOnClickOutside = (ev) => {
            console.log('[SCHEDULED] Click outside check:', {
                target: ev.target,
                containsInMenu: menu.contains(ev.target),
                containsInBtn: menuBtn.contains(ev.target),
                menuIsOpen: menu.classList.contains('is-open')
            });
            
            if (!menu.contains(ev.target) && !menuBtn.contains(ev.target)) {
                if (menu.classList.contains('is-open')) {
                    console.log('[SCHEDULED] Closing menu from outside click');
                    menu.classList.remove('is-open');
                    actionsWrap.classList.remove('is-open');
                    document.removeEventListener('click', closeMenuOnClickOutside);
                }
            }
        };
        
        // Add listener when menu opens, remove when it closes
        const originalToggle = toggleMenu;
        const toggleMenuWithListener = (ev) => {
            const wasOpen = menu.classList.contains('is-open');
            originalToggle(ev);
            const isNowOpen = menu.classList.contains('is-open');
            
            console.log('[SCHEDULED] Toggle with listener:', { wasOpen, isNowOpen });
            
            if (!wasOpen && isNowOpen) {
                // Menu just opened, add outside click listener after a short delay
                setTimeout(() => {
                    document.addEventListener('click', closeMenuOnClickOutside);
                    console.log('[SCHEDULED] Added outside click listener');
                }, 100);
            } else if (wasOpen && !isNowOpen) {
                // Menu just closed, remove listener
                document.removeEventListener('click', closeMenuOnClickOutside);
                console.log('[SCHEDULED] Removed outside click listener');
            }
        };
        
        // Replace the toggle function
        menuBtn.removeEventListener('click', toggleMenu);
        menuBtn.removeEventListener('touchend', toggleMenu);
        menuBtn.addEventListener('click', toggleMenuWithListener);
        menuBtn.addEventListener('touchend', toggleMenuWithListener, { passive: false });
        bubbleRow.appendChild(actionsWrap);
        if (typeof window.bindMobileMessageGestures === 'function') {
            window.bindMobileMessageGestures(messageDiv, messageBubble, {
                onLongPress: () => {
                    if (!menu.classList.contains('is-open')) {
                        toggleMenuWithListener({
                            type: 'longpress',
                            preventDefault() {},
                            stopPropagation() {}
                        });
                    }
                }
            });
        }
        
        messageContent.appendChild(scheduledIndicator);
        messageContent.appendChild(bubbleRow);
        messageDiv.appendChild(messageContent);
        
        chatBox.appendChild(messageDiv);
        chatBox.scrollTop = chatBox.scrollHeight;
    }
    
    // Poll for scheduled messages to check if they've been sent
    async function pollScheduledMessages() {
        try {
            const sessionToken = getSessionTokenValue();
            if (!sessionToken) {
                return;
            }

            const res = await fetch(`get_scheduled_messages.php?token=${encodeURIComponent(sessionToken)}`);
            const scheduled = await res.json();
            
            console.log('Polled scheduled messages:', scheduled);
            
            // Check which scheduled messages are no longer pending (have been sent)
            scheduledMessagesMap.forEach((info, scheduledId) => {
                const stillPending = scheduled.some(s => s.id === scheduledId);
                if (!stillPending) {
                    // Message was sent, remove scheduled styling
                    const messageEl = document.querySelector(`[data-scheduled-id="${scheduledId}"]`);
                    if (messageEl) {
                        messageEl.classList.remove('scheduled');
                        const indicator = messageEl.querySelector('.message-scheduled-indicator');
                        if (indicator) indicator.remove();
                    }
                    scheduledMessagesMap.delete(scheduledId);
                }
            });
            
            // Add any scheduled messages that aren't displayed yet (only for current conversation)
            if (selectedUser) {
                scheduled.forEach(item => {
                    // Skip if user has hidden this message locally
                    if (hiddenScheduledMessages.has(item.id)) {
                        console.log('Skipping hidden scheduled message:', item.id);
                        return;
                    }
                    
                    if (item.recipient_id === selectedUser) {
                        if (!scheduledMessagesMap.has(item.id)) {
                            console.log('Adding scheduled message to map:', item.id);
                            scheduledMessagesMap.set(item.id, {
                                recipient_id: item.recipient_id,
                                message: item.message,
                                scheduled_time: item.scheduled_time,
                                scheduled_id: item.id
                            });
                        }
                        
                        // Always try to display (the function checks for duplicates)
                        displayScheduledMessage(item.id, item.message, item.scheduled_time);
                    }
                });
            }
        } catch (error) {
            console.error('Failed to poll scheduled messages:', error);
        }
    }
    
    // Poll every 10 seconds
    setInterval(pollScheduledMessages, 10000);
    
    // Load scheduled messages when opening a conversation
    window.addEventListener('conversationOpened', () => {
        setTimeout(pollScheduledMessages, 500);
    });
    
    // Also reload after messages are fetched (in case chatBox was cleared)
    window.addEventListener('messagesLoaded', () => {
        setTimeout(pollScheduledMessages, 100);
    });
    
    // Initial load
    setTimeout(pollScheduledMessages, 2000);
    
    // Add "Send now" and "Edit" options to message actions menu
    document.addEventListener('click', async (e) => {
        // Handle "Edit scheduled message"
        if (e.target.closest('[data-act="edit-scheduled"]')) {
            const messageEl = e.target.closest('.message');
            if (!messageEl) return;
            
            const scheduledId = parseInt(messageEl.dataset.scheduledId);
            if (!scheduledId) return;
            
            const scheduledInfo = scheduledMessagesMap.get(scheduledId);
            if (!scheduledInfo) return;
            
            // Find the message bubble and text
            const bubble = messageEl.querySelector('.message-bubble');
            const textEl = bubble.querySelector('.message-text');
            if (!textEl) return;
            
            const originalText = scheduledInfo.message;
            const originalTime = scheduledInfo.scheduled_time;
            
            // Create edit inputs
            const editContainer = document.createElement('div');
            editContainer.className = 'scheduled-message-edit-container';
            editContainer.style.cssText = 'display: flex; flex-direction: column; gap: 8px; padding: 8px;';
            
            // Time input
            const timeInput = document.createElement('input');
            timeInput.type = 'datetime-local';
            timeInput.className = 'message-edit-input';
            timeInput.style.cssText = 'width: 100%; padding: 6px 8px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--surface-primary); color: var(--text-primary);';
            
            // Parse the scheduled time and set it
            let scheduledDate;
            if (originalTime.includes('T')) {
                scheduledDate = new Date(originalTime);
            } else {
                scheduledDate = new Date(originalTime.replace(' ', 'T') + 'Z');
            }
            const year = scheduledDate.getFullYear();
            const month = String(scheduledDate.getMonth() + 1).padStart(2, '0');
            const day = String(scheduledDate.getDate()).padStart(2, '0');
            const hours = String(scheduledDate.getHours()).padStart(2, '0');
            const minutes = String(scheduledDate.getMinutes()).padStart(2, '0');
            timeInput.value = `${year}-${month}-${day}T${hours}:${minutes}`;
            
            // Message input
            const messageInput = document.createElement('input');
            messageInput.type = 'text';
            messageInput.className = 'message-edit-input';
            messageInput.value = originalText;
            messageInput.style.cssText = 'width: 100%; padding: 6px 8px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--surface-primary); color: var(--text-primary);';
            
            editContainer.appendChild(timeInput);
            editContainer.appendChild(messageInput);
            
            // Replace bubble content with edit container
            bubble.innerHTML = '';
            bubble.appendChild(editContainer);
            
            // Hide actions and show edit toolbar
            const actionsWrap = messageEl.querySelector('.message-actions-wrap');
            if (actionsWrap) actionsWrap.style.display = 'none';
            
            const bubbleRow = messageEl.querySelector('.message-bubble-row');
            const editToolbar = document.createElement('div');
            editToolbar.className = 'message-edit-toolbar';
            
            const doneBtn = document.createElement('button');
            doneBtn.type = 'button';
            doneBtn.className = 'message-actions-btn';
            doneBtn.title = 'Done';
            doneBtn.innerHTML = '<i class="fa-solid fa-check"></i>';
            
            const cancelBtn = document.createElement('button');
            cancelBtn.type = 'button';
            cancelBtn.className = 'message-actions-btn';
            cancelBtn.title = 'Cancel';
            cancelBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
            
            editToolbar.appendChild(doneBtn);
            editToolbar.appendChild(cancelBtn);
            bubbleRow.appendChild(editToolbar);
            
            // Cancel handler
            cancelBtn.addEventListener('click', () => {
                bubble.innerHTML = '';
                const restoredText = document.createElement('div');
                restoredText.className = 'message-text';
                restoredText.textContent = originalText;
                decorateInlineEmojiText(restoredText);
                bubble.appendChild(restoredText);
                editToolbar.remove();
                if (actionsWrap) actionsWrap.style.display = '';
            });
            
            // Done handler
            doneBtn.addEventListener('click', async () => {
                const newMessage = messageInput.value.trim();
                const newTime = timeInput.value;
                
                if (!newMessage) {
                    showToast('Message cannot be empty', 'error');
                    return;
                }
                
                if (!newTime) {
                    showToast('Please select a time', 'error');
                    return;
                }
                
                // Validate time is in the future
                const selectedTimestamp = new Date(newTime).getTime();
                if (selectedTimestamp <= Date.now()) {
                    showToast('Time must be in the future', 'error');
                    return;
                }
                
                try {
                    const selectedDate = new Date(newTime);
                    const isoTime = selectedDate.toISOString();
                    const sessionToken = getSessionTokenValue();
                    if (!sessionToken) {
                        showToast('Missing session token. Please refresh and sign in again.', 'error');
                        return;
                    }
                    
                    console.log('[SCHEDULED EDIT] Sending update:', {
                        scheduled_id: scheduledId,
                        message: newMessage,
                        scheduled_time: isoTime
                    });
                    
                    const res = await fetch(`update_scheduled_message.php?token=${encodeURIComponent(sessionToken)}`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            token: sessionToken,
                            scheduled_id: scheduledId,
                            message: newMessage,
                            scheduled_time: isoTime
                        })
                    });
                    
                    console.log('[SCHEDULED EDIT] Response status:', res.status);
                    const data = await res.json();
                    console.log('[SCHEDULED EDIT] Response data:', data);
                    
                    if (data.success) {
                        // Update local map
                        scheduledMessagesMap.set(scheduledId, {
                            ...scheduledInfo,
                            message: newMessage,
                            scheduled_time: data.scheduled_time
                        });
                        
                        // Update display
                        bubble.innerHTML = '';
                        const newTextEl = document.createElement('div');
                        newTextEl.className = 'message-text';
                        newTextEl.textContent = newMessage;
                        decorateInlineEmojiText(newTextEl);
                        bubble.appendChild(newTextEl);
                        
                        // Update scheduled indicator
                        const indicator = messageEl.querySelector('.message-scheduled-indicator span');
                        if (indicator) {
                            const updatedDate = new Date(data.scheduled_time.replace(' ', 'T') + 'Z');
                            const formattedTime = updatedDate.toLocaleString(undefined, {
                                month: 'short',
                                day: 'numeric',
                                hour: 'numeric',
                                minute: '2-digit',
                                hour12: true
                            });
                            indicator.textContent = `Scheduled for ${formattedTime}`;
                        }
                        
                        editToolbar.remove();
                        if (actionsWrap) actionsWrap.style.display = '';
                        if (typeof window.invalidateSidebarHistoryCache === 'function') {
                            window.invalidateSidebarHistoryCache({ reloadIfVisible: true });
                        }
                        showToast('Scheduled message updated', 'success');
                    } else {
                        showToast(data.error || 'Failed to update', 'error');
                    }
                } catch (error) {
                    console.error('Failed to update scheduled message:', error);
                    showToast('Network error', 'error');
                }
            });
            
            // Focus message input
            setTimeout(() => {
                try {
                    messageInput.focus();
                    messageInput.setSelectionRange(0, messageInput.value.length);
                } catch (e) {}
            }, 20);
            
            return;
        }
        
        // Handle "Delete" button click for scheduled messages
        const deleteBtn = e.target.closest('[data-act="delete"]');
        if (deleteBtn) {
            console.log('[SCHEDULED DELETE] Delete button clicked', e.target);
            
            const messageEl = deleteBtn.closest('.message');
            console.log('[SCHEDULED DELETE] Message element:', messageEl);
            
            if (!messageEl) {
                console.log('[SCHEDULED DELETE] No message element found');
                return;
            }
            
            // Check if this is a scheduled message
            const scheduledId = messageEl.dataset.scheduledId;
            console.log('[SCHEDULED DELETE] Scheduled ID:', scheduledId);
            
            if (scheduledId) {
                console.log('[SCHEDULED DELETE] This is a scheduled message');
                
                // Close the menu first
                const menu = deleteBtn.closest('.message-actions-menu');
                const actionsWrap = deleteBtn.closest('.message-actions-wrap');
                if (menu) menu.classList.remove('is-open');
                if (actionsWrap) actionsWrap.classList.remove('is-open');
                
                // Open the delete modal for scheduled message
                // Use the fake message ID we set earlier
                const fakeMessageId = parseInt(scheduledId);
                console.log('[SCHEDULED DELETE] Fake message ID:', fakeMessageId);
                
                // Trigger the delete modal by dispatching a custom event
                // This will be caught by the existing delete message handler
                const deleteEvent = new CustomEvent('openScheduledDeleteModal', {
                    detail: {
                        scheduledId: fakeMessageId,
                        messageElement: messageEl
                    }
                });
                window.dispatchEvent(deleteEvent);
                
                return;
            } else {
                console.log('[SCHEDULED DELETE] Not a scheduled message, letting regular handler take over');
            }
        }
        
        // Handle "Send now"
        if (e.target.closest('[data-act="send-now"]')) {
            const messageEl = e.target.closest('.message');
            if (!messageEl) return;
            
            const scheduledId = parseInt(messageEl.dataset.scheduledId);
            if (!scheduledId) return;

            const sessionToken = getSessionTokenValue();
            if (!sessionToken) {
                showToast('Missing session token. Please refresh and sign in again.', 'error');
                return;
            }
            
            try {
                const res = await fetch(`send_scheduled_now.php?token=${encodeURIComponent(sessionToken)}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        token: sessionToken,
                        scheduled_id: scheduledId
                    })
                });
                
                const data = await res.json();
                
                if (data.success) {
                    // Remove scheduled styling
                    messageEl.classList.remove('scheduled');
                    const indicator = messageEl.querySelector('.message-scheduled-indicator');
                    if (indicator) indicator.remove();
                    scheduledMessagesMap.delete(scheduledId);
                    if (typeof window.invalidateSidebarHistoryCache === 'function') {
                        window.invalidateSidebarHistoryCache({ reloadIfVisible: true });
                    }
                    showToast('Message sent', 'success');
                    
                    // Refresh messages
                    if (typeof window.pollMessages === 'function') {
                        window.pollMessages();
                    }
                } else {
                    showToast(data.error || 'Failed to send message', 'error');
                }
            } catch (error) {
                console.error('Failed to send scheduled message now:', error);
                showToast('Failed to send message', 'error');
            }
        }
    });
    
    // Process scheduled messages every minute (client-side trigger)
    async function processScheduledMessages() {
        try {
            await fetch('process_scheduled_messages.php');
            // Refresh messages after processing
            if (typeof window.pollMessages === 'function') {
                window.pollMessages();
            }
        } catch (error) {
            console.error('Failed to process scheduled messages:', error);
        }
    }
    
    // Process every minute
    setInterval(processScheduledMessages, 60000);
    // Also process on page load
    setTimeout(processScheduledMessages, 2000);
})();

</script>

